        public GreedLastLobbySnapshot SelectSaveLoadoutSlot(int slotIndex)
        {
            selectedSaveSlotIndex = Mathf.Clamp(slotIndex, 0, SaveSlotCount - 1);
            SavePersistedData();
            return BuildLobbySnapshot(ensureSelectedSlot: false);
        }

        public GreedLastLobbySnapshot ConfirmSaveLoadout()
        {
            lastSaveLoadoutConfirmSlotIndex = -1;
            if (saveLoadoutUnlocked && HasSaveLoadoutCandidate)
            {
                saveLoadoutSlots[selectedSaveSlotIndex] = BuildSaveLoadoutRecord(lastRunRecord);
                saveLoadoutUsesRemaining[selectedSaveSlotIndex] = MaxSaveLoadoutUses;
                saveLoadoutRenameSteps[selectedSaveSlotIndex] = 0;
                savedLoadoutConfirmed = true;
                lastSaveLoadoutConfirmSlotIndex = selectedSaveSlotIndex;
                ResolveSaveLoadoutCandidate();
                profileNoticePending = true;
                SavePersistedData();
            }

            return LoadLobby();
        }

        public void DiscardSaveLoadoutCandidate()
        {
            if (!saveLoadoutCandidateAvailable)
            {
                return;
            }

            ResolveSaveLoadoutCandidate();
            lastSaveLoadoutConfirmSlotIndex = -1;
            profileNoticePending = true;
            SavePersistedData();
        }

        public bool SelectedSaveSlotHasRecord()
        {
            selectedSaveSlotIndex = Mathf.Clamp(selectedSaveSlotIndex, 0, SaveSlotCount - 1);
            return saveLoadoutSlots[selectedSaveSlotIndex].IsValid;
        }

        public string BuildSaveConfirmMessage()
        {
            int confirmedSlotIndex = lastSaveLoadoutConfirmSlotIndex;
            if (confirmedSlotIndex < 0
                || confirmedSlotIndex >= SaveSlotCount
                || !saveLoadoutSlots[confirmedSlotIndex].IsValid)
            {
                if (saveLoadoutCandidateAvailable)
                {
                    return "저장 확인 전\n좌 / 중 / 우 슬롯 선택 후 저장하세요.";
                }

                return "저장 후보 없음\n새 저장은 다음 클리어 후 1회만 가능합니다.";
            }

            return "슬롯 " + (confirmedSlotIndex + 1) + " 저장 조합 저장 완료\n"
                + saveLoadoutSlots[confirmedSlotIndex].LoadoutName
                + "\n사용 가능 횟수 2회 / 모두 쓰면 자동 비움"
                + "\n요약: " + FormatSaveSlotCompact(saveLoadoutSlots[confirmedSlotIndex], saveLoadoutUsesRemaining[confirmedSlotIndex])
                + "\n" + BuildSaveLoadoutQualitySummary(saveLoadoutSlots[confirmedSlotIndex])
                + "\n저장 후보 소모 완료 / 같은 클리어 재저장 불가"
                + "\n다음: 저장 조합으로 무한모드 시작";
        }

        public string BuildSelectedSaveLoadoutComparisonText()
        {
            GreedLastRunRecord slotRecord = saveLoadoutSlots[selectedSaveSlotIndex];
            bool hasCandidate = HasSaveLoadoutCandidate;
            string slotHeader = "슬롯 " + (selectedSaveSlotIndex + 1)
                + (hasCandidate ? " 상세 비교" : " 상세 보기");
            if (!hasCandidate)
            {
                if (!slotRecord.IsValid)
                {
                    if (HasAnyUsableSaveLoadoutSlot())
                    {
                        return slotHeader
                            + "\n비어 있음"
                            + "\n\n선택 불가: 사용 가능한 슬롯을 고르세요."
                            + "\n다른 슬롯에서 저장 조합을 확인하세요."
                            + "\n목록: 좌 / 중 / 우로 확인할 슬롯 선택";
                    }

                    if (firstSaveCompleted || saveLoadoutUnlocked)
                    {
                        return slotHeader
                            + "\n비어 있음"
                            + "\n\n보충 런으로 새 저장 조합을 만들어야 합니다."
                            + "\n다음: 보충 런 클리어 후 새 조합 저장";
                    }

                    return slotHeader
                        + "\n비어 있음"
                        + "\n\n일반 런을 클리어하면 새 저장 후보를 만들 수 있습니다.";
                }

                return slotHeader
                    + "\n" + BuildSaveSlotStatusLine(slotRecord, saveLoadoutUsesRemaining[selectedSaveSlotIndex])
                    + "\n요약: " + FormatSaveSlotCompact(slotRecord, saveLoadoutUsesRemaining[selectedSaveSlotIndex])
                    + "\n보너스: " + GreedLastRunCore.BuildInfiniteLoadoutBonusGrade(slotRecord)
                    + " / " + BuildInfiniteLoadoutStartStatePreview(slotRecord).Replace("\n", " / ")
                    + "\n구성: " + FormatLoadoutCombo(slotRecord)
                    + "\n타이밍: " + FormatTimingProfile(slotRecord.TimingProfile)
                    + "\n선택: " + CompactText(slotRecord.ChoiceSummary, 42);
            }

            GreedLastRunRecord candidate = BuildSaveLoadoutRecord(lastRunRecord);
            string text = slotHeader
                + "\n후보: " + FormatSaveCandidateSummary(candidate).Replace("\n", " / ")
                + "\n후보 보너스: " + GreedLastRunCore.BuildInfiniteLoadoutBonusGrade(candidate)
                + " / " + BuildInfiniteLoadoutStartStatePreview(candidate)
                + "\n후보 타이밍: " + FormatTimingProfile(candidate.TimingProfile);

            if (!slotRecord.IsValid)
            {
                return text
                    + "\n현재: 비어 있음"
                    + "\n저장하면 새 조합으로 2회 사용할 수 있습니다.";
            }

            text += "\n현재: " + FormatSaveSlotCompact(slotRecord, saveLoadoutUsesRemaining[selectedSaveSlotIndex])
                + "\n현재 품질: " + BuildSaveLoadoutQualitySummary(slotRecord)
                + "\n현재 보너스: " + GreedLastRunCore.BuildInfiniteLoadoutBonusGrade(slotRecord)
                + " / " + BuildInfiniteLoadoutStartStatePreview(slotRecord).Replace("\n", " / ")
                + "\n현재 구성: " + FormatLoadoutCombo(slotRecord)
                + "\n현재 타이밍: " + FormatTimingProfile(slotRecord.TimingProfile)
                + "\n차이: " + FormatSaveLoadoutQualityDelta(candidate, slotRecord)
                + " / 점수 " + FormatSigned(candidate.Score - slotRecord.Score)
                + $" / 거리 {FormatSigned(candidate.Distance - slotRecord.Distance)}m"
                + $" / 체력 {FormatSigned(candidate.Health - slotRecord.Health)}"
                + $" / 집중 {FormatSigned(candidate.Focus - slotRecord.Focus)}"
                + $" / 콤보 {FormatSigned(candidate.MaxCombo - slotRecord.MaxCombo)}"
                + $" / 실수 {FormatSigned(candidate.MissCount - slotRecord.MissCount)}";
            return text;
        }

        public string BuildSelectedSaveLoadoutOverwritePreviewText()
        {
            selectedSaveSlotIndex = Mathf.Clamp(selectedSaveSlotIndex, 0, SaveSlotCount - 1);
            GreedLastRunRecord slotRecord = saveLoadoutSlots[selectedSaveSlotIndex];
            int usesRemaining = saveLoadoutUsesRemaining[selectedSaveSlotIndex];
            if (!HasSaveLoadoutCandidate)
            {
                return "덮어쓰기 후보 없음\n새 클리어 기록이 있어야 슬롯을 갱신할 수 있습니다.";
            }

            GreedLastRunRecord candidate = BuildSaveLoadoutRecord(lastRunRecord);
            string text = "덮어쓰기 확인"
                + "\n대상: 슬롯 " + (selectedSaveSlotIndex + 1)
                + "\n현재: " + FormatSaveSlotCompact(slotRecord, usesRemaining)
                + "\n후보: " + FormatSaveCandidateSummary(candidate).Replace("\n", " / ")
                + "\n후보 보너스: " + GreedLastRunCore.BuildInfiniteLoadoutBonusGrade(candidate)
                + " / " + BuildInfiniteLoadoutStartStatePreview(candidate).Replace("\n", " / ");

            if (slotRecord.IsValid)
            {
                text += "\n현재 품질: " + BuildSaveLoadoutQualitySummary(slotRecord)
                    + "\n차이: " + FormatSaveLoadoutQualityDelta(candidate, slotRecord)
                    + " / 점수 " + FormatSigned(candidate.Score - slotRecord.Score)
                    + " / 거리 " + FormatSigned(candidate.Distance - slotRecord.Distance) + "m"
                    + " / 체력 " + FormatSigned(candidate.Health - slotRecord.Health)
                    + " / 집중 " + FormatSigned(candidate.Focus - slotRecord.Focus)
                    + " / 콤보 " + FormatSigned(candidate.MaxCombo - slotRecord.MaxCombo)
                    + " / 실수 " + FormatSigned(candidate.MissCount - slotRecord.MissCount);
            }

            return text
                + "\n다시 저장을 누르면 기존 슬롯이 후보로 교체되고 후보는 소모됩니다."
                + "\n다른 슬롯을 고르면 덮어쓰기 확인이 취소됩니다."
                + "\n\n슬롯\n"
                + BuildSaveSlotListText(showSelectedSlot: true, compact: true);
        }

        public string RenameSelectedSaveLoadoutSlot()
        {
            selectedSaveSlotIndex = Mathf.Clamp(selectedSaveSlotIndex, 0, SaveSlotCount - 1);
            GreedLastRunRecord record = saveLoadoutSlots[selectedSaveSlotIndex];
            if (!record.IsValid)
            {
                return "선택한 슬롯이 비어 있어 이름을 바꿀 수 없습니다.";
            }

            saveLoadoutRenameSteps[selectedSaveSlotIndex] =
                (saveLoadoutRenameSteps[selectedSaveSlotIndex] + 1) % SaveLoadoutNamePresets.Length;
            string newName = BuildSaveLoadoutNameForStep(selectedSaveSlotIndex, saveLoadoutRenameSteps[selectedSaveSlotIndex]);
            saveLoadoutSlots[selectedSaveSlotIndex] = WithLoadoutName(record, newName);
            profileNoticePending = true;
            SavePersistedData();
            return "슬롯 " + (selectedSaveSlotIndex + 1) + " 이름 변경: " + newName;
        }

        public string BuildSelectedSaveLoadoutRenamePreviewText()
        {
            selectedSaveSlotIndex = Mathf.Clamp(selectedSaveSlotIndex, 0, SaveSlotCount - 1);
            GreedLastRunRecord record = saveLoadoutSlots[selectedSaveSlotIndex];
            int usesRemaining = saveLoadoutUsesRemaining[selectedSaveSlotIndex];
            if (!record.IsValid)
            {
                return "선택한 슬롯이 비어 있어 이름을 바꿀 수 없습니다.";
