        private string BuildPrototypePlaytestChecklistText()
        {
            string runStatus = bestRunRecord.IsValid
                ? "일반 " + BuildRunGrade(bestRunRecord) + " 완료"
                : normalFailCount > 0 || normalAbandonCount > 0 ? "일반 재도전 필요" : "일반 대기";
            string saveStatus = HasSaveLoadoutCandidate
                ? "저장 후보 우선"
                : HasAnyUsableSaveLoadoutSlot()
                    ? "저장 조합 가능"
                    : firstSaveCompleted ? "조합 보충 필요" : "저장 조합 대기";
            string infiniteStatus = bestInfiniteRunRecord.IsValid
                ? "무한 " + bestInfiniteRunRecord.SectionsCleared + "구간 기록"
                : HasSaveLoadoutCandidate
                    ? "후보 처리 후 무한"
                    : infiniteRunCount > 0 ? "무한 기록 갱신 대기" : "무한 대기";
            string growthStatus = growthSurvivalLevel + growthFocusLevel + growthTimingLevel > 0
                ? "성장 Lv." + (growthSurvivalLevel + growthFocusLevel + growthTimingLevel)
                : growthPoints > 0 ? "성장 포인트 보유" : "성장 대기";
            string recordStatus = bestRunRecord.IsValid || bestInfiniteRunRecord.IsValid || lastRunAttemptRecord.IsValid
                ? "기록 보드 확인 가능 / 점수 행 기준 / 보조 단독 제외"
                : "기록 대기 / 점수 기록 필요 / 보조 단독 제외";
            string cueStatus = BuildPrototypeCueChecklistText();
            string consumptionStatus = BuildSaveLoadoutConsumptionChecklistText();
            string reviewStatus = BuildPrototypeReviewChecklistText();
            string sensoryStatus = BuildPrototypeSensoryChecklistText();
            string threatStatus = BuildPrototypeThreatChecklistText();
            string nextCheck = BuildPrototypeNextCheckText();

            return BuildPrototypeScopeContractLine()
                + "\n" + BuildPrototypeRuntimeModeChecklistText(
                    GreedLastDevToolPolicy.ShouldEnable(Application.isEditor, Debug.isDebugBuild))
                + "\n진행: " + BuildPrototypeProgressChecklistStatusText()
                + " / " + BuildPrototypeCompletionLoopStatusText()
                + " / 루프 상태: " + BuildPrototypeLoopCheckpointStateText()
                + "\n진행칸: " + BuildPrototypeProgressPipSummaryText()
                + "\n" + BuildPrototypeImmediateCheckLineText(nextCheck)
                + "\n" + runStatus + " / " + saveStatus + " / " + infiniteStatus + " / " + threatStatus
                + "\n" + growthStatus + " / " + cueStatus
                + "\n" + recordStatus + " / " + consumptionStatus
                + "\n" + reviewStatus + " / " + sensoryStatus;
        }

        private static string BuildPrototypeRuntimeModeChecklistText(bool devToolsEnabled)
        {
            return devToolsEnabled
                ? "검증 모드: 에디터 테스트키 ON"
                : "검증 모드: 모바일/릴리스 테스트키 숨김";
        }

        private string BuildPrototypeProgressChecklistStatusText()
        {
            const int totalChecks = 7;
            return "체크 " + CountPrototypeProgressChecks() + "/" + totalChecks;
        }

        private int CountPrototypeProgressChecks()
        {
            int completedChecks = 0;
            bool hasRunTrace = normalClearCount > 0
                || normalFailCount > 0
                || normalAbandonCount > 0
                || lastRunAttemptRecord.IsValid;

            if (hasRunTrace)
            {
                completedChecks += 1;
            }

            if (bestRunRecord.IsValid)
            {
                completedChecks += 1;
            }

            if (firstSaveCompleted || saveLoadoutUnlocked || HasSaveLoadoutCandidate || HasAnySaveLoadoutSlot())
            {
                completedChecks += 1;
            }

            if (HasLastSaveLoadoutUseTrace())
            {
                completedChecks += 1;
            }

            if (lastConsumedSaveSlotAutoCleared)
            {
                completedChecks += 1;
            }

            if (infiniteRunCount > 0 || bestInfiniteRunRecord.IsValid || lastInfiniteRunRecord.IsValid)
            {
                completedChecks += 1;
            }

            if (bestRunRecord.IsValid || bestInfiniteRunRecord.IsValid || lastRunAttemptRecord.IsValid)
            {
                completedChecks += 1;
            }

            return completedChecks;
        }

        private string BuildPrototypeCompletionLoopStatusText()
        {
            const int totalLoopSteps = 4;
            return "루프 " + CountPrototypeCompletionLoopSteps() + "/" + totalLoopSteps;
        }

        private int CountPrototypeCompletionLoopSteps()
        {
            int completedSteps = 0;
            if (bestRunRecord.IsValid)
            {
                completedSteps += 1;
            }

            if (savedLoadoutConfirmed
                || HasAnySaveLoadoutSlot()
                || HasLastSaveLoadoutUseTrace()
                || lastConsumedSaveSlotAutoCleared)
            {
                completedSteps += 1;
            }

            if (infiniteRunCount > 0 || bestInfiniteRunRecord.IsValid || lastInfiniteRunRecord.IsValid)
            {
                completedSteps += 1;
            }

            if (bestRunRecord.IsValid || bestInfiniteRunRecord.IsValid || lastRunAttemptRecord.IsValid)
            {
                completedSteps += 1;
            }

            return completedSteps;
        }

        private string BuildPrototypeProgressPipSummaryText()
        {
            return "체크 " + BuildPrototypeProgressPipText(CountPrototypeProgressChecks(), 7)
                + " / 루프 " + BuildPrototypeProgressPipText(CountPrototypeCompletionLoopSteps(), 4)
                + " / 남은: " + BuildPrototypeRemainingLoopStepText();
        }

        private string BuildPrototypeLoopCheckpointStateText()
        {
            return BuildPrototypeLoopCheckpointStateTextForValues(
                CountPrototypeCompletionLoopSteps(),
                HasPrototypeCompletionLoopCompleted(),
                lastConsumedSaveSlotAutoCleared,
                HasAnyUsableSaveLoadoutSlot(),
                BuildPrototypeNextCheckText());
        }

        private static string BuildPrototypeLoopCheckpointStateTextForValues(
            int completedLoopSteps,
            bool loopCompleted,
            bool lastAutoCleared,
            bool hasAnyUsableSaveLoadout,
            string nextCheck)
        {
            int safeSteps = Mathf.Clamp(completedLoopSteps, 0, 4);
            string normalizedNextCheck = string.IsNullOrWhiteSpace(nextCheck) ? string.Empty : nextCheck.Trim();
            if (loopCompleted
                && (normalizedNextCheck.Contains("완성 루프 기록", StringComparison.Ordinal)
                    || normalizedNextCheck.StartsWith("완성 기록", StringComparison.Ordinal)))
            {
                return "완성 기록 확인";
            }

            if (lastAutoCleared && !hasAnyUsableSaveLoadout)
            {
                return safeSteps >= 4 ? "루프 완료 / 보충 필요" : "보충 후 무한";
            }

            if (normalizedNextCheck.Contains("2회 소진", StringComparison.Ordinal))
            {
                return "마지막 소진 확인";
            }

            if (normalizedNextCheck.Contains("후보", StringComparison.Ordinal))
            {
                return "저장 후보 처리";
            }

            if (normalizedNextCheck.Contains("무한", StringComparison.Ordinal))
            {
                return safeSteps >= 3 ? "무한 기록 확인" : "저장 후 무한";
            }

            if (normalizedNextCheck.Contains("기록", StringComparison.Ordinal))
            {
                return "기록 확인";
            }

            if (safeSteps <= 0)
            {
                return "일반 런부터";
            }

            return safeSteps <= 1 ? "일반 탈출 확인" : "다음 루프 확인";
        }

        private static string BuildPrototypeProgressPipText(int completed, int total)
        {
            int safeTotal = Mathf.Clamp(total, 1, 10);
            int safeCompleted = Mathf.Clamp(completed, 0, safeTotal);
            string text = "[";
            for (int i = 0; i < safeTotal; i += 1)
            {
                text += i < safeCompleted ? "#" : "-";
            }

            return text + "]";
        }

        private string BuildPrototypeRemainingLoopStepText()
        {
            if (!bestRunRecord.IsValid)
            {
                return lastRunAttemptRecord.IsValid ? "복기 후 탈출" : "일반 탈출";
            }

            if (HasSaveLoadoutCandidate)
            {
                return "후보 처리";
            }

            if (!firstSaveCompleted && !saveLoadoutUnlocked && !HasAnySaveLoadoutSlot())
            {
                return "조합 저장";
            }

            if (!HasLastSaveLoadoutUseTrace())
            {
                return HasAnyUsableSaveLoadoutSlot() ? "첫 무한" : "조합 보충";
            }

            if (!lastConsumedSaveSlotAutoCleared)
            {
                return "2회 소진";
            }

            if (lastConsumedSaveSlotAutoCleared && !HasAnyUsableSaveLoadoutSlot())
            {
                return "보충 재진입";
            }

            if (infiniteRunCount <= 0 && !bestInfiniteRunRecord.IsValid && !lastInfiniteRunRecord.IsValid)
            {
                return "무한 기록";
            }

            if (HasPrototypeCompletionLoopCompleted())
            {
                return "완성 기록";
            }

            string avoidancePractice = BuildAvoidancePracticeNextActionFromProgress();
            if (!string.IsNullOrEmpty(avoidancePractice))
            {
                return BuildPrototypeRemainingReviewStepText(avoidancePractice);
            }

            string reviewTarget = BuildReviewTargetNextActionFromProgress();
            if (!string.IsNullOrEmpty(reviewTarget))
            {
                return BuildPrototypeRemainingReviewStepText(reviewTarget);
            }

            return IsPrototypeCompletionRecordCheckActive() ? "완성 기록" : "기록 확인";
        }

        private static string BuildPrototypeRemainingReviewStepText(string action)
        {
            if (string.IsNullOrEmpty(action))
            {
                return "복기";
            }

            if (action.Contains("무한", StringComparison.Ordinal))
            {
                return "무한 복기";
            }

            if (action.Contains("정확권", StringComparison.Ordinal)
                || action.Contains("보정 0회", StringComparison.Ordinal))
            {
                return "정확권 복기";
            }

            return "복기";
        }

        private bool HasPrototypeCompletionLoopCompleted()
        {
            return bestRunRecord.IsValid
                && (savedLoadoutConfirmed
                    || HasAnySaveLoadoutSlot()
                    || HasLastSaveLoadoutUseTrace()
                    || lastConsumedSaveSlotAutoCleared)
                && (infiniteRunCount > 0 || bestInfiniteRunRecord.IsValid || lastInfiniteRunRecord.IsValid);
        }

        private bool IsPrototypeCompletionRecordCheckActive()
        {
            return HasPrototypeCompletionLoopCompleted()
                && string.Equals(BuildPrototypeNextCheckText(), "완성 루프 기록 확인", StringComparison.Ordinal);
        }

        private string BuildPrototypeNextCheckText()
        {
            bool hasRunTrace = normalClearCount > 0
                || normalFailCount > 0
                || normalAbandonCount > 0
                || lastRunAttemptRecord.IsValid;

            if (!hasRunTrace)
            {
                return "시작→런 확인";
            }

            if (!bestRunRecord.IsValid)
            {
                return lastRunAttemptRecord.IsValid ? "복기 연습 후 탈출" : "일반 런 탈출";
            }

            if (HasSaveLoadoutCandidate)
            {
                return "저장 후보 저장/포기";
            }

            if (!firstSaveCompleted && !saveLoadoutUnlocked && !HasAnySaveLoadoutSlot())
            {
                return "클리어 후 저장 후보";
            }

            if (!HasLastSaveLoadoutUseTrace())
            {
                return HasAnyUsableSaveLoadoutSlot() ? "저장 조합으로 무한 시작" : "무한 조합 보충";
            }

            if (!lastConsumedSaveSlotAutoCleared)
            {
                return "저장 조합 2회 소진";
            }

            if (lastConsumedSaveSlotAutoCleared && !HasAnyUsableSaveLoadoutSlot())
            {
                return "보충 후 무한 재진입";
            }

            if (infiniteRunCount <= 0 && !bestInfiniteRunRecord.IsValid && !lastInfiniteRunRecord.IsValid)
            {
                return "무한 기록 생성";
            }

            if (!bestRunRecord.IsValid && !bestInfiniteRunRecord.IsValid && !lastRunAttemptRecord.IsValid)
            {
                return "기록 보드 확인";
            }

            if (HasPrototypeCompletionLoopCompleted())
            {
                return "완성 루프 기록 확인";
            }

            string avoidancePractice = BuildAvoidancePracticeNextActionFromProgress();
            if (!string.IsNullOrEmpty(avoidancePractice))
            {
                return CompactText(avoidancePractice, 34);
            }

            string nextAction = BuildReviewTargetNextActionFromProgress();
            if (!string.IsNullOrEmpty(nextAction))
            {
                return CompactText(nextAction, 34);
            }

            return HasAnyUsableSaveLoadoutSlot() ? "무한 기록 갱신" : "보충 후 무한 재진입";
        }

