        private static string BuildPrototypeNextCheckDisplayText(string nextCheck)
        {
            if (string.IsNullOrWhiteSpace(nextCheck))
            {
                return "강조 버튼 경로";
            }

            string normalizedNextCheck = nextCheck.Trim();
            if (normalizedNextCheck.Equals("일반 런 첫 함정", StringComparison.Ordinal))
            {
                return "첫 함정";
            }

            if (normalizedNextCheck.Equals("복기 연습 후 탈출", StringComparison.Ordinal))
            {
                return "복기 후 탈출";
            }

            if (normalizedNextCheck.Equals("일반 런 탈출", StringComparison.Ordinal))
            {
                return "일반 탈출";
            }

            if (normalizedNextCheck.Equals("클리어 후 저장 후보", StringComparison.Ordinal))
            {
                return "저장 후보 생성";
            }

            if (normalizedNextCheck.Equals("저장 후보 저장/포기", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("후보 저장/포기", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("후보 처리", StringComparison.Ordinal))
            {
                return "후보 처리";
            }

            if (normalizedNextCheck.Equals("저장 조합으로 무한 시작", StringComparison.Ordinal))
            {
                return "첫 무한";
            }

            if (normalizedNextCheck.Equals("저장 조합 2회 소진", StringComparison.Ordinal))
            {
                return "2회 소진";
            }

            if (normalizedNextCheck.Equals("보충 후 무한 재진입", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("보충 런 클리어 후 새 조합 저장", StringComparison.Ordinal))
            {
                return "보충 재진입";
            }

            if (normalizedNextCheck.Equals("무한 기록 생성", StringComparison.Ordinal))
            {
                return "무한 기록";
            }

            if (normalizedNextCheck.Equals("완성 루프 기록 확인", StringComparison.Ordinal))
            {
                return "완성 기록";
            }

            if (normalizedNextCheck.StartsWith("성장 보정", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("성장 포인트", StringComparison.Ordinal))
            {
                return "성장 보정";
            }

            if (normalizedNextCheck.StartsWith("흔적", StringComparison.Ordinal))
            {
                return "흔적 확인";
            }

            return CompactText(normalizedNextCheck, 22);
        }

        private static string BuildPrototypeNextCheckActionTextForMode(
            string nextCheck,
            bool hasAnyUsableSaveLoadoutSlot,
            bool devToolsEnabled)
        {
            if (string.IsNullOrWhiteSpace(nextCheck))
            {
                return "강조 버튼";
            }

            string normalizedNextCheck = nextCheck.Trim();
            string compactDisplayAction = BuildPrototypeCompactDisplayLabelActionTextForMode(
                normalizedNextCheck,
                hasAnyUsableSaveLoadoutSlot,
                devToolsEnabled);
            if (!string.IsNullOrEmpty(compactDisplayAction))
            {
                return compactDisplayAction;
            }

            if (normalizedNextCheck.Equals("일반", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("일반 런", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("클리어 후", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("일반 런", StringComparison.Ordinal))
            {
                return "일반 런";
            }

            if (normalizedNextCheck.Equals("성장", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("성장 보정", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("성장 보정", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("성장 포인트", StringComparison.Ordinal))
            {
                return "성장 보정";
            }

            if (normalizedNextCheck.Equals("흔적", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("흔적", StringComparison.Ordinal)
                || normalizedNextCheck.Contains("성장/저장 변화", StringComparison.Ordinal))
            {
                return "흔적";
            }

            if (normalizedNextCheck.Equals("저장", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("저장/포기", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("저장 또는 포기", StringComparison.Ordinal)
                || normalizedNextCheck.Contains("저장 후보", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("저장 조합에서", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("저장 조합 변경", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("저장 조합 후보", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("저장 조합 관리", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("저장 버튼", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("포기 버튼", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("후보 저장", StringComparison.Ordinal)
                || normalizedNextCheck.StartsWith("후보 처리", StringComparison.Ordinal)
                || normalizedNextCheck.Contains("후보 소모", StringComparison.Ordinal))
            {
                return "저장 조합";
            }

            if (normalizedNextCheck.Contains("2회 소진", StringComparison.Ordinal))
            {
                return BuildSaveUseCheckpointActionText(
                    hasAnyUsableSaveLoadoutSlot,
                    devToolsEnabled);
            }

            if (normalizedNextCheck.Equals("연습", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("복기 연습", StringComparison.Ordinal))
            {
                return "복기 연습";
            }

            if (normalizedNextCheck.Contains("보충", StringComparison.Ordinal)
                || normalizedNextCheck.Contains("무한 조합", StringComparison.Ordinal))
            {
                return "무한 조합 보충";
            }

            if (normalizedNextCheck.Contains("복기 재도전", StringComparison.Ordinal))
            {
                return normalizedNextCheck.Contains("무한", StringComparison.Ordinal) ? "무한모드" : "일반 런";
            }

            if (normalizedNextCheck.Contains("복기", StringComparison.Ordinal)
                || normalizedNextCheck.Contains("기초연습", StringComparison.Ordinal)
                || normalizedNextCheck.Contains("실수", StringComparison.Ordinal)
                || normalizedNextCheck.Contains("보정", StringComparison.Ordinal))
            {
                return "복기 연습";
            }

            if (normalizedNextCheck.Equals("무한", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("무한모드", StringComparison.Ordinal)
                || normalizedNextCheck.Contains("무한", StringComparison.Ordinal))
            {
                return "무한모드";
            }

            if (normalizedNextCheck.Equals("기록", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("기록 보기", StringComparison.Ordinal)
                || normalizedNextCheck.Contains("기록", StringComparison.Ordinal))
            {
                return "기록 보기";
            }

            return "일반 런";
        }

        private static string BuildPrototypeCompactDisplayLabelActionTextForMode(
            string normalizedNextCheck,
            bool hasAnyUsableSaveLoadoutSlot,
            bool devToolsEnabled)
        {
            string target = GreedLastApp.ResolvePrototypeCompactDisplayLabelLobbyTarget(normalizedNextCheck);
            if (string.IsNullOrEmpty(target))
            {
                return string.Empty;
            }

            switch (target)
            {
                case "일반":
                    return "일반 런";
                case "연습":
                    return "복기 연습";
                case "저장":
                    return "저장 조합";
                case "무한":
                    if (normalizedNextCheck.Contains("2회 소진", StringComparison.Ordinal))
                    {
                        return BuildSaveUseCheckpointActionText(
                            hasAnyUsableSaveLoadoutSlot,
                            devToolsEnabled);
                    }

                    return normalizedNextCheck.Contains("보충", StringComparison.Ordinal)
                        ? "무한 조합 보충"
                        : "무한모드";
                case "성장":
                    return "성장 보정";
                case "흔적":
                    return "흔적";
                case "기록":
                    return "기록 보기";
                default:
                    return string.Empty;
            }
        }

        private static string BuildPrototypeNextCheckPurposeText(string nextCheck)
        {
            if (string.IsNullOrWhiteSpace(nextCheck))
            {
                return "강조 버튼 경로 확인";
            }

            string normalizedNextCheck = nextCheck.Trim();
            if (nextCheck.Contains("첫 함정", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("시작→런 확인", StringComparison.Ordinal)
                || normalizedNextCheck.Equals("런 확인", StringComparison.Ordinal))
            {
                return "위험·동작·박자 첫 체감";
            }

            if (nextCheck.Contains("정확권", StringComparison.Ordinal)
                || nextCheck.Contains("정확 보상", StringComparison.Ordinal))
            {
                return "정확 보상 전환 확인";
            }

            if (nextCheck.Contains("복기", StringComparison.Ordinal)
                || nextCheck.Contains("실수", StringComparison.Ordinal)
                || nextCheck.Contains("기초연습", StringComparison.Ordinal))
            {
                return "약한 동작을 짧게 반복";
            }

            if (nextCheck.Contains("탈출", StringComparison.Ordinal))
            {
                return "공명핵 회수 뒤 입구 마무리";
            }

            if (nextCheck.Contains("클리어 후 저장", StringComparison.Ordinal)
                || nextCheck.Contains("저장 후보 생성", StringComparison.Ordinal))
            {
                return "새 클리어로 후보 생성";
            }

            if (nextCheck.Contains("저장 후보", StringComparison.Ordinal)
                || nextCheck.Contains("후보 저장", StringComparison.Ordinal)
                || nextCheck.Contains("후보 처리", StringComparison.Ordinal)
                || nextCheck.Contains("후보 소모", StringComparison.Ordinal)
                || nextCheck.Contains("저장/포기", StringComparison.Ordinal)
                || nextCheck.Contains("저장 또는 포기", StringComparison.Ordinal))
            {
                return "저장·포기 1회성 처리";
            }

            if (nextCheck.Contains("2회 소진", StringComparison.Ordinal))
            {
                return "마지막 사용 후 자동 비움";
            }

            if (nextCheck.Contains("보충", StringComparison.Ordinal)
                || nextCheck.Contains("무한 조합", StringComparison.Ordinal))
            {
                return "빈 조합을 보충 런으로 회복";
            }

            if (nextCheck.Contains("무한", StringComparison.Ordinal)
                || nextCheck.Contains("위협", StringComparison.Ordinal))
            {
                return "저장 효과와 위협 보상 확인";
            }

            if (nextCheck.Contains("성장", StringComparison.Ordinal))
            {
                return "성장 보정 적용 확인";
            }

            if (nextCheck.Contains("기록", StringComparison.Ordinal))
            {
                return "코칭 없는 순수 기록 확인";
            }

            if (nextCheck.Contains("흔적", StringComparison.Ordinal))
            {
                return "검증 순서와 다음 행동 확인";
            }

            return "다음 버튼 경로 확인";
        }

        private static string BuildSaveUseCheckpointActionText(bool hasAnyUsableSaveLoadoutSlot, bool devToolsEnabled)
        {
            if (!hasAnyUsableSaveLoadoutSlot)
            {
                return "무한 조합 보충";
            }

            return devToolsEnabled ? "PgUp 소모" : "저장 소모";
        }

        private string BuildPrototypePlaytestOrderText()
        {
            string normalStep = bestRunRecord.IsValid ? "완료" : "첫 탈출";
            string saveStep = HasSaveLoadoutCandidate
                ? "후보 저장/포기"
                : HasAnySaveLoadoutSlot()
                    ? "저장됨"
                    : firstSaveCompleted ? "보충 클리어 후 저장" : "클리어 후 저장";
            string infiniteStep = HasSaveLoadoutCandidate
                ? "후보 처리 후 시작"
                : firstSaveCompleted && !HasAnyUsableSaveLoadoutSlot()
                ? "조합 보충"
                : infiniteRunCount > 0
                    ? "기록 확인"
                    : HasAnyUsableSaveLoadoutSlot() ? "저장 조합 시작" : "조합 보충";
            string recordStep = bestRunRecord.IsValid || bestInfiniteRunRecord.IsValid || lastRunAttemptRecord.IsValid
                ? "기록 비교"
                : "기록 생성";

            return "1 일반 런: " + normalStep + " / 위험→동작·박자·보상·상태줄·코치·루트 버튼·탈출 게이트"
                + "\n2 저장 조합: " + saveStep + " / 입구로 나가기→클리어 요약→슬롯 선택 / 저장 없이 로비→클리어 요약→클리어 복기 / 2회 소진"
                + "\n3 무한모드: " + infiniteStep + " / 위협·정산·실전 재개"
                + "\n4 기록/흔적: " + recordStep + " / 기록만: 점수 행 / 거리·구간 보조 / 보조 단독 제외·일시 피드백 제외 / 2/4 버튼";
        }

        private string BuildPrototypeInteractionChecklistText()
        {
            bool devToolsEnabled = GreedLastDevToolPolicy.ShouldEnable(Application.isEditor, Debug.isDebugBuild);
            string infiniteCheck = BuildPrototypeInfiniteInteractionCheckText(
                devToolsEnabled,
                HasAnyUsableSaveLoadoutSlot(),
                firstSaveCompleted);
            string saveUseCheck = BuildPrototypeSaveUseInteractionChecklistText();
            return BuildPrototypeInteractionChecklistTextForMode(devToolsEnabled, infiniteCheck, saveUseCheck);
        }

        private string BuildPrototypeSaveUseInteractionChecklistText()
        {
            string readySaveUseCheck = BuildReadySaveLoadoutUseChecklistText();
            if (HasLastSaveLoadoutUseTrace())
            {
                return BuildSaveLoadoutConsumptionChecklistText()
                    + (lastConsumedSaveSlotAutoCleared ? string.Empty : " / 자동 비움 대기");
            }

            return string.IsNullOrEmpty(readySaveUseCheck)
                ? "저장 조합 2회 소진 후 자동 비움"
                : readySaveUseCheck + " / 2회 소진 후 자동 비움";
        }

        private static string BuildPrototypeInteractionChecklistTextForMode(
            bool devToolsEnabled,
            string infiniteCheck,
            string saveUseCheck)
        {
            string primaryActionCheck = devToolsEnabled ? "Enter: 강조 다음 행동" : "강조 버튼: 다음 행동";
            return BuildPrototypeScopeContractLine()
                + "\n동작 확인: 위험→동작 / 바닥↑점·상단↓숙·측면↔틀 / " + BuildPrototypePayoffGoalChecklistText()
                + BuildPrototypeInteractionShortcutChecklistText(devToolsEnabled)
                + "\n" + primaryActionCheck + " / 일시정지 재개목표·배경차단 / 선택·정산 큐 숨김 / 태그·흔적·잔상·끊김 숨김"
                + "\nGO 첫 함정 / 복기 약점 반복 / 보정 빠름·추천·늦음 / 감각 소리%·진동 / 터치 탭"
                + "\n" + PrototypeCompletionLoopContract
                + "\n무한: " + infiniteCheck
                + "\n저장: " + saveUseCheck;
        }

        private static string BuildPrototypeInteractionShortcutChecklistText(bool devToolsEnabled)
        {
            if (devToolsEnabled)
            {
                return "\n상태줄 보상·코치 목표·3동작 HUD / 최근 흐름 / 박자공간·주자 / F8 경로 ↑↓↔·↔↓↑·↓↔↑"
                    + "\n테스트키: 중앙/레인 큐 / F1 무적 / F2 기프트·F3 유물·F4 핵·F5 탈출"
                    + "\nF6 집중 / F7 목표·F8 경로·F9 동작 / F10 낙하 보기 / PgUp·PgDn·End";
            }

            return "\n상태줄 보상·코치 목표·3동작 HUD / 최근 흐름 / 박자공간·주자 / 터치 레인 좌·중·우"
                + "\n모바일 조작: 중앙/레인 큐 / 일시정지 / 소리%·진동 / 터치 탭"
                + "\n개발 테스트키 숨김 / 기록·흔적 체크로 검증";
        }

        private static string BuildPrototypeInfiniteInteractionCheckText(
            bool devToolsEnabled,
            bool hasAnyUsableSaveLoadoutSlot,
            bool firstSaveCompleted)
        {
            if (hasAnyUsableSaveLoadoutSlot)
            {
                return devToolsEnabled
                    ? "무한 위협 +/- / 폭·보상 읽기 / 정산 종료"
                    : "무한 위협 변화 / 폭·보상 읽기 / 종료 흐름";
            }

            return firstSaveCompleted
                ? "무한 조합 보충 / 무한 위협 전 준비 / 폭·보상"
                : "무한 위협 전 저장 조합 준비 / 폭·보상";
        }

        private static string BuildPrototypeSensoryChecklistText()
        {
            string calibration = GreedLastRunCore.BuildStoredInputTimingOffsetChecklistText()
                .Replace("보정: ", "보정:");
            string sensory = GreedLastRuntimeUi.BuildSensorySettingsChecklistTextFromPrefs()
                .Replace("감각: ", string.Empty)
                .Replace("소리 ", "소리")
                .Replace("진동 ", "진동");
            return "감각 " + calibration + "·" + sensory;
        }

        private string BuildPrototypeThreatChecklistText()
        {
            if (HasAnyUsableSaveLoadoutSlot() || infiniteRunCount > 0 || bestInfiniteRunRecord.IsValid)
            {
                return "위협 폭·보상 확인";
            }

            return firstSaveCompleted ? "위협 폭·보상 대기" : "위협 전 저장";
        }

        private string BuildPrototypeReviewChecklistText()
        {
            string attemptWeakness = lastRunAttemptRecord.IsValid
                ? BuildAvoidanceWeaknessSummary(lastRunAttemptRecord.TimingProfile)
                : string.Empty;
            if (!string.IsNullOrEmpty(attemptWeakness))
            {
                return "복기 약점 " + BuildPrototypeWeaknessChecklistText(attemptWeakness, 38);
            }

            string infiniteWeakness = lastInfiniteRunRecord.IsValid
                ? BuildAvoidanceWeaknessSummary(lastInfiniteRunRecord.TimingProfile)
                : string.Empty;
            if (!string.IsNullOrEmpty(infiniteWeakness))
            {
                return "무한 약점 " + BuildPrototypeWeaknessChecklistText(infiniteWeakness, 34);
            }

            string nextAction = BuildReviewTargetNextActionFromProgress();
            if (!string.IsNullOrEmpty(nextAction))
            {
                return "복기 다음 " + CompactText(nextAction, 48);
            }

            if (lastRunAttemptRecord.IsValid || lastInfiniteRunRecord.IsValid)
            {
                return "복기 기록 확인 가능";
            }

            return "복기 대기";
        }

        private static string BuildPrototypeWeaknessChecklistText(string weakness, int maxLength)
        {
            string compact = weakness
                .Replace("기초연습 ", "연습 ")
                .Replace(" 단계", string.Empty)
                .Replace("실수 ", "실")
                .Replace("보정 ", "보")
                .Replace("회", string.Empty);
            return CompactText(compact, maxLength);
        }

        private string BuildPrototypeCueChecklistText()
        {
            bool hasRunTrace = normalClearCount > 0
                || normalFailCount > 0
                || normalAbandonCount > 0
                || infiniteRunCount > 0;
            return BuildPrototypeCueChecklistTextForMode(
                hasRunTrace,
                GreedLastDevToolPolicy.ShouldEnable(Application.isEditor, Debug.isDebugBuild));
        }

        private static string BuildPrototypeCueChecklistTextForMode(bool hasRunTrace, bool devToolsEnabled)
        {
            string cueContract = BuildPrototypeCueContractText(devToolsEnabled);
            return hasRunTrace
                ? "중앙/레인 큐+상태줄·코치+박자공간·주자 확인: " + cueContract + " / " + BuildPrototypePayoffGoalChecklistText()
                : "중앙/레인 큐+상태줄·코치+박자공간·주자 대기: 첫 함정 " + cueContract + " / " + BuildPrototypePayoffGoalChecklistText();
        }

