        {
            return devToolsEnabled ? "위험→동작·키·1박·보상" : "위험→동작·탭·1박·보상";
        }

        private static string BuildPrototypePayoffGoalChecklistText()
        {
            return "정확→집중·반격·연쇄 / 위기→생존·고점·회복";
        }

        private string BuildSaveLoadoutConsumptionChecklistText()
        {
            if (!HasLastSaveLoadoutUseTrace())
            {
                string readyUse = BuildReadySaveLoadoutUseChecklistText();
                return string.IsNullOrEmpty(readyUse) ? "소진 확인 대기" : readyUse;
            }

            return lastConsumedSaveSlotAutoCleared
                ? "최근 소진 자동 비움"
                : "최근 소모 " + BuildCompactSaveUseTraceText(lastConsumedSaveSlotRemainingAfterUse);
        }

        private string BuildReadySaveLoadoutUseChecklistText()
        {
            int slotIndex = FindBestUsableSaveLoadoutSlot();
            if (slotIndex < 0)
            {
                return string.Empty;
            }

            return "소진 대기 S" + (slotIndex + 1)
                + " " + BuildCompactSaveUseTraceText(saveLoadoutUsesRemaining[slotIndex]);
        }

        public string BuildProfileButtonSummary()
        {
            if (!HasAnyProfileTrace())
            {
                return "흔적";
            }

            if (HasSaveLoadoutCandidate)
            {
                return profileNoticePending ? "흔적 저장 NEW" : "흔적 저장";
            }

            if (firstSaveCompleted && !HasAnyUsableSaveLoadoutSlot())
            {
                return profileNoticePending ? "흔적 보충 NEW" : "흔적 보충";
            }

            if (IsPrototypeCompletionRecordCheckActive())
            {
                return profileNoticePending ? "흔적 완성 NEW" : "흔적 완성";
            }

            if (!string.IsNullOrEmpty(BuildReviewTargetNextActionFromProgress())
                || !string.IsNullOrEmpty(BuildAvoidancePracticeNextActionFromProgress()))
            {
                return profileNoticePending ? "흔적 복기 NEW" : "흔적 복기";
            }

            if (HasAnyGrowthUpgradeAvailable() || growthPoints > 0)
            {
                return profileNoticePending ? "흔적 성장 NEW" : "흔적 성장";
            }

            if (profileNoticePending)
            {
                return "흔적 NEW";
            }

            string tier = BuildProfileTierLabel();
            return string.IsNullOrEmpty(tier) ? "흔적" : "흔적 " + tier;
        }

        public GreedLastLobbySnapshot MarkProfileSeen()
        {
            if (profileNoticePending)
            {
                profileNoticePending = false;
                SavePersistedData();
            }

            return LoadLobby();
        }

        private string FormatProfileResultTraceLine()
        {
            return HasAnyProfileTrace()
                ? "\n흔적: " + BuildProfileBadgeName() + " / " + BuildProfileTierLabel()
                : string.Empty;
        }

        private static string FormatReviewTargetResultLine(string timingProfile)
        {
            string result = ExtractReviewTargetResultSummary(timingProfile);
            return string.IsNullOrEmpty(result)
                ? string.Empty
                : "\n복기 목표: " + CompactText(result, 78);
        }

        private static string ExtractReviewTargetResultSummary(string timingProfile)
        {
            if (string.IsNullOrWhiteSpace(timingProfile))
            {
                return string.Empty;
            }

            const string targetMarker = "복기 목표 ";
            const string resultMarker = " / 복기 결과 ";
            string normalized = timingProfile.Replace('\r', ' ').Replace('\n', ' ').Trim();
            int targetStart = normalized.IndexOf(targetMarker, StringComparison.Ordinal);
            if (targetStart < 0)
            {
                return string.Empty;
            }

            targetStart += targetMarker.Length;
            int resultStart = normalized.IndexOf(resultMarker, targetStart, StringComparison.Ordinal);
            if (resultStart < 0)
            {
                return string.Empty;
            }

            string target = normalized.Substring(targetStart, resultStart - targetStart).Trim();
            string result = normalized.Substring(resultStart + resultMarker.Length).Trim();
            int nextSeparator = result.IndexOf(" / ", StringComparison.Ordinal);
            if (nextSeparator >= 0)
            {
                result = result.Substring(0, nextSeparator).Trim();
            }

            return string.IsNullOrEmpty(target) || string.IsNullOrEmpty(result)
                ? string.Empty
                : target + " / " + result;
        }

        public string BuildRecordBoardText(int pageIndex)
        {
            int page = NormalizeRecordBoardPage(pageIndex);
            switch (page)
            {
                case 1:
                    return BuildNormalRecordBoardText();
                case 2:
                    return BuildInfiniteRecordListText();
                case 3:
                    return BuildInfiniteRankingText();
                default:
                    return BuildRecordBoardSummaryText();
            }
        }

        private string BuildRecordBoardSummaryText()
        {
            string text = string.Empty;
            if (bestRunRecord.IsValid)
            {
                AppendRecordBoardLine(ref text, "일반 최고", FormatRunRecordBoardCompactLine(bestRunRecord));
            }

            if (bestInfiniteRunRecord.IsValid)
            {
                AppendRecordBoardLine(ref text, "무한 최고", FormatInfiniteRecordBoardCompactLine(bestInfiniteRunRecord));
            }

            string recentRecord = BuildRecentRecordBoardSummaryLine(out string recentLabel);
            if (recentRecord != "기록 없음"
                && !IsDuplicateRecordBoardSummaryLine(recentRecord, bestRunRecord, bestInfiniteRunRecord))
            {
                AppendRecordBoardLine(ref text, recentLabel, recentRecord);
            }

            return string.IsNullOrEmpty(text) ? "기록 없음" : text;
        }

        private static bool IsDuplicateRecordBoardSummaryLine(
            string recentRecord,
            GreedLastRunRecord bestNormalRecord,
            GreedLastInfiniteRunRecord bestInfiniteRecord)
        {
            if (string.IsNullOrEmpty(recentRecord) || recentRecord == "기록 없음")
            {
                return true;
            }

            return (bestNormalRecord.IsValid && recentRecord == FormatRunRecordBoardLine(bestNormalRecord))
                || (bestNormalRecord.IsValid && recentRecord == FormatRunRecordBoardCompactLine(bestNormalRecord))
                || (bestInfiniteRecord.IsValid && recentRecord == FormatInfiniteRecordBoardLine(bestInfiniteRecord))
                || (bestInfiniteRecord.IsValid && recentRecord == FormatInfiniteRecordBoardCompactLine(bestInfiniteRecord));
        }

        private string BuildNormalRecordBoardText()
        {
            string attemptProbeText = BuildNormalAttemptHistoryText(1);
            bool hasAttemptRecords = attemptProbeText != "기록 없음";
            int clearLimit = hasAttemptRecords
                ? Mathf.Max(1, RecordBoardVisibleRows - 1)
                : RecordBoardVisibleRows;
            string clearText = BuildNormalRankingText(clearLimit);
            int clearRowCount = CountRecordBoardRows(clearText);
            int attemptLimit = clearText == "기록 없음"
                ? RecordBoardVisibleRows
                : Mathf.Max(1, RecordBoardVisibleRows - clearRowCount);
            string attemptText = hasAttemptRecords
                ? BuildNormalAttemptHistoryText(attemptLimit)
                : "기록 없음";
            if (clearText == "기록 없음" && attemptText == "기록 없음")
            {
                return "기록 없음";
            }

            string text = clearText == "기록 없음" ? string.Empty : clearText;
            if (attemptText != "기록 없음")
            {
                AppendPlainRecordBoardText(ref text, attemptText);
            }

            return text;
        }

        private string BuildInfiniteRecordListText()
        {
            if (!bestInfiniteRunRecord.IsValid && !lastInfiniteRunRecord.IsValid)
            {
                return "기록 없음";
            }

            string text = string.Empty;
            if (bestInfiniteRunRecord.IsValid)
            {
                AppendRecordBoardLine(ref text, "최고", FormatInfiniteRecordBoardCompactLine(bestInfiniteRunRecord));
            }

            if (lastInfiniteRunRecord.IsValid
                && !IsSameInfiniteRecordIdentity(lastInfiniteRunRecord, bestInfiniteRunRecord))
            {
                AppendRecordBoardLine(ref text, "최근", FormatInfiniteRecordBoardCompactLine(lastInfiniteRunRecord));
            }

            return text;
        }

        private string BuildRecentRecordBoardSummaryLine(out string label)
        {
            switch (lastProgressEvent)
            {
                case ProgressEventKind.NormalClear:
                    label = "최근 일반";
                    return lastRunRecord.IsValid ? FormatRunRecordBoardCompactLine(lastRunRecord) : "기록 없음";
                case ProgressEventKind.NormalFailed:
                case ProgressEventKind.NormalAbandoned:
                    label = "최근 시도";
                    return lastRunAttemptRecord.IsValid ? FormatRunAttemptBoardCompactLine(lastRunAttemptRecord) : "기록 없음";
                case ProgressEventKind.InfiniteRun:
                    label = "최근 무한";
                    return lastInfiniteRunRecord.IsValid ? FormatInfiniteRecordBoardCompactLine(lastInfiniteRunRecord) : "기록 없음";
                default:
                    if (lastInfiniteRunRecord.IsValid)
                    {
                        label = "최근 무한";
                    return FormatInfiniteRecordBoardCompactLine(lastInfiniteRunRecord);
                }
                label = "최근 일반";
                if (!lastRunRecord.IsValid)
                {
                    return "기록 없음";
                }
                return FormatRunRecordBoardCompactLine(lastRunRecord);
            }
        }

        private static void AppendRecordBoardLine(ref string text, string label, string recordText)
        {
            string compactRecord = CompactRecordBoardLine(recordText);
            if (!(compactRecord == "기록 없음"))
            {
                if (!string.IsNullOrEmpty(text))
                {
                    text += "\n";
                }
                text = text + label + "  " + CompactText(compactRecord, 58);
            }
        }

        private static void AppendPlainRecordBoardText(ref string text, string recordText)
        {
            if (string.IsNullOrWhiteSpace(recordText) || recordText == "기록 없음")
            {
                return;
            }
            string[] lines = recordText.Replace("\r\n", "\n").Replace('\r', '\n').Trim()
                .Split('\n');
            for (int i = 0; i < lines.Length; i++)
            {
                string compactRecord = CompactRecordBoardLine(lines[i]);
                if (!(compactRecord == "기록 없음"))
                {
                    if (!string.IsNullOrEmpty(text))
                    {
                        text += "\n";
                    }
                    text += compactRecord.Trim();
                }
            }
        }

        internal static string CompactRecordBoardLine(string recordText)
        {
            if (string.IsNullOrWhiteSpace(recordText))
            {
                return "기록 없음";
            }
            string[] lines = recordText.Replace("\r\n", "\n").Replace('\r', '\n').Trim()
                .Split('\n');
            for (int i = 0; i < lines.Length; i++)
            {
                string sanitized = SanitizeRecordBoardLine(lines[i]);
                if (!string.IsNullOrWhiteSpace(sanitized) && HasRecordBoardMetric(sanitized) && HasRecordBoardPrimaryMetric(sanitized))
                {
                    return sanitized.Trim();
                }
            }
            return "기록 없음";
        }

        private static string SanitizeRecordBoardLine(string line)
        {
            if (string.IsNullOrWhiteSpace(line))
            {
                return string.Empty;
            }
            string trimmedLine = StripRecordBoardListPrefix(line.Trim());
            if (IsRecordBoardManagementLine(trimmedLine))
            {
                return string.Empty;
            }
            trimmedLine = StripRecordBoardDisplayPrefix(trimmedLine);
            if (IsRecordBoardManagementLine(trimmedLine))
            {
                return string.Empty;
            }
            if (trimmedLine == "기록 없음" || trimmedLine.StartsWith("기록 없음 /", StringComparison.Ordinal))
            {
                return string.Empty;
            }
            string[] parts = SplitRecordBoardSanitizationParts(trimmedLine);
            string text = string.Empty;
            string pendingRank = string.Empty;
            for (int i = 0; i < parts.Length; i++)
            {
                string part = StripRecordBoardDisplayPrefix(StripRecordBoardListPrefix(parts[i].Trim()));
                part = NormalizeRecordBoardRankOnlyPart(part);
                part = StripRecordBoardInlineSaveLoadoutGuidance(part);
                if (string.IsNullOrEmpty(part) || IsRecordBoardCoachingPart(part))
                {
                    continue;
                }
                if (IsRecordBoardRankOnlyPart(part))
                {
                    pendingRank = part;
                    continue;
                }
                if (!string.IsNullOrEmpty(pendingRank) && StartsWithRecordBoardScoreMarker(part))
                {
                    part = pendingRank + " " + part;
                    pendingRank = string.Empty;
                }
                text = (string.IsNullOrEmpty(text) ? part : (text + " / " + part));
            }
            return StripRecordBoardSaveLoadoutGuidanceSegments(text);
        }

        private static string StripRecordBoardInlineSaveLoadoutGuidance(string part)
        {
            if (string.IsNullOrWhiteSpace(part))
            {
                return string.Empty;
            }
            string trimmed = part.Trim();
            string[] markers = new string[4] { "저장 조합이 비어", "저장 조합이 비었", "저장 조합 없음", "남은 저장 조합 없음" };
            int markerIndex = -1;
            for (int i = 0; i < markers.Length; i++)
            {
                int index = trimmed.IndexOf(markers[i], StringComparison.Ordinal);
                if (index >= 0 && (markerIndex < 0 || index < markerIndex))
                {
                    markerIndex = index;
                }
            }
            if (markerIndex < 0)
            {
                return part;
            }
            if (markerIndex == 0)
            {
                return string.Empty;
            }
            string scorePrefix = trimmed.Substring(0, markerIndex).TrimEnd(' ', '/', '-', ':', '·', 'ㆍ');
            if (!HasRecordBoardPrimaryMetric(scorePrefix))
            {
                return string.Empty;
            }
            return scorePrefix;
        }

        private static string StripRecordBoardSaveLoadoutGuidanceSegments(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return string.Empty;
            }
            string[] parts = text.Split(new string[1] { " / " }, StringSplitOptions.None);
            string compact = string.Empty;
            for (int i = 0; i < parts.Length; i++)
            {
                string part = parts[i].Trim();
                if (!string.IsNullOrEmpty(part) && !part.Contains("저장 조합이 비어", StringComparison.Ordinal) && !part.Contains("저장 조합이 비었", StringComparison.Ordinal) && !part.Contains("저장 조합 없음", StringComparison.Ordinal) && !part.Contains("남은 저장 조합 없음", StringComparison.Ordinal))
                {
                    compact = (string.IsNullOrEmpty(compact) ? part : (compact + " / " + part));
                }
            }
            return compact;
        }

        private static string NormalizeRecordBoardRankOnlyPart(string part)
        {
            if (string.IsNullOrWhiteSpace(part))
            {
                return string.Empty;
            }
            string trimmed = NormalizeRecordBoardLeadingRankPrefix(part.Trim());
            if (trimmed.StartsWith("랭킹 ", StringComparison.Ordinal) || trimmed.StartsWith("순위 ", StringComparison.Ordinal))
            {
                string suffix = trimmed.Substring(3).TrimStart();
                if (IsRecordBoardRankOnlyPart(suffix))
                {
                    return suffix;
                }
            }
            return trimmed;
        }

        private static bool IsRecordBoardRankOnlyPart(string part)
        {
            if (string.IsNullOrWhiteSpace(part))
            {
                return false;
            }
            string trimmed = part.Trim();
            int digitIndex;
            for (digitIndex = 0; digitIndex < trimmed.Length && char.IsDigit(trimmed[digitIndex]); digitIndex++)
            {
            }
            if (digitIndex <= 0)
            {
                return false;
            }
            return trimmed.Substring(digitIndex).Trim().Equals("위", StringComparison.Ordinal);
        }

        private static string StripRecordBoardListPrefix(string line)
        {
            if (string.IsNullOrWhiteSpace(line))
            {
                return string.Empty;
            }
            string trimmed = StripRecordBoardMarkdownWrapper(line.Trim());
            bool changed = true;
            while (changed)
            {
                changed = false;
                string unwrapped = StripRecordBoardMarkdownWrapper(trimmed);
                if (!string.Equals(unwrapped, trimmed, StringComparison.Ordinal))
                {
                    trimmed = unwrapped;
                    changed = true;
                    continue;
                }
                if (trimmed.Length >= 2 && (trimmed[0] == '-' || trimmed[0] == '*' || trimmed[0] == '•' || trimmed[0] == '·' || trimmed[0] == 'ㆍ' || trimmed[0] == '▸' || trimmed[0] == '▹' || trimmed[0] == '›' || trimmed[0] == '>') && char.IsWhiteSpace(trimmed[1]))
                {
                    trimmed = trimmed.Substring(2).TrimStart();
                    changed = true;
                    continue;
                }
                if (trimmed.Length >= 2 && trimmed[0] == '|')
                {
                    trimmed = trimmed.Substring(1).TrimStart();
                    changed = true;
                    continue;
                }
                if (trimmed.Length >= 2 && trimmed[trimmed.Length - 1] == '|')
                {
                    trimmed = trimmed.Substring(0, trimmed.Length - 1).TrimEnd();
                    changed = true;
                    continue;
                }
                int headingIndex;
                for (headingIndex = 0; headingIndex < trimmed.Length && trimmed[headingIndex] == '#'; headingIndex++)
                {
                }
                if (headingIndex > 0 && headingIndex < trimmed.Length && char.IsWhiteSpace(trimmed[headingIndex]))
                {
                    trimmed = trimmed.Substring(headingIndex + 1).TrimStart();
                    changed = true;
                    continue;
                }
                string rankNormalized = NormalizeRecordBoardLeadingRankPrefix(trimmed);
                if (!string.Equals(rankNormalized, trimmed, StringComparison.Ordinal))
                {
                    trimmed = rankNormalized;
                    changed = true;
                    continue;
                }
                int index;
                for (index = 0; index < trimmed.Length && char.IsDigit(trimmed[index]); index++)
                {
                }
                if (index > 0 && index + 1 < trimmed.Length && (trimmed[index] == '.' || trimmed[index] == ')') && char.IsWhiteSpace(trimmed[index + 1]))
                {
                    trimmed = trimmed.Substring(index + 2).TrimStart();
                    changed = true;
                    continue;
                }
                if (!changed)
                {
                    int wikiLabelEndIndex = trimmed.IndexOf("]]", StringComparison.Ordinal);
                    if (wikiLabelEndIndex > 2 && wikiLabelEndIndex + 2 < trimmed.Length && trimmed[0] == '[' && trimmed[1] == '[' && char.IsWhiteSpace(trimmed[wikiLabelEndIndex + 2]) && IsRecordBoardNonGradeBracketPrefix(trimmed.Substring(2, wikiLabelEndIndex - 2).Trim()))
                    {
                        trimmed = trimmed.Substring(wikiLabelEndIndex + 3).TrimStart();
                        changed = true;
                        continue;
                    }
                }
                if (trimmed.Length >= 4 && trimmed[0] == '[' && trimmed[2] == ']' && char.IsWhiteSpace(trimmed[3]) && (trimmed[1] == ' ' || trimmed[1] == 'x' || trimmed[1] == 'X' || trimmed[1] == '-'))
                {
                    trimmed = trimmed.Substring(4).TrimStart();
                    changed = true;
                }
                if (!changed && TryStripRecordBoardMarkdownLinkPrefix(trimmed, out var markdownLinkStripped))
                {
                    trimmed = markdownLinkStripped;
                    changed = true;
                    continue;
                }
                if (!changed && TryStripRecordBoardAngleLinkPrefix(trimmed, out var angleLinkStripped))
                {
                    trimmed = angleLinkStripped;
                    changed = true;
                    continue;
                }
                if (!changed)
                {
                    int bracketEndIndex = trimmed.IndexOf("]", StringComparison.Ordinal);
                    if (bracketEndIndex > 1 && bracketEndIndex + 1 < trimmed.Length && trimmed[0] == '[' && char.IsWhiteSpace(trimmed[bracketEndIndex + 1]) && IsRecordBoardNonGradeBracketPrefix(trimmed.Substring(1, bracketEndIndex - 1).Trim()))
                    {
                        trimmed = trimmed.Substring(bracketEndIndex + 2).TrimStart();
                        changed = true;
                        continue;
                    }
                }
                if (!changed && trimmed.Length >= 4 && trimmed[0] == '(')
                {
                    int parenEndIndex = trimmed.IndexOf(")", StringComparison.Ordinal);
                    if (parenEndIndex > 1 && parenEndIndex + 1 < trimmed.Length && char.IsWhiteSpace(trimmed[parenEndIndex + 1]) && IsRecordBoardNonGradeBracketPrefix(trimmed.Substring(1, parenEndIndex - 1).Trim()))
                    {
                        trimmed = trimmed.Substring(parenEndIndex + 2).TrimStart();
                        changed = true;
                    }
                }
            }
            return trimmed;
        }

        private static bool TryStripRecordBoardMarkdownLinkPrefix(string text, out string stripped)
        {
            stripped = text;
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }
            bool imageLink = text.StartsWith("![", StringComparison.Ordinal);
            if (!imageLink && !text.StartsWith("[", StringComparison.Ordinal))
            {
                return false;
            }
            int labelStartIndex = ((!imageLink) ? 1 : 2);
            int labelEndIndex = text.IndexOf("](", labelStartIndex, StringComparison.Ordinal);
            if (labelEndIndex <= labelStartIndex)
            {
                return false;
            }
            int targetEndIndex = text.IndexOf(")", labelEndIndex + 2, StringComparison.Ordinal);
            if (targetEndIndex < 0 || !CanStripRecordBoardLinkPrefixAt(text, targetEndIndex + 1))
            {
                return false;
            }
            string label = text.Substring(labelStartIndex, labelEndIndex - labelStartIndex).Trim();
            if (!imageLink && !IsRecordBoardNonGradeBracketPrefix(label))
            {
                return false;
            }
            stripped = text.Substring(targetEndIndex + 1).TrimStart();
            return true;
        }

        private static bool TryStripRecordBoardAngleLinkPrefix(string text, out string stripped)
        {
            stripped = text;
            if (string.IsNullOrWhiteSpace(text) || text[0] != '<')
            {
                return false;
            }
            int linkEndIndex = text.IndexOf(">", StringComparison.Ordinal);
            if (linkEndIndex <= 1 || !CanStripRecordBoardLinkPrefixAt(text, linkEndIndex + 1))
            {
                return false;
            }
            string target = text.Substring(1, linkEndIndex - 1).Trim();
            if (!target.StartsWith("http", StringComparison.OrdinalIgnoreCase) && !target.StartsWith("obsidian:", StringComparison.OrdinalIgnoreCase) && !target.StartsWith("file:", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }
            stripped = text.Substring(linkEndIndex + 1).TrimStart();
            return true;
        }

        private static bool CanStripRecordBoardLinkPrefixAt(string text, int remainderIndex)
        {
            if (remainderIndex >= text.Length)
            {
                return false;
            }
            char ch = text[remainderIndex];
            if (!char.IsWhiteSpace(ch) && ch != '[' && ch != '#')
            {
                return ch == '시';
            }
            return true;
        }

        private static string StripRecordBoardMarkdownWrapper(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return string.Empty;
            }
            string trimmed = text.Trim();
            bool changed = true;
            while (changed)
            {
                changed = false;
                if (trimmed.Length >= 4 && ((trimmed.StartsWith("**", StringComparison.Ordinal) && trimmed.EndsWith("**", StringComparison.Ordinal)) || (trimmed.StartsWith("__", StringComparison.Ordinal) && trimmed.EndsWith("__", StringComparison.Ordinal)) || (trimmed.StartsWith("~~", StringComparison.Ordinal) && trimmed.EndsWith("~~", StringComparison.Ordinal))))
                {
                    trimmed = trimmed.Substring(2, trimmed.Length - 4).Trim();
                    changed = true;
                }
                else if (trimmed.Length >= 2 && trimmed[0] == '`' && trimmed[trimmed.Length - 1] == '`')
                {
                    trimmed = trimmed.Substring(1, trimmed.Length - 2).Trim();
                    changed = true;
                }
                else if (trimmed.Length >= 2 && trimmed[0] == '_' && trimmed[trimmed.Length - 1] == '_')
                {
                    trimmed = trimmed.Substring(1, trimmed.Length - 2).Trim();
                    changed = true;
                }
            }
            return trimmed;
        }

        private static string NormalizeRecordBoardLeadingRankPrefix(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return string.Empty;
            }
            string trimmed = text.TrimStart();
            if (trimmed.StartsWith("#", StringComparison.Ordinal) && trimmed.Length > 1 && char.IsDigit(trimmed[1]))
            {
                int digitIndex;
                for (digitIndex = 1; digitIndex < trimmed.Length && char.IsDigit(trimmed[digitIndex]); digitIndex++)
                {
                }
                if (digitIndex < trimmed.Length && char.IsWhiteSpace(trimmed[digitIndex]))
                {
                    return trimmed.Substring(1, digitIndex - 1) + "위 " + trimmed.Substring(digitIndex).TrimStart();
                }
            }
            if (trimmed.StartsWith("No.", StringComparison.OrdinalIgnoreCase) || trimmed.StartsWith("No ", StringComparison.OrdinalIgnoreCase))
            {
                int i;
                for (i = (trimmed.StartsWith("No.", StringComparison.OrdinalIgnoreCase) ? 3 : 3); i < trimmed.Length && char.IsWhiteSpace(trimmed[i]); i++)
                {
                }
                int digitStart = i;
                for (; i < trimmed.Length && char.IsDigit(trimmed[i]); i++)
                {
                }
                if (i > digitStart && i < trimmed.Length && char.IsWhiteSpace(trimmed[i]))
                {
                    return trimmed.Substring(digitStart, i - digitStart) + "위 " + trimmed.Substring(i).TrimStart();
                }
            }
            return text;
        }

        private static bool IsRecordBoardNonGradeBracketPrefix(string label)
        {
            if (string.IsNullOrWhiteSpace(label))
            {
                return false;
            }
            string trimmed = label.Trim();
            if (trimmed.Length == 1)
            {
                switch (trimmed)
                {
                case "S":
                case "A":
                case "B":
                case "C":
                    return false;
                }
            }
            if (!trimmed.StartsWith("!", StringComparison.Ordinal))
            {
                switch (trimmed)
                {
                default:
                    if (!trimmed.EndsWith("기록", StringComparison.Ordinal) && !trimmed.EndsWith("요약", StringComparison.Ordinal))
                    {
                        return trimmed.EndsWith("랭킹", StringComparison.Ordinal);
                    }
                    break;
                case "기록":
                case "최근":
                case "최고":
                case "일반":
                case "무한":
                case "시도":
                case "요약":
                case "랭킹":
                case "체크":
                case "완성":
                    break;
                }
            }
            return true;
        }

        private static string[] SplitRecordBoardSanitizationParts(string text)
        {
            if (string.IsNullOrEmpty(text))
            {
                return Array.Empty<string>();
            }
            List<string> parts = new List<string>();
            int partStartIndex = 0;
            for (int i = 0; i < text.Length; i++)
            {
                if (!IsRecordBoardSanitizationSeparator(text, i))
                {
                    continue;
                }
                if (text[i] == '/')
                {
                    bool num = i > 0 && char.IsDigit(text[i - 1]);
                    bool nextIsDigit = i + 1 < text.Length && char.IsDigit(text[i + 1]);
                    if (num & nextIsDigit)
                    {
                        continue;
                    }
                }
                parts.Add(text.Substring(partStartIndex, i - partStartIndex));
                partStartIndex = i + 1;
            }
            parts.Add(text.Substring(partStartIndex));
            return parts.ToArray();
        }

        private static bool IsRecordBoardSanitizationSeparator(string text, int index)
        {
            switch (text[index])
            {
            case '/':
            case ';':
            case '|':
            case '／':
            case '；':
            case '｜':
                return true;
            default:
                return false;
            case '·':
            case 'ㆍ':
            {
                bool num = index > 0 && char.IsWhiteSpace(text[index - 1]);
                bool nextIsWhitespace = index + 1 < text.Length && char.IsWhiteSpace(text[index + 1]);
                return num & nextIsWhitespace;
            }
            }
        }

        private static string StripRecordBoardDisplayPrefix(string line)
        {
            string[] prefixes = new string[41]
            {
                "기록:", "기록 저장 완료:", "기록 저장 완료 -", "기록 저장 완료", "기록 확인:", "기록 확인 -", "기록 확인", "이번 기록:", "최근 기록:", "최고 기록:",
                "대표 기록:", "보충 기록:", "보충 기록 -", "보충 기록", "완성 기록:", "완성 기록 -", "완성 기록 확인:", "완성 기록 확인 -", "완성 기록 확인", "완성 기록",
                "탈출 성공:", "탈출 성공 -", "탈출 완료:", "탈출 완료 -", "입구 탈출 완료:", "입구 탈출 완료 -", "무한 기록 저장 완료:", "무한 기록 저장 완료 -", "무한 기록 저장 완료", "이번:",
                "최근:", "최고:", "대표:", "최근 일반:", "최근 시도:", "최근 무한:", "일반 기록:", "무한 기록:", "시도 기록:", "일반 최고:",
                "무한 최고:"
            };
            for (int i = 0; i < prefixes.Length; i++)
            {
                if (line.StartsWith(prefixes[i], StringComparison.Ordinal))
                {
                    return line.Substring(prefixes[i].Length).Trim();
                }
            }
            string leadInStrippedLine = StripRecordBoardScoreLeadIn(line);
            if (!string.Equals(leadInStrippedLine, line, StringComparison.Ordinal))
            {
                return leadInStrippedLine;
            }
            return line;
        }

        private static string StripRecordBoardScoreLeadIn(string line)
        {
            string[] leadIns = new string[26]
            {
                "기록 저장 완료", "기록 확인", "이번 기록", "최근 기록", "최고 기록", "대표 기록", "보충 기록", "완성 기록 확인", "완성 기록", "무한 기록 저장 완료",
                "일반 최고", "무한 최고", "최근 일반", "최근 시도", "최근 무한", "일반 기록", "무한 기록", "시도 기록", "이번", "최근",
                "최고", "대표", "랭킹", "탈출 성공", "탈출 완료", "입구 탈출 완료"
            };
            for (int i = 0; i < leadIns.Length; i++)
            {
                if (line.StartsWith(leadIns[i], StringComparison.Ordinal))
                {
                    string remainder = TrimRecordBoardScoreLeadInSeparator(line.Substring(leadIns[i].Length).TrimStart());
                    if (StartsWithRecordBoardScoreMarker(remainder))
                    {
                        return remainder.Trim();
                    }
                }
            }
            return line;
        }

        private static string TrimRecordBoardScoreLeadInSeparator(string text)
        {
            string trimmed = text.TrimStart();
            if (trimmed.StartsWith(":", StringComparison.Ordinal) || trimmed.StartsWith("-", StringComparison.Ordinal) || trimmed.StartsWith("/", StringComparison.Ordinal))
            {
                return trimmed.Substring(1).TrimStart();
            }
            return trimmed;
        }

        private static bool StartsWithRecordBoardScoreMarker(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }
            string trimmed = text.TrimStart();
            if (!trimmed.StartsWith("[", StringComparison.Ordinal) && !trimmed.StartsWith("시도", StringComparison.Ordinal))
            {
                return ContainsRecordBoardRankedScoreMarker(trimmed);
            }
            return true;
        }

        private static bool ContainsRecordBoardRankedScoreMarker(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }
            for (int rankMarkerIndex = text.IndexOf("위", StringComparison.Ordinal); rankMarkerIndex >= 0; rankMarkerIndex = text.IndexOf("위", rankMarkerIndex + 1, StringComparison.Ordinal))
            {
                int scoreMarkerIndex;
                for (scoreMarkerIndex = rankMarkerIndex + 1; scoreMarkerIndex < text.Length && char.IsWhiteSpace(text[scoreMarkerIndex]); scoreMarkerIndex++)
                {
                }
                if (scoreMarkerIndex < text.Length && text[scoreMarkerIndex] == '[')
                {
                    return true;
                }
            }
            return false;
        }

        private static int CountRecordBoardRows(string text)
        {
            if (string.IsNullOrWhiteSpace(text) || text == "기록 없음")
            {
                return 0;
            }
            int count = 1;
            for (int i = 0; i < text.Length; i++)
            {
                if (text[i] == '\n')
                {
                    count++;
                }
            }
            return count;
        }

        private static bool IsRecordBoardManagementLine(string line)
        {
            if (LooksLikeRecordBoardPlayableScoreLine(line))
            {
                return false;
            }
            if (!line.StartsWith("관리 모드", StringComparison.Ordinal) && !line.StartsWith("저장 모드", StringComparison.Ordinal) && !line.StartsWith("선택:", StringComparison.Ordinal) && !line.StartsWith("슬롯 ", StringComparison.Ordinal) && !line.StartsWith("> 슬롯 ", StringComparison.Ordinal) && !line.StartsWith("추천 슬롯:", StringComparison.Ordinal) && !line.StartsWith("최고 슬롯:", StringComparison.Ordinal) && !line.StartsWith("저장 슬롯 선택", StringComparison.Ordinal) && !line.StartsWith("신규:", StringComparison.Ordinal) && !line.StartsWith("교체 전:", StringComparison.Ordinal) && !line.StartsWith("요약:", StringComparison.Ordinal) && !line.StartsWith("현재:", StringComparison.Ordinal) && !line.StartsWith("품질:", StringComparison.Ordinal) && !line.StartsWith("대상:", StringComparison.Ordinal) && !line.StartsWith("선택 전 저장 잠김", StringComparison.Ordinal))
            {
