        private static bool LooksLikeSaveLoadoutManagementSummaryLine(string line)
        {
            if (string.IsNullOrWhiteSpace(line))
            {
                return false;
            }
            string trimmed = line.Trim();
            if (LooksLikeRecordBoardPlayableScoreLine(trimmed))
            {
                return false;
            }
            if (trimmed.StartsWith("품질 ", StringComparison.Ordinal) || trimmed.StartsWith("현재 품질", StringComparison.Ordinal) || trimmed.StartsWith("차이:", StringComparison.Ordinal) || trimmed.Contains(" / 조합 ", StringComparison.Ordinal))
            {
                return true;
            }
            if (trimmed.Contains("점", StringComparison.Ordinal) && trimmed.Contains("m", StringComparison.Ordinal))
            {
                if (!trimmed.Contains("형", StringComparison.Ordinal) && !trimmed.Contains("축", StringComparison.Ordinal) && !trimmed.Contains("기프트", StringComparison.Ordinal) && !trimmed.Contains("유물", StringComparison.Ordinal))
                {
                    return trimmed.Contains("조합", StringComparison.Ordinal);
                }
                return true;
            }
            return false;
        }

        private static bool LooksLikeRecordBoardPlayableScoreLine(string line)
        {
            if (string.IsNullOrWhiteSpace(line))
            {
                return false;
            }
            string trimmed = line.Trim();
            if (trimmed.StartsWith("[", StringComparison.Ordinal) || trimmed.StartsWith("탈출 ", StringComparison.Ordinal) || ContainsRecordBoardRankedScoreMarker(trimmed))
            {
                return ContainsDigitBeforeMetricMarker(trimmed, "점");
            }
            return false;
        }

