        private bool HasUnpresentedRunCommandTransition => Application.isPlaying && IsRunState()
            && runCommandTransitionFrame == Time.frameCount;
        private bool HasUnpresentedScreenTransition => Application.isPlaying && screenInputTransitionFrame == Time.frameCount;

#if UNITY_EDITOR
        public const string EditorPlayModeCheckKey = "GreedLast.EditorTests.PlayModeCheck";

        public static void ResetPrototypeProgressForEditor()
        {
            GreedLastMockBackend.ClearPersistedProgressForEditor();
            PlayerPrefs.DeleteKey(PracticeCompletedPrefsKey);
            PlayerPrefs.Save();
        }
#endif

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        private static void Create()
        {
            if (FindAnyObjectByType<GreedLastApp>(FindObjectsInactive.Include) != null) return;
            var root = new GameObject(nameof(GreedLastApp));
            root.AddComponent<GreedLastApp>();
        }

        private void Awake()
        {
            if (Application.isPlaying)
            {
                if (activeApp != null && activeApp != this)
                {
                    enabled = false;
                    Destroy(this);
                    return;
                }
                activeApp = this;
                DontDestroyOnLoad(gameObject);
            }
            ConfigurePresentationSettings();
            ConfigurePrototypeMobileOrientation();

            requestGate = new GreedLastRequestGate();
#if UNITY_EDITOR
            bool isolatedPlayModeCheck = UnityEditor.SessionState.GetBool(EditorPlayModeCheckKey, false);
            backend = new GreedLastMockBackend(
                loadPersistedData: !isolatedPlayModeCheck, persistData: !isolatedPlayModeCheck);
#else
            backend = new GreedLastMockBackend();
#endif
            stateMachine = new GreedLastStateMachine(requestGate);
            runCore = new GreedLastRunCore();

            runtimeUi = gameObject.AddComponent<GreedLastRuntimeUi>();
            runtimeUi.Initialize(
                RequestPracticeRun,
                RequestNormalRun,
                RequestSaveLoadout,
                RequestInfiniteRun,
                RequestInfiniteRecordBoard,
                RequestGrowthBoard,
                RequestProfileBoard,
                RequestRetrySync,
                ToggleOfflineForEditorCheck,
                RequestNextRunPattern,
                RequestToggleRunPause,
                RequestReturnToLobby,
                RequestShowSaveLoadoutDetail,
                RequestRenameSaveLoadoutSlot,
                RequestDeleteSaveLoadoutSlot,
                ToggleRunInvincible,
                RequestInfiniteTestStop,
                RequestFocusMaxForTest,
                RequestThreatUpForTest,
                RequestThreatDownForTest,
                RequestTimingOffsetAdjust,
                RequestRunDevShortcut,
                HandleRunChannelInput);
            runtimeUi.RotationTiltPreferenceChanged += HandleRotationTiltPreferenceChanged;
            runtimeUi.ViewportChanged += HandleViewportChanged;
            runtimeUi.PresentationSuspended += HandlePresentationSuspended;
            runtimeUi.PresentationReleased += HandlePresentationReleased;

            stateMachine.StateChanged += HandleScreenStateChanged;
            runCore.SnapshotChanged += HandleRunSnapshotChanged;
        }

        private void ConfigurePresentationSettings()
        {
            if (!presentationSettingsCaptured)
            {
                previousQualityLevel = QualitySettings.GetQualityLevel();
                previousVSyncCount = QualitySettings.vSyncCount;
                previousTargetFrameRate = Application.targetFrameRate;
                previousSleepTimeout = Screen.sleepTimeout;
                presentationSettingsCaptured = true;
            }
            QualitySettings.vSyncCount = PrototypeVSyncCount;
            Application.targetFrameRate = PrototypeTargetFrameRate;
            Screen.sleepTimeout = SleepTimeout.NeverSleep;
        }

        private void RestorePresentationSettings()
        {
            if (!presentationSettingsCaptured) return;
            presentationSettingsCaptured = false;
            // Restore only values still matching this app's settings, not another owner's new choices.
            if (QualitySettings.GetQualityLevel() == previousQualityLevel
                && QualitySettings.vSyncCount == PrototypeVSyncCount) QualitySettings.vSyncCount = previousVSyncCount;
            if (Application.targetFrameRate == PrototypeTargetFrameRate) Application.targetFrameRate = previousTargetFrameRate;
            if (Screen.sleepTimeout == SleepTimeout.NeverSleep) Screen.sleepTimeout = previousSleepTimeout;
        }

        private static void ConfigurePrototypeMobileOrientation()
        {
            if (!Application.isMobilePlatform)
            {
                return;
            }

            Input.compensateSensors = ShouldCompensatePrototypeSensors();
            Screen.autorotateToPortrait = ShouldAllowPrototypeAutoRotation(ScreenOrientation.Portrait);
            Screen.autorotateToPortraitUpsideDown = ShouldAllowPrototypeAutoRotation(ScreenOrientation.PortraitUpsideDown);
            Screen.autorotateToLandscapeLeft = ShouldAllowPrototypeAutoRotation(ScreenOrientation.LandscapeLeft);
            Screen.autorotateToLandscapeRight = ShouldAllowPrototypeAutoRotation(ScreenOrientation.LandscapeRight);
            Screen.orientation = ScreenOrientation.AutoRotation;
        }

        private static bool ShouldCompensatePrototypeSensors()
        {
            return true;
        }

        private static bool ShouldAllowPrototypeAutoRotation(ScreenOrientation orientation)
        {
            return orientation == ScreenOrientation.LandscapeLeft
                || orientation == ScreenOrientation.LandscapeRight;
        }

        private void Start()
        {
            appStarted = true;
            StartCoroutine(BootThenConnect());
        }

        private void OnEnable()
        {
            RefreshPlayerInputAvailability();
            if (!interruptedBootPending) return;
            interruptedBootPending = false;
            StartCoroutine(BootThenConnect());
        }

        private void OnDisable()
        {
            runtimeUi?.SetAppInputAvailable(false);
            HandlePresentationSuspended();
            // Inactive hosts stop Unity coroutines; a component-only disable does not.
            if (appStarted && !gameObject.activeInHierarchy && requestGate != null && requestGate.Busy)
            {
                requestGate.CancelPending();
                interruptedBootPending = true;
            }
        }

        private void OnApplicationQuit()
        {
            if (applicationQuitting) return;
            applicationQuitting = true;
            runtimeUi?.SetAppInputAvailable(false);
            PersistTerminalRunResult();
        }

        private void PersistTerminalRunResult()
        {
            if (stateMachine == null || backend == null || runCore == null
                || runCore.IsPracticeRun) return;

            // Mobile suspension may never deliver quit; preserve terminal results without choosing a slot.
            if (stateMachine.CurrentState == GreedLastScreenState.RunCoreTest)
            {
                if (runCore.CanExitAfterClear) RegisterClearOnce(runCore.CreateRunRecord());
                else if (runCore.IsStoppedNormalRun)
                    RegisterNormalAttemptOnce(runCore.CreateNormalAttemptRecord(GreedLastRunAttemptOutcome.Failed));
            }
            else if (stateMachine.CurrentState == GreedLastScreenState.InfiniteRun && runCore.IsStoppedInfiniteRun)
            {
                RegisterInfiniteRunOnce(runCore.CreateInfiniteRunRecord());
            }
        }

        private GreedLastLobbySnapshot RegisterClearOnce(GreedLastRunRecord record)
        {
            if (runResultRegistered || !record.IsValid) return backend.LoadLobby();
            GreedLastLobbySnapshot snapshot = backend.RegisterClear(record);
            runResultRegistered = true;
            return snapshot;
        }

        private bool RegisterNormalAttemptOnce(GreedLastRunAttemptRecord record)
        {
            if (!record.IsValid) return false;
            if (runResultRegistered) return true;
            runResultRegistered = backend.RegisterNormalAttempt(record);
            return runResultRegistered;
        }

        private bool RegisterInfiniteRunOnce(GreedLastInfiniteRunRecord record)
        {
            if (!record.IsValid) return false;
            if (runResultRegistered) return true;
            runResultRegistered = backend.RegisterInfiniteRun(record);
            return runResultRegistered;
        }

        private void OnDestroy()
        {
            if (activeApp == this) activeApp = null;
            RestorePresentationSettings();
            if (stateMachine != null && runtimeUi != null)
            {
                stateMachine.StateChanged -= HandleScreenStateChanged;
                runtimeUi.RotationTiltPreferenceChanged -= HandleRotationTiltPreferenceChanged;
                runtimeUi.ViewportChanged -= HandleViewportChanged;
                runtimeUi.PresentationSuspended -= HandlePresentationSuspended;
                runtimeUi.PresentationReleased -= HandlePresentationReleased;
            }

            if (runCore != null)
            {
                runCore.SnapshotChanged -= HandleRunSnapshotChanged;
            }
            if (Application.isPlaying && runtimeUi != null)
            {
                runtimeUi.enabled = false;
                Destroy(runtimeUi);
            }
        }

        private void HandleScreenStateChanged(GreedLastStateSnapshot snapshot)
        {
            screenInputTransitionFrame = Time.frameCount;
            runtimeUi?.Render(snapshot);
        }

        private void HandleRunSnapshotChanged(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.Stopped) runResultRegistered = false;
            if (snapshot.ActivePattern && (!hasLatestAppRunSnapshot || !latestAppRunSnapshot.ActivePattern
                || !string.Equals(snapshot.Pattern.PatternId, latestAppRunSnapshot.Pattern.PatternId, StringComparison.Ordinal)))
                runPatternTransitionFrame = Time.frameCount;
            if (snapshot.ChoiceActive && (!hasLatestAppRunSnapshot || !latestAppRunSnapshot.ChoiceActive
                || snapshot.ChoiceKind != latestAppRunSnapshot.ChoiceKind))
                runChoiceTransitionFrame = Time.frameCount;
            // A live press must not become a newly opened pause or result command.
            if ((snapshot.Stopped && (!hasLatestAppRunSnapshot || !latestAppRunSnapshot.Stopped))
                || (snapshot.Paused && (!hasLatestAppRunSnapshot || !latestAppRunSnapshot.Paused)))
            {
                runCommandTransitionFrame = Time.frameCount;
                runtimeUi?.CancelPendingUiInput();
            }
            bool leavingRotation = hasLatestAppRunSnapshot
                && IsLiveRotationInputWindow(latestAppRunSnapshot)
                && GreedLastRunCore.IsRotationPattern(latestAppRunSnapshot.Pattern)
                && (!IsLiveRotationInputWindow(snapshot)
                    || !GreedLastRunCore.IsRotationPattern(snapshot.Pattern));
            latestAppRunSnapshot = snapshot;
            hasLatestAppRunSnapshot = true;
            if (leavingRotation)
                ResetRotationTiltSensorTracking(requireNeutralRelease: true);
            if (!snapshot.ActivePattern || snapshot.Paused || snapshot.CountdownActive
                || !GreedLastRunCore.IsRotationPattern(snapshot.Pattern))
            {
                ResetRotationDragTracking();
            }
            if (runtimeUi != null)
            {
                PublishRotationTiltGateState();
                runtimeUi.RenderRun(snapshot);
            }
        }

        private void HandleRotationTiltPreferenceChanged(bool enabled)
        {
            ResetRotationTiltSensorTracking(requireNeutralRelease: Application.isMobilePlatform && enabled);
            PublishRotationTiltGateState();
            if (runtimeUi != null && hasLatestAppRunSnapshot)
            {
                runtimeUi.RenderRun(latestAppRunSnapshot);
            }
        }

        private void HandleViewportChanged()
        {
            ResetRotationDragTracking();
            ResetRotationTiltSensorTracking(requireNeutralRelease: true);
            PublishRotationTiltGateState();
        }

        private void HandlePresentationReleased(GreedLastRuntimeUi releasedUi)
        {
            if (!ReferenceEquals(runtimeUi, releasedUi)) return;
            stateMachine.StateChanged -= HandleScreenStateChanged;
            releasedUi.RotationTiltPreferenceChanged -= HandleRotationTiltPreferenceChanged;
            releasedUi.ViewportChanged -= HandleViewportChanged;
            releasedUi.PresentationSuspended -= HandlePresentationSuspended;
            releasedUi.PresentationReleased -= HandlePresentationReleased;
            runtimeUi = null;
            HandlePresentationSuspended();
        }

        private void HandlePresentationSuspended()
        {
            PauseRunForAppBackground();
            runtimeUi?.CancelPendingUiInput();
            ResetRotationDragTracking();
            ResetRotationTiltSensorTracking(requireNeutralRelease: true);
            PublishRotationTiltGateState();
        }

        private void PublishRotationTiltGateState()
        {
            if (runtimeUi != null)
            {
                float now = Time.realtimeSinceStartup;
                bool dragPreview = DevToolsEnabled
                    && !Application.isMobilePlatform
                    && rotationDragTracking;
                int displayCandidateDirection = dragPreview
                    ? ResolveRotationTiltDirection(rotationDragVisualAxis, 1f)
                    : rotationTiltCandidateDirection;
                float displayCandidateProgress = dragPreview
                    ? Mathf.Clamp01(Mathf.Abs(rotationDragVisualAxis))
                    : BuildRotationTiltCandidateProgress(
                        rotationTiltCandidateDirection,
                        rotationTiltCandidateSince,
                        now,
                        RotationTiltConfirmationSeconds);
                float displayAxis = dragPreview
                    ? rotationDragVisualAxis
                    : BuildRotationTiltNormalizedAxis(
                        rotationTiltAxisInitialized,
                        rotationTiltFilteredAxis,
                        RotationTiltInputThreshold);
                runtimeUi.SetRotationTiltGateState(
                    (DevToolsEnabled && !Application.isMobilePlatform)
                        || CanUseRotationTiltSensorWithPreference(
                            Application.isMobilePlatform,
                            SystemInfo.supportsAccelerometer,
                            runtimeUi.RotationTiltEnabled),
                    rotationTiltReady,
                    rotationTiltHeldDirection,
                    displayCandidateDirection,
                    displayCandidateProgress,
                    displayAxis);
            }
        }

        private void Update()
        {
            if (stateMachine == null || runCore == null || !CanAcceptPlayerInput())
            {
                return;
            }

            if (IsRunState())
            {
                float now = Time.realtimeSinceStartup;
                if (runCore.PauseForInterruptedFrame(now))
                {
                    HandlePresentationSuspended();
                    return;
                }
                runCore.Tick(now);
            }

            bool keyboardAllowed = CanUsePrototypeKeyboardInput();
            if (keyboardAllowed && (TryHandlePauseOrBackKeyboardInput(Input.GetKeyDown(KeyCode.Escape), Input.GetKeyDown(KeyCode.P))
                || TryHandleDevKeyboardInput() || TryHandlePrimaryKeyboardInput() || TryHandleRotationKeyboardInput()))
            {
                return;
            }

            if (TryHandleRotationTiltInput())
            {
                return;
            }

            if (TryHandleRotationMouseDragInput())
            {
                return;
            }

            if (keyboardAllowed && TryHandleLaneKeyboardInput())
            {
                return;
            }
        }

        internal static bool CanUsePrototypeKeyboardInput()
        {
            return ShouldAllowPrototypeKeyboardInput(
                Input.GetKey(KeyCode.LeftControl) || Input.GetKey(KeyCode.RightControl),
                Input.GetKey(KeyCode.LeftAlt) || Input.GetKey(KeyCode.RightAlt) || Input.GetKey(KeyCode.AltGr),
                Input.GetKey(KeyCode.LeftCommand) || Input.GetKey(KeyCode.RightCommand)
                    || Input.GetKey(KeyCode.LeftWindows) || Input.GetKey(KeyCode.RightWindows));
        }

        private static bool ShouldAllowPrototypeKeyboardInput(bool controlHeld, bool altHeld, bool systemHeld)
            => !controlHeld && !altHeld && !systemHeld;

        private bool TryHandlePrimaryKeyboardInput()
        {
            bool primaryPressed = Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter);
            return TryHandlePrimaryKeyboardFrame(primaryPressed,
                primaryPressed && ReadPressedLaneKeyboardChannel() != GreedLastRunChannel.None);
        }

        private bool TryHandlePrimaryKeyboardFrame(bool primaryPressed, bool lanePressed)
        {
            // In selection screens the direction must win; confirmation requires a separate fresh Enter.
            if (primaryPressed && lanePressed && (stateMachine.CurrentState == GreedLastScreenState.SaveLoadoutDraft
                || stateMachine.CurrentState == GreedLastScreenState.InfiniteLoadoutSelect
                || stateMachine.CurrentState == GreedLastScreenState.InfiniteStartReady)) return false;
            return TryHandlePrimaryKeyboardCommand(primaryPressed);
        }

        private bool TryHandlePrimaryKeyboardCommand(bool primaryPressed)
        {
            if (!primaryPressed)
            {
                return false;
            }
            if (HasUnpresentedScreenTransition || HasUnpresentedRunCommandTransition) return true;

            if (stateMachine.CurrentState == GreedLastScreenState.SaveLoadoutDraft
                || stateMachine.CurrentState == GreedLastScreenState.InfiniteLoadoutSelect
                || stateMachine.CurrentState == GreedLastScreenState.InfiniteRecordBoard
                || stateMachine.CurrentState == GreedLastScreenState.InfiniteStartReady
                || stateMachine.CurrentState == GreedLastScreenState.ProfileBoard
                || IsRunState())
            {
                RequestNextRunPattern();
                return true;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.GrowthBoard)
            {
                UpgradeRecommendedGrowthTrack();
                return true;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.LobbyReady)
            {
                HandleLobbyPrimaryKeyboardInput();
                return true;
            }

            return false;
        }

        private void HandleLobbyPrimaryKeyboardInput()
        {
            GreedLastLobbySnapshot snapshot = stateMachine.LobbySnapshot;
            string detail = stateMachine.CurrentDetail ?? string.Empty;
            if (PlayerPrefs.GetInt(PracticeCompletedPrefsKey, 0) != 1
                && !snapshot.FirstSaveCompleted
                && !snapshot.SaveLoadoutUnlocked)
            {
                RequestPracticeRun();
                return;
            }

            if (snapshot.SaveLoadoutCandidateAvailable)
            {
                RequestSaveLoadout();
                return;
            }

            switch (ResolveLobbyPrimaryActionTarget(
                snapshot.SaveLoadoutCandidateAvailable,
                snapshot.SaveLoadoutUnlocked,
                snapshot.FirstSaveCompleted,
                HasAnyUsableSaveSlot(snapshot),
                detail))
            {
                case "무한":
                    RequestInfiniteRun();
                    return;
                case "연습":
                    RequestPracticeRun();
                    return;
                case "일반":
                    RequestNormalRun();
                    return;
                case "저장":
                    RequestSaveLoadout();
                    return;
                case "성장":
                    RequestGrowthBoard();
                    return;
                case "흔적":
                    RequestProfileBoard();
                    return;
                case "기록":
                    RequestInfiniteRecordBoard();
                    return;
            }

            if (CanUpgradeAnyGrowthTrack(snapshot))
            {
                RequestGrowthBoard();
                return;
            }

            if (snapshot.ProfileButtonSummary.Contains("NEW", StringComparison.Ordinal))
            {
                RequestProfileBoard();
                return;
            }

            RequestNormalRun();
        }

        private static string ResolveLobbyPrimaryActionTarget(
            bool saveLoadoutCandidateAvailable,
            bool saveLoadoutUnlocked,
            bool firstSaveCompleted,
            bool hasAnyUsableSaveLoadoutSlot,
            string detail)
        {
            if (saveLoadoutCandidateAvailable)
            {
                return "저장";
            }

            if ((saveLoadoutUnlocked || firstSaveCompleted) && !hasAnyUsableSaveLoadoutSlot)
            {
                return "무한";
            }

            string nextActionTarget = ResolveLobbyNextActionTarget(detail);
            if (!string.IsNullOrEmpty(nextActionTarget))
            {
                return nextActionTarget;
            }

            return IsNormalRecordResultDetail(detail) || IsInfiniteRecordResultDetail(detail)
                ? "기록"
                : string.Empty;
        }

        internal static string ResolveLobbyNextActionTarget(string detail)
        {
            if (string.IsNullOrEmpty(detail))
            {
                return string.Empty;
            }

            string compactDisplayTarget = ResolvePrototypeCompactDisplayLabelLobbyTarget(detail.Trim());
            if (!string.IsNullOrEmpty(compactDisplayTarget))
            {
                return compactDisplayTarget;
            }

            if (detail.Contains("다음 확인: 저장 후보", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 후보 처리", StringComparison.Ordinal))
            {
                return "저장";
            }

            if (ContainsNextDirectiveAlias(detail, "후보 처리"))
            {
                return "저장";
            }

            if (ContainsNextDirectiveAlias(detail, "저장")
                || ContainsNextDirectiveAlias(detail, "저장/포기")
                || ContainsNextDirectiveAlias(detail, "저장 또는 포기"))
            {
                return "저장";
            }

            if (detail.Contains("다음: 저장 후보 저장", StringComparison.Ordinal)
                || detail.Contains("다음: 저장 후보를", StringComparison.Ordinal)
                || detail.Contains("다음: 후보 저장", StringComparison.Ordinal)
                || detail.Contains("다음: 후보 처리", StringComparison.Ordinal)
                || detail.Contains("다음: 저장 버튼", StringComparison.Ordinal))
            {
                return "저장";
            }

            if (detail.Contains("다음 확인: 저장 조합에서 후보", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 저장 조합에서 첫 슬롯", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 저장 조합 후보", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 저장 조합 변경", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 저장 조합 관리", StringComparison.Ordinal))
            {
                return "저장";
            }

            if (detail.Contains("다음: 슬롯 선택 후 저장", StringComparison.Ordinal)
                || detail.Contains("저장 기회: 저장하거나 포기", StringComparison.Ordinal)
                || (detail.Contains("저장 기회:", StringComparison.Ordinal)
                    && detail.Contains("저장하거나 포기", StringComparison.Ordinal)))
            {
                return "저장";
            }

            if (detail.Contains("다음 확인: 일반 런", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 첫 함정", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 시작→런", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 런 확인", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 일반 탈출", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 클리어 후", StringComparison.Ordinal))
            {
                return "일반";
            }

            if (ContainsNextDirectiveAlias(detail, "첫 함정")
                || ContainsNextDirectiveAlias(detail, "시작→런 확인")
                || ContainsNextDirectiveAlias(detail, "런 확인")
                || ContainsNextDirectiveAlias(detail, "일반 탈출")
                || ContainsNextDirectiveAlias(detail, "저장 후보 생성"))
            {
                return "일반";
            }

            if (ContainsNextDirectiveAlias(detail, "일반"))
            {
                return "일반";
            }

            if (detail.Contains("다음 확인: 복기 연습", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 복기 후 탈출", StringComparison.Ordinal))
            {
                return "연습";
            }

            if (ContainsNextDirectiveAlias(detail, "복기 후 탈출"))
            {
                return "연습";
            }

            if (ContainsNextDirectiveAlias(detail, "연습"))
            {
                return "연습";
            }

            if (detail.Contains("다음 확인: 무한 복기 전", StringComparison.Ordinal)
                || detail.Contains("다음: 무한 복기 전", StringComparison.Ordinal))
            {
                return "연습";
            }

            if (detail.Contains("다음 확인: 복기 재도전", StringComparison.Ordinal))
            {
                return "일반";
            }

            if (detail.Contains("다음: 무한 복기 재도전", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 무한 복기 재도전", StringComparison.Ordinal)
                || detail.Contains("다음: 저장 조합으로 무한모드", StringComparison.Ordinal)
                || detail.Contains("다음: 무한모드 다시 준비", StringComparison.Ordinal)
                || detail.Contains("다음: 정산 종료 확인 후 무한모드", StringComparison.Ordinal)
                || detail.Contains("다음: 무한 버튼으로 보충 런", StringComparison.Ordinal)
                || detail.Contains("다음: 무한 조합 보충", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 저장 조합으로 무한", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 첫 무한", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 저장 조합 2회 소진", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 2회 소진", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 무한 조합 보충", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 무한 위협", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 무한 기록", StringComparison.Ordinal)
                || detail.Contains("다음: 보충 후 무한 재진입", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 보충 후 무한 재진입", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 보충 재진입", StringComparison.Ordinal)
                || detail.Contains("다음: 보충 런", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 보충 런", StringComparison.Ordinal)
                || detail.Contains("보충 런 버튼:", StringComparison.Ordinal)
                || (detail.Contains("보충 안내", StringComparison.Ordinal)
                    && detail.Contains("저장 조합 없음", StringComparison.Ordinal)))
            {
                return "무한";
            }

            if (detail.Contains("다음: 복기 연습", StringComparison.Ordinal))
            {
                return "연습";
            }

            if (detail.Contains("다음: 복기 재도전", StringComparison.Ordinal)
                || detail.Contains("다음: 일반 런", StringComparison.Ordinal))
            {
                return "일반";
            }

            if (detail.Contains("다음: 저장 조합", StringComparison.Ordinal))
            {
                return "저장";
            }

            if (ContainsNextDirectiveAlias(detail, "무한"))
            {
                return "무한";
            }

            if (ContainsNextDirectiveAlias(detail, "첫 무한")
                || ContainsNextDirectiveAlias(detail, "2회 소진")
                || ContainsNextDirectiveAlias(detail, "무한 기록")
                || ContainsNextDirectiveAlias(detail, "보충 재진입"))
            {
                return "무한";
            }

            if (ContainsNextDirectiveAlias(detail, "저장 소모")
                || ContainsNextDirectiveAlias(detail, "PgUp 소모"))
            {
                return "무한";
            }

            if (detail.Contains("다음: 성장 보정", StringComparison.Ordinal)
                || detail.Contains("다음: 성장 포인트", StringComparison.Ordinal))
            {
                return "성장";
            }

            if (detail.Contains("다음 확인: 성장 보정", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 성장 포인트", StringComparison.Ordinal))
            {
                return "성장";
            }

            if (ContainsNextDirectiveAlias(detail, "성장"))
            {
                return "성장";
            }

            if (detail.Contains("다음: 흔적", StringComparison.Ordinal))
            {
                return "흔적";
            }

            if (detail.Contains("다음 확인: 흔적", StringComparison.Ordinal))
            {
                return "흔적";
            }

            if (ContainsNextDirectiveAlias(detail, "흔적"))
            {
                return "흔적";
            }

            if (detail.Contains("다음: 기록 보기", StringComparison.Ordinal)
                || detail.Contains("다음: 기록 확인", StringComparison.Ordinal)
                || detail.Contains("다음: 기록 보드", StringComparison.Ordinal)
                || detail.Contains("다음: 완성 기록", StringComparison.Ordinal)
                || IsPrototypeCompletionRecordRequestDetail(detail)
                || detail.Contains("다음 확인: 기록 보드", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 기록 보기", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 기록 확인", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 완성 기록", StringComparison.Ordinal))
            {
                return "기록";
            }

            if (ContainsNextDirectiveAlias(detail, "기록"))
            {
                return "기록";
            }

            return ResolveLobbyExplicitActionTarget(detail);
        }

        internal static string ResolvePrototypeCompactDisplayLabelLobbyTarget(string normalizedText)
        {
            if (string.IsNullOrWhiteSpace(normalizedText))
            {
                return string.Empty;
            }

            string text = normalizedText.Trim();
            if (text.Equals("후보 처리", StringComparison.Ordinal))
            {
                return "저장";
            }

            if (text.Equals("첫 함정", StringComparison.Ordinal)
                || text.Equals("시작→런 확인", StringComparison.Ordinal)
                || text.Equals("런 확인", StringComparison.Ordinal)
                || text.Equals("일반 탈출", StringComparison.Ordinal)
                || text.Equals("저장 후보 생성", StringComparison.Ordinal))
            {
                return "일반";
            }

            if (text.Equals("복기 후 탈출", StringComparison.Ordinal))
            {
                return "연습";
            }

            if (text.Equals("첫 무한", StringComparison.Ordinal)
                || text.Equals("2회 소진", StringComparison.Ordinal)
                || text.Equals("무한 기록", StringComparison.Ordinal)
                || text.Equals("보충 재진입", StringComparison.Ordinal))
            {
                return "무한";
            }

            if (text.Equals("성장 보정", StringComparison.Ordinal))
            {
                return "성장";
            }

            if (text.Equals("흔적 확인", StringComparison.Ordinal))
            {
                return "흔적";
            }

            return text.Equals("완성 기록", StringComparison.Ordinal) ? "기록" : string.Empty;
        }

        private static bool ContainsNextDirectiveAlias(string detail, string alias)
        {
            if (string.IsNullOrEmpty(detail) || string.IsNullOrWhiteSpace(alias))
            {
                return false;
            }

            string nextDirective = "다음: " + alias;
            string nextCheckDirective = "다음 확인: " + alias;
            foreach (string rawLine in detail.Split('\n'))
            {
                string line = rawLine.Trim();
                if (LineOrSlashSegmentMatchesDirectiveAlias(line, nextDirective)
                    || LineOrSlashSegmentMatchesDirectiveAlias(line, nextCheckDirective))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool LineOrSlashSegmentMatchesDirectiveAlias(string line, string directive, bool allowSpacePrefix = false)
        {
            if (LineMatchesDirectiveAlias(line, directive, allowSpacePrefix))
            {
                return true;
            }

            for (int i = 0; i < line.Length; i += 1)
            {
                if (!IsLobbyDirectiveSegmentSeparator(line, i) || i + 1 >= line.Length)
                {
                    continue;
                }

                string segmentTail = line.Substring(i + 1).TrimStart();
                if (LineMatchesDirectiveAlias(segmentTail, directive, allowSpacePrefix))
                {
                    return true;
                }
            }

            foreach (string rawSegment in SplitLobbyDirectiveSegments(line))
            {
                string segment = rawSegment.Trim();
                if (LineMatchesDirectiveAlias(segment, directive, allowSpacePrefix))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool LineMatchesDirectiveAlias(string line, string directive, bool allowSpacePrefix)
        {
            if (LineStartsWithDirectiveAlias(line, directive, allowSpacePrefix))
            {
                return true;
            }

            int separatorIndex = line.IndexOf(": ", StringComparison.Ordinal);
            while (separatorIndex >= 0 && separatorIndex + 2 < line.Length)
            {
                string nestedLine = line.Substring(separatorIndex + 2).TrimStart();
                if (LineStartsWithDirectiveAlias(nestedLine, directive, allowSpacePrefix))
                {
                    return true;
                }

                separatorIndex = line.IndexOf(": ", separatorIndex + 2, StringComparison.Ordinal);
            }

            separatorIndex = line.IndexOf(':');
            while (separatorIndex >= 0 && separatorIndex + 1 < line.Length)
            {
                string nestedLine = line.Substring(separatorIndex + 1).TrimStart();
                if (LineStartsWithDirectiveAlias(nestedLine, directive, allowSpacePrefix))
                {
                    return true;
                }

                separatorIndex = line.IndexOf(':', separatorIndex + 1);
            }

            return false;
        }

        private static string[] SplitLobbyDirectiveSegments(string line)
        {
            if (string.IsNullOrEmpty(line))
            {
                return Array.Empty<string>();
            }

            var segments = new List<string>();
            int segmentStartIndex = 0;
            for (int i = 0; i < line.Length; i += 1)
            {
                if (!IsLobbyDirectiveSegmentSeparator(line, i))
                {
                    continue;
                }

                segments.Add(line.Substring(segmentStartIndex, i - segmentStartIndex));
                segmentStartIndex = i + 1;
            }

            segments.Add(line.Substring(segmentStartIndex));
            return segments.ToArray();
        }

        private static bool IsLobbyDirectiveSegmentSeparator(string line, int index)
        {
            char ch = line[index];
            if (ch == '/'
                || ch == '／')
            {
                bool previousIsDigit = index > 0 && char.IsDigit(line[index - 1]);
                bool nextIsDigit = index + 1 < line.Length && char.IsDigit(line[index + 1]);
                return !(previousIsDigit && nextIsDigit);
            }

            return ch == '|'
                || ch == '｜'
                || ch == ';'
                || ch == '；';
        }

        private static bool LineStartsWithDirectiveAlias(string line, string directive, bool allowSpacePrefix)
        {
            string compactDirective = directive.Replace(": ", ":");
            return LineStartsWithDirectiveForm(line, directive, allowSpacePrefix)
                || (!string.Equals(compactDirective, directive, StringComparison.Ordinal)
                    && LineStartsWithDirectiveForm(line, compactDirective, allowSpacePrefix));
        }

        private static bool LineStartsWithDirectiveForm(string line, string directive, bool allowSpacePrefix)
        {
            return line.Equals(directive, StringComparison.Ordinal)
                || (allowSpacePrefix && line.StartsWith(directive + " ", StringComparison.Ordinal))
                || line.StartsWith(directive + " /", StringComparison.Ordinal)
                || line.StartsWith(directive + "/", StringComparison.Ordinal)
                || line.StartsWith(directive + " |", StringComparison.Ordinal)
                || line.StartsWith(directive + "|", StringComparison.Ordinal)
                || line.StartsWith(directive + " -", StringComparison.Ordinal)
                || line.StartsWith(directive + "-", StringComparison.Ordinal)
                || line.StartsWith(directive + ":", StringComparison.Ordinal);
        }

        private static string ResolveLobbyExplicitActionTarget(string detail)
        {
            if (string.IsNullOrEmpty(detail))
            {
                return string.Empty;
            }

            if (ContainsActionDirectiveAlias(detail, "저장 소모")
                || ContainsActionDirectiveAlias(detail, "PgUp 소모"))
            {
                return "무한";
            }

            if (ContainsActionDirectiveAlias(detail, "저장 조합 2회 소진")
                || ContainsActionDirectiveAlias(detail, "저장 조합 소진"))
            {
                return "무한";
            }

            if (ContainsActionDirectiveAlias(detail, "후보 처리"))
            {
                return "저장";
            }

            if (ContainsActionDirectiveAlias(detail, "저장 후보 생성"))
            {
                return "일반";
            }

            if (ContainsActionDirectiveAlias(detail, "저장")
                || ContainsActionDirectiveAlias(detail, "저장/포기")
                || ContainsActionDirectiveAlias(detail, "저장 또는 포기"))
            {
                return "저장";
            }

            if (detail.Contains("실행: 저장 조합", StringComparison.Ordinal)
                || detail.Contains("실행: 저장 후보", StringComparison.Ordinal)
                || detail.Contains("실행: 후보 처리", StringComparison.Ordinal)
                || detail.Contains("Enter/강조: 저장 조합", StringComparison.Ordinal)
                || detail.Contains("Enter/강조: 저장 후보", StringComparison.Ordinal)
                || detail.Contains("Enter/강조: 후보 처리", StringComparison.Ordinal)
