            }

            return string.Empty;
        }

        private static bool ContainsActionDirectiveAlias(string detail, string alias)
        {
            if (string.IsNullOrEmpty(detail) || string.IsNullOrWhiteSpace(alias))
            {
                return false;
            }

            string executeDirective = "실행: " + alias;
            string enterDirective = "Enter/강조: " + alias;
            string highlightDirective = "강조 버튼: " + alias;
            foreach (string rawLine in detail.Split('\n'))
            {
                string line = rawLine.Trim();
                if (LineOrSlashSegmentMatchesDirectiveAlias(line, executeDirective, allowSpacePrefix: true)
                    || LineOrSlashSegmentMatchesDirectiveAlias(line, enterDirective, allowSpacePrefix: true)
                    || LineOrSlashSegmentMatchesDirectiveAlias(line, highlightDirective, allowSpacePrefix: true))
                {
                    return true;
                }
            }

            return false;
        }

        private bool TryHandleRotationKeyboardInput()
        {
            bool leftRotation = Input.GetKeyDown(KeyCode.Q);
            bool rightRotation = Input.GetKeyDown(KeyCode.E);
            if (!leftRotation && !rightRotation)
            {
                return false;
            }

            if (!DevToolsEnabled || !IsRunState())
            {
                return true;
            }

            if (runCore.IsPaused
                || !hasLatestAppRunSnapshot
                || !latestAppRunSnapshot.ActivePattern
                || !GreedLastRunCore.IsRotationPattern(latestAppRunSnapshot.Pattern))
            {
                return true;
            }

            HandleRunChannelInput(leftRotation ? GreedLastRunChannel.Left : GreedLastRunChannel.Right);
            return true;
        }

        private bool TryHandleRotationTiltInput()
        {
            if (!CanUseRotationTiltSensorWithPreference(
                Application.isMobilePlatform,
                SystemInfo.supportsAccelerometer,
                runtimeUi == null || runtimeUi.RotationTiltEnabled))
            {
                if (!rotationTiltReady || rotationTiltHeldDirection != 0 || rotationTiltAxisInitialized)
                {
                    ResetRotationTiltSensorTracking(requireNeutralRelease: Application.isMobilePlatform);
                    PublishRotationTiltGateState();
                }

                return false;
            }

            int orientationMode = ResolveRotationTiltOrientationMode(Screen.orientation, Input.deviceOrientation);
            if (orientationMode < 0)
            {
                orientationMode = rotationTiltOrientationMode >= 0
                    ? rotationTiltOrientationMode
                    : (Screen.width >= Screen.height ? 2 : 0);
            }

            float rawTiltAxis = ResolveCompensatedRotationTiltAxis(Input.acceleration);
            return TryHandleRotationTiltSample(rawTiltAxis, orientationMode,
                Time.realtimeSinceStartup, Time.unscaledDeltaTime);
        }

        private bool TryHandleRotationTiltSample(float rawTiltAxis, int orientationMode, float now, float deltaTime)
        {
            if (!IsRotationTiltAxisSampleValid(rawTiltAxis))
            {
                ResetRotationTiltSensorTracking(requireNeutralRelease: true);
                PublishRotationTiltGateState();
                return false;
            }

            if (lastRotationTiltSampleAt >= 0f
                && (now < lastRotationTiltSampleAt || now - lastRotationTiltSampleAt > RotationTiltMaxSampleGapSeconds))
            {
                ResetRotationTiltSensorTracking(requireNeutralRelease: true);
            }
            lastRotationTiltSampleAt = now;

            bool orientationChanged = orientationMode != rotationTiltOrientationMode;
            if (orientationChanged)
            {
                rotationTiltOrientationMode = orientationMode;
                rotationTiltAxisInitialized = false;
                rotationTiltReady = false;
                rotationTiltHeldDirection = 0;
                ResetRotationTiltCandidate();
            }

            rotationTiltFilteredAxis = BuildRotationTiltFilteredAxis(
                rotationTiltFilteredAxis,
                rawTiltAxis,
                deltaTime,
                RotationTiltFilterSpeed,
                rotationTiltAxisInitialized);
            rotationTiltAxisInitialized = true;

            bool activeRotationPattern = IsRunState()
                && hasLatestAppRunSnapshot
                && IsLiveRotationInputWindow(latestAppRunSnapshot)
                && GreedLastRunCore.IsRotationPattern(latestAppRunSnapshot.Pattern);
            if (!activeRotationPattern || runCore.IsPaused)
            {
                UpdateRotationTiltGateForInactiveWindow(rawTiltAxis, rotationTiltFilteredAxis);
                PublishRotationTiltGateState();
                return false;
            }

            if (IsRotationTiltNeutralSample(rawTiltAxis, rotationTiltFilteredAxis))
            {
                rotationTiltReady = true;
                rotationTiltHeldDirection = 0;
                ResetRotationTiltCandidate();
                PublishRotationTiltGateState();
                return false;
            }

            int tiltDirection = ResolveRotationTiltDirection(rotationTiltFilteredAxis, RotationTiltInputThreshold);
            if (!rotationTiltReady || tiltDirection == 0
                || tiltDirection != ResolveRotationTiltDirection(rawTiltAxis, RotationTiltInputThreshold))
            {
                ResetRotationTiltCandidate();
                PublishRotationTiltGateState();
                return false;
            }

            if (tiltDirection != rotationTiltCandidateDirection)
            {
                rotationTiltCandidateDirection = tiltDirection;
                rotationTiltCandidateSince = now;
                PublishRotationTiltGateState();
                return false;
            }

            if (!ShouldConfirmRotationTiltCandidate(
                tiltDirection,
                rotationTiltCandidateDirection,
                rotationTiltCandidateSince,
                now,
                RotationTiltConfirmationSeconds))
            {
                PublishRotationTiltGateState();
                return false;
            }

            if (!ShouldAcceptRotationTiltInputForValues(
                activeRotationPattern,
                runCore.IsPaused,
                rotationTiltReady,
                tiltDirection,
                rotationTiltHeldDirection,
                now,
                lastRotationTiltInputAt,
                RotationTiltRepeatBlockSeconds))
            {
                PublishRotationTiltGateState();
                return false;
            }

            rotationTiltReady = false;
            rotationTiltHeldDirection = tiltDirection;
            lastRotationTiltInputAt = now;
            ResetRotationTiltCandidate();
            PublishRotationTiltGateState();
            HandleRunChannelInput(tiltDirection < 0 ? GreedLastRunChannel.Left : GreedLastRunChannel.Right);
            return true;
        }

        private void UpdateRotationTiltGateForInactiveWindow(float rawTiltAxis, float filteredTiltAxis)
        {
            ResetRotationTiltCandidate();
            if (IsRotationTiltNeutralSample(rawTiltAxis, filteredTiltAxis))
            {
                rotationTiltReady = true;
                rotationTiltHeldDirection = 0;
                return;
            }

            int heldDirection = ResolveRotationTiltDirection(rawTiltAxis, RotationTiltInputThreshold);
            if (heldDirection == 0)
                heldDirection = ResolveRotationTiltDirection(filteredTiltAxis, RotationTiltInputThreshold);
            if (heldDirection != 0)
            {
                rotationTiltReady = false;
                rotationTiltHeldDirection = heldDirection;
            }
        }

        private void ResetRotationTiltCandidate()
        {
            rotationTiltCandidateDirection = 0;
            rotationTiltCandidateSince = -1f;
        }

        private void ResetRotationTiltSensorTracking(bool requireNeutralRelease)
        {
            rotationTiltFilteredAxis = 0f;
            rotationTiltAxisInitialized = false;
            rotationTiltOrientationMode = -1;
            lastRotationTiltSampleAt = -1f;
            rotationTiltReady = !requireNeutralRelease;
            rotationTiltHeldDirection = 0;
            ResetRotationTiltCandidate();
        }

        private static bool IsLiveRotationInputWindow(GreedLastRunSnapshot snapshot)
        {
            return snapshot.ActivePattern && !snapshot.Paused && !snapshot.CountdownActive
                && !snapshot.Stopped && !snapshot.ChoiceActive;
        }

        private static bool IsRotationTiltNeutralSample(float rawTiltAxis, float filteredTiltAxis)
        {
            return ShouldArmRotationTiltFromAcceleration(rawTiltAxis, RotationTiltReleaseThreshold)
                && ShouldArmRotationTiltFromAcceleration(filteredTiltAxis, RotationTiltReleaseThreshold);
        }

        private static int ResolveRotationTiltOrientationMode(
            ScreenOrientation screenOrientation,
            DeviceOrientation deviceOrientation)
        {
            switch (deviceOrientation)
            {
                case DeviceOrientation.Portrait:
                    return 0;
                case DeviceOrientation.PortraitUpsideDown:
                    return 1;
                case DeviceOrientation.LandscapeLeft:
                    return 2;
                case DeviceOrientation.LandscapeRight:
                    return 3;
            }

            switch (screenOrientation)
            {
                case ScreenOrientation.Portrait:
                    return 0;
                case ScreenOrientation.PortraitUpsideDown:
                    return 1;
                case ScreenOrientation.LandscapeLeft:
                    return 2;
                case ScreenOrientation.LandscapeRight:
                    return 3;
                default:
                    return -1;
            }
        }

        private static float ResolveCompensatedRotationTiltAxis(Vector3 acceleration)
        {
            return acceleration.x;
        }

        private static bool CanUseRotationTiltSensor(bool isMobilePlatform, bool supportsAccelerometer)
        {
            return isMobilePlatform && supportsAccelerometer;
        }

        private static bool CanUseRotationTiltSensorWithPreference(
            bool isMobilePlatform,
            bool supportsAccelerometer,
            bool rotationTiltEnabled)
        {
            return rotationTiltEnabled
                && CanUseRotationTiltSensor(isMobilePlatform, supportsAccelerometer);
        }

        private static bool IsRotationTiltAxisSampleValid(float axis)
        {
            return !float.IsNaN(axis) && !float.IsInfinity(axis);
        }

        private static float BuildRotationTiltFilteredAxis(
            float currentAxis,
            float rawAxis,
            float deltaTime,
            float filterSpeed,
            bool initialized)
        {
            if (!initialized || deltaTime <= 0f)
            {
                return rawAxis;
            }

            float blend = 1f - Mathf.Exp(-Mathf.Max(1f, filterSpeed) * Mathf.Max(0f, deltaTime));
            return Mathf.Lerp(currentAxis, rawAxis, blend);
        }

        private static bool ShouldConfirmRotationTiltCandidate(
            int tiltDirection,
            int candidateDirection,
            float candidateSince,
            float now,
            float confirmationSeconds)
        {
            return tiltDirection != 0
                && tiltDirection == candidateDirection
                && candidateSince >= 0f
                && now - candidateSince >= Mathf.Max(0.02f, confirmationSeconds);
        }

        private static float BuildRotationTiltCandidateProgress(
            int candidateDirection,
            float candidateSince,
            float now,
            float confirmationSeconds)
        {
            if (candidateDirection == 0 || candidateSince < 0f)
            {
                return 0f;
            }

            return Mathf.Clamp01(
                (now - candidateSince) / Mathf.Max(0.02f, confirmationSeconds));
        }

        private static float BuildRotationTiltNormalizedAxis(
            bool initialized,
            float filteredAxis,
            float inputThreshold)
        {
            if (!initialized)
            {
                return 0f;
            }

            return Mathf.Clamp(filteredAxis / Mathf.Max(0.05f, inputThreshold), -1.25f, 1.25f);
        }

        private static int ResolveRotationTiltDirection(float accelerationX, float inputThreshold)
        {
            float threshold = Mathf.Max(0.05f, inputThreshold);
            if (accelerationX <= -threshold)
            {
                return -1;
            }

            return accelerationX >= threshold ? 1 : 0;
        }

        private static bool ShouldArmRotationTiltFromAcceleration(float accelerationX, float releaseThreshold)
        {
            return Mathf.Abs(accelerationX) <= Mathf.Max(0.02f, releaseThreshold);
        }

        private static bool ShouldAcceptRotationTiltInputForValues(
            bool activeRotationPattern,
            bool paused,
            bool tiltReady,
            int tiltDirection,
            int heldDirection,
            float now,
            float lastInputAt,
            float repeatBlockSeconds)
        {
            if (!activeRotationPattern || paused || tiltDirection == 0 || !tiltReady)
            {
                return false;
            }

            float repeatBlock = Mathf.Max(0f, repeatBlockSeconds);
            if (heldDirection != 0
                && tiltDirection == heldDirection
                && now - lastInputAt < repeatBlock)
            {
                return false;
            }

            return now - lastInputAt >= repeatBlock;
        }

        private bool TryHandleRotationMouseDragInput()
        {
            if (!DevToolsEnabled)
            {
                ResetRotationDragTracking();
                return false;
            }

            bool activeRotationPattern = IsRunState()
                && hasLatestAppRunSnapshot
                && latestAppRunSnapshot.ActivePattern
                && GreedLastRunCore.IsRotationPattern(latestAppRunSnapshot.Pattern);
            if (!activeRotationPattern || runCore.IsPaused)
            {
                ResetRotationDragTracking();
                return false;
            }

            if (Input.GetMouseButtonDown(0))
            {
                if (runtimeUi == null || runtimeUi.IsPointerOverInteractiveUi(Input.mousePosition))
                {
                    ResetRotationDragTracking();
                    return false;
                }
                rotationDragTracking = true;
                rotationDragStartX = Input.mousePosition.x;
                rotationDragVisualAxis = 0f;
                rotationDragHeldDirection = 0;
                PublishRotationTiltGateState();
                return false;
            }

            if (!rotationDragTracking)
            {
                return false;
            }

            if (Input.GetMouseButtonUp(0) || !Input.GetMouseButton(0))
            {
                ResetRotationDragTracking();
                return false;
            }

            float dragDeltaX = Input.mousePosition.x - rotationDragStartX;
            rotationDragVisualAxis = BuildRotationDragNormalizedAxis(
                dragDeltaX,
                Screen.width,
                RotationDragInputThresholdNormalized);
            PublishRotationTiltGateState();
            int dragDirection = ResolveRotationDragDirection(
                dragDeltaX,
                Screen.width,
                RotationDragInputThresholdNormalized);
            float now = Time.realtimeSinceStartup;
            if (!ShouldAcceptRotationDragInputForValues(
                activeRotationPattern,
                runCore.IsPaused,
                dragDirection,
                rotationDragHeldDirection,
                now,
                lastRotationDragInputAt,
                RotationTiltRepeatBlockSeconds))
            {
                return false;
            }

            rotationDragTracking = false;
            rotationDragHeldDirection = dragDirection;
            lastRotationDragInputAt = now;
            rotationDragVisualAxis = 0f;
            PublishRotationTiltGateState();
            HandleRunChannelInput(dragDirection < 0 ? GreedLastRunChannel.Left : GreedLastRunChannel.Right);
            return true;
        }

        private void ResetRotationDragTracking()
        {
            bool hadVisualState = rotationDragTracking || !Mathf.Approximately(rotationDragVisualAxis, 0f);
            rotationDragTracking = false;
            rotationDragStartX = 0f;
            rotationDragVisualAxis = 0f;
            rotationDragHeldDirection = 0;
            if (hadVisualState)
            {
                PublishRotationTiltGateState();
            }
        }

        private static float BuildRotationDragNormalizedAxis(
            float deltaX,
            float screenWidth,
            float thresholdNormalized)
        {
            float threshold = BuildRotationDragPixelThreshold(screenWidth, thresholdNormalized);
            return Mathf.Clamp(deltaX / threshold, -1.25f, 1.25f);
        }

        private static float BuildRotationDragPixelThreshold(float screenWidth, float thresholdNormalized)
        {
            return Mathf.Max(18f, Mathf.Max(1f, screenWidth) * Mathf.Max(0.01f, thresholdNormalized));
        }

        private static int ResolveRotationDragDirection(
            float deltaX,
            float screenWidth,
            float thresholdNormalized)
        {
            float threshold = BuildRotationDragPixelThreshold(screenWidth, thresholdNormalized);
            if (deltaX <= -threshold)
            {
                return -1;
            }

            return deltaX >= threshold ? 1 : 0;
        }

        private static bool ShouldAcceptRotationDragInputForValues(
            bool activeRotationPattern,
            bool paused,
            int dragDirection,
            int heldDirection,
            float now,
            float lastInputAt,
            float repeatBlockSeconds)
        {
            if (!activeRotationPattern || paused || dragDirection == 0)
            {
                return false;
            }

            float repeatBlock = Mathf.Max(0f, repeatBlockSeconds);
            if (heldDirection != 0
                && dragDirection == heldDirection
                && now - lastInputAt < repeatBlock)
            {
                return false;
            }

            return now - lastInputAt >= repeatBlock;
        }

        private bool TryHandleLaneKeyboardInput()
        {
            GreedLastRunChannel channel = ReadPressedLaneKeyboardChannel();
            if (channel == GreedLastRunChannel.None) return false;
            HandleRunChannelInput(channel);
            return true;
        }

        private static GreedLastRunChannel ReadPressedLaneKeyboardChannel()
        {
            if (Input.GetKeyDown(KeyCode.A)
                || Input.GetKeyDown(KeyCode.J)
                || Input.GetKeyDown(KeyCode.Alpha1)
                || Input.GetKeyDown(KeyCode.Keypad1)
                || Input.GetKeyDown(KeyCode.LeftArrow))
            {
                return GreedLastRunChannel.Left;
            }
            else if (Input.GetKeyDown(KeyCode.S)
                || Input.GetKeyDown(KeyCode.K)
                || Input.GetKeyDown(KeyCode.Alpha2)
                || Input.GetKeyDown(KeyCode.Keypad2)
                || Input.GetKeyDown(KeyCode.W)
                || Input.GetKeyDown(KeyCode.Space)
                || Input.GetKeyDown(KeyCode.UpArrow)
                || Input.GetKeyDown(KeyCode.DownArrow))
            {
                return GreedLastRunChannel.Center;
            }
            else if (Input.GetKeyDown(KeyCode.D)
                || Input.GetKeyDown(KeyCode.L)
                || Input.GetKeyDown(KeyCode.Alpha3)
                || Input.GetKeyDown(KeyCode.Keypad3)
                || Input.GetKeyDown(KeyCode.RightArrow))
            {
                return GreedLastRunChannel.Right;
            }

            return GreedLastRunChannel.None;
        }

        private bool TryHandleDevKeyboardInput()
        {
            if (!DevToolsEnabled)
            {
                return false;
            }

            if (Input.GetKeyDown(KeyCode.F11))
            {
                runtimeUi.ToggleDevCleanView();
                return true;
            }

            bool runState = IsRunState();
            bool stateDevTools = stateMachine.CurrentState == GreedLastScreenState.LobbyReady
                || stateMachine.CurrentState == GreedLastScreenState.GrowthBoard;
            if (!runState && !stateDevTools)
            {
                return false;
            }

            if (runState && Input.GetKeyDown(KeyCode.F1))
            {
                ToggleRunInvincible();
                return true;
            }

            if (runState && Input.GetKeyDown(KeyCode.F2))
            {
                RequestRunDevShortcut(GreedLastDevShortcut.GiftChoice);
                return true;
            }

            if (runState && Input.GetKeyDown(KeyCode.F3))
            {
                RequestRunDevShortcut(GreedLastDevShortcut.RelicChoice);
                return true;
            }

            if (runState && Input.GetKeyDown(KeyCode.F4))
            {
                RequestRunDevShortcut(GreedLastDevShortcut.AfterCore);
                return true;
            }

            if (runState && Input.GetKeyDown(KeyCode.F5))
            {
                RequestRunDevShortcut(GreedLastDevShortcut.BeforeClear);
                return true;
            }

            if (Input.GetKeyDown(KeyCode.F6))
            {
                RequestFocusMaxForTest();
                return true;
            }

            if (runState && Input.GetKeyDown(KeyCode.F7))
            {
                RequestRunDevShortcut(GreedLastDevShortcut.ReviewTargetCheck);
                return true;
            }

            if (runState && Input.GetKeyDown(KeyCode.F8))
            {
                RequestRunDevShortcut(GreedLastDevShortcut.RouteCycle);
                return true;
            }

            if (runState && Input.GetKeyDown(KeyCode.F9))
            {
                RequestRunDevShortcut(GreedLastDevShortcut.AvoidanceCycle);
                return true;
            }

            if (runState && Input.GetKeyDown(KeyCode.F10))
            {
                RequestRunDevShortcut(GreedLastDevShortcut.VisualDropPreview);
                return true;
            }

            if (Input.GetKeyDown(KeyCode.PageUp))
            {
                RequestThreatUpForTest();
                return true;
            }

            if (Input.GetKeyDown(KeyCode.PageDown))
            {
                RequestThreatDownForTest();
                return true;
            }

            if (runState && Input.GetKeyDown(KeyCode.End))
            {
                RequestInfiniteTestStop();
                return true;
            }

            return false;
        }

        private bool TryHandlePauseOrBackKeyboardInput(bool backPressed, bool pausePressed)
        {
            if (!backPressed && !pausePressed) return false;
            // A gameplay key sampled before the new pause/result is visible cannot act on that screen.
            if (HasUnpresentedScreenTransition || HasUnpresentedRunCommandTransition) return true;
            if (backPressed && TryHandleBackKeyboardInput()) return true;
            if (!IsRunState()) return false;
            runtimeUi?.CancelPendingUiInput();
            RequestToggleRunPause();
            return true;
        }

        private bool TryHandleBackKeyboardInput()
        {
            if (IsRunState() && hasLatestAppRunSnapshot && latestAppRunSnapshot.Stopped)
            {
                runtimeUi?.CancelPendingUiInput();
                // A back key must not silently discard a clear's one-time save opportunity.
                if (runCore.CanExitAfterClear) RequestNextRunPattern();
                else RequestReturnToLobby();
                return true;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.SaveLoadoutDraft
                || stateMachine.CurrentState == GreedLastScreenState.InfiniteLoadoutSelect
                || stateMachine.CurrentState == GreedLastScreenState.InfiniteRecordBoard
                || stateMachine.CurrentState == GreedLastScreenState.InfiniteStartReady
                || stateMachine.CurrentState == GreedLastScreenState.GrowthBoard
                || stateMachine.CurrentState == GreedLastScreenState.ProfileBoard)
            {
                runtimeUi?.CancelPendingUiInput();
                RequestReturnToLobby();
                return true;
            }

            return false;
        }

        private void OnApplicationPause(bool pauseStatus)
        {
            bool wasPaused = applicationPaused;
            applicationPaused = pauseStatus;
            RefreshPlayerInputAvailability();
            if (pauseStatus && !applicationQuitting) PersistTerminalRunResult();
            ResetRotationDragTracking();
            ResetRotationTiltSensorTracking(requireNeutralRelease: true);
            PublishRotationTiltGateState();
            if (pauseStatus && PauseRunForAppBackground())
            {
                return;
            }

            if (!pauseStatus
                && wasPaused
                && stateMachine != null
                && (stateMachine.CurrentState == GreedLastScreenState.LobbyReady
                    || (stateMachine.CurrentState == GreedLastScreenState.ReSyncPending && stateMachine.CoreActionsEnabled)))
            {
                stateMachine.SetReSyncPending("앱 복귀 후 최신 로비 상태를 다시 확인해야 합니다.", coreActionsEnabled: false);
            }
        }

        private void OnApplicationFocus(bool hasFocus)
        {
            applicationHasFocus = hasFocus;
            RefreshPlayerInputAvailability();
            ResetRotationDragTracking();
            ResetRotationTiltSensorTracking(requireNeutralRelease: true);
            PublishRotationTiltGateState();
            if (!hasFocus)
            {
                if (!applicationQuitting) PersistTerminalRunResult();
                PauseRunForAppBackground();
            }
        }

        private bool CanAcceptPlayerInput()
        {
            return !applicationQuitting && isActiveAndEnabled && applicationHasFocus && !applicationPaused
                && runtimeUi != null && runtimeUi.AcceptsPlayerInput;
        }

        private void RefreshPlayerInputAvailability()
        {
            runtimeUi?.SetAppInputAvailable(!applicationQuitting && isActiveAndEnabled && applicationHasFocus && !applicationPaused);
        }

        private bool PauseRunForAppBackground()
        {
            if (stateMachine == null || runCore == null || !IsRunState())
            {
                return false;
            }

            float now = Time.realtimeSinceStartup;
            if (!runCore.PauseForInterruptedFrame(now)) runCore.PauseForAppBackground(now);
            return true;
        }

        private IEnumerator BootThenConnect()
        {
            if (!requestGate.TryBegin(GreedLastRequestKind.BootInit, out GreedLastRequestToken token))
            {
                yield break;
            }

            stateMachine.SetBoot("로컬 설정을 준비하는 중입니다.");
            yield return new WaitForSecondsRealtime(BootBrandHoldSeconds);
            requestGate.Complete(token);
            yield return ConnectThenLoadLobby();
        }

        private IEnumerator ConnectThenLoadLobby()
        {
            if (!requestGate.TryBegin(GreedLastRequestKind.ConnectCheck, out GreedLastRequestToken connectToken))
            {
                yield break;
            }

            stateMachine.SetConnectChecking();
            yield return new WaitForSecondsRealtime(0.45f);

            GreedLastConnectResult result = backend.CheckConnect();
            if (!requestGate.IsCurrent(connectToken))
            {
                yield break;
            }

            requestGate.Complete(connectToken);

            if (!result.Success)
            {
                stateMachine.SetConnectBlocked(result.Reason, result.Message);
                yield break;
            }

            yield return LoadLobby();
        }

        private IEnumerator LoadLobby()
        {
            if (!requestGate.TryBegin(GreedLastRequestKind.LobbySync, out GreedLastRequestToken token))
            {
                yield break;
            }

            stateMachine.SetLobbyLoading();
            yield return new WaitForSecondsRealtime(0.45f);

            GreedLastLobbySnapshot snapshot = backend.LoadLobby();
            if (!requestGate.IsCurrent(token))
            {
                yield break;
            }

            requestGate.Complete(token);

            if (snapshot.AuxiliaryWarning)
            {
                stateMachine.SetLobbySyncWarning(snapshot);
            }
            else
            {
                stateMachine.SetLobbyReady(snapshot);
            }
        }

        private void RequestRetrySync()
        {
            if (!CanSyncLobby())
            {
                return;
            }

            StartCoroutine(RetrySyncRoutine());
        }

        private IEnumerator RetrySyncRoutine()
        {
            if (!CanSyncLobby() || !requestGate.TryBegin(GreedLastRequestKind.ReSync, out GreedLastRequestToken token))
            {
                yield break;
            }

            stateMachine.SetReSyncPending("최신 로비 상태를 다시 확인하고 있습니다.", coreActionsEnabled: false);
            yield return new WaitForSecondsRealtime(0.4f);

            GreedLastConnectResult connectResult = backend.CheckConnect();
            if (!requestGate.IsCurrent(token))
            {
                yield break;
            }

            if (!connectResult.Success)
            {
                requestGate.Complete(token);

                if (stateMachine.CurrentState == GreedLastScreenState.LobbyReady
                    || stateMachine.CurrentState == GreedLastScreenState.ReSyncPending)
                {
                    stateMachine.SetReSyncPending(connectResult.Message, coreActionsEnabled: false, blockReason: connectResult.Reason);
                }
                else
                {
                    stateMachine.SetConnectBlocked(connectResult.Reason, connectResult.Message);
                }

                yield break;
            }

            GreedLastLobbySnapshot snapshot = backend.ReSyncLobby();
            requestGate.Complete(token);
            if (snapshot.AuxiliaryWarning)
            {
                stateMachine.SetLobbySyncWarning(snapshot);
            }
            else
            {
                stateMachine.SetLobbyReady(snapshot);
            }
        }

        private void RequestNormalRun()
        {
            if (backend.HasSaveLoadoutCandidate)
            {
                RequestSaveLoadout();
                return;
            }

            if (!TryBeginLobbyAction(out GreedLastRequestToken token))
            {
                return;
            }

            requestGate.Complete(token);
            GreedLastLobbySnapshot snapshot = backend.LoadLobby();
            bool refillRun = ShouldStartLobbyNormalAsRefillRun(snapshot);
            string openingContext = refillRun
                ? BuildRefillRunOpeningContext(stateMachine.CurrentDetail)
                : BuildNormalRunOpeningContextFromLobbyDetail(stateMachine.CurrentDetail);
            StartNormalRunCore(openingContext, refillRun);
        }

        private void RequestPracticeRun()
        {
            if (!TryBeginLobbyAction(out GreedLastRequestToken token))
            {
                return;
            }

            string openingContext = BuildPracticeOpeningContextFromLobbyDetail(stateMachine.CurrentDetail);
            requestGate.Complete(token);
            activeNormalRunWasRefill = false;
            ClearInfinitePreparationContext();
            runEntryLaneInputBlockUntil = Time.realtimeSinceStartup + RunEntryLaneInputBlockSeconds;
            stateMachine.SetRunCoreTest();
            runCore.ConfigureGrowth(0, 0, 0);
            ResetRunLaneInputGuard();
            runEntryLaneInputBlockUntil = Time.realtimeSinceStartup + RunEntryLaneInputBlockSeconds;
            runCore.EnterPractice(openingContext);
            runEntryLaneInputBlockUntil = Time.realtimeSinceStartup + RunEntryLaneInputBlockSeconds;
        }

        private void StartNormalRunCore(string openingContext, bool refillRun)
        {
            runEntryLaneInputBlockUntil = Time.realtimeSinceStartup + RunEntryLaneInputBlockSeconds;
            activeNormalRunWasRefill = refillRun;
            ClearInfinitePreparationContext();
            stateMachine.SetRunCoreTest();
            ApplyGrowthToRunCore();
            ResetRunLaneInputGuard();
            runCore.Enter(openingContext, refillRun);
            runEntryLaneInputBlockUntil = Time.realtimeSinceStartup + RunEntryLaneInputBlockSeconds;
        }

        private void RequestSaveLoadout()
        {
            if (!CanAcceptPlayerInput()) return;
            if (stateMachine.CurrentState == GreedLastScreenState.InfiniteStartReady)
            {
                saveSlotDeleteConfirmPending = false;
                saveSlotDetailViewActive = false;
                saveSlotRenameConfirmPending = false;
                stateMachine.SetInfiniteLoadoutSelect(backend.LoadLobby(), backend.BuildInfiniteLoadoutSelectText());
                return;
            }

            if (!TryBeginLobbyAction(out GreedLastRequestToken token))
            {
                return;
            }

            GreedLastLobbySnapshot snapshot = stateMachine.LobbySnapshot;
            requestGate.Complete(token);

            if (snapshot.SaveLoadoutUnlocked)
            {
                pendingRefillRunReviewContext = ShouldStartLobbyNormalAsRefillRun(snapshot)
                    ? BuildNormalRunOpeningContextFromLobbyDetail(stateMachine.CurrentDetail)
                    : string.Empty;
                string noCandidateNotice = HasAnyUsableSaveSlot(snapshot)
                    ? "저장할 새 클리어 후보는 없습니다.\n기존 저장 슬롯은 여기서 관리할 수 있습니다."
                    : "저장 조합이 비어 있습니다.\n무한 조합 보충 또는 보충 런으로 새 후보를 만든 뒤 저장하세요.";
                if (!string.IsNullOrEmpty(pendingRefillRunReviewContext))
                    noCandidateNotice = pendingRefillRunReviewContext + "\n\n" + noCandidateNotice;
                OpenSaveLoadoutDraft(
                    snapshot,
                    requireExplicitSlotChoice: backend.HasSaveLoadoutCandidate,
                    backend.HasSaveLoadoutCandidate
                        ? null
                        : noCandidateNotice,
                    refillRunCandidate: false);
            }
            else
            {
                stateMachine.ShowLocalNotice("저장할 새 클리어 후보가 없습니다.\n일반 런을 다시 클리어하면 새 저장 기회가 생깁니다.");
            }
        }

        private void RequestInfiniteRun()
        {
            if (!TryBeginLobbyAction(out GreedLastRequestToken token))
            {
                return;
            }

            GreedLastLobbySnapshot snapshot = stateMachine.LobbySnapshot;
            requestGate.Complete(token);

            if (snapshot.SaveLoadoutCandidateAvailable)
            {
                RequestSaveLoadout();
                return;
            }

            if (!snapshot.InfiniteUnlocked)
            {
                if (snapshot.SaveLoadoutUnlocked || snapshot.FirstSaveCompleted)
                {
                    OpenInfinitePreparation();
                    return;
                }

                stateMachine.ShowLocalNotice("무한모드는 저장 조합 저장 뒤 열립니다.");
                return;
            }

            OpenInfinitePreparation();
        }

        private void OpenInfinitePreparation(string notice = null, bool resetPreparation = true)
        {
            GreedLastLobbySnapshot lobby = backend.LoadLobby();
            bool settledResultNotice = notice != null
                && (notice.StartsWith("무한 기록 저장", StringComparison.Ordinal)
                    || notice.StartsWith("무한모드 기록이 없습니다.", StringComparison.Ordinal));
            if (resetPreparation)
            {
                ResetInfinitePreparation();
                pendingInfinitePreparationResultNotice = settledResultNotice ? notice : string.Empty;
                // Direct settlement still has the previous run's screen detail, not its new result.
                string contextDetail = settledResultNotice ? notice : stateMachine.CurrentDetail;
                pendingInfinitePreparationReviewContext = BuildInfinitePreparationReviewContextFromLobbyDetail(contextDetail);
                pendingInfinitePreparationEntryNotice = BuildInfinitePreparationEntryNoticeFromLobbyDetail(contextDetail);
                pendingRefillRunReviewContext = !HasAnyUsableSaveSlot(lobby)
                    ? BuildNormalRunOpeningContextFromLobbyDetail(contextDetail)
                    : string.Empty;
            }

            string detail = backend.BuildInfiniteStartReadyText(infinitePreparationGift, infinitePreparationRelic);
            string entryNotice = pendingInfinitePreparationEntryNotice;
            if (!string.IsNullOrEmpty(entryNotice))
            {
                detail = entryNotice + "\n\n" + detail;
            }

            string reviewContext = pendingInfinitePreparationReviewContext;
            if (!string.IsNullOrEmpty(reviewContext))
            {
                detail = reviewContext + "\n\n" + detail;
            }

            if (!HasAnyUsableSaveSlot(lobby) && !string.IsNullOrEmpty(pendingRefillRunReviewContext))
            {
                detail = pendingRefillRunReviewContext + "\n\n" + detail;
            }

            if (IsSelectedSaveSlotUsable(lobby))
            {
                detail = BuildInfinitePreparationDetail().TrimStart() + "\n\n" + detail;
            }

            if (!string.IsNullOrEmpty(notice) && !settledResultNotice)
            {
                detail = notice + "\n\n" + detail;
            }

            if (!string.IsNullOrEmpty(pendingInfinitePreparationResultNotice))
            {
                detail += "\n\n" + pendingInfinitePreparationResultNotice;
            }

            infinitePreparationInputBlockUntil = Time.realtimeSinceStartup + RunChoiceTransitionInputBlockSeconds;
            stateMachine.SetInfiniteStartReady(lobby, detail);
            // Preserve the full guard after synchronous layout work, including a slow first presentation.
            infinitePreparationInputBlockUntil = Time.realtimeSinceStartup + RunChoiceTransitionInputBlockSeconds;
        }

        private string BuildInfinitePreparationDetail()
        {
            return BuildInfinitePreparationDetailForStep(infinitePreparationStep, infinitePreparationGift, infinitePreparationRelic);
        }

        public static string BuildInfinitePreparationDetailForStep(int step, string gift, string relic)
        {
            switch (step)
            {
                case 0:
                    return "\n\n시작 정비 1/2 · 기프트 정비 선택"
                        + "\n좌 생존 축 / 중 집중 축 / 우 연쇄 축"
                        + "\n선택 전에는 사용 횟수가 차감되지 않습니다.";
                case 1:
                    return "\n\n시작 정비 2/2 · 유물 정비 선택"
                        + "\n기프트 정비: " + gift
                        + "\n좌 사막의 잔상 / 중 황금 박동 / 우 파라오의 각인";
                default:
                    return "\n\n시작 정비 완료"
                        + "\n기프트: " + gift
                        + " / 유물: " + relic
                        + "\n이제 시작 확정 시에만 사용 횟수 1회가 차감됩니다."
                        + "\n좌 기프트 다시 / 중 유물 다시 / 우 선택 유지";
            }
        }

        private void SelectInfinitePreparation(GreedLastRunChannel channel)
        {
            if (Time.realtimeSinceStartup < infinitePreparationInputBlockUntil)
            {
                return;
            }

            GreedLastLobbySnapshot lobby = backend.LoadLobby();
            if (!IsSelectedSaveSlotUsable(lobby))
            {
                OpenInfinitePreparation("사용 가능한 저장 조합을 먼저 준비하세요.", resetPreparation: false);
                return;
            }

            runtimeUi.CancelPendingUiInput();
            int choiceIndex = Mathf.Clamp((int)channel - 1, 0, 2);
            if (infinitePreparationStep <= 0)
            {
                infinitePreparationGift = InfinitePreparationGifts[choiceIndex];
                infinitePreparationStep = 1;
                OpenInfinitePreparation(infinitePreparationGift + " 정비 선택 완료", resetPreparation: false);
                return;
            }

            if (infinitePreparationStep == 1)
            {
                infinitePreparationRelic = InfinitePreparationRelics[choiceIndex];
                infinitePreparationStep = 2;
                OpenInfinitePreparation(infinitePreparationRelic + " 정비 선택 완료", resetPreparation: false);
                return;
            }

            if (channel == GreedLastRunChannel.Left)
            {
                ResetInfinitePreparation();
                OpenInfinitePreparation("기프트 정비부터 다시 선택합니다.", resetPreparation: false);
            }
            else if (channel == GreedLastRunChannel.Center)
            {
                infinitePreparationRelic = string.Empty;
                infinitePreparationStep = 1;
                OpenInfinitePreparation("유물 정비를 다시 선택합니다.", resetPreparation: false);
            }
            else if (channel == GreedLastRunChannel.Right)
            {
                OpenInfinitePreparation("현재 정비 선택을 유지합니다.", resetPreparation: false);
            }
        }

        private void ResetInfinitePreparation()
        {
            infinitePreparationInputBlockUntil = 0f;
            infinitePreparationStep = 0;
            infinitePreparationGift = string.Empty;
            infinitePreparationRelic = string.Empty;
        }

        private void ClearInfinitePreparationContext()
        {
            pendingInfinitePreparationReviewContext = string.Empty;
            pendingInfinitePreparationEntryNotice = string.Empty;
            pendingInfinitePreparationResultNotice = string.Empty;
            pendingRefillRunReviewContext = string.Empty;
        }

        private void StartInfiniteRunFromSelectedLoadout(string failedNotice = null)
        {
            if (!backend.TryConsumeSelectedSaveLoadout(out GreedLastRunRecord selectedLoadout, out string runDetail,
                    out string errorMessage, infinitePreparationGift, infinitePreparationRelic))
            {
                runCore.Exit();
                string detail = errorMessage;
                if (!string.IsNullOrEmpty(failedNotice))
                {
                    detail = failedNotice + "\n" + detail;
                }

                OpenInfinitePreparation(detail, resetPreparation: false);
                return;
            }

            GreedLastRunRecord preparedLoadout = GreedLastRunCore.CreatePreparedInfiniteLoadout(
                selectedLoadout,
                infinitePreparationGift,
                infinitePreparationRelic);
            runDetail += "\n시작 정비: " + infinitePreparationGift + " / " + infinitePreparationRelic;
            string reviewContext = pendingInfinitePreparationReviewContext;
            stateMachine.SetInfiniteRun(runDetail);
            activeNormalRunWasRefill = false;
            ApplyGrowthToRunCore();
            ResetRunLaneInputGuard();
            runCore.EnterInfiniteRun(preparedLoadout, reviewContext);
            ResetInfinitePreparation();
            ClearInfinitePreparationContext();
        }

        private void RequestGrowthBoard()
        {
            if (!TryBeginLobbyAction(out GreedLastRequestToken token))
            {
                return;
            }

            requestGate.Complete(token);
            lastGrowthUpgradeChannel = GreedLastRunChannel.None;
            lastGrowthUpgradeAt = 0f;
            stateMachine.SetGrowthBoard(backend.LoadLobby(), backend.BuildGrowthBoardText());
        }

        private void RequestProfileBoard()
        {
            if (!TryBeginLobbyAction(out GreedLastRequestToken token))
            {
                return;
            }

            requestGate.Complete(token);
            GreedLastLobbySnapshot snapshot = backend.LoadLobby();
            OpenProfileBoard(ResolveProfileBoardOpeningPage(snapshot), markSeen: true);
        }

        private static int ResolveProfileBoardOpeningPage(GreedLastLobbySnapshot snapshot)
        {
            if (snapshot.SaveLoadoutCandidateAvailable
                || ((snapshot.FirstSaveCompleted || snapshot.SaveLoadoutUnlocked) && !HasAnyUsableSaveSlot(snapshot)))
            {
                return 1;
            }

            if (snapshot.ProfileButtonSummary.Contains("성장", StringComparison.Ordinal))
            {
                return 1;
            }

            return 0;
        }

        private void ApplyGrowthToRunCore()
        {
            runCore.ConfigureGrowth(
                backend.GrowthSurvivalLevel,
                backend.GrowthFocusLevel,
                backend.GrowthTimingLevel);
        }

        private void RequestInfiniteRecordBoard()
        {
            if (!TryBeginLobbyAction(out GreedLastRequestToken token))
            {
                return;
            }

            requestGate.Complete(token);
            int targetPage = ResolveRecordBoardPageForCurrentLobby();
            OpenRecordBoard(
                targetPage,
                markProfileSeen: ShouldMarkProfileSeenFromRecordRequest(stateMachine.CurrentDetail));
        }

        private int ResolveRecordBoardPageForCurrentLobby()
        {
            return ResolveRecordBoardPageForLobbyDetail(
                stateMachine.CurrentDetail,
                preferredRecordBoardPageIndex,
                backend.RecordBoardPages);
        }

        internal static int ResolveRecordBoardPageForLobbyDetail(string detail, int preferredPageIndex, int recordBoardPageCount)
        {
            string safeDetail = detail ?? string.Empty;
            int safePageCount = Mathf.Max(1, recordBoardPageCount);
            if (IsPrototypeCompletionRecordRequestDetail(safeDetail))
            {
                return 0;
            }

            if (IsNormalRecordResultDetail(safeDetail))
            {
                return Mathf.Clamp(1, 0, safePageCount - 1);
            }

            if (IsInfiniteRecordResultDetail(safeDetail))
            {
                return Mathf.Clamp(2, 0, safePageCount - 1);
            }

            return Mathf.Clamp(preferredPageIndex, 0, safePageCount - 1);
        }

        private static bool ShouldMarkProfileSeenFromRecordRequest(string detail)
        {
            return IsPrototypeCompletionRecordRequestDetail(detail);
        }

        internal static bool IsPrototypeCompletionRecordRequestDetail(string detail)
        {
            if (string.IsNullOrEmpty(detail))
            {
                return false;
            }

            string trimmedDetail = detail.Trim();
            return trimmedDetail.Equals("완성 기록", StringComparison.Ordinal)
                || trimmedDetail.Equals("완성 기록 확인", StringComparison.Ordinal)
                || trimmedDetail.Equals("완성 루프 기록 확인", StringComparison.Ordinal)
                || detail.Contains("다음 확인: 완성 루프 기록", StringComparison.Ordinal)
                || detail.Contains("다음: 완성 루프 기록", StringComparison.Ordinal)
                || ContainsNextDirectiveAlias(detail, "완성 기록")
                || ContainsNextDirectiveAlias(detail, "완성 기록 확인")
                || ContainsNextDirectiveAlias(detail, "기록 보기 - 완성 루프 기록 확인")
                || ContainsNextDirectiveAlias(detail, "기록 보기 - 완성 루프 기록")
                || ContainsNextDirectiveAlias(detail, "기록 보기 - 완성 기록 확인")
                || ContainsNextDirectiveAlias(detail, "기록 보기 - 완성 기록")
                || ContainsNextDirectiveAlias(detail, "기록 보드 - 완성 루프 기록 확인")
                || ContainsNextDirectiveAlias(detail, "기록 보드 - 완성 루프 기록")
                || ContainsNextDirectiveAlias(detail, "기록 보드 - 완성 기록 확인")
                || ContainsNextDirectiveAlias(detail, "기록 보드 - 완성 기록")
                || ContainsActionDirectiveAlias(detail, "완성 기록")
                || ContainsActionDirectiveAlias(detail, "완성 기록 확인")
                || ContainsActionDirectiveAlias(detail, "기록 보기 - 완성 루프 기록 확인")
                || ContainsActionDirectiveAlias(detail, "기록 보기 - 완성 루프 기록")
                || ContainsActionDirectiveAlias(detail, "기록 보기 - 완성 기록 확인")
                || ContainsActionDirectiveAlias(detail, "기록 보기 - 완성 기록")
                || ContainsActionDirectiveAlias(detail, "기록 보드 - 완성 루프 기록 확인")
                || ContainsActionDirectiveAlias(detail, "기록 보드 - 완성 루프 기록")
                || ContainsActionDirectiveAlias(detail, "기록 보드 - 완성 기록 확인")
                || ContainsActionDirectiveAlias(detail, "기록 보드 - 완성 기록");
        }

        private static string BuildLobbyRecordButtonLabel(string detail)
        {
            if (string.IsNullOrEmpty(detail))
            {
                return "기록 보기";
            }

            if (IsRefillRecordResultDetail(detail))
            {
                return "보충 기록";
            }

            if (HasLineStartingWith(detail, "탈출 성공 / 기록 저장")
                || IsEntranceExitRecordResultDetail(detail)
                || IsClearSummaryRecordResultDetail(detail))
            {
                return "클리어 복기";
            }

            if (detail.Contains("저장 조합 슬롯에는 저장하지 않았습니다.", StringComparison.Ordinal))
            {
                return "클리어 복기";
            }

            if (HasLineStartingWith(detail, "탈출 실패 기록 저장")
                || HasLineStartingWith(detail, "탈출 중단 기록 저장"))
            {
                return "복기 기록";
            }

            if (IsInfiniteRecordResultDetail(detail))
            {
                return "무한 복기";
            }

            if (IsPrototypeCompletionRecordRequestDetail(detail))
            {
                return "완성 기록";
            }

            return "기록 보기";
        }

        private bool TryBeginLobbyAction(out GreedLastRequestToken token)
        {
            if (!CanAcceptPlayerInput() || !stateMachine.CoreActionsEnabled
                || (stateMachine.CurrentState != GreedLastScreenState.LobbyReady
                    && stateMachine.CurrentState != GreedLastScreenState.ReSyncPending))
            {
                token = default;
                return false;
            }

            return requestGate.TryBegin(GreedLastRequestKind.LobbyAction, out token);
        }

        private void ToggleOfflineForEditorCheck()
        {
            if (!DevToolsEnabled || !CanSyncLobby())
            {
                return;
            }

            bool online = backend.ToggleOfflineForEditorCheck();
            if (online)
            {
                StartCoroutine(RetrySyncRoutine());
            }
            else
            {
                stateMachine.SetReSyncPending("개발 확인용으로 네트워크 OFF 상태가 되었습니다.", coreActionsEnabled: false,
                    blockReason: GreedLastConnectBlockReason.NetworkUnavailable);
            }
        }

        private bool CanSyncLobby()
        {
            return stateMachine != null && requestGate != null && !requestGate.Busy
                && (stateMachine.CurrentState == GreedLastScreenState.LobbyReady
                    || stateMachine.CurrentState == GreedLastScreenState.ReSyncPending
                    || stateMachine.CurrentState == GreedLastScreenState.ConnectBlocked);
        }

        private void RequestNextRunPattern()
        {
            if (!CanAcceptPlayerInput()) return;
            if (stateMachine.CurrentState == GreedLastScreenState.InfiniteRecordBoard)
            {
                MoveRecordBoardPage(1);
                return;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.ProfileBoard)
            {
                MoveProfileBoardPage(1);
                return;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.GrowthBoard)
            {
                UpgradeRecommendedGrowthTrack();
                return;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.InfiniteStartReady)
            {
                if (Time.realtimeSinceStartup < infinitePreparationInputBlockUntil) return;
                GreedLastLobbySnapshot visibleLobbySnapshot = stateMachine.LobbySnapshot;
                if (ShouldOpenRecommendedSlotBeforeInfiniteStart(visibleLobbySnapshot))
                {
                    backend.SelectBestUsableSaveLoadoutSlotForInfiniteEntry(out string autoSelectNotice);
                    OpenInfinitePreparation(autoSelectNotice, resetPreparation: false);
                    return;
                }

                if (!IsSelectedSaveSlotUsable(visibleLobbySnapshot))
                {
                    StartNormalRunCore(
                        BuildRefillRunOpeningContext(pendingRefillRunReviewContext),
                        refillRun: true);
                    return;
                }

                if (infinitePreparationStep < 2)
                {
                    string notice = infinitePreparationStep <= 0
                        ? "좌 · 중 · 우에서 기프트 정비를 먼저 선택하세요."
                        : "좌 · 중 · 우에서 유물 정비를 선택하세요.";
                    OpenInfinitePreparation(notice, resetPreparation: false);
                    return;
                }

                StartInfiniteRunFromSelectedLoadout();
                return;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.InfiniteLoadoutSelect)
            {
                if (saveSlotDeleteConfirmPending || saveSlotRenameConfirmPending)
                {
                    RefreshInfiniteLoadoutPendingConfirmation(saveSlotDeleteConfirmPending
                        ? "삭제 확인 중입니다. 삭제 확정 또는 다른 작업을 선택하세요."
                        : "이름 확인 중입니다. 이름 확정 또는 다른 작업을 선택하세요.");
                    return;
                }

                saveSlotDeleteConfirmPending = false;
                saveSlotDetailViewActive = false;
                saveSlotRenameConfirmPending = false;
                if (!IsSelectedSaveSlotUsable(stateMachine.LobbySnapshot))
                {
                    if (!HasAnyUsableSaveSlot(stateMachine.LobbySnapshot))
                    {
                        StartNormalRunCore(
                            GreedLastApp.BuildRefillRunOpeningContext(pendingRefillRunReviewContext),
                            refillRun: true);
                        return;
                    }

                    backend.SelectBestUsableSaveLoadoutSlotForInfiniteEntry(out string autoSelectNotice);
                    OpenInfinitePreparation(autoSelectNotice, resetPreparation: false);
                    return;
                }

                OpenInfinitePreparation(resetPreparation: false);
                return;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.SaveLoadoutDraft)
            {
                GreedLastLobbySnapshot lobbySnapshot = stateMachine.LobbySnapshot;
                if (!backend.HasSaveLoadoutCandidate
                    && (lobbySnapshot.FirstSaveCompleted || lobbySnapshot.SaveLoadoutUnlocked)
                    && !HasAnyUsableSaveSlot(lobbySnapshot))
                {
                    StartNormalRunCore(
                        GreedLastApp.BuildRefillRunOpeningContext(pendingRefillRunReviewContext),
                        refillRun: true);
                    return;
                }

                ConfirmSaveLoadoutAndReturn();
                return;
            }

            if (IsRunState())
            {
                float now = Time.realtimeSinceStartup;
                // A queued primary command must not bypass interruption recovery.
                if (runCore.PauseForInterruptedFrame(now))
                {
                    HandlePresentationSuspended();
                    return;
                }
                if (runCore.IsPaused)
                {
                    runCore.TogglePause(Time.realtimeSinceStartup);
                    return;
                }

                if (runCore.CanExitAfterClear)
                {
                    CompleteClearAndOpenSaveDraft();
                    return;
                }

                if (runCore.CanExitAfterPractice)
                {
                    bool practicePreviouslyCompleted = PlayerPrefs.GetInt(PracticeCompletedPrefsKey, 0) == 1;
                    bool continueToFirstNormalRun = hasLatestAppRunSnapshot
                        && ShouldContinuePracticeToFirstNormal(
                            latestAppRunSnapshot,
                            practicePreviouslyCompleted);
                    if (continueToFirstNormalRun)
                    {
                        MarkPracticeCompletedIfNeeded();
                        runCore.Exit();
                        if (backend.HasSaveLoadoutCandidate)
                        {
                            OpenSaveLoadoutDraft(backend.LoadLobby(), requireExplicitSlotChoice: true,
                                notice: "기초연습 완료\n이전 클리어의 저장 후보가 남아 있습니다.");
                            return;
                        }
                        StartNormalRunCore(BuildFirstNormalRunOpeningContext(), refillRun: false);
                        return;
                    }

                    runCore.RestartPractice(Time.realtimeSinceStartup);
                    return;
                }

                if (runCore.IsStoppedInfiniteRun)
                {
                    GreedLastInfiniteRunRecord record = runCore.CreateInfiniteRunRecord();
                    bool registered = RegisterInfiniteRunOnce(record);
                    if (registered)
                    {
                        preferredRecordBoardPageIndex = 2;
                    }

                    runCore.Exit();
                    string detail = registered
                        ? backend.BuildInfiniteRunSavedPrepMessage(record)
                        : backend.BuildInfiniteRunNoRecordMessage();
                    OpenInfinitePreparation(detail);
                    return;
                }

                if (runCore.IsStoppedNormalRun)
                {
                    string restartPrefix = BuildRestartPrefixFromResultMessage(
                        RegisterNormalAttempt(GreedLastRunAttemptOutcome.Failed, activeNormalRunWasRefill));
                    runCore.RestartStoppedNormalRun(Time.realtimeSinceStartup, restartPrefix);
                    return;
                }

                if (runtimeUi == null || runtimeUi.UsePlayerRunControls)
                {
                    if (!hasLatestAppRunSnapshot || latestAppRunSnapshot.CountdownActive
                        || latestAppRunSnapshot.ChoiceActive) return;
                    if (!latestAppRunSnapshot.AutoFlow)
                    {
                        runCore.ToggleAutoFlow(Time.realtimeSinceStartup);
                        return;
                    }
                    RequestToggleRunPause();
                    return;
                }

                runCore.ToggleAutoFlow(Time.realtimeSinceStartup);
            }
        }

        private void HandleRunChannelInput(GreedLastRunChannel channel)
        {
            if (!CanAcceptPlayerInput()) return;
            if (channel < GreedLastRunChannel.Left || channel > GreedLastRunChannel.Right) return;
            if (HasUnpresentedScreenTransition) return;

            if (stateMachine.CurrentState == GreedLastScreenState.InfiniteStartReady)
            {
                SelectInfinitePreparation(channel);
                return;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.SaveLoadoutDraft
                || stateMachine.CurrentState == GreedLastScreenState.InfiniteLoadoutSelect)
            {
                SelectSaveSlot(channel);
                return;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.InfiniteRecordBoard)
            {
                SelectRecordBoardPage(channel);
                return;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.ProfileBoard)
            {
                SelectProfileBoardPage(channel);
                return;
            }

            if (stateMachine.CurrentState == GreedLastScreenState.GrowthBoard)
            {
                UpgradeGrowth(channel);
                return;
            }

            if (IsRunState())
            {
                if (runCore.IsPaused)
                {
                    return;
                }

                // A lane key sampled during play cannot select a choice that has not been presented yet.
                if (Application.isPlaying && hasLatestAppRunSnapshot && latestAppRunSnapshot.ChoiceActive
                    && runChoiceTransitionFrame == Time.frameCount) return;

                // Update and EventSystem order must not judge a trap before its first rendered frame.
                if (Application.isPlaying && hasLatestAppRunSnapshot && latestAppRunSnapshot.ActivePattern
                    && runPatternTransitionFrame == Time.frameCount) return;

                float now = Time.realtimeSinceStartup;
                // EventSystem can process a queued tap before this app's Update after a stall.
                if (runCore.PauseForInterruptedFrame(now))
                {
                    HandlePresentationSuspended();
                    return;
                }
                if (ShouldBlockRunEntryLaneInput(now, runEntryLaneInputBlockUntil))
                {
                    return;
                }

                if (ShouldBlockRunChoiceInput(
                    hasLatestAppRunSnapshot && latestAppRunSnapshot.ChoiceActive,
                    now,
                    runChoiceInputBlockUntil))
                {
                    return;
                }

                if (ShouldBlockRapidRunLaneInput(channel, now))
                {
                    return;
                }

                runtimeUi.RecordLaneInput(channel);
                bool choiceWasActive = hasLatestAppRunSnapshot && latestAppRunSnapshot.ChoiceActive;
                runCore.HandleInput(channel, now);
                runChoiceInputBlockUntil = BuildRunChoiceInputBlockUntil(
                    choiceWasActive,
                    hasLatestAppRunSnapshot && latestAppRunSnapshot.ChoiceActive,
                    Time.realtimeSinceStartup,
                    runChoiceInputBlockUntil);
            }
        }

        private static bool ShouldBlockRunEntryLaneInput(float now, float inputBlockUntil)
        {
            return inputBlockUntil > 0f && now < inputBlockUntil;
        }

        private static bool ShouldBlockRunChoiceInput(
            bool choiceActive,
            float now,
            float inputBlockUntil)
        {
            return choiceActive && inputBlockUntil > 0f && now < inputBlockUntil;
        }

        private static float BuildRunChoiceInputBlockUntil(
            bool choiceWasActive,
            bool choiceRemainsActive,
            float now,
            float currentInputBlockUntil)
        {
            if (!choiceWasActive || !choiceRemainsActive)
            {
                return currentInputBlockUntil;
            }

            return Mathf.Max(currentInputBlockUntil, now + RunChoiceTransitionInputBlockSeconds);
        }

        private bool ShouldBlockRapidRunLaneInput(GreedLastRunChannel channel, float now)
        {
            if (ShouldBlockRapidRunLaneInputFromValues(
                channel,
                now,
                lastRunAnyLaneInputAt,
                lastRunLaneInputChannel,
                lastRunLaneInputAt))
            {
                return true;
            }

            lastRunAnyLaneInputAt = now;
            lastRunLaneInputChannel = channel;
            lastRunLaneInputAt = now;
            return false;
        }

        private static bool ShouldBlockRapidRunLaneInputFromValues(
            GreedLastRunChannel channel,
            float now,
            float lastAnyLaneInputAt,
            GreedLastRunChannel lastLaneInputChannel,
            float lastLaneInputAt)
        {
            if (channel == GreedLastRunChannel.None)
            {
                return true;
            }

            if (lastAnyLaneInputAt > 0f
                && now - lastAnyLaneInputAt < RunLaneGlobalInputRepeatBlockSeconds)
            {
                return true;
            }

            return lastLaneInputAt > 0f
                && channel == lastLaneInputChannel
                && now - lastLaneInputAt < RunLaneInputRepeatBlockSeconds;
        }

        private void ResetRunLaneInputGuard()
        {
            lastRunLaneInputChannel = GreedLastRunChannel.None;
            lastRunAnyLaneInputAt = 0f;
            lastRunLaneInputAt = 0f;
        }

        private void SelectSaveSlot(GreedLastRunChannel channel)
        {
            runtimeUi.CancelPendingUiInput();
            int slotIndex = channel == GreedLastRunChannel.Left
                ? 0
                : channel == GreedLastRunChannel.Center
                    ? 1
                    : 2;
            GreedLastLobbySnapshot snapshot = backend.SelectSaveLoadoutSlot(slotIndex);
            if (stateMachine.CurrentState == GreedLastScreenState.InfiniteLoadoutSelect)
            {
                saveSlotDeleteConfirmPending = false;
                saveSlotDetailViewActive = false;
                saveSlotRenameConfirmPending = false;
                stateMachine.SetInfiniteLoadoutSelect(
                    snapshot,
                    BuildInfiniteLoadoutSlotSelectionNotice(snapshot, slotIndex)
                        + "\n\n" + backend.BuildInfiniteLoadoutSelectText());
                return;
            }

            OpenSaveLoadoutDraft(
                snapshot,
                requireExplicitSlotChoice: false,
                BuildSaveDraftSlotSelectionNotice(snapshot, backend.HasSaveLoadoutCandidate, slotIndex));
        }

        private void OpenSaveLoadoutDraft(
            GreedLastLobbySnapshot snapshot,
            bool requireExplicitSlotChoice,
            string notice = null,
            bool? refillRunCandidate = null,
            bool preserveSkipConfirmation = false)
        {
            if (refillRunCandidate.HasValue)
            {
                saveDraftFromRefillRun = refillRunCandidate.Value;
            }
            else if (!backend.HasSaveLoadoutCandidate)
            {
                saveDraftFromRefillRun = false;
            }

            saveDraftRequiresExplicitSlotChoice = requireExplicitSlotChoice;
            saveDraftOverwriteConfirmPending = false;
            if (!preserveSkipConfirmation)
            {
                saveDraftSkipConfirmPending = false;
            }

            saveSlotDeleteConfirmPending = false;
            saveSlotDetailViewActive = false;
            saveSlotRenameConfirmPending = false;
            string detail = requireExplicitSlotChoice && IsClearSaveDraftNotice(notice)
                ? backend.BuildSaveLoadoutClearSlotChoiceText()
                : backend.BuildSaveLoadoutDraftText(!requireExplicitSlotChoice);
            if (requireExplicitSlotChoice)
            {
                detail += "\n선택 전 저장 잠김 / 저장 포기는 후보 소모";
            }

            if (!string.IsNullOrEmpty(notice))
            {
                detail = notice + "\n\n" + detail;
            }

            stateMachine.SetSaveLoadoutDraft(
                snapshot,
                detail,
                requireExplicitSlotChoice,
                saveLoadoutSkipConfirmationPending: saveDraftSkipConfirmPending,
                saveLoadoutCandidateAvailable: backend.HasSaveLoadoutCandidate);
        }

        private static bool IsClearSaveDraftNotice(string notice)
        {
            return !string.IsNullOrWhiteSpace(notice)
                && notice.TrimStart().StartsWith("클리어 요약", StringComparison.Ordinal);
        }

