            saveSlotDeleteConfirmPending = false;
            saveSlotDetailViewActive = false;
            saveSlotRenameConfirmPending = false;
            string detail = backend.BuildSelectedSaveLoadoutOverwritePreviewText();
            if (!string.IsNullOrEmpty(notice))
