            if (stateMachine.CurrentState == GreedLastScreenState.LobbyReady)
            {
                GreedLastLobbySnapshot snapshot = backend.ConsumeSelectedSaveLoadoutUseForTest(out string notice);
                if (ShouldStartLobbyNormalAsRefillRun(snapshot))
