            focusMaxRequested = onFocusMaxRequested;
            threatUpRequested = onThreatUpRequested;
            threatDownRequested = onThreatDownRequested;
            timingOffsetRequested = onTimingOffsetRequested;
            devShortcutRequested = onDevShortcutRequested;
            runChannelRequested = onRunChannelRequested;
            EnsureUi();
        }

        public void SetRotationTiltGateState(
            bool available,
            bool ready,
            int heldDirection,
            int candidateDirection,
            float candidateProgress,
            float normalizedAxis)
        {
            rotationTiltInputAvailable = available;
            rotationTiltInputReady = ready;
            rotationTiltInputHeldDirection = Mathf.Clamp(heldDirection, -1, 1);
            rotationTiltInputCandidateDirection = Mathf.Clamp(candidateDirection, -1, 1);
            rotationTiltInputCandidateProgress = Mathf.Clamp01(candidateProgress);
            rotationTiltInputAxis = Mathf.Clamp(normalizedAxis, -1.25f, 1.25f);
        }

        public void CycleDevTrapVisualPreview()
        {
            devTrapVisualPreviewMode = (devTrapVisualPreviewMode + 1) % DevTrapVisualPreviewModeCount;
            ShowDevTrapVisualPreviewFeedback();
        }

        public void ToggleDevCleanView()
        {
            if (!DevToolsEnabled)
            {
                return;
            }

            CancelPendingUiInput();
            devCleanViewEnabled = !devCleanViewEnabled;
            ApplyDevCleanView();
            if (!UsePlayerRunControls && runModeActive && hasRunSnapshot)
            {
                UpdateRunDebugButtonLabels(latestRunSnapshot);
                UpdateRunSettingsButtonLabels(latestRunSnapshot);
            }
            if (runModeActive && hasRunSnapshot && !latestRunSnapshot.Stopped)
            {
                SetButtonLabel(nextPatternButton, BuildRunPrimaryButtonLabelForMode(latestRunSnapshot,
                    normalClearReady: false, playerControls: UsePlayerRunControls));
                UpdateRunProgress(latestRunSnapshot);
                UpdateStageTransitionBanner();
                if (Time.unscaledTime < judgementFeedbackUntil && CanShowRunTransientFeedback()
                    && !latestRunSnapshot.CountdownActive
                    && lastPresentedJudgementSnapshot.LastResult != GreedLastJudgementResult.None)
                {
                    SetJudgementFeedbackText(lastPresentedJudgementSnapshot);
                    ApplyJudgementFeedbackPop();
                }
            }
        }

        private void ApplyDevCleanView()
        {
            bool cleanView = UsePlayerRunControls;
            bool pauseSettings = runModeActive && hasRunSnapshot && latestRunSnapshot.Paused;
            bool liveHeader = runModeActive && hasRunSnapshot
                && !latestRunSnapshot.Stopped && !latestRunSnapshot.Paused
                && !latestRunSnapshot.ChoiceActive && !latestRunSnapshot.CountdownActive;
            SetAnchored(titleText.rectTransform, 0.5f, liveHeader ? 0.88f : 0.82f,
                liveHeader ? 1200f : 900f, liveHeader ? 200f : 110f);
            if (pauseSettings) UpdatePauseMenuOverlay(latestRunSnapshot);
            SetCleanViewGroupsVisible(devCleanViewGroups, !cleanView);
            CanvasGroup resultCalibration = runModeActive && hasRunSnapshot
                && latestRunSnapshot.Stopped && latestRunSnapshot.PracticeMode
                ? timingOffsetButtons[1].GetComponent<CanvasGroup>() : null;
            SetCleanViewGroupsVisible(liveSettingCleanViewGroups, !cleanView || pauseSettings, resultCalibration);
            if (runModeActive && hasRunSnapshot)
                returnLobbyButton.gameObject.SetActive(!cleanView || latestRunSnapshot.Stopped
                    || latestRunSnapshot.Paused || latestRunSnapshot.ChoiceActive);
            if (runModeActive && hasRunSnapshot && !latestRunSnapshot.Stopped)
            {
                if (!cleanView) detailedRunHud = BuildDetailedRunHud(latestRunSnapshot);
                runHudText.text = cleanView ? GetCompactLiveRunHud(latestRunSnapshot) : detailedRunHud;
                runHudText.fontSize = cleanView ? 38 : BuildRunHudFontSize(latestRunSnapshot, detailedRunHud);
                if (cleanView)
                    SetAnchored(runHudText.rectTransform, 0.5f, 0.265f, 1450f, 150f);
                else
                    UpdateRunHudLayout(detailedRunHud);
                subtitleText.text = cleanView ? string.Empty : BuildModeSubtitleForScreen(
                    latestRunSnapshot.InfiniteMode ? GreedLastScreenState.InfiniteRun : GreedLastScreenState.RunCoreTest);
                UpdateLaneLabels(latestRunSnapshot);
            }
        }

        private string BuildDetailedRunHud(GreedLastRunSnapshot snapshot)
        {
            string runState = snapshot.Stopped
                ? snapshot.PracticeMode
                    ? snapshot.Phase == GreedLastRunPhase.ClearResolving ? "상태: 연습 완료" : "상태: 연습 중단"
                    : snapshot.InfiniteMode ? "상태: 무한 종료" : snapshot.SaveEligible ? "상태: 탈출 성공" : "상태: 탈출 실패"
                : snapshot.ResumeCountdownActive
                    ? "상태: 재개 준비"
                    : snapshot.Paused
                        ? "상태: 일시정지"
                        : snapshot.StartCountdownActive
                            ? "상태: 시작 준비"
                            : snapshot.ChoiceActive
                                ? "상태: 선택 중"
                                : snapshot.AutoFlow
                                    ? "상태: 자동 진행"
                                    : "상태: 대기";
            string chapterText = BuildRunChapterHudText(snapshot);
            string choiceText = snapshot.ChoiceActive ? "\n선택: " + snapshot.ChoicePrompt : string.Empty;
            return snapshot.InfiniteMode
                ? BuildInfiniteRunHud(snapshot, runState)
                : BuildNormalRunHud(snapshot, runState, chapterText, choiceText);
        }

        private string GetCompactLiveRunHud(GreedLastRunSnapshot snapshot)
        {
            CultureInfo culture = CultureInfo.CurrentCulture;
            // Mutable number formats can change without replacing the culture object.
            if (!culture.IsReadOnly || !culture.NumberFormat.IsReadOnly) return BuildCompactLiveRunHud(snapshot);
            bool sameTotals = cachedCompactHudText != null && ReferenceEquals(cachedCompactHudCulture, culture)
                && cachedCompactHudScore == snapshot.Score && cachedCompactHudCombo == snapshot.Combo
                && cachedCompactHudSuccess == snapshot.SuccessCount && cachedCompactHudGood == snapshot.GoodCount
                && cachedCompactHudMiss == snapshot.MissCount;
            if (sameTotals && cachedCompactHudDistance.Equals(snapshot.Distance)) return cachedCompactHudText;
            string distance = snapshot.Distance.ToString("0.0");
            if (sameTotals && distance == cachedCompactHudDistanceText)
            {
                cachedCompactHudDistance = snapshot.Distance;
                return cachedCompactHudText;
            }
            if (!sameTotals)
            {
                cachedCompactHudCulture = culture;
                cachedCompactHudScore = snapshot.Score;
                cachedCompactHudCombo = snapshot.Combo;
                cachedCompactHudSuccess = snapshot.SuccessCount;
                cachedCompactHudGood = snapshot.GoodCount;
                cachedCompactHudMiss = snapshot.MissCount;
                cachedCompactHudPrefix = snapshot.Score.ToString("N0") + "점 · ";
                cachedCompactHudSuffix = "m · 콤보 " + snapshot.Combo
                    + "\n정확 " + snapshot.SuccessCount + " · Good " + snapshot.GoodCount + " · Miss " + snapshot.MissCount;
            }
            cachedCompactHudDistance = snapshot.Distance;
            cachedCompactHudDistanceText = distance;
            cachedCompactHudText = cachedCompactHudPrefix + distance + cachedCompactHudSuffix;
            return cachedCompactHudText;
        }

        private static string BuildCompactLiveRunHud(GreedLastRunSnapshot snapshot)
        {
            return snapshot.Score.ToString("N0") + "점 · " + snapshot.Distance.ToString("0.0")
                + "m · 콤보 " + snapshot.Combo
                + "\n정확 " + snapshot.SuccessCount + " · Good " + snapshot.GoodCount + " · Miss " + snapshot.MissCount;
        }

        private static void SetCleanViewGroupsVisible(List<CanvasGroup> groups, bool visible, CanvasGroup visibleException = null)
        {
            foreach (CanvasGroup group in groups)
            {
                bool groupVisible = visible || group == visibleException;
                group.alpha = groupVisible ? 1f : 0f;
                group.interactable = groupVisible;
                group.blocksRaycasts = groupVisible;
            }
        }

        private static void RegisterCleanViewControls(List<CanvasGroup> groups, params Component[] controls)
        {
            foreach (Component control in controls)
            {
                groups.Add(control.gameObject.AddComponent<CanvasGroup>());
            }
        }

        private void Update()
        {
            if (!RefreshPresentationVisibility()) return;
            UpdatePrototypeEntranceBackdrop();
            UpdatePrototypeRunCorridorBackdrop();
            if (beatMarker == null)
            {
                return;
            }

            UpdateRhythmBeatSchedule();
            if (runModeActive && hasRunSnapshot && !latestRunSnapshot.Stopped)
            {
                UpdateHealthDangerPips(latestRunSnapshot);
                UpdateFocusStateTimerPips(latestRunSnapshot);
                ApplyFocusStateGaugePulse(latestRunSnapshot,
                    Mathf.Clamp01(latestRunSnapshot.FocusStateRemainingSeconds / FocusStateUiDurationSeconds));
                UpdateEscapeGatePips(latestRunSnapshot, BuildRunProgressStagePulse(),
                    BuildForwardPayoffBurstPulse(forwardPayoffBurstUntil - Time.unscaledTime, forwardPayoffBurstStrength));
            }
            float beatSpeed = BuildBeatVisualSpeed(latestRunSnapshot);
            beatPhase += Time.unscaledDeltaTime * beatSpeed;
            float pulse = runModeActive ? GetGameplayBeatPulse() : 0.5f + Mathf.Sin(beatPhase * Mathf.PI * 2f) * 0.5f;
            bool transientFeedbackActive = CanShowRunTransientFeedback();
            float missImpact = transientFeedbackActive ? BuildBeatMarkerMissImpact() : 0f;
            float focusGuardImpact = transientFeedbackActive ? BuildBeatMarkerFocusGuardImpact() : 0f;
            float successImpact = transientFeedbackActive ? BuildBeatMarkerSuccessPulse() : 0f;
            float goodImpact = transientFeedbackActive ? BuildBeatMarkerGoodPulse() : 0f;
            float comboBreakImpact = transientFeedbackActive ? BuildBeatMarkerComboBreakPulse() : 0f;
            float comboTierImpact = transientFeedbackActive ? BuildBeatMarkerComboTierPulse() : 0f;
            float profileImpact = transientFeedbackActive ? BuildBeatMarkerProfilePulse() : 0f;
            float downbeatImpact = runModeActive && hasRunSnapshot && ShouldShowDownbeatPulse(latestRunSnapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;
            UpdateKeyboardLaneHoldVisuals();
            Color32 markerColor = Color32.Lerp(new Color32(240, 197, 89, 140), new Color32(255, 238, 181, 255), pulse);
            if (downbeatImpact > 0f)
            {
                markerColor = Color32.Lerp(markerColor, new Color32(255, 214, 105, 255), BuildDownbeatColorBlend(downbeatImpact, 0.44f));
            }

            if (successImpact > 0f)
            {
                markerColor = Color32.Lerp(markerColor, new Color32(255, 238, 181, 255), BuildBeatMarkerColorBlend(successImpact, 0.74f));
            }

            if (comboTierImpact > 0f)
            {
                markerColor = Color32.Lerp(markerColor, new Color32(255, 214, 105, 255), BuildBeatMarkerColorBlend(comboTierImpact, 0.86f));
            }

            if (profileImpact > 0f)
            {
                markerColor = Color32.Lerp(markerColor, GetChoiceProfilePulseColor(latestRunSnapshot.ActiveChoiceProfile), BuildBeatMarkerColorBlend(profileImpact, 0.78f));
            }

            if (goodImpact > 0f)
            {
                markerColor = Color32.Lerp(markerColor, new Color32(132, 190, 208, 245), BuildBeatMarkerColorBlend(goodImpact, 0.58f));
            }

            if (comboBreakImpact > 0f)
            {
                markerColor = Color32.Lerp(markerColor, new Color32(154, 84, 63, 255), BuildBeatMarkerColorBlend(comboBreakImpact, 0.64f));
            }

            if (missImpact > 0f)
            {
                markerColor = Color32.Lerp(markerColor, new Color32(231, 91, 77, 255), BuildBeatMarkerColorBlend(missImpact, 0.82f));
            }

            if (focusGuardImpact > 0f)
            {
                markerColor = Color32.Lerp(markerColor, new Color32(145, 231, 199, 255), BuildBeatMarkerColorBlend(focusGuardImpact, 0.88f));
            }

            beatMarker.color = markerColor;
            beatMarker.rectTransform.localScale = Vector3.one * (BuildBeatMarkerScaleWithImpacts(
                pulse,
                successImpact,
                goodImpact,
                comboTierImpact,
                profileImpact,
                missImpact,
                focusGuardImpact,
                comboBreakImpact)
                + BuildBeatMarkerDownbeatScaleLift(downbeatImpact));
            beatMarker.rectTransform.anchoredPosition = new Vector2(transientFeedbackActive ? BuildBeatMarkerMissShake() : 0f, 0f);
            ApplyRunHudBeatPulse(pulse, downbeatImpact);
            UpdateRunAtmosphere();
            UpdateHealthDangerEdges();

            if (!saveSlotModeActive)
            {
                int activeRunTargetIndex = hasRunSnapshot ? BuildActiveRunTargetLaneIndex(latestRunSnapshot) : -1;
                float activeTargetReadinessGlow = activeRunTargetIndex >= 0 && hasRunSnapshot
                    ? BuildTargetLaneReadinessGlow(activeRunTargetIndex, latestRunSnapshot)
                    : 0f;
                for (int i = 0; i < laneImages.Length; i += 1)
                {
                    float lanePulse = Mathf.Repeat(beatPhase + i * 0.2f, 1f);
                    Color32 baseColor = growthBoardModeActive
                        ? BuildGrowthLaneColumnColor(i, lanePulse)
                        : hasRunSnapshot && latestRunSnapshot.ChoiceActive
                            ? BuildChoiceLaneColumnColor(latestRunSnapshot, i, lanePulse)
                            : BuildRunLaneBaseColor(i, lanePulse);
                    GreedLastRunChannel laneChannel = (GreedLastRunChannel)(i + 1);
                    float trapEntryPulse = 0f;
                    if (!growthBoardModeActive
                        && hasRunSnapshot
                        && ShouldHighlightActivePatternLane(latestRunSnapshot, laneChannel))
                    {
                        trapEntryPulse = BuildTrapEntryPulse();
                        baseColor = Color32.Lerp(baseColor, new Color32(154, 84, 63, 255), 0.72f);
                        if (TryGetPatternVariationAccent(latestRunSnapshot.Pattern, out Color32 variationColor, out float variationStrength))
                        {
                            baseColor = Color32.Lerp(baseColor, variationColor, variationStrength);
                        }

                        if (trapEntryPulse > 0f)
                        {
                            baseColor = Color32.Lerp(baseColor, new Color32(255, 207, 126, 255), trapEntryPulse * 0.46f);
                        }
                    }

                    float choiceConfirmationPulse = BuildChoiceConfirmationPulse(
                        i,
                        choiceConfirmationLaneIndex,
                        choiceConfirmationUntil - Time.unscaledTime);
                    if (choiceConfirmationPulse > 0f)
                    {
                        baseColor = Color32.Lerp(
                            baseColor,
                            choiceConfirmationColor,
                            BuildChoiceConfirmationColorBlend(choiceConfirmationPulse));
                    }

                    float pressPulse = Mathf.Max(BuildLanePressPulse(i), choiceConfirmationPulse * 0.82f);
                    float holdAmount = BuildLaneHoldAmount(i);
                    if (holdAmount > 0f)
                    {
                        baseColor = Color32.Lerp(baseColor, new Color32(255, 238, 181, 255), BuildLaneHoldColorBlend(holdAmount));
                    }

                    if (pressPulse > 0f)
                    {
                        baseColor = Color32.Lerp(baseColor, new Color32(255, 238, 181, 255), BuildLanePressColorBlend(pressPulse));
                    }

                    float targetGlow = i == activeRunTargetIndex ? activeTargetReadinessGlow : 0f;
                    float wrongHoldWarning = BuildLaneWrongHoldWarning(i, activeRunTargetIndex, holdAmount, activeTargetReadinessGlow);
                    if (wrongHoldWarning > 0f)
                    {
                        baseColor = Color32.Lerp(
                            baseColor,
                            new Color32(207, 87, 65, 255),
                            BuildLaneWrongHoldColorBlend(wrongHoldWarning));
                    }

                    float judgementPulse = transientFeedbackActive ? BuildLaneJudgementPulse(i) : 0f;
                    if (judgementPulse > 0f)
                    {
                        baseColor = Color32.Lerp(baseColor, GetLaneJudgementPulseColor(i), judgementPulse * 0.82f);
                    }

                    if (targetGlow > 0f)
                    {
                        baseColor = Color32.Lerp(baseColor, new Color32(255, 238, 181, 255), targetGlow * 0.16f);
                    }

                    float laneBeatCueUrgency = i == activeRunTargetIndex ? BuildActiveBeatCueUrgency(latestRunSnapshot) : 0f;
                    UpdateLaneInputRipple(
                        i,
                        pressPulse,
                        holdAmount,
                        judgementPulse,
                        laneBeatCueUrgency,
                        runModeActive && (ShouldShowLaneInputRipple(latestRunSnapshot)
                            || ShouldShowChoiceConfirmationRipple(choiceConfirmationPulse)));
                    UpdateLaneTargetGlow(
                        i,
                        targetGlow,
                        judgementPulse,
                        laneBeatCueUrgency);
                    UpdateLaneJudgementTag(i, judgementPulse);

                    float missShake = transientFeedbackActive ? BuildLaneMissShake(i) : 0f;
                    laneImages[i].color = baseColor;
                    laneImages[i].rectTransform.anchoredPosition = new Vector2(missShake, 0f);
                    float growthLevel = growthBoardModeActive ? GetGrowthLaneLevel(i) : 0f;
                    laneImages[i].rectTransform.localScale = Vector3.one * (
                        BuildRunLaneSurfaceScale(growthLevel, holdAmount, pressPulse, judgementPulse, trapEntryPulse, targetGlow)
                        + BuildLaneWrongHoldScaleLift(wrongHoldWarning));
                    if (laneLabelTexts != null && i < laneLabelTexts.Length && laneLabelTexts[i] != null && runModeActive)
                    {
                        Color32 labelColor = latestRunSnapshot.ChoiceActive
                            ? BuildChoiceLaneTextColor(latestRunSnapshot, i)
                            : Color32.Lerp(
                                BuildRunLaneLabelColor(i, activeRunTargetIndex, latestRunSnapshot),
                                new Color32(255, 238, 181, 255),
                                Mathf.Max(pressPulse, holdAmount * 0.46f));
                        float exactLanePulse = i == activeRunTargetIndex ? BuildExactTimingPulse() : 0f;
                        if (exactLanePulse > 0f)
                        {
                            labelColor = Color32.Lerp(labelColor, new Color32(255, 248, 210, 255), exactLanePulse * 0.62f);
                        }

                        float labelDownbeatLift = i == activeRunTargetIndex
                            ? BuildRunLaneLabelDownbeatLift(
                                ShouldShowDownbeatPulse(latestRunSnapshot) ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime) : 0f,
                                targetGlow,
                                exactLanePulse)
                            : 0f;
                        if (labelDownbeatLift > 0f)
                        {
                            labelColor = Color32.Lerp(
                                labelColor,
                                new Color32(255, 214, 105, 255),
                                BuildRunLaneLabelDownbeatColorBlend(labelDownbeatLift));
                        }

                        float labelBeatUrgency = laneBeatCueUrgency;
                        if (labelBeatUrgency > 0f)
                        {
                            labelColor = Color32.Lerp(
                                labelColor,
                                new Color32(255, 238, 181, 255),
                                BuildRunLaneLabelBeatCueUrgencyColorBlend(labelBeatUrgency));
                        }

                        if (judgementPulse > 0f)
                        {
                            labelColor = Color32.Lerp(labelColor, GetLaneJudgementPulseColor(i), judgementPulse);
                        }

                        if (choiceConfirmationPulse > 0f)
                        {
                            labelColor = Color32.Lerp(
                                labelColor,
                                choiceConfirmationColor,
                                BuildChoiceConfirmationLabelColorBlend(choiceConfirmationPulse));
                        }

                        if (wrongHoldWarning > 0f)
                        {
                            labelColor = Color32.Lerp(
                                labelColor,
                                new Color32(255, 190, 154, 255),
                                BuildLaneWrongHoldLabelColorBlend(wrongHoldWarning));
                        }

                        laneLabelTexts[i].color = labelColor;
                        float labelScale = BuildRunLaneLabelScale(exactLanePulse, holdAmount, pressPulse, judgementPulse)
                            + BuildRunLaneLabelBeatCueUrgencyScaleLift(labelBeatUrgency)
                            + BuildLaneWrongHoldLabelScaleLift(wrongHoldWarning)
                            + BuildChoiceConfirmationLabelScaleLift(choiceConfirmationPulse);
                        labelScale = BuildRunLaneLabelScaleWithDownbeat(labelScale, labelDownbeatLift);
                        laneLabelTexts[i].rectTransform.localScale = new Vector3(
                            BuildRunLaneLabelScaleXWithDownbeat(
                                BuildRunLaneLabelScaleX(labelScale, exactLanePulse),
                                labelDownbeatLift),
                            BuildRunLaneLabelScaleYWithDownbeat(
                                BuildRunLaneLabelScaleY(labelScale, exactLanePulse),
                                labelDownbeatLift),
                            1f);
                    }
                }
            }
            else
            {
                HideLaneTargetGlows();
                HideLaneJudgementTags();
                HideLaneInputRipples();
            }

            UpdateTempleDepthBackdrop();
            UpdateLobbyRunPortal(pulse);
            UpdateForwardMotionLines();
            UpdateRunnerAvatar();
            UpdateStageTransitionBanner();
            UpdateRunTimingVisuals();
            KeepRunnerCuesAboveTimingGuide();
            UpdateResolvedTrapAfterimage();
            UpdateJudgementHistoryDots();
            ApplyFocusStateAuraBand();
            UpdateFeedbackFlash();
        }

        public void RecordLaneInput(GreedLastRunChannel channel)
        {
            if (lanePressPulseUntil == null)
            {
                return;
            }

            int index = (int)channel - 1;
            if (index < 0 || index >= lanePressPulseUntil.Length)
            {
                return;
            }

            lanePressPulseUntil[index] = Time.unscaledTime + 0.16f;
            if (laneInputRippleUntil != null && index < laneInputRippleUntil.Length)
            {
                laneInputRippleUntil[index] = Time.unscaledTime + LaneInputRippleDuration;
            }
        }

        public void Render(GreedLastStateSnapshot snapshot)
        {
            EnsureUi();
            pendingSaveCandidate = snapshot.SaveLoadoutCandidateAvailable;
            ClearLanePointerHolds();
            if (runModeActive && snapshot.State != GreedLastScreenState.RunCoreTest
                && snapshot.State != GreedLastScreenState.InfiniteRun)
            {
                StopRhythmAudio();
            }
            ApplySafeArea();
            ResetMenuDetailLayout();
            TrackScreenEntranceTransitions(snapshot.State);
            SetPrototypeEntranceBackdropState(snapshot.State);
            if (pauseMenuOverlay != null)
            {
                pauseMenuOverlay.SetActive(false);
            }

            SetRunMenuButtonLayout(false);
            ResetSaveSlotUtilityButtonLayout();

            titleText.text = snapshot.Headline;
            subtitleText.text = string.Empty;
            string detail = BuildDetail(snapshot);
            detailText.text = detail;
            detailText.enabled = true;

            bool lobbyLike = snapshot.State == GreedLastScreenState.LobbyReady
                || snapshot.State == GreedLastScreenState.ReSyncPending;
            bool runLike = snapshot.State == GreedLastScreenState.RunCoreTest
                || snapshot.State == GreedLastScreenState.InfiniteRun;
            bool infiniteRunLike = snapshot.State == GreedLastScreenState.InfiniteRun;
            bool normalRunLike = snapshot.State == GreedLastScreenState.RunCoreTest;
            bool saveDraftConfirmLike = snapshot.State == GreedLastScreenState.SaveLoadoutDraft;
            bool infiniteLoadoutSelectLike = snapshot.State == GreedLastScreenState.InfiniteLoadoutSelect;
            bool saveDraftLike = saveDraftConfirmLike || infiniteLoadoutSelectLike;
            bool recordBoardLike = snapshot.State == GreedLastScreenState.InfiniteRecordBoard;
            bool infinitePrepLike = snapshot.State == GreedLastScreenState.InfiniteStartReady;
            bool growthBoardLike = snapshot.State == GreedLastScreenState.GrowthBoard;
            bool profileBoardLike = snapshot.State == GreedLastScreenState.ProfileBoard;
            bool showDevTools = DevToolsEnabled;
            subtitleText.text = BuildModeSubtitleForScreen(snapshot.State);
            bool growthDevLike = showDevTools && growthBoardLike;
            bool lobbyDevLike = showDevTools && snapshot.State == GreedLastScreenState.LobbyReady;
            bool onboardingComplete = IsCoreOnboardingComplete(snapshot);
            lobbyRunPortalVisible = ShouldShowLobbyRunPortal(snapshot.State);
            lobbyRunPortalPracticeFirst = lobbyRunPortalVisible && !onboardingComplete;
            lobbyRunPortalReady = BuildLobbyRunPortalReady(
                lobbyRunPortalVisible,
                onboardingComplete,
                snapshot.CoreActionsEnabled,
                snapshot.SaveLoadoutCandidateAvailable,
                ResolveLobbyNextActionTarget(snapshot.Detail));
            runModeActive = runLike;
            saveSlotModeActive = saveDraftLike;
            growthBoardModeActive = growthBoardLike;
            if (!saveDraftLike)
            {
                HideSaveSlotUsePips();
            }

            SetGrowthBoardVisualState(snapshot);
            UpdateDebugText(snapshot);
            bool lobbyNoticeLike = snapshot.State == GreedLastScreenState.LobbyReady
                && !string.IsNullOrEmpty(detail);
            if (runGaugeRoot != null)
            {
                runGaugeRoot.SetActive(runLike);
            }

            if (runProgressRoot != null)
            {
                runProgressRoot.SetActive(runLike);
            }

            if (comboBadgeRoot != null)
            {
                comboBadgeRoot.SetActive(false);
            }

            if (!runLike)
            {
                ClearJudgementHistory();
                ResetRhythmBeatSchedule();
                hasRunSnapshot = false;
            }

            detailText.fontSize = recordBoardLike
                ? BuildRecordBoardFontSize(detail)
                : growthBoardLike
                    ? BuildGrowthBoardFontSize(detail)
                    : profileBoardLike
                        ? BuildProfileBoardFontSize(detail)
                        : lobbyNoticeLike
                            ? BuildLobbyNoticeFontSize(detail)
                            : saveDraftLike || infinitePrepLike ? BuildManagementDetailFontSize(detail) : 33;
            if (recordBoardLike || growthBoardLike || profileBoardLike)
            {
                SetAnchored(detailText.rectTransform, 0.5f, 0.55f, 920f, 640f);
            }
            else if (lobbyNoticeLike)
            {
                SetAnchored(detailText.rectTransform, 0.5f, 0.57f, 920f, BuildLobbyNoticeHeight(detail));
            }
            else if (saveDraftLike || infinitePrepLike)
            {
                SetAnchored(detailText.rectTransform, 0.5f, 0.565f, 900f, BuildManagementDetailHeight(detail));
            }
            else
            {
                SetAnchored(detailText.rectTransform, 0.5f, 0.59f, 850f, 260f);
            }

            if (lanePreviewRoot != null)
            {
                lanePreviewRoot.SetActive(ShouldShowLanePreviewForScreen(snapshot.State));
            }

            bool entranceLike = ShouldShowPrototypeEntranceBackdrop(snapshot.State);
            for (int i = 0; i < laneButtons.Length; i += 1)
            {
                laneButtons[i].gameObject.SetActive(!entranceLike);
                laneHitButtons[i].gameObject.SetActive(!entranceLike);
            }
            judgementLine.enabled = runLike;
            beatMarker.enabled = runLike && runnerIllustration == null;

            if (judgementFeedbackText != null && !runLike)
            {
                judgementFeedbackText.text = string.Empty;
                judgementFeedbackText.color = new Color32(255, 238, 181, 0);
                lastTimingRecommendationReady = false;
            }

            if (!runLike)
            {
                HideLaneInputRipples();
                HideRunTimingFeedback();
                HideResolvedTrapAfterimage();
                ClearFeedbackFlash();
                UpdateForwardMotionLines();
                UpdateRunnerAvatar();
