        public void RenderRun(GreedLastRunSnapshot snapshot)
        {
            EnsureUi();
            ApplySafeArea();
            GreedLastRunSnapshot previousSnapshot = latestRunSnapshot;
            bool hadPreviousSnapshot = hasRunSnapshot;
            if (snapshot.Paused && !snapshot.ResumeCountdownActive
                && (!hadPreviousSnapshot || !previousSnapshot.Paused || previousSnapshot.ResumeCountdownActive))
            {
                StopRhythmAudio();
                // A suspended app may not run Update between interrupting and restarting a countdown.
                ResetRhythmBeatSchedule();
            }
            if (!hadPreviousSnapshot || IsNewRunPresentation(previousSnapshot, snapshot))
            {
                ResetRunPresentation(snapshot);
                hadPreviousSnapshot = false;
            }
            // Publications can cross a trap boundary before the UI receives another Update.
            if (!hadPreviousSnapshot || !ShouldShowActivePatternVisuals(snapshot)
                || !ShouldShowActivePatternVisuals(previousSnapshot)
                || !string.Equals(snapshot.Pattern.PatternId, previousSnapshot.Pattern.PatternId, StringComparison.Ordinal)
                || snapshot.ElapsedSeconds < previousSnapshot.ElapsedSeconds)
            {
                lastActivePatternVisual = false;
                targetCuePlayed = false;
            }
            latestRunSnapshot = snapshot;
            hasRunSnapshot = true;
            judgementLine.enabled = !snapshot.ChoiceActive && !snapshot.Stopped;
            TrackChoiceConfirmation(hadPreviousSnapshot, previousSnapshot, snapshot);
            TrackStagePresentation(snapshot);
            HideDebugText();
            RenderRunHeader(snapshot);
            detailText.enabled = snapshot.Stopped;
            bool showDevTools = DevToolsEnabled && !snapshot.PracticeMode;

            // ApplyDevCleanView applies the live HUD once, without a hidden detailed/compact round trip.
            if (snapshot.Stopped)
            {
                detailedRunHud = BuildDetailedRunHud(snapshot);
                runHudText.text = detailedRunHud;
                runHudText.fontSize = BuildRunHudFontSize(snapshot, detailedRunHud);
                UpdateRunHudLayout(detailedRunHud);
            }
            UpdateRunGauges(snapshot);
            UpdateRunProgress(snapshot);
            UpdateComboBadge(snapshot);
            ResetJudgementHistoryForFreshRun(snapshot);
            UpdateJudgementHistoryVisibility(snapshot);
            if (snapshot.ResumeCountdownActive || snapshot.StartCountdownActive)
            {
                ShowResumeCountdownFeedback(snapshot);
            }

            UpdatePauseMenuOverlay(snapshot);
            UpdateRunSideToolsForPause(snapshot, showDevTools);
            SetRunMenuButtonLayout(snapshot.Paused);

            bool normalClearReady = snapshot.Stopped && snapshot.SaveEligible && !snapshot.InfiniteMode;
            bool practiceCandidateHandoff = pendingSaveCandidate
                && GreedLastApp.ShouldContinuePracticeToFirstNormal(snapshot,
                    PlayerPrefs.GetInt(GreedLastApp.PracticeCompletedPrefsKey, 0) == 1);
            SetButtonLabel(nextPatternButton, practiceCandidateHandoff ? "저장 후보 확인"
                : BuildRunPrimaryButtonLabelForMode(snapshot, normalClearReady, UsePlayerRunControls));
            SetButtonLabel(returnLobbyButton, BuildRunReturnButtonLabel(snapshot, normalClearReady));
            SetButtonLabel(pauseButton, BuildRunPauseButtonLabelForMode(snapshot, showDevTools));
            if (!UsePlayerRunControls) UpdateRunDebugButtonLabels(snapshot);
            if (!UsePlayerRunControls || snapshot.Paused || snapshot.Stopped)
                UpdateRunSettingsButtonLabels(snapshot);
            nextPatternButton.interactable = !snapshot.ResumeCountdownActive
                && (snapshot.Paused || (!snapshot.CountdownActive && (!snapshot.ChoiceActive || snapshot.Stopped)));
            pauseButton.interactable = !snapshot.Stopped && !snapshot.ChoiceActive && !snapshot.ResumeCountdownActive;
            infiniteTestStopButton.interactable = showDevTools && snapshot.InfiniteMode && !snapshot.Stopped && !snapshot.Paused && !snapshot.CountdownActive;
            focusMaxButton.interactable = showDevTools && !snapshot.Stopped && !snapshot.Paused && !snapshot.CountdownActive;
            threatUpButton.interactable = showDevTools && snapshot.InfiniteMode && !snapshot.Stopped && !snapshot.Paused && !snapshot.CountdownActive;
            threatDownButton.interactable = showDevTools
                && !snapshot.Stopped
                && !snapshot.Paused
                && !snapshot.CountdownActive
                && (snapshot.InfiniteMode || !snapshot.ChoiceActive);
            hapticsButton.interactable = showDevTools || snapshot.Paused;
            rotationTiltButton.interactable = snapshot.Paused
                && ShouldShowRotationTiltSetting(
                    DevToolsEnabled,
                    Application.isMobilePlatform,
                    SystemInfo.supportsAccelerometer);
            motionComfortButton.interactable = snapshot.Paused;
            for (int i = 0; i < timingOffsetButtons.Length; i += 1)
            {
                timingOffsetButtons[i].interactable = i == 1
                    ? CanUseTimingRecommendationButton(snapshot) : !snapshot.Stopped;
            }

            for (int i = 0; i < sfxVolumeButtons.Length; i += 1)
            {
                sfxVolumeButtons[i].interactable = showDevTools || snapshot.Paused;
            }

            for (int i = 0; i < laneButtons.Length; i += 1)
            {
                SetLaneInputInteractable(i, snapshot.ChoiceActive || (!snapshot.Stopped && !snapshot.Paused && !snapshot.CountdownActive));
            }

            ApplyRunButtonTones(snapshot, normalClearReady);
            if (snapshot.Paused)
            {
                BringPauseControlsToFront();
            }

            UpdateLaneLabels(snapshot);

            PlayJudgementFeedback(snapshot);
            if (!IsLiveRunControlWindow(snapshot))
            {
                HideRunTimingFeedback();
                HideResolvedTrapAfterimage();
                ClearFeedbackFlash();
                UpdateForwardMotionLines();
                UpdateRunnerAvatar();
                UpdateJudgementFeedbackText();
            }
            ApplyStoppedRunPresentation(snapshot);
            ApplyDevCleanView();
        }

