        private static bool IsNewRunPresentation(GreedLastRunSnapshot previous, GreedLastRunSnapshot current)
        {
            return (previous.Stopped && !current.Stopped)
                || previous.InfiniteMode != current.InfiniteMode
                || previous.PracticeMode != current.PracticeMode
                || current.SuccessCount + current.GoodCount + current.MissCount
                    < previous.SuccessCount + previous.GoodCount + previous.MissCount;
        }

        private void ResetRunPresentation(GreedLastRunSnapshot snapshot)
        {
            ResetRhythmBeatSchedule();
            choiceConfirmationCountdownBeatNotBefore = 0f;
            lastComboForBadge = snapshot.Combo;
            lastGaugeHealth = snapshot.Health;
            lastGaugeFocus = snapshot.Focus;
            lastFocusStateActive = snapshot.FocusStateActive;
            lastFeedbackJudgementCount = snapshot.SuccessCount + snapshot.GoodCount + snapshot.MissCount;
            lastPresentedJudgementSnapshot = default;
            lastPresentedJudgementRecommendationReady = false;
            lastTimingRecommendationReady = snapshot.HasTimingRecommendation;
            comboTierFeedbackPending = false;
            comboBreakBadgeCombo = 0;
            comboTierBadgeLevel = 0;
            comboBreakBadgeUntil = comboTierBadgeUntil = comboBadgePulseUntil = 0f;
            healthGaugePulseUntil = focusGaugePulseUntil = focusStateActivationPulseUntil = 0f;
            beatMarkerMissImpactUntil = beatMarkerFocusGuardUntil = beatMarkerSuccessPulseUntil = 0f;
            beatMarkerGoodPulseUntil = beatMarkerComboBreakPulseUntil = beatMarkerComboTierPulseUntil = beatMarkerProfilePulseUntil = 0f;
            judgementFeedbackUntil = judgementFeedbackPopUntil = judgementLinePulseUntil = 0f;
            runnerResponseUntil = resolvedTrapUntil = forwardPayoffBurstUntil = rhythmBreakLineUntil = inputTimingTraceUntil = 0f;
            threeActionExactBurstUntil = feedbackFlashUntil = downbeatPulseUntil = 0f;
            stageTransitionUntil = choiceConfirmationUntil = 0f;
            lastStagePresentationKey = string.Empty;
            lastPresentedRunWasStopped = false;
            stageTransitionCuePending = false;
            judgementFeedbackText.text = string.Empty;
            feedbackFlash.color = Color.clear;
            ClearJudgementHistory();
            for (int i = 0; i < laneButtons.Length; i++)
            {
                ClearLanePointerHold(i);
                lanePressPulseUntil[i] = laneInputRippleUntil[i] = laneJudgementPulseUntil[i] = 0f;
                laneJudgementTagUntil[i] = laneMissShakeUntil[i] = 0f;
            }
        }

        private void ResetRhythmBeatSchedule()
        {
            lastCountdownBeatActive = false;
            lastCountdownWasResume = false;
            nextBeatSoundAt = 0f;
            rhythmBeatIndex = 0;
            rhythmPulseStartedAt = -1f;
            downbeatPulseUntil = 0f;
        }

        private void ApplyStoppedRunPresentation(GreedLastRunSnapshot snapshot)
        {
            bool playing = !snapshot.Stopped;
            lanePreviewRoot.SetActive(playing);
            runGaugeRoot.SetActive(playing);
            runProgressRoot.SetActive(playing);
            runHudText.gameObject.SetActive(playing);
            stageTransitionText.enabled = playing;
            stageTransitionLine.enabled = playing;
            if (!snapshot.Paused) SetButtonFontSize(timingOffsetButtons[1], 22);
            if (playing) return;
            comboBadgeRoot.SetActive(false);
            judgementFeedbackText.text = string.Empty;
            subtitleText.text = string.Empty;
            detailText.text = BuildStoppedRunSummary(snapshot);
            detailText.fontSize = 44;
            detailText.resizeTextForBestFit = false;
            SetAnchored(detailText.rectTransform, 0.5f, 0.53f, 1600f, 680f);
            if (snapshot.PracticeMode)
            {
                bool hasCalibration = snapshot.HasTimingRecommendation || snapshot.TimingRecommendationApplied
                    || Mathf.Abs(snapshot.InputTimingOffsetSeconds) >= 0.001f;
                timingOffsetButtons[1].gameObject.SetActive(hasCalibration);
                SetAnchored(timingOffsetButtons[1].GetComponent<RectTransform>(), 0.5f, 0.265f, 690f, 86f);
                SetButtonFontSize(timingOffsetButtons[1], 34);
            }
        }

        private static string BuildStoppedRunSummary(GreedLastRunSnapshot snapshot)
        {
            string outcome = snapshot.PracticeMode
                ? snapshot.Phase == GreedLastRunPhase.ClearResolving ? "연습 완료" : "연습 중단"
                : snapshot.InfiniteMode
                    ? snapshot.Health <= 0 ? "무한모드 종료 · 체력 소진" : "무한모드 정산 완료"
                    : snapshot.EscapeSucceeded ? "탈출 성공 · 공명핵 회수" : "탈출 실패 · 체력 소진";
            string text = outcome + "\n\n"
                + snapshot.Score.ToString("N0") + "점 · " + snapshot.Distance.ToString("0.0") + "m"
                + "\n정확 " + snapshot.SuccessCount + " · Good " + snapshot.GoodCount + " · Miss " + snapshot.MissCount
                + "\n최대 콤보 " + snapshot.MaxCombo;
            if (snapshot.InfiniteMode)
                text += " · " + snapshot.InfiniteSectionsCleared + "구간 · 최고 위협 " + snapshot.MaxInfiniteThreatLevel;
            if (!snapshot.PracticeMode && !string.IsNullOrEmpty(snapshot.ActiveChoiceProfile))
                text += "\n" + snapshot.ActiveChoiceProfile;
            if (snapshot.SaveEligible && !snapshot.InfiniteMode && !snapshot.PracticeMode)
                text += "\n\n저장 기회 1회";
            if (snapshot.PracticeMode && snapshot.HasTimingRecommendation)
                text += "\n추천 보정 " + FormatTimingRecommendation(snapshot);
            return text;
        }

        private void CreateMenuDetailScroll(Transform parent)
        {
            GameObject scrollObject = CreateRect("MenuDetailScroll", parent, Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero);
            menuDetailScroll = scrollObject.AddComponent<GreedLastMenuScrollRect>();
            menuDetailScroll.horizontal = false;
            menuDetailScroll.movementType = ScrollRect.MovementType.Clamped;
            menuDetailScroll.scrollSensitivity = 70f;
            GameObject viewport = CreateRect("Viewport", scrollObject.transform, Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero);
            viewport.GetComponent<RectTransform>().offsetMax = new Vector2(-32f, 0f);
            viewport.AddComponent<Image>().color = Color.clear;
            viewport.AddComponent<RectMask2D>();
            menuDetailScroll.viewport = viewport.GetComponent<RectTransform>();
            GameObject track = CreateRect("Scrollbar", scrollObject.transform, new Vector2(1f, 0f), Vector2.one,
                new Vector2(1f, 0.5f), new Vector2(14f, 0f));
            track.AddComponent<Image>().color = new Color32(58, 73, 76, 130);
            GameObject handle = CreateRect("Handle", track.transform, Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero);
            Image handleImage = handle.AddComponent<Image>();
            handleImage.color = new Color32(171, 203, 195, 240);
            Scrollbar scrollbar = track.AddComponent<GreedLastMenuScrollbar>();
            scrollbar.handleRect = handle.GetComponent<RectTransform>();
            scrollbar.targetGraphic = handleImage;
            scrollbar.direction = Scrollbar.Direction.BottomToTop;
            menuDetailScroll.verticalScrollbar = scrollbar;
            menuDetailScroll.verticalScrollbarVisibility = ScrollRect.ScrollbarVisibility.Permanent;
            scrollObject.SetActive(false);
        }

        private void ResetMenuDetailLayout()
        {
            if (menuDetailScroll != null)
            {
                detailText.transform.SetParent(rootPanel.transform, false);
                detailText.rectTransform.pivot = new Vector2(0.5f, 0.5f);
                menuDetailScroll.content = null;
                menuDetailScroll.gameObject.SetActive(false);
            }
            detailText.alignment = TextAnchor.UpperCenter;
            detailText.resizeTextForBestFit = false;
            RectTransform lanes = lanePreviewRoot.GetComponent<RectTransform>();
            lanes.anchorMin = new Vector2(0.14f, 0.44f);
            lanes.anchorMax = new Vector2(0.86f, 0.74f);
            lanes.offsetMin = lanes.offsetMax = Vector2.zero;
            for (int i = 0; i < laneImages.Length; i++)
            {
                laneImages[i].rectTransform.sizeDelta = new Vector2(195f, 520f);
                laneHitButtons[i].GetComponent<RectTransform>().sizeDelta = new Vector2(230f, 580f);
                SetLaneLabelRect(laneLabelTexts[i], false);
            }
        }

        private void ApplyMenuDetailLayout(GreedLastStateSnapshot snapshot)
        {
            bool slots = snapshot.State == GreedLastScreenState.SaveLoadoutDraft
                || snapshot.State == GreedLastScreenState.InfiniteLoadoutSelect;
            bool preparing = snapshot.State == GreedLastScreenState.InfiniteStartReady;
            bool records = snapshot.State == GreedLastScreenState.InfiniteRecordBoard
                || snapshot.State == GreedLastScreenState.ProfileBoard;
            bool growth = snapshot.State == GreedLastScreenState.GrowthBoard;
            bool lobbyNotice = snapshot.State == GreedLastScreenState.LobbyReady && !string.IsNullOrWhiteSpace(detailText.text);
            if (!slots && !preparing && !records && !growth && !lobbyNotice) return;
            bool choices = slots || growth || (preparing && IsSelectedSaveSlotUsable(snapshot));
            if (!lobbyNotice) subtitleText.text = string.Empty;
            if (preparing && IsSelectedSaveSlotUsable(snapshot))
            {
                string slotLabel = snapshot.SaveSlotLabels[snapshot.SelectedSaveSlotIndex];
                subtitleText.text = IsSaveSlotFinalUseLabel(slotLabel)
                    ? "마지막 1회 · 시작 후 슬롯 자동 비움"
                    : "저장 조합 2회 사용 가능";
            }
            if (choices)
            {
                RectTransform lanes = lanePreviewRoot.GetComponent<RectTransform>();
                lanes.anchorMin = new Vector2(0.18f, 0.245f);
                lanes.anchorMax = new Vector2(0.82f, 0.465f);
                lanes.offsetMin = lanes.offsetMax = Vector2.zero;
                for (int i = 0; i < laneImages.Length; i++)
                {
                    laneImages[i].rectTransform.sizeDelta = new Vector2(460f, 330f);
                    laneHitButtons[i].GetComponent<RectTransform>().sizeDelta = new Vector2(460f, 330f);
                }
                SetLaneLabelMode(40, true);
                saveSlotModeText.gameObject.SetActive(false);
                SetAnchored(saveSlotDetailButton.GetComponent<RectTransform>(), 0.315f, 0.205f, 450f, 80f);
                SetAnchored(saveSlotRenameButton.GetComponent<RectTransform>(), 0.5f, 0.205f, 450f, 80f);
                SetAnchored(saveSlotDeleteButton.GetComponent<RectTransform>(), 0.685f, 0.205f, 450f, 80f);
                if (preparing)
                    SetAnchored(saveLoadoutButton.GetComponent<RectTransform>(), 0.5f, 0.205f, 690f, 80f);
            }
            else if (!lobbyNotice)
            {
                lanePreviewRoot.SetActive(false);
            }

            // Keep long comparison data readable in its own scrolling area, separate from selectable slots.
            // Native OnEnable binds the scrollbar only when its scroll axis is already enabled.
            menuDetailScroll.vertical = true;
            menuDetailScroll.gameObject.SetActive(true);
            SetAnchored(menuDetailScroll.GetComponent<RectTransform>(), 0.5f, choices || lobbyNotice ? 0.62f : 0.55f,
                1800f, choices || lobbyNotice ? 440f : preparing ? 720f : 850f);
            detailText.transform.SetParent(menuDetailScroll.viewport, false);
            detailText.fontSize = records ? 42 : 38;
            detailText.alignment = TextAnchor.UpperLeft;
            RectTransform content = detailText.rectTransform;
            content.anchorMin = new Vector2(0f, 1f);
            content.anchorMax = Vector2.one;
            content.pivot = new Vector2(0.5f, 1f);
            content.anchoredPosition = Vector2.zero;
            content.sizeDelta = new Vector2(-32f, 0f);
            menuDetailScroll.content = content;
            Canvas.ForceUpdateCanvases();
            content.sizeDelta = new Vector2(-32f, Mathf.Max(menuDetailScroll.viewport.rect.height, detailText.preferredHeight + 16f));
            menuDetailScroll.vertical = content.sizeDelta.y > menuDetailScroll.viewport.rect.height + 1f;
            menuDetailScroll.verticalScrollbar.gameObject.SetActive(menuDetailScroll.vertical);
            menuDetailScroll.StopMovement();
            menuDetailScroll.verticalNormalizedPosition = 1f;
        }

        private static string PrefixDevShortcut(string shortcut, string label)
        {
            return string.IsNullOrEmpty(shortcut) ? label : shortcut + " " + label;
        }

        private static string BuildDevSectionShortcutLabel(GreedLastDevShortcut shortcut)
        {
            switch (shortcut)
            {
                case GreedLastDevShortcut.GiftChoice:
                    return "기프트 선택";
                case GreedLastDevShortcut.RelicChoice:
                    return "유물 선택";
                case GreedLastDevShortcut.AfterCore:
                    return "핵 직후";
                case GreedLastDevShortcut.BeforeClear:
                    return "탈출 직전";
                default:
                    return "구간";
            }
        }

        private static string BuildReviewTargetShortcutLabel(GreedLastRunSnapshot snapshot)
        {
            string target = snapshot.ReviewTargetText ?? string.Empty;
            if (target.Contains("추천 보정 적용", StringComparison.Ordinal))
            {
                return "목표 보정";
            }

            if (target.Contains("구간 생존", StringComparison.Ordinal)
                || target.Contains("위협", StringComparison.Ordinal))
            {
                return "목표 구간";
            }

            if (target.Contains("무실수", StringComparison.Ordinal)
                || target.Contains("보정 0회", StringComparison.Ordinal)
                || target.Contains("입력 없음", StringComparison.Ordinal)
                || (target.Contains("실수", StringComparison.Ordinal)
                    && target.Contains("이하", StringComparison.Ordinal)))
            {
                return "목표 정산";
            }

            return "목표 직전";
        }

        private static string BuildRunFocusTestButtonLabel(GreedLastRunSnapshot snapshot)
        {
            return snapshot.FocusStateActive ? "집중 리필" : "집중 발동";
        }

        private static string BuildRunThreatUpTestButtonLabel(GreedLastRunSnapshot snapshot)
        {
            return snapshot.InfiniteThreatLevel >= InfiniteThreatUiMaxLevel ? "위협 MAX" : "위협 +1";
        }

        private static string BuildRunThreatDownTestButtonLabel(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.InfiniteMode)
            {
                return snapshot.Health <= 1 ? "위험 유지" : "피해 -1";
            }

            return snapshot.InfiniteThreatLevel <= InfiniteThreatUiMinLevel ? "위협 MIN" : "위협 -1";
        }

        private static string BuildRouteTestShortcutLabel(GreedLastRunSnapshot snapshot)
        {
            return "경로 " + FormatRouteShortcutLabel(BuildNextRouteTestProfile(snapshot.ActiveRouteProfile));
        }

        private static string BuildNextRouteTestProfile(string activeRouteProfile)
        {
            switch (activeRouteProfile)
            {
                case "안정 루트":
                    return "변주 루트";
                case "변주 루트":
                    return "압박 루트";
                default:
                    return "안정 루트";
            }
        }

        private static string FormatRouteShortcutLabel(string routeProfile)
        {
            switch (routeProfile)
            {
                case "변주 루트":
                    return "변주 ↔↓↑";
                case "압박 루트":
                    return "압박 ↓↔↑";
                default:
                    return "안정 ↑↓↔";
            }
        }

        private static string BuildAvoidanceTestShortcutLabel(GreedLastRunSnapshot snapshot)
        {
            int current = ExtractActiveAvoidanceTestIndex(snapshot);
            int next = current < 0 ? 0 : (current + 1) % 5;
            string prefix = current < 0 ? "동작 " : "다음 ";
            return prefix + FormatAvoidanceTestShortcutLabel(next);
        }

        private static string FormatAvoidanceTestShortcutLabel(int index)
        {
            switch ((index % 5 + 5) % 5)
            {
                case 1:
                    return "↓ 숙이기";
                case 2:
                    return "↔ 비틀기";
                case 3:
                    return "⭯ 회전 Q";
                case 4:
                    return "⭮ 회전 E";
                default:
                    return "↑ 점프";
            }
        }

        private static string BuildDevTrapVisualPreviewButtonLabel(int previewMode)
        {
            switch (NormalizeDevTrapVisualPreviewMode(previewMode))
            {
                case 1:
                    return "낙하 느림";
                case 2:
                    return "낙하 빠름";
                default:
                    return "낙하 보통";
            }
        }

        private static string BuildDevTrapVisualPreviewFeedbackText(int previewMode)
        {
            return "테스트 " + BuildDevTrapVisualPreviewButtonLabel(previewMode)
                + "\n판정 위치 유지";
        }

        private static int NormalizeDevTrapVisualPreviewMode(int previewMode)
        {
            return (previewMode % DevTrapVisualPreviewModeCount + DevTrapVisualPreviewModeCount) % DevTrapVisualPreviewModeCount;
        }

        private static int ExtractActiveAvoidanceTestIndex(GreedLastRunSnapshot snapshot)
        {
            string judgementText = snapshot.JudgementText ?? string.Empty;
            if (judgementText.Contains("테스트 동작 확인 - 점프", StringComparison.Ordinal))
            {
                return 0;
            }

            if (judgementText.Contains("테스트 동작 확인 - 숙이기", StringComparison.Ordinal))
            {
                return 1;
            }

            if (judgementText.Contains("테스트 동작 확인 - 비틀기", StringComparison.Ordinal))
            {
                return 2;
            }

            if (judgementText.Contains("테스트 동작 확인 - 좌회전 통로", StringComparison.Ordinal))
            {
                return 3;
            }

            if (judgementText.Contains("테스트 동작 확인 - 우회전 통로", StringComparison.Ordinal))
            {
                return 4;
            }

            if (snapshot.ActivePattern
                && snapshot.ChapterIndex == 1
                && snapshot.Score == 0
                && snapshot.SuccessCount == 0
                && snapshot.GoodCount == 0
                && snapshot.MissCount == 0)
            {
                if (GreedLastRunCore.IsRotationPattern(snapshot.Pattern))
                {
                    return snapshot.Pattern.Channel == GreedLastRunChannel.Left ? 3 : 4;
                }

                switch (BuildRunnerResponseType(snapshot.Pattern))
                {
                    case RunnerResponseType.Jump:
                        return 0;
                    case RunnerResponseType.Slide:
                        return 1;
                    case RunnerResponseType.Twist:
                        return 2;
                }
            }

            return -1;
        }

        private void UpdatePauseMenuOverlay(GreedLastRunSnapshot snapshot)
        {
            if (pauseMenuOverlay == null)
            {
                return;
            }

            pauseMenuOverlay.SetActive(snapshot.Paused);
            if (!snapshot.Paused)
            {
                return;
            }

            pauseMenuOverlay.transform.SetAsLastSibling();
            UpdatePauseSoftBlurBands(snapshot);

            if (pauseMenuTitleText != null)
            {
                pauseMenuTitleText.text = snapshot.ResumeCountdownActive
                    ? "재개 " + BuildResumeCountdownFeedbackText(snapshot)
                    : BuildRunPauseTitle(snapshot);
            }

            if (pauseMenuBodyText != null)
            {
                string unplayedExitLine = IsUnplayedInfiniteRun(snapshot) ? "\n기록 없음 · 사용권 차감 유지" : string.Empty;
                if (!DevToolsEnabled || devCleanViewEnabled)
                {
                    pauseMenuBodyText.text = "체력 " + snapshot.Health + "/" + snapshot.MaxHealth
                        + " · 집중 " + snapshot.Focus + "/" + snapshot.MaxFocus
                        + "\n" + snapshot.Score.ToString("N0") + "점 · " + snapshot.Distance.ToString("0.0") + "m"
                        + "\n보정 " + FormatTimingOffset(snapshot.InputTimingOffsetSeconds)
                        + unplayedExitLine;
                    pauseMenuBodyText.fontSize = 36;
                    return;
                }
                string settingsLine = BuildPauseSettingsLine(snapshot);
                string coachLine = BuildPauseCoachLine(snapshot);
                string coachBlock = string.IsNullOrEmpty(coachLine) ? string.Empty : "\n" + coachLine;
                if (snapshot.ResumeCountdownActive)
                {
                    pauseMenuBodyText.text = "카운트 후 앞 박자 여유를 두고 이어집니다.\n입력은 다시 보이는 판정선에 맞춰 받습니다."
                        + unplayedExitLine
                        + coachBlock
                        + "\n" + settingsLine;
                }
                else if (snapshot.StartCountdownActive)
                {
                    pauseMenuBodyText.text = "시작 카운트가 멈춰 있습니다.\n재개하면 여유 카운트 뒤 첫 함정이 내려옵니다."
                        + unplayedExitLine
                        + coachBlock
                        + "\n" + settingsLine;
                }
                else
                {
                    pauseMenuBodyText.text = BuildPauseMenuResumeLineForMode(DevToolsEnabled)
                        + coachBlock
                        + "\n" + BuildPauseExitHintLine(snapshot)
                        + "\n" + settingsLine;
                }

                pauseMenuBodyText.fontSize = BuildPauseMenuBodyFontSize(pauseMenuBodyText.text);
                while (pauseMenuBodyText.fontSize > 18 && !FeedbackTextFitsBounds(pauseMenuBodyText))
                    pauseMenuBodyText.fontSize -= 1;
            }
        }

        public static string BuildPauseCoachLine(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped)
            {
                return string.Empty;
            }

            if (snapshot.ActivePattern && snapshot.Pattern.IsValid)
            {
                string coachLine = BuildLiveRunCoachLine(snapshot);
                if (string.IsNullOrEmpty(coachLine))
                {
                    coachLine = BuildActivePatternCoach(snapshot);
                }

                string target = (snapshot.ResumeCountdownActive ? "첫 함정 기준선 / " : string.Empty)
                    + FormatChannel(snapshot.Pattern.Channel)
                    + " · " + FormatTimingType(snapshot.Pattern.TimingType);
                string exactGoal = BuildPauseExactGoalTargetSuffix(snapshot);
                if (!string.IsNullOrEmpty(exactGoal))
                {
                    target += " / " + exactGoal;
                }

                string reviewTarget = BuildPauseReviewTargetSuffix(snapshot);
                if (!string.IsNullOrEmpty(reviewTarget))
                {
                    target += " / " + reviewTarget;
                }

                return string.IsNullOrEmpty(coachLine)
                    ? "재개 목표: " + target
                    : "재개 목표: " + target + "\n" + CompactUiText(coachLine, 82);
            }

            if (snapshot.StartCountdownActive || snapshot.ResumeCountdownActive)
            {
                string reviewTarget = BuildPauseReviewTargetSuffix(snapshot);
                return string.IsNullOrEmpty(reviewTarget)
                    ? "재개 목표: 카운트 뒤 첫 함정 기준선 확인"
                    : "재개 목표: " + CompactUiText("카운트 뒤 첫 함정 기준선 확인 / " + reviewTarget, 82);
            }

            return snapshot.ChoiceActive
                ? "재개 목표: " + CompactUiText("선택지 확인 후 좌 · 중 · 우 입력" + BuildChoicePauseReviewTargetSuffix(snapshot), 82)
                : string.Empty;
        }

        private static string BuildPauseReviewTargetSuffix(GreedLastRunSnapshot snapshot)
        {
            string reviewTarget = BuildReviewTargetHudLine(snapshot);
            return string.IsNullOrEmpty(reviewTarget) ? string.Empty : reviewTarget;
        }

        private static string BuildRunPauseTitle(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.ResumeCountdownActive)
            {
                return "재개 준비";
            }

            if (snapshot.StartCountdownActive)
            {
                return "시작 대기";
            }

            if (snapshot.PracticeMode)
            {
                return "기초연습 메뉴";
            }

            return snapshot.InfiniteMode ? "무한모드 메뉴" : snapshot.RefillRun ? "보충 런 메뉴" : "일시정지 메뉴";
        }

        private static string BuildPauseExactGoalTargetSuffix(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.Pattern.IsValid)
            {
                return string.Empty;
            }

            string payoffGoal = BuildPrototypeFeelPayoffGoal(snapshot);
            return string.IsNullOrEmpty(payoffGoal) ? string.Empty : "정확→" + payoffGoal;
        }

        private static string BuildChoicePauseReviewTargetSuffix(GreedLastRunSnapshot snapshot)
        {
            string reviewTarget = BuildPauseReviewTargetSuffix(snapshot);
            return string.IsNullOrEmpty(reviewTarget) ? string.Empty : " / " + reviewTarget;
        }

        private static bool IsUnplayedInfiniteRun(GreedLastRunSnapshot snapshot)
        {
            return snapshot.InfiniteMode && !GreedLastRunCore.HasRecordableInfiniteProgress(
                snapshot.Distance, snapshot.SuccessCount, snapshot.GoodCount, snapshot.MissCount);
        }

        private static string BuildPauseExitHintLine(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.PracticeMode)
            {
                return "로비로 돌아가도 일반 런 기록과 저장 기회는 변하지 않습니다.";
            }

            if (snapshot.InfiniteMode)
            {
                return IsUnplayedInfiniteRun(snapshot)
                    ? "주행 전 종료: 기록·보상 없음 / 사용권 차감 유지"
                    : "로비로 돌아가면 현재 무한 기록을 정산하고 종료합니다.";
            }

            return snapshot.RefillRun
                ? "로비로 돌아가면 보충 런 중단 기록으로 남습니다."
                : "로비로 돌아가면 중단 기록으로 남습니다.";
        }

        private static string BuildRunReturnButtonLabel(GreedLastRunSnapshot snapshot, bool normalClearReady)
        {
            if (snapshot.PracticeMode)
            {
                return snapshot.Stopped ? "연습 마치기" : "연습 그만두기";
            }

            if (normalClearReady)
            {
                return "저장 없이 로비";
            }

            if (snapshot.Stopped)
            {
                return "로비로";
            }

            if (snapshot.InfiniteMode)
            {
                return IsUnplayedInfiniteRun(snapshot) ? "기록 없이 로비" : "정산 후 로비";
            }

            if (snapshot.Paused)
            {
                return snapshot.RefillRun ? "보충 중단" : "중단하고 로비";
            }

            return snapshot.RefillRun ? "보충 포기" : "탈출 포기";
        }

        private static string BuildRunPrimaryButtonLabelForMode(GreedLastRunSnapshot snapshot,
            bool normalClearReady, bool playerControls)
        {
            if (playerControls && !snapshot.Stopped && !snapshot.Paused && !snapshot.ChoiceActive)
                return snapshot.CountdownActive ? "시작 준비" : snapshot.AutoFlow ? "일시정지" : "함정 재개";
            return BuildRunNextActionButtonLabel(snapshot, normalClearReady);
        }

        private static string BuildRunNextActionButtonLabel(GreedLastRunSnapshot snapshot, bool normalClearReady)
        {
            if (snapshot.ResumeCountdownActive) return "재개 준비";
            if (snapshot.Stopped)
            {
                if (snapshot.PracticeMode)
                {
                    bool practicePreviouslyCompleted = PlayerPrefs.GetInt(
                        GreedLastApp.PracticeCompletedPrefsKey,
                        0) == 1;
                    return BuildPracticeCompletionPrimaryButtonLabel(
                        snapshot,
                        practicePreviouslyCompleted);
                }

                if (normalClearReady)
                {
                    return "저장 슬롯 선택";
                }

                if (snapshot.InfiniteMode)
                {
                    return "정산 후 재준비";
                }

                return snapshot.RefillRun ? "보충 재시작" : "다시 시작";
            }

            if (snapshot.Paused)
            {
                return "재개";
            }

            if (snapshot.ChoiceActive)
            {
                return "선택 대기";
            }

            return snapshot.AutoFlow ? "자동 정지" : "자동 시작";
        }

        private static string BuildPracticeCompletionPrimaryButtonLabel(
            GreedLastRunSnapshot snapshot,
            bool practicePreviouslyCompleted)
        {
            return GreedLastApp.ShouldContinuePracticeToFirstNormal(
                snapshot,
                practicePreviouslyCompleted)
                    ? "일반 런으로"
                    : BuildPracticeRestartButtonLabel(snapshot);
        }

        private void UpdatePauseSoftBlurBands(GreedLastRunSnapshot snapshot)
        {
            if (pauseMenuSoftBlurBands == null || pauseMenuSoftBlurBands.Length < 5)
            {
                return;
            }

            for (int i = 0; i < pauseMenuSoftBlurBands.Length; i += 1)
            {
                SetImageAlpha(pauseMenuSoftBlurBands[i], (byte)BuildPauseSoftBlurBandAlpha(snapshot, i));
            }
        }

        private static int BuildPauseSoftBlurBandAlpha(GreedLastRunSnapshot snapshot, int bandIndex)
        {
            return BuildPauseSoftBlurBandAlphaFromValues(snapshot.ResumeCountdownActive, bandIndex);
        }

        private static int BuildPauseSoftBlurBandAlphaFromValues(bool resumeCountdownActive, int bandIndex)
        {
            switch (bandIndex)
            {
                case 0:
                case 1:
                    return resumeCountdownActive ? 132 : 118;
                case 2:
                case 3:
                    return resumeCountdownActive ? 108 : 96;
                case 4:
                    return resumeCountdownActive ? 28 : 18;
                default:
                    return 0;
            }
        }

        private static void SetImageAlpha(Image image, byte alpha)
        {
            if (image == null)
            {
                return;
            }

            Color32 color = image.color;
            color.a = alpha;
            image.color = color;
        }

        private void BringPauseControlsToFront()
        {
            BringButtonToFront(nextPatternButton);
            BringButtonToFront(returnLobbyButton);
            BringButtonToFront(hapticsButton);
            BringButtonToFront(rotationTiltButton);
            BringButtonToFront(motionComfortButton);
            BringButtonArrayToFront(sfxVolumeButtons);
            BringButtonArrayToFront(timingOffsetButtons);
        }

        private static void BringButtonArrayToFront(Button[] buttons)
        {
            if (buttons == null)
            {
                return;
            }

            for (int i = 0; i < buttons.Length; i += 1)
            {
                BringButtonToFront(buttons[i]);
            }
        }

        private static void BringButtonToFront(Button button)
        {
            if (button == null || !button.gameObject.activeSelf)
            {
                return;
            }

            button.transform.SetAsLastSibling();
        }

        private string BuildPauseSettingsLine(GreedLastRunSnapshot snapshot)
        {
            bool showRotationTiltSetting = ShouldShowRotationTiltSetting(
                DevToolsEnabled,
                Application.isMobilePlatform,
                SystemInfo.supportsAccelerometer);
            return BuildPauseSettingsLineTextWithTilt(
                snapshot,
                sfxVolume,
                hapticsEnabled,
                rotationTiltEnabled,
                showRotationTiltSetting)
                + " / 시야 "
                + BuildMotionComfortStatusText(motionComfortEnabled);
        }

        private static string BuildPauseSettingsLineText(
            GreedLastRunSnapshot snapshot,
            float volume,
            bool hapticsOn)
        {
            return BuildPauseSettingsLineTextWithTilt(
                snapshot,
                volume,
                hapticsOn,
                rotationTiltOn: true,
                showRotationTiltSetting: false);
        }

        private static string BuildPauseSettingsLineTextWithTilt(
            GreedLastRunSnapshot snapshot,
            float volume,
            bool hapticsOn,
            bool rotationTiltOn,
            bool showRotationTiltSetting)
        {
            int volumePercent = Mathf.RoundToInt(NormalizeSfxVolume(volume) * 100f);
            string hapticsText = hapticsOn ? "ON" : "OFF";
            string recommendationText = " / " + FormatTimingRecommendationStatus(snapshot);
            string countdownText = string.Empty;
            if (snapshot.ResumeCountdownActive)
            {
                countdownText = " / 재개 " + snapshot.ResumeCountdownRemainingSeconds.ToString("0.0") + "s";
            }

            if (snapshot.StartCountdownActive)
            {
                countdownText += " / 시작 " + snapshot.StartCountdownRemainingSeconds.ToString("0.0") + "s";
            }

            string rotationTiltText = showRotationTiltSetting
                ? " / 기울임 " + (rotationTiltOn ? "ON" : "OFF")
                : string.Empty;
            return "설정: 소리 " + volumePercent + "% / 보정 " + FormatTimingOffset(snapshot.InputTimingOffsetSeconds) + recommendationText + countdownText + " / 진동 " + hapticsText + rotationTiltText;
        }

        private static string BuildTimingRecommendationButtonLabel(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.TimingRecommendationApplied)
            {
                return "적용 완료 "
                    + FormatTimingOffset(snapshot.AppliedTimingRecommendationMilliseconds / 1000f);
            }

            if (snapshot.HasTimingRecommendation)
            {
                return HasActionableTimingRecommendationButton(snapshot)
                    ? "추천 적용 " + FormatTimingRecommendation(snapshot)
                    : "보정 안정";
            }

            if (Mathf.Abs(snapshot.InputTimingOffsetSeconds) >= 0.001f)
            {
                return "0ms 복귀";
            }

            return "추천 대기 " + snapshot.TimingRecommendationSampleCount + "/" + snapshot.TimingRecommendationSampleTarget;
        }

        private static bool HasActionableTimingRecommendationButton(GreedLastRunSnapshot snapshot)
        {
            int currentMilliseconds = Mathf.RoundToInt(snapshot.InputTimingOffsetSeconds * 1000f);
            if (!snapshot.HasTimingRecommendation)
            {
                return currentMilliseconds != 0;
            }

            return Mathf.Abs(currentMilliseconds - snapshot.TimingRecommendationMilliseconds) >= 25;
        }

        private static bool CanUseTimingRecommendationButton(GreedLastRunSnapshot snapshot)
        {
            return (!snapshot.Stopped || snapshot.PracticeMode)
                && HasActionableTimingRecommendationButton(snapshot);
        }

        private static string FormatTimingRecommendation(GreedLastRunSnapshot snapshot)
        {
            return FormatTimingOffset(snapshot.TimingRecommendationMilliseconds / 1000f);
        }

        private static string FormatTimingRecommendationStatus(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.HasTimingRecommendation)
            {
                return "추천 대기 " + snapshot.TimingRecommendationSampleCount + "/" + snapshot.TimingRecommendationSampleTarget;
            }

            int currentMilliseconds = Mathf.RoundToInt(snapshot.InputTimingOffsetSeconds * 1000f);
            int recommendationDelta = snapshot.TimingRecommendationMilliseconds - currentMilliseconds;
            if (Mathf.Abs(recommendationDelta) < 25)
            {
                return "추천 보정 안정";
            }

            string trend = recommendationDelta < 0 ? "입력 늦음" : "입력 빠름";
            return "추천 " + trend + " -> " + FormatTimingRecommendation(snapshot);
        }

        private void UpdateRunSideToolsForPause(GreedLastRunSnapshot snapshot, bool showDevTools)
        {
            bool showSideTools = !snapshot.Paused;
            bool showPauseSettings = snapshot.Paused;
            pauseButton.gameObject.SetActive(showSideTools && !snapshot.Stopped);
            devInvincibleButton.gameObject.SetActive(showDevTools && showSideTools);
            infiniteTestStopButton.gameObject.SetActive(showDevTools && showSideTools && snapshot.InfiniteMode);
            focusMaxButton.gameObject.SetActive(showDevTools && showSideTools);
            threatUpButton.gameObject.SetActive(showDevTools && showSideTools && snapshot.InfiniteMode);
            threatDownButton.gameObject.SetActive(showDevTools && showSideTools);
            hapticsButton.gameObject.SetActive(showPauseSettings || (showDevTools && showSideTools));
            rotationTiltButton.gameObject.SetActive(
                showPauseSettings
                && ShouldShowRotationTiltSetting(
                    DevToolsEnabled,
                    Application.isMobilePlatform,
                    SystemInfo.supportsAccelerometer));
            motionComfortButton.gameObject.SetActive(showPauseSettings);

            for (int i = 0; i < devShortcutButtons.Length; i += 1)
            {
                bool targetShortcut = i == (int)GreedLastDevShortcut.ReviewTargetCheck;
                bool visualPreviewShortcut = i == (int)GreedLastDevShortcut.VisualDropPreview;
                bool shortcutVisible = showDevTools
                    && showSideTools
                    && (!(snapshot.ChoiceActive || snapshot.Stopped) || i < (int)GreedLastDevShortcut.ReviewTargetCheck)
                    && (targetShortcut || visualPreviewShortcut || !snapshot.InfiniteMode)
                    && (!targetShortcut || !string.IsNullOrWhiteSpace(snapshot.ReviewTargetText));
                devShortcutButtons[i].gameObject.SetActive(shortcutVisible);
                devShortcutButtons[i].interactable = shortcutVisible;
            }

            for (int i = 0; i < timingOffsetButtons.Length; i += 1)
            {
                timingOffsetButtons[i].gameObject.SetActive(showPauseSettings || showSideTools);
            }

            for (int i = 0; i < sfxVolumeButtons.Length; i += 1)
            {
                sfxVolumeButtons[i].gameObject.SetActive(showPauseSettings || (showDevTools && showSideTools));
            }
        }

        private static bool ShouldShowRotationTiltSetting(
            bool devToolsEnabled,
            bool isMobilePlatform,
            bool supportsAccelerometer)
        {
            return devToolsEnabled || (isMobilePlatform && supportsAccelerometer);
        }

