        private void UpdateRunGauges(GreedLastRunSnapshot snapshot)
        {
            if (runGaugeRoot == null)
            {
                return;
            }

            runGaugeRoot.SetActive(true);
            TrackRunGaugeValueChanges(snapshot);
            int healthMax = Mathf.Max(1, snapshot.MaxHealth);
            float healthRatio = healthMax <= 0 ? 0f : Mathf.Clamp01(snapshot.Health / (float)healthMax);
            float focusRatio = snapshot.FocusStateActive
                ? Mathf.Clamp01(snapshot.FocusStateRemainingSeconds / FocusStateUiDurationSeconds)
                : snapshot.MaxFocus <= 0 ? 0f : Mathf.Clamp01(snapshot.Focus / (float)snapshot.MaxFocus);
            SetGaugeFill(healthGaugeFill, healthRatio);
            SetGaugeFill(focusGaugeFill, focusRatio);

            if (healthGaugeFill != null)
            {
                healthGaugeFill.color = snapshot.Health <= 1
                    ? new Color32(207, 87, 65, 235)
                    : new Color32(218, 86, 68, 220);
                ApplyRunGaugePulse(healthGaugeFill, healthGaugeText, BuildRunGaugePulse(healthGaugePulseUntil), new Color32(255, 170, 150, 255));
            }

            if (focusGaugeFill != null)
            {
                focusGaugeFill.color = snapshot.FocusStateActive
                    ? new Color32(255, 196, 74, 235)
                    : new Color32(86, 158, 184, 220);
                ApplyRunGaugePulse(focusGaugeFill, focusGaugeText, BuildRunGaugePulse(focusGaugePulseUntil), new Color32(145, 231, 199, 255));
            }

            if (healthGaugeText != null)
            {
                healthGaugeText.text = GetHealthGaugeLabel(snapshot);
            }

            if (focusGaugeText != null)
            {
                focusGaugeText.text = GetFocusGaugeLabel(snapshot);
            }

            UpdateHealthDangerPips(snapshot);
            ApplyFocusStateGaugePulse(snapshot, focusRatio);
            UpdateFocusStateTimerPips(snapshot);
        }

        private string GetHealthGaugeLabel(GreedLastRunSnapshot snapshot)
        {
            int maxHealth = Mathf.Max(1, snapshot.MaxHealth);
            if (cachedHealthGaugeLabel == null || cachedGaugeHealth != snapshot.Health
                || cachedGaugeMaxHealth != maxHealth)
            {
                cachedGaugeHealth = snapshot.Health;
                cachedGaugeMaxHealth = maxHealth;
                cachedHealthGaugeLabel = "체력 " + FormatHealthValue(snapshot);
            }
            return cachedHealthGaugeLabel;
        }

        private string GetFocusGaugeLabel(GreedLastRunSnapshot snapshot)
        {
            if (cachedFocusGaugeLabel == null || cachedGaugeFocusActive != snapshot.FocusStateActive
                || (snapshot.FocusStateActive
                    ? cachedGaugeFocusRemaining != snapshot.FocusStateRemainingSeconds
                    : cachedGaugeFocus != snapshot.Focus || cachedGaugeMaxFocus != snapshot.MaxFocus))
            {
                cachedGaugeFocus = snapshot.Focus;
                cachedGaugeMaxFocus = snapshot.MaxFocus;
                cachedGaugeFocusActive = snapshot.FocusStateActive;
                cachedGaugeFocusRemaining = snapshot.FocusStateRemainingSeconds;
                cachedFocusGaugeLabel = FormatFocusStatus(snapshot);
            }
            return cachedFocusGaugeLabel;
        }

        private void TrackRunGaugeValueChanges(GreedLastRunSnapshot snapshot)
        {
            if (lastGaugeHealth != int.MinValue && snapshot.Health != lastGaugeHealth)
            {
                healthGaugePulseUntil = Time.unscaledTime + RunGaugePulseDuration;
            }

            if (lastGaugeFocus != int.MinValue && snapshot.Focus != lastGaugeFocus)
            {
                focusGaugePulseUntil = Time.unscaledTime + RunGaugePulseDuration;
            }

            if (snapshot.FocusStateActive && !lastFocusStateActive)
            {
                focusStateActivationPulseUntil = Time.unscaledTime + FocusStateActivationPulseDuration;
                focusGaugePulseUntil = Time.unscaledTime + FocusStateActivationPulseDuration;
                beatMarkerFocusGuardUntil = Time.unscaledTime + BeatMarkerFocusGuardDuration;
                PlayClip(focusGuardClip, 0.50f);
                PlayHaptic(0.045f);
            }

            lastGaugeHealth = snapshot.Health;
            lastGaugeFocus = snapshot.Focus;
            lastFocusStateActive = snapshot.FocusStateActive;
        }

        private static float BuildRunGaugePulse(float pulseUntil)
        {
            float remaining = pulseUntil - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            return Mathf.Clamp01(remaining / RunGaugePulseDuration);
        }

        private static void ApplyRunGaugePulse(Image fillImage, Text valueText, float pulse, Color32 pulseColor)
        {
            Transform gaugeBar = fillImage != null ? fillImage.transform.parent : null;
            if (pulse <= 0f)
            {
                if (gaugeBar != null)
                {
                    gaugeBar.localScale = Vector3.one;
                }

                if (valueText != null)
                {
                    valueText.rectTransform.localScale = Vector3.one;
                    valueText.color = new Color32(237, 239, 231, 240);
                }

                return;
            }

            if (fillImage != null)
            {
                fillImage.color = Color32.Lerp(fillImage.color, pulseColor, pulse * 0.72f);
            }

            if (gaugeBar != null)
            {
                gaugeBar.localScale = new Vector3(1f, 1f + pulse * 0.22f, 1f);
            }

            if (valueText != null)
            {
                valueText.rectTransform.localScale = Vector3.one * (1f + pulse * 0.08f);
                valueText.color = Color32.Lerp(new Color32(237, 239, 231, 240), pulseColor, pulse * 0.8f);
            }
        }

        private void ApplyFocusStateGaugePulse(GreedLastRunSnapshot snapshot, float focusRatio)
        {
            if (!snapshot.FocusStateActive)
            {
                return;
            }

            float activationRemaining = focusStateActivationPulseUntil - Time.unscaledTime;
            float activationPulse = activationRemaining > 0f
                ? Mathf.Sin(Mathf.Clamp01(activationRemaining / FocusStateActivationPulseDuration) * Mathf.PI)
                : 0f;
            float livePulse = GetGameplayBeatPulse();

            if (focusGaugeFill != null)
            {
                SetGaugeFill(focusGaugeFill, focusRatio);
                focusGaugeFill.color = Color32.Lerp(
                    new Color32(255, 174, 66, 225),
                    new Color32(255, 238, 181, 250),
                    Mathf.Max(livePulse * 0.55f, activationPulse));
            }

            if (focusGaugeText != null)
            {
                focusGaugeText.text = GetFocusGaugeLabel(snapshot);
                focusGaugeText.color = Color32.Lerp(
                    new Color32(255, 214, 105, 255),
                    new Color32(255, 248, 210, 255),
                    livePulse);
                focusGaugeText.rectTransform.localScale = Vector3.one * (1f + activationPulse * 0.12f + livePulse * 0.025f);
            }
        }

        private void UpdateFocusStateTimerPips(GreedLastRunSnapshot snapshot)
        {
            if (focusStateTimerPips == null)
            {
                return;
            }

            bool visible = ShouldShowFocusStateTimerPips(snapshot);
            float beatPulse = GetGameplayBeatPulse();
            float downbeatPulse = visible && ShouldShowDownbeatPulse(snapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;

            for (int i = 0; i < focusStateTimerPips.Length; i += 1)
            {
                Image pipFill = focusStateTimerPips[i];
                if (pipFill == null)
                {
                    continue;
                }

                Image pipBack = pipFill.transform.parent != null
                    ? pipFill.transform.parent.GetComponent<Image>()
                    : null;
                float fill = BuildFocusStateTimerPipFillAmount(snapshot.FocusStateRemainingSeconds, i);
                float alpha = BuildFocusStateTimerPipAlpha(visible, fill, snapshot.FocusStateRemainingSeconds, beatPulse);
                float scale = BuildFocusStateTimerPipScale(visible, fill, snapshot.FocusStateRemainingSeconds, beatPulse);
                float downbeatLift = BuildFocusStateTimerPipDownbeatLift(
                    downbeatPulse,
                    fill,
                    snapshot.FocusStateRemainingSeconds,
                    i);
                alpha = BuildFocusStateTimerPipAlphaWithDownbeat(alpha, downbeatLift);
                scale = BuildFocusStateTimerPipScaleWithDownbeat(scale, downbeatLift);

                SetGaugeFill(pipFill, visible ? fill : 0f);
                pipFill.color = WithAlpha(
                    Color32.Lerp(
                        Color32.Lerp(
                            new Color32(255, 180, 66, 255),
                            new Color32(255, 244, 186, 255),
                            Mathf.Clamp01(beatPulse * 0.55f + fill * 0.35f)),
                        new Color32(255, 255, 226, 255),
                        BuildFocusStateTimerPipDownbeatColorBlend(downbeatLift)),
                    Mathf.RoundToInt(alpha * 255f));

                if (pipBack != null)
                {
                    pipBack.color = WithAlpha(new Color32(62, 53, 31, 255), visible ? Mathf.RoundToInt(92f + beatPulse * 18f) : 0);
                    pipBack.rectTransform.localScale = Vector3.one * scale;
                }
            }
        }

        private static bool ShouldShowFocusStateTimerPips(GreedLastRunSnapshot snapshot)
        {
            return snapshot.FocusStateActive
                && !snapshot.Stopped
                && !snapshot.Paused
                && !snapshot.CountdownActive
                && !snapshot.ChoiceActive;
        }

        private static float BuildFocusStateTimerPipFillAmount(float remainingSeconds, int pipIndex)
        {
            if (pipIndex < 0 || pipIndex >= FocusStateTimerPipCount || remainingSeconds <= 0f)
            {
                return 0f;
            }

            float segmentSeconds = FocusStateUiDurationSeconds / FocusStateTimerPipCount;
            float remainingPips = Mathf.Clamp(remainingSeconds / segmentSeconds, 0f, FocusStateTimerPipCount);
            return Mathf.Clamp01(remainingPips - pipIndex);
        }

        private static float BuildFocusStateTimerPipAlpha(bool visible, float fillAmount, float remainingSeconds, float beatPulse)
        {
            if (!visible)
            {
                return 0f;
            }

            float lowTimePulse = remainingSeconds <= 1.25f ? Mathf.Clamp01(beatPulse) * 0.18f : 0f;
            return Mathf.Clamp01(Mathf.Lerp(0.22f, 0.92f, Mathf.Clamp01(fillAmount)) + lowTimePulse);
        }

        private static float BuildFocusStateTimerPipScale(bool visible, float fillAmount, float remainingSeconds, float beatPulse)
        {
            if (!visible)
            {
                return 1f;
            }

            float activeEdge = fillAmount > 0f && fillAmount < 1f ? 0.06f : 0f;
            float lowTimePulse = remainingSeconds <= 1.25f ? Mathf.Clamp01(beatPulse) * 0.05f : 0f;
            return 1f + activeEdge + lowTimePulse;
        }

        private static float BuildFocusStateTimerPipDownbeatLift(
            float downbeatPulse,
            float fillAmount,
            float remainingSeconds,
            int pipIndex)
        {
            if (fillAmount <= 0f || remainingSeconds <= 0f || pipIndex < 0 || pipIndex >= FocusStateTimerPipCount)
            {
                return 0f;
            }

            float urgency = remainingSeconds <= 1.25f ? 1f : 0.46f;
            float edgeWeight = fillAmount < 1f ? 1f : 0.72f;
            return Mathf.Clamp01(downbeatPulse) * Mathf.Clamp01(fillAmount) * urgency * edgeWeight;
        }

        private static float BuildFocusStateTimerPipAlphaWithDownbeat(float baseAlpha, float downbeatLift)
        {
            return Mathf.Clamp01(baseAlpha + Mathf.Clamp01(downbeatLift) * 0.13f);
        }

        private static float BuildFocusStateTimerPipScaleWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.09f;
        }

        private static float BuildFocusStateTimerPipDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.44f;
        }

        private void UpdateHealthDangerPips(GreedLastRunSnapshot snapshot)
        {
            if (healthDangerPips == null)
            {
                return;
            }

            float dangerStrength = BuildHealthDangerStrength(snapshot);
            bool visible = ShouldShowHealthDangerPips(snapshot, dangerStrength);
            float beatPulse = GetGameplayBeatPulse();
            float hitPulse = BuildRunGaugePulse(healthGaugePulseUntil);
            float downbeatPulse = visible && ShouldShowDownbeatPulse(snapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;

            for (int i = 0; i < healthDangerPips.Length; i += 1)
            {
                Image pipFill = healthDangerPips[i];
                if (pipFill == null)
                {
                    continue;
                }

                Image pipBack = pipFill.transform.parent != null
                    ? pipFill.transform.parent.GetComponent<Image>()
                    : null;
                float fill = BuildHealthDangerPipFillAmount(dangerStrength, i);
                float alpha = BuildHealthDangerPipAlpha(visible, fill, dangerStrength, beatPulse, hitPulse);
                float scale = BuildHealthDangerPipScale(visible, fill, dangerStrength, beatPulse, hitPulse);
                float downbeatLift = BuildHealthDangerPipDownbeatLift(downbeatPulse, fill, dangerStrength, i);
                alpha = BuildHealthDangerPipAlphaWithDownbeat(alpha, downbeatLift);
                scale = BuildHealthDangerPipScaleWithDownbeat(scale, downbeatLift);
                Color32 fillColor = Color32.Lerp(
                    new Color32(207, 87, 65, 255),
                    new Color32(255, 170, 126, 255),
                    Mathf.Clamp01(beatPulse * 0.52f + hitPulse * 0.55f));
                fillColor = Color32.Lerp(
                    fillColor,
                    new Color32(255, 214, 105, 255),
                    BuildHealthDangerPipDownbeatColorBlend(downbeatLift));

                SetGaugeFill(pipFill, visible ? fill : 0f);
                pipFill.color = WithAlpha(fillColor, Mathf.RoundToInt(alpha * 255f));

                if (pipBack != null)
                {
                    pipBack.color = WithAlpha(new Color32(68, 31, 25, 255), visible ? Mathf.RoundToInt(72f + dangerStrength * 50f) : 0);
                    pipBack.rectTransform.localScale = Vector3.one * scale;
                }
            }
        }

        private static bool ShouldShowHealthDangerPips(GreedLastRunSnapshot snapshot, float dangerStrength)
        {
            return dangerStrength > 0f
                && !snapshot.Stopped
                && !snapshot.Paused
                && !snapshot.CountdownActive
                && !snapshot.ChoiceActive;
        }

        private static float BuildHealthDangerPipFillAmount(float dangerStrength, int pipIndex)
        {
            if (pipIndex < 0 || pipIndex >= HealthDangerPipCount || dangerStrength <= 0f)
            {
                return 0f;
            }

            float dangerPips = Mathf.Clamp01(dangerStrength) * HealthDangerPipCount;
            return Mathf.Clamp01(dangerPips - pipIndex);
        }

        private static float BuildHealthDangerPipAlpha(bool visible, float fillAmount, float dangerStrength, float beatPulse, float hitPulse)
        {
            if (!visible)
            {
                return 0f;
            }

            float baseAlpha = Mathf.Lerp(0.20f, 0.84f, Mathf.Clamp01(fillAmount));
            float dangerPulse = Mathf.Clamp01(beatPulse) * Mathf.Clamp01(dangerStrength) * 0.16f;
            float hitLift = Mathf.Clamp01(hitPulse) * 0.18f;
            return Mathf.Clamp01(baseAlpha + dangerPulse + hitLift);
        }

        private static float BuildHealthDangerPipScale(bool visible, float fillAmount, float dangerStrength, float beatPulse, float hitPulse)
        {
            if (!visible)
            {
                return 1f;
            }

            float activeEdge = fillAmount > 0f && fillAmount < 1f ? 0.06f : 0f;
            float dangerPulse = Mathf.Clamp01(beatPulse) * Mathf.Clamp01(dangerStrength) * 0.055f;
            return 1f + activeEdge + dangerPulse + Mathf.Clamp01(hitPulse) * 0.07f;
        }

        private static float BuildHealthDangerPipDownbeatLift(
            float downbeatPulse,
            float fillAmount,
            float dangerStrength,
            int pipIndex)
        {
            if (fillAmount <= 0f || dangerStrength <= 0f || pipIndex < 0 || pipIndex >= HealthDangerPipCount)
            {
                return 0f;
            }

            float indexWeight = HealthDangerPipCount <= 1
                ? 1f
                : Mathf.Lerp(1f, 0.72f, Mathf.Clamp01(pipIndex / (float)(HealthDangerPipCount - 1)));
            float dangerWeight = Mathf.Lerp(0.42f, 1f, Mathf.Clamp01(dangerStrength));
            float fillWeight = Mathf.Lerp(0.55f, 1f, Mathf.Clamp01(fillAmount));
            return Mathf.Clamp01(downbeatPulse) * dangerWeight * fillWeight * indexWeight;
        }

        private static float BuildHealthDangerPipAlphaWithDownbeat(float baseAlpha, float downbeatLift)
        {
            return Mathf.Clamp01(baseAlpha + Mathf.Clamp01(downbeatLift) * 0.12f);
        }

        private static float BuildHealthDangerPipScaleWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.08f;
        }

        private static float BuildHealthDangerPipDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.30f;
        }

        private void UpdateHealthDangerEdges()
        {
            if (healthDangerEdges == null)
            {
                return;
            }

            float dangerStrength = runModeActive && hasRunSnapshot ? BuildHealthDangerStrength(latestRunSnapshot) : 0f;
            if (!ShouldShowHealthDangerPips(latestRunSnapshot, dangerStrength))
            {
                dangerStrength = 0f;
            }

            float beatPulse = GetGameplayBeatPulse();
            float hitPulse = BuildRunGaugePulse(healthGaugePulseUntil);
            float alpha = BuildHealthDangerEdgeAlpha(dangerStrength, beatPulse, hitPulse);
            float thickness = BuildHealthDangerEdgeThickness(dangerStrength, beatPulse, hitPulse);
            float inset = BuildHealthDangerEdgeInset(dangerStrength, beatPulse, hitPulse);
            float downbeatPulse = dangerStrength > 0f && ShouldShowDownbeatPulse(latestRunSnapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;
            float downbeatLift = BuildHealthDangerEdgeDownbeatLift(downbeatPulse, dangerStrength);
            alpha = BuildHealthDangerEdgeAlphaWithDownbeat(alpha, downbeatLift);
            thickness = BuildHealthDangerEdgeThicknessWithDownbeat(thickness, downbeatLift);
            inset = BuildHealthDangerEdgeInsetWithDownbeat(inset, downbeatLift);
            Color32 baseColor = Color32.Lerp(
                new Color32(154, 84, 63, 255),
                new Color32(255, 128, 94, 255),
                Mathf.Clamp01(beatPulse * dangerStrength + hitPulse * 0.75f));
            baseColor = Color32.Lerp(
                baseColor,
                new Color32(255, 178, 96, 255),
                BuildHealthDangerEdgeDownbeatColorBlend(downbeatLift));

            for (int i = 0; i < healthDangerEdges.Length; i += 1)
            {
                Image edge = healthDangerEdges[i];
                if (edge == null)
                {
                    continue;
                }

                if (alpha <= 0f)
                {
                    edge.color = new Color32(207, 87, 65, 0);
                    SetHealthDangerEdgeInset(edge.rectTransform, i, 0f);
                    edge.rectTransform.localScale = Vector3.one;
                    continue;
                }

                edge.color = WithAlpha(baseColor, Mathf.RoundToInt(alpha * 255f));
                SetHealthDangerEdgeInset(edge.rectTransform, i, inset);
                bool horizontal = i < 2;
                edge.rectTransform.localScale = horizontal
                    ? new Vector3(1f, thickness, 1f)
                    : new Vector3(thickness, 1f, 1f);
            }
        }

        private static float BuildHealthDangerStrength(GreedLastRunSnapshot snapshot)
        {
            return BuildHealthDangerStrengthFromValues(
                snapshot.Health,
                snapshot.MaxHealth,
                snapshot.ActivePattern,
                snapshot.Stopped,
                snapshot.Paused,
                snapshot.ChoiceActive,
                snapshot.InfiniteMode,
                snapshot.InfiniteThreatLevel);
        }

        private static float BuildHealthDangerStrengthFromValues(
            int health,
            int maxHealth,
            bool activePattern,
            bool stopped,
            bool paused,
            bool choiceActive,
            bool infiniteMode,
            int infiniteThreatLevel)
        {
            if (stopped || paused || choiceActive || maxHealth <= 0)
            {
                return 0f;
            }

            if (health <= 0)
            {
                return 1f;
            }

            float healthRatio = Mathf.Clamp01(health / (float)Mathf.Max(1, maxHealth));
            if (healthRatio > 0.5f)
            {
                return 0f;
            }

            float strength = Mathf.InverseLerp(0.5f, 0f, healthRatio);
            if (health <= 1)
            {
                strength = Mathf.Max(strength, 0.72f);
            }

            if (activePattern)
            {
                strength += 0.08f;
            }

            if (infiniteMode)
            {
                strength += Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.10f;
            }

            return Mathf.Clamp01(strength);
        }

        private static float BuildHealthDangerEdgeAlpha(float dangerStrength, float beatPulse, float hitPulse)
        {
            dangerStrength = Mathf.Clamp01(dangerStrength);
            if (dangerStrength <= 0f)
            {
                return 0f;
            }

            float beatLift = Mathf.Lerp(0.42f, 1f, Mathf.Clamp01(beatPulse));
            float impactLift = Mathf.Clamp01(hitPulse) * 0.20f;
            return Mathf.Clamp01(dangerStrength * (0.16f + beatLift * 0.30f) + impactLift);
        }

        private static float BuildHealthDangerEdgeThickness(float dangerStrength, float beatPulse, float hitPulse)
        {
            dangerStrength = Mathf.Clamp01(dangerStrength);
            return 1f + dangerStrength * 0.17f + Mathf.Clamp01(beatPulse) * dangerStrength * 0.11f + Mathf.Clamp01(hitPulse) * 0.13f;
        }

        private static float BuildHealthDangerEdgeInset(float dangerStrength, float beatPulse, float hitPulse)
        {
            dangerStrength = Mathf.Clamp01(dangerStrength);
            if (dangerStrength <= 0f)
            {
                return 0f;
            }

            float beatLift = Mathf.Clamp01(beatPulse) * dangerStrength * 9f;
            float hitLift = Mathf.Clamp01(hitPulse) * 12f;
            return Mathf.Lerp(8f, 28f, dangerStrength) + beatLift + hitLift;
        }

        private static float BuildHealthDangerEdgeDownbeatLift(float downbeatPulse, float dangerStrength)
        {
            dangerStrength = Mathf.Clamp01(dangerStrength);
            if (dangerStrength <= 0f)
            {
                return 0f;
            }

            return Mathf.Clamp01(downbeatPulse) * Mathf.Lerp(0.35f, 1f, dangerStrength);
        }

        private static float BuildHealthDangerEdgeAlphaWithDownbeat(float baseAlpha, float downbeatLift)
        {
            return Mathf.Clamp01(baseAlpha + Mathf.Clamp01(downbeatLift) * 0.08f);
        }

        private static float BuildHealthDangerEdgeThicknessWithDownbeat(float baseThickness, float downbeatLift)
        {
            return Mathf.Max(0f, baseThickness) + Mathf.Clamp01(downbeatLift) * 0.06f;
        }

        private static float BuildHealthDangerEdgeInsetWithDownbeat(float baseInset, float downbeatLift)
        {
            return Mathf.Max(0f, baseInset) + Mathf.Clamp01(downbeatLift) * 6f;
        }

        private static float BuildHealthDangerEdgeDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.18f;
        }

        private static void SetHealthDangerEdgeInset(RectTransform rect, int edgeIndex, float inset)
        {
            if (rect == null)
            {
                return;
            }

            float safeInset = Mathf.Max(0f, inset);
            switch (edgeIndex)
            {
                case 0:
                    rect.offsetMin = new Vector2(0f, -safeInset);
                    rect.offsetMax = Vector2.zero;
                    break;
                case 1:
                    rect.offsetMin = Vector2.zero;
                    rect.offsetMax = new Vector2(0f, safeInset);
                    break;
                case 2:
                    rect.offsetMin = Vector2.zero;
                    rect.offsetMax = new Vector2(safeInset, 0f);
                    break;
                case 3:
                    rect.offsetMin = new Vector2(-safeInset, 0f);
                    rect.offsetMax = Vector2.zero;
                    break;
                default:
                    rect.offsetMin = Vector2.zero;
                    rect.offsetMax = Vector2.zero;
                    break;
            }
        }

        private void UpdateRunProgress(GreedLastRunSnapshot snapshot)
        {
            if (runProgressRoot == null)
            {
                return;
            }

            runProgressRoot.SetActive(true);
            int target = Mathf.Max(1, snapshot.ChapterTarget);
            float ratio = Mathf.Clamp01(snapshot.ChapterProgress / (float)target);
            bool compact = (!DevToolsEnabled || devCleanViewEnabled) && !snapshot.Stopped;
            string label;
            TrackRunProgressStageState(snapshot);
            TrackThreatProgressState(snapshot);
            float threatPulse = BuildThreatProgressPulse(snapshot);
            float stagePulse = BuildRunProgressStagePulse();
            float forwardPulse = BuildForwardPayoffBurstPulse(forwardPayoffBurstUntil - Time.unscaledTime, forwardPayoffBurstStrength);
            float progressDownbeatPulse = ShouldShowDownbeatPulse(snapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;
            float progressDownbeatLift = BuildRunProgressDownbeatLift(snapshot, progressDownbeatPulse, stagePulse);
            bool threatAlert = threatPulse > 0f;

            if (compact)
            {
                label = BuildCompactRunProgressLabel(snapshot, target);
            }
            else if (snapshot.PracticeMode)
            {
                if (snapshot.Stopped)
                {
                    bool completed = snapshot.Phase == GreedLastRunPhase.ClearResolving;
                    ratio = completed ? 1f : ratio;
                    label = completed ? BuildPracticeCompletionProgressLabel(snapshot) : "기초연습 중단";
                }
                else
                {
                    label = BuildPracticeProgressLabel(snapshot, target);
                }
            }
            else if (snapshot.Stopped)
            {
                if (snapshot.InfiniteMode)
                {
                    int resolvedCurrentSegment = snapshot.CurrentSegmentExactCount
                        + snapshot.CurrentSegmentGoodCount
                        + snapshot.CurrentSegmentMissCount;
                    ratio = Mathf.Clamp01(Mathf.Max(snapshot.ChapterProgress, resolvedCurrentSegment) / (float)target);
                    label = $"무한 종료  {snapshot.InfiniteSectionsCleared}구간 / 위협 {snapshot.InfiniteThreatLevel}"
                        + BuildStoppedInfiniteSegmentPerformance(snapshot);
                }
                else
                {
                    ratio = snapshot.SaveEligible ? 1f : ratio;
                    label = snapshot.SaveEligible ? BuildStoppedNormalProgressLabel(snapshot) : "런 중단";
                }
            }
            else if (snapshot.InfiniteMode)
            {
                label = BuildInfiniteProgressLabel(snapshot, target);
            }
            else if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                label = BuildEscapeProgressLabel(snapshot, target);
            }
            else if (snapshot.Phase == GreedLastRunPhase.ClearResolving)
            {
                ratio = 1f;
                label = "탈출 완료";
            }
            else
            {
                label = BuildNormalProgressLabel(snapshot, target);
            }

            if (threatAlert)
            {
                label = BuildThreatProgressAlertLabel(snapshot.InfiniteThreatLevel, threatProgressDirection);
            }

            SetGaugeFill(runProgressFill, ratio);
            Color32 progressColor = snapshot.InfiniteMode
                ? snapshot.Stopped && snapshot.Health <= 0
                    ? new Color32(207, 87, 65, 230)
                    : new Color32(205, 166, 70, 225)
                : snapshot.Phase == GreedLastRunPhase.EscapeRunning || snapshot.Phase == GreedLastRunPhase.ClearResolving
                    ? new Color32(255, 238, 181, 230)
                    : new Color32(104, 151, 142, 220);
            if (runProgressFill != null)
            {
                if (threatAlert)
                {
                    Color32 alertColor = threatProgressDirection >= 0
                        ? new Color32(232, 92, 56, 238)
                        : new Color32(85, 171, 190, 232);
                    progressColor = Color32.Lerp(progressColor, alertColor, threatPulse * 0.85f);
                }
                else if (stagePulse > 0f)
                {
                    progressColor = Color32.Lerp(progressColor, new Color32(255, 238, 181, 238), stagePulse * 0.58f);
                }

                runProgressFill.color = progressColor;
            }

            if (runProgressText != null)
            {
                runProgressText.text = label;
                runProgressText.fontSize = compact ? 34 : BuildRunProgressFontSize(label);
                SetAnchored(runProgressRoot.GetComponent<RectTransform>(), 0.5f, compact ? 0.69f : 0.715f, 760f, 64f);
                SetAnchored(runProgressText.rectTransform, 0.5f, compact ? 1.3f : 1.1f, 720f, compact ? 56f : 40f);
                Color32 baseTextColor = new Color32(218, 226, 218, 230);
                float downbeatTextBlend = BuildRunProgressDownbeatColorBlend(progressDownbeatLift);
                int textAlpha = BuildRunProgressTextAlpha(230, progressDownbeatLift);
                Color32 textColor;
                if (threatAlert)
                {
                    textColor = Color32.Lerp(
                        baseTextColor,
                        threatProgressDirection >= 0
                            ? new Color32(255, 211, 154, 255)
                            : new Color32(178, 232, 238, 255),
                        threatPulse);
                    textColor = Color32.Lerp(textColor, new Color32(255, 238, 181, 255), downbeatTextBlend * 0.50f);
                }
                else
                {
                    float stageTextBlend = stagePulse * 0.72f;
                    textColor = Mathf.Max(stageTextBlend, downbeatTextBlend) > 0f
                        ? Color32.Lerp(baseTextColor, new Color32(255, 248, 210, 255), Mathf.Max(stageTextBlend, downbeatTextBlend))
                        : baseTextColor;
                }

                runProgressText.color = WithAlpha(textColor, textAlpha);
                runProgressText.rectTransform.localScale = Vector3.one * BuildRunProgressTextScale(stagePulse, progressDownbeatLift);
            }

            UpdateRouteCadencePips(snapshot, stagePulse);
            UpdateInfiniteThreatPips(snapshot, threatPulse);
            UpdateEscapeGatePips(snapshot, stagePulse, forwardPulse);

            float scale = 1f + Mathf.Max(
                threatPulse * 0.055f,
                Mathf.Max(stagePulse * 0.045f, Mathf.Max(forwardPulse * 0.040f, progressDownbeatLift * 0.018f)));
            runProgressRoot.transform.localScale = Vector3.one * scale;
        }

        private void UpdateEscapeGatePips(GreedLastRunSnapshot snapshot, float stagePulse, float forwardPulse)
        {
            if (escapeGatePips == null)
            {
                return;
            }

            bool visible = ShouldShowEscapeGatePips(snapshot);
            float beatPulse = GetGameplayBeatPulse();
            float downbeatPulse = visible && ShouldShowDownbeatPulse(snapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;
            int target = Mathf.Max(1, snapshot.ChapterTarget);
            int gateProgress = BuildEscapeGateVisibleProgress(snapshot);

            for (int i = 0; i < escapeGatePips.Length; i += 1)
            {
                Image pipFill = escapeGatePips[i];
                if (pipFill == null)
                {
                    continue;
                }

                Image pipBack = pipFill.transform.parent != null
                    ? pipFill.transform.parent.GetComponent<Image>()
                    : null;
                float fill = BuildEscapeGatePipFillAmount(gateProgress, target, i);
                float readinessPulse = BuildEscapeGatePipReadinessPulse(
                    visible,
                    gateProgress,
                    target,
                    i,
                    snapshot.CoreDeltaSeconds,
                    snapshot.Pattern.GoodWindowSeconds,
                    stagePulse,
                    forwardPulse);
                float downbeatLift = BuildEscapeGatePipDownbeatLift(
                    downbeatPulse,
                    visible,
                    fill,
                    readinessPulse,
                    i,
                    gateProgress,
                    target);
                float alpha = BuildEscapeGatePipAlphaWithDownbeat(
                    BuildEscapeGatePipAlphaWithReadiness(visible, fill, beatPulse, stagePulse, forwardPulse, readinessPulse),
                    downbeatLift);
                float scale = BuildEscapeGatePipScaleWithDownbeat(
                    BuildEscapeGatePipScaleWithReadiness(visible, fill, beatPulse, stagePulse, forwardPulse, readinessPulse),
                    downbeatLift);
                Color32 fillColor = Color32.Lerp(
                    new Color32(104, 151, 142, 255),
                    new Color32(255, 238, 181, 255),
                    Mathf.Clamp01(fill * 0.72f + stagePulse * 0.32f + forwardPulse * 0.20f + readinessPulse * 0.34f));
                fillColor = Color32.Lerp(
                    fillColor,
                    new Color32(255, 255, 226, 255),
                    BuildEscapeGatePipDownbeatColorBlend(downbeatLift));

                SetGaugeFill(pipFill, visible ? fill : 0f);
                pipFill.color = WithAlpha(fillColor, Mathf.RoundToInt(alpha * 255f));

                if (pipBack != null)
                {
                    Color32 backColor = Color32.Lerp(
                        new Color32(35, 41, 33, 255),
                        new Color32(88, 76, 44, 255),
                        BuildEscapeGatePipBackDownbeatColorBlend(downbeatLift));
                    pipBack.color = WithAlpha(
                        backColor,
                        visible ? Mathf.RoundToInt(68f + fill * 42f + downbeatLift * 34f) : 0);
                    pipBack.rectTransform.localScale = Vector3.one * scale;
                }
            }
        }

        private static int BuildEscapeGateVisibleProgress(GreedLastRunSnapshot snapshot)
        {
            int target = Mathf.Max(1, snapshot.ChapterTarget);
            return snapshot.EscapeSucceeded
                ? target
                : Mathf.Clamp(snapshot.ChapterProgress, 0, target);
        }

        private static bool ShouldShowEscapeGatePips(GreedLastRunSnapshot snapshot)
        {
            bool activeEscape = snapshot.Phase == GreedLastRunPhase.EscapeRunning
                && !snapshot.Stopped;
            bool clearSummary = snapshot.Phase == GreedLastRunPhase.ClearResolving
                && snapshot.EscapeSucceeded;
            return snapshot.CoreRetrieved
                && !snapshot.InfiniteMode
                && !snapshot.Paused
                && !snapshot.CountdownActive
                && !snapshot.ChoiceActive
                && (activeEscape || clearSummary);
        }

        private static float BuildEscapeGatePipFillAmount(int progress, int target, int pipIndex)
        {
            if (pipIndex < 0 || pipIndex >= EscapeGatePipCount)
            {
                return 0f;
            }

            float gateProgress = Mathf.Clamp01(progress / (float)Mathf.Max(1, target)) * EscapeGatePipCount;
            return Mathf.Clamp01(gateProgress - pipIndex);
        }

        private static float BuildEscapeGatePipAlpha(bool visible, float fillAmount, float beatPulse, float stagePulse, float forwardPulse)
        {
            if (!visible)
            {
                return 0f;
            }

            float baseAlpha = Mathf.Lerp(0.20f, 0.88f, Mathf.Clamp01(fillAmount));
            float beatLift = Mathf.Clamp01(beatPulse) * Mathf.Clamp01(fillAmount) * 0.06f;
            return Mathf.Clamp01(baseAlpha + beatLift + Mathf.Clamp01(stagePulse) * 0.16f + Mathf.Clamp01(forwardPulse) * 0.12f);
        }

        private static float BuildEscapeGatePipAlphaWithReadiness(
            bool visible,
            float fillAmount,
            float beatPulse,
            float stagePulse,
            float forwardPulse,
            float readinessPulse)
        {
            return Mathf.Clamp01(BuildEscapeGatePipAlpha(visible, fillAmount, beatPulse, stagePulse, forwardPulse)
                + Mathf.Clamp01(readinessPulse) * 0.24f);
        }

        private static float BuildEscapeGatePipScale(bool visible, float fillAmount, float beatPulse, float stagePulse, float forwardPulse)
        {
            if (!visible)
            {
                return 1f;
            }

            float activeEdge = fillAmount > 0f && fillAmount < 1f ? 0.055f : 0f;
            float filledPulse = Mathf.Clamp01(beatPulse) * Mathf.Clamp01(fillAmount) * 0.030f;
            return 1f + activeEdge + filledPulse + Mathf.Clamp01(stagePulse) * 0.08f + Mathf.Clamp01(forwardPulse) * 0.055f;
        }

        private static float BuildEscapeGatePipScaleWithReadiness(
            bool visible,
            float fillAmount,
            float beatPulse,
            float stagePulse,
            float forwardPulse,
            float readinessPulse)
        {
            return BuildEscapeGatePipScale(visible, fillAmount, beatPulse, stagePulse, forwardPulse)
                + Mathf.Clamp01(readinessPulse) * 0.13f;
        }

        private static float BuildEscapeGatePipDownbeatLift(
            float downbeatPulse,
            bool visible,
            float fillAmount,
            float readinessPulse,
            int pipIndex,
            int progress,
            int target)
        {
            if (!visible || pipIndex < 0 || pipIndex >= EscapeGatePipCount)
            {
                return 0f;
            }

            int safeTarget = Mathf.Max(1, target);
            int clampedProgress = Mathf.Clamp(progress, 0, safeTarget);
            bool completion = clampedProgress >= safeTarget;
            int activeIndex = completion
                ? EscapeGatePipCount - 1
                : Mathf.Clamp(clampedProgress, 0, EscapeGatePipCount - 1);
            bool activePip = pipIndex == activeIndex;
            bool filledPip = fillAmount > 0f;
            if (!activePip && !filledPip)
            {
                return 0f;
            }

            float fillWeight = filledPip
                ? Mathf.Lerp(0.46f, 1f, Mathf.Clamp01(fillAmount))
                : 0.34f;
            float activeWeight = activePip ? 1f : 0.52f;
            float readinessWeight = activePip
                ? Mathf.Lerp(0.66f, 1f, Mathf.Clamp01(readinessPulse))
                : 0.46f;
            float completionWeight = completion && activePip ? 1.12f : 1f;
            return Mathf.Clamp01(Mathf.Clamp01(downbeatPulse) * fillWeight * activeWeight * readinessWeight * completionWeight);
        }

        private static float BuildEscapeGatePipAlphaWithDownbeat(float baseAlpha, float downbeatLift)
        {
            return Mathf.Clamp01(baseAlpha + Mathf.Clamp01(downbeatLift) * 0.17f);
        }

        private static float BuildEscapeGatePipScaleWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.11f;
        }

        private static float BuildEscapeGatePipDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.42f;
        }

        private static float BuildEscapeGatePipBackDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.56f;
        }

        private static float BuildEscapeGatePipReadinessPulse(
            bool visible,
            int progress,
            int target,
            int pipIndex,
            float coreDeltaSeconds,
            float goodWindowSeconds,
            float stagePulse,
            float forwardPulse)
        {
            int safeTarget = Mathf.Max(1, target);
            int clampedProgress = Mathf.Clamp(progress, 0, safeTarget);
            if (!visible
                || clampedProgress >= safeTarget
                || pipIndex != Mathf.Clamp(clampedProgress, 0, EscapeGatePipCount - 1))
            {
                return 0f;
            }

            float safeGoodWindow = Mathf.Max(0.04f, goodWindowSeconds);
            float approach = Mathf.Clamp01(1f - Mathf.Max(0f, -coreDeltaSeconds) / (safeGoodWindow * 4.6f));
            float proximity = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / (safeGoodWindow * 2.2f));
            return Mathf.Clamp01(
                proximity * 0.58f
                    + approach * 0.22f
                    + Mathf.Clamp01(stagePulse) * 0.10f
                    + Mathf.Clamp01(forwardPulse) * 0.10f);
        }

        private void UpdateInfiniteThreatPips(GreedLastRunSnapshot snapshot, float threatPulse)
        {
            if (infiniteThreatPips == null)
            {
                return;
            }

            bool visible = ShouldShowInfiniteThreatPips(snapshot);
            int threatLevel = Mathf.Clamp(snapshot.InfiniteThreatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel);
            float threatStrength = Mathf.Clamp01((threatLevel - InfiniteThreatUiMinLevel) / (float)(InfiniteThreatUiMaxLevel - InfiniteThreatUiMinLevel));
            Color32 fillColor = Color32.Lerp(new Color32(205, 166, 70, 255), new Color32(232, 92, 56, 255), threatStrength);

            for (int i = 0; i < infiniteThreatPips.Length; i += 1)
            {
                Image pipFill = infiniteThreatPips[i];
                if (pipFill == null)
                {
                    continue;
                }

                Image pipBack = pipFill.transform.parent != null
                    ? pipFill.transform.parent.GetComponent<Image>()
                    : null;
                float fill = BuildInfiniteThreatPipFillAmount(threatLevel, i);
                float alpha = BuildInfiniteThreatPipAlpha(visible, threatLevel, i, threatPulse);
                float scale = BuildInfiniteThreatPipScale(visible, threatLevel, i, threatPulse);
                float offsetY = BuildInfiniteThreatPipOffsetY(visible, threatLevel, i, threatPulse, threatProgressDirection);
                SetGaugeFill(pipFill, visible ? fill : 0f);
                pipFill.color = WithAlpha(fillColor, Mathf.RoundToInt(alpha * 255f));

                if (pipBack != null)
                {
                    pipBack.color = WithAlpha(new Color32(47, 38, 24, 255), visible ? 74 : 0);
                    pipBack.rectTransform.anchoredPosition = new Vector2(0f, offsetY);
                    pipBack.rectTransform.localScale = Vector3.one * scale;
                }
            }
        }

        private static bool ShouldShowInfiniteThreatPips(GreedLastRunSnapshot snapshot)
        {
            return ShouldShowInfiniteThreatPipsForValues(
                snapshot.InfiniteMode,
                snapshot.PracticeMode,
                snapshot.ChoiceActive,
                snapshot.CountdownActive,
                snapshot.Paused,
                snapshot.Stopped);
        }

        private static bool ShouldShowInfiniteThreatPipsForValues(
            bool infiniteMode,
            bool practiceMode,
            bool choiceActive,
            bool countdownActive,
            bool paused,
            bool stopped)
        {
            return infiniteMode
                && !practiceMode
                && !choiceActive
                && !countdownActive
                && !paused
                && !stopped;
        }

        private static float BuildInfiniteThreatPipFillAmount(int threatLevel, int pipIndex)
        {
            if (pipIndex < 0 || pipIndex >= InfiniteThreatUiMaxLevel)
            {
                return 0f;
            }

            int safeThreatLevel = Mathf.Clamp(threatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel);
            return pipIndex < safeThreatLevel ? 1f : 0f;
        }

        private static float BuildInfiniteThreatPipAlpha(bool visible, int threatLevel, int pipIndex, float threatPulse)
        {
            if (!visible)
            {
                return 0f;
            }

            float fill = BuildInfiniteThreatPipFillAmount(threatLevel, pipIndex);
            float activePulse = pipIndex == Mathf.Clamp(threatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel) - 1
                ? Mathf.Clamp01(threatPulse) * 0.24f
                : 0f;
            float highThreatLift = threatLevel >= 4 && fill > 0f ? 0.08f : 0f;
            return Mathf.Clamp01(Mathf.Lerp(0.18f, 0.78f, fill) + activePulse + highThreatLift);
        }

        private static float BuildInfiniteThreatPipScale(bool visible, int threatLevel, int pipIndex, float threatPulse)
        {
            if (!visible)
            {
                return 1f;
            }

            bool activePip = pipIndex == Mathf.Clamp(threatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel) - 1;
            float pulse = activePip ? Mathf.Clamp01(threatPulse) * 0.16f : 0f;
            float highThreatPressure = threatLevel >= 4 && pipIndex < threatLevel ? 0.035f : 0f;
            return 1f + pulse + highThreatPressure;
        }

        private static float BuildInfiniteThreatPipOffsetY(
            bool visible,
            int threatLevel,
            int pipIndex,
            float threatPulse,
            int direction)
        {
            if (!visible || direction == 0)
            {
                return 0f;
            }

            int safeThreatLevel = Mathf.Clamp(threatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel);
            if (pipIndex != safeThreatLevel - 1)
            {
                return 0f;
            }

            float threatStrength = Mathf.Clamp01((safeThreatLevel - InfiniteThreatUiMinLevel) / (float)(InfiniteThreatUiMaxLevel - InfiniteThreatUiMinLevel));
            float signedDirection = direction > 0 ? 1f : -1f;
            return signedDirection * Mathf.Clamp01(threatPulse) * Mathf.Lerp(5f, 12f, threatStrength);
        }

        private void UpdateRouteCadencePips(GreedLastRunSnapshot snapshot, float stagePulse)
        {
            if (routeCadencePipsRoot == null || routeCadencePips == null)
            {
                return;
            }

            bool visible = BuildRouteCadencePipState(snapshot, 0) != "hidden";
            routeCadencePipsRoot.SetActive(visible);
            if (!visible || !TryBuildHudCadence(snapshot, out GreedLastTimingType[] timings))
            {
                return;
            }

            for (int i = 0; i < routeCadencePips.Length; i += 1)
            {
                Image pip = routeCadencePips[i];
                if (pip == null)
                {
                    continue;
                }

                string state = BuildRouteCadencePipState(snapshot, i);
                Color32 timingColor = BuildRouteCadencePipTimingColor(timings[i]);
                Text actionText = routeCadenceActionTexts != null && i < routeCadenceActionTexts.Length
                    ? routeCadenceActionTexts[i]
                    : null;
                if (actionText != null)
                {
                    actionText.text = BuildRouteCadencePipActionSymbol(snapshot, i);
                }
                float readinessPulse = BuildRouteCadencePipReadinessPulse(
                    state,
                    snapshot.CoreDeltaSeconds,
                    snapshot.Pattern.GoodWindowSeconds,
                    stagePulse);
                switch (state)
                {
                    case "done":
                        pip.color = WithAlpha(timingColor, 238);
                        pip.rectTransform.localScale = Vector3.one;
                        SetRouteCadenceActionStyle(actionText, new Color32(16, 24, 26, 245), 1f);
                        break;
                    case "broken":
                        pip.color = new Color32(207, 87, 65, 242);
                        pip.rectTransform.localScale = Vector3.one;
                        SetRouteCadenceActionStyle(actionText, new Color32(255, 238, 231, 245), 1f);
                        break;
                    case "active":
                        pip.color = Color32.Lerp(
                            timingColor,
                            new Color32(255, 248, 210, 255),
                            BuildRouteCadencePipActiveColorBlend(readinessPulse));
                        pip.rectTransform.localScale = Vector3.one * BuildRouteCadencePipActiveScale(stagePulse, readinessPulse);
                        SetRouteCadenceActionStyle(
                            actionText,
                            new Color32(20, 28, 30, 255),
                            BuildRouteCadencePipActiveActionScale(stagePulse, readinessPulse));
                        break;
                    default:
                        pip.color = WithAlpha(timingColor, 76);
                        pip.rectTransform.localScale = Vector3.one * 0.78f;
                        SetRouteCadenceActionStyle(actionText, WithAlpha(new Color32(218, 226, 218, 255), 118), 0.82f);
                        break;
                }
            }
        }

        private static void SetRouteCadenceActionStyle(Text actionText, Color32 color, float scale)
        {
            if (actionText == null)
            {
                return;
            }

            actionText.color = color;
            actionText.rectTransform.localScale = Vector3.one * scale;
        }

        private static float BuildRouteCadencePipReadinessPulse(
            string state,
            float coreDeltaSeconds,
            float goodWindowSeconds,
            float stagePulse)
        {
            if (state != "active")
            {
                return 0f;
            }

            float safeGoodWindow = Mathf.Max(0.04f, goodWindowSeconds);
            float approach = Mathf.Clamp01(1f - Mathf.Max(0f, -coreDeltaSeconds) / (safeGoodWindow * 4.5f));
            float proximity = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / (safeGoodWindow * 2.15f));
            return Mathf.Clamp01(proximity * 0.60f + approach * 0.24f + Mathf.Clamp01(stagePulse) * 0.16f);
        }

        private static float BuildRouteCadencePipActiveColorBlend(float readinessPulse)
        {
            return Mathf.Clamp01(0.42f + Mathf.Clamp01(readinessPulse) * 0.28f);
        }

        private static float BuildRouteCadencePipActiveScale(float stagePulse, float readinessPulse)
        {
            return 1.24f + Mathf.Clamp01(stagePulse) * 0.10f + Mathf.Clamp01(readinessPulse) * 0.14f;
        }

        private static float BuildRouteCadencePipActiveActionScale(float stagePulse, float readinessPulse)
        {
            return 1.18f + Mathf.Clamp01(stagePulse) * 0.06f + Mathf.Clamp01(readinessPulse) * 0.10f;
        }

        private static string BuildRouteCadencePipState(GreedLastRunSnapshot snapshot, int index)
        {
            if (index < 0
                || index >= 3
                || snapshot.InfiniteMode
                || snapshot.ChoiceActive
                || snapshot.Stopped
                || snapshot.Paused
                || snapshot.CountdownActive
                || !TryBuildHudCadence(snapshot, out _))
            {
                return "hidden";
            }

            int progress = Mathf.Clamp(snapshot.ChapterProgress, 0, 3);
            if (index < progress)
            {
                return snapshot.PracticeMode || snapshot.PerfectBundleIntact ? "done" : "broken";
            }

            return index == progress ? "active" : "pending";
        }

        private static bool TryBuildHudCadence(
            GreedLastRunSnapshot snapshot,
            out GreedLastTimingType[] timings)
        {
            if (snapshot.PracticeMode || !snapshot.InfiniteMode && snapshot.ChapterIndex == 1)
            {
                timings = new[]
                {
                    GreedLastTimingType.Perfect,
                    GreedLastTimingType.Clutch,
                    GreedLastTimingType.Offbeat,
                };
                return true;
            }

            return TryBuildRouteCadence(snapshot, out _, out timings);
        }

        private static string BuildRouteCadencePipActionSymbol(GreedLastRunSnapshot snapshot, int index)
        {
            if (index < 0 || index >= 3 || !TryBuildHudAvoidanceCadence(snapshot, out GreedLastAvoidanceType[] actions))
            {
                return string.Empty;
            }

            switch (actions[index])
            {
                case GreedLastAvoidanceType.Jump:
                    return "↑";
                case GreedLastAvoidanceType.Slide:
                    return "↓";
                case GreedLastAvoidanceType.Twist:
                    return "↔";
                default:
                    return string.Empty;
            }
        }

        private static bool TryBuildHudAvoidanceCadence(
            GreedLastRunSnapshot snapshot,
            out GreedLastAvoidanceType[] actions)
        {
            actions = null;
            if (!TryBuildHudCadence(snapshot, out _))
            {
                return false;
            }

            bool finalValidation = snapshot.Phase == GreedLastRunPhase.EscapeRunning || snapshot.ChapterIndex >= 4;
            int authoredChapter = snapshot.PracticeMode || snapshot.ChapterIndex <= 1
                ? 1
                : finalValidation ? 4 : snapshot.ChapterIndex;
            actions = new GreedLastAvoidanceType[3];
            for (int i = 0; i < actions.Length; i += 1)
            {
                actions[i] = GreedLastRunCore.GetAuthoredAvoidanceType(
                    authoredChapter,
                    i,
                    snapshot.PracticeMode,
                    false,
                    finalValidation,
                    snapshot.ActiveRouteProfile);
            }

            return true;
        }

        private static Color32 BuildRouteCadencePipTimingColor(GreedLastTimingType timingType)
        {
            switch (timingType)
            {
                case GreedLastTimingType.Perfect:
                    return new Color32(105, 188, 174, 255);
                case GreedLastTimingType.Clutch:
                    return new Color32(232, 143, 83, 255);
                case GreedLastTimingType.Offbeat:
                    return new Color32(170, 132, 209, 255);
                default:
                    return new Color32(125, 139, 143, 255);
            }
        }

        private static string BuildNormalProgressLabel(GreedLastRunSnapshot snapshot, int target)
        {
            if (snapshot.ChoiceActive)
            {
                return BuildChoiceScreenTitle(snapshot) + " · 챕터 " + snapshot.ChapterIndex;
            }

            if (snapshot.CoreRetrieved)
            {
                return "탈출 준비  공명핵 회수";
            }

            int remaining = Mathf.Max(0, target - snapshot.ChapterProgress);
            string rolePrefix = BuildChapterProgressRolePrefix(snapshot.ChapterIndex) + " · ";
            if (remaining <= 1)
            {
                return rolePrefix
                    + (snapshot.ChapterIndex >= 4 ? "공명핵 직전 " : "선택지 직전 ")
                    + snapshot.ChapterProgress + "/" + target
                    + "  다음 통과";
            }

            return rolePrefix + "공명핵 준비 "
                + snapshot.ChapterProgress + "/" + target
                + "  남은 함정 " + remaining;
        }

        private static string BuildCompactRunProgressLabel(GreedLastRunSnapshot snapshot, int target)
        {
            int progress = Mathf.Clamp(snapshot.ChapterProgress, 0, target);
            if (snapshot.ChoiceActive)
            {
                return BuildChoiceScreenTitle(snapshot);
            }

            if (snapshot.PracticeMode)
            {
                return "연습 " + (Mathf.Min(progress, target - 1) + 1) + "/" + target;
            }

            if (snapshot.InfiniteMode)
            {
                int threat = Mathf.Clamp(snapshot.InfiniteThreatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel);
                return (snapshot.InfiniteSectionsCleared + 1) + "구간 · " + progress + "/" + target + " · 위협 " + threat;
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                return "탈출 · " + progress + "/" + target;
            }

            if (snapshot.CoreRetrieved)
            {
                return "공명핵 회수";
            }

            return Mathf.Clamp(snapshot.ChapterIndex, 1, 4) + "장 · " + progress + "/" + target;
        }

        private static string BuildChapterProgressRolePrefix(int chapterIndex)
        {
            switch (Mathf.Clamp(chapterIndex, 1, 4))
            {
                case 1:
                    return "학습";
                case 2:
                    return "방향 형성";
                case 3:
                    return "변주 정점";
                default:
                    return "공명핵 검증";
            }
        }

        private static string BuildEscapeProgressLabel(GreedLastRunSnapshot snapshot, int target)
        {
            return "탈출 검증 · " + BuildEscapeGateProgressText(snapshot, target) + "  공명핵 회수";
        }

        private static string BuildStoppedNormalProgressLabel(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.EscapeSucceeded)
            {
                return "탈출 완료";
            }

            int target = Mathf.Max(1, snapshot.ChapterTarget);
            int progress = BuildEscapeGateVisibleProgress(snapshot);
            return "탈출 게이트 " + progress + "/" + target + " 완료 · 입구로 나가기";
        }

        private static string BuildInfiniteProgressLabel(GreedLastRunSnapshot snapshot, int target)
        {
            int remaining = Mathf.Max(0, target - snapshot.ChapterProgress);
            string prefix = remaining <= 1 ? "무한 정산 직전 " : "무한 생존 ";
            int threatLevel = Mathf.Clamp(snapshot.InfiniteThreatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel);
            return prefix + snapshot.ChapterProgress + "/" + target
                + "  위협 " + threatLevel + "/5 " + BuildInfiniteThreatReadPressureLabel(threatLevel)
                + " 폭" + BuildInfiniteThreatDangerWidthLabel(threatLevel)
                + " " + BuildInfiniteThreatRewardPreview(threatLevel)
                + BuildCurrentInfiniteSegmentPerformance(snapshot)
                + BuildInfiniteThreatProgressPreview(snapshot);
        }

        private static int BuildRunProgressFontSize(string label)
        {
            if (string.IsNullOrEmpty(label))
            {
                return 24;
            }

            return label.Length >= 20 ? 20 : label.Length >= 16 ? 22 : 24;
        }

        private static float BuildRunProgressDownbeatLift(
            GreedLastRunSnapshot snapshot,
            float downbeatPulse,
            float stagePulse)
        {
            return BuildRunProgressDownbeatLiftFromValues(
                snapshot.ActivePattern,
                snapshot.Pattern.IsValid,
                snapshot.Stopped,
                snapshot.Paused,
                snapshot.CountdownActive,
                snapshot.ChoiceActive,
                snapshot.CoreDeltaSeconds,
                snapshot.Pattern.GoodWindowSeconds,
                snapshot.Pattern.SuccessWindowSeconds,
                snapshot.Health,
                snapshot.InfiniteMode,
                snapshot.InfiniteThreatLevel,
                downbeatPulse,
                stagePulse);
        }

        private static float BuildRunProgressDownbeatLiftFromValues(
            bool activePattern,
            bool patternValid,
            bool stopped,
            bool paused,
            bool countdownActive,
            bool choiceActive,
            float coreDeltaSeconds,
            float goodWindowSeconds,
            float successWindowSeconds,
            int health,
            bool infiniteMode,
            int infiniteThreatLevel,
            float downbeatPulse,
            float stagePulse)
        {
            if (!activePattern
                || !patternValid
                || stopped
                || paused
                || countdownActive
                || choiceActive)
            {
                return 0f;
            }

            float readiness = goodWindowSeconds > 0f
                ? 1f - Mathf.Clamp01(Mathf.Abs(coreDeltaSeconds) / goodWindowSeconds)
                : 0f;
            float exactness = successWindowSeconds > 0f
                ? 1f - Mathf.Clamp01(Mathf.Abs(coreDeltaSeconds) / successWindowSeconds)
                : 0f;
            float pressure = Mathf.Max(
                health <= 1 ? 0.10f : 0f,
                infiniteMode ? Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.10f : 0f);
            return Mathf.Clamp01(downbeatPulse)
                * Mathf.Clamp01(0.24f + readiness * 0.30f + exactness * 0.34f + Mathf.Clamp01(stagePulse) * 0.08f + pressure);
        }

        private static float BuildRunProgressDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.34f;
        }

        private static int BuildRunProgressTextAlpha(int baseAlpha, float downbeatLift)
        {
            return Mathf.Clamp(baseAlpha + Mathf.RoundToInt(Mathf.Clamp01(downbeatLift) * 18f), 0, 255);
        }

        private static float BuildRunProgressTextScale(float stagePulse, float downbeatLift)
        {
            return 1f + Mathf.Max(Mathf.Clamp01(stagePulse) * 0.020f, Mathf.Clamp01(downbeatLift) * 0.014f);
        }

        private static string BuildThreatProgressAlertLabel(int threatLevel, int direction)
        {
            int safeThreatLevel = Mathf.Clamp(threatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel);
            return direction >= 0
                ? "위협 상승  " + safeThreatLevel
                : "위협 하강  " + safeThreatLevel;
        }

        private void TrackRunProgressStageState(GreedLastRunSnapshot snapshot)
        {
            string stageKey = BuildRunProgressStageKey(snapshot);
            if (string.IsNullOrEmpty(lastRunProgressStageKey))
            {
                lastRunProgressStageKey = stageKey;
                return;
            }

            if (string.Equals(lastRunProgressStageKey, stageKey, StringComparison.Ordinal))
            {
                return;
            }

            bool pauseTransition = string.Equals(lastRunProgressStageKey, "paused", StringComparison.Ordinal)
                || string.Equals(stageKey, "paused", StringComparison.Ordinal);
            lastRunProgressStageKey = stageKey;
            if (pauseTransition)
            {
                targetCuePlayed = false;
                return;
            }

            runProgressStagePulseUntil = Time.unscaledTime + RunProgressStagePulseDuration;
            if (!snapshot.Paused && !snapshot.CountdownActive)
            {
                PlayHaptic(0.018f);
            }
        }

        private static string BuildRunProgressStageKey(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.PracticeMode)
            {
                return snapshot.Stopped ? "practice_stopped" : "practice";
            }

            if (snapshot.Stopped)
            {
                return snapshot.InfiniteMode
                    ? "infinite_stopped"
                    : snapshot.SaveEligible ? "normal_clear" : "normal_stopped";
            }

            if (snapshot.Paused)
            {
                return "paused";
            }

            if (snapshot.InfiniteMode)
            {
                return "infinite_section_" + snapshot.InfiniteSectionsCleared;
            }

            if (snapshot.ChoiceActive)
            {
                return "choice_" + snapshot.ChoiceKind;
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                return "escape";
            }

            if (snapshot.Phase == GreedLastRunPhase.ClearResolving)
            {
                return "clear";
            }

            if (snapshot.CoreRetrieved)
            {
                return "core_ready";
            }

            return "chapter_" + snapshot.ChapterIndex;
        }

        private float BuildRunProgressStagePulse()
        {
            float remaining = runProgressStagePulseUntil - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remaining / RunProgressStagePulseDuration);
            return Mathf.Sin(normalized * Mathf.PI);
        }

        private void TrackThreatProgressState(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.InfiniteMode || snapshot.Stopped || snapshot.CountdownActive)
            {
                lastProgressThreatLevel = snapshot.InfiniteMode ? snapshot.InfiniteThreatLevel : int.MinValue;
                threatProgressDirection = 0;
                threatProgressPulseUntil = 0f;
                return;
            }

            int currentThreat = snapshot.InfiniteThreatLevel;
            if (lastProgressThreatLevel != int.MinValue && currentThreat != lastProgressThreatLevel)
            {
                threatProgressDirection = currentThreat > lastProgressThreatLevel ? 1 : -1;
                threatProgressPulseUntil = Time.unscaledTime + ThreatProgressPulseDuration;
                if (threatProgressDirection > 0)
                {
                    PlayClip(threatUpClip, 0.30f);
                    PlayHaptic(0.036f);
                }
                else
                {
                    PlayClip(threatDownClip, 0.22f);
                    PlayHaptic(0.020f);
                }
            }

            lastProgressThreatLevel = currentThreat;
        }

        private float BuildThreatProgressPulse(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.InfiniteMode || snapshot.Stopped)
            {
                return 0f;
            }

            float remaining = threatProgressPulseUntil - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remaining / ThreatProgressPulseDuration);
            return Mathf.Sin(normalized * Mathf.PI);
        }

        private void UpdateComboBadge(GreedLastRunSnapshot snapshot)
        {
            if (comboBadgeRoot == null)
            {
                return;
            }

            TrackComboBadgeState(snapshot);
            bool showBreak = !snapshot.Stopped && snapshot.Combo == 0 && Time.unscaledTime < comboBreakBadgeUntil;
            bool showTier = !showBreak && !snapshot.Stopped && snapshot.Combo > 0 && Time.unscaledTime < comboTierBadgeUntil;
            bool precisionActive = !snapshot.Stopped && snapshot.PrecisionStreak >= 2;
            bool stoppedPrecision = snapshot.Stopped && snapshot.MaxPrecisionStreak > 0;
            bool profileBonusActive = !snapshot.Stopped
                && IsVisibleChoiceProfile(snapshot.ActiveChoiceProfile)
                && Time.unscaledTime < beatMarkerProfilePulseUntil;
            bool showBadge = showBreak
                || showTier
                || profileBonusActive
                || snapshot.Combo > 0
                || precisionActive
                || snapshot.Stopped && snapshot.MaxCombo > 0
                || stoppedPrecision;
            if (!snapshot.Stopped && (stageTransitionCuePending || Time.unscaledTime < stageTransitionUntil))
                showBadge = false;
            comboBadgeRoot.SetActive(showBadge);
            if (!showBadge)
            {
                HidePrecisionRewardPips();
                return;
            }

            bool chainActive = snapshot.Combo >= 3;
            string text = snapshot.Stopped
                ? "최대 콤보 " + snapshot.MaxCombo + (snapshot.MaxPrecisionStreak > 0 ? " / 정박 " + snapshot.MaxPrecisionStreak : string.Empty)
                : chainActive
                    ? "콤보 " + snapshot.Combo + "  연쇄 " + BuildRhythmChainLabel(snapshot) + BuildPrecisionBadgeSuffix(snapshot)
                    : snapshot.Combo > 0
                        ? "콤보 " + snapshot.Combo + BuildPrecisionBadgeSuffix(snapshot)
                        : precisionActive
                            ? "정박 " + snapshot.PrecisionStreak
                            : "조합 " + snapshot.ActiveChoiceProfile;

            if (comboBadgeText != null)
            {
                if (showBreak)
                {
                    text = comboBreakBadgeCombo > 0
                        ? "연쇄 끊김  " + comboBreakBadgeCombo + "콤보"
                        : "연쇄 끊김";
                }
                else if (showTier)
                {
                    text = "연쇄 상승  x" + comboTierBadgeLevel;
                }
                else if (profileBonusActive && snapshot.Combo > 0)
                {
                    text += " / 조합 " + snapshot.ActiveChoiceProfile;
                }

                comboBadgeText.text = text;
            }

            float rewardReadiness = BuildComboBadgeRewardReadiness(
                snapshot.PrecisionStreak,
                snapshot.Combo,
                snapshot.Stopped,
                snapshot.Paused,
                snapshot.CountdownActive,
                snapshot.ChoiceActive);
            float rewardPulse = BuildComboBadgeRewardPulse(
                rewardReadiness,
                Time.unscaledTime < comboBadgePulseUntil,
                showTier,
                showBreak);
            float downbeatLift = BuildComboBadgeDownbeatLift(
                ShouldShowDownbeatPulse(snapshot) ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime) : 0f,
                rewardReadiness,
                snapshot.Combo,
                snapshot.PrecisionStreak,
                showBadge);

            if (comboBadgeBack != null)
            {
                comboBadgeBack.color = snapshot.Stopped
                    ? new Color32(24, 33, 36, 218)
                    : chainActive
                        ? new Color32(178, 123, 36, 228)
                        : precisionActive
                            ? new Color32(165, 128, 52, 228)
                            : new Color32(35, 65, 75, 218);
                if (showBreak)
                {
                    comboBadgeBack.color = new Color32(120, 46, 42, 226);
                }
                else if (showTier)
                {
                    comboBadgeBack.color = new Color32(207, 151, 46, 236);
                }
                else if (profileBonusActive)
                {
                    comboBadgeBack.color = Color32.Lerp(comboBadgeBack.color, GetChoiceProfilePulseColor(snapshot.ActiveChoiceProfile), 0.42f);
                }

                comboBadgeBack.color = Color32.Lerp(
                    comboBadgeBack.color,
                    new Color32(225, 167, 56, 240),
                    BuildComboBadgeRewardBackBlend(rewardPulse));
                comboBadgeBack.color = Color32.Lerp(
                    comboBadgeBack.color,
                    new Color32(255, 214, 105, 248),
                    BuildComboBadgeDownbeatBackBlend(downbeatLift));
            }

            if (comboBadgeAccent != null)
            {
                comboBadgeAccent.color = snapshot.Stopped
                    ? new Color32(125, 139, 143, 220)
                    : chainActive
                        ? new Color32(255, 214, 105, 245)
                        : precisionActive
                            ? new Color32(255, 238, 181, 252)
                            : new Color32(105, 168, 190, 230);
                if (showBreak)
                {
                    comboBadgeAccent.color = new Color32(231, 91, 77, 245);
                }
                else if (showTier)
                {
                    comboBadgeAccent.color = new Color32(255, 238, 181, 255);
                }
                else if (profileBonusActive)
                {
                    comboBadgeAccent.color = GetChoiceProfilePulseColor(snapshot.ActiveChoiceProfile);
                }

                comboBadgeAccent.color = Color32.Lerp(
                    comboBadgeAccent.color,
                    new Color32(255, 252, 214, 255),
                    BuildComboBadgeRewardAccentBlend(rewardPulse));
                comboBadgeAccent.color = Color32.Lerp(
                    comboBadgeAccent.color,
                    new Color32(255, 255, 228, 255),
                    BuildComboBadgeDownbeatAccentBlend(downbeatLift));
            }

            float profilePulse = profileBonusActive ? BuildBeatMarkerProfilePulse() : 0f;
            float pulse = BuildComboBadgeHitPulse(Time.unscaledTime < comboBadgePulseUntil, Time.unscaledTime);
            float badgeScale = BuildComboBadgeScaleWithDownbeat(
                BuildComboBadgeScale(pulse, profilePulse, rewardPulse),
                downbeatLift);
            comboBadgeRoot.transform.localScale = Vector3.one * badgeScale;
            if (comboBadgeText != null)
            {
                Color32 textColor = showBreak
                    ? new Color32(255, 230, 221, 248)
                    : new Color32(237, 239, 231, 245);
                comboBadgeText.color = Color32.Lerp(
                    textColor,
                    new Color32(255, 248, 210, 255),
                    BuildComboBadgeDownbeatTextBlend(downbeatLift));
            }

            UpdatePrecisionRewardPips(snapshot);
        }

        private void UpdatePrecisionRewardPips(GreedLastRunSnapshot snapshot)
        {
            if (precisionRewardPips == null)
            {
                return;
            }

            bool visible = ShouldShowPrecisionRewardPips(snapshot);
            bool rewardReady = visible && BuildPrecisionRewardRemaining(snapshot) == 0;
            float rewardPulse = rewardReady ? 0.5f + Mathf.Sin(Time.unscaledTime * 18f) * 0.5f : 0f;
            float downbeatPulse = visible && ShouldShowDownbeatPulse(snapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;
            for (int i = 0; i < precisionRewardPips.Length; i += 1)
            {
                Image pip = precisionRewardPips[i];
                if (pip == null)
                {
                    continue;
                }

                float fill = BuildPrecisionRewardPipFillAmountFromValues(
                    snapshot.PrecisionStreak,
                    i,
                    snapshot.Stopped,
                    snapshot.Paused,
                    snapshot.CountdownActive,
                    snapshot.ChoiceActive);
                float alpha = BuildPrecisionRewardPipAlpha(visible, fill, rewardReady, rewardPulse);
                float downbeatLift = BuildPrecisionRewardPipDownbeatLift(downbeatPulse, fill, rewardReady, i);
                alpha = BuildPrecisionRewardPipAlphaWithDownbeat(alpha, downbeatLift);
                Color32 color = fill > 0f
                    ? new Color32(255, 238, 181, 255)
                    : new Color32(125, 139, 143, 255);
                if (rewardReady && fill > 0f)
                {
                    color = Color32.Lerp(color, new Color32(255, 255, 255, 255), rewardPulse * 0.58f);
                }
                if (downbeatLift > 0f)
                {
                    color = Color32.Lerp(
                        color,
                        new Color32(255, 255, 228, 255),
                        BuildPrecisionRewardPipDownbeatColorBlend(downbeatLift));
                }

                color.a = (byte)Mathf.RoundToInt(alpha * 255f);
                pip.color = color;
                pip.rectTransform.localScale = Vector3.one * BuildPrecisionRewardPipScaleWithDownbeat(
                    BuildPrecisionRewardPipScale(fill, rewardReady, rewardPulse),
                    downbeatLift);
            }
        }

        private void HidePrecisionRewardPips()
        {
            if (precisionRewardPips == null)
            {
                return;
            }

            for (int i = 0; i < precisionRewardPips.Length; i += 1)
            {
                Image pip = precisionRewardPips[i];
                if (pip == null)
                {
                    continue;
                }

                pip.color = new Color32(255, 238, 181, 0);
                pip.rectTransform.localScale = Vector3.one;
            }
        }

        private static bool ShouldShowPrecisionRewardPips(GreedLastRunSnapshot snapshot)
        {
            return snapshot.PrecisionStreak > 0
                && !snapshot.Stopped
                && !snapshot.Paused
                && !snapshot.CountdownActive
                && !snapshot.ChoiceActive;
        }

        private static float BuildPrecisionRewardPipFillAmountFromValues(
            int precisionStreak,
            int pipIndex,
            bool stopped,
            bool paused,
            bool countdownActive,
            bool choiceActive)
        {
            if (pipIndex < 0
                || pipIndex >= PrecisionRewardPipCount
                || precisionStreak <= 0
                || stopped
                || paused
                || countdownActive
                || choiceActive)
            {
                return 0f;
            }

            int remainder = precisionStreak % PrecisionFocusStepUi;
            int fillCount = remainder == 0 ? PrecisionRewardPipCount : remainder;
            return pipIndex < fillCount ? 1f : 0f;
        }

        private static float BuildPrecisionRewardPipAlpha(bool visible, float fillAmount, bool rewardReady, float pulse)
        {
            if (!visible)
            {
                return 0f;
            }

            float alpha = Mathf.Lerp(0.22f, 0.82f, Mathf.Clamp01(fillAmount));
            if (rewardReady && fillAmount > 0f)
            {
                alpha = Mathf.Lerp(alpha, 1f, Mathf.Clamp01(pulse) * 0.72f);
            }

            return Mathf.Clamp01(alpha);
        }

        private static float BuildPrecisionRewardPipScale(float fillAmount, bool rewardReady, float pulse)
        {
            return 1f
                + Mathf.Clamp01(fillAmount) * 0.08f
                + (rewardReady ? Mathf.Clamp01(pulse) * 0.14f : 0f);
        }

        private static float BuildPrecisionRewardPipDownbeatLift(
            float downbeatPulse,
            float fillAmount,
            bool rewardReady,
            int pipIndex)
        {
            if (fillAmount <= 0f || pipIndex < 0 || pipIndex >= PrecisionRewardPipCount)
            {
                return 0f;
            }

            float pipProgress = (pipIndex + 1f) / PrecisionRewardPipCount;
            float readinessWeight = rewardReady
                ? Mathf.Lerp(0.72f, 1f, pipProgress)
                : Mathf.Lerp(0.34f, 0.58f, pipProgress);
            return Mathf.Clamp01(downbeatPulse) * Mathf.Clamp01(fillAmount) * readinessWeight;
        }

        private static float BuildPrecisionRewardPipAlphaWithDownbeat(float baseAlpha, float downbeatLift)
        {
            return Mathf.Clamp01(baseAlpha + Mathf.Clamp01(downbeatLift) * 0.16f);
        }

        private static float BuildPrecisionRewardPipScaleWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.12f;
        }

        private static float BuildPrecisionRewardPipDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.48f;
        }

        private static float BuildComboBadgeRewardReadiness(
            int precisionStreak,
            int combo,
            bool stopped,
            bool paused,
            bool countdownActive,
            bool choiceActive)
        {
            if (stopped || paused || countdownActive || choiceActive)
            {
                return 0f;
            }

            float precisionReadiness = 0f;
            if (precisionStreak > 0)
            {
                int remainder = precisionStreak % PrecisionFocusStepUi;
                precisionReadiness = remainder == 0
                    ? 1f
                    : remainder / (float)PrecisionFocusStepUi;
            }

            float chainReadiness = 0f;
            if (combo > 0)
            {
                int currentTier = Mathf.Clamp(combo / 3, 0, 5);
                if (currentTier < 5)
                {
                    int nextTierCombo = (currentTier + 1) * 3;
                    int remaining = Mathf.Clamp(nextTierCombo - combo, 0, 3);
                    chainReadiness = 1f - remaining / 3f;
                }
            }

            return Mathf.Clamp01(Mathf.Max(precisionReadiness, chainReadiness * 0.82f));
        }

        private static float BuildComboBadgeRewardPulse(
            float readiness,
            bool activeComboPulse,
            bool tierBadgeActive,
            bool breakBadgeActive)
        {
            if (breakBadgeActive)
            {
                return 0f;
            }

            float pulse = Mathf.Clamp01(readiness);
            if (activeComboPulse)
            {
                pulse = Mathf.Max(pulse, 0.62f);
            }

            if (tierBadgeActive)
            {
                pulse = Mathf.Max(pulse, 0.88f);
            }

            return pulse;
        }

        private static float BuildComboBadgeRewardBackBlend(float rewardPulse)
        {
            return Mathf.Clamp01(rewardPulse) * 0.32f;
        }

        private static float BuildComboBadgeRewardAccentBlend(float rewardPulse)
        {
            return Mathf.Clamp01(rewardPulse) * 0.64f;
        }

        private static float BuildComboBadgeRewardScaleLift(float rewardPulse)
        {
            return Mathf.Clamp01(rewardPulse) * 0.075f;
        }

        private static float BuildComboBadgeHitPulse(bool pulseActive, float nowSeconds)
        {
            return pulseActive
                ? 1.06f + Mathf.Sin(nowSeconds * 48f) * 0.035f
                : 1f;
        }

        private static float BuildComboBadgeScale(float hitPulse, float profilePulse, float rewardPulse)
        {
            return Mathf.Max(0.1f, hitPulse)
                + Mathf.Clamp01(profilePulse) * 0.08f
                + BuildComboBadgeRewardScaleLift(rewardPulse);
        }

        private static float BuildComboBadgeDownbeatLift(
            float downbeatPulse,
            float rewardReadiness,
            int combo,
            int precisionStreak,
            bool badgeVisible)
        {
            if (!badgeVisible || combo <= 0 && precisionStreak <= 0)
            {
                return 0f;
            }

            float activity = Mathf.Clamp01(Mathf.Max(combo / 6f, precisionStreak / (float)PrecisionFocusStepUi));
            return Mathf.Clamp01(downbeatPulse)
                * Mathf.Clamp01(0.22f + Mathf.Clamp01(rewardReadiness) * 0.58f + activity * 0.20f);
        }

        private static float BuildComboBadgeDownbeatBackBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.24f;
        }

        private static float BuildComboBadgeDownbeatAccentBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.52f;
        }

        private static float BuildComboBadgeDownbeatTextBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.36f;
        }

        private static float BuildComboBadgeScaleWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.055f;
        }

        private static int BuildComboBadgeRewardFlashAlphaLift(float rewardPulse)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(rewardPulse) * 18f);
        }

        private static float BuildComboBadgeRewardFlashDurationLift(float rewardPulse)
        {
            return Mathf.Clamp01(rewardPulse) * 0.045f;
        }

        private static Color32 BuildColorWithAlphaLift(Color32 color, int alphaLift, int maxAlpha)
        {
            int liftedAlpha = Mathf.Clamp(
                color.a + Mathf.Max(0, alphaLift),
                0,
                Mathf.Clamp(maxAlpha, 0, 255));
            color.a = (byte)liftedAlpha;
            return color;
        }

        private static string BuildPrecisionBadgeSuffix(GreedLastRunSnapshot snapshot)
        {
            string suffix = snapshot.PrecisionStreak >= 2 ? " / 정박 " + snapshot.PrecisionStreak : string.Empty;
            return suffix + BuildComboBadgeRewardSuffix(snapshot);
        }

        private static string BuildComboBadgeRewardSuffix(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped || snapshot.Paused || snapshot.CountdownActive)
            {
                return string.Empty;
            }

            int precisionRewardRemaining = BuildPrecisionRewardRemaining(snapshot);
            if (precisionRewardRemaining == 0)
            {
                return snapshot.FocusStateActive
                    ? snapshot.LastJudgementStartedInFocusState ? " / 집중 유지" : " / 집중 발동"
                    : " / 집중 +1";
            }

            if (!snapshot.FocusStateActive && precisionRewardRemaining > 0 && precisionRewardRemaining <= 2)
            {
                return " / 집중 " + precisionRewardRemaining + "회";
            }

            int chainRewardRemaining = BuildNextChainRemaining(snapshot);
            if (chainRewardRemaining > 0 && chainRewardRemaining <= 2)
            {
                return " / 연쇄 " + chainRewardRemaining + "회";
            }

            return string.Empty;
        }

        private void ResetJudgementHistoryForFreshRun(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped || snapshot.Paused || snapshot.ResumeCountdownActive)
            {
                return;
            }

            bool freshStart = snapshot.StartCountdownActive
                && snapshot.Score == 0
                && snapshot.Distance <= 0.1f
                && snapshot.Combo == 0
                && snapshot.LastResult == GreedLastJudgementResult.None;
            bool targetChanged = !string.Equals(
                lastPresentedReviewTargetText,
                snapshot.ReviewTargetText,
                StringComparison.Ordinal);
            bool targetShortcutStart = snapshot.StartCountdownActive
                && snapshot.LastResult == GreedLastJudgementResult.None
                && snapshot.JudgementText.Contains("목표 직전", StringComparison.Ordinal);
            bool resetReviewPresentation = freshStart || targetChanged || targetShortcutStart;
            if (resetReviewPresentation && judgementHistoryCount > 0)
            {
                ClearJudgementHistory();
            }

            if (resetReviewPresentation)
            {
                reviewTargetAchievementAnnounced = false;
            }

            lastPresentedReviewTargetText = snapshot.ReviewTargetText ?? string.Empty;
        }

        private void UpdateJudgementHistoryVisibility(GreedLastRunSnapshot snapshot)
        {
            if (judgementHistoryRoot == null)
            {
                return;
            }

            bool showHistory = ShouldShowJudgementHistory(snapshot, judgementHistoryCount);
            judgementHistoryRoot.SetActive(showHistory);
        }

        private static bool ShouldShowJudgementHistory(GreedLastRunSnapshot snapshot, int historyCount)
        {
            return historyCount > 0
                && ShouldShowRunTransientFeedback(snapshot);
        }

        private void RecordJudgementHistory(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.LastResult == GreedLastJudgementResult.None)
            {
                return;
            }

            if (judgementHistoryCount < JudgementHistoryCapacity)
            {
                judgementHistoryResults[judgementHistoryCount] = snapshot.LastResult;
                judgementHistoryFocusGuards[judgementHistoryCount] = snapshot.FocusStateActive
                    && snapshot.LastResult != GreedLastJudgementResult.Miss;
                judgementHistoryCenterHits[judgementHistoryCount] = snapshot.LastCenterHit;
                judgementHistoryResponses[judgementHistoryCount] = BuildJudgementHistoryResponseType(snapshot);
                judgementHistoryCount += 1;
            }
            else
            {
                for (int i = 1; i < JudgementHistoryCapacity; i += 1)
                {
                    judgementHistoryResults[i - 1] = judgementHistoryResults[i];
                    judgementHistoryFocusGuards[i - 1] = judgementHistoryFocusGuards[i];
                    judgementHistoryCenterHits[i - 1] = judgementHistoryCenterHits[i];
                    judgementHistoryResponses[i - 1] = judgementHistoryResponses[i];
                }

                judgementHistoryResults[JudgementHistoryCapacity - 1] = snapshot.LastResult;
                judgementHistoryFocusGuards[JudgementHistoryCapacity - 1] = snapshot.FocusStateActive
                    && snapshot.LastResult != GreedLastJudgementResult.Miss;
                judgementHistoryCenterHits[JudgementHistoryCapacity - 1] = snapshot.LastCenterHit;
                judgementHistoryResponses[JudgementHistoryCapacity - 1] = BuildJudgementHistoryResponseType(snapshot);
            }

            judgementHistoryPulseUntil = Time.unscaledTime + JudgementHistoryPulseDuration;
            if (judgementHistoryRoot != null)
            {
                judgementHistoryRoot.SetActive(ShouldShowJudgementHistory(snapshot, judgementHistoryCount));
            }
        }

        private static RunnerResponseType BuildJudgementHistoryResponseType(GreedLastRunSnapshot snapshot)
        {
            return BuildRunnerResponseType(BuildJudgementFeedbackPattern(snapshot));
        }

        private static string BuildJudgementHistoryResponseSymbol(GreedLastRunSnapshot snapshot)
        {
            return FormatRunnerResponseSymbol(BuildJudgementHistoryResponseType(snapshot));
        }

        private void ClearJudgementHistory()
        {
            judgementHistoryCount = 0;
            judgementHistoryPulseUntil = 0f;
            for (int i = 0; i < JudgementHistoryCapacity; i += 1)
            {
                judgementHistoryResults[i] = GreedLastJudgementResult.None;
                judgementHistoryFocusGuards[i] = false;
                judgementHistoryCenterHits[i] = false;
                judgementHistoryResponses[i] = RunnerResponseType.None;
            }

            if (judgementHistoryRoot != null)
            {
                judgementHistoryRoot.SetActive(false);
            }
        }

        private void UpdateJudgementHistoryDots()
        {
            if (judgementHistoryDots == null || judgementHistoryRoot == null || !judgementHistoryRoot.activeSelf)
            {
                return;
            }

            float pulse = BuildJudgementHistoryPulse();
            int emptyCount = JudgementHistoryCapacity - judgementHistoryCount;
            for (int i = 0; i < judgementHistoryDots.Length; i += 1)
            {
                Image dot = judgementHistoryDots[i];
                if (dot == null)
                {
                    continue;
                }

                int historyIndex = i - emptyCount;
                bool hasEntry = historyIndex >= 0 && historyIndex < judgementHistoryCount;
                bool newest = hasEntry && historyIndex == judgementHistoryCount - 1;
                GreedLastJudgementResult result = hasEntry
                    ? judgementHistoryResults[historyIndex]
                    : GreedLastJudgementResult.None;
                bool focusGuard = hasEntry && judgementHistoryFocusGuards[historyIndex];
                bool centerHit = hasEntry && judgementHistoryCenterHits[historyIndex];
                RunnerResponseType response = hasEntry
                    ? judgementHistoryResponses[historyIndex]
                    : RunnerResponseType.None;
                Color32 color = BuildJudgementHistoryColor(result, focusGuard, centerHit, hasEntry);
                if (newest && pulse > 0f)
                {
                    color = Color32.Lerp(color, new Color32(255, 248, 210, 255), pulse * 0.72f);
                }

                dot.color = color;
                dot.rectTransform.localScale = Vector3.one * BuildJudgementHistoryDotScale(
                    result,
                    focusGuard,
                    centerHit,
                    hasEntry,
                    newest,
                    pulse);
                if (judgementHistoryActionLabels != null && i < judgementHistoryActionLabels.Length)
                {
                    Text actionLabel = judgementHistoryActionLabels[i];
                    actionLabel.text = hasEntry ? FormatRunnerResponseSymbol(response) : string.Empty;
                    actionLabel.color = BuildJudgementHistoryActionLabelColor(
                        result,
                        focusGuard,
                        centerHit,
                        hasEntry,
                        newest,
                        pulse);
                    actionLabel.rectTransform.localScale = Vector3.one * BuildJudgementHistoryActionLabelScale(
                        result,
                        focusGuard,
                        centerHit,
                        hasEntry,
                        newest,
                        pulse);
                }
            }
        }

        private float BuildJudgementHistoryPulse()
        {
            float remaining = judgementHistoryPulseUntil - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remaining / JudgementHistoryPulseDuration);
            return Mathf.Sin(normalized * Mathf.PI);
        }

        private static float BuildJudgementHistoryResultWeight(
            GreedLastJudgementResult result,
            bool focusGuard,
            bool centerHit)
        {
            float weight;
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    weight = 1f;
                    break;
                case GreedLastJudgementResult.Good:
                    weight = 0.62f;
                    break;
                case GreedLastJudgementResult.Miss:
                    weight = 0.86f;
                    break;
                default:
                    return 0f;
            }

            return Mathf.Clamp01(weight + (centerHit ? 0.06f : 0f) + (focusGuard ? 0.05f : 0f));
        }

        private static float BuildJudgementHistoryDotScale(
            GreedLastJudgementResult result,
            bool focusGuard,
            bool centerHit,
            bool hasEntry,
            bool newest,
            float pulse)
        {
            if (!hasEntry)
            {
                return 0.86f;
            }

            float weight = BuildJudgementHistoryResultWeight(result, focusGuard, centerHit);
            return 0.96f + weight * 0.075f + (newest ? Mathf.Clamp01(pulse) * (0.15f + weight * 0.05f) : 0f);
        }

        private static int BuildJudgementHistoryActionLabelAlpha(
            GreedLastJudgementResult result,
            bool focusGuard,
            bool centerHit,
            bool newest,
            float pulse)
        {
            float weight = BuildJudgementHistoryResultWeight(result, focusGuard, centerHit);
            return Mathf.RoundToInt(Mathf.Clamp(204f + weight * 34f + (newest ? Mathf.Clamp01(pulse) * 12f : 0f), 0f, 255f));
        }

        private static float BuildJudgementHistoryActionLabelScale(
            GreedLastJudgementResult result,
            bool focusGuard,
            bool centerHit,
            bool hasEntry,
            bool newest,
            float pulse)
        {
            if (!hasEntry)
            {
                return 0.86f;
            }

            float weight = BuildJudgementHistoryResultWeight(result, focusGuard, centerHit);
            return 0.93f + weight * 0.105f + (newest ? Mathf.Clamp01(pulse) * 0.045f : 0f);
        }

        private static Color32 BuildJudgementHistoryActionLabelColor(
            GreedLastJudgementResult result,
            bool focusGuard,
            bool centerHit,
            bool hasEntry,
            bool newest,
            float pulse)
        {
            if (!hasEntry)
            {
                return new Color32(18, 27, 30, 0);
            }

            Color32 color;
            if (focusGuard && result != GreedLastJudgementResult.Miss)
            {
                color = centerHit
                    ? new Color32(55, 39, 14, 255)
                    : new Color32(48, 36, 15, 255);
            }
            else
            {
                switch (result)
                {
                    case GreedLastJudgementResult.Success:
                        color = centerHit
                            ? new Color32(42, 34, 15, 255)
                            : new Color32(35, 31, 18, 255);
                        break;
                    case GreedLastJudgementResult.Good:
                        color = new Color32(12, 36, 44, 255);
                        break;
                    case GreedLastJudgementResult.Miss:
                        color = new Color32(63, 18, 17, 255);
                        break;
                    default:
                        color = new Color32(18, 27, 30, 255);
                        break;
                }
            }

            color.a = (byte)BuildJudgementHistoryActionLabelAlpha(result, focusGuard, centerHit, newest, pulse);
            return color;
        }

        private static Color32 BuildJudgementHistoryColor(GreedLastJudgementResult result, bool focusGuard, bool centerHit, bool hasEntry)
        {
            if (!hasEntry)
            {
                return new Color32(63, 78, 82, 92);
            }

            if (focusGuard && result != GreedLastJudgementResult.Miss)
            {
                return centerHit
                    ? new Color32(255, 248, 210, 252)
                    : new Color32(255, 196, 74, 242);
            }

            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return centerHit
                        ? new Color32(255, 248, 210, 248)
                        : new Color32(255, 218, 105, 235);
                case GreedLastJudgementResult.Good:
                    return new Color32(132, 190, 208, 226);
                case GreedLastJudgementResult.Miss:
                    return new Color32(231, 91, 77, 232);
                default:
                    return new Color32(63, 78, 82, 92);
            }
        }

        private void TrackComboBadgeState(GreedLastRunSnapshot snapshot)
        {
            if (!runModeActive || snapshot.Stopped || snapshot.CountdownActive)
            {
                lastComboForBadge = snapshot.Combo;
                return;
            }

            if (lastComboForBadge >= 3 && snapshot.Combo == 0)
            {
                comboBreakBadgeCombo = lastComboForBadge;
                comboBreakBadgeUntil = Time.unscaledTime + ComboBreakBadgeDuration;
                comboTierBadgeUntil = 0f;
                comboTierFeedbackPending = false;
                beatMarkerComboBreakPulseUntil = Time.unscaledTime + BeatMarkerComboBreakPulseDuration;
                comboBadgePulseUntil = Time.unscaledTime + 0.20f;
                PlayClip(comboBreakClip, 0.24f);
                PlayHaptic(0.024f);
            }
            else if (snapshot.Combo > 0)
            {
                comboBreakBadgeUntil = 0f;
            }

            int previousTier = lastComboForBadge == int.MinValue
                ? 0
                : Mathf.Clamp(lastComboForBadge / 3, 0, 5);
            int currentTier = Mathf.Clamp(snapshot.Combo / 3, 0, 5);
            if (snapshot.Combo > 0 && currentTier > previousTier && currentTier > 0)
            {
                comboTierBadgeLevel = currentTier;
                comboTierBadgeUntil = Time.unscaledTime + ComboTierBadgeDuration;
                comboTierFeedbackPending = true;
                beatMarkerComboTierPulseUntil = Time.unscaledTime + BeatMarkerComboTierPulseDuration;
                comboBadgePulseUntil = Time.unscaledTime + 0.24f;
            }

            lastComboForBadge = snapshot.Combo;
        }

        private string BuildNormalRunHud(
            GreedLastRunSnapshot snapshot,
            string runState,
            string chapterText,
            string choiceText)
        {
            string runTag = snapshot.RefillRun ? "보충 " : string.Empty;
            if (snapshot.Stopped)
            {
                string relicText = string.IsNullOrEmpty(snapshot.ActiveRelic) ? "없음" : snapshot.ActiveRelic;
                return $"{runState}  {runTag}{chapterText}\n"
                    + $"점수 {snapshot.Score}  거리 {snapshot.Distance:0.0}m  최대 콤보 {snapshot.MaxCombo}\n"
                    + $"정박 {snapshot.PerfectSuccessCount}  압박 {snapshot.ClutchSuccessCount}  엇박 {snapshot.OffbeatSuccessCount}  보정 {snapshot.GoodCount}  실수 {snapshot.MissCount}\n"
                    + BuildSnapshotFocusPerformance(snapshot) + "\n"
                    + BuildStoppedAvoidanceHudLine(snapshot)
                    + BuildStoppedAvoidanceReviewHudLine(snapshot)
                    + $"조합 {snapshot.ActiveChoiceProfile}  {BuildGiftStackSummary(snapshot)}\n"
                    + BuildStoppedReviewTargetResultLine(snapshot)
                    + BuildRoutePayoffSettlementLine(snapshot)
                    + $"유물 {relicText}  최대 정박 {snapshot.MaxPrecisionStreak}{BuildRecoveryPrecisionHudSuffix(snapshot)}{BuildPerfectFocusChargeHudSuffix(snapshot)}{BuildClutchCounterHudSuffix(snapshot)}{BuildOffbeatFlowHudSuffix(snapshot)}{BuildThreeActionExactHudSuffix(snapshot)}";
            }

            if (snapshot.ChoiceActive)
            {
                string feedback = BuildChoiceFeedbackLine(snapshot.JudgementText);
                string feedbackLine = string.IsNullOrEmpty(feedback)
                    ? string.Empty
                    : feedback + "\n";
                string giftStackLine = snapshot.ChoiceKind == GreedLastChoiceKind.Gift
                    || snapshot.ChoiceKind == GreedLastChoiceKind.Relic
                        ? BuildGiftStackSummary(snapshot) + "\n"
                        : string.Empty;
                string reviewTargetLine = BuildReviewTargetHudLine(snapshot);
                return $"{runTag}{chapterText}  점수 {snapshot.Score}  콤보 {snapshot.Combo}\n"
                    + feedbackLine
                    + giftStackLine
                    + (string.IsNullOrEmpty(reviewTargetLine) ? string.Empty : reviewTargetLine + "\n")
                    + $"체력 {FormatHealthValue(snapshot)}  {FormatFocusStatus(snapshot)}\n"
                    + BuildChoiceInputHintLine(snapshot);
            }

            int total = snapshot.SuccessCount + snapshot.GoodCount + snapshot.MissCount;
            string flow = total > 0 ? BuildRunFlowTag(snapshot, total) : "시작";
            string status = BuildRunPressureStatus(snapshot);
            string statusLine = string.IsNullOrEmpty(status) ? string.Empty : "\n상태 " + status;
            string coachLine = BuildLiveRunCoachLine(snapshot);
            string coachHudLine = string.IsNullOrEmpty(coachLine) ? string.Empty : "\n" + coachLine;
            string reviewTargetHudLine = BuildReviewTargetHudLine(snapshot);
            return $"{runTag}{chapterText}  점수 {snapshot.Score}  콤보 {snapshot.Combo}{BuildPrecisionHudText(snapshot)}\n"
                + $"체력 {FormatHealthValue(snapshot)}  {FormatFocusStatus(snapshot)}  거리 {snapshot.Distance:0.0}m\n"
                + $"판정 {BuildCompactJudgementText(snapshot)}  흐름 {flow}"
                + (string.IsNullOrEmpty(reviewTargetHudLine) ? string.Empty : "\n" + reviewTargetHudLine)
                + statusLine
                + coachHudLine;
        }

        private static string BuildRunChapterHudText(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.PracticeMode)
            {
                return $"기초연습 {snapshot.ChapterProgress}/{snapshot.ChapterTarget}";
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                return BuildEscapeGateProgressText(snapshot);
            }

            if (snapshot.Phase == GreedLastRunPhase.ClearResolving)
            {
                return snapshot.EscapeSucceeded ? "입구 탈출 완료" : "결과 준비";
            }

            return $"챕터 {snapshot.ChapterIndex} {snapshot.ChapterProgress}/{snapshot.ChapterTarget}";
        }

        private string BuildInfiniteRunHud(GreedLastRunSnapshot snapshot, string runState)
        {
            if (snapshot.Stopped)
            {
                string lastMissText = string.IsNullOrEmpty(snapshot.MissReason)
                    ? "마지막 실수 -"
                    : "마지막 실수 " + FormatMissReason(snapshot.MissReason);
                return $"{runState}\n"
                    + $"이번 기록: [{BuildInfiniteSnapshotGrade(snapshot)}] {snapshot.Score}점 / {snapshot.Distance:0.0}m / {snapshot.InfiniteSectionsCleared}구간 / 위협 {snapshot.InfiniteThreatLevel}\n"
                    + $"조합: {FormatActiveInfiniteLoadoutName(snapshot.ActiveInfiniteLoadoutName)}{FormatActiveInfiniteLoadoutProfileSuffix(snapshot)} / 유물 {(string.IsNullOrEmpty(snapshot.ActiveRelic) ? "없음" : snapshot.ActiveRelic)} / {BuildInfiniteStoppedHighlight(snapshot)}\n"
                    + $"판정: 정박 {snapshot.PerfectSuccessCount}  압박 {snapshot.ClutchSuccessCount}  엇박 {snapshot.OffbeatSuccessCount}  보정 {snapshot.GoodCount}  실수 {snapshot.MissCount}\n"
                    + BuildSnapshotFocusPerformance(snapshot) + "\n"
                    + BuildStoppedAvoidanceHudLine(snapshot)
                    + BuildStoppedAvoidanceReviewHudLine(snapshot)
                    + $"최대 콤보 {snapshot.MaxCombo}{BuildMaxPrecisionHudText(snapshot)}{BuildRecoveryPrecisionHudSuffix(snapshot)}{BuildPerfectFocusChargeHudSuffix(snapshot)}{BuildClutchCounterHudSuffix(snapshot)}{BuildOffbeatFlowHudSuffix(snapshot)}  {lastMissText}\n"
                    + BuildStoppedReviewTargetResultLine(snapshot)
                    + BuildRoutePayoffSettlementLine(snapshot)
                    + BuildThreeActionExactHudResultLine(snapshot)
                    + "정산 후 재준비하거나 로비로 돌아갈 수 있습니다.";
            }

            string sectionText = snapshot.Stopped
                ? $"이번 기록: {snapshot.InfiniteSectionsCleared}구간 / {snapshot.Distance:0.0}m / {snapshot.Score}점"
                : $"무한 구간 {snapshot.ChapterProgress}/{snapshot.ChapterTarget}  위협 {snapshot.InfiniteThreatLevel}";
            int total = snapshot.SuccessCount + snapshot.GoodCount + snapshot.MissCount;
            string flow = total > 0 ? BuildRunFlowTag(snapshot, total) : "시작";
            string status = BuildRunPressureStatus(snapshot);
            string statusLine = string.IsNullOrEmpty(status) ? string.Empty : "\n상태 " + status;
            string coachLine = BuildLiveRunCoachLine(snapshot);
            string coachHudLine = string.IsNullOrEmpty(coachLine) ? string.Empty : "\n" + coachLine;
            string reviewTargetHudLine = BuildReviewTargetHudLine(snapshot);
            return $"{sectionText}{FormatActiveInfiniteLoadoutProfileSuffix(snapshot)}  점수 {snapshot.Score}  콤보 {snapshot.Combo}{BuildPrecisionHudText(snapshot)}\n"
                + $"체력 {FormatHealthValue(snapshot)}  {FormatFocusStatus(snapshot)}  거리 {snapshot.Distance:0.0}m\n"
                + $"판정 {BuildCompactJudgementText(snapshot)}  흐름 {flow}"
                + (string.IsNullOrEmpty(reviewTargetHudLine) ? string.Empty : "\n" + reviewTargetHudLine)
                + statusLine
                + coachHudLine;
        }

        public static string BuildReviewTargetHudLine(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped || string.IsNullOrWhiteSpace(snapshot.ReviewTargetText))
            {
                return string.Empty;
            }

            string progress = BuildReviewTargetProgressSuffix(snapshot);
            string text = snapshot.ReviewTargetText + progress;
            return "목표 " + CompactUiText(text, 64);
        }

        public static string BuildStoppedReviewTargetResultLine(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.Stopped || string.IsNullOrWhiteSpace(snapshot.ReviewTargetText))
            {
                return string.Empty;
            }

            string result = BuildReviewTargetSettlementText(snapshot);
            return string.IsNullOrEmpty(result)
                ? string.Empty
                : "복기 목표: " + CompactUiText(snapshot.ReviewTargetText + " / " + result, 78) + "\n";
        }

        private static string BuildReviewTargetProgressSuffix(GreedLastRunSnapshot snapshot)
        {
            string target = snapshot.ReviewTargetText ?? string.Empty;
            if (target.Contains("무실수", StringComparison.Ordinal))
            {
                return snapshot.MissCount <= 0 ? " / 목표 유지" : " / 목표 실패 실수 " + snapshot.MissCount;
            }

            if (target.Contains("보정 0회", StringComparison.Ordinal))
            {
                if (snapshot.GoodCount > 0)
                {
                    return " / 목표 실패 보정 " + snapshot.GoodCount;
                }

                return snapshot.MissCount > 0 ? " / 목표 실패 실수 " + snapshot.MissCount : " / 목표 유지";
            }

            if (target.Contains("입력 없음", StringComparison.Ordinal))
            {
                int targetNoInput = ExtractTargetNumberAfterKeywordForUi(target, "입력 없음");
                return snapshot.NoInputMissCount <= targetNoInput
                    ? " / 목표 유지 입력 없음 " + snapshot.NoInputMissCount + "/" + targetNoInput
                    : " / 목표 실패 입력 없음 " + snapshot.NoInputMissCount + "/" + targetNoInput;
            }

            if (target.Contains("추천 보정 적용", StringComparison.Ordinal))
            {
                if (snapshot.TimingRecommendationApplied)
                {
                    return " / 목표 달성 보정 "
                        + FormatTimingOffset(snapshot.AppliedTimingRecommendationMilliseconds / 1000f);
                }

                return snapshot.HasTimingRecommendation
                    ? " / 적용 대기 추천 " + FormatTimingRecommendation(snapshot)
                    : " / 추천 대기 " + snapshot.TimingRecommendationSampleCount + "/" + snapshot.TimingRecommendationSampleTarget;
            }

            if (target.Contains("콤보", StringComparison.Ordinal))
            {
                int currentCombo = Mathf.Max(snapshot.Combo, snapshot.MaxCombo);
                int targetCombo = ExtractTargetNumberAfterKeywordForUi(target, "콤보");
                return targetCombo > 0 && currentCombo >= targetCombo
                    ? " / 목표 달성 콤보 " + currentCombo
                    : " / 진행 현재 " + currentCombo;
            }

            if (target.Contains("점", StringComparison.Ordinal))
            {
                int targetScore = ExtractTargetNumberBeforeMarkerForUi(target, "점");
                return targetScore > 0 && snapshot.Score >= targetScore
                    ? " / 목표 달성 " + snapshot.Score + "점"
                    : " / 진행 현재 " + snapshot.Score + "점";
            }

            if (target.Contains("구간 생존", StringComparison.Ordinal))
            {
                int targetSections = ExtractTargetNumberBeforeMarkerForUi(target, "구간");
                return targetSections > 0 && snapshot.InfiniteSectionsCleared >= targetSections
                    ? " / 목표 달성 " + snapshot.InfiniteSectionsCleared + "구간"
                    : " / 진행 " + snapshot.InfiniteSectionsCleared + "/" + targetSections + "구간";
            }

            if (target.Contains("위협", StringComparison.Ordinal))
            {
                int targetThreat = ExtractTargetNumberAfterKeywordForUi(target, "위협");
                return targetThreat > 0 && snapshot.MaxInfiniteThreatLevel >= targetThreat
                    ? " / 목표 달성 위협 " + snapshot.MaxInfiniteThreatLevel
                    : " / 진행 위협 " + snapshot.MaxInfiniteThreatLevel;
            }

            if (target.Contains("실수", StringComparison.Ordinal)
                && target.Contains("이하", StringComparison.Ordinal))
            {
                int targetMisses = ExtractTargetNumberAfterKeywordForUi(target, "실수");
                return snapshot.MissCount <= targetMisses
                    ? " / 목표 유지 실수 " + snapshot.MissCount + "/" + targetMisses
                    : " / 목표 실패 실수 " + snapshot.MissCount + "/" + targetMisses;
            }

            if (target.Contains("체력", StringComparison.Ordinal) || target.Contains("생존", StringComparison.Ordinal))
            {
                int targetHealth = target.Contains("체력", StringComparison.Ordinal)
                    ? ExtractTargetNumberAfterKeywordForUi(target, "체력")
                    : ExtractTargetNumberAfterKeywordForUi(target, "생존");
                return targetHealth > 0 && snapshot.Health >= targetHealth
                    ? " / 목표 달성 체력 " + snapshot.Health
                    : " / 진행 체력 " + snapshot.Health;
            }

            if (target.Contains("집중", StringComparison.Ordinal))
            {
                int targetFocus = ExtractTargetNumberAfterKeywordForUi(target, "집중");
                int currentFocus = BuildReviewTargetFocusProgress(snapshot, target);
                string focusText = BuildReviewTargetFocusProgressText(target, currentFocus);
                return targetFocus > 0 && currentFocus >= targetFocus
                    ? " / 목표 달성 " + focusText
                    : " / 진행 " + focusText;
            }

            if (target.Contains("정박", StringComparison.Ordinal) || target.Contains("정확권", StringComparison.Ordinal))
            {
                int targetPrecision = ExtractTargetPrecisionNumberForUi(target);
                int bestPrecision = Mathf.Max(snapshot.PrecisionStreak, snapshot.MaxPrecisionStreak);
                return targetPrecision > 0 && bestPrecision >= targetPrecision
                    ? " / 목표 달성 정박 " + bestPrecision
                    : " / 진행 정박 " + bestPrecision;
            }

            return string.Empty;
        }

        private static string BuildReviewTargetSettlementText(GreedLastRunSnapshot snapshot)
        {
            string target = snapshot.ReviewTargetText ?? string.Empty;
            if (target.Contains("무실수", StringComparison.Ordinal))
            {
                return snapshot.MissCount <= 0 ? "달성 무실수" : "실패 실수 " + snapshot.MissCount;
            }

            if (target.Contains("보정 0회", StringComparison.Ordinal))
            {
                if (snapshot.GoodCount > 0)
                {
                    return "실패 보정 " + snapshot.GoodCount;
                }

                return snapshot.MissCount > 0 ? "실패 실수 " + snapshot.MissCount : "달성 보정 0";
            }

            if (target.Contains("입력 없음", StringComparison.Ordinal))
            {
                int targetNoInput = ExtractTargetNumberAfterKeywordForUi(target, "입력 없음");
                return snapshot.NoInputMissCount <= targetNoInput
                    ? "달성 입력 없음 " + snapshot.NoInputMissCount + "/" + targetNoInput
                    : "실패 입력 없음 " + snapshot.NoInputMissCount + "/" + targetNoInput;
            }

            if (target.Contains("추천 보정 적용", StringComparison.Ordinal))
            {
                return snapshot.TimingRecommendationApplied
                    ? "달성 추천 보정 " + snapshot.AppliedTimingRecommendationMilliseconds + "ms"
                    : "진행 추천 보정 미적용";
            }

            if (target.Contains("콤보", StringComparison.Ordinal))
            {
                int currentCombo = Mathf.Max(snapshot.Combo, snapshot.MaxCombo);
                int targetCombo = ExtractTargetNumberAfterKeywordForUi(target, "콤보");
                return targetCombo > 0 && currentCombo >= targetCombo
                    ? "달성 콤보 " + currentCombo
                    : "진행 콤보 " + currentCombo;
            }

            if (target.Contains("점", StringComparison.Ordinal))
            {
                int targetScore = ExtractTargetNumberBeforeMarkerForUi(target, "점");
                return targetScore > 0 && snapshot.Score >= targetScore
                    ? "달성 " + snapshot.Score + "점"
                    : "진행 " + snapshot.Score + "점";
            }

            if (target.Contains("구간 생존", StringComparison.Ordinal))
            {
                int targetSections = ExtractTargetNumberBeforeMarkerForUi(target, "구간");
                return targetSections > 0 && snapshot.InfiniteSectionsCleared >= targetSections
                    ? "달성 " + snapshot.InfiniteSectionsCleared + "구간 생존"
                    : "진행 " + snapshot.InfiniteSectionsCleared + "/" + targetSections + "구간";
            }

            if (target.Contains("위협", StringComparison.Ordinal))
            {
                int targetThreat = ExtractTargetNumberAfterKeywordForUi(target, "위협");
                return targetThreat > 0 && snapshot.MaxInfiniteThreatLevel >= targetThreat
                    ? "달성 위협 " + snapshot.MaxInfiniteThreatLevel
                    : "진행 위협 " + snapshot.MaxInfiniteThreatLevel;
            }

            if (target.Contains("실수", StringComparison.Ordinal)
                && target.Contains("이하", StringComparison.Ordinal))
            {
                int targetMisses = ExtractTargetNumberAfterKeywordForUi(target, "실수");
                return snapshot.MissCount <= targetMisses
                    ? "달성 실수 " + snapshot.MissCount + "/" + targetMisses
                    : "실패 실수 " + snapshot.MissCount + "/" + targetMisses;
            }

            if (target.Contains("체력", StringComparison.Ordinal) || target.Contains("생존", StringComparison.Ordinal))
            {
                int targetHealth = target.Contains("체력", StringComparison.Ordinal)
                    ? ExtractTargetNumberAfterKeywordForUi(target, "체력")
                    : ExtractTargetNumberAfterKeywordForUi(target, "생존");
                return targetHealth > 0 && snapshot.Health >= targetHealth
                    ? "달성 체력 " + snapshot.Health
                    : "진행 체력 " + snapshot.Health;
            }

            if (target.Contains("집중", StringComparison.Ordinal))
            {
                int targetFocus = ExtractTargetNumberAfterKeywordForUi(target, "집중");
                int currentFocus = BuildReviewTargetFocusProgress(snapshot, target);
                string focusText = BuildReviewTargetFocusProgressText(target, currentFocus);
                return targetFocus > 0 && currentFocus >= targetFocus
                    ? "달성 " + focusText
                    : "진행 " + focusText;
            }

            if (target.Contains("정박", StringComparison.Ordinal) || target.Contains("정확권", StringComparison.Ordinal))
            {
                int targetPrecision = ExtractTargetPrecisionNumberForUi(target);
                return targetPrecision > 0 && snapshot.MaxPrecisionStreak >= targetPrecision
                    ? "달성 정박 " + snapshot.MaxPrecisionStreak
                    : "진행 정박 " + snapshot.MaxPrecisionStreak;
            }

            return string.Empty;
        }

        private static int ExtractTargetPrecisionNumberForUi(string target)
        {
            int targetPrecision = ExtractTargetNumberBeforeMarkerForUi(target, "연속");
            if (targetPrecision > 0)
            {
                return targetPrecision;
            }

            return target.Contains("정박", StringComparison.Ordinal)
                ? ExtractTargetNumberAfterKeywordForUi(target, "정박")
                : ExtractTargetNumberAfterKeywordForUi(target, "정확권");
        }

        private static int BuildReviewTargetFocusProgress(GreedLastRunSnapshot snapshot, string target)
        {
            if (target.Contains("발동", StringComparison.Ordinal))
            {
                return snapshot.FocusStateActivationCount;
            }

            return snapshot.FocusStateActivationCount > 0
                ? Mathf.Max(snapshot.Focus, snapshot.MaxFocus)
                : snapshot.Focus;
        }

        private static string BuildReviewTargetFocusProgressText(string target, int progress)
        {
            return target.Contains("발동", StringComparison.Ordinal)
                ? "집중 발동 " + progress + "회"
                : "집중 " + progress;
        }

        private static int ExtractTargetNumberAfterKeywordForUi(string text, string keyword)
        {
            if (string.IsNullOrWhiteSpace(text) || string.IsNullOrEmpty(keyword))
            {
                return 0;
            }

            int keywordIndex = text.IndexOf(keyword, StringComparison.Ordinal);
            return keywordIndex < 0
                ? 0
                : ExtractFirstNumberForUi(text.Substring(keywordIndex + keyword.Length));
        }

        private static int ExtractTargetNumberBeforeMarkerForUi(string text, string marker)
        {
            if (string.IsNullOrWhiteSpace(text) || string.IsNullOrEmpty(marker))
            {
                return 0;
            }

            int markerIndex = text.IndexOf(marker, StringComparison.Ordinal);
            if (markerIndex <= 0)
            {
                return 0;
            }

            int end = markerIndex - 1;
            while (end >= 0 && char.IsWhiteSpace(text[end]))
            {
                end -= 1;
            }

            int start = end;
            while (start >= 0 && char.IsDigit(text[start]))
            {
                start -= 1;
            }

            if (start == end)
            {
                return 0;
            }

            string value = text.Substring(start + 1, end - start);
            return int.TryParse(value, out int number) ? Mathf.Max(0, number) : 0;
        }

        private static int ExtractFirstNumberForUi(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return 0;
            }

            for (int i = 0; i < text.Length; i += 1)
            {
                if (!char.IsDigit(text[i]))
                {
                    continue;
                }

                int start = i;
                while (i < text.Length && char.IsDigit(text[i]))
                {
                    i += 1;
                }

                string value = text.Substring(start, i - start);
                return int.TryParse(value, out int number) ? Mathf.Max(0, number) : 0;
            }

            return 0;
        }

        public static string BuildReviewTargetFeedbackLine(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped
                || string.IsNullOrWhiteSpace(snapshot.ReviewTargetText)
                || snapshot.LastResult == GreedLastJudgementResult.None)
            {
                return string.Empty;
            }

            string target = snapshot.ReviewTargetText;
            if (target.Contains("무실수", StringComparison.Ordinal))
            {
                return snapshot.LastResult == GreedLastJudgementResult.Miss || snapshot.MissCount > 0
                    ? "목표 실패: 실수 " + Mathf.Max(1, snapshot.MissCount)
                    : "목표 유지: 무실수";
            }

            if (target.Contains("보정 0회", StringComparison.Ordinal))
            {
                if (snapshot.LastResult == GreedLastJudgementResult.Good || snapshot.GoodCount > 0)
                {
                    return "목표 실패: 보정 " + Mathf.Max(1, snapshot.GoodCount);
                }

                return snapshot.LastResult == GreedLastJudgementResult.Miss || snapshot.MissCount > 0
                    ? "목표 실패: 실수 " + Mathf.Max(1, snapshot.MissCount)
                    : "목표 유지: 보정 0";
            }

            if (target.Contains("입력 없음", StringComparison.Ordinal))
            {
                int targetNoInput = ExtractTargetNumberAfterKeywordForUi(target, "입력 없음");
                return snapshot.NoInputMissCount <= targetNoInput
                    ? "목표 유지: 입력 없음 " + snapshot.NoInputMissCount + "/" + targetNoInput
                    : "목표 실패: 입력 없음 " + snapshot.NoInputMissCount + "/" + targetNoInput;
            }

            if (target.Contains("추천 보정 적용", StringComparison.Ordinal))
            {
                if (snapshot.TimingRecommendationApplied)
                {
                    return "목표 달성: 추천 보정 " + snapshot.AppliedTimingRecommendationMilliseconds + "ms";
                }

                return snapshot.HasTimingRecommendation
                    ? "목표 진행: 추천 적용 대기"
                    : "목표 진행: 추천 샘플 " + snapshot.TimingRecommendationSampleCount + "/" + snapshot.TimingRecommendationSampleTarget;
            }

            if (target.Contains("콤보", StringComparison.Ordinal))
            {
                int currentCombo = Mathf.Max(snapshot.Combo, snapshot.MaxCombo);
                int targetCombo = ExtractTargetNumberAfterKeywordForUi(target, "콤보");
                if (targetCombo > 0 && currentCombo >= targetCombo)
                {
                    return snapshot.Combo >= targetCombo
                        ? "목표 달성: 콤보 " + currentCombo
                        : "목표 달성 유지: 콤보 " + currentCombo;
                }

                return "목표 진행: 콤보 " + currentCombo;
            }

            if (target.Contains("점", StringComparison.Ordinal))
            {
                int targetScore = ExtractTargetNumberBeforeMarkerForUi(target, "점");
                return targetScore > 0 && snapshot.Score >= targetScore
                    ? "목표 달성: " + snapshot.Score + "점"
                    : "목표 진행: " + snapshot.Score + "점";
            }

            if (target.Contains("구간 생존", StringComparison.Ordinal))
            {
                int targetSections = ExtractTargetNumberBeforeMarkerForUi(target, "구간");
                return targetSections > 0 && snapshot.InfiniteSectionsCleared >= targetSections
                    ? "목표 달성: " + snapshot.InfiniteSectionsCleared + "구간 생존"
                    : "목표 진행: " + snapshot.InfiniteSectionsCleared + "/" + targetSections + "구간";
            }

            if (target.Contains("위협", StringComparison.Ordinal))
            {
                int targetThreat = ExtractTargetNumberAfterKeywordForUi(target, "위협");
                return targetThreat > 0 && snapshot.MaxInfiniteThreatLevel >= targetThreat
                    ? "목표 달성: 위협 " + snapshot.MaxInfiniteThreatLevel
                    : "목표 진행: 위협 " + snapshot.MaxInfiniteThreatLevel;
            }

            if (target.Contains("실수", StringComparison.Ordinal)
                && target.Contains("이하", StringComparison.Ordinal))
            {
                int targetMisses = ExtractTargetNumberAfterKeywordForUi(target, "실수");
                return snapshot.MissCount <= targetMisses
                    ? "목표 유지: 실수 " + snapshot.MissCount + "/" + targetMisses
                    : "목표 실패: 실수 " + snapshot.MissCount + "/" + targetMisses;
            }

            if (target.Contains("체력", StringComparison.Ordinal) || target.Contains("생존", StringComparison.Ordinal))
            {
                int targetHealth = target.Contains("체력", StringComparison.Ordinal)
                    ? ExtractTargetNumberAfterKeywordForUi(target, "체력")
                    : ExtractTargetNumberAfterKeywordForUi(target, "생존");
                return targetHealth > 0 && snapshot.Health >= targetHealth
                    ? "목표 달성: 체력 " + snapshot.Health
                    : "목표 진행: 체력 " + snapshot.Health;
            }

            if (target.Contains("집중", StringComparison.Ordinal))
            {
                int targetFocus = ExtractTargetNumberAfterKeywordForUi(target, "집중");
                int currentFocus = BuildReviewTargetFocusProgress(snapshot, target);
                string focusText = BuildReviewTargetFocusProgressText(target, currentFocus);
                return targetFocus > 0 && currentFocus >= targetFocus
                    ? "목표 달성: " + focusText
                    : "목표 진행: " + focusText;
            }

            if (target.Contains("정박", StringComparison.Ordinal) || target.Contains("정확권", StringComparison.Ordinal))
            {
                int targetPrecision = ExtractTargetPrecisionNumberForUi(target);
                int bestPrecision = Mathf.Max(snapshot.PrecisionStreak, snapshot.MaxPrecisionStreak);
                if (targetPrecision > 0 && bestPrecision >= targetPrecision)
                {
                    return snapshot.PrecisionStreak >= targetPrecision
                        ? "목표 달성: 정박 " + bestPrecision
                        : "목표 달성 유지: 정박 " + bestPrecision;
                }

                return "목표 진행: 정박 " + bestPrecision;
            }

            return string.Empty;
        }

        private static string BuildPrecisionHudText(GreedLastRunSnapshot snapshot)
        {
            return snapshot.PrecisionStreak > 0 ? "  정박 " + snapshot.PrecisionStreak : string.Empty;
        }

        private static string BuildMaxPrecisionHudText(GreedLastRunSnapshot snapshot)
        {
            return snapshot.MaxPrecisionStreak > 0 ? "  최대 정박 " + snapshot.MaxPrecisionStreak : string.Empty;
        }

        private static string BuildThreeActionExactHudSuffix(GreedLastRunSnapshot snapshot)
        {
            return snapshot.ThreeActionExactBundleCount > 0
                ? "  3동작 " + snapshot.ThreeActionExactBundleCount
                : string.Empty;
        }

        private static string BuildThreeActionExactHudResultLine(GreedLastRunSnapshot snapshot)
        {
            string suffix = BuildThreeActionExactHudSuffix(snapshot);
            return string.IsNullOrEmpty(suffix) ? string.Empty : suffix.TrimStart() + "\n";
        }

        private static string BuildStoppedAvoidanceHudLine(GreedLastRunSnapshot snapshot)
        {
            int jumpExact = ExtractRunTimingProfileCount(snapshot.TimingProfile, "점프 정확 ");
            int jumpGood = ExtractRunTimingProfileCount(snapshot.TimingProfile, "점프 보정 ");
            int jumpMiss = ExtractRunTimingProfileCount(snapshot.TimingProfile, "점프 실수 ");
            int slideExact = ExtractRunTimingProfileCount(snapshot.TimingProfile, "숙이기 정확 ");
            int slideGood = ExtractRunTimingProfileCount(snapshot.TimingProfile, "숙이기 보정 ");
            int slideMiss = ExtractRunTimingProfileCount(snapshot.TimingProfile, "숙이기 실수 ");
            int twistExact = ExtractRunTimingProfileCount(snapshot.TimingProfile, "비틀기 정확 ");
            int twistGood = ExtractRunTimingProfileCount(snapshot.TimingProfile, "비틀기 보정 ");
            int twistMiss = ExtractRunTimingProfileCount(snapshot.TimingProfile, "비틀기 실수 ");
            int total = jumpExact + jumpGood + jumpMiss
                + slideExact + slideGood + slideMiss
                + twistExact + twistGood + twistMiss;
            if (total <= 0)
            {
                return string.Empty;
            }

            return "회피 점프 " + FormatRunAvoidanceCounts(jumpExact, jumpGood, jumpMiss)
                + " · 숙 " + FormatRunAvoidanceCounts(slideExact, slideGood, slideMiss)
                + " · 틀 " + FormatRunAvoidanceCounts(twistExact, twistGood, twistMiss)
                + " (정/보/실)\n";
        }

        private static string FormatRunAvoidanceCounts(int exact, int good, int miss)
        {
            return exact + "/" + good + "/" + miss;
        }

        private static string BuildStoppedAvoidanceReviewHudLine(GreedLastRunSnapshot snapshot)
        {
            string bestLabel = string.Empty;
            int bestGood = 0;
            int bestMiss = 0;
            int bestScore = 0;
            SelectStoppedAvoidanceReviewCandidate(
                "바닥→↑점프",
                ExtractRunTimingProfileCount(snapshot.TimingProfile, "점프 보정 "),
                ExtractRunTimingProfileCount(snapshot.TimingProfile, "점프 실수 "),
                ref bestLabel,
                ref bestGood,
                ref bestMiss,
                ref bestScore);
            SelectStoppedAvoidanceReviewCandidate(
                "상단→↓숙이기",
                ExtractRunTimingProfileCount(snapshot.TimingProfile, "숙이기 보정 "),
                ExtractRunTimingProfileCount(snapshot.TimingProfile, "숙이기 실수 "),
                ref bestLabel,
                ref bestGood,
                ref bestMiss,
                ref bestScore);
            SelectStoppedAvoidanceReviewCandidate(
                "측면→↔비틀기",
                ExtractRunTimingProfileCount(snapshot.TimingProfile, "비틀기 보정 "),
                ExtractRunTimingProfileCount(snapshot.TimingProfile, "비틀기 실수 "),
                ref bestLabel,
                ref bestGood,
                ref bestMiss,
                ref bestScore);

            if (bestScore <= 0 || string.IsNullOrEmpty(bestLabel))
            {
                return string.Empty;
            }

            string result = bestMiss > 0
                ? "실수 " + bestMiss + "회"
                : "보정 " + bestGood + "회";
            return "회피 복기 " + bestLabel + " " + result + "\n";
        }

        private static void SelectStoppedAvoidanceReviewCandidate(
            string label,
            int good,
            int miss,
            ref string bestLabel,
            ref int bestGood,
            ref int bestMiss,
            ref int bestScore)
        {
            int clampedGood = Mathf.Max(0, good);
            int clampedMiss = Mathf.Max(0, miss);
            int score = clampedMiss * 3 + clampedGood;
            if (score <= bestScore)
            {
                return;
            }

            bestLabel = label;
            bestGood = clampedGood;
            bestMiss = clampedMiss;
            bestScore = score;
        }

        private static int ExtractRunTimingProfileCount(string timingProfile, string prefix)
        {
            if (string.IsNullOrEmpty(timingProfile) || string.IsNullOrEmpty(prefix))
            {
                return 0;
            }

            int start = timingProfile.IndexOf(prefix, StringComparison.Ordinal);
            if (start < 0)
            {
                return 0;
            }

            start += prefix.Length;
            int end = timingProfile.IndexOf("회", start, StringComparison.Ordinal);
            if (end <= start)
            {
                return 0;
            }

            string value = timingProfile.Substring(start, end - start).Trim();
            return int.TryParse(value, out int number) ? Mathf.Max(0, number) : 0;
        }

        private static int BuildRunHudFontSize(GreedLastRunSnapshot snapshot, string hudText)
        {
            if (snapshot.InfiniteMode && snapshot.Stopped)
            {
                int stoppedLineCount = CountTextLines(hudText);
                int stoppedLongLinePenalty = HasLongTextLine(hudText, 72) ? 2 : 0;
                if (stoppedLineCount >= 7)
                {
                    return 23 - stoppedLongLinePenalty;
                }

                return stoppedLineCount >= 6 ? 25 - stoppedLongLinePenalty : 30 - stoppedLongLinePenalty;
            }

            int lineCount = CountTextLines(hudText);
            int longLinePenalty = HasLongTextLine(hudText, 76) ? 1 : 0;
            if (lineCount >= 7)
            {
                return 23 - longLinePenalty;
            }

            if (lineCount >= 6)
            {
                return 24 - longLinePenalty;
            }

            return lineCount <= 4 ? 30 - longLinePenalty : 26 - longLinePenalty;
        }

        private void UpdateRunHudLayout(string hudText)
        {
            if (runHudText == null)
            {
                return;
            }

            int lineCount = CountTextLines(hudText);
            if (lineCount >= 8)
            {
                SetAnchored(runHudText.rectTransform, 0.5f, 0.292f, 930f, 330f);
                return;
            }

            if (lineCount >= 7)
            {
                SetAnchored(runHudText.rectTransform, 0.5f, 0.282f, 930f, 305f);
                return;
            }

            if (lineCount >= 6)
            {
                SetAnchored(runHudText.rectTransform, 0.5f, 0.268f, 910f, 275f);
                return;
            }

            if (lineCount <= 4)
            {
                SetAnchored(runHudText.rectTransform, 0.5f, 0.252f, 920f, 220f);
                return;
            }

            SetAnchored(runHudText.rectTransform, 0.5f, 0.255f, 900f, 245f);
        }

        private static string BuildRunObjectiveLine(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped)
            {
                return string.Empty;
            }

            if (snapshot.Paused)
            {
                return "목표: 재개 카운트 뒤 앞 박자 여유 확인\n";
            }

            if (snapshot.ChoiceActive)
            {
                return "목표: 루트 선택으로 다음 보정 결정\n";
            }

            if (snapshot.PracticeMode)
            {
                return BuildPracticeObjectiveLine(snapshot);
            }

            if (snapshot.InfiniteMode)
            {
                return "목표: 위협 " + snapshot.InfiniteThreatLevel + " 생존 / 무한 기록 갱신"
                    + BuildRunMicroObjectiveSuffix(snapshot) + "\n";
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                return "목표: 공명핵 들고 " + BuildEscapeGateProgressText(snapshot) + " 통과"
                    + BuildRunMicroObjectiveSuffix(snapshot) + "\n";
            }

            if (snapshot.CoreRetrieved)
            {
                return "목표: 탈출 구간 진입 준비"
                    + BuildRunMicroObjectiveSuffix(snapshot) + "\n";
            }

            return "목표: 챕터 돌파로 공명핵 회수"
                + BuildRunMicroObjectiveSuffix(snapshot) + "\n";
        }

        private static string BuildEscapeGateProgressText(GreedLastRunSnapshot snapshot)
        {
            return BuildEscapeGateProgressText(snapshot, snapshot.ChapterTarget);
        }

        private static string BuildEscapeGateProgressText(GreedLastRunSnapshot snapshot, int target)
        {
            int safeTarget = Mathf.Max(1, target);
            int progress = snapshot.EscapeSucceeded
                ? safeTarget
                : Mathf.Clamp(snapshot.ChapterProgress, 0, safeTarget);
            string prefix = Mathf.Max(0, safeTarget - progress) <= 1 ? "입구 직전 게이트 " : "탈출 게이트 ";
            return prefix + progress + "/" + safeTarget;
        }

        private static string BuildRunMicroObjectiveSuffix(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped || snapshot.Paused || snapshot.CountdownActive || snapshot.ChoiceActive)
            {
                return string.Empty;
            }

            string timingCorrectionObjective = BuildJudgementCorrectionObjectiveSuffix(snapshot);
            if (snapshot.Health <= 1)
            {
                return " / 생존 우선"
                    + BuildPatternObjectiveSuffix(snapshot)
                    + BuildStageTransitionObjectiveSuffix(snapshot)
                    + timingCorrectionObjective;
            }

            string transitionObjective = BuildStageTransitionObjectiveSuffix(snapshot);
            string patternObjective = BuildPatternObjectiveSuffix(snapshot);
            if (!string.IsNullOrEmpty(transitionObjective)
                && !string.IsNullOrEmpty(patternObjective))
            {
                return patternObjective + transitionObjective + timingCorrectionObjective;
            }

            if (!string.IsNullOrEmpty(transitionObjective))
            {
                return transitionObjective + timingCorrectionObjective;
            }

            if (!string.IsNullOrEmpty(patternObjective))
            {
                return patternObjective + timingCorrectionObjective;
            }

            if (!string.IsNullOrEmpty(timingCorrectionObjective))
            {
                return timingCorrectionObjective;
            }

            if (snapshot.FocusStateActive)
            {
                return " / 집중 고점 유지";
            }

            if (snapshot.InfiniteMode && WillInfiniteThreatRiseAfterSection(snapshot))
            {
                return " / 위협 상승 임박";
            }

            int precisionRewardRemaining = BuildPrecisionRewardRemaining(snapshot);
            if (precisionRewardRemaining > 0 && precisionRewardRemaining <= 2)
            {
                return " / 정박 보상까지 " + precisionRewardRemaining;
            }

            int chainRewardRemaining = BuildNextChainRemaining(snapshot);
            if (chainRewardRemaining > 0 && chainRewardRemaining <= 2)
            {
                return " / 연쇄 보너스까지 " + chainRewardRemaining;
            }

            string profileObjective = BuildChoiceProfileObjectiveSuffix(snapshot);
            if (!string.IsNullOrEmpty(profileObjective))
            {
                return profileObjective;
            }

            return string.Empty;
        }

        private static string BuildJudgementCorrectionObjectiveSuffix(GreedLastRunSnapshot snapshot)
        {
            switch (snapshot.LastResult)
            {
                case GreedLastJudgementResult.Good:
                    string goodHint = BuildTimingGoodFeedbackHint(snapshot);
                    return string.IsNullOrEmpty(goodHint) ? string.Empty : " / " + goodHint;
                case GreedLastJudgementResult.Miss:
                    if (snapshot.MissReason == "wrong_channel")
                    {
                        return " / 정답 채널 확인";
                    }

                    if (snapshot.MissReason == "no_input")
                    {
                        return " / 다음 함정 입력";
                    }

                    string missHint = BuildTimingMissFeedbackHint(snapshot.MissReason);
                    return string.IsNullOrEmpty(missHint) ? string.Empty : " / " + missHint;
                default:
                    return string.Empty;
            }
        }

        private static string BuildJudgedInputTimingLine(GreedLastRunSnapshot snapshot)
        {
            return snapshot.HasJudgedInputTiming
                ? GreedLastRunCore.FormatTimingDelta(snapshot.LastInputTimingDeltaSeconds) : string.Empty;
        }

        private static string BuildStageTransitionObjectiveSuffix(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped || snapshot.Paused || snapshot.CountdownActive || snapshot.ChoiceActive)
            {
                return string.Empty;
            }

            int target = Mathf.Max(1, snapshot.ChapterTarget);
            int remaining = target - snapshot.ChapterProgress;
            if (remaining != 1)
            {
                return string.Empty;
            }

            string routeFinish = snapshot.PerfectBundleIntact
                ? BuildRouteBundleObjectiveSuffix(snapshot)
                : string.Empty;

            if (snapshot.InfiniteMode)
            {
                string infiniteTransition = WillInfiniteThreatRiseAfterSection(snapshot)
                    ? " / 다음 통과로 위협 상승"
                    : " / 다음 통과로 구간 정산";
                return routeFinish + infiniteTransition;
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                return routeFinish + " / 다음 통과로 탈출";
            }

            if (!snapshot.CoreRetrieved && snapshot.ChapterIndex >= 4)
            {
                return routeFinish + " / 다음 통과로 공명핵";
            }

            return routeFinish + " / 다음 통과로 선택지";
        }

        private static string BuildRouteBundleObjectiveSuffix(GreedLastRunSnapshot snapshot)
        {
            switch (snapshot.ActiveRouteProfile)
            {
                case "안정 루트":
                    return snapshot.GoodHealthGainPreview > 0 ? " / 안정 완주 회복" : " / 안정 완주 집중";
                case "변주 루트":
                    return " / 변주 완주 집중 보상";
                case "압박 루트":
                    return " / 압박 완주 +" + GreedLastRunCore.PressureRouteBundleScoreBonus;
                default:
                    return string.Empty;
            }
        }

        public static string BuildLiveRunCoachLine(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped || snapshot.Paused || snapshot.CountdownActive || snapshot.ChoiceActive)
            {
                return string.Empty;
            }

            string coach = BuildImmediateJudgementCoach(snapshot);
            if (string.IsNullOrEmpty(coach))
            {
                coach = BuildActivePatternCoach(snapshot);
            }

            string routeStepCoach = BuildRouteStepCoach(snapshot);
            if (!string.IsNullOrEmpty(routeStepCoach))
            {
                coach = string.IsNullOrEmpty(coach) ? routeStepCoach : coach + " / " + routeStepCoach;
            }

            string pressure = BuildPressureCoachSuffix(snapshot);
            if (!string.IsNullOrEmpty(pressure))
            {
                coach = string.IsNullOrEmpty(coach) ? pressure : coach + " / " + pressure;
            }

            coach = PrependPrototypePayoffGoalCoach(snapshot, coach);
            return string.IsNullOrEmpty(coach) ? string.Empty : "코칭 " + CompactUiText(coach, 66);
        }

        private static string PrependPrototypePayoffGoalCoach(GreedLastRunSnapshot snapshot, string coach)
        {
            if (!snapshot.Pattern.IsValid
                || (snapshot.LastResult != GreedLastJudgementResult.None
                    && snapshot.LastResult != GreedLastJudgementResult.Success))
            {
                return coach;
            }

            string payoffGoal = BuildPrototypeFeelPayoffGoal(snapshot);
            if (string.IsNullOrEmpty(payoffGoal))
            {
                return coach;
            }

            string prefix = "정확→" + payoffGoal;
            if (!string.IsNullOrEmpty(coach) && coach.Contains(prefix, StringComparison.Ordinal))
            {
                return coach;
            }

            return string.IsNullOrEmpty(coach) ? prefix : prefix + " / " + coach;
        }

        private static string BuildRouteStepCoach(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.LastResult == GreedLastJudgementResult.None
                || !TryGetNextRouteCadenceStep(snapshot, out string routeLabel, out string nextTiming, out string nextAction))
            {
                return string.Empty;
            }

            return snapshot.PerfectBundleIntact
                ? routeLabel + " " + snapshot.ChapterProgress + "/" + snapshot.ChapterTarget
                    + " / 다음 " + nextTiming + " · " + nextAction
                : "다음 " + nextTiming + " 연습 · " + nextAction + " / " + routeLabel + " 완주 중단";
        }

        private static string BuildImmediateJudgementCoach(GreedLastRunSnapshot snapshot)
        {
            switch (snapshot.LastResult)
            {
                case GreedLastJudgementResult.Miss:
                    switch (snapshot.MissReason)
                    {
                        case "wrong_channel":
                            return "채널 먼저 확인";
                        case "no_input":
                            return "다음 함정 입력 준비";
                        case "too_early":
                            return AppendRecentTimingNudgeCoach(snapshot, "살짝 늦게 / 판정선 가까이");
                        case "too_late":
                            return AppendRecentTimingNudgeCoach(snapshot, "살짝 빠르게 / 소리 앞박");
                        default:
                            return "회복 우선";
                    }
                case GreedLastJudgementResult.Good:
                    if (IsRecoveryPattern(snapshot.Pattern))
                    {
                        return AppendRecentTimingNudgeCoach(
                            snapshot,
                            AppendGoodMissedExactPayoffCoach(snapshot, "복구 성공 / 다음 정박으로 연쇄 재시동"));
                    }

                    return AppendRecentTimingNudgeCoach(
                        snapshot,
                        AppendGoodMissedExactPayoffCoach(snapshot, "보정권 생존 / 판정선 안쪽으로"));
                case GreedLastJudgementResult.Success:
                    string reviewTargetCoach = BuildReviewTargetCoach(snapshot);
                    if (!string.IsNullOrEmpty(reviewTargetCoach))
                    {
                        return reviewTargetCoach;
                    }

                    if (IsRecoveryPattern(snapshot.Pattern))
                    {
                        string recoveryCoach = snapshot.LastCenterHit
                            ? "흐름 회복 완료 / 연쇄 재시동"
                            : "흐름 복귀 / 다음은 판정선 중앙";
                        return AppendImmediatePrecisionRewardCoach(snapshot, recoveryCoach);
                    }

                    if (snapshot.LastCenterHit && snapshot.Pattern.TimingType == GreedLastTimingType.Perfect)
                    {
                        return AppendImmediatePrecisionRewardCoach(snapshot, snapshot.LastJudgementStartedInFocusState
                            ? "정박 집중 유지 / 고점 연장" : "정박 충전 / 집중 가속");
                    }

                    if (snapshot.LastCenterHit && snapshot.Pattern.TimingType == GreedLastTimingType.Clutch)
                    {
                        return AppendImmediatePrecisionRewardCoach(snapshot, "압박 반격 성공 / 고점 확보");
                    }

                    if (snapshot.LastCenterHit && snapshot.Pattern.TimingType == GreedLastTimingType.Offbeat)
                    {
                        return AppendImmediatePrecisionRewardCoach(snapshot, "엇박 포착 / 연쇄 가속");
                    }

                    int precisionRewardRemaining = BuildPrecisionRewardRemaining(snapshot);
                    if (precisionRewardRemaining > 0 && precisionRewardRemaining <= 2)
                    {
                        return "정박 보상까지 " + precisionRewardRemaining + "회";
                    }

                    return string.Empty;
                default:
                    return string.Empty;
            }
        }

        private static string AppendRecentTimingNudgeCoach(GreedLastRunSnapshot snapshot, string coach)
        {
            string timingNudge = BuildRecentTimingNudgeCoach(snapshot);
            return string.IsNullOrEmpty(timingNudge)
                ? coach
                : coach + " / " + timingNudge;
        }

        private static string AppendGoodMissedExactPayoffCoach(GreedLastRunSnapshot snapshot, string coach)
        {
            string missedExactPayoff = BuildGoodMissedExactPayoffLine(snapshot);
            if (string.IsNullOrEmpty(missedExactPayoff)
                || (!string.IsNullOrEmpty(coach) && coach.Contains(missedExactPayoff, StringComparison.Ordinal)))
            {
                return coach;
            }

            return string.IsNullOrEmpty(coach) ? missedExactPayoff : coach + " / " + missedExactPayoff;
        }

        private static string BuildRecentTimingNudgeCoach(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.HasJudgedInputTiming)
            {
                return string.Empty;
            }

            float signedDeltaSeconds = snapshot.LastInputTimingDeltaSeconds;
            int milliseconds = Mathf.RoundToInt(Mathf.Abs(signedDeltaSeconds) * 1000f);
            if (milliseconds <= 20)
            {
                return string.Empty;
            }

            return signedDeltaSeconds < 0f
                ? "빠름 " + milliseconds + "ms→살짝 늦게"
                : "늦음 " + milliseconds + "ms→살짝 빠르게";
        }

        private static string AppendImmediatePrecisionRewardCoach(
            GreedLastRunSnapshot snapshot,
            string coach)
        {
            int precisionRewardRemaining = BuildPrecisionRewardRemaining(snapshot);
            if (precisionRewardRemaining == 0)
            {
                return coach + " / 정박 보상 획득";
            }

            return precisionRewardRemaining > 0 && precisionRewardRemaining <= 2
                ? coach + " / 정박 보상까지 " + precisionRewardRemaining + "회"
                : coach;
        }

        private static string BuildReviewTargetCoach(GreedLastRunSnapshot snapshot)
        {
            string target = snapshot.ReviewTargetText ?? string.Empty;
            if (string.IsNullOrWhiteSpace(target))
            {
                return string.Empty;
            }

            if (target.Contains("무실수", StringComparison.Ordinal))
            {
                return snapshot.MissCount <= 0 ? "무실수 목표 유지" : string.Empty;
            }

            if (target.Contains("보정 0회", StringComparison.Ordinal))
            {
                return snapshot.GoodCount <= 0 && snapshot.MissCount <= 0
                    ? "보정 0회 목표 유지"
                    : string.Empty;
            }

            if (target.Contains("입력 없음", StringComparison.Ordinal))
            {
                int targetNoInput = ExtractTargetNumberAfterKeywordForUi(target, "입력 없음");
                int remaining = targetNoInput - snapshot.NoInputMissCount;
                return remaining < 0 ? "입력 누락 목표 실패" : "입력 누락 허용 " + remaining + "회";
            }

            if (target.Contains("추천 보정 적용", StringComparison.Ordinal))
            {
                if (snapshot.TimingRecommendationApplied)
                {
                    return "추천 보정 목표 달성";
                }

                return snapshot.HasTimingRecommendation ? "가운데 추천 적용" : "추천 샘플 수집";
            }

            if (target.Contains("콤보", StringComparison.Ordinal))
            {
                int targetCombo = ExtractTargetNumberAfterKeywordForUi(target, "콤보");
                int remaining = targetCombo - Mathf.Max(snapshot.Combo, snapshot.MaxCombo);
                return targetCombo <= 0
                    ? string.Empty
                    : remaining <= 0 ? "콤보 목표 달성" : "목표까지 콤보 " + remaining;
            }

            if (target.Contains("점", StringComparison.Ordinal))
            {
                int targetScore = ExtractTargetNumberBeforeMarkerForUi(target, "점");
                int remaining = targetScore - snapshot.Score;
                return targetScore <= 0
                    ? string.Empty
                    : remaining <= 0 ? "점수 목표 달성" : "목표까지 " + remaining + "점";
            }

            if (target.Contains("구간 생존", StringComparison.Ordinal))
            {
                int targetSections = ExtractTargetNumberBeforeMarkerForUi(target, "구간");
                int remaining = targetSections - snapshot.InfiniteSectionsCleared;
                return targetSections <= 0
                    ? string.Empty
                    : remaining <= 0 ? "생존 구간 목표 달성" : "목표까지 " + remaining + "구간";
            }

            if (target.Contains("위협", StringComparison.Ordinal))
            {
                int targetThreat = ExtractTargetNumberAfterKeywordForUi(target, "위협");
                int remaining = targetThreat - snapshot.MaxInfiniteThreatLevel;
                return targetThreat <= 0
                    ? string.Empty
                    : remaining <= 0 ? "위협 목표 달성" : "목표 위협까지 " + remaining;
            }

            if (target.Contains("실수", StringComparison.Ordinal)
                && target.Contains("이하", StringComparison.Ordinal))
            {
                int targetMisses = ExtractTargetNumberAfterKeywordForUi(target, "실수");
                int remaining = targetMisses - snapshot.MissCount;
                return remaining < 0 ? "허용 실수 초과" : "허용 실수 " + remaining + "회 남음";
            }

            if (target.Contains("체력", StringComparison.Ordinal) || target.Contains("생존", StringComparison.Ordinal))
            {
                int targetHealth = target.Contains("체력", StringComparison.Ordinal)
                    ? ExtractTargetNumberAfterKeywordForUi(target, "체력")
                    : ExtractTargetNumberAfterKeywordForUi(target, "생존");
                int remaining = targetHealth - snapshot.Health;
                return targetHealth <= 0
                    ? string.Empty
                    : remaining <= 0 ? "목표 체력 유지" : "목표 체력까지 " + remaining;
            }

            if (target.Contains("집중", StringComparison.Ordinal))
            {
                int targetFocus = ExtractTargetNumberAfterKeywordForUi(target, "집중");
                int currentFocus = BuildReviewTargetFocusProgress(snapshot, target);
                int remaining = targetFocus - currentFocus;
                bool activationTarget = target.Contains("발동", StringComparison.Ordinal);
                if (targetFocus <= 0)
                {
                    return string.Empty;
                }

                if (remaining <= 0)
                {
                    return activationTarget ? "집중 발동 목표 달성" : "집중 목표 달성";
                }

                return activationTarget
                    ? "목표까지 집중 발동 " + remaining + "회"
                    : "목표 집중까지 " + remaining;
            }

            if (target.Contains("정박", StringComparison.Ordinal) || target.Contains("정확권", StringComparison.Ordinal))
            {
                int targetPrecision = ExtractTargetPrecisionNumberForUi(target);
                int remaining = targetPrecision - Mathf.Max(snapshot.PrecisionStreak, snapshot.MaxPrecisionStreak);
                return targetPrecision <= 0
                    ? string.Empty
                    : remaining <= 0 ? "정박 목표 달성" : "목표까지 정박 " + remaining + "회";
            }

            return string.Empty;
        }

        private static string BuildActivePatternCoach(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ActivePattern)
            {
                return string.Empty;
            }

            string beatCue = BuildActivePatternBeatCue(snapshot);
            string prompt = snapshot.Pattern.Prompt ?? string.Empty;
            string coach;
            if (prompt.Contains("[복구]", StringComparison.Ordinal))
            {
                coach = "복구 패턴 / 정확권 재진입";
                string recoveryRoutePayoff = BuildActiveRoutePayoffCoach(snapshot);
                if (!string.IsNullOrEmpty(recoveryRoutePayoff))
                {
                    coach += " / " + recoveryRoutePayoff;
                }
            }
            else
            {
                string variation = BuildActivePatternVariationCoachPrefix(prompt);
                switch (snapshot.Pattern.TimingType)
                {
                    case GreedLastTimingType.Perfect:
                        coach = snapshot.FocusStateActive ? "정박 타이밍 / " + BuildActiveFocusPayoffHint(snapshot)
                            : "정박 타이밍 / 중앙 집중 +" + GreedLastRunCore.PerfectFocusChargeBonus;
                        break;
                    case GreedLastTimingType.Clutch:
                        coach = "압박 타이밍 / 정박 반격 +" + GreedLastRunCore.ClutchCounterScoreBonus;
                        break;
                    case GreedLastTimingType.Offbeat:
                        coach = "엇박 타이밍 / 정박 연쇄 +" + GreedLastRunCore.OffbeatFlowComboBonus;
                        break;
                    default:
                        coach = string.Empty;
                        break;
                }

                string routePayoff = BuildActiveRoutePayoffCoach(snapshot);
                if (!string.IsNullOrEmpty(routePayoff))
                {
                    coach = string.IsNullOrEmpty(coach) ? routePayoff : routePayoff + " / " + coach;
                }
                else if (!string.IsNullOrEmpty(variation))
                {
                    coach = string.IsNullOrEmpty(coach) ? variation : variation + " / " + coach;
                }
            }

            string chapterRole = BuildChapterRoleCoachPrefix(snapshot);
            if (!string.IsNullOrEmpty(chapterRole))
            {
                coach = string.IsNullOrEmpty(coach) ? chapterRole : chapterRole + " / " + coach;
            }

            string avoidance = BuildActiveAvoidanceCoach(snapshot.Pattern);
            if (!string.IsNullOrEmpty(avoidance))
            {
                coach = string.IsNullOrEmpty(coach) ? avoidance : avoidance + " / " + coach;
            }

            return AppendCoachBeatCue(coach, beatCue);
        }

        private static string BuildActiveAvoidanceCoach(GreedLastPatternModel pattern)
        {
            if (!pattern.IsValid)
            {
                return string.Empty;
            }

            return BuildTrapResponseCueLabel(pattern) + " " + BuildPatternActionVerb(pattern);
        }

        private static string BuildChapterRoleCoachPrefix(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.InfiniteMode || snapshot.PracticeMode)
            {
                return string.Empty;
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                return "탈출 검증";
            }

            if (snapshot.ChapterIndex >= 4)
            {
                return "공명핵 검증";
            }

            return snapshot.ChapterIndex == 3 ? "변주 정점" : string.Empty;
        }

        private static string BuildActiveRoutePayoffCoach(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel pattern = snapshot.Pattern;
            string prompt = pattern.Prompt ?? string.Empty;
            if (snapshot.ActiveRouteProfile == "안정 루트")
            {
                return snapshot.GoodHealthGainPreview > 0
                    ? "안정 보험 / 보정 체력 +" + snapshot.GoodHealthGainPreview : "안정 보험 / 회복 상한";
            }

            if (prompt.Contains("[변주]", StringComparison.Ordinal)
                && pattern.TimingType == GreedLastTimingType.Offbeat)
            {
                return snapshot.FocusStateActive ? "변주 공명 / " + BuildActiveFocusPayoffHint(snapshot)
                    : "변주 공명 / 집중 +" + GreedLastRunCore.VariationRouteOffbeatFocusBonus;
            }

            if (prompt.Contains("[압박]", StringComparison.Ordinal)
                && pattern.TimingType == GreedLastTimingType.Clutch)
            {
                return "압박 증폭 / 반격 +" + GreedLastRunCore.PressureRouteClutchScoreBonus;
            }

            return string.Empty;
        }

        private static string BuildActivePatternVariationCoachPrefix(string prompt)
        {
            if (prompt.Contains("[탈출]", StringComparison.Ordinal))
            {
                return "탈출 압박";
            }

            if (prompt.Contains("[위기]", StringComparison.Ordinal))
            {
                return "위기 패턴";
            }

            if (prompt.Contains("[유예]", StringComparison.Ordinal))
            {
                return "유예 패턴";
            }

            if (prompt.Contains("[안정]", StringComparison.Ordinal))
            {
                return "안정 패턴";
            }

            if (prompt.Contains("[변주]", StringComparison.Ordinal))
            {
                return "변주 패턴";
            }

            if (prompt.Contains("[압박]", StringComparison.Ordinal)
                || prompt.Contains("[심층]", StringComparison.Ordinal))
            {
                return "압박 패턴";
            }

            return string.Empty;
        }

        private static string AppendCoachBeatCue(string coach, string beatCue)
        {
            if (string.IsNullOrEmpty(beatCue))
            {
                return coach;
            }

            return string.IsNullOrEmpty(coach) ? beatCue : coach + " / " + beatCue;
        }

        private static string BuildPressureCoachSuffix(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Health <= 1)
            {
                return "생존 우선";
            }

            if (snapshot.InfiniteMode && snapshot.CurrentSegmentMissCount > 0)
            {
                return "현재 구간 실수 " + snapshot.CurrentSegmentMissCount;
            }

            if (snapshot.InfiniteMode && WillInfiniteThreatRiseAfterSection(snapshot))
            {
                return "위협 상승 전 정박";
            }

            if (!snapshot.FocusStateActive && snapshot.Focus == snapshot.MaxFocus - 1 && snapshot.MaxFocus > 1)
            {
                return "집중 1칸 남음";
            }

            if (snapshot.LastResult == GreedLastJudgementResult.Success)
            {
                return string.Empty;
            }

            return BuildRewardCoachSuffix(snapshot);
        }

        private static string BuildRewardCoachSuffix(GreedLastRunSnapshot snapshot)
        {
            int precisionRewardRemaining = BuildPrecisionRewardRemaining(snapshot);
            if (precisionRewardRemaining == 0)
            {
                return "정박 보상 획득";
            }

            if (precisionRewardRemaining > 0 && precisionRewardRemaining <= 2)
            {
                return "정박 보상 " + precisionRewardRemaining + "회";
            }

            int chainRewardRemaining = BuildNextChainRemaining(snapshot);
            if (chainRewardRemaining > 0 && chainRewardRemaining <= 2)
            {
                return "연쇄 보너스 " + chainRewardRemaining + "회";
            }

            return string.Empty;
        }

        private static string BuildChoiceProfileObjectiveSuffix(GreedLastRunSnapshot snapshot)
        {
            switch (snapshot.ActiveChoiceProfile)
            {
                case "안정형":
                    return snapshot.GoodHealthGainPreview > 0 ? " / 안정 회복" : " / 안전 돌파";
                case "집중형":
                    return snapshot.FocusStateActive ? " / " + BuildActiveFocusPayoffHint(snapshot) : " / 집중 채우기";
                case "연쇄형":
                    return snapshot.Combo <= 0 ? " / 연쇄 시동" : " / 연쇄 유지";
                case "고점형":
                    return snapshot.PrecisionStreak <= 0 ? " / 정박 고점" : " / 고점 유지";
                case "균형형":
                    return " / 균형 유지";
                default:
                    return string.Empty;
            }
        }

        private static string BuildPatternObjectiveSuffix(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel pattern = snapshot.Pattern;
            string prompt = pattern.Prompt ?? string.Empty;
            string objective;
            if (prompt.Contains("[복구]", StringComparison.Ordinal))
            {
                objective = " / 복구 정박 +" + GreedLastRunCore.RecoveryPrecisionScoreBonus
                    + " / 연쇄 +" + GreedLastRunCore.RecoveryPrecisionComboBonus;
            }
            else if (pattern.TimingType == GreedLastTimingType.Perfect)
            {
                objective = snapshot.FocusStateActive ? " / 정박 " + BuildActiveFocusPayoffHint(snapshot)
                    : " / 정박 중앙 집중 +" + GreedLastRunCore.PerfectFocusChargeBonus;
            }
            else if (pattern.TimingType == GreedLastTimingType.Clutch)
            {
                objective = " / 압박 정박 반격 +" + GreedLastRunCore.ClutchCounterScoreBonus;
            }
            else if (pattern.TimingType == GreedLastTimingType.Offbeat)
            {
                objective = " / 엇박 정박 연쇄 +" + GreedLastRunCore.OffbeatFlowComboBonus;
            }
            else if (prompt.Contains("[탈출]", StringComparison.Ordinal))
            {
                objective = " / 탈출 집중";
            }
            else if (prompt.Contains("[압박]", StringComparison.Ordinal))
            {
                objective = " / 압박 정박";
            }
            else if (prompt.Contains("[심층]", StringComparison.Ordinal))
            {
                objective = " / 심층 집중";
            }
            else if (prompt.Contains("[변주]", StringComparison.Ordinal))
            {
                objective = " / 엇박 대응";
            }
            else if (prompt.Contains("[안정]", StringComparison.Ordinal))
            {
                objective = " / 안정 돌파";
            }
            else
            {
                objective = string.Empty;
            }

            return BuildPatternAvoidanceObjectiveSuffix(pattern)
                + objective
                + BuildRoutePatternObjectiveSuffix(snapshot);
        }

        private static string BuildPatternAvoidanceObjectiveSuffix(GreedLastPatternModel pattern)
        {
            if (!pattern.IsValid)
            {
                return string.Empty;
            }

            return " / " + BuildTrapResponseCueLabel(pattern) + " " + BuildPatternActionVerb(pattern);
        }

        private static string BuildRoutePatternObjectiveSuffix(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel pattern = snapshot.Pattern;
            string prompt = pattern.Prompt ?? string.Empty;
            if (snapshot.ActiveRouteProfile == "안정 루트")
            {
                return snapshot.GoodHealthGainPreview > 0
                    ? " / 보정 체력 +" + snapshot.GoodHealthGainPreview : " / 회복 상한";
            }

            if (prompt.Contains("[변주]", StringComparison.Ordinal)
                && pattern.TimingType == GreedLastTimingType.Offbeat)
            {
                return snapshot.FocusStateActive ? " / 변주 " + BuildActiveFocusPayoffHint(snapshot)
                    : " / 변주 집중 +" + GreedLastRunCore.VariationRouteOffbeatFocusBonus;
            }

            if (prompt.Contains("[압박]", StringComparison.Ordinal)
                && pattern.TimingType == GreedLastTimingType.Clutch)
            {
                return " / 압박 증폭 +" + GreedLastRunCore.PressureRouteClutchScoreBonus;
            }

            return string.Empty;
        }

        private static string BuildRunFlowLine(GreedLastRunSnapshot snapshot)
        {
            int total = snapshot.SuccessCount + snapshot.GoodCount + snapshot.MissCount;
            if (total <= 0)
            {
                return string.Empty;
            }

            string tag = BuildRunFlowTag(snapshot, total);
            string prefix = snapshot.InfiniteMode
                ? "누적 " + snapshot.InfiniteSectionsCleared + "구간"
                : "흐름";
            return prefix
                + $"  정확 {snapshot.SuccessCount}  보정 {snapshot.GoodCount}  실수 {snapshot.MissCount}"
                + " / " + tag
                + BuildRecentPatternFlowSuffix(snapshot)
                + "\n";
        }

        private static string BuildRunFlowTag(GreedLastRunSnapshot snapshot, int total)
        {
            if (snapshot.Health <= 1 && snapshot.MissCount > 0)
            {
                return "위험";
            }

            if (snapshot.MissCount >= Math.Max(2L, (long)snapshot.SuccessCount + snapshot.GoodCount))
            {
                return "흔들림";
            }

            if (snapshot.ThreeActionExactBundleCount > 0 && snapshot.MissCount <= 0)
            {
                return "3동작 정확";
            }

            if (snapshot.Combo >= 6)
            {
                return "연쇄 좋음";
            }

            if (snapshot.PrecisionStreak >= 3)
            {
                return "정박 좋음";
            }

            if (snapshot.SuccessCount >= snapshot.GoodCount + snapshot.MissCount + 2)
            {
                return "정확 우세";
            }

            if (snapshot.GoodCount > snapshot.SuccessCount && snapshot.GoodCount >= Mathf.Max(2, total / 2))
            {
                return "보정 의존";
            }

            string timingAxisFlowTag = BuildDominantTimingAxisFlowTag(snapshot);
            if (!string.IsNullOrEmpty(timingAxisFlowTag))
            {
                return timingAxisFlowTag;
            }

            string profileFlowTag = BuildChoiceProfileFlowTag(snapshot);
            if (!string.IsNullOrEmpty(profileFlowTag))
            {
                return profileFlowTag;
            }

            return "균형";
        }

        private static string BuildDominantTimingAxisFlowTag(GreedLastRunSnapshot snapshot)
        {
            int total = snapshot.PerfectSuccessCount + snapshot.ClutchSuccessCount + snapshot.OffbeatSuccessCount;
            if (total < 4)
            {
                return string.Empty;
            }

            int top = Mathf.Max(snapshot.PerfectSuccessCount, snapshot.ClutchSuccessCount, snapshot.OffbeatSuccessCount);
            int second = snapshot.PerfectSuccessCount == top
                ? Mathf.Max(snapshot.ClutchSuccessCount, snapshot.OffbeatSuccessCount)
                : snapshot.ClutchSuccessCount == top
                    ? Mathf.Max(snapshot.PerfectSuccessCount, snapshot.OffbeatSuccessCount)
                    : Mathf.Max(snapshot.PerfectSuccessCount, snapshot.ClutchSuccessCount);
            if (top < second + 2)
            {
                return string.Empty;
            }

            return snapshot.PerfectSuccessCount == top
                ? "정박 우세"
                : snapshot.ClutchSuccessCount == top ? "압박 우세" : "엇박 우세";
        }

        private static string BuildRecentPatternFlowSuffix(GreedLastRunSnapshot snapshot)
        {
            if (!DevToolsEnabled
                || snapshot.Stopped
                || snapshot.Paused
                || snapshot.CountdownActive
                || snapshot.ChoiceActive
                || string.IsNullOrEmpty(snapshot.RecentPatternFlow))
            {
                return string.Empty;
            }

            return " / 최근 " + snapshot.RecentPatternFlow;
        }

        private static string BuildChoiceProfileFlowTag(GreedLastRunSnapshot snapshot)
        {
            switch (snapshot.ActiveChoiceProfile)
            {
                case "안정형":
                    return snapshot.Health >= Mathf.Max(2, snapshot.MaxHealth - 1) ? "안정 유지" : string.Empty;
                case "집중형":
                    return snapshot.Focus >= snapshot.MaxFocus - 1 ? "집중 흐름" : string.Empty;
                case "연쇄형":
                    return snapshot.MaxCombo >= 3 ? "연쇄 축적" : string.Empty;
                case "고점형":
                    return snapshot.Score >= 300 ? "고점 축적" : string.Empty;
                case "균형형":
                    return "균형 유지";
                default:
                    return string.Empty;
            }
        }

        private static string BuildChoiceHeaderPreview(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ChoiceActive)
            {
                return string.Empty;
            }

            string leftHint = BuildCurrentChoiceHeaderPreviewPart(snapshot, snapshot.ChoiceLeft);
            string centerHint = BuildCurrentChoiceHeaderPreviewPart(snapshot, snapshot.ChoiceCenter);
            string rightHint = BuildCurrentChoiceHeaderPreviewPart(snapshot, snapshot.ChoiceRight);
            if (string.IsNullOrEmpty(leftHint)
                && string.IsNullOrEmpty(centerHint)
                && string.IsNullOrEmpty(rightHint))
            {
                return string.Empty;
            }

            return "좌 " + leftHint + " / 중 " + centerHint + " / 우 " + rightHint;
        }

        private static string BuildCurrentChoiceHeaderPreviewPart(GreedLastRunSnapshot snapshot, string choiceName)
        {
            return snapshot.ChoiceKind == GreedLastChoiceKind.Node
                ? BuildChoiceHeaderPreviewPart(snapshot.ChoiceKind, choiceName)
                : BuildCurrentChoiceEffectHint(snapshot, choiceName);
        }

        private static string BuildChoiceHeaderPreviewPart(GreedLastChoiceKind kind, string choiceName)
        {
            if (kind == GreedLastChoiceKind.Node && IsRouteChoiceName(choiceName))
            {
                return BuildRouteChoiceShortName(choiceName)
                    + " " + BuildRouteCadenceText(choiceName)
                    + "/" + BuildAvoidanceCadenceText(choiceName, false, -1);
            }

            return BuildChoiceEffectHint(kind, choiceName);
        }

        private static bool IsRouteChoiceName(string choiceName)
        {
            return choiceName == "안정 루트"
                || choiceName == "변주 루트"
                || choiceName == "압박 루트";
        }

        private static string BuildRouteChoiceShortName(string choiceName)
        {
            switch (choiceName)
            {
                case "안정 루트":
                    return "안정";
                case "변주 루트":
                    return "변주";
                case "압박 루트":
                    return "압박";
                default:
                    return choiceName;
            }
        }

        private static string BuildChoiceHeaderDetail(GreedLastRunSnapshot snapshot)
        {
            string text = snapshot.ChoicePrompt;
            if (snapshot.ChoiceKind == GreedLastChoiceKind.Node)
            {
                string segmentReview = BuildCompletedSegmentReview(snapshot);
                if (!string.IsNullOrEmpty(segmentReview))
                {
                    text += "\n" + segmentReview;
                }

                text += "\n박자 지도 · 안정 정-압-정 / 변주 엇-정-엇 / 압박 압-엇-압";
                text += "\n동작 지도 · " + BuildAvoidanceRouteMapText();
            }

            string choicePreview = BuildChoiceHeaderPreview(snapshot);
            if (!string.IsNullOrEmpty(choicePreview))
            {
                text += "\n" + choicePreview;
            }

            string openingContext = BuildChoiceOpeningContextLine(snapshot.JudgementText);
            if (!string.IsNullOrEmpty(openingContext))
            {
                text += "\n" + openingContext;
            }

            string recommendationLine = BuildChoiceRecommendationLine(snapshot);
            if (!string.IsNullOrEmpty(recommendationLine))
            {
                text += "\n" + recommendationLine;
            }

            string feedback = BuildChoiceFeedbackLine(snapshot.JudgementText);
            if (!string.IsNullOrEmpty(feedback))
            {
                text += "\n" + feedback;
            }

            if (snapshot.ChoiceKind == GreedLastChoiceKind.Gift
                || snapshot.ChoiceKind == GreedLastChoiceKind.Relic)
            {
                text += "\n현재 " + BuildGiftStackSummary(snapshot);
            }

            return text;
        }

        private static string BuildChoiceOpeningContextLine(string judgementText)
        {
            if (string.IsNullOrWhiteSpace(judgementText))
            {
                return string.Empty;
            }

            string normalized = judgementText.Replace("\r", string.Empty);
            string[] lines = normalized.Split('\n');
            string reviewLine = string.Empty;
            string reviewTargetResultLine = string.Empty;
            string targetLine = string.Empty;
            string practiceHandoffLine = string.Empty;
            string normalStartLine = string.Empty;
            for (int i = 0; i < lines.Length; i += 1)
            {
                string line = lines[i].Trim();
                if (string.IsNullOrEmpty(line))
                {
                    continue;
                }

                if (string.IsNullOrEmpty(reviewLine)
                    && (line.Contains("복기 재도전", StringComparison.Ordinal)
                        || line.Contains("복기 연습", StringComparison.Ordinal)))
                {
                    reviewLine = line;
                    continue;
                }

                if (string.IsNullOrEmpty(reviewTargetResultLine)
                    && line.StartsWith("복기 목표:", StringComparison.Ordinal))
                {
                    reviewTargetResultLine = line;
                    continue;
                }

                if (string.IsNullOrEmpty(targetLine)
                    && (line.StartsWith("재도전 목표:", StringComparison.Ordinal)
                        || line.StartsWith("훈련 힌트:", StringComparison.Ordinal)))
                {
                    targetLine = line;
                    continue;
                }

                if (string.IsNullOrEmpty(practiceHandoffLine)
                    && line.StartsWith("기초연습 3축 확인 완료", StringComparison.Ordinal))
                {
                    practiceHandoffLine = line;
                    continue;
                }

                if (string.IsNullOrEmpty(normalStartLine)
                    && line.StartsWith("일반 런 시작:", StringComparison.Ordinal))
                {
                    normalStartLine = line;
                }
            }

            if (!string.IsNullOrEmpty(practiceHandoffLine)
                || !string.IsNullOrEmpty(normalStartLine))
            {
                return string.IsNullOrEmpty(practiceHandoffLine)
                    ? normalStartLine
                    : string.IsNullOrEmpty(normalStartLine)
                        ? practiceHandoffLine
                        : practiceHandoffLine + " · " + normalStartLine;
            }

            if (string.IsNullOrEmpty(reviewLine)
                && string.IsNullOrEmpty(reviewTargetResultLine)
                && string.IsNullOrEmpty(targetLine))
            {
                return string.Empty;
            }

            string text = string.IsNullOrEmpty(reviewLine) ? "복기" : reviewLine;
            if (!string.IsNullOrEmpty(reviewTargetResultLine))
            {
                text += " / " + reviewTargetResultLine;
            }

            if (!string.IsNullOrEmpty(targetLine))
            {
                text += " / " + targetLine;
            }

            return CompactUiText(text, 88);
        }

        private static string BuildCompletedSegmentReview(GreedLastRunSnapshot snapshot)
        {
            if (string.IsNullOrEmpty(snapshot.LastCompletedSegment))
            {
                return string.Empty;
            }

            string coaching = snapshot.LastCompletedSegmentMissCount > 0
                ? "안정화 필요"
                : snapshot.LastCompletedSegmentGoodCount > 0
                    ? "정확권 전환"
                    : snapshot.LastCompletedSegmentExactCount >= 3 ? "완전 정확" : "구간 통과";
            return "직전 " + snapshot.LastCompletedSegment
                + "  정확 " + snapshot.LastCompletedSegmentExactCount
                + " · 보정 " + snapshot.LastCompletedSegmentGoodCount
                + " · 실수 " + snapshot.LastCompletedSegmentMissCount
                + " / " + coaching;
        }

        private static string BuildChoiceInputHintLine(GreedLastRunSnapshot snapshot)
        {
            string recommendationLine = BuildChoiceRecommendationLine(snapshot);
            return string.IsNullOrEmpty(recommendationLine)
                ? "선택 입력: 좌 / 중 / 우"
                : "선택 입력: 좌 / 중 / 우  " + CompactUiText(recommendationLine, 42);
        }

        public static string BuildChoiceRecommendationLine(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ChoiceActive)
            {
                return string.Empty;
            }

            string recommendedChoice = BuildRecommendedChoiceName(snapshot);
            if (string.IsNullOrEmpty(recommendedChoice))
            {
                return "추천: 현재 균형 유지";
            }

            string reason = BuildChoiceRecommendationReasonText(snapshot, recommendedChoice);
            string effect = BuildCurrentChoiceEffectHint(snapshot, recommendedChoice);
            string text = "추천: " + recommendedChoice;
            if (!string.IsNullOrEmpty(reason))
            {
                text += " / " + reason;
            }

            return string.IsNullOrEmpty(effect)
                ? text
                : text + " / " + effect;
        }

        private static string BuildChoiceFeedbackLine(string judgementText)
        {
            if (string.IsNullOrEmpty(judgementText))
            {
                return string.Empty;
            }

            string normalized = judgementText.Replace("\r", string.Empty);
            string[] lines = normalized.Split('\n');
            if (lines.Length == 0 || !lines[0].Contains(" 선택"))
            {
                return string.Empty;
            }

            string selected = lines[0].Split(new[] { " 선택" }, StringSplitOptions.None)[0];
            string effect = string.Empty;
            string profile = string.Empty;
            for (int i = 1; i < lines.Length; i += 1)
            {
                if (lines[i].StartsWith("효과:", StringComparison.Ordinal))
                {
                    effect = lines[i].Substring(3).Trim();
                    continue;
                }

                if (lines[i].StartsWith("조합 성향:", StringComparison.Ordinal))
                {
                    profile = lines[i].Substring(6).Trim();
                }
            }

            string text = string.IsNullOrEmpty(effect)
                ? "직전 " + selected
                : "직전 " + selected + " / " + effect;
            string result = string.IsNullOrEmpty(profile)
                ? text
                : text + " / 조합 " + profile;
            return CompactUiText(result, 76);
        }

        private static string BuildFocusStateHudLine(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.FocusStateActive)
            {
                return string.Empty;
            }

            return "집중 상태  점수 x1.20  연쇄 완충  " + snapshot.FocusStateRemainingSeconds.ToString("0.0") + "s\n";
        }

        private static string BuildRunGuideLine(GreedLastRunSnapshot snapshot)
        {
            string line = $"가이드 {BuildTimingGuideLabel(snapshot)}  보정 {FormatTimingOffset(snapshot.InputTimingOffsetSeconds)}";
            if (snapshot.FocusStateActive)
            {
                line += "  집중 상태";
            }
            else if (!string.IsNullOrEmpty(snapshot.MissReason))
            {
                line += "  실수 " + FormatMissReason(snapshot.MissReason);
            }

            if (snapshot.DevInvincible)
            {
                line += "  테스트 무적 ON";
            }

            string infiniteThreatLine = BuildInfiniteThreatReadLine(snapshot);
            if (!string.IsNullOrEmpty(infiniteThreatLine))
            {
                line += "\n" + infiniteThreatLine;
            }

            string healthDangerLine = BuildHealthDangerSurvivalGuideLine(snapshot);
            if (!string.IsNullOrEmpty(healthDangerLine))
            {
                line += "\n" + healthDangerLine;
            }

            string status = BuildRunPressureStatus(snapshot);
            return string.IsNullOrEmpty(status)
                ? line
                : line + "\n상태 " + status;
        }

        private static string BuildHealthDangerSurvivalGuideLine(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Health > 1
                || snapshot.Stopped
                || snapshot.Paused
                || snapshot.ChoiceActive
                || snapshot.CountdownActive)
            {
                return string.Empty;
            }

            if (snapshot.SurvivalGiftStacks > 0 || snapshot.ActiveRouteProfile == "안정 루트")
            {
                return "체력 위험: Good 이상 생존 / 안정 보정 회복";
            }

            if (snapshot.ActivePattern && snapshot.Pattern.IsValid)
            {
                return "체력 위험: " + BuildTrapResponseCueLabel(snapshot.Pattern) + " Good 이상 생존";
            }

            return "체력 위험: 다음 함정 Good 이상 생존";
        }

        private static string BuildInfiniteThreatReadLine(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.InfiniteMode
                || snapshot.Stopped
                || snapshot.Paused
                || snapshot.ChoiceActive)
            {
                return string.Empty;
            }

            int threatLevel = Mathf.Clamp(snapshot.InfiniteThreatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel);
            string nextStep = WillInfiniteThreatRiseAfterSection(snapshot) ? "다음 구간 상승" : "현재 압박 유지";
            return "위협 " + threatLevel + "/5 " + BuildInfiniteThreatReadPressureLabel(threatLevel)
                + "  위험폭 " + BuildInfiniteThreatDangerWidthLabel(threatLevel)
                + "  보상 " + BuildInfiniteThreatRewardPreview(threatLevel)
                + "  " + nextStep;
        }

        private static string BuildInfiniteThreatReadPressureLabel(int threatLevel)
        {
            switch (Mathf.Clamp(threatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel))
            {
                case 1:
                    return "안정";
                case 2:
                    return "상승";
                case 3:
                    return "압박";
                case 4:
                    return "고압";
                default:
                    return "최고";
            }
        }

        private static string BuildInfiniteThreatDangerWidthLabel(int threatLevel)
        {
            switch (Mathf.Clamp(threatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel))
            {
                case 1:
                    return "좁음";
                case 2:
                    return "보통";
                case 3:
                    return "확대";
                case 4:
                    return "넓음";
                default:
                    return "최대";
            }
        }

        private static string BuildInfiniteThreatRewardPreview(int threatLevel)
        {
            int perfectBonus = BuildInfiniteThreatPrecisionBonusPreview(threatLevel, GreedLastTimingType.Perfect);
            int clutchBonus = BuildInfiniteThreatPrecisionBonusPreview(threatLevel, GreedLastTimingType.Clutch);
            int offbeatBonus = BuildInfiniteThreatPrecisionBonusPreview(threatLevel, GreedLastTimingType.Offbeat);
            int minBonus = Mathf.Min(perfectBonus, Mathf.Min(clutchBonus, offbeatBonus));
            int maxBonus = Mathf.Max(perfectBonus, Mathf.Max(clutchBonus, offbeatBonus));
            return minBonus == maxBonus ? "정확+" + minBonus : "정확+" + minBonus + "~" + maxBonus;
        }

        private static int BuildInfiniteThreatPrecisionBonusPreview(int threatLevel, GreedLastTimingType timingType)
        {
            int safeThreatLevel = Mathf.Clamp(threatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel);
            int bonus = Mathf.Max(0, safeThreatLevel - 1) * 12;
            if (timingType == GreedLastTimingType.Clutch)
            {
                bonus += safeThreatLevel >= 3 ? 10 : 0;
            }
            else if (timingType == GreedLastTimingType.Offbeat)
            {
                bonus += safeThreatLevel >= 3 ? 8 : 0;
            }

            return bonus;
        }

        private static string BuildRunPressureStatus(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped || snapshot.Paused || snapshot.CountdownActive)
            {
                return string.Empty;
            }

            string status = string.Empty;
            if (snapshot.Staggered || snapshot.StaggerRemainingSeconds > 0.01f)
            {
                AppendCompactStatus(ref status, "복구 " + snapshot.StaggerRemainingSeconds.ToString("0.0") + "s");
            }

            if (!snapshot.InfiniteMode && snapshot.ChapterProgress > 0)
            {
                AppendCompactStatus(
                    ref status,
                    snapshot.PerfectBundleIntact
                        ? BuildRouteBundleProgressLabel(snapshot)
                        : BuildRouteBundleBrokenLabel(snapshot));
            }

            AppendCompactStatus(ref status, BuildThreeActionBundleStatus(snapshot));

            if (snapshot.InfiniteMode
                && snapshot.ChapterProgress == 0
                && snapshot.LastCompletedSegment.StartsWith("무한 ", StringComparison.Ordinal))
            {
                AppendCompactStatus(
                    ref status,
                    "직전 정" + snapshot.LastCompletedSegmentExactCount
                        + " 보" + snapshot.LastCompletedSegmentGoodCount
                        + " 실" + snapshot.LastCompletedSegmentMissCount);
            }

            AppendCompactStatus(ref status, BuildActiveChoiceProfileStatus(snapshot));
            AppendCompactStatus(ref status, BuildActiveRouteStatus(snapshot));
            if (!snapshot.InfiniteMode
                && snapshot.FocusGiftStacks + snapshot.SurvivalGiftStacks + snapshot.ChainGiftStacks > 0)
            {
                AppendCompactStatus(ref status, BuildGiftStackSummary(snapshot));
            }

            AppendCompactStatus(ref status, BuildActiveScoringPreviewStatus(snapshot));
            AppendCompactStatus(ref status, BuildPrototypeFeelStatus(snapshot));

            if (snapshot.Combo >= 3)
            {
                AppendCompactStatus(ref status, "연쇄 " + BuildRhythmChainLabel(snapshot));
            }

            if (snapshot.PrecisionStreak >= 2)
            {
                AppendCompactStatus(ref status, "정박 " + snapshot.PrecisionStreak);
            }

            AppendCompactStatus(ref status, BuildPrecisionRewardStatus(snapshot));
            AppendCompactStatus(ref status, BuildNextChainStatus(snapshot));
            AppendCompactStatus(ref status, BuildPatternVariationStatus(snapshot.Pattern));

            if (snapshot.FocusStateActive)
            {
                AppendCompactStatus(ref status, "집중 상태 " + snapshot.FocusStateRemainingSeconds.ToString("0.0") + "s");
            }
            else if (snapshot.Focus == snapshot.MaxFocus - 1 && snapshot.MaxFocus > 1)
            {
                AppendCompactStatus(ref status, "집중 1칸 남음");
            }

            if (snapshot.Health <= 1)
            {
                AppendCompactStatus(ref status, BuildHealthDangerCompactStatus(snapshot));
            }

            if (snapshot.InfiniteMode)
            {
                if (!string.IsNullOrEmpty(snapshot.ActiveRelic))
                {
                    AppendCompactStatus(ref status, "유물 " + snapshot.ActiveRelic);
                }

                AppendCompactStatus(ref status, BuildInfiniteThreatPreviewStatus(snapshot));
            }

            AppendCompactStatus(ref status, BuildTimingRecommendationStatus(snapshot));
            return CompactUiText(status, 64);
        }

        private static string BuildHealthDangerCompactStatus(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.SurvivalGiftStacks > 0 || snapshot.ActiveRouteProfile == "안정 루트")
            {
                return "체력 위험 Good 회복";
            }

            return snapshot.ActivePattern && snapshot.Pattern.IsValid
                ? "체력 위험 " + BuildTrapResponseCueLabel(snapshot.Pattern)
                : "체력 위험";
        }

        private static string BuildPrototypeFeelStatus(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped
                || snapshot.Paused
                || snapshot.CountdownActive
                || snapshot.ChoiceActive
                || !snapshot.ActivePattern
                || !snapshot.Pattern.IsValid)
            {
                return string.Empty;
            }

            string mode = snapshot.InfiniteMode
                ? "무한"
                : snapshot.PracticeMode
                    ? "연습"
                    : snapshot.RefillRun
                        ? "보충"
                        : snapshot.Phase == GreedLastRunPhase.EscapeRunning
                            ? "탈출"
                            : "일반";

            string payoffGoal = BuildPrototypeFeelPayoffGoal(snapshot);
            return "체감 " + mode + " " + BuildTrapResponseCueLabel(snapshot.Pattern)
                + "→정확"
                + (string.IsNullOrEmpty(payoffGoal) ? string.Empty : "→" + payoffGoal);
        }

        private static string BuildPrototypeFeelPayoffGoal(GreedLastRunSnapshot snapshot)
        {
            return BuildPrototypeFeelPayoffGoal(snapshot, snapshot.Pattern);
        }

        private static string BuildPrototypeFeelPayoffGoal(GreedLastRunSnapshot snapshot, GreedLastPatternModel pattern)
        {
            if (!pattern.IsValid)
            {
                return string.Empty;
            }

            if (snapshot.Health <= 1)
            {
                return "생존";
            }

            if (snapshot.FocusStateActive)
            {
                return "고점";
            }

            if (IsRecoveryPattern(pattern))
            {
                return "회복";
            }

            return BuildPrototypePatternPayoffGoal(pattern);
        }

        private static string BuildPrototypePatternPayoffGoal(GreedLastPatternModel pattern)
        {
            switch (pattern.TimingType)
            {
                case GreedLastTimingType.Perfect:
                    return "집중";
                case GreedLastTimingType.Clutch:
                    return "반격";
                case GreedLastTimingType.Offbeat:
                    return "연쇄";
                default:
                    return string.Empty;
            }
        }

        private static string BuildPrototypePayoffGoalFromTransitionText(string text)
        {
            if (string.IsNullOrEmpty(text))
            {
                return string.Empty;
            }

            if (text.StartsWith("복구", StringComparison.Ordinal))
            {
                return "회복";
            }

            if (text.StartsWith("정박", StringComparison.Ordinal))
            {
                return "집중";
            }

            if (text.StartsWith("압박", StringComparison.Ordinal))
            {
                return "반격";
            }

            if (text.StartsWith("엇박", StringComparison.Ordinal))
            {
                return "연쇄";
            }

            return string.Empty;
        }

        private static string BuildRouteBundleProgressLabel(GreedLastRunSnapshot snapshot)
        {
            string routeLabel;
            switch (snapshot.ActiveRouteProfile)
            {
                case "안정 루트":
                    routeLabel = "안정 완주";
                    break;
                case "변주 루트":
                    routeLabel = "변주 완주";
                    break;
                case "압박 루트":
                    routeLabel = "압박 완주";
                    break;
                default:
                    routeLabel = "묶음 정확";
                    break;
            }

            return routeLabel + " " + snapshot.ChapterProgress + "/" + snapshot.ChapterTarget;
        }

        private static string BuildThreeActionBundleStatus(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped
                || snapshot.Paused
                || snapshot.CountdownActive
                || snapshot.ChoiceActive
                || snapshot.ChapterProgress <= 0)
            {
                return string.Empty;
            }

            if (!snapshot.PerfectBundleIntact)
            {
                return "동작 완주 중단";
            }

            string symbols = BuildThreeActionBundleSymbols(snapshot.CurrentBundleAvoidanceMask);
            int count = CountThreeActionBundleActions(snapshot.CurrentBundleAvoidanceMask);
            if (count <= 0)
            {
                return string.Empty;
            }

            string nextSymbol = BuildThreeActionBundleNextSymbol(snapshot.CurrentBundleAvoidanceMask);
            string nextText = string.IsNullOrEmpty(nextSymbol) ? string.Empty : "→" + nextSymbol;
            return "동작 " + symbols + " " + count + "/3" + nextText;
        }

        private static string BuildThreeActionBundleSymbols(int avoidanceMask)
        {
            string text = string.Empty;
            if (HasAvoidanceMask(avoidanceMask, GreedLastAvoidanceType.Jump))
            {
                text += "↑";
            }

            if (HasAvoidanceMask(avoidanceMask, GreedLastAvoidanceType.Slide))
            {
                text += "↓";
            }

            if (HasAvoidanceMask(avoidanceMask, GreedLastAvoidanceType.Twist))
            {
                text += "↔";
            }

            return text;
        }

        private static string BuildChoiceScreenTitle(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.RefillRun)
            {
                return "보충 방향 선택";
            }

            switch (snapshot.ChoiceKind)
            {
                case GreedLastChoiceKind.StartGift:
                    return "시작 기프트 선택";
                case GreedLastChoiceKind.Node:
                    return "경로 선택";
                case GreedLastChoiceKind.Gift:
                    return "기프트 선택";
                case GreedLastChoiceKind.Relic:
                    return "유물 선택";
                default:
                    return "방향 선택";
            }
        }

        private static string BuildThreeActionBundleNextSymbol(int avoidanceMask)
        {
            if (!HasAvoidanceMask(avoidanceMask, GreedLastAvoidanceType.Jump))
            {
                return FormatRunnerResponseSymbol(RunnerResponseType.Jump);
            }

            if (!HasAvoidanceMask(avoidanceMask, GreedLastAvoidanceType.Slide))
            {
                return FormatRunnerResponseSymbol(RunnerResponseType.Slide);
            }

            return !HasAvoidanceMask(avoidanceMask, GreedLastAvoidanceType.Twist)
                ? FormatRunnerResponseSymbol(RunnerResponseType.Twist)
                : string.Empty;
        }

        private static int CountThreeActionBundleActions(int avoidanceMask)
        {
            int count = 0;
            count += HasAvoidanceMask(avoidanceMask, GreedLastAvoidanceType.Jump) ? 1 : 0;
            count += HasAvoidanceMask(avoidanceMask, GreedLastAvoidanceType.Slide) ? 1 : 0;
            count += HasAvoidanceMask(avoidanceMask, GreedLastAvoidanceType.Twist) ? 1 : 0;
            return count;
        }

        private static bool HasAvoidanceMask(int avoidanceMask, GreedLastAvoidanceType avoidanceType)
        {
            return (avoidanceMask & (1 << (int)avoidanceType)) != 0;
        }

        private static string BuildRouteBundleBrokenLabel(GreedLastRunSnapshot snapshot)
        {
            string routeLabel;
            switch (snapshot.ActiveRouteProfile)
            {
                case "안정 루트":
                    routeLabel = "안정 완주 중단";
                    break;
                case "변주 루트":
                    routeLabel = "변주 완주 중단";
                    break;
                case "압박 루트":
                    routeLabel = "압박 완주 중단";
                    break;
                default:
                    routeLabel = "묶음 보정";
                    break;
            }

            return routeLabel + " " + snapshot.ChapterProgress + "/" + snapshot.ChapterTarget;
        }

        private static string BuildActiveChoiceProfileStatus(GreedLastRunSnapshot snapshot)
        {
            string profile = snapshot.InfiniteMode && IsVisibleChoiceProfile(snapshot.ActiveInfiniteLoadoutProfile)
                ? snapshot.ActiveInfiniteLoadoutProfile
                : snapshot.ActiveChoiceProfile;
            if (snapshot.Stopped
                || snapshot.ChoiceActive
                || !IsVisibleChoiceProfile(profile))
            {
                return string.Empty;
            }

            return "조합 " + CompactActiveInfiniteLoadoutProfileText(profile);
        }

        private static string BuildActiveRouteStatus(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped || snapshot.ChoiceActive || snapshot.InfiniteMode)
            {
                return string.Empty;
            }

            switch (snapshot.ActiveRouteProfile)
            {
                case "안정 루트":
                    return "경로 안정 보험" + BuildRouteCadenceCompact(snapshot);
                case "변주 루트":
                    return "경로 변주 공명" + BuildRouteCadenceCompact(snapshot);
                case "압박 루트":
                    return "경로 압박 고점" + BuildRouteCadenceCompact(snapshot);
                default:
                    return string.Empty;
            }
        }

        private static string BuildRouteCadenceCompact(GreedLastRunSnapshot snapshot)
        {
            if (!TryBuildRouteCadence(snapshot, out _, out GreedLastTimingType[] timings))
            {
                return string.Empty;
            }

            return " " + BuildCadenceToken(timings[0])
                + ">" + BuildCadenceToken(timings[1])
                + ">" + BuildCadenceToken(timings[2]);
        }

        private static string BuildGiftStackSummary(GreedLastRunSnapshot snapshot)
        {
            string summary = string.Empty;
            if (snapshot.FocusGiftStacks > 0)
            {
                AppendCompactStatus(ref summary, "집중 x" + snapshot.FocusGiftStacks);
            }

            if (snapshot.SurvivalGiftStacks > 0)
            {
                AppendCompactStatus(ref summary, "생존 x" + snapshot.SurvivalGiftStacks);
            }

            if (snapshot.ChainGiftStacks > 0)
            {
                AppendCompactStatus(ref summary, "연쇄 x" + snapshot.ChainGiftStacks);
            }

            return string.IsNullOrEmpty(summary) ? "기프트 미선택" : "기프트 " + summary;
        }

        private static string BuildActiveScoringPreviewStatus(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ActivePattern || !snapshot.Pattern.IsValid)
            {
                return string.Empty;
            }

            int exactScore = BuildActiveExactScorePreview(snapshot);
            int goodScore = BuildActiveGoodScorePreview(snapshot);
            if (exactScore <= 0 || goodScore <= 0)
            {
                return string.Empty;
            }

            string exactPreview = BuildTrapResponseCueLabel(snapshot.Pattern) + " 정박 +" + exactScore;
            string payoffGoal = BuildPrototypeFeelPayoffGoal(snapshot);
            if (!string.IsNullOrEmpty(payoffGoal))
            {
                exactPreview += "→" + payoffGoal;
            }

            return exactPreview + " / 보정 +" + goodScore;
        }

        private static int BuildActiveExactScorePreview(GreedLastRunSnapshot snapshot)
        {
            return snapshot.CenterHitScoreGainPreview;
        }

        private static int BuildActiveGoodScorePreview(GreedLastRunSnapshot snapshot)
        {
            return snapshot.GoodScoreGainPreview;
        }

        private static bool IsVisibleChoiceProfile(string profile)
        {
            return !string.IsNullOrEmpty(profile)
                && profile != "루트 미정"
                && profile != "저장 조합";
        }

        private static string BuildPrecisionRewardStatus(GreedLastRunSnapshot snapshot)
        {
            int remaining = BuildPrecisionRewardRemaining(snapshot);
            if (remaining < 0)
            {
                return string.Empty;
            }

            if (remaining == 0)
            {
                return snapshot.FocusStateActive ? "정박 보상 · 집중 유지" : "정박 보상 +집중";
            }

            return remaining <= 2 ? "정박 보상까지 " + remaining : string.Empty;
        }

        private static int BuildPrecisionRewardRemaining(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.PrecisionStreak <= 0)
            {
                return -1;
            }

            int remainder = snapshot.PrecisionStreak % PrecisionFocusStepUi;
            return remainder == 0 ? 0 : PrecisionFocusStepUi - remainder;
        }

        private static string BuildInfiniteThreatProgressPreview(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.InfiniteMode || snapshot.Stopped)
            {
                return string.Empty;
            }

            return WillInfiniteThreatRiseAfterSection(snapshot)
                ? "  다음 위협↑"
                : string.Empty;
        }

        private static string BuildCurrentInfiniteSegmentPerformance(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.InfiniteMode || snapshot.Stopped)
            {
                return string.Empty;
            }

            return "  정" + snapshot.CurrentSegmentExactCount
                + " 보" + snapshot.CurrentSegmentGoodCount
                + " 실" + snapshot.CurrentSegmentMissCount;
        }

        private static string BuildStoppedInfiniteSegmentPerformance(GreedLastRunSnapshot snapshot)
        {
            int resolved = snapshot.CurrentSegmentExactCount
                + snapshot.CurrentSegmentGoodCount
                + snapshot.CurrentSegmentMissCount;
            if (!snapshot.InfiniteMode || !snapshot.Stopped || resolved <= 0 || snapshot.MissReason == "test_stop")
            {
                return string.Empty;
            }

            return "  종료 정" + snapshot.CurrentSegmentExactCount
                + " 보" + snapshot.CurrentSegmentGoodCount
                + " 실" + snapshot.CurrentSegmentMissCount;
        }

        private static string BuildInfiniteThreatPreviewStatus(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.InfiniteMode || snapshot.Stopped)
            {
                return string.Empty;
            }

            int remaining = Mathf.Max(0, snapshot.ChapterTarget - snapshot.ChapterProgress);
            if (remaining > 1)
            {
                return string.Empty;
            }

            return WillInfiniteThreatRiseAfterSection(snapshot)
                ? "위협 상승 예고"
                : "구간 보너스 임박";
        }

        private static bool WillInfiniteThreatRiseAfterSection(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.InfiniteMode)
            {
                return false;
            }

            int currentThreat = Mathf.Clamp(snapshot.InfiniteThreatLevel, 1, 5);
            return snapshot.NextInfiniteThreatLevel > currentThreat;
        }

        private static string BuildNextChainStatus(GreedLastRunSnapshot snapshot)
        {
            int remaining = BuildNextChainRemaining(snapshot);
            if (remaining < 0)
            {
                return string.Empty;
            }

            int currentTier = Mathf.Clamp(snapshot.Combo / 3, 0, 5);
            return remaining <= 2
                ? "연쇄 보너스 x" + (currentTier + 1) + "까지 " + remaining
                : string.Empty;
        }

        private static int BuildNextChainRemaining(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Combo <= 0)
            {
                return -1;
            }

            int currentTier = Mathf.Clamp(snapshot.Combo / 3, 0, 5);
            if (currentTier >= 5)
            {
                return -1;
            }

            int nextTierCombo = (currentTier + 1) * 3;
            return nextTierCombo - snapshot.Combo;
        }

        private static string BuildTimingRecommendationStatus(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.HasTimingRecommendation)
            {
                return snapshot.TimingRecommendationSampleCount > 0
                    ? "보정 샘플 " + snapshot.TimingRecommendationSampleCount + "/" + snapshot.TimingRecommendationSampleTarget
                    : string.Empty;
            }

            int currentMilliseconds = Mathf.RoundToInt(snapshot.InputTimingOffsetSeconds * 1000f);
            int recommendationDelta = snapshot.TimingRecommendationMilliseconds - currentMilliseconds;
            if (Mathf.Abs(recommendationDelta) < 25f)
            {
                return "보정 안정";
            }

            string trend = recommendationDelta < 0 ? "입력 늦음" : "입력 빠름";
            return trend + " / 추천 " + FormatTimingOffset(snapshot.TimingRecommendationMilliseconds / 1000f);
        }

