        private static string BuildDetail(GreedLastStateSnapshot snapshot)
        {
            if (snapshot.State == GreedLastScreenState.LobbyReady)
            {
                return ShouldHideLobbyDetail(snapshot.Detail)
                    ? string.Empty
                    : snapshot.Detail;
            }

            if (snapshot.State == GreedLastScreenState.ReSyncPending)
            {
                if (snapshot.CoreActionsEnabled)
                {
                    return ShouldHideLobbyDetail(snapshot.Detail) ? "일부 정보 갱신 대기" : snapshot.Detail;
                }
                return snapshot.Detail
                    + "\n\n핵심 버튼은 최신 상태 확인 뒤 다시 열립니다.";
            }

            if (snapshot.State == GreedLastScreenState.SaveLoadoutDraft)
            {
                return snapshot.Detail;
            }

            if (snapshot.State == GreedLastScreenState.InfiniteStartReady)
            {
                return BuildPreparedInfiniteDisplayDetail(snapshot.Detail);
            }

            return snapshot.Detail;
        }

        private static string BuildPreparedInfiniteDisplayDetail(string detail)
        {
            if (string.IsNullOrEmpty(detail) || !detail.Contains("시작 정비 완료", StringComparison.Ordinal))
                return detail;

            string[] lines = detail.Replace("\r", string.Empty).Split('\n');
            string[] prefixes = { "시작 정비 완료", "기프트: ", "성향: ", "시작 상태: ", "목표: " };
            var priority = new List<string>();
            var moved = new bool[lines.Length];
            for (int prefix = 0; prefix < prefixes.Length; prefix++)
            {
                bool found = false;
                for (int line = 0; line < lines.Length; line++)
                {
                    bool match = prefix == 0 ? lines[line] == prefixes[prefix]
                        : lines[line].StartsWith(prefixes[prefix], StringComparison.Ordinal);
                    if (!match) continue;
                    priority.Add(lines[line]);
                    moved[line] = true;
                    found = true;
                    break;
                }
                if (!found && prefix < 4) return detail;
            }

            // Keep the complete detail below the ready summary; only presentation order changes.
            var remainder = new List<string>();
            for (int line = 0; line < lines.Length; line++)
                if (!moved[line]) remainder.Add(lines[line]);
            string tail = string.Join("\n", remainder).Trim();
            return string.Join("\n", priority) + (tail.Length == 0 ? string.Empty : "\n\n" + tail);
        }

        private void UpdateDebugText(GreedLastStateSnapshot snapshot)
        {
            bool showDebugText = DevToolsEnabled
                && (snapshot.State == GreedLastScreenState.ConnectBlocked
                    || snapshot.State == GreedLastScreenState.ReSyncPending);
            if (debugText != null)
            {
                debugText.gameObject.SetActive(showDebugText);
                debugText.text = showDebugText
                    ? $"상태: {FormatDebugState(snapshot.State)}\n요청: {snapshot.RequestId}\n차단: {FormatDebugBlock(snapshot.BlockReason)}"
                    : string.Empty;
            }
        }

        private void HideDebugText()
        {
            if (debugText == null)
            {
                return;
            }

            debugText.text = string.Empty;
            debugText.gameObject.SetActive(false);
        }

        private static bool ShouldHideLobbyDetail(string detail)
        {
            if (string.IsNullOrWhiteSpace(detail))
            {
                return true;
            }

            string normalized = detail.Replace("\r\n", "\n").Replace('\r', '\n').Trim();
            if (normalized == "피라미드 입구 동기화 완료")
            {
                return true;
            }

            string[] lines = SplitLobbyDefaultDetailParts(normalized);
            bool hasDefaultLobbyLine = false;
            for (int i = 0; i < lines.Length; i += 1)
            {
                string line = StripLobbyDefaultDetailPrefix(lines[i]);
                if (line.Length == 0)
                {
                    continue;
                }

                if (IsDefaultLobbyOnboardingLine(line))
                {
                    hasDefaultLobbyLine = true;
                    continue;
                }

                return false;
            }

            return hasDefaultLobbyLine;
        }

        private static bool IsDefaultLobbyOnboardingLine(string line)
        {
            if (string.IsNullOrWhiteSpace(line))
            {
                return false;
            }

            string trimmed = line.Trim();
            if (trimmed == "피라미드 입구 동기화 완료"
                || trimmed.StartsWith("일반 런은 ", StringComparison.Ordinal)
                || trimmed.StartsWith("일반런은 ", StringComparison.Ordinal)
                || trimmed.StartsWith("첫 저장 전 ", StringComparison.Ordinal))
            {
                return true;
            }

            string compact = RemoveLobbyDefaultDetailWhitespace(trimmed);
            return compact.StartsWith("첫저장전", StringComparison.Ordinal)
                || ((compact.StartsWith("일반런은6-2", StringComparison.Ordinal)
                        || compact.StartsWith("일반런6-2", StringComparison.Ordinal))
                    && (compact.Contains("열립니다", StringComparison.Ordinal)
                        || compact.Contains("열림", StringComparison.Ordinal)
                        || compact.Contains("보입니다", StringComparison.Ordinal)
                        || compact.Contains("보임", StringComparison.Ordinal)
                        || compact.Contains("해금", StringComparison.Ordinal)));
        }

        private static string RemoveLobbyDefaultDetailWhitespace(string text)
        {
            if (string.IsNullOrEmpty(text))
            {
                return string.Empty;
            }

            string compact = string.Empty;
            for (int i = 0; i < text.Length; i += 1)
            {
                if (!char.IsWhiteSpace(text[i]))
                {
                    compact += text[i];
                }
            }

            return compact;
        }

        private static string[] SplitLobbyDefaultDetailParts(string detail)
        {
            if (string.IsNullOrEmpty(detail))
            {
                return Array.Empty<string>();
            }

            var parts = new List<string>();
            int startIndex = 0;
            for (int i = 0; i < detail.Length; i += 1)
            {
                char ch = detail[i];
                bool split = ch == '\n'
                    || ch == '\r'
                    || ch == '/'
                    || ch == '／'
                    || ch == '|'
                    || ch == '｜'
                    || ch == ';'
                    || ch == '；'
                    || ch == ','
                    || ch == '，'
                    || ch == '·'
                    || ch == 'ㆍ'
                    || ch == '。'
                    || (ch == '.' && (i == 0 || !char.IsDigit(detail[i - 1])));
                if (!split)
                {
                    continue;
                }

                parts.Add(detail.Substring(startIndex, i - startIndex));
                startIndex = i + 1;
            }

            parts.Add(detail.Substring(startIndex));
            return parts.ToArray();
        }

        private static string StripLobbyDefaultDetailPrefix(string line)
        {
            if (string.IsNullOrWhiteSpace(line))
            {
                return string.Empty;
            }

            string trimmed = line.Trim();
            bool changed = true;
            while (changed && trimmed.Length >= 2)
            {
                changed = false;
                if ((trimmed[0] == '-'
                        || trimmed[0] == '*'
                        || trimmed[0] == '•'
                        || trimmed[0] == '·'
                        || trimmed[0] == 'ㆍ'
                        || trimmed[0] == '>'
                        || trimmed[0] == '▸'
                        || trimmed[0] == '▹')
                    && char.IsWhiteSpace(trimmed[1]))
                {
                    trimmed = trimmed.Substring(2).TrimStart();
                    changed = true;
                    continue;
                }

                int index = 0;
                while (index < trimmed.Length && char.IsDigit(trimmed[index]))
                {
                    index += 1;
                }

                if (index > 0
                    && index + 1 < trimmed.Length
                    && (trimmed[index] == '.' || trimmed[index] == ')')
                    && char.IsWhiteSpace(trimmed[index + 1]))
                {
                    trimmed = trimmed.Substring(index + 2).TrimStart();
                    changed = true;
                }
            }

            return trimmed.Trim().TrimEnd(':', '-', '.', '。').Trim();
        }

        private static int BuildRecordBoardFontSize(string detail)
        {
            int lineCount = CountTextLines(detail);
            int longLinePenalty = HasLongTextLine(detail, 92) ? 4 : HasLongTextLine(detail, 64) ? 2 : 0;

            if (lineCount <= 4)
            {
                return 34 - longLinePenalty;
            }

            if (lineCount <= 7)
            {
                return 31 - longLinePenalty;
            }

            if (lineCount <= 10)
            {
                return 25 - longLinePenalty;
            }

            return 22;
        }

        private static int BuildPauseMenuBodyFontSize(string detail)
        {
            int lineCount = CountTextLines(detail);
            int longLinePenalty = HasLongTextLine(detail, 58) ? 2 : 0;
            if (lineCount <= 4)
            {
                return 29 - longLinePenalty;
            }

            if (lineCount <= 6)
            {
                return 26 - longLinePenalty;
            }

            if (lineCount <= 8)
            {
                return 24 - longLinePenalty;
            }

            return Mathf.Max(21, 22 - longLinePenalty);
        }

