        private static string BuildLobbyRecordButtonLabel(string detail)
        {
            if (string.IsNullOrEmpty(detail))
            {
                return "기록 보기";
            }

            if (GreedLastApp.IsRefillRecordResultDetail(detail))
            {
                return "보충 기록";
            }

            if (GreedLastApp.HasLineStartingWith(detail, "탈출 성공 / 기록 저장")
                || GreedLastApp.IsEntranceExitRecordResultDetail(detail)
                || GreedLastApp.IsClearSummaryRecordResultDetail(detail))
            {
                return "클리어 복기";
            }

            if (detail.Contains("저장 조합 슬롯에는 저장하지 않았습니다.", StringComparison.Ordinal))
            {
                return "클리어 복기";
            }

            if (GreedLastApp.HasLineStartingWith(detail, "탈출 실패 기록 저장")
                || GreedLastApp.HasLineStartingWith(detail, "탈출 중단 기록 저장"))
            {
                return "복기 기록";
            }

            if (IsInfiniteRecordResultDetail(detail))
            {
                return "무한 복기";
            }

            if (GreedLastApp.IsPrototypeCompletionRecordRequestDetail(detail))
            {
                return "완성 기록";
            }

            return "기록 보기";
        }

        private static bool IsNormalRecordResultDetail(string detail)
        {
            if (string.IsNullOrEmpty(detail))
            {
                return false;
            }

            return GreedLastApp.IsRefillRecordResultDetail(detail)
                || GreedLastApp.IsClearSummaryRecordResultDetail(detail)
                || GreedLastApp.HasLineStartingWith(detail, "탈출 성공 / 기록 저장")
                || detail.Contains("저장 조합 슬롯에는 저장하지 않았습니다.", StringComparison.Ordinal)
                || GreedLastApp.HasLineStartingWith(detail, "탈출 실패 기록 저장")
                || GreedLastApp.HasLineStartingWith(detail, "탈출 중단 기록 저장");
        }

        private static bool IsInfiniteRecordResultDetail(string detail)
        {
            if (string.IsNullOrEmpty(detail))
            {
                return false;
            }

            return detail.StartsWith("무한모드 종료 / 기록 저장", StringComparison.Ordinal)
                || detail.StartsWith("무한 기록 저장", StringComparison.Ordinal)
                || detail.StartsWith("무한 기록 저장 완료", StringComparison.Ordinal);
        }

