        private static string BuildLobbyNormalRunButtonLabel(GreedLastStateSnapshot snapshot)
        {
            if (snapshot.SaveLoadoutCandidateAvailable)
            {
                return "후보 먼저 저장";
            }

            string detail = snapshot.Detail ?? string.Empty;
