                && !canSaveCandidate
                && (snapshot.FirstSaveCompleted || snapshot.SaveLoadoutUnlocked)
                && !HasAnyUsableSaveSlot(snapshot);
        }

        private static string BuildSaveDraftPrimaryActionLabel(
            GreedLastStateSnapshot snapshot,
            bool infiniteLoadoutSelectLike,
            bool selectedSaveSlotUsable,
            bool canSaveCandidate,
            bool saveDraftRefillAvailable)
        {
            if (infiniteLoadoutSelectLike)
            {
                if (snapshot.SaveSlotDeleteConfirmationPending)
                {
                    return "삭제 확인 중";
                }

                if (snapshot.SaveSlotRenameConfirmationPending)
                {
                    return "이름 확인 중";
                }

                return BuildInfiniteLoadoutSelectActionLabel(snapshot, selectedSaveSlotUsable);
            }

            if (snapshot.SaveSlotChoiceRequired)
            {
                return "좌·중·우 선택";
            }

            if (snapshot.SaveSlotDeleteConfirmationPending)
            {
                return "삭제 확인 중";
            }

            if (snapshot.SaveSlotRenameConfirmationPending)
            {
                return "이름 확인 중";
            }

            if (!canSaveCandidate)
            {
                return saveDraftRefillAvailable ? "보충 런" : "저장 후보 없음";
            }

            if (snapshot.SaveLoadoutSkipConfirmationPending)
            {
                return "포기 취소 저장";
            }

            return snapshot.SaveSlotOverwriteConfirmationPending
                ? "덮어쓰기 확정"
                : "슬롯 " + (snapshot.SelectedSaveSlotIndex + 1) + "에 저장";
        }

        private static bool BuildSaveDraftPrimaryActionEnabled(
            GreedLastStateSnapshot snapshot,
            bool infiniteLoadoutSelectLike,
            bool canSaveCandidate,
            bool saveDraftRefillAvailable)
        {
            if (snapshot.SaveSlotDeleteConfirmationPending || snapshot.SaveSlotRenameConfirmationPending)
            {
                return false;
            }

            return infiniteLoadoutSelectLike
                || (!snapshot.SaveSlotChoiceRequired && (canSaveCandidate || saveDraftRefillAvailable));
        }

