            {
                return "포기 확정";
            }

            return snapshot.SaveSlotChoiceRequired || canSaveCandidate ? "저장 포기" : "로비로";
        }

        private static bool BuildSaveSlotDetailActionEnabled(
            GreedLastStateSnapshot snapshot,
            bool recordBoardLike,
