        private static bool ShouldShowLanePreviewForScreen(GreedLastScreenState state)
        {
            return state != GreedLastScreenState.InfiniteRecordBoard
                && state != GreedLastScreenState.ProfileBoard;
        }

        internal static bool ShouldShowLobbyRunPortal(GreedLastScreenState state)
        {
            return state == GreedLastScreenState.LobbyReady;
        }

        internal static bool BuildLobbyRunPortalReady(
            bool visible,
            bool onboardingComplete,
            bool coreActionsEnabled,
            bool saveCandidateAvailable,
            string nextActionTarget)
        {
            if (!visible || !onboardingComplete || !coreActionsEnabled || saveCandidateAvailable)
            {
                return false;
            }

            return string.IsNullOrEmpty(nextActionTarget)
                || nextActionTarget.Equals("일반", StringComparison.Ordinal);
        }

        internal static float BuildLobbyRunPortalPulse(bool visible, bool ready, float pulse)
        {
            if (!visible)
            {
                return 0f;
            }

            float safePulse = Mathf.Clamp01(pulse);
            return ready
                ? Mathf.Lerp(0.42f, 1f, safePulse)
                : Mathf.Lerp(0.18f, 0.30f, safePulse);
        }

        private void TrackScreenEntranceTransitions(GreedLastScreenState state)
        {
            if (ShouldStartLobbyEntranceReveal(hasRenderedScreenState, lastRenderedScreenState, state))
            {
                lobbyEntranceRevealStartedAt = Time.unscaledTime;
                lobbyEntranceRevealUntil = lobbyEntranceRevealStartedAt + LobbyEntranceRevealDuration;
                PlayClip(lobbyEntranceClip, BuildLobbyEntranceCueVolume());
            }

            if (ShouldStartRunEntranceHandoff(hasRenderedScreenState, lastRenderedScreenState, state))
            {
                runEntranceHandoffStartedAt = Time.unscaledTime;
                runEntranceHandoffUntil = runEntranceHandoffStartedAt + RunEntranceHandoffDuration;
                runEntranceHandoffPortalReady = lobbyRunPortalReady;
                runEntranceHandoffPracticeFirst = lobbyRunPortalPracticeFirst;
                PlayClip(
                    runEntranceClip,
                    BuildRunEntranceCueVolume(runEntranceHandoffPortalReady, runEntranceHandoffPracticeFirst));
                PlayHaptic(BuildRunEntranceHapticDuration());
            }

            lastRenderedScreenState = state;
            hasRenderedScreenState = true;
        }

        private static bool ShouldStartLobbyEntranceReveal(
            bool hadPreviousState,
            GreedLastScreenState previousState,
            GreedLastScreenState state)
        {
            return hadPreviousState
                && state == GreedLastScreenState.LobbyReady
                && previousState != GreedLastScreenState.LobbyReady;
        }

        internal static float BuildLobbyEntranceRevealProgress(
            bool visible,
            float now,
            float startedAt,
            float until)
        {
            if (!visible)
            {
                return 0f;
            }

            float duration = until - startedAt;
            if (duration <= 0f || now >= until)
            {
                return 1f;
            }

            if (now <= startedAt)
            {
                return 0f;
            }

            return Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((now - startedAt) / duration));
        }

        private static int BuildLobbyEntranceRevealAlpha(int baseAlpha, float revealProgress)
        {
            return Mathf.RoundToInt(Mathf.Clamp(baseAlpha, 0, 255) * Mathf.Clamp01(revealProgress));
        }

        private static float BuildLobbyRunnerRevealYOffset(float revealProgress)
        {
            return Mathf.Lerp(-22f, 0f, Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(revealProgress)));
        }

        private static bool ShouldStartRunEntranceHandoff(
            bool hadPreviousState,
            GreedLastScreenState previousState,
            GreedLastScreenState state)
        {
            return hadPreviousState
                && previousState == GreedLastScreenState.LobbyReady
                && state == GreedLastScreenState.RunCoreTest;
        }

        internal static float BuildRunEntranceHandoffProgress(
            bool runVisible,
            float now,
            float startedAt,
            float until)
        {
            if (!runVisible)
            {
                return 0f;
            }

            float duration = until - startedAt;
            if (duration <= 0f || now >= until)
            {
                return 1f;
            }

            if (now <= startedAt)
            {
                return 0f;
            }

            return Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((now - startedAt) / duration));
        }

        private static float BuildRunEntrancePortalVisibility(float handoffProgress)
        {
            return 1f - Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(handoffProgress));
        }

        private static float BuildRunEntranceRunnerScale(float handoffProgress)
        {
            return Mathf.Lerp(0.60f, 1f, Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(handoffProgress)));
        }

        private static float BuildRunEntranceRunnerOffsetY(float handoffProgress)
        {
            return Mathf.Lerp(-24f, 0f, Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(handoffProgress)));
        }

        private static float BuildRunEntranceRunnerAlpha(
            float handoffProgress,
            bool portalReady,
            bool practiceFirst)
        {
            float lobbyAlpha = portalReady ? 0.88f : practiceFirst ? 0.68f : 0.58f;
            return Mathf.Lerp(
                lobbyAlpha,
                1f,
                Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(handoffProgress)));
        }

        private static float BuildLobbyEntranceCueVolume()
        {
            return 0.16f;
        }

        private static float BuildRunEntranceCueVolume(bool portalReady, bool practiceFirst)
        {
            return portalReady ? 0.22f : practiceFirst ? 0.18f : 0.16f;
        }

        private static float BuildRunEntranceHapticDuration()
        {
            return 0.018f;
        }

        internal static int BuildLobbyRunPortalPieceAlpha(
            int pieceIndex,
            bool visible,
            bool ready,
            bool practiceFirst,
            float pulse)
        {
            if (!visible)
            {
                return 0;
            }

            int safeIndex = Mathf.Clamp(pieceIndex, 0, LobbyRunPortalPieceCount - 1);
            float strength = BuildLobbyRunPortalPulse(visible, ready, pulse);
            float baseAlpha = safeIndex == 3 ? 72f : safeIndex == 2 ? 58f : 48f;
            if (ready)
            {
                baseAlpha += safeIndex == 3 ? 96f : safeIndex == 2 ? 72f : 54f;
            }
            else if (practiceFirst)
            {
                baseAlpha += safeIndex == 3 ? 16f : 10f;
            }

            return Mathf.RoundToInt(Mathf.Clamp(baseAlpha * strength, 0f, 255f));
        }

        internal static int BuildLobbyRunPortalPipAlpha(
            int pipIndex,
            bool visible,
            bool ready,
            float phase)
        {
            if (!visible || !ready)
            {
                return 0;
            }

            int safeIndex = Mathf.Clamp(pipIndex, 0, LobbyRunPortalPipCount - 1);
            float shifted = Mathf.Repeat(phase - safeIndex * 0.18f, 1f);
            float travelPulse = 1f - Mathf.Abs(shifted * 2f - 1f);
            return Mathf.RoundToInt(Mathf.Lerp(74f, 208f, travelPulse));
        }

        internal static float BuildLobbyRunButtonEmphasis(
            bool portalVisible,
            bool portalReady,
            float pulse)
        {
            if (!portalVisible || !portalReady)
            {
                return 0f;
            }

            return Mathf.Lerp(0.24f, 1f, Mathf.Clamp01(pulse));
        }

        internal static float BuildLobbyPracticeButtonEmphasis(
            bool portalVisible,
            bool practiceFirst,
            float pulse)
        {
            if (!portalVisible || !practiceFirst)
            {
                return 0f;
            }

            return Mathf.Lerp(0.18f, 0.72f, Mathf.Clamp01(pulse));
        }

        internal static float BuildLobbyRunButtonScale(float emphasis)
        {
            return 1f + Mathf.Clamp01(emphasis) * 0.015f;
        }

        private static string BuildModeSubtitleForScreen(GreedLastScreenState state)
