        private static bool IsSelectedSaveSlotLastUse(GreedLastStateSnapshot snapshot)
        {
            if (snapshot.SaveSlotLabels == null
                || snapshot.SelectedSaveSlotIndex < 0
                || snapshot.SelectedSaveSlotIndex >= snapshot.SaveSlotLabels.Length)
            {
                return false;
            }

            return IsSaveSlotFinalUseLabel(snapshot.SaveSlotLabels[snapshot.SelectedSaveSlotIndex]);
        }

        private static bool HasSaveSlotUseStatusLabel(string label)
        {
            return ExtractSaveSlotUsesRemainingForVisual(label) > 0
                || IsSaveSlotFinalUseLabel(label);
        }

        private static bool IsSaveSlotFinalUseLabel(string label)
        {
            if (string.IsNullOrWhiteSpace(label))
            {
                return false;
            }

            string trimmed = label.Trim();
            return trimmed.StartsWith("마지막", StringComparison.Ordinal)
                || trimmed.Contains("마지막 1회", StringComparison.Ordinal)
                || trimmed.Contains("1/2 마지막", StringComparison.Ordinal)
                || trimmed.Contains("(1/2)", StringComparison.Ordinal);
        }

        private static bool HasAnyUsableSaveSlot(GreedLastStateSnapshot snapshot)
        {
            if (snapshot.SaveSlotUsable == null)
            {
                return false;
            }

            for (int i = 0; i < snapshot.SaveSlotUsable.Length; i += 1)
            {
                if (snapshot.SaveSlotUsable[i])
                {
                    return true;
                }
            }

            return false;
        }

        private static bool IsCoreOnboardingComplete(GreedLastStateSnapshot snapshot)
        {
            return PlayerPrefs.GetInt(GreedLastApp.PracticeCompletedPrefsKey, 0) == 1
                || snapshot.FirstSaveCompleted
                || snapshot.SaveLoadoutUnlocked;
        }

        private static bool HasAnySaveSlotOccupied(GreedLastStateSnapshot snapshot)
        {
            if (snapshot.SaveSlotOccupied == null)
            {
                return false;
            }

            for (int i = 0; i < snapshot.SaveSlotOccupied.Length; i += 1)
            {
                if (snapshot.SaveSlotOccupied[i])
                {
                    return true;
                }
            }

            return false;
        }

        private static bool IsSelectedSaveSlotUsable(GreedLastLobbySnapshot snapshot)
        {
            return snapshot.SaveSlotUsable != null
                && snapshot.SelectedSaveSlotIndex >= 0
                && snapshot.SelectedSaveSlotIndex < snapshot.SaveSlotUsable.Length
                && snapshot.SaveSlotUsable[snapshot.SelectedSaveSlotIndex];
