            shadow.SetActive(false);

            GameObject coreGlow = CreateRect("RunnerCoreGlow", parent, new Vector2(0.5f, 0.205f), new Vector2(0.5f, 0.205f), new Vector2(0.5f, 0.5f), new Vector2(240f, 240f));
            runnerCoreGlow = coreGlow.AddComponent<Image>();
            runnerCoreGlow.color = new Color32(255, 214, 105, 0);
            runnerCoreGlow.raycastTarget = false;
            coreGlow.SetActive(false);

            CreateRunnerActionTrails(parent);
            CreateRunnerFootfallPips(parent);

            GameObject preparationCue = CreateRect("RunnerPreparationCue", parent, new Vector2(0.5f, 0.155f), new Vector2(0.5f, 0.155f), new Vector2(0.5f, 0.5f), new Vector2(92f, 12f));
            runnerPreparationCue = preparationCue.AddComponent<Image>();
            runnerPreparationCue.color = new Color32(255, 238, 181, 0);
            runnerPreparationCue.raycastTarget = false;
            preparationCue.SetActive(false);

            runnerPreparationSymbolText = CreateText(parent, "RunnerPreparationSymbol", string.Empty, 38, TextAnchor.MiddleCenter, FontStyle.Bold);
            runnerPreparationSymbolText.rectTransform.anchorMin = new Vector2(0.5f, 0.155f);
            runnerPreparationSymbolText.rectTransform.anchorMax = runnerPreparationSymbolText.rectTransform.anchorMin;
            runnerPreparationSymbolText.rectTransform.sizeDelta = new Vector2(96f, 72f);
            runnerPreparationSymbolText.color = new Color32(255, 238, 181, 0);
            runnerPreparationSymbolText.raycastTarget = false;
            runnerPreparationSymbolText.gameObject.SetActive(false);

            runnerAvatarRoot = CreateRect("RunnerAvatar", parent, new Vector2(0.5f, 0.155f), new Vector2(0.5f, 0.155f), new Vector2(0.5f, 0.12f), new Vector2(120f, 190f));
            runnerAvatarCanvasGroup = runnerAvatarRoot.AddComponent<CanvasGroup>();
            runnerAvatarCanvasGroup.alpha = 1f;
            runnerAvatarCanvasGroup.blocksRaycasts = false;
            runnerAvatarCanvasGroup.interactable = false;
            runnerAvatarRoot.SetActive(false);

            Texture2D runnerTexture = Resources.Load<Texture2D>("GreedLast/PrototypeRunner");
            if (runnerTexture != null)
            {
                GameObject illustration = CreateRect(
                    "RunnerIllustration",
                    runnerAvatarRoot.transform,
                    new Vector2(0.5f, 0.5f),
                    new Vector2(0.5f, 0.5f),
                    new Vector2(0.5f, 0.5f),
                    new Vector2(138f, 207f));
                runnerIllustration = illustration.AddComponent<RawImage>();
                runnerIllustration.texture = runnerTexture;
                runnerIllustration.color = new Color32(255, 255, 255, 240);
                runnerIllustration.raycastTarget = false;
                runnerIllustration.rectTransform.anchoredPosition = new Vector2(4f, 2f);
            }

            Color32 bodyColor = PrototypeRunnerSkinColor;
            runnerHairBack = CreateRunnerPart(runnerAvatarRoot.transform, "RunnerHairBack", 0.5f, 0.80f, 58f, 48f, PrototypeRunnerHairColor);
            runnerHead = CreateRunnerPart(runnerAvatarRoot.transform, "RunnerHead", 0.5f, 0.81f, 34f, 36f, bodyColor);
            runnerLeftHorn = CreateRunnerPart(runnerAvatarRoot.transform, "RunnerLeftHorn", 0.38f, 0.96f, 16f, 34f, PrototypeRunnerHornColor);
            runnerRightHorn = CreateRunnerPart(runnerAvatarRoot.transform, "RunnerRightHorn", 0.62f, 0.96f, 16f, 34f, PrototypeRunnerHornColor);
            SetRunnerPartAngle(runnerLeftHorn, -22f);
            SetRunnerPartAngle(runnerRightHorn, 22f);
            runnerTorso = CreateRunnerPart(runnerAvatarRoot.transform, "RunnerTorso", 0.5f, 0.55f, 45f, 72f, bodyColor);
            runnerSash = CreateRunnerPart(runnerAvatarRoot.transform, "RunnerSash", 0.55f, 0.49f, 58f, 13f, PrototypeRunnerSashColor);
            SetRunnerPartAngle(runnerSash, -8f);
            runnerLeftArm = CreateRunnerPart(runnerAvatarRoot.transform, "RunnerLeftArm", 0.28f, 0.54f, 15f, 68f, bodyColor);
            runnerRightArm = CreateRunnerPart(runnerAvatarRoot.transform, "RunnerRightArm", 0.72f, 0.54f, 15f, 68f, bodyColor);
            runnerLeftLeg = CreateRunnerPart(runnerAvatarRoot.transform, "RunnerLeftLeg", 0.39f, 0.22f, 18f, 72f, bodyColor);
            runnerRightLeg = CreateRunnerPart(runnerAvatarRoot.transform, "RunnerRightLeg", 0.61f, 0.22f, 18f, 72f, bodyColor);
            if (runnerPreparationSymbolText != null)
            {
                runnerPreparationSymbolText.transform.SetAsLastSibling();
            }
        }

