        private GameObject CreateRunGauge(Transform parent, string name, float x, Color32 fillColor, out Image fillImage, out Text valueText)
        {
            GameObject gaugeRoot = CreateRect(name, parent, new Vector2(x, 0.5f), new Vector2(x, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(360f, 76f));

            Image back = CreateRect(name + "Back", gaugeRoot.transform, new Vector2(0f, 0.24f), new Vector2(1f, 0.70f), Vector2.zero, Vector2.zero).AddComponent<Image>();
            back.color = new Color32(19, 27, 30, 210);
            back.raycastTarget = false;

            fillImage = CreateRect(name + "Fill", back.transform, Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero).AddComponent<Image>();
            fillImage.color = fillColor;
            fillImage.raycastTarget = false;

            valueText = CreateText(gaugeRoot.transform, name + "Value", string.Empty, 32, TextAnchor.MiddleLeft, FontStyle.Bold);
            SetAnchored(valueText.rectTransform, 0.5f, 0.92f, 360f, 52f);
            valueText.color = new Color32(237, 239, 231, 240);
            valueText.raycastTarget = false;

            return gaugeRoot;
        }

        private void CreateTemplePreview(Transform parent)
        {
            GameObject laneRoot = CreateRect("LanePreview", parent, new Vector2(0.14f, 0.44f), new Vector2(0.86f, 0.74f), Vector2.zero, Vector2.zero);
            lanePreviewRoot = laneRoot;
            laneRoot.AddComponent<CanvasGroup>().alpha = 0.95f;
            CreateTempleDepthBackdrop(laneRoot.transform);
            CreateLobbyRunPortal(laneRoot.transform);

            laneImages = new Image[3];
            laneInputRipples = new Image[3];
            laneTargetGlows = new Image[3];
            laneJudgementTagTexts = new Text[3];
            laneHoldActive = new bool[3];
            laneHeldPointers = new[] { new HashSet<int>(), new HashSet<int>(), new HashSet<int>() };
            laneKeyboardHoldActive = new bool[3];
            lanePressPulseUntil = new float[3];
            laneInputRippleUntil = new float[3];
            laneJudgementPulseUntil = new float[3];
            laneJudgementTagUntil = new float[3];
            laneMissShakeUntil = new float[3];
            laneJudgementPulseColors = new Color32[3];
            laneJudgementTagColors = new Color32[3];
            laneJudgementTagResults = new GreedLastJudgementResult[3];
            laneButtons = new Button[3];
            laneHitButtons = new Button[3];
            laneLabelTexts = new Text[3];
            saveSlotUsePips = new Image[3, SaveSlotUsePipCount];
            for (int i = 0; i < laneImages.Length; i += 1)
            {
                float x = 0.2f + i * 0.3f;
                int capturedIndex = i;

                GameObject hitZone = CreateRect("LaneHitZone_" + i, laneRoot.transform, new Vector2(x, 0.5f), new Vector2(x, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(230f, 580f));
                Image hitImage = hitZone.AddComponent<Image>();
                hitImage.color = new Color32(255, 255, 255, 0);
                Button hitButton = hitZone.AddComponent<Button>();
                hitButton.transition = Selectable.Transition.None;
                AddLanePointerDown(hitZone, hitButton, capturedIndex);
                laneHitButtons[i] = hitButton;

                GameObject lane = CreateRect("Lane_" + i, laneRoot.transform, new Vector2(x, 0.5f), new Vector2(x, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(195f, 520f));
                Image laneImage = lane.AddComponent<Image>();
                laneImage.color = new Color32(32, 42, 49, 255);
                laneImages[i] = laneImage;
                Button laneButton = lane.AddComponent<Button>();
                ColorBlock laneColors = laneButton.colors;
                laneColors.normalColor = Color.white;
                laneColors.highlightedColor = new Color32(255, 238, 181, 255);
                laneColors.pressedColor = new Color32(205, 166, 70, 255);
                laneColors.disabledColor = new Color32(66, 71, 72, 180);
                laneButton.colors = laneColors;
                AddLanePointerDown(lane, laneButton, capturedIndex);
                laneButtons[i] = laneButton;

                GameObject ripple = CreateRect("LaneInputRipple_" + i, lane.transform, Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero);
                Image rippleImage = ripple.AddComponent<Image>();
                rippleImage.color = new Color32(255, 238, 181, 0);
                rippleImage.raycastTarget = false;
                laneInputRipples[i] = rippleImage;

                GameObject targetGlow = CreateRect("LaneTargetGlow_" + i, lane.transform, new Vector2(0.05f, 0.02f), new Vector2(0.95f, 0.98f), Vector2.zero, Vector2.zero);
                Image targetGlowImage = targetGlow.AddComponent<Image>();
                targetGlowImage.color = new Color32(255, 238, 181, 0);
                targetGlowImage.raycastTarget = false;
                laneTargetGlows[i] = targetGlowImage;

                Text laneLabel = CreateText(lane.transform, "Label", i == 0 ? "좌" : i == 1 ? "중" : "우", 56, TextAnchor.MiddleCenter, FontStyle.Bold);
                laneLabel.color = new Color32(218, 226, 218, 230);
                laneLabel.horizontalOverflow = HorizontalWrapMode.Wrap;
                laneLabel.verticalOverflow = VerticalWrapMode.Overflow;
                laneLabel.rectTransform.anchorMin = Vector2.zero;
                laneLabel.rectTransform.anchorMax = Vector2.one;
                laneLabel.rectTransform.offsetMin = Vector2.zero;
                laneLabel.rectTransform.offsetMax = Vector2.zero;
                laneLabel.raycastTarget = false;
                laneLabelTexts[i] = laneLabel;

                CreateSaveSlotUsePips(lane.transform, i);

                Text judgementTag = CreateText(lane.transform, "JudgementTag", string.Empty, 29, TextAnchor.MiddleCenter, FontStyle.Bold);
                SetAnchored(judgementTag.rectTransform, 0.5f, 0.20f, 150f, 48f);
                judgementTag.color = new Color32(255, 238, 181, 0);
                judgementTag.resizeTextForBestFit = true;
                judgementTag.resizeTextMinSize = 18;
                judgementTag.resizeTextMaxSize = 29;
                judgementTag.raycastTarget = false;
                laneJudgementTagTexts[i] = judgementTag;
            }

            CreateStraightRunCorridorGates(laneRoot.transform);
            CreateStraightRunSideWallStripes(laneRoot.transform);
            CreateStraightRunSpeedStreaks(laneRoot.transform);
            CreateStraightRunCenterSeamDashes(laneRoot.transform);
            CreateStraightRunForwardPaceMarkers(laneRoot.transform);
            CreateStraightRunFocusRings(laneRoot.transform);
            CreateStraightRunTargetFrame(laneRoot.transform);
            CreateStraightRunExitSlot(laneRoot.transform);
            CreateStraightRunExitApproachRails(laneRoot.transform);
            CreateStraightRunFocusBeacon(laneRoot.transform);
            CreateStraightRunLaunchGate(laneRoot.transform);
            CreateStraightRunRotationComfortAnchor(laneRoot.transform);
            CreateStraightRunRotationTiltPips(laneRoot.transform);
            CreateForwardMotionLines(laneRoot.transform);

            GameObject goodBand = CreateRect("GoodTimingBand", laneRoot.transform, new Vector2(0.08f, 0.20f), new Vector2(0.92f, 0.24f), Vector2.zero, Vector2.zero);
            goodTimingBand = goodBand.AddComponent<Image>();
            goodTimingBand.color = new Color32(105, 168, 190, 0);
            goodTimingBand.raycastTarget = false;

            GameObject successBand = CreateRect("SuccessTimingBand", laneRoot.transform, new Vector2(0.08f, 0.21f), new Vector2(0.92f, 0.23f), Vector2.zero, Vector2.zero);
            successTimingBand = successBand.AddComponent<Image>();
            successTimingBand.color = new Color32(255, 238, 181, 0);
            successTimingBand.raycastTarget = false;

            GameObject centerBand = CreateRect("CenterTimingBand", laneRoot.transform, new Vector2(0.08f, 0.216f), new Vector2(0.92f, 0.224f), Vector2.zero, Vector2.zero);
            centerTimingBand = centerBand.AddComponent<Image>();
            centerTimingBand.color = new Color32(255, 248, 210, 0);
            centerTimingBand.raycastTarget = false;

            timingBeatPips = new Image[TimingBeatPipCount];
            for (int i = 0; i < timingBeatPips.Length; i += 1)
            {
                GameObject pip = CreateRect("TimingBeatPip_" + i, laneRoot.transform, new Vector2(0.5f, 0.18f), new Vector2(0.5f, 0.18f), new Vector2(0.5f, 0.5f), new Vector2(112f, 8f));
                Image pipImage = pip.AddComponent<Image>();
                pipImage.color = new Color32(255, 238, 181, 0);
                pipImage.raycastTarget = false;
                timingBeatPips[i] = pipImage;
            }

            CreateThreeActionExactBurstPips(laneRoot.transform);

            GameObject line = CreateRect("JudgementLine", laneRoot.transform, new Vector2(0.08f, 0.22f), new Vector2(0.92f, 0.22f), new Vector2(0.5f, 0.5f), new Vector2(0f, 18f));
            judgementLine = line.AddComponent<Image>();
            judgementLine.color = new Color32(255, 238, 181, 205);
            judgementLine.raycastTarget = false;

            GameObject breakLine = CreateRect("RhythmBreakLine", laneRoot.transform, new Vector2(0.5f, 0.22f), new Vector2(0.5f, 0.22f), new Vector2(0.5f, 0.5f), new Vector2(760f, 8f));
            rhythmBreakLine = breakLine.AddComponent<Image>();
