        private void AddLanePointerDown(GameObject target, Button gateButton, int laneIndex)
        {
            gateButton.navigation = new Navigation { mode = Navigation.Mode.None };
            EventTrigger trigger = target.AddComponent<EventTrigger>();
            EventTrigger.Entry entry = new EventTrigger.Entry
            {
                eventID = EventTriggerType.PointerDown,
            };
            entry.callback.AddListener(data =>
            {
                if (!(data is PointerEventData pointer)
                    || !AcceptsPlayerInput
                    || pointer.button != PointerEventData.InputButton.Left
                    || gateButton == null || !gateButton.IsActive() || !gateButton.IsInteractable())
                {
                    return;
                }

                if (!GreedLastPointerInput.IsFreshPress(pointer))
                {
                    pointer.eligibleForClick = false;
                    return;
                }

                if (!laneHeldPointers[laneIndex].Add(pointer.pointerId))
                {
                    return;
                }

                laneHoldActive[laneIndex] = true;
                runChannelRequested?.Invoke((GreedLastRunChannel)(laneIndex + 1));
            });
            trigger.triggers.Add(entry);
            AddLanePointerRelease(trigger, laneIndex, EventTriggerType.PointerUp);
            AddLanePointerRelease(trigger, laneIndex, EventTriggerType.PointerExit);
            AddLanePointerRelease(trigger, laneIndex, EventTriggerType.Cancel);
        }

        private void AddLanePointerRelease(EventTrigger trigger, int laneIndex, EventTriggerType eventType)
        {
            EventTrigger.Entry entry = new EventTrigger.Entry
            {
                eventID = eventType,
            };
            entry.callback.AddListener(data =>
            {
                if (eventType == EventTriggerType.Cancel)
                {
                    ClearLanePointerHold(laneIndex);
                }
                else if (data is PointerEventData pointer && pointer.button == PointerEventData.InputButton.Left)
                {
                    laneHeldPointers[laneIndex].Remove(pointer.pointerId);
                    laneHoldActive[laneIndex] = laneHeldPointers[laneIndex].Count > 0;
                }
            });
            trigger.triggers.Add(entry);
        }

        private void ClearLanePointerHold(int laneIndex)
        {
            if (laneHeldPointers == null || laneIndex < 0 || laneIndex >= laneHeldPointers.Length) return;
            laneHeldPointers[laneIndex].Clear();
            laneHoldActive[laneIndex] = false;
        }

        private void ClearLanePointerHolds()
        {
            if (laneHeldPointers == null) return;
            for (int i = 0; i < laneHeldPointers.Length; i++) ClearLanePointerHold(i);
        }

        internal void CancelPendingUiInput()
        {
            ClearLanePointerHolds();
            if (menuDetailScroll is GreedLastMenuScrollRect scroll) scroll.CancelPendingGestures();
            if (menuDetailScroll != null && menuDetailScroll.verticalScrollbar is GreedLastMenuScrollbar bar)
                bar.CancelPendingGestures();
            if (rootPanel == null) return;
            foreach (GreedLastCommandButton button in rootPanel.GetComponentsInChildren<GreedLastCommandButton>(true))
                button.CancelPendingPresses();
        }

        internal void SetAppInputAvailable(bool available)
        {
            appInputAvailable = available;
            RefreshPlayerInputGroup();
            RefreshAudioPlaybackState();
        }

        private void RefreshPlayerInputGroup()
        {
            if (playerInputGroup != null)
            {
                playerInputGroup.interactable = AcceptsPlayerInput;
                // Keep the menu occluding the scene even when its controls are suspended.
                playerInputGroup.blocksRaycasts = true;
            }
            if (!AcceptsPlayerInput)
            {
                CancelPendingUiInput();
                // ScrollRect does not consult CanvasGroup.interactable; OnDisable also cancels its drag.
                if (rootPanel == null) return;
                foreach (ScrollRect scroll in rootPanel.GetComponentsInChildren<ScrollRect>(true))
                {
                    if (!scroll.enabled) continue;
                    suspendedPlayerScrolls.Add(scroll);
                    scroll.enabled = false;
                }
            }
            else
            {
                foreach (ScrollRect scroll in suspendedPlayerScrolls)
                    if (scroll != null) scroll.enabled = true;
                suspendedPlayerScrolls.Clear();
            }
        }

        public bool IsPointerOverInteractiveUi(Vector2 screenPoint)
        {
            EventSystem events = EventSystem.current;
            if (events == null) return false;
            var hits = new List<RaycastResult>();
            events.RaycastAll(new PointerEventData(events) { position = screenPoint }, hits);
            if (hits.Count == 0) return false;
            Transform hit = hits[0].gameObject.transform;
            return hit.GetComponentInParent<Selectable>() != null || hit.GetComponentInParent<ScrollRect>() != null;
        }

        private void OnApplicationFocus(bool hasFocus)
        {
            sensoryHasFocus = hasFocus;
            RefreshPlayerInputGroup();
            RefreshAudioPlaybackState();
            if (!hasFocus) PresentationSuspended?.Invoke();
        }

        private void OnApplicationPause(bool paused)
        {
            sensoryAppPaused = paused;
            RefreshPlayerInputGroup();
            RefreshAudioPlaybackState();
            if (paused) PresentationSuspended?.Invoke();
        }

        private void OnEnable()
        {
            sensoryComponentEnabled = true;
            RefreshPlayerInputGroup();
            if (Application.isPlaying && ownedCanvas != null)
            {
                ownedCanvas.SetActive(true);
                EnsureCamera();
                EnsureAudioListener();
                EnsureEventSystem();
            }
            RefreshPlayerInputGroup();
            RecoverAudioConfiguration();
            RefreshAudioPlaybackState();
        }

        private void OnDisable()
        {
            sensoryComponentEnabled = false;
            RefreshPlayerInputGroup();
            RefreshAudioPlaybackState();
            CancelPendingUiInput();
            if (Application.isPlaying && ownedCanvas != null) ownedCanvas.SetActive(false);
            PresentationSuspended?.Invoke();
        }

        private void OnDestroy()
        {
            ReleasePresentation();
            StopRhythmAudio();
            SceneManager.sceneLoaded -= RestoreSceneResources;
            AudioSettings.OnAudioConfigurationChanged -= HandleAudioConfigurationChanged;
            audioConfigurationSubscribed = false;
            audioConfigurationPending = false;
            ReleaseOwnedAudioClips();
            ReleaseOwnedAudioListener();
            if (ownedAudioSource != null)
            {
                if (Application.isPlaying) Destroy(ownedAudioSource);
                else DestroyImmediate(ownedAudioSource);
            }
            RestoreBorrowedNavigation();
            ReleaseOwnedEventSystem();
            if (Application.isPlaying)
            {
                if (ownedCanvas != null) Destroy(ownedCanvas);
                if (ownedCamera != null) Destroy(ownedCamera);
            }
        }

        private void ReleasePresentation()
        {
            if (presentationReleased) return;
            presentationReleased = true;
            PresentationReleased?.Invoke(this);
        }

        private void CreateAudio()
        {
            sfxVolume = NormalizeSfxVolume(PlayerPrefs.GetFloat(SfxVolumePrefsKey, DefaultSfxVolume));
            hapticsEnabled = PlayerPrefs.GetInt(HapticsEnabledPrefsKey, 1) == 1;
            rotationTiltEnabled = IsRotationTiltEnabledFromPrefs();
            motionComfortEnabled = PlayerPrefs.GetInt(MotionComfortEnabledPrefsKey, 1) == 1;
            rhythmAudio = gameObject.AddComponent<AudioSource>();
            ownedAudioSource = rhythmAudio;
            rhythmAudio.playOnAwake = false;
            rhythmAudio.loop = false;
            rhythmAudio.spatialBlend = 0f;
            CreatePrototypeTones();
            if (!audioConfigurationSubscribed)
            {
                AudioSettings.OnAudioConfigurationChanged += HandleAudioConfigurationChanged;
                audioConfigurationSubscribed = true;
            }
            RefreshAudioPlaybackState();
        }

        private void HandleAudioConfigurationChanged(bool deviceWasChanged)
        {
            if (ownedAudioSource == null || ownedAudioClips.Count == 0) return;
            audioConfigurationPending = true;
            StopRhythmAudio();
            ResetRhythmBeatSchedule();
            CancelPendingUiInput();
            PresentationSuspended?.Invoke();
            RecoverAudioConfiguration();
            RefreshAudioPlaybackState();
        }

        private void RecoverAudioConfiguration()
        {
            if (!audioConfigurationPending || !isActiveAndEnabled || ownedAudioSource == null) return;
            // Device resets invalidate generated PCM; reuse the source and keep the chosen preferences.
            ReleaseOwnedAudioClips();
            CreatePrototypeTones();
            audioConfigurationPending = false;
        }

        private void ReleaseOwnedAudioClips()
        {
            if (rhythmAudio != null && ownedAudioClips.Contains(rhythmAudio.clip)) rhythmAudio.clip = null;
            foreach (AudioClip clip in ownedAudioClips)
            {
                if (clip == null) continue;
                if (Application.isPlaying) Destroy(clip);
                else DestroyImmediate(clip);
            }
            ownedAudioClips.Clear();
        }

