        private static void PreserveDuringPlay(GameObject gameObject)
        {
            if (Application.isPlaying && gameObject != null)
            {
                DontDestroyOnLoad(gameObject);
            }
        }

        private void EnsureCamera()
        {
            if (FindAnyObjectByType<Camera>() != null)
            {
                return;
            }

            GameObject cameraObject = new GameObject("GreedLastCamera", typeof(Camera));
            ownedCamera = cameraObject;
            PreserveDuringPlay(cameraObject);

            Camera camera = cameraObject.GetComponent<Camera>();
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color32(11, 16, 18, 255);
            camera.orthographic = true;
            camera.orthographicSize = 5f;
            camera.transform.position = new Vector3(0f, 0f, -10f);
        }

        private void EnsureAudioListener()
        {
            // A scene can keep its listener on a player or other object, independently of its camera.
            foreach (AudioListener listener in FindObjectsByType<AudioListener>(FindObjectsSortMode.None))
            {
                if (listener != ownedAudioListener && listener.isActiveAndEnabled)
                {
                    ReleaseOwnedAudioListener();
                    return;
                }
            }
            if (ownedAudioListener != null) return;
            GameObject listenerObject = new GameObject("GreedLastAudioListener", typeof(AudioListener));
            ownedAudioListener = listenerObject.GetComponent<AudioListener>();
            PreserveDuringPlay(listenerObject);
        }

        private void ReleaseOwnedAudioListener()
        {
            if (ownedAudioListener == null) return;
            AudioListener listener = ownedAudioListener;
            ownedAudioListener = null;
            listener.enabled = false;
            if (Application.isPlaying) Destroy(listener.gameObject);
            else DestroyImmediate(listener.gameObject);
        }

        private void EnsureEventSystem()
        {
            EventSystem existing = EventSystem.current;
            if (!CanBorrowEventSystem(existing) || (ownedEventSystem != null && existing.gameObject == ownedEventSystem))
            {
                existing = null;
                foreach (EventSystem candidate in FindObjectsByType<EventSystem>(FindObjectsSortMode.InstanceID))
                {
                    if ((ownedEventSystem == null || candidate.gameObject != ownedEventSystem) && CanBorrowEventSystem(candidate))
                    {
                        existing = candidate;
                        break;
                    }
                }
            }
            if (existing != null)
            {
                if (existing != borrowedEventSystem)
                {
                    RestoreBorrowedNavigation();
                    borrowedEventSystem = existing;
                    borrowedNavigationEvents = existing.sendNavigationEvents;
                    existing.sendNavigationEvents = false;
                }
                if (ownedEventSystem != null) CancelPendingUiInput();
                ReleaseOwnedEventSystem();
                if (Application.isPlaying) EventSystem.current = existing;
                return;
            }

            RestoreBorrowedNavigation();
            borrowedEventSystem = null;
            if (ownedEventSystem == null)
            {
                ownedEventSystem = new GameObject("GreedLastEventSystem", typeof(EventSystem), typeof(StandaloneInputModule));
                PreserveDuringPlay(ownedEventSystem);
            }
            // GreedLastApp owns keyboard commands; Submit/Move would also activate the last clicked button.
            EventSystem fallback = ownedEventSystem.GetComponent<EventSystem>();
            fallback.sendNavigationEvents = false;
            if (Application.isPlaying) EventSystem.current = fallback;
        }

        private static bool CanBorrowEventSystem(EventSystem events)
        {
            if (events == null || !events.isActiveAndEnabled) return false;
            foreach (BaseInputModule module in events.GetComponents<BaseInputModule>())
                if (module.IsActive() && module.IsModuleSupported()) return true;
            return false;
        }

        private void ReleaseOwnedEventSystem()
        {
            if (ownedEventSystem == null) return;
            GameObject events = ownedEventSystem;
            ownedEventSystem = null;
            // Remove it from Unity's current-system list before deferred destruction.
            events.GetComponent<EventSystem>().enabled = false;
            if (Application.isPlaying) Destroy(events);
            else DestroyImmediate(events);
        }

        private void RestoreSceneResources(Scene scene, LoadSceneMode mode)
        {
            if (rootPanel == null) return;
            // The persistent canvas can outlive a camera or input system borrowed from its former scene.
            EnsureCamera();
            EnsureAudioListener();
            EnsureEventSystem();
        }

        private void RestoreBorrowedNavigation()
        {
            // Restore only our keyboard isolation; preserve a later external enable.
            if (borrowedEventSystem != null && !borrowedEventSystem.sendNavigationEvents)
                borrowedEventSystem.sendNavigationEvents = borrowedNavigationEvents;
        }

        private static Button CreateButton(Transform parent, string name, string label)
        {
            GameObject buttonObject = CreateRect(name, parent, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(620f, 90f));
            Image image = buttonObject.AddComponent<Image>();
            image.color = Color.white;

            Button button = buttonObject.AddComponent<GreedLastCommandButton>();
            button.navigation = new Navigation { mode = Navigation.Mode.None };
            ColorBlock colors = button.colors;
            colors.normalColor = ButtonNormalColor;
            colors.highlightedColor = ButtonHighlightedColor;
            colors.pressedColor = ButtonPressedColor;
            colors.selectedColor = ButtonHighlightedColor;
            colors.disabledColor = ButtonDisabledColor;
            button.colors = colors;

            Text text = CreateText(buttonObject.transform, "Label", label, 33, TextAnchor.MiddleCenter, FontStyle.Bold);
            text.color = new Color32(12, 16, 17, 255);
            text.resizeTextForBestFit = true;
            text.resizeTextMinSize = 18;
            text.resizeTextMaxSize = 33;
            text.rectTransform.anchorMin = Vector2.zero;
            text.rectTransform.anchorMax = Vector2.one;
            text.rectTransform.offsetMin = Vector2.zero;
            text.rectTransform.offsetMax = Vector2.zero;
            return button;
        }

        private static Text CreateText(Transform parent, string name, string value, int size, TextAnchor alignment, FontStyle style)
        {
            GameObject textObject = CreateRect(name, parent, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(800f, 160f));
            Text text = textObject.AddComponent<Text>();
            text.text = value;
            bool bold = style == FontStyle.Bold || style == FontStyle.BoldAndItalic;
            if (bold && prototypeBoldFont == null)
                prototypeBoldFont = Resources.Load<Font>("GreedLast/Fonts/NotoSansKR-Bold");
            if (!bold && prototypeRegularFont == null)
                prototypeRegularFont = Resources.Load<Font>("GreedLast/Fonts/NotoSansKR-Regular");
            Font bundledFont = bold ? prototypeBoldFont : prototypeRegularFont;
            text.font = bundledFont != null ? bundledFont : Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            text.fontSize = size;
            text.fontStyle = bundledFont != null
                ? (style == FontStyle.Italic || style == FontStyle.BoldAndItalic ? FontStyle.Italic : FontStyle.Normal)
                : style;
            text.alignment = alignment;
            text.horizontalOverflow = HorizontalWrapMode.Wrap;
            text.verticalOverflow = VerticalWrapMode.Overflow;
            text.color = new Color32(237, 239, 231, 255);
            return text;
        }

        private static GameObject CreateRect(string name, Transform parent, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 size)
        {
            GameObject obj = new GameObject(name, typeof(RectTransform));
            obj.transform.SetParent(parent, false);
            RectTransform rect = obj.GetComponent<RectTransform>();
            rect.anchorMin = anchorMin;
            rect.anchorMax = anchorMax;
            rect.pivot = pivot == Vector2.zero ? new Vector2(0.5f, 0.5f) : pivot;
            rect.sizeDelta = size;
            rect.anchoredPosition = Vector2.zero;
            return obj;
        }

        private void LateUpdate()
        {
            // Menus can remain idle while the OS moves a notch or resizes the window.
            ApplySafeArea();
        }

        private void ApplySafeArea(bool force = false)
        {
            ApplySafeAreaSample(Screen.safeArea, Screen.width, Screen.height, force);
        }

        private bool ApplySafeAreaSample(Rect safeArea, int screenWidth, int screenHeight, bool force = false)
        {
            if (rootPanelRect == null || screenWidth <= 0 || screenHeight <= 0)
            {
                return false;
            }

            if (!IsFiniteSafeAreaValue(safeArea.xMin) || !IsFiniteSafeAreaValue(safeArea.yMin)
                || !IsFiniteSafeAreaValue(safeArea.xMax) || !IsFiniteSafeAreaValue(safeArea.yMax))
                return false;
            Vector2 minimum = new Vector2(Mathf.Clamp(safeArea.xMin, 0f, screenWidth), Mathf.Clamp(safeArea.yMin, 0f, screenHeight));
            Vector2 maximum = new Vector2(Mathf.Clamp(safeArea.xMax, 0f, screenWidth), Mathf.Clamp(safeArea.yMax, 0f, screenHeight));
            // Preserve the last valid layout during transient zero/invalid OS samples.
            if (maximum.x - minimum.x < 1f || maximum.y - minimum.y < 1f) return false;
            bool sameSafeArea = Mathf.Approximately(safeArea.x, lastSafeArea.x)
                && Mathf.Approximately(safeArea.y, lastSafeArea.y)
                && Mathf.Approximately(safeArea.width, lastSafeArea.width)
                && Mathf.Approximately(safeArea.height, lastSafeArea.height)
                && lastSafeAreaScreenWidth == screenWidth
                && lastSafeAreaScreenHeight == screenHeight;
            if (!force && sameSafeArea)
            {
                return false;
            }

            Vector2 anchorMin = new Vector2(minimum.x / screenWidth, minimum.y / screenHeight);
            Vector2 anchorMax = new Vector2(maximum.x / screenWidth, maximum.y / screenHeight);
            bool changedViewport = lastSafeAreaScreenWidth > 0 && lastSafeAreaScreenHeight > 0
                && (lastSafeAreaScreenWidth != screenWidth || lastSafeAreaScreenHeight != screenHeight
                    || Vector2.Distance(rootPanelRect.anchorMin, anchorMin) > 0.00001f
                    || Vector2.Distance(rootPanelRect.anchorMax, anchorMax) > 0.00001f);
            rootPanelRect.anchorMin = anchorMin;
            rootPanelRect.anchorMax = anchorMax;
            rootPanelRect.offsetMin = Vector2.zero;
            rootPanelRect.offsetMax = Vector2.zero;
            lastSafeArea = safeArea;
            lastSafeAreaScreenWidth = screenWidth;
            lastSafeAreaScreenHeight = screenHeight;
            if (changedViewport)
            {
                CancelPendingUiInput();
                ViewportChanged?.Invoke();
            }
            return true;
        }

        private static bool IsFiniteSafeAreaValue(float value) => !float.IsNaN(value) && !float.IsInfinity(value);

        private static void SetAnchored(RectTransform rect, float x, float y, float width, float height)
        {
            rect.anchorMin = new Vector2(x, y);
            rect.anchorMax = new Vector2(x, y);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(width, height);
            rect.anchoredPosition = Vector2.zero;
        }

        private static void SetGaugeFill(Image fillImage, float amount)
        {
            if (fillImage == null)
            {
                return;
            }

            RectTransform rect = fillImage.rectTransform;
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = new Vector2(Mathf.Clamp01(amount), 1f);
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;
        }

        private float BuildLanePressPulse(int index)
        {
            if (lanePressPulseUntil == null || index < 0 || index >= lanePressPulseUntil.Length)
            {
                return 0f;
            }

            float remaining = lanePressPulseUntil[index] - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            return Mathf.Clamp01(remaining / 0.16f);
        }

        private void UpdateKeyboardLaneHoldVisuals()
        {
            if (laneKeyboardHoldActive == null)
            {
                return;
            }

            bool enabled = ShouldUseKeyboardLaneHoldVisualsForMode(
                DevToolsEnabled,
                runModeActive,
                hasRunSnapshot,
                hasRunSnapshot && latestRunSnapshot.Stopped,
                hasRunSnapshot && latestRunSnapshot.Paused,
                hasRunSnapshot && latestRunSnapshot.CountdownActive,
                hasRunSnapshot && latestRunSnapshot.ChoiceActive,
                saveSlotModeActive);
            if (!enabled)
            {
                ClearKeyboardLaneHoldVisuals();
                return;
            }

            ApplyKeyboardLaneHoldInput(GreedLastApp.CanUsePrototypeKeyboardInput(),
                IsLeftLaneKeyHeld(), IsCenterLaneKeyHeld(), IsRightLaneKeyHeld());
        }

        private void ApplyKeyboardLaneHoldInput(bool keyboardAllowed, bool leftHeld, bool centerHeld, bool rightHeld)
        {
            laneKeyboardHoldActive[0] = keyboardAllowed && leftHeld;
            laneKeyboardHoldActive[1] = keyboardAllowed && centerHeld;
            laneKeyboardHoldActive[2] = keyboardAllowed && rightHeld;
        }

        private void ClearKeyboardLaneHoldVisuals()
        {
            if (laneKeyboardHoldActive == null)
            {
                return;
            }

            for (int i = 0; i < laneKeyboardHoldActive.Length; i += 1)
            {
                laneKeyboardHoldActive[i] = false;
            }
        }

        private static bool ShouldUseKeyboardLaneHoldVisualsForMode(
            bool devToolsEnabled,
            bool runModeActive,
            bool hasSnapshot,
            bool stopped,
            bool paused,
            bool countdownActive,
            bool choiceActive,
            bool saveSlotModeActive)
        {
            return devToolsEnabled
                && runModeActive
                && hasSnapshot
                && !stopped
                && !paused
                && !countdownActive
                && !choiceActive
                && !saveSlotModeActive;
        }

        private static int BuildActiveRunTargetLaneIndex(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ActivePattern
                || !snapshot.Pattern.IsValid
                || !IsLiveRunControlWindow(snapshot))
            {
                return -1;
            }

            return Mathf.Clamp((int)snapshot.Pattern.Channel - 1, 0, 2);
        }

        private static bool ShouldHighlightActivePatternLane(GreedLastRunSnapshot snapshot, GreedLastRunChannel laneChannel)
        {
            return ShouldShowActivePatternVisuals(snapshot)
                && snapshot.Pattern.IsValid
                && snapshot.Pattern.Channel == laneChannel;
        }

        private static bool IsLeftLaneKeyHeld()
        {
            return Input.GetKey(KeyCode.A)
                || Input.GetKey(KeyCode.J)
                || Input.GetKey(KeyCode.Alpha1)
                || Input.GetKey(KeyCode.Keypad1)
                || Input.GetKey(KeyCode.LeftArrow);
        }

        private static bool IsCenterLaneKeyHeld()
        {
            return Input.GetKey(KeyCode.S)
                || Input.GetKey(KeyCode.K)
                || Input.GetKey(KeyCode.Alpha2)
                || Input.GetKey(KeyCode.Keypad2)
                || Input.GetKey(KeyCode.W)
                || Input.GetKey(KeyCode.Space)
                || Input.GetKey(KeyCode.UpArrow)
                || Input.GetKey(KeyCode.DownArrow);
        }

        private static bool IsRightLaneKeyHeld()
        {
            return Input.GetKey(KeyCode.D)
                || Input.GetKey(KeyCode.L)
                || Input.GetKey(KeyCode.Alpha3)
                || Input.GetKey(KeyCode.Keypad3)
                || Input.GetKey(KeyCode.RightArrow);
        }

        private float BuildLaneHoldAmount(int index)
        {
            bool touchHold = laneHoldActive != null
                && index >= 0
                && index < laneHoldActive.Length
                && laneHoldActive[index];
            bool keyboardHold = laneKeyboardHoldActive != null
                && index >= 0
                && index < laneKeyboardHoldActive.Length
                && laneKeyboardHoldActive[index];
            if (!touchHold && !keyboardHold)
            {
                return 0f;
            }

            return touchHold ? 1f : 0.86f;
        }

        private void HideLaneInputRipples()
        {
            if (laneInputRipples == null) return;
            for (int i = 0; i < laneInputRipples.Length; i++)
                UpdateLaneInputRipple(i, 0f, 0f, 0f, 0f, false);
        }

        private void UpdateLaneInputRipple(
            int index,
            float pressPulse,
            float holdAmount,
            float judgementPulse,
            float beatCueUrgency,
            bool visible)
        {
            if (laneInputRipples == null || index < 0 || index >= laneInputRipples.Length)
            {
                return;
            }

            Image ripple = laneInputRipples[index];
            if (ripple == null)
            {
                return;
            }

            if (!visible)
            {
                ripple.color = new Color32(255, 238, 181, 0);
                ripple.rectTransform.localScale = Vector3.one;
                return;
            }

            float remaining = laneInputRippleUntil != null && index < laneInputRippleUntil.Length
                ? laneInputRippleUntil[index] - Time.unscaledTime
                : 0f;
            float alpha = BuildLaneInputRippleAlpha(remaining);
            if (alpha <= 0f)
            {
                ripple.color = new Color32(255, 238, 181, 0);
                ripple.rectTransform.localScale = Vector3.one;
                return;
            }

            Color32 color = new Color32(255, 238, 181, 255);
            float choiceConfirmationPulse = BuildChoiceConfirmationPulse(
                index,
                choiceConfirmationLaneIndex,
                choiceConfirmationUntil - Time.unscaledTime);
            if (choiceConfirmationPulse > 0f)
            {
                color = Color32.Lerp(
                    color,
                    choiceConfirmationColor,
                    BuildChoiceConfirmationColorBlend(choiceConfirmationPulse));
            }

            if (beatCueUrgency > 0f)
            {
                color = Color32.Lerp(
                    color,
                    new Color32(255, 214, 105, 255),
                    BuildLaneInputRippleBeatCueColorBlend(beatCueUrgency));
            }

            if (judgementPulse > 0f)
            {
                color = Color32.Lerp(color, GetLaneJudgementPulseColor(index), judgementPulse * 0.74f);
            }

            float touchEmphasis = Mathf.Max(
                Mathf.Max(pressPulse, holdAmount * 0.52f),
                choiceConfirmationPulse);
            int finalAlpha = BuildLaneInputRippleAlphaWithJudgementAndBeatCue(
                remaining,
                touchEmphasis,
                judgementPulse,
                beatCueUrgency);
            ripple.color = WithAlpha(color, finalAlpha);
            float scale = BuildLaneInputRippleScaleWithJudgementAndBeatCue(remaining, judgementPulse, beatCueUrgency)
                + choiceConfirmationPulse * 0.055f;
            ripple.rectTransform.localScale = new Vector3(scale, scale, 1f);
        }

        private static float BuildLaneInputRippleAlpha(float remainingSeconds)
        {
            if (remainingSeconds <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remainingSeconds / LaneInputRippleDuration);
            return Mathf.Pow(normalized, 0.92f);
        }

        private static float BuildLaneInputRippleScale(float remainingSeconds)
        {
            float normalized = Mathf.Clamp01(remainingSeconds / LaneInputRippleDuration);
            float age = 1f - normalized;
            return Mathf.Lerp(0.82f, 1.18f, Mathf.SmoothStep(0f, 1f, age));
        }

        private static int BuildLaneInputRippleAlphaWithJudgement(
            float remainingSeconds,
            float touchEmphasis,
            float judgementPulse)
        {
            return BuildLaneInputRippleAlphaWithJudgementAndBeatCue(
                remainingSeconds,
                touchEmphasis,
                judgementPulse,
                0f);
        }

        private static int BuildLaneInputRippleAlphaWithJudgementAndBeatCue(
            float remainingSeconds,
            float touchEmphasis,
            float judgementPulse,
            float beatCueUrgency)
        {
            float alpha = BuildLaneInputRippleAlpha(remainingSeconds);
            float emphasis = Mathf.Clamp01(
                Mathf.Clamp01(touchEmphasis)
                + Mathf.Clamp01(judgementPulse) * 0.55f
                + Mathf.Clamp01(beatCueUrgency) * 0.28f);
            return Mathf.RoundToInt(Mathf.Lerp(74f, 148f, emphasis) * alpha);
        }

        private static float BuildLaneInputRippleScaleWithJudgement(float remainingSeconds, float judgementPulse)
        {
            return BuildLaneInputRippleScaleWithJudgementAndBeatCue(remainingSeconds, judgementPulse, 0f);
        }

        private static float BuildLaneInputRippleScaleWithJudgementAndBeatCue(
            float remainingSeconds,
            float judgementPulse,
            float beatCueUrgency)
        {
            return BuildLaneInputRippleScale(remainingSeconds)
                + Mathf.Clamp01(judgementPulse) * 0.085f
                + Mathf.Clamp01(beatCueUrgency) * 0.038f;
        }

        private static float BuildLaneInputRippleBeatCueColorBlend(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.18f;
        }

        private static bool ShouldShowLaneInputRipple(GreedLastRunSnapshot snapshot)
        {
            bool interactivePhase = snapshot.Phase == GreedLastRunPhase.RunPlaying
                || snapshot.Phase == GreedLastRunPhase.EscapeRunning
                || snapshot.Phase == GreedLastRunPhase.ChoiceSelecting;
            return interactivePhase
                && !snapshot.Stopped
                && !snapshot.Paused
                && !snapshot.CountdownActive;
        }

        private static float BuildLaneHoldColorBlend(float holdAmount)
        {
            return Mathf.Clamp01(holdAmount) * 0.24f;
        }

        private static float BuildLaneWrongHoldWarning(
            int laneIndex,
            int targetIndex,
            float holdAmount,
            float targetReadinessGlow)
        {
            if (laneIndex < 0
                || targetIndex < 0
                || laneIndex == targetIndex
                || holdAmount <= 0f)
            {
                return 0f;
            }

            float readiness = Mathf.Clamp01((Mathf.Clamp01(targetReadinessGlow) - 0.18f) / 0.82f);
            float distancePressure = Mathf.Clamp01(Mathf.Abs(laneIndex - targetIndex) / 2f);
            return Mathf.Clamp01(Mathf.Clamp01(holdAmount) * (0.16f + readiness * 0.56f + distancePressure * 0.12f));
        }

        private static float BuildLaneWrongHoldColorBlend(float warning)
        {
            return Mathf.Clamp01(warning) * 0.36f;
        }

        private static float BuildLaneWrongHoldScaleLift(float warning)
        {
            return Mathf.Clamp01(warning) * 0.030f;
        }

        private static float BuildLaneWrongHoldLabelColorBlend(float warning)
        {
            return Mathf.Clamp01(warning) * 0.42f;
        }

        private static float BuildLaneWrongHoldLabelScaleLift(float warning)
        {
            return Mathf.Clamp01(warning) * 0.018f;
        }

        private static float BuildLanePressColorBlend(float pressPulse)
        {
            return Mathf.Clamp01(pressPulse) * 0.72f;
        }

        private static float BuildRunLaneSurfaceScale(
            float growthLevel,
            float holdAmount,
            float pressPulse,
            float judgementPulse,
            float trapEntryPulse,
            float targetGlow)
        {
            return 1f
                + Mathf.Max(0f, growthLevel) * 0.018f
                + Mathf.Clamp01(holdAmount) * 0.025f
                + Mathf.Clamp01(pressPulse) * 0.055f
                + Mathf.Clamp01(judgementPulse) * 0.075f
                + Mathf.Clamp01(trapEntryPulse) * 0.045f
                + Mathf.Clamp01(targetGlow) * 0.026f;
        }

        private static float BuildRunLaneLabelScale(float exactLanePulse, float holdAmount, float pressPulse, float judgementPulse)
        {
            return 1f
                + Mathf.Clamp01(exactLanePulse) * 0.10f
                + Mathf.Clamp01(holdAmount) * 0.025f
                + Mathf.Clamp01(pressPulse) * 0.04f
                + Mathf.Clamp01(judgementPulse) * 0.06f;
        }

        private static float BuildRunLaneLabelScaleX(float baseScale, float exactLanePulse)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(exactLanePulse) * 0.004f;
        }

        private static float BuildRunLaneLabelScaleY(float baseScale, float exactLanePulse)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(exactLanePulse) * 0.034f;
        }

        private static float BuildRunLaneLabelDownbeatLift(float downbeatPulse, float targetGlow, float exactLanePulse)
        {
            float readiness = Mathf.Clamp01(0.12f + Mathf.Clamp01(targetGlow) * 0.58f + Mathf.Clamp01(exactLanePulse) * 0.30f);
            return Mathf.Clamp01(downbeatPulse) * readiness;
        }

        private static float BuildRunLaneLabelDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.16f;
        }

        private static float BuildRunLaneLabelBeatCueUrgencyColorBlend(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.12f;
        }

        private static float BuildRunLaneLabelBeatCueUrgencyScaleLift(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.014f;
        }

        private static float BuildRunLaneLabelScaleWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.012f;
        }

        private static float BuildRunLaneLabelScaleXWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.003f;
        }

        private static float BuildRunLaneLabelScaleYWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.024f;
        }

        private void UpdateLaneTargetGlow(int index, float targetGlow, float judgementPulse, float beatCueUrgency)
        {
            if (laneTargetGlows == null || index < 0 || index >= laneTargetGlows.Length)
            {
                return;
            }

            Image glow = laneTargetGlows[index];
            if (glow == null)
            {
                return;
            }

            if (targetGlow <= 0f)
            {
                glow.color = new Color32(255, 238, 181, 0);
                glow.rectTransform.localScale = Vector3.one;
                return;
            }

            float urgency = Mathf.Clamp01(beatCueUrgency);
            float beatPulse = 0.5f + Mathf.Sin((beatPhase * 1.35f + index * 0.12f) * Mathf.PI * 2f) * 0.5f;
            float glowPulse = BuildLaneTargetGlowBeatPulse(targetGlow, beatPulse);
            float exactLock = BuildLaneTargetGlowExactLock(targetGlow, beatPulse, judgementPulse);
            float downbeatLift = BuildLaneTargetGlowDownbeatLift(
                ShouldShowDownbeatPulse(latestRunSnapshot) ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime) : 0f,
                targetGlow);
            Color32 color = Color32.Lerp(new Color32(105, 168, 190, 255), new Color32(255, 238, 181, 255), Mathf.Clamp01(targetGlow + glowPulse * 0.18f));
            if (urgency > 0f)
            {
                color = Color32.Lerp(color, new Color32(255, 238, 181, 255), BuildLaneTargetGlowUrgencyColorBlend(urgency));
            }
            if (exactLock > 0f)
            {
                color = Color32.Lerp(color, new Color32(255, 248, 210, 255), BuildLaneTargetGlowExactLockColorBlend(exactLock));
            }
            if (downbeatLift > 0f)
            {
                color = Color32.Lerp(color, new Color32(255, 214, 105, 255), BuildLaneTargetGlowDownbeatColorBlend(downbeatLift));
            }
            if (judgementPulse > 0f)
            {
                color = Color32.Lerp(color, GetLaneJudgementPulseColor(index), judgementPulse * 0.62f);
            }

            glow.color = WithAlpha(
                color,
                BuildLaneTargetGlowAlpha(targetGlow, beatPulse, judgementPulse)
                    + BuildLaneTargetGlowExactLockAlphaLift(exactLock)
                    + BuildLaneTargetGlowDownbeatAlphaLift(downbeatLift)
                    + BuildLaneTargetGlowUrgencyAlphaLift(urgency));
            glow.rectTransform.localScale = new Vector3(
                BuildLaneTargetGlowScaleXWithExactLock(targetGlow, beatPulse, judgementPulse, exactLock)
                    + BuildLaneTargetGlowDownbeatScaleXLift(downbeatLift)
                    + BuildLaneTargetGlowUrgencyScaleXLift(urgency),
                BuildLaneTargetGlowScaleYWithExactLock(targetGlow, beatPulse, judgementPulse, exactLock)
                    + BuildLaneTargetGlowDownbeatScaleYLift(downbeatLift)
                    + BuildLaneTargetGlowUrgencyScaleYLift(urgency),
                1f);
        }

        private void HideLaneTargetGlows()
        {
            if (laneTargetGlows == null)
            {
                return;
            }

            for (int i = 0; i < laneTargetGlows.Length; i += 1)
            {
                if (laneTargetGlows[i] == null)
                {
                    continue;
                }

                laneTargetGlows[i].color = new Color32(255, 238, 181, 0);
                laneTargetGlows[i].rectTransform.localScale = Vector3.one;
            }
        }

        private void UpdateLaneJudgementTag(int index, float judgementPulse)
        {
            if (laneJudgementTagTexts == null
                || laneJudgementTagUntil == null
                || index < 0
                || index >= laneJudgementTagTexts.Length
                || index >= laneJudgementTagUntil.Length)
            {
                return;
            }

            Text tag = laneJudgementTagTexts[index];
            if (tag == null)
            {
                return;
            }

            if (!CanShowRunTransientFeedback())
            {
                tag.color = new Color32(255, 238, 181, 0);
                tag.rectTransform.localScale = Vector3.one;
                tag.rectTransform.anchoredPosition = Vector2.zero;
                ClearLaneJudgementTagResult(index);
                return;
            }

            float remaining = laneJudgementTagUntil[index] - Time.unscaledTime;
            float alpha = BuildLaneJudgementTagAlpha(remaining, judgementPulse);
            if (alpha <= 0f)
            {
                tag.color = new Color32(255, 238, 181, 0);
                tag.rectTransform.localScale = Vector3.one;
                tag.rectTransform.anchoredPosition = Vector2.zero;
                ClearLaneJudgementTagResult(index);
                return;
            }

            Color32 color = laneJudgementTagColors != null && index < laneJudgementTagColors.Length
                ? laneJudgementTagColors[index]
                : new Color32(255, 238, 181, 255);
            GreedLastJudgementResult result = laneJudgementTagResults != null && index < laneJudgementTagResults.Length
                ? laneJudgementTagResults[index]
                : GreedLastJudgementResult.None;
            tag.color = WithAlpha(color, Mathf.RoundToInt(alpha * 255f));
            tag.rectTransform.localScale = Vector3.one * BuildLaneJudgementTagScaleForResult(remaining, judgementPulse, result);
            tag.rectTransform.anchoredPosition = new Vector2(0f, BuildLaneJudgementTagRiseForResult(remaining, result));
        }

        private void HideLaneJudgementTags()
        {
            if (laneJudgementTagTexts == null)
            {
                return;
            }

            for (int i = 0; i < laneJudgementTagTexts.Length; i += 1)
            {
                Text tag = laneJudgementTagTexts[i];
                if (tag == null)
                {
                    continue;
                }

                tag.color = new Color32(255, 238, 181, 0);
                tag.rectTransform.localScale = Vector3.one;
                tag.rectTransform.anchoredPosition = Vector2.zero;
                ClearLaneJudgementTagResult(i);
            }
        }

        private void ClearLaneJudgementTagResult(int index)
        {
            if (laneJudgementTagResults == null || index < 0 || index >= laneJudgementTagResults.Length)
            {
                return;
            }

            laneJudgementTagResults[index] = GreedLastJudgementResult.None;
        }

        private static float BuildLaneJudgementTagAlpha(float remainingSeconds, float judgementPulse)
        {
            if (remainingSeconds <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remainingSeconds / LaneJudgementTagDuration);
            float baseAlpha = Mathf.Pow(normalized, 0.72f);
            return Mathf.Clamp01(baseAlpha + Mathf.Clamp01(judgementPulse) * 0.12f);
        }

        private static float BuildLaneJudgementTagScale(float remainingSeconds, float judgementPulse)
        {
            return BuildLaneJudgementTagScaleForResult(
                remainingSeconds,
                judgementPulse,
                GreedLastJudgementResult.None);
        }

        private static float BuildLaneJudgementTagScaleForResult(
            float remainingSeconds,
            float judgementPulse,
            GreedLastJudgementResult result)
        {
            float normalized = Mathf.Clamp01(remainingSeconds / LaneJudgementTagDuration);
            float age = 1f - normalized;
            float pop = Mathf.Sin(Mathf.Clamp01(age * 1.35f) * Mathf.PI) * 0.16f;
            return 1f + pop + Mathf.Clamp01(judgementPulse) * 0.08f + BuildLaneJudgementTagResultPop(result);
        }

        private static float BuildLaneJudgementTagRise(float remainingSeconds)
        {
            return BuildLaneJudgementTagRiseForResult(remainingSeconds, GreedLastJudgementResult.None);
        }

        private static float BuildLaneJudgementTagRiseForResult(
            float remainingSeconds,
            GreedLastJudgementResult result)
        {
            float normalized = Mathf.Clamp01(remainingSeconds / LaneJudgementTagDuration);
            float age = 1f - normalized;
            return Mathf.Lerp(0f, 28f, Mathf.SmoothStep(0f, 1f, age)) * BuildLaneJudgementTagRiseMultiplier(result);
        }

        private static float BuildLaneJudgementTagResultPop(GreedLastJudgementResult result)
        {
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return 0.045f;
                case GreedLastJudgementResult.Good:
                    return 0.022f;
                case GreedLastJudgementResult.Miss:
                    return 0.034f;
                default:
                    return 0f;
            }
        }

        private static float BuildLaneJudgementTagRiseMultiplier(GreedLastJudgementResult result)
        {
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return 1.12f;
                case GreedLastJudgementResult.Good:
                    return 0.94f;
                case GreedLastJudgementResult.Miss:
                    return 0.74f;
                default:
                    return 1f;
            }
        }

        private static float BuildTargetLaneReadinessGlow(int laneIndex, GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ActivePattern
                || !snapshot.Pattern.IsValid
                || !IsLiveRunControlWindow(snapshot)
                || laneIndex != Mathf.Clamp((int)snapshot.Pattern.Channel - 1, 0, 2))
            {
                return 0f;
            }

            float interval = BuildTimingBeatPipInterval(snapshot.Pattern, BuildBeatInterval(snapshot));
            float secondsToCore = Mathf.Max(0f, -snapshot.CoreDeltaSeconds);
            float approach = Mathf.Clamp01(1f - secondsToCore / Mathf.Max(0.01f, interval * 2.35f));
            float exactProximity = Mathf.Clamp01(1f - Mathf.Abs(snapshot.CoreDeltaSeconds) / Mathf.Max(0.01f, snapshot.Pattern.GoodWindowSeconds));
            float pressure = Mathf.Max(0f, BuildTrapVariationPressure(snapshot.Pattern));
            return Mathf.Clamp01(
                0.10f
                    + approach * 0.40f
                    + exactProximity * 0.28f
                    + pressure * 0.08f
                    + BuildTargetLanePressureGlowBonus(
                        BuildHealthDangerStrength(snapshot),
                        snapshot.InfiniteMode,
                        snapshot.InfiniteThreatLevel)
                    + BuildTargetLaneBeatCueGlowBonus(BuildActiveBeatCueUrgency(snapshot)));
        }

        private static float BuildTargetLaneBeatCueGlowBonus(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.10f;
        }

        private static float BuildTargetLanePressureGlowBonus(
            float healthDangerStrength,
            bool infiniteMode,
            int infiniteThreatLevel)
        {
            float survivalPressure = Mathf.Clamp01(healthDangerStrength) * 0.14f;
            float infinitePressure = infiniteMode
                ? Mathf.Clamp01((Mathf.Clamp(infiniteThreatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel) - InfiniteThreatUiMinLevel)
                    / (float)(InfiniteThreatUiMaxLevel - InfiniteThreatUiMinLevel)) * 0.10f
                : 0f;
            return Mathf.Clamp01(survivalPressure + infinitePressure);
        }

        private static float BuildLaneTargetGlowBeatPulse(float targetGlow, float beatPulse)
        {
            float readiness = Mathf.Clamp01((Mathf.Clamp01(targetGlow) - 0.18f) / 0.82f);
            return Mathf.Clamp01(readiness * Mathf.Clamp01(beatPulse));
        }

        private static float BuildLaneTargetGlowDownbeatLift(float downbeatPulse, float targetGlow)
        {
            float readiness = Mathf.Lerp(0.38f, 1f, Mathf.Clamp01(targetGlow));
            return Mathf.Clamp01(downbeatPulse) * readiness;
        }

        private static float BuildLaneTargetGlowExactLock(float targetGlow, float beatPulse, float judgementPulse)
        {
            float readiness = Mathf.Clamp01((Mathf.Clamp01(targetGlow) - 0.52f) / 0.48f);
            if (readiness <= 0f)
            {
                return 0f;
            }

            float beatLift = 0.72f + Mathf.Clamp01(beatPulse) * 0.28f;
            float judgementLift = 1f + Mathf.Clamp01(judgementPulse) * 0.08f;
            return Mathf.Clamp01(readiness * beatLift * judgementLift);
        }

        private static int BuildLaneTargetGlowAlpha(float targetGlow, float beatPulse, float judgementPulse)
        {
            float safeGlow = Mathf.Clamp01(targetGlow);
            float pulse = BuildLaneTargetGlowBeatPulse(safeGlow, beatPulse);
            return Mathf.RoundToInt(Mathf.Min(132f, Mathf.Lerp(24f, 96f, safeGlow) + pulse * 18f + Mathf.Clamp01(judgementPulse) * 20f));
        }

        private static int BuildLaneTargetGlowExactLockAlphaLift(float exactLock)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(exactLock) * 22f);
        }

        private static float BuildLaneTargetGlowExactLockColorBlend(float exactLock)
        {
            return Mathf.Clamp01(exactLock) * 0.28f;
        }

        private static int BuildLaneTargetGlowDownbeatAlphaLift(float downbeatLift)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(downbeatLift) * 14f);
        }

        private static float BuildLaneTargetGlowDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.18f;
        }

        private static int BuildLaneTargetGlowUrgencyAlphaLift(float beatCueUrgency)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(beatCueUrgency) * 16f);
        }

        private static float BuildLaneTargetGlowUrgencyColorBlend(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.16f;
        }

        private static float BuildLaneTargetGlowUrgencyScaleXLift(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.010f;
        }

        private static float BuildLaneTargetGlowUrgencyScaleYLift(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.020f;
        }

        private static float BuildLaneTargetGlowScaleX(float targetGlow, float beatPulse, float judgementPulse)
        {
            float safeGlow = Mathf.Clamp01(targetGlow);
            float pulse = BuildLaneTargetGlowBeatPulse(safeGlow, beatPulse);
            return 1f + safeGlow * 0.050f + pulse * 0.032f + Mathf.Clamp01(judgementPulse) * 0.046f;
        }

        private static float BuildLaneTargetGlowScaleY(float targetGlow, float beatPulse, float judgementPulse)
        {
            float safeGlow = Mathf.Clamp01(targetGlow);
            float pulse = BuildLaneTargetGlowBeatPulse(safeGlow, beatPulse);
            return 1f + safeGlow * 0.024f + pulse * 0.052f + Mathf.Clamp01(judgementPulse) * 0.040f;
        }

        private static float BuildLaneTargetGlowScaleXWithExactLock(
            float targetGlow,
            float beatPulse,
            float judgementPulse,
            float exactLock)
        {
            return BuildLaneTargetGlowScaleX(targetGlow, beatPulse, judgementPulse)
                + Mathf.Clamp01(exactLock) * 0.014f;
        }

        private static float BuildLaneTargetGlowScaleYWithExactLock(
            float targetGlow,
            float beatPulse,
            float judgementPulse,
            float exactLock)
        {
            return BuildLaneTargetGlowScaleY(targetGlow, beatPulse, judgementPulse)
                + Mathf.Clamp01(exactLock) * 0.066f;
        }

        private static float BuildLaneTargetGlowDownbeatScaleXLift(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.012f;
        }

        private static float BuildLaneTargetGlowDownbeatScaleYLift(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.034f;
        }

        private float BuildLaneJudgementPulse(int index)
        {
            if (laneJudgementPulseUntil == null || index < 0 || index >= laneJudgementPulseUntil.Length)
            {
                return 0f;
            }

            float remaining = laneJudgementPulseUntil[index] - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            return Mathf.Clamp01(remaining / 0.24f);
        }

        private float BuildLaneMissShake(int index)
        {
            if (laneMissShakeUntil == null || index < 0 || index >= laneMissShakeUntil.Length)
            {
                return 0f;
            }

            float remaining = laneMissShakeUntil[index] - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remaining / LaneMissShakeDuration);
            float age = 1f - normalized;
            return Mathf.Sin(age * Mathf.PI * 8f)
                * normalized
                * LaneMissShakePixels
                * BuildMotionComfortShakeScale(motionComfortEnabled);
        }

        private float BuildBeatMarkerMissImpact()
        {
            float remaining = beatMarkerMissImpactUntil - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remaining / BeatMarkerMissImpactDuration);
            return Mathf.Sin(normalized * Mathf.PI);
        }

        private float BuildBeatMarkerMissShake()
        {
            float remaining = beatMarkerMissImpactUntil - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remaining / BeatMarkerMissImpactDuration);
            float age = 1f - normalized;
            return Mathf.Sin(age * Mathf.PI * 10f)
                * normalized
                * BeatMarkerMissImpactShakePixels
                * BuildMotionComfortShakeScale(motionComfortEnabled);
        }

        private float BuildBeatMarkerFocusGuardImpact()
