        private static float BuildBeatMarkerColorBlend(float impact, float strength)
        {
            return Mathf.Clamp01(impact) * Mathf.Clamp01(strength);
        }

        private static float BuildBeatMarkerBaseScale(float beatPulse)
        {
            return Mathf.Lerp(0.86f, 1.18f, Mathf.Clamp01(beatPulse));
        }

        private static float BuildBeatMarkerSuccessScaleLift(float impact)
        {
            return Mathf.Clamp01(impact) * 0.13f;
        }

        private static float BuildBeatMarkerGoodScaleLift(float impact)
        {
            return Mathf.Clamp01(impact) * 0.075f;
        }

        private static float BuildBeatMarkerComboTierScaleLift(float impact)
        {
            return Mathf.Clamp01(impact) * 0.18f;
        }

        private static float BuildBeatMarkerProfileScaleLift(float impact)
        {
            return Mathf.Clamp01(impact) * 0.13f;
        }

        private static float BuildBeatMarkerDownbeatScaleLift(float impact)
        {
            return Mathf.Clamp01(impact) * 0.075f;
        }

        private void ApplyRunHudBeatPulse(float beatPulse, float downbeatPulse)
        {
            if (runHudText == null)
            {
                return;
            }

            float hudLift = BuildRunHudDownbeatLift(
                hasRunSnapshot ? latestRunSnapshot : default,
                downbeatPulse,
                beatPulse);
            runHudText.color = WithAlpha(
                Color32.Lerp(
                    new Color32(218, 226, 218, 230),
                    new Color32(255, 238, 181, 255),
                    BuildRunHudDownbeatColorBlend(hudLift)),
                BuildRunHudAlphaWithDownbeat(230, hudLift));
            runHudText.rectTransform.localScale = Vector3.one * BuildRunHudScaleWithDownbeat(1f, hudLift);
        }

        private static float BuildRunHudDownbeatLift(
            GreedLastRunSnapshot snapshot,
            float downbeatPulse,
            float beatPulse)
        {
            return BuildRunHudDownbeatLiftFromValues(
                snapshot.ActivePattern,
                snapshot.Pattern.IsValid,
                snapshot.Stopped,
                snapshot.Paused,
                snapshot.CountdownActive,
                snapshot.ChoiceActive,
                snapshot.CoreDeltaSeconds,
                snapshot.Pattern.GoodWindowSeconds,
                snapshot.Pattern.SuccessWindowSeconds,
                snapshot.Health,
                snapshot.InfiniteMode,
                snapshot.InfiniteThreatLevel,
                downbeatPulse,
                beatPulse);
        }

        private static float BuildRunHudDownbeatLiftFromValues(
            bool activePattern,
            bool patternValid,
            bool stopped,
            bool paused,
            bool countdownActive,
            bool choiceActive,
            float coreDeltaSeconds,
            float goodWindowSeconds,
            float successWindowSeconds,
            int health,
            bool infiniteMode,
            int infiniteThreatLevel,
            float downbeatPulse,
            float beatPulse)
        {
            if (!activePattern
                || !patternValid
                || stopped
                || paused
                || countdownActive
                || choiceActive)
            {
                return 0f;
            }

            float readiness = goodWindowSeconds > 0f
                ? 1f - Mathf.Clamp01(Mathf.Abs(coreDeltaSeconds) / goodWindowSeconds)
                : 0f;
            float exactness = successWindowSeconds > 0f
                ? 1f - Mathf.Clamp01(Mathf.Abs(coreDeltaSeconds) / successWindowSeconds)
                : 0f;
            float pressure = Mathf.Max(
                health <= 1 ? 0.16f : 0f,
                infiniteMode ? Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.12f : 0f);
            return Mathf.Clamp01(downbeatPulse)
                * Mathf.Clamp01(0.30f + Mathf.Clamp01(beatPulse) * 0.10f + readiness * 0.36f + exactness * 0.28f + pressure);
        }

        private static float BuildRunHudDownbeatColorBlend(float hudLift)
        {
            return Mathf.Clamp01(hudLift) * 0.38f;
        }

        private static int BuildRunHudAlphaWithDownbeat(int baseAlpha, float hudLift)
        {
            return Mathf.Clamp(baseAlpha + Mathf.RoundToInt(Mathf.Clamp01(hudLift) * 25f), 0, 255);
        }

        private static float BuildRunHudScaleWithDownbeat(float baseScale, float hudLift)
        {
            return Mathf.Max(0f, baseScale) + Mathf.Clamp01(hudLift) * 0.018f;
        }

        private static float BuildBeatMarkerMissScaleLift(float impact)
        {
            return Mathf.Clamp01(impact) * 0.16f;
        }

        private static float BuildBeatMarkerFocusGuardScaleLift(float impact)
        {
            return Mathf.Clamp01(impact) * 0.22f;
        }

        private static float BuildBeatMarkerComboBreakScaleDrop(float impact)
        {
            return Mathf.Clamp01(impact) * 0.075f;
        }

        private static float BuildBeatMarkerScaleWithImpacts(
            float beatPulse,
            float successImpact,
            float goodImpact,
            float comboTierImpact,
            float profileImpact,
            float missImpact,
            float focusGuardImpact,
            float comboBreakImpact)
        {
            return BuildBeatMarkerBaseScale(beatPulse)
                + BuildBeatMarkerSuccessScaleLift(successImpact)
                + BuildBeatMarkerGoodScaleLift(goodImpact)
                + BuildBeatMarkerComboTierScaleLift(comboTierImpact)
                + BuildBeatMarkerProfileScaleLift(profileImpact)
                + BuildBeatMarkerMissScaleLift(missImpact)
                + BuildBeatMarkerFocusGuardScaleLift(focusGuardImpact)
                - BuildBeatMarkerComboBreakScaleDrop(comboBreakImpact);
        }

        private static bool IsLiveRunControlWindow(GreedLastRunSnapshot snapshot)
        {
            return !snapshot.Stopped
                && !snapshot.Paused
                && !snapshot.CountdownActive
                && !snapshot.ChoiceActive;
        }

        private static bool ShouldShowDownbeatPulse(GreedLastRunSnapshot snapshot)
        {
            return IsLiveRunControlWindow(snapshot);
        }

        private static bool ShouldAdvanceRunMotion(GreedLastRunSnapshot snapshot)
        {
            return IsLiveRunControlWindow(snapshot);
        }

        private static bool ShouldPlayLiveBeatClick(GreedLastRunSnapshot snapshot)
        {
            return IsLiveRunControlWindow(snapshot);
        }

        private static float BuildDownbeatPulse(float remainingSeconds)
        {
            if (remainingSeconds <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remainingSeconds / DownbeatPulseDuration);
            return Mathf.Sin(normalized * Mathf.PI);
        }

        private static float BuildDownbeatColorBlend(float impact, float strength)
        {
            return Mathf.Clamp01(impact) * Mathf.Clamp01(strength);
        }

        private void ApplyFocusStateAuraBand()
        {
            if (!hasRunSnapshot
                || !ShouldShowFocusStateTimerPips(latestRunSnapshot)
                || goodTimingBand == null
                || judgementLine == null)
            {
                return;
            }

            float activationImpact = BuildBeatMarkerFocusGuardImpact();
            float livePulse = GetGameplayBeatPulse();
            float urgencyPulse = BuildFocusStateUrgencyPulse(latestRunSnapshot.FocusStateRemainingSeconds, livePulse);
            float focusPulse = Mathf.Max(activationImpact, Mathf.Max(0.32f + livePulse * 0.34f, urgencyPulse));

            float lineY = judgementLine.rectTransform.anchorMin.y;
            float halfHeight = Mathf.Lerp(0.016f, 0.038f, focusPulse) + urgencyPulse * 0.010f;
            RectTransform bandRect = goodTimingBand.rectTransform;
            bandRect.anchorMin = new Vector2(0.10f, Mathf.Clamp01(lineY - halfHeight));
            bandRect.anchorMax = new Vector2(0.90f, Mathf.Clamp01(lineY + halfHeight));
            bandRect.offsetMin = Vector2.zero;
            bandRect.offsetMax = Vector2.zero;
            bandRect.localScale = Vector3.one * (1f + activationImpact * 0.055f + urgencyPulse * 0.07f);
            goodTimingBand.color = new Color32(255, 196, 74, (byte)Mathf.RoundToInt(Mathf.Lerp(24f, 92f, focusPulse) + urgencyPulse * 54f));

            judgementLine.color = Color32.Lerp(judgementLine.color, new Color32(255, 214, 105, 255), focusPulse * (0.44f + urgencyPulse * 0.18f));
            float currentLineScaleY = judgementLine.rectTransform.localScale.y;
            judgementLine.rectTransform.localScale = new Vector3(1f, Mathf.Max(currentLineScaleY, 1f + activationImpact * 0.52f + urgencyPulse * 0.28f), 1f);
        }

        private static float BuildFocusStateUrgencyPulse(float remainingSeconds, float beatPulse)
        {
            if (remainingSeconds <= 0f || remainingSeconds > 1.25f)
            {
                return 0f;
            }

            float urgency = 1f - Mathf.Clamp01(remainingSeconds / 1.25f);
            return Mathf.Clamp01(0.24f + urgency * 0.48f + Mathf.Clamp01(beatPulse) * 0.28f);
        }

        private Color32 GetLaneJudgementPulseColor(int index)
        {
            if (laneJudgementPulseColors == null || index < 0 || index >= laneJudgementPulseColors.Length)
            {
                return new Color32(255, 238, 181, 255);
            }

            return laneJudgementPulseColors[index];
        }

        private void UpdateForwardMotionLines()
        {
            if (runMotionLines == null)
            {
                return;
            }

            bool motionActive = runModeActive
                && hasRunSnapshot
                && ShouldAdvanceRunMotion(latestRunSnapshot);

            if (!motionActive)
            {
                for (int i = 0; i < runMotionLines.Length; i += 1)
                {
                    if (runMotionLines[i] != null)
                    {
                        runMotionLines[i].color = new Color32(104, 151, 142, 0);
                    }
                }

                return;
            }

            float threatStrength = latestRunSnapshot.InfiniteMode
                ? Mathf.Clamp01((latestRunSnapshot.InfiniteThreatLevel - 1) / 4f)
                : 0f;
            float comboStrength = Mathf.Clamp01(latestRunSnapshot.Combo / 12f);
            float forwardPulse = BuildForwardPayoffBurstPulse(forwardPayoffBurstUntil - Time.unscaledTime, forwardPayoffBurstStrength);
            float stageMotionScale = BuildStageMotionScale(latestRunSnapshot);
            float stageDepthScale = BuildStageDepthScale(latestRunSnapshot);
            float speedBias = BuildForwardMotionSpeedBias(latestRunSnapshot, comboStrength, forwardPulse);
            float recoveryPressure = BuildMissRecoveryMotionPressure(latestRunSnapshot);
            float lineSurge = BuildForwardMotionLineResultSurge(
                latestRunSnapshot.LastResult,
                forwardPulse,
                latestRunSnapshot.FocusStateActive,
                comboStrength);
            float lineDrag = BuildForwardMotionLineDrag(latestRunSnapshot.LastResult, recoveryPressure);
            float rotationDirection = BuildRotationPatternDirection(latestRunSnapshot.Pattern);
            float rotationReadiness = latestRunSnapshot.ActivePattern
                && latestRunSnapshot.Pattern.IsValid
                && GreedLastRunCore.IsRotationPattern(latestRunSnapshot.Pattern)
                    ? BuildStraightRunRotationReadiness(latestRunSnapshot)
                    : 0f;
            float downbeatPulse = ShouldShowDownbeatPulse(latestRunSnapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;
            float beatCueUrgency = BuildActiveBeatCueUrgency(latestRunSnapshot);
            Color32 baseColor = BuildRunAtmosphereAccent(latestRunSnapshot);
            if (IsVisibleChoiceProfile(latestRunSnapshot.ActiveChoiceProfile))
            {
                baseColor = Color32.Lerp(
                    baseColor,
                    GetChoiceProfilePulseColor(latestRunSnapshot.ActiveChoiceProfile),
                    0.20f);
            }

            for (int i = 0; i < runMotionLines.Length; i += 1)
            {
                Image line = runMotionLines[i];
                if (line == null)
                {
                    continue;
                }

                float phase = Mathf.Repeat(
                    beatPhase * (0.46f + threatStrength * 0.2f) * speedBias * stageMotionScale
                        + i / (float)runMotionLines.Length,
                    1f);
                float downbeatLift = BuildForwardMotionLineDownbeatLift(
                    downbeatPulse,
                    latestRunSnapshot.ActivePattern,
                    latestRunSnapshot.CoreDeltaSeconds,
                    latestRunSnapshot.Pattern.IsValid ? latestRunSnapshot.Pattern.GoodWindowSeconds : 0f,
                    phase,
                    i);
                float lineBeatCueUrgency = BuildForwardMotionLineBeatCueUrgency(beatCueUrgency, phase, i);
                float y = Mathf.Lerp(0.86f, 0.20f, phase);
                float rotationDrift = BuildForwardMotionLineRotationDrift(rotationDirection, rotationReadiness, phase, i);
                float halfWidth = Mathf.Min(
                    0.49f,
                    Mathf.Lerp(0.035f, 0.42f, phase)
                        * stageDepthScale
                        * (1f + forwardPulse * 0.08f)
                        * BuildForwardMotionLineWidthScale(lineSurge, lineDrag, i)
                        * BuildForwardMotionLineDownbeatWidthScale(downbeatLift)
                        * BuildForwardMotionLineBeatCueUrgencyWidthScale(lineBeatCueUrgency)
                        * BuildForwardMotionLineRotationWidthScale(rotationReadiness, phase, i));
                RectTransform rect = line.rectTransform;
                rect.anchorMin = new Vector2(Mathf.Clamp01(0.5f + rotationDrift - halfWidth), y);
                rect.anchorMax = new Vector2(Mathf.Clamp01(0.5f + rotationDrift + halfWidth), y);
                rect.sizeDelta = new Vector2(
                    0f,
                    Mathf.Lerp(3f, 15f + comboStrength * 6f, phase)
                        * stageDepthScale
                        * (1f + forwardPulse * 0.34f)
                        * BuildForwardMotionLineHeightScale(lineSurge, lineDrag, i)
                        * BuildForwardMotionLineDownbeatHeightScale(downbeatLift)
                        * BuildForwardMotionLineBeatCueUrgencyHeightScale(lineBeatCueUrgency)
                        * BuildForwardMotionLineRotationHeightScale(rotationReadiness, phase, i));
                rect.anchoredPosition = Vector2.zero;
                rect.localEulerAngles = new Vector3(
                    0f,
                    0f,
                    BuildForwardMotionLineRotationAngle(rotationDirection, rotationReadiness, phase, i));

                int alpha = Mathf.RoundToInt(Mathf.Lerp(18f, 82f + threatStrength * 32f, phase) * Mathf.Lerp(0.72f, 1.08f, Mathf.Sin((beatPhase + phase) * Mathf.PI * 2f) * 0.5f + 0.5f));
                int lineAlphaLift = BuildForwardMotionLineAlphaLift(lineSurge, lineDrag, i);
                Color32 lineColor = baseColor;
                if (forwardPulse > 0f)
                {
                    alpha = Mathf.RoundToInt(alpha * Mathf.Lerp(1f, 1.54f, forwardPulse));
                    lineColor = Color32.Lerp(lineColor, new Color32(255, 238, 181, 255), forwardPulse * 0.38f);
                }
                if (latestRunSnapshot.FocusStateActive)
                {
                    alpha = Mathf.RoundToInt(alpha * 1.22f);
                    lineColor = Color32.Lerp(lineColor, new Color32(255, 196, 74, 255), 0.18f);
                }
                if (comboStrength > 0f)
                {
                    alpha = Mathf.RoundToInt(alpha * Mathf.Lerp(1f, 1.28f, comboStrength));
                    lineColor = Color32.Lerp(lineColor, new Color32(255, 214, 105, 255), comboStrength * 0.22f);
                }
                if (lineSurge > 0f)
                {
                    alpha += lineAlphaLift;
                    lineColor = Color32.Lerp(
                        lineColor,
                        new Color32(255, 248, 210, 255),
                        BuildForwardMotionLineColorBlend(lineSurge, lineDrag, i));
                }
                if (downbeatLift > 0f)
                {
                    alpha += BuildForwardMotionLineDownbeatAlphaLift(downbeatLift);
                    lineColor = Color32.Lerp(
                        lineColor,
                        new Color32(255, 214, 105, 255),
                        BuildForwardMotionLineDownbeatColorBlend(downbeatLift));
                }
                if (lineBeatCueUrgency > 0f)
                {
                    alpha += BuildForwardMotionLineBeatCueUrgencyAlphaLift(lineBeatCueUrgency);
                    lineColor = Color32.Lerp(
                        lineColor,
                        new Color32(255, 238, 181, 255),
                        BuildForwardMotionLineBeatCueUrgencyColorBlend(lineBeatCueUrgency));
                }
                if (rotationReadiness > 0f)
                {
                    alpha += BuildForwardMotionLineRotationAlphaLift(rotationReadiness, phase, i);
                    lineColor = Color32.Lerp(
                        lineColor,
                        PrototypeGoldColor,
                        BuildForwardMotionLineRotationColorBlend(rotationReadiness, phase, i));
                }
                if (recoveryPressure > 0f)
                {
                    lineColor = BuildMissRecoveryMotionTint(lineColor, recoveryPressure, 0.36f);
                    alpha = BuildMissRecoveryMotionAlpha(alpha, recoveryPressure, 0.20f);
                }
                line.color = WithAlpha(lineColor, alpha);
            }
        }

        private static float BuildForwardMotionLineResultSurge(
            GreedLastJudgementResult result,
            float forwardPulse,
            bool focusActive,
            float comboStrength)
        {
            if (forwardPulse <= 0f
                || result == GreedLastJudgementResult.None
                || result == GreedLastJudgementResult.Miss)
            {
                return 0f;
            }

            float resultWeight = result == GreedLastJudgementResult.Success ? 1f : 0.58f;
            float focusLift = focusActive ? 0.08f : 0f;
            float comboLift = Mathf.Clamp01(comboStrength) * 0.12f;
            return Mathf.Clamp01(Mathf.Clamp01(forwardPulse) * (resultWeight + focusLift + comboLift));
        }

        private static float BuildForwardMotionLineDrag(GreedLastJudgementResult result, float recoveryPressure)
        {
            if (recoveryPressure <= 0f)
            {
                return 0f;
            }

            float resultWeight = result == GreedLastJudgementResult.Miss ? 1f : 0.48f;
            return Mathf.Clamp01(Mathf.Clamp01(recoveryPressure) * resultWeight);
        }

        private static float BuildForwardMotionLineWidthScale(float resultSurge, float dragStrength, int lineIndex)
        {
            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float lineFalloff = 1f - safeIndex * 0.028f;
            return 1f
                + Mathf.Clamp01(resultSurge) * Mathf.Clamp(lineFalloff, 0.72f, 1f) * 0.09f
                + Mathf.Clamp01(dragStrength) * 0.12f;
        }

        private static float BuildForwardMotionLineHeightScale(float resultSurge, float dragStrength, int lineIndex)
        {
            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float lineLift = 1f - safeIndex * 0.018f;
            return Mathf.Clamp(
                1f
                    + Mathf.Clamp01(resultSurge) * Mathf.Clamp(lineLift, 0.78f, 1f) * 0.20f
                    - Mathf.Clamp01(dragStrength) * 0.11f,
                0.78f,
                1.24f);
        }

        private static int BuildForwardMotionLineAlphaLift(float resultSurge, float dragStrength, int lineIndex)
        {
            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float lineFalloff = 1f - safeIndex * 0.035f;
            return Mathf.RoundToInt(
                Mathf.Clamp01(resultSurge) * Mathf.Clamp(lineFalloff, 0.70f, 1f) * 26f
                    + Mathf.Clamp01(dragStrength) * 10f);
        }

        private static float BuildForwardMotionLineColorBlend(float resultSurge, float dragStrength, int lineIndex)
        {
            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float lineFalloff = 1f - safeIndex * 0.035f;
            return Mathf.Clamp01(
                Mathf.Clamp01(resultSurge) * Mathf.Clamp(lineFalloff, 0.70f, 1f) * 0.30f
                    - Mathf.Clamp01(dragStrength) * 0.08f);
        }

        private static float BuildForwardMotionLineDownbeatLift(
            float downbeatPulse,
            bool activePattern,
            float coreDeltaSeconds,
            float goodWindowSeconds,
            float linePhase,
            int lineIndex)
        {
            if (!activePattern)
            {
                return 0f;
            }

            float goodWindow = Mathf.Max(0.01f, goodWindowSeconds);
            float coreReadiness = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / Mathf.Max(0.18f, goodWindow * 2.4f));
            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float indexFalloff = Mathf.Clamp(1f - safeIndex * 0.030f, 0.72f, 1f);
            float depthWeight = Mathf.Lerp(0.40f, 1f, Mathf.Clamp01(linePhase));
            return Mathf.Clamp01(downbeatPulse) * Mathf.Lerp(0.42f, 1f, coreReadiness) * depthWeight * indexFalloff;
        }

        private static float BuildForwardMotionLineDownbeatWidthScale(float downbeatLift)
        {
            return 1f + Mathf.Clamp01(downbeatLift) * 0.045f;
        }

        private static float BuildForwardMotionLineDownbeatHeightScale(float downbeatLift)
        {
            return 1f + Mathf.Clamp01(downbeatLift) * 0.080f;
        }

        private static int BuildForwardMotionLineDownbeatAlphaLift(float downbeatLift)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(downbeatLift) * 18f);
        }

        private static float BuildForwardMotionLineDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.22f;
        }

        private static float BuildForwardMotionLineBeatCueUrgency(float beatCueUrgency, float linePhase, int lineIndex)
        {
            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float indexFalloff = Mathf.Clamp(1f - safeIndex * 0.026f, 0.74f, 1f);
            float depthWeight = Mathf.Lerp(0.50f, 1f, Mathf.Clamp01(linePhase));
            return Mathf.Clamp01(beatCueUrgency) * depthWeight * indexFalloff;
        }

        private static float BuildForwardMotionLineBeatCueUrgencyWidthScale(float lineBeatCueUrgency)
        {
            return 1f + Mathf.Clamp01(lineBeatCueUrgency) * 0.028f;
        }

        private static float BuildForwardMotionLineBeatCueUrgencyHeightScale(float lineBeatCueUrgency)
        {
            return 1f + Mathf.Clamp01(lineBeatCueUrgency) * 0.044f;
        }

        private static int BuildForwardMotionLineBeatCueUrgencyAlphaLift(float lineBeatCueUrgency)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(lineBeatCueUrgency) * 10f);
        }

        private static float BuildForwardMotionLineBeatCueUrgencyColorBlend(float lineBeatCueUrgency)
        {
            return Mathf.Clamp01(lineBeatCueUrgency) * 0.13f;
        }

        private static float BuildForwardMotionLineRotationDrift(
            float rotationDirection,
            float rotationReadiness,
            float linePhase,
            int lineIndex)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float indexFalloff = Mathf.Clamp(1f - safeIndex * 0.032f, 0.72f, 1f);
            float depthWeight = Mathf.Lerp(0.35f, 1f, Mathf.Clamp01(linePhase));
            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * depthWeight * indexFalloff * 0.026f;
        }

        private static float BuildForwardMotionLineRotationAngle(
            float rotationDirection,
            float rotationReadiness,
            float linePhase,
            int lineIndex)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float indexFalloff = Mathf.Clamp(1f - safeIndex * 0.026f, 0.76f, 1f);
            float depthWeight = Mathf.Lerp(0.45f, 1f, Mathf.Clamp01(linePhase));
            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * depthWeight * indexFalloff * 4.2f;
        }

        private static float BuildForwardMotionLineRotationWidthScale(float rotationReadiness, float linePhase, int lineIndex)
        {
            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float indexFalloff = Mathf.Clamp(1f - safeIndex * 0.020f, 0.80f, 1f);
            float depthWeight = Mathf.Lerp(0.35f, 1f, Mathf.Clamp01(linePhase));
            return 1f + Mathf.Clamp01(rotationReadiness) * depthWeight * indexFalloff * 0.050f;
        }

        private static float BuildForwardMotionLineRotationHeightScale(float rotationReadiness, float linePhase, int lineIndex)
        {
            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float indexFalloff = Mathf.Clamp(1f - safeIndex * 0.024f, 0.78f, 1f);
            float depthWeight = Mathf.Lerp(0.42f, 1f, Mathf.Clamp01(linePhase));
            return 1f + Mathf.Clamp01(rotationReadiness) * depthWeight * indexFalloff * 0.075f;
        }

        private static int BuildForwardMotionLineRotationAlphaLift(float rotationReadiness, float linePhase, int lineIndex)
        {
            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float indexFalloff = Mathf.Clamp(1f - safeIndex * 0.030f, 0.72f, 1f);
            float depthWeight = Mathf.Lerp(0.40f, 1f, Mathf.Clamp01(linePhase));
            return Mathf.RoundToInt(Mathf.Clamp01(rotationReadiness) * depthWeight * indexFalloff * 14f);
        }

        private static float BuildForwardMotionLineRotationColorBlend(float rotationReadiness, float linePhase, int lineIndex)
        {
            int safeIndex = Mathf.Clamp(lineIndex, 0, 8);
            float indexFalloff = Mathf.Clamp(1f - safeIndex * 0.030f, 0.74f, 1f);
            float depthWeight = Mathf.Lerp(0.45f, 1f, Mathf.Clamp01(linePhase));
            return Mathf.Clamp01(rotationReadiness) * depthWeight * indexFalloff * 0.18f;
        }

        private void TrackChoiceConfirmation(
            bool hadPreviousSnapshot,
            GreedLastRunSnapshot previousSnapshot,
            GreedLastRunSnapshot snapshot)
        {
            if (!ShouldStartChoiceConfirmation(hadPreviousSnapshot, previousSnapshot, snapshot))
            {
                return;
            }

            int laneIndex = ResolveChoiceConfirmationLaneIndex(previousSnapshot, snapshot.JudgementText);
            if (laneIndex < 0 || laneIndex >= 3)
            {
                return;
            }

            choiceConfirmationLaneIndex = laneIndex;
            choiceConfirmationUntil = Time.unscaledTime + ChoiceConfirmationDuration;
            choiceConfirmationCountdownBeatNotBefore = snapshot.ChoiceActive
                ? 0f
                : Time.unscaledTime + BuildChoiceConfirmationCountdownBeatDelay(snapshot.ChoiceActive);
            choiceConfirmationColor = GetChoiceProfilePulseColor(snapshot.ActiveChoiceProfile);
            if (laneInputRippleUntil != null && laneIndex < laneInputRippleUntil.Length)
            {
                laneInputRippleUntil[laneIndex] = Mathf.Max(
                    laneInputRippleUntil[laneIndex],
                    choiceConfirmationUntil);
            }

            if (lanePressPulseUntil != null && laneIndex < lanePressPulseUntil.Length)
            {
                lanePressPulseUntil[laneIndex] = Mathf.Max(
                    lanePressPulseUntil[laneIndex],
                    Time.unscaledTime + 0.20f);
            }

            if (laneCueClips != null && laneIndex < laneCueClips.Length)
            {
                PlayClip(
                    laneCueClips[laneIndex],
                    BuildChoiceConfirmationLaneVolume(laneIndex, snapshot.ChoiceActive));
            }

            PlayClip(choiceConfirmationClip, BuildChoiceConfirmationAccentVolume(snapshot.ChoiceActive));
            PlayHaptic(BuildChoiceConfirmationHapticDuration(snapshot.ChoiceActive));
        }

        private static bool ShouldStartChoiceConfirmation(
            bool hadPreviousSnapshot,
            GreedLastRunSnapshot previousSnapshot,
            GreedLastRunSnapshot snapshot)
        {
            if (!hadPreviousSnapshot
                || !previousSnapshot.ChoiceActive
                || snapshot.Stopped
                || snapshot.Paused)
            {
                return false;
            }

            bool advancedToNextChoice = snapshot.ChoiceActive
                && snapshot.ChoiceKind != GreedLastChoiceKind.None
                && snapshot.ChoiceKind != previousSnapshot.ChoiceKind;
            bool committedIntoCountdown = !snapshot.ChoiceActive && snapshot.StartCountdownActive;
            return advancedToNextChoice || committedIntoCountdown;
        }

        private static int ResolveChoiceConfirmationLaneIndex(
            GreedLastRunSnapshot previousSnapshot,
            string judgementText)
        {
            if (!previousSnapshot.ChoiceActive || string.IsNullOrWhiteSpace(judgementText))
            {
                return -1;
            }

            string normalized = judgementText.Replace("\r", string.Empty).TrimStart();
            string[] options =
            {
                previousSnapshot.ChoiceLeft,
                previousSnapshot.ChoiceCenter,
                previousSnapshot.ChoiceRight,
            };
            for (int i = 0; i < options.Length; i += 1)
            {
                string option = options[i];
                if (!string.IsNullOrWhiteSpace(option)
                    && normalized.StartsWith(option.Trim() + " 선택", StringComparison.Ordinal))
                {
                    return i;
                }
            }

            return -1;
        }

        private static float BuildChoiceConfirmationPulse(
            int laneIndex,
            int selectedLaneIndex,
            float remainingSeconds)
        {
            if (laneIndex < 0
                || laneIndex != selectedLaneIndex
                || remainingSeconds <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remainingSeconds / ChoiceConfirmationDuration);
            return Mathf.Pow(normalized, 0.72f);
        }

        private static bool ShouldShowChoiceConfirmationRipple(float confirmationPulse)
        {
            return confirmationPulse > 0f;
        }

        private static float BuildChoiceConfirmationColorBlend(float confirmationPulse)
        {
            return Mathf.Clamp01(confirmationPulse) * 0.68f;
        }

        private static float BuildChoiceConfirmationLabelColorBlend(float confirmationPulse)
        {
            return Mathf.Clamp01(confirmationPulse) * 0.82f;
        }

        private static float BuildChoiceConfirmationLabelScaleLift(float confirmationPulse)
        {
            return Mathf.Clamp01(confirmationPulse) * 0.085f;
        }

        private static float BuildChoiceConfirmationLaneVolume(int laneIndex, bool continuesToAnotherChoice)
        {
            if (laneIndex < 0 || laneIndex > 2)
            {
                return 0f;
            }

            float laneLift = laneIndex * 0.012f;
            return Mathf.Clamp(0.25f + laneLift + (continuesToAnotherChoice ? 0f : 0.018f), 0.20f, 0.31f);
        }

        private static float BuildChoiceConfirmationAccentVolume(bool continuesToAnotherChoice)
        {
            return continuesToAnotherChoice ? 0.24f : 0.29f;
        }

        private static float BuildChoiceConfirmationHapticDuration(bool continuesToAnotherChoice)
        {
            return continuesToAnotherChoice ? 0.018f : 0.026f;
        }

        private static float BuildChoiceConfirmationCountdownBeatDelay(bool continuesToAnotherChoice)
        {
            return continuesToAnotherChoice ? 0f : ChoiceConfirmationCountdownLeadSeconds;
        }

        private static float BuildCountdownBeatScheduleStartTime(float now, float notBefore)
        {
            return Mathf.Max(now, notBefore);
        }

        private static float BuildNextBeatScheduleTime(float scheduledAt, float now, float interval)
        {
            float safeInterval = Mathf.Clamp(interval, 0.08f, 2f);
            if (scheduledAt <= 0f)
            {
                return now + safeInterval;
            }

            float next = scheduledAt + safeInterval;
            if (next > now)
            {
                return next;
            }

            int skippedIntervals = Mathf.FloorToInt((now - next) / safeInterval) + 1;
            if (skippedIntervals > 1)
            {
                return now + safeInterval;
            }

            return next + safeInterval;
        }

        private void TrackStagePresentation(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped)
            {
                lastPresentedRunWasStopped = true;
                stageTransitionCuePending = false;
                return;
            }

            if (lastPresentedRunWasStopped)
            {
                lastStagePresentationKey = string.Empty;
                rhythmBeatIndex = 0;
                downbeatPulseUntil = 0f;
            }

            lastPresentedRunWasStopped = false;
            if (!ShouldTrackStagePresentation(snapshot))
            {
                return;
            }

            string stageKey = BuildStagePresentationKey(snapshot);
            if (string.IsNullOrEmpty(stageKey)
                || string.Equals(stageKey, lastStagePresentationKey, StringComparison.Ordinal))
            {
                return;
            }

            lastStagePresentationKey = stageKey;
            string banner = BuildStagePresentationText(snapshot);
            if (string.IsNullOrEmpty(banner) || stageTransitionText == null)
            {
                return;
            }

            stageTransitionText.text = banner;
            stageTransitionColor = BuildRunAtmosphereAccent(snapshot);
            float now = Time.unscaledTime;
            stageTransitionStartedAt = now + BuildStageTransitionStartDelay(choiceConfirmationUntil - now);
            stageTransitionUntil = stageTransitionStartedAt + StageTransitionBannerDuration;
            stageTransitionCuePending = true;
            stageTransitionCueEscape = snapshot.Phase == GreedLastRunPhase.EscapeRunning;
        }

        private static float BuildStageTransitionStartDelay(float choiceConfirmationRemainingSeconds)
        {
            return choiceConfirmationRemainingSeconds > 0f ? StageTransitionAfterChoiceDelay : 0f;
        }

        private static bool ShouldPlayStageTransitionCue(
            bool cuePending,
            bool presentationVisible,
            float now,
            float presentationStartedAt)
        {
            return cuePending
                && presentationVisible
                && now >= presentationStartedAt;
        }

        private static bool ShouldTrackStagePresentation(GreedLastRunSnapshot snapshot)
        {
            return !snapshot.Stopped
                && !snapshot.Paused
                && !snapshot.ChoiceActive;
        }

        private static string BuildStagePresentationKey(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.PracticeMode)
            {
                return snapshot.Stopped ? string.Empty : "practice";
            }

            if (snapshot.InfiniteMode)
            {
                return "infinite_" + Mathf.Max(1, snapshot.InfiniteThreatLevel);
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                return "escape";
            }

            if (snapshot.Phase == GreedLastRunPhase.ClearResolving
                || snapshot.Phase == GreedLastRunPhase.FailResolving)
            {
                return string.Empty;
            }

            string chapterKey = "chapter_" + Mathf.Clamp(snapshot.ChapterIndex, 1, 4);
            return snapshot.ChapterIndex == 3 && !string.IsNullOrEmpty(snapshot.ActiveRelic)
                ? chapterKey + "_" + snapshot.ActiveRelic
                : chapterKey;
        }

        private static string BuildStagePresentationText(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.PracticeMode)
            {
                return "기초 연습  ·  3축 대응";
            }

            if (snapshot.InfiniteMode)
            {
                int threatLevel = Mathf.Clamp(snapshot.InfiniteThreatLevel, InfiniteThreatUiMinLevel, InfiniteThreatUiMaxLevel);
                return "무한 위협 " + threatLevel
                    + "  ·  " + BuildInfiniteThreatReadPressureLabel(threatLevel)
                    + "  ·  폭 " + BuildInfiniteThreatDangerWidthLabel(threatLevel);
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                return "공명핵 회수  ·  탈출 시작";
            }

            switch (Mathf.Clamp(snapshot.ChapterIndex, 1, 4))
            {
                case 1:
                    return "CHAPTER 1  ·  신호의 회랑";
                case 2:
                    return "CHAPTER 2  ·  압박의 축";
                case 3:
                    return string.IsNullOrEmpty(snapshot.ActiveRelic)
                        ? "CHAPTER 3  ·  연쇄의 심부"
                        : "CHAPTER 3  ·  " + snapshot.ActiveRelic + " 증폭";
                default:
                    return "CHAPTER 4  ·  왕의 핵실";
            }
        }

        private void UpdateStageTransitionBanner()
        {
            if (stageTransitionText == null || stageTransitionLine == null)
            {
                return;
            }

            float now = Time.unscaledTime;
            float remaining = stageTransitionUntil - now;
            bool presentationVisible = runModeActive
                && hasRunSnapshot
                && ShouldShowStageTransitionBanner(latestRunSnapshot);
            if (!presentationVisible || remaining <= 0f)
            {
                if (hasRunSnapshot
                    && ShouldRearmStagePresentationAfterInterruption(
                        latestRunSnapshot,
                        remaining,
                        stageTransitionCuePending))
                {
                    lastStagePresentationKey = string.Empty;
                    stageTransitionUntil = 0f;
                }

                stageTransitionCuePending = false;
                stageTransitionText.color = new Color32(255, 238, 181, 0);
                stageTransitionLine.color = new Color32(255, 238, 181, 0);
                if (detailText != null)
                {
                    detailText.color = WithAlpha(detailText.color, 255);
                }

                return;
            }

            if (ShouldPlayStageTransitionCue(
                    stageTransitionCuePending,
                    presentationVisible,
                    now,
                    stageTransitionStartedAt))
            {
                stageTransitionCuePending = false;
                PlayClip(stageTransitionClip, stageTransitionCueEscape ? 0.34f : 0.25f);
                PlayHaptic(stageTransitionCueEscape ? 0.055f : 0.028f);
            }

            float age = Mathf.Max(0f, now - stageTransitionStartedAt);
            float fadeIn = BuildStageTransitionFadeIn(age);
            float visibility = BuildStageTransitionVisibility(age, remaining);
            if ((!DevToolsEnabled || devCleanViewEnabled) && latestRunSnapshot.PracticeMode)
            {
                visibility = 0f;
            }
            if (detailText != null)
            {
                detailText.color = WithAlpha(detailText.color, BuildStageTransitionDetailAlpha(visibility));
            }

            Color32 textColor = Color32.Lerp(new Color32(237, 239, 231, 255), stageTransitionColor, 0.58f);
            textColor.a = (byte)Mathf.RoundToInt(255f * visibility);
            stageTransitionText.color = textColor;
            stageTransitionText.rectTransform.localScale = Vector3.one * BuildStageTransitionTextScale(age);

            Color32 lineColor = stageTransitionColor;
            lineColor.a = (byte)Mathf.RoundToInt(210f * visibility);
            stageTransitionLine.color = lineColor;
            stageTransitionLine.rectTransform.localScale = new Vector3(BuildStageTransitionLineScaleX(fadeIn), 1f, 1f);
        }

        private static float BuildStageTransitionFadeIn(float ageSeconds)
        {
            return Mathf.Clamp01(ageSeconds / 0.16f);
        }

        private static float BuildStageTransitionFadeOut(float remainingSeconds)
        {
            return Mathf.Clamp01(remainingSeconds / 0.32f);
        }

        private static float BuildStageTransitionVisibility(float ageSeconds, float remainingSeconds)
        {
            return Mathf.Min(BuildStageTransitionFadeIn(ageSeconds), BuildStageTransitionFadeOut(remainingSeconds));
        }

        private static float BuildStageTransitionTextScale(float ageSeconds)
        {
            return Mathf.Lerp(1.08f, 1f, Mathf.Clamp01(ageSeconds / 0.28f));
        }

        private static float BuildStageTransitionLineScaleX(float fadeIn)
        {
            return Mathf.Lerp(0.35f, 1f, Mathf.Clamp01(fadeIn));
        }

        private static int BuildStageTransitionDetailAlpha(float transitionVisibility)
        {
            return Mathf.RoundToInt(255f * (1f - Mathf.Clamp01(transitionVisibility) * 0.95f));
        }

        private static bool ShouldRearmStagePresentationAfterInterruption(
            GreedLastRunSnapshot snapshot,
            float remainingSeconds,
            bool cuePending)
        {
            return remainingSeconds > 0f
                && cuePending
                && !snapshot.Stopped
                && (snapshot.Paused || snapshot.ChoiceActive);
        }

        private static bool ShouldShowStageTransitionBanner(GreedLastRunSnapshot snapshot)
        {
            return !snapshot.Stopped
                && !snapshot.Paused
                && !snapshot.ChoiceActive;
        }

        private void UpdateRhythmBeatSchedule()
        {
            bool countdownBeatActive = runModeActive && BuildCountdownBeatActive(latestRunSnapshot);
            bool launchReleaseStarted = ShouldStartStraightRunLaunchRelease(
                lastCountdownBeatActive,
                countdownBeatActive,
                runModeActive,
                IsLiveRunControlWindow(latestRunSnapshot));
            if (launchReleaseStarted)
            {
                straightRunLaunchReleaseStartedAt = Time.unscaledTime;
                straightRunLaunchReleaseUntil = Time.unscaledTime + StraightRunLaunchReleaseDuration;
                straightRunLaunchReleaseWasResume = lastCountdownWasResume;
                runEntryTrapRevealPending = ShouldQueueRunEntryTrapReveal(
                    true,
                    lastCountdownWasResume,
                    latestRunSnapshot.SuccessCount,
                    latestRunSnapshot.GoodCount,
                    latestRunSnapshot.MissCount);
                PlayRhythmPulse(
                    latestRunSnapshot,
                    BuildStraightRunLaunchCueVolume(
                        true,
                        lastCountdownWasResume,
                        latestRunSnapshot.ActivePattern,
                        latestRunSnapshot.InfiniteMode,
                        latestRunSnapshot.InfiniteThreatLevel));
                PlayHaptic(BuildStraightRunLaunchHapticDuration(
                    true,
                    lastCountdownWasResume,
                    latestRunSnapshot.ActivePattern,
                    latestRunSnapshot.InfiniteMode,
                    latestRunSnapshot.InfiniteThreatLevel));
                nextBeatSoundAt = Time.unscaledTime + BuildBeatInterval(latestRunSnapshot);
            }
            if (ShouldResetCountdownBeatSchedule(lastCountdownBeatActive, countdownBeatActive))
            {
                nextBeatSoundAt = BuildCountdownBeatScheduleStartTime(
                    Time.unscaledTime,
                    choiceConfirmationCountdownBeatNotBefore);
                rhythmBeatIndex = 0;
            }
            if (countdownBeatActive) lastCountdownWasResume = latestRunSnapshot.ResumeCountdownActive;
            lastCountdownBeatActive = countdownBeatActive;

            if (countdownBeatActive && Time.unscaledTime >= nextBeatSoundAt)
            {
                nextBeatSoundAt = BuildNextBeatScheduleTime(nextBeatSoundAt, Time.unscaledTime, BuildBeatInterval(latestRunSnapshot));
                PlayRhythmPulse(latestRunSnapshot, BuildCountdownBeatVolume(latestRunSnapshot));
            }
            else if (runModeActive && ShouldPlayLiveBeatClick(latestRunSnapshot) && Time.unscaledTime >= nextBeatSoundAt)
            {
                nextBeatSoundAt = BuildNextBeatScheduleTime(nextBeatSoundAt, Time.unscaledTime, BuildBeatInterval(latestRunSnapshot));
                PlayRhythmPulse(latestRunSnapshot, BuildBeatClickVolume(latestRunSnapshot));
            }
        }

        private float GetGameplayBeatPulse()
        {
            if (!runModeActive || !hasRunSnapshot || rhythmPulseStartedAt < 0f
                || (!BuildCountdownBeatActive(latestRunSnapshot) && !ShouldPlayLiveBeatClick(latestRunSnapshot))) return 0f;
            return BuildSynchronizedBeatPulse(Time.unscaledTime - rhythmPulseStartedAt, rhythmPulseInterval);
        }

        private static float BuildSynchronizedBeatPulse(float elapsed, float interval)
        {
            if (elapsed < 0f || interval <= 0f) return 0f;
            float duration = Mathf.Min(0.18f, interval * 0.45f);
            float remaining = 1f - Mathf.Clamp01(elapsed / duration);
            return remaining * remaining * (3f - 2f * remaining);
        }

        private void PlayRhythmPulse(GreedLastRunSnapshot snapshot, float volume)
        {
            // Shared event timing keeps visual beats available even when sound is muted.
            rhythmPulseStartedAt = Time.unscaledTime;
            rhythmPulseInterval = BuildBeatInterval(snapshot);
            bool downbeat = rhythmBeatIndex % 4 == 0;
            PlayClip(beatClip, volume);
            if (BuildCountdownBeatActive(snapshot))
            {
                PlayHaptic(BuildCountdownBeatHapticDuration(snapshot));
            }

            if (downbeat)
            {
                downbeatPulseUntil = Time.unscaledTime + DownbeatPulseDuration;
                float downbeatVolume = snapshot.Phase == GreedLastRunPhase.EscapeRunning ? 0.18f : 0.14f;
                PlayClip(downbeatClip, downbeatVolume);
            }

            if (snapshot.FocusStateActive && rhythmBeatIndex % 2 == 0)
            {
                PlayClip(focusBeatClip, downbeat ? 0.13f : 0.085f);
            }

            rhythmBeatIndex += 1;
        }

        private void UpdateRunAtmosphere()
        {
            if (rootBackground == null)
            {
                return;
            }

            Color32 target = runModeActive && hasRunSnapshot
                ? BuildRunAtmosphereBackground(latestRunSnapshot)
                : new Color32(11, 16, 18, 255);
            rootBackground.color = Color.Lerp(
                rootBackground.color,
                target,
                1f - Mathf.Exp(-Time.unscaledDeltaTime * 3.4f));
        }

        private void CreatePrototypeEntranceBackdrop(Transform parent)
        {
            prototypeEntranceTitleTexture = Resources.Load<Texture2D>("GreedLast/PrototypeEntrance");
            prototypeLobbyTexture = Resources.Load<Texture2D>("GreedLast/PrototypeLobby");
            Texture2D texture = prototypeEntranceTitleTexture != null
                ? prototypeEntranceTitleTexture
                : prototypeLobbyTexture;
            if (texture == null)
            {
                return;
            }

            GameObject backdropObject = CreateRect(
                "PrototypeEntranceBackdrop",
                parent,
                Vector2.zero,
                Vector2.one,
                Vector2.zero,
                Vector2.zero);
            prototypeEntranceBackdrop = backdropObject.AddComponent<RawImage>();
            prototypeEntranceBackdrop.texture = texture;
            prototypeEntranceBackdrop.color = new Color32(150, 158, 154, 255);
            prototypeEntranceBackdrop.raycastTarget = false;

            AspectRatioFitter fitter = backdropObject.AddComponent<AspectRatioFitter>();
            fitter.aspectMode = AspectRatioFitter.AspectMode.EnvelopeParent;
            fitter.aspectRatio = texture.height > 0 ? (float)texture.width / texture.height : 16f / 9f;

            prototypeEntranceBackdropCanvasGroup = backdropObject.AddComponent<CanvasGroup>();
            prototypeEntranceBackdropCanvasGroup.alpha = 0f;
            prototypeEntranceBackdropCanvasGroup.interactable = false;
            prototypeEntranceBackdropCanvasGroup.blocksRaycasts = false;
            prototypeEntranceBackdropState = GreedLastScreenState.BootInit;
            backdropObject.SetActive(false);
        }

        private void SetPrototypeEntranceBackdropState(GreedLastScreenState state)
        {
            prototypeEntranceBackdropState = state;
            if (prototypeEntranceBackdrop == null)
            {
                return;
            }

            bool visible = ShouldShowPrototypeEntranceBackdrop(state);
            if (visible)
            {
                Texture2D texture = state == GreedLastScreenState.BootInit
                    ? prototypeEntranceTitleTexture
                    : prototypeLobbyTexture;
                if (texture != null)
                {
                    prototypeEntranceBackdrop.texture = texture;
                    prototypeEntranceBackdrop.GetComponent<AspectRatioFitter>().aspectRatio =
                        (float)texture.width / texture.height;
                }
            }
            if (visible && !prototypeEntranceBackdrop.gameObject.activeSelf)
            {
                prototypeEntranceBackdropCanvasGroup.alpha = 0f;
                prototypeEntranceBackdrop.gameObject.SetActive(true);
            }
        }

        private void UpdatePrototypeEntranceBackdrop()
        {
            if (prototypeEntranceBackdrop == null
                || prototypeEntranceBackdropCanvasGroup == null
                || !prototypeEntranceBackdrop.gameObject.activeSelf)
            {
                return;
            }

            float targetAlpha = BuildPrototypeEntranceBackdropAlpha(prototypeEntranceBackdropState);
            prototypeEntranceBackdropCanvasGroup.alpha = Mathf.Lerp(
                prototypeEntranceBackdropCanvasGroup.alpha,
                targetAlpha,
                1f - Mathf.Exp(-Time.unscaledDeltaTime * 4.2f));

            RectTransform rect = prototypeEntranceBackdrop.rectTransform;
            float breath = 0.5f + Mathf.Sin(Time.unscaledTime * 0.62f) * 0.5f;
            float motionScale = BuildMotionComfortMotionScale(motionComfortEnabled);
            float scale = 1.025f + breath * 0.004f * motionScale;
            rect.localScale = new Vector3(scale, scale, 1f);
            rect.anchoredPosition = new Vector2(0f, Mathf.Lerp(-4f, 3f, breath) * motionScale);

            if (ShouldDeactivatePrototypeEntranceBackdrop(
                    prototypeEntranceBackdropState,
                    prototypeEntranceBackdropCanvasGroup.alpha))
            {
                prototypeEntranceBackdropCanvasGroup.alpha = 0f;
                prototypeEntranceBackdrop.gameObject.SetActive(false);
            }
        }

        private static bool ShouldDeactivatePrototypeEntranceBackdrop(
            GreedLastScreenState state,
            float currentAlpha)
        {
            return !ShouldShowPrototypeEntranceBackdrop(state) && currentAlpha <= 0.005f;
        }

        private static bool ShouldShowPrototypeEntranceBackdrop(GreedLastScreenState state)
        {
            return state == GreedLastScreenState.BootInit
                || state == GreedLastScreenState.ConnectChecking
                || state == GreedLastScreenState.ConnectBlocked
                || state == GreedLastScreenState.ReSyncPending
                || state == GreedLastScreenState.LobbyReady;
        }

        private static float BuildPrototypeEntranceBackdropAlpha(GreedLastScreenState state)
        {
            switch (state)
            {
                case GreedLastScreenState.BootInit:
                    return 0.54f;
                case GreedLastScreenState.ConnectChecking:
                case GreedLastScreenState.ConnectBlocked:
                case GreedLastScreenState.ReSyncPending:
                    return 0.38f;
                case GreedLastScreenState.LobbyReady:
                    return 0.30f;
                default:
                    return 0f;
            }
        }

        private void CreatePrototypeRunCorridorBackdrop(Transform parent)
        {
            Texture2D texture = Resources.Load<Texture2D>("GreedLast/PrototypeRunCorridor");
            if (texture == null)
            {
                return;
            }

            GameObject backdropObject = CreateRect(
                "PrototypeRunCorridorBackdrop",
                parent,
                Vector2.zero,
                Vector2.one,
                Vector2.zero,
                Vector2.zero);
            prototypeRunCorridorBackdrop = backdropObject.AddComponent<RawImage>();
            prototypeRunCorridorBackdrop.texture = texture;
            prototypeRunCorridorBackdrop.color = PrototypeRunCorridorTintColor;
            prototypeRunCorridorBackdrop.raycastTarget = false;

            AspectRatioFitter fitter = backdropObject.AddComponent<AspectRatioFitter>();
            fitter.aspectMode = AspectRatioFitter.AspectMode.EnvelopeParent;
            fitter.aspectRatio = texture.height > 0 ? (float)texture.width / texture.height : 16f / 9f;

            prototypeRunCorridorBackdropCanvasGroup = backdropObject.AddComponent<CanvasGroup>();
            prototypeRunCorridorBackdropCanvasGroup.alpha = 0f;
            prototypeRunCorridorBackdropCanvasGroup.interactable = false;
            prototypeRunCorridorBackdropCanvasGroup.blocksRaycasts = false;
            backdropObject.SetActive(false);
        }

        private void UpdatePrototypeRunCorridorBackdrop()
        {
            if (prototypeRunCorridorBackdrop == null || prototypeRunCorridorBackdropCanvasGroup == null)
            {
                return;
            }

            bool visible = ShouldShowPrototypeRunCorridorBackdrop(runModeActive, hasRunSnapshot);
            if (visible && !prototypeRunCorridorBackdrop.gameObject.activeSelf)
            {
                prototypeRunCorridorBackdropCanvasGroup.alpha = 0f;
                prototypeRunCorridorBackdrop.gameObject.SetActive(true);
            }

            if (!prototypeRunCorridorBackdrop.gameObject.activeSelf)
            {
                return;
            }

            float targetAlpha = BuildPrototypeRunCorridorBackdropAlpha(
                visible,
                visible && latestRunSnapshot.Paused,
                visible && (latestRunSnapshot.CountdownActive || latestRunSnapshot.ResumeCountdownActive),
                visible && latestRunSnapshot.ChoiceActive,
                visible && latestRunSnapshot.Stopped);
            prototypeRunCorridorBackdropCanvasGroup.alpha = Mathf.Lerp(
                prototypeRunCorridorBackdropCanvasGroup.alpha,
                targetAlpha,
                1f - Mathf.Exp(-Time.unscaledDeltaTime * 5.2f));

            Color32 targetTint = visible
                ? BuildPrototypeRunCorridorBackdropTint(
                    BuildRunAtmosphereAccent(latestRunSnapshot),
                    latestRunSnapshot.InfiniteMode,
                    latestRunSnapshot.Phase == GreedLastRunPhase.EscapeRunning
                        || latestRunSnapshot.Phase == GreedLastRunPhase.ClearResolving,
                    latestRunSnapshot.FocusStateActive,
                    latestRunSnapshot.Health <= 1 && !latestRunSnapshot.Stopped,
                    BuildTrapReadinessAtmosphereStrength(latestRunSnapshot))
                : PrototypeRunCorridorTintColor;
            prototypeRunCorridorBackdrop.color = Color.Lerp(
                prototypeRunCorridorBackdrop.color,
                targetTint,
                1f - Mathf.Exp(-Time.unscaledDeltaTime * 4.4f));

            bool advancing = visible && ShouldAdvanceRunMotion(latestRunSnapshot);
            float pulse = 0.5f + Mathf.Sin(beatPhase * Mathf.PI * 2f) * 0.5f;
            RectTransform rect = prototypeRunCorridorBackdrop.rectTransform;
            float scale = BuildPrototypeRunCorridorBackdropScale(visible, advancing, pulse, motionComfortEnabled);
            rect.localScale = new Vector3(scale, scale, 1f);
            rect.anchoredPosition = new Vector2(
                0f,
                BuildPrototypeRunCorridorBackdropOffsetY(visible, advancing, pulse, motionComfortEnabled));

            float rotationDirection = visible && latestRunSnapshot.ActivePattern
                ? BuildRotationPatternDirection(latestRunSnapshot.Pattern)
                : 0f;
            float rotationReadiness = visible && latestRunSnapshot.ActivePattern
                ? BuildStraightRunRotationReadiness(latestRunSnapshot)
                : 0f;
            rect.localEulerAngles = new Vector3(
                0f,
                0f,
                BuildPrototypeRunCorridorBackdropRotation(
                    rotationDirection,
                    rotationReadiness,
                    motionComfortEnabled));

            if (!visible && prototypeRunCorridorBackdropCanvasGroup.alpha <= 0.005f)
            {
                prototypeRunCorridorBackdropCanvasGroup.alpha = 0f;
                prototypeRunCorridorBackdrop.gameObject.SetActive(false);
            }
        }

        private static bool ShouldShowPrototypeRunCorridorBackdrop(bool runModeActive, bool hasRunSnapshot)
        {
            return runModeActive && hasRunSnapshot;
        }

        private static float BuildPrototypeRunCorridorBackdropAlpha(
            bool visible,
            bool paused,
            bool countdown,
            bool choice,
            bool stopped)
        {
            if (!visible)
            {
                return 0f;
            }

            if (paused || stopped)
            {
                return 0.30f;
            }

            if (countdown || choice)
            {
                return 0.36f;
            }

            return 0.44f;
        }

        private static float BuildPrototypeRunCorridorBackdropScale(
            bool visible,
            bool advancing,
            float pulse,
            bool motionComfortEnabled)
        {
            if (!visible)
            {
                return 1f;
            }

            float motionScale = BuildMotionComfortMotionScale(motionComfortEnabled);
            float beatLift = advancing ? Mathf.Clamp01(pulse) * 0.010f : 0f;
            return 1.022f + beatLift * motionScale;
        }

        private static float BuildPrototypeRunCorridorBackdropOffsetY(
            bool visible,
            bool advancing,
            float pulse,
            bool motionComfortEnabled)
        {
            if (!visible || !advancing)
            {
                return 0f;
            }

            return Mathf.Lerp(-2f, 5f, Mathf.Clamp01(pulse))
                * BuildMotionComfortMotionScale(motionComfortEnabled);
        }

        private static float BuildPrototypeRunCorridorBackdropRotation(
            float direction,
            float readiness,
            bool motionComfortEnabled)
        {
            return Mathf.Clamp(direction, -1f, 1f)
                * Mathf.Clamp01(readiness)
                * 1.6f
                * BuildMotionComfortRotationScale(motionComfortEnabled);
        }

        private static Color32 BuildPrototypeRunCorridorBackdropTint(
            Color32 atmosphereAccent,
            bool infiniteMode,
            bool escapePhase,
            bool focusActive,
            bool healthDanger,
            float trapReadiness)
        {
            float blend = infiniteMode ? 0.18f : escapePhase ? 0.16f : 0.10f;
            if (focusActive)
            {
                blend += 0.04f;
            }

            if (healthDanger)
            {
                blend += 0.03f;
            }

            blend += Mathf.Clamp01(trapReadiness) * 0.035f;
            return Color32.Lerp(
                PrototypeRunCorridorTintColor,
                atmosphereAccent,
                Mathf.Clamp(blend, 0.08f, 0.28f));
        }

        private Color32 BuildRunLaneBaseColor(int laneIndex, float lanePulse)
        {
            if (!runModeActive || !hasRunSnapshot)
            {
                return Color32.Lerp(
                    PrototypePyramidStoneColor,
                    Color32.Lerp(PrototypeTealColor, PrototypeGoldColor, 0.28f),
                    lanePulse * 0.35f);
            }

            Color32 accent = BuildRunAtmosphereAccent(latestRunSnapshot);
            if (IsVisibleChoiceProfile(latestRunSnapshot.ActiveChoiceProfile))
            {
                accent = Color32.Lerp(
                    accent,
                    GetChoiceProfilePulseColor(latestRunSnapshot.ActiveChoiceProfile),
                    0.16f);
            }
            Color32 darkBase = Color32.Lerp(PrototypePyramidStoneColor, accent, 0.13f + laneIndex * 0.018f);
            float pulseStrength = latestRunSnapshot.Phase == GreedLastRunPhase.EscapeRunning ? 0.24f : 0.16f;
            return Color32.Lerp(darkBase, accent, lanePulse * pulseStrength);
        }

        private static Color32 BuildRunAtmosphereBackground(GreedLastRunSnapshot snapshot)
        {
            Color32 background;
            if (snapshot.InfiniteMode)
            {
                background = Color32.Lerp(PrototypePyramidShadowColor, new Color32(21, 15, 9, 255), 0.42f);
            }
            else if (snapshot.Phase == GreedLastRunPhase.EscapeRunning
                || snapshot.Phase == GreedLastRunPhase.ClearResolving)
            {
                background = Color32.Lerp(PrototypePyramidShadowColor, new Color32(27, 17, 8, 255), 0.50f);
            }
            else
            {
                switch (Mathf.Clamp(snapshot.ChapterIndex, 1, 4))
                {
                    case 1:
                        background = Color32.Lerp(PrototypePyramidShadowColor, PrototypeTealColor, 0.08f);
                        break;
                    case 2:
                        background = Color32.Lerp(PrototypePyramidShadowColor, PrototypeGoldColor, 0.08f);
                        break;
                    case 3:
                        background = Color32.Lerp(PrototypePyramidShadowColor, PrototypeVermilionColor, 0.08f);
                        break;
                    default:
                        background = Color32.Lerp(PrototypePyramidShadowColor, PrototypeGoldColor, 0.11f);
                        break;
                }
            }

            float threatStrength = BuildInfiniteThreatStrength(snapshot);
            float blend = snapshot.InfiniteMode
                ? Mathf.Lerp(0.08f, 0.18f, threatStrength)
                : snapshot.Phase == GreedLastRunPhase.EscapeRunning ? 0.12f : 0.065f;
            if (snapshot.FocusStateActive)
            {
                blend += 0.025f;
            }

            if (snapshot.Health <= 1 && !snapshot.Stopped)
            {
                background = Color32.Lerp(background, new Color32(32, 9, 9, 255), 0.22f);
            }

            float trapReadiness = BuildTrapReadinessAtmosphereStrength(snapshot);
            if (trapReadiness > 0f)
            {
                background = Color32.Lerp(
                    background,
                    BuildTrapReadinessAtmosphereColor(snapshot),
                    trapReadiness * 0.10f);
                blend += trapReadiness * 0.025f;
            }

            return Color32.Lerp(background, BuildRunAtmosphereAccent(snapshot), Mathf.Clamp01(blend));
        }

        private static Color32 BuildRunAtmosphereAccent(GreedLastRunSnapshot snapshot)
        {
            Color32 accent;
            if (snapshot.InfiniteMode)
            {
                accent = new Color32(205, 166, 70, 255);
            }
            else if (snapshot.Phase == GreedLastRunPhase.EscapeRunning
                || snapshot.Phase == GreedLastRunPhase.ClearResolving)
            {
                accent = new Color32(255, 196, 74, 255);
            }
            else
            {
                switch (Mathf.Clamp(snapshot.ChapterIndex, 1, 4))
                {
                    case 1:
                        accent = new Color32(87, 151, 142, 255);
                        break;
                    case 2:
                        accent = new Color32(180, 137, 74, 255);
                        break;
                    case 3:
                        accent = new Color32(196, 89, 65, 255);
                        break;
                    default:
                        accent = new Color32(220, 174, 76, 255);
                        break;
                }
            }

            string profile = BuildAtmosphereChoiceProfile(snapshot);
            if (IsVisibleChoiceProfile(profile))
            {
                accent = Color32.Lerp(
                    accent,
                    GetChoiceProfilePulseColor(profile),
                    snapshot.InfiniteMode ? 0.30f : 0.22f);
            }

            string route = BuildAtmosphereRouteProfile(snapshot);
            if (!string.IsNullOrEmpty(route))
            {
                accent = Color32.Lerp(
                    accent,
                    GetRouteProfileAtmosphereColor(route),
                    snapshot.InfiniteMode ? 0.34f : 0.26f);
            }

            if (!string.IsNullOrEmpty(snapshot.ActiveRelic))
            {
                accent = Color32.Lerp(accent, GetRelicAtmosphereColor(snapshot.ActiveRelic), 0.18f);
            }

            if (snapshot.FocusStateActive)
            {
                accent = Color32.Lerp(accent, new Color32(255, 224, 129, 255), 0.20f);
            }

            if (snapshot.InfiniteMode)
            {
                accent = Color32.Lerp(
                    accent,
                    GetInfiniteThreatAtmosphereColor(snapshot.InfiniteThreatLevel),
                    Mathf.Lerp(0.16f, 0.42f, BuildInfiniteThreatStrength(snapshot)));
            }

            if (snapshot.Health <= 1 && !snapshot.Stopped)
            {
                accent = Color32.Lerp(accent, new Color32(231, 91, 77, 255), 0.22f);
            }

            float trapReadiness = BuildTrapReadinessAtmosphereStrength(snapshot);
            if (trapReadiness > 0f)
            {
                accent = Color32.Lerp(
                    accent,
                    BuildTrapReadinessAtmosphereColor(snapshot),
                    trapReadiness * 0.34f);
            }

            return accent;
        }

        private static string BuildAtmosphereChoiceProfile(GreedLastRunSnapshot snapshot)
        {
            string profile = snapshot.InfiniteMode && !string.IsNullOrEmpty(snapshot.ActiveInfiniteLoadoutProfile)
                ? snapshot.ActiveInfiniteLoadoutProfile
                : snapshot.ActiveChoiceProfile;
            string extracted = ExtractChoiceProfileKeyword(profile);
            if (!string.IsNullOrEmpty(extracted))
            {
                return extracted;
            }

            return IsVisibleChoiceProfile(profile) ? profile : string.Empty;
        }

        private static string ExtractChoiceProfileKeyword(string value)
        {
            if (string.IsNullOrEmpty(value))
            {
                return string.Empty;
            }

            if (value.Contains("안정형", StringComparison.Ordinal))
            {
                return "안정형";
            }

            if (value.Contains("집중형", StringComparison.Ordinal))
            {
                return "집중형";
            }

            if (value.Contains("연쇄형", StringComparison.Ordinal))
            {
                return "연쇄형";
            }

            if (value.Contains("고점형", StringComparison.Ordinal))
            {
                return "고점형";
            }

            return value.Contains("균형형", StringComparison.Ordinal) ? "균형형" : string.Empty;
        }

        private static string BuildAtmosphereRouteProfile(GreedLastRunSnapshot snapshot)
        {
            if (!string.IsNullOrEmpty(snapshot.ActiveRouteProfile))
            {
                return ExtractRouteProfileKeyword(snapshot.ActiveRouteProfile);
            }

            string profile = snapshot.InfiniteMode
                ? snapshot.ActiveInfiniteLoadoutProfile
                : snapshot.ActiveChoiceProfile;
            return ExtractRouteProfileKeyword(profile);
        }

        private static string ExtractRouteProfileKeyword(string value)
        {
            if (string.IsNullOrEmpty(value))
            {
                return string.Empty;
            }

            if (value.Contains("안정 루트", StringComparison.Ordinal))
            {
                return "안정 루트";
            }

            if (value.Contains("변주 루트", StringComparison.Ordinal))
            {
                return "변주 루트";
            }

            if (value.Contains("압박 루트", StringComparison.Ordinal))
            {
                return "압박 루트";
            }

            return value.Contains("혼합 루트", StringComparison.Ordinal) ? "혼합 루트" : string.Empty;
        }

        private static Color32 GetRouteProfileAtmosphereColor(string route)
        {
            switch (route)
            {
                case "안정 루트":
                    return new Color32(116, 202, 173, 255);
                case "변주 루트":
                    return new Color32(111, 169, 210, 255);
                case "압박 루트":
                    return new Color32(255, 157, 92, 255);
                case "혼합 루트":
                    return new Color32(218, 197, 144, 255);
                default:
                    return new Color32(255, 238, 181, 255);
            }
        }

        private static Color32 GetRelicAtmosphereColor(string relic)
        {
            if (string.IsNullOrEmpty(relic))
            {
                return new Color32(255, 238, 181, 255);
            }

            if (relic.Contains("파라오", StringComparison.Ordinal))
            {
                return new Color32(255, 197, 86, 255);
            }

            if (relic.Contains("사막", StringComparison.Ordinal))
            {
                return new Color32(201, 228, 181, 255);
            }

            return relic.Contains("황금", StringComparison.Ordinal)
                ? new Color32(255, 214, 105, 255)
                : new Color32(218, 226, 218, 255);
        }

        private static Color32 GetInfiniteThreatAtmosphereColor(int threatLevel)
        {
            float pressure = Mathf.Clamp01((threatLevel - 1) / 4f);
            return Color32.Lerp(new Color32(205, 166, 70, 255), new Color32(231, 91, 77, 255), pressure);
        }

        private static float BuildTrapReadinessAtmosphereStrength(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ActivePattern
                || !snapshot.Pattern.IsValid
                || snapshot.Stopped
                || snapshot.Paused
                || snapshot.ChoiceActive
                || snapshot.CountdownActive)
            {
                return 0f;
            }

            float interval = BuildTimingBeatPipInterval(snapshot.Pattern, BuildBeatInterval(snapshot));
            float secondsToCore = Mathf.Max(0f, -snapshot.CoreDeltaSeconds);
            float approach = Mathf.Clamp01(1f - secondsToCore / Mathf.Max(0.01f, interval * 1.85f));
            float exactProximity = Mathf.Clamp01(1f - Mathf.Abs(snapshot.CoreDeltaSeconds) / Mathf.Max(0.01f, snapshot.Pattern.GoodWindowSeconds));
            float variationPressure = Mathf.Max(0f, BuildTrapVariationPressure(snapshot.Pattern));
            float focusLift = snapshot.FocusStateActive ? 0.08f : 0f;
            float infiniteLift = BuildInfiniteThreatStrength(snapshot) * 0.08f;
            return Mathf.Clamp01(0.08f + approach * 0.34f + exactProximity * 0.34f + variationPressure * 0.14f + focusLift + infiniteLift);
        }

        private static Color32 BuildTrapReadinessAtmosphereColor(GreedLastRunSnapshot snapshot)
        {
            Color32 responseColor = GetRunnerResponseAtmosphereColor(BuildRunnerResponseType(snapshot.Pattern));
            Color32 timingColor = GetTimingTypeAtmosphereColor(snapshot.Pattern.TimingType);
            Color32 color = Color32.Lerp(responseColor, timingColor, 0.38f);
            if (TryGetPatternVariationAccent(snapshot.Pattern, out Color32 variationColor, out float variationStrength))
            {
                color = Color32.Lerp(color, variationColor, Mathf.Clamp01(0.24f + variationStrength * 0.28f));
            }

            return color;
        }

        private static Color32 GetRunnerResponseAtmosphereColor(RunnerResponseType response)
        {
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return new Color32(255, 214, 105, 255);
                case RunnerResponseType.Slide:
                    return new Color32(145, 231, 199, 255);
                case RunnerResponseType.Twist:
                    return new Color32(142, 190, 255, 255);
                default:
                    return new Color32(255, 238, 181, 255);
            }
        }

        private static Color32 GetTimingTypeAtmosphereColor(GreedLastTimingType timingType)
        {
            switch (timingType)
            {
                case GreedLastTimingType.Perfect:
                    return new Color32(255, 238, 181, 255);
                case GreedLastTimingType.Clutch:
                    return new Color32(255, 178, 101, 255);
                case GreedLastTimingType.Offbeat:
                    return new Color32(129, 198, 230, 255);
                default:
                    return new Color32(218, 226, 218, 255);
            }
        }

        private static float BuildInfiniteThreatStrength(GreedLastRunSnapshot snapshot)
        {
            return snapshot.InfiniteMode
                ? Mathf.Clamp01((snapshot.InfiniteThreatLevel - 1) / 4f)
                : 0f;
        }

        private static float BuildStageMotionScale(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.PracticeMode)
            {
                return 0.82f;
            }

            if (snapshot.InfiniteMode)
            {
                return Mathf.Lerp(1f, 1.32f, Mathf.Clamp01((snapshot.InfiniteThreatLevel - 1) / 4f));
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                return 1.30f;
            }

            switch (Mathf.Clamp(snapshot.ChapterIndex, 1, 4))
            {
                case 1:
                    return 0.86f;
                case 2:
                    return 1f;
                case 3:
                    return 1.16f;
                default:
                    return 1.08f;
            }
        }

        private static float BuildStageDepthScale(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.PracticeMode)
            {
                return 0.88f;
            }

            if (snapshot.InfiniteMode)
            {
                return Mathf.Lerp(1.04f, 1.22f, Mathf.Clamp01((snapshot.InfiniteThreatLevel - 1) / 4f));
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                return 1.28f;
            }

            switch (Mathf.Clamp(snapshot.ChapterIndex, 1, 4))
            {
                case 1:
                    return 0.84f;
                case 2:
                    return 0.98f;
                case 3:
                    return 1.12f;
                default:
                    return 1.20f;
            }
        }

        private static float BuildTunnelDepthContactStrength(
            GreedLastRunSnapshot snapshot,
            float forwardPulse,
            float beatPulse)
        {
            return BuildTunnelDepthContactStrengthFromValues(
                snapshot.ActivePattern,
                snapshot.Paused || snapshot.Stopped || snapshot.ChoiceActive || snapshot.CountdownActive,
                snapshot.CoreDeltaSeconds,
                snapshot.Pattern.IsValid ? snapshot.Pattern.SuccessWindowSeconds : 0f,
                snapshot.Pattern.IsValid ? snapshot.Pattern.GoodWindowSeconds : 0f,
                snapshot.Pattern.IsValid ? snapshot.Pattern.TimingType : GreedLastTimingType.Perfect,
                snapshot.InfiniteMode,
                snapshot.InfiniteThreatLevel,
                forwardPulse,
                beatPulse);
        }

        private static float BuildTunnelDepthContactStrengthFromValues(
            bool activePattern,
            bool blocked,
            float coreDeltaSeconds,
            float successWindowSeconds,
            float goodWindowSeconds,
            GreedLastTimingType timingType,
            bool infiniteMode,
            int infiniteThreatLevel,
            float forwardPulse,
            float beatPulse)
        {
            if (!activePattern || blocked)
            {
                return 0f;
            }

            float successWindow = Mathf.Max(0.01f, successWindowSeconds);
            float goodWindow = Mathf.Max(successWindow, Mathf.Max(0.01f, goodWindowSeconds));
            float successProximity = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / successWindow);
            float goodProximity = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / goodWindow);
            float timingLift;
            switch (timingType)
            {
                case GreedLastTimingType.Clutch:
                    timingLift = 1.12f;
                    break;
                case GreedLastTimingType.Offbeat:
                    timingLift = 1.06f;
                    break;
                default:
                    timingLift = 1f;
                    break;
            }

            float threatLift = infiniteMode
                ? Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.12f
                : 0f;
            float beatLift = 0.78f + Mathf.Clamp01(beatPulse) * 0.22f;
            float payoffLift = 1f + Mathf.Clamp01(forwardPulse) * 0.16f;
            return Mathf.Clamp01((goodProximity * 0.54f + successProximity * 0.34f + threatLift) * timingLift * beatLift * payoffLift);
        }

        private static float BuildTunnelDepthContactScale(float stageDepthScale, float contactStrength)
        {
            return Mathf.Clamp(
                Mathf.Max(0.1f, stageDepthScale) * (1f - Mathf.Clamp01(contactStrength) * 0.045f),
                0.72f,
                1.38f);
        }

        private static int BuildTunnelDepthContactAlphaLift(float contactStrength, bool innerRail)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(contactStrength) * (innerRail ? 24f : 16f));
        }

        private static int BuildTunnelDepthHorizonAlphaLift(float contactStrength)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(contactStrength) * 22f);
        }

        private static float BuildTunnelDepthContactColorBlend(float contactStrength, bool innerRail)
        {
            return Mathf.Clamp01(contactStrength) * (innerRail ? 0.30f : 0.22f);
        }

        private static float BuildTunnelDepthPillarSpreadScale(float contactStrength, int depthIndex)
        {
            int safeIndex = Mathf.Clamp(depthIndex, 0, 3);
            return 1f + Mathf.Clamp01(contactStrength) * (0.020f + safeIndex * 0.006f);
        }

        private static float BuildTunnelDepthPillarWidthScale(float contactStrength, int depthIndex)
        {
            int safeIndex = Mathf.Clamp(depthIndex, 0, 3);
            return 1f + Mathf.Clamp01(contactStrength) * Mathf.Clamp(0.080f - safeIndex * 0.010f, 0.045f, 0.080f);
        }

        private static float BuildTunnelDepthPillarHeightScale(float contactStrength, int depthIndex)
        {
            int safeIndex = Mathf.Clamp(depthIndex, 0, 3);
            return 1f - Mathf.Clamp01(contactStrength) * Mathf.Clamp(0.042f - safeIndex * 0.006f, 0.020f, 0.042f);
        }

        private static int BuildTunnelDownbeatAlphaLift(float downbeatPulse, bool innerRail)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(downbeatPulse) * (innerRail ? 18f : 11f));
        }

        private static float BuildTunnelDownbeatScaleLift(float downbeatPulse, bool innerRail)
        {
            return Mathf.Clamp01(downbeatPulse) * (innerRail ? 0.048f : 0.030f);
        }

        private static float BuildTunnelBeatCueUrgency(float beatCueUrgency, float contactStrength)
        {
            return Mathf.Clamp01(beatCueUrgency) * Mathf.Lerp(0.72f, 1f, Mathf.Clamp01(contactStrength));
        }

        private static float BuildTunnelRailBeatCueUrgency(float tunnelBeatCueUrgency, bool innerRail)
        {
            return Mathf.Clamp01(tunnelBeatCueUrgency) * (innerRail ? 1f : 0.62f);
        }

        private static int BuildTunnelBeatCueUrgencyAlphaLift(float railBeatCueUrgency, bool innerRail)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(railBeatCueUrgency) * (innerRail ? 10f : 6f));
        }

        private static int BuildTunnelBeatCueUrgencyHorizonAlphaLift(float tunnelBeatCueUrgency)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(tunnelBeatCueUrgency) * 9f);
        }

        private static float BuildTunnelBeatCueUrgencyColorBlend(float railBeatCueUrgency, bool innerRail)
        {
            return Mathf.Clamp01(railBeatCueUrgency) * (innerRail ? 0.13f : 0.08f);
        }

        private static float BuildTunnelBeatCueUrgencyScaleLift(float railBeatCueUrgency, bool innerRail)
        {
            return Mathf.Clamp01(railBeatCueUrgency) * (innerRail ? 0.014f : 0.009f);
        }

        private static float BuildTunnelBeatCueUrgencyHorizonScaleLift(float tunnelBeatCueUrgency)
        {
            return Mathf.Clamp01(tunnelBeatCueUrgency) * 0.012f;
        }

        private static float BuildTunnelHorizonAnchorX(float rotationDirection, float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0.5f;
            }

            return 0.5f + Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 0.018f;
        }

        private static float BuildTunnelHorizonAnchorY(float tunnelContact, float rotationReadiness)
        {
            return 0.875f - Mathf.Clamp01(tunnelContact) * 0.010f + Mathf.Clamp01(rotationReadiness) * 0.004f;
        }

        private static float BuildTunnelHorizonTiltAngle(float rotationDirection, float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 2.6f;
        }

        private static float BuildTunnelHorizonScaleX(
            float pulse,
            float tunnelDepthScale,
            float downbeatPulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            return Mathf.Lerp(0.82f, 1.12f, Mathf.Clamp01(pulse))
                * Mathf.Max(0.1f, tunnelDepthScale)
                * (1f
                    + Mathf.Clamp01(downbeatPulse) * 0.025f
                    + BuildTunnelBeatCueUrgencyHorizonScaleLift(tunnelBeatCueUrgency)
                    + Mathf.Clamp01(rotationReadiness) * 0.026f);
        }

        private static int BuildTunnelHorizonRotationAlphaLift(float rotationReadiness)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(rotationReadiness) * 10f);
        }

        private static float BuildTunnelHorizonRotationColorBlend(float rotationReadiness)
        {
            return Mathf.Clamp01(rotationReadiness) * 0.10f;
        }

        private static float BuildTempleEntranceArchPieceAnchorX(
            int pieceIndex,
            float rotationDirection,
            float rotationReadiness)
        {
            int safeIndex = Mathf.Clamp(pieceIndex, 0, TempleEntranceArchPieceCount - 1);
            float drift = Mathf.Approximately(rotationDirection, 0f)
                ? 0f
                : Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * (safeIndex == 2 ? 0.014f : 0.022f);
            if (safeIndex == 0)
            {
                return 0.365f + drift;
            }
            if (safeIndex == 1)
            {
                return 0.635f + drift;
            }

            return 0.5f + drift * 0.70f;
        }

        private static float BuildTempleEntranceArchPieceAnchorY(
            int pieceIndex,
            float tunnelContact,
            float rotationReadiness)
        {
            int safeIndex = Mathf.Clamp(pieceIndex, 0, TempleEntranceArchPieceCount - 1);
            float approachDip = Mathf.Clamp01(tunnelContact) * 0.018f;
            float rotationLift = Mathf.Clamp01(rotationReadiness) * 0.006f;
            return (safeIndex == 2 ? 0.818f : 0.735f) - approachDip + rotationLift;
        }

        private static float BuildTempleEntranceArchPieceWidth(
            int pieceIndex,
            float tunnelContact,
            float downbeatPulse,
            float rotationReadiness)
        {
            int safeIndex = Mathf.Clamp(pieceIndex, 0, TempleEntranceArchPieceCount - 1);
            float contact = Mathf.Clamp01(tunnelContact);
            float beat = Mathf.Clamp01(downbeatPulse);
            float rotation = Mathf.Clamp01(rotationReadiness);
            return safeIndex == 2
                ? Mathf.Lerp(218f, 284f, contact) + beat * 8f + rotation * 12f
                : Mathf.Lerp(20f, 30f, contact) + beat * 2.2f + rotation * 1.6f;
        }

        private static float BuildTempleEntranceArchPieceHeight(
            int pieceIndex,
            float tunnelContact,
            float downbeatPulse,
            float rotationReadiness)
        {
            int safeIndex = Mathf.Clamp(pieceIndex, 0, TempleEntranceArchPieceCount - 1);
            float contact = Mathf.Clamp01(tunnelContact);
            float beat = Mathf.Clamp01(downbeatPulse);
            float rotation = Mathf.Clamp01(rotationReadiness);
            return safeIndex == 2
                ? Mathf.Lerp(16f, 28f, contact) + beat * 3.4f + rotation * 2.2f
                : Mathf.Lerp(136f, 178f, contact) + beat * 5f + rotation * 6f;
        }

        private static float BuildTempleEntranceArchPieceAngle(
            int pieceIndex,
            float rotationDirection,
            float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            int safeIndex = Mathf.Clamp(pieceIndex, 0, TempleEntranceArchPieceCount - 1);
            float maxAngle = safeIndex == 2 ? 5.5f : 3.2f;
            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * maxAngle;
        }

        private static int BuildTempleEntranceArchPieceAlpha(
            bool visible,
            float motionStrength,
            float tunnelContact,
            float downbeatPulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness,
            bool lintel)
        {
            if (!visible)
            {
                return 0;
            }

            float alpha = (lintel ? 20f : 24f)
                + Mathf.Clamp01(motionStrength) * (lintel ? 30f : 34f)
                + Mathf.Clamp01(tunnelContact) * (lintel ? 28f : 22f)
                + Mathf.Clamp01(downbeatPulse) * (lintel ? 16f : 12f)
                + Mathf.Clamp01(tunnelBeatCueUrgency) * (lintel ? 10f : 8f)
                + Mathf.Clamp01(rotationReadiness) * (lintel ? 16f : 13f);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 116f));
        }

        private static float BuildTempleEntranceArchPieceColorBlend(
            float tunnelContact,
            float downbeatPulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            return Mathf.Clamp01(
                0.14f
                    + Mathf.Clamp01(tunnelContact) * 0.22f
                    + Mathf.Clamp01(downbeatPulse) * 0.14f
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * 0.10f
                    + Mathf.Clamp01(rotationReadiness) * 0.16f);
        }

        private static float BuildTempleEntranceLaunchPassThroughStrength(
            bool visible,
            bool running,
            bool resumeLaunch,
            float now,
            float releaseStartedAt,
            float releaseUntil)
        {
            if (resumeLaunch)
            {
                return 0f;
            }

            return BuildStraightRunLaunchForwardBurst(
                visible,
                running,
                now,
                releaseStartedAt,
                releaseUntil);
        }

