            return Mathf.Clamp01(strength) * (lintel ? 38f : 6f);
        }

        private static float BuildTempleEntranceLaunchHeightLift(int pieceIndex, float strength)
        {
            bool lintel = Mathf.Clamp(pieceIndex, 0, TempleEntranceArchPieceCount - 1) == 2;
            return Mathf.Clamp01(strength) * (lintel ? 5f : 24f);
        }

        private static float BuildTempleEntranceLaunchScaleX(int pieceIndex, float strength)
        {
            bool lintel = Mathf.Clamp(pieceIndex, 0, TempleEntranceArchPieceCount - 1) == 2;
            return 1f + Mathf.Clamp01(strength) * (lintel ? 0.085f : 0.045f);
        }

        private static float BuildTempleEntranceLaunchScaleY(int pieceIndex, float strength)
