        private static float BuildSceneryPillarRotationCue(float rotationReadiness, float phase, int depthIndex)
        {
            int safeDepth = Mathf.Clamp(depthIndex, 0, 6);
            float depthFalloff = Mathf.Clamp(1f - safeDepth * 0.075f, 0.62f, 1f);
            float nearWeight = Mathf.Lerp(0.38f, 1f, Mathf.Clamp01(phase));
            return Mathf.Clamp01(rotationReadiness) * nearWeight * depthFalloff;
        }

        private static float BuildSceneryPillarRotationSpreadScale(float pillarRotationCue)
        {
            return 1f + Mathf.Clamp01(pillarRotationCue) * 0.060f;
        }

        private static float BuildSceneryPillarRotationOffsetX(
            float rotationDirection,
            float pillarRotationCue,
            float sideDirection)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            float parallax = Mathf.Lerp(0.86f, 1.14f, Mathf.Clamp01((Mathf.Sign(sideDirection) + 1f) * 0.5f));
            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(pillarRotationCue) * parallax * 0.022f;
        }

        private static float BuildSceneryPillarRotationAngle(
            float rotationDirection,
            float pillarRotationCue,
            float sideDirection)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            float sideWeight = Mathf.Lerp(0.76f, 1f, Mathf.Clamp01((Mathf.Sign(sideDirection) + 1f) * 0.5f));
            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(pillarRotationCue) * sideWeight * 5.2f;
        }

        private static int BuildSceneryPillarRotationAlphaLift(float pillarRotationCue)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(pillarRotationCue) * 16f);
        }

        private static float BuildSceneryPillarRotationColorBlend(float pillarRotationCue)
        {
            return Mathf.Clamp01(pillarRotationCue) * 0.16f;
        }

        private static float BuildForwardMotionSpeedBias(
            GreedLastRunSnapshot snapshot,
            float comboStrength,
            float forwardPulse)
        {
            float speedBias = snapshot.CountdownActive ? 0.55f : snapshot.ActivePattern ? 1.18f : 0.82f;
            speedBias *= 1f + Mathf.Clamp01(comboStrength) * 0.16f + Mathf.Clamp01(forwardPulse) * 0.46f;
            if (snapshot.FocusStateActive)
            {
                speedBias *= 1.22f;
            }

            if (snapshot.Staggered || snapshot.StaggerRemainingSeconds > 0.01f)
            {
                float recoveryPressure = Mathf.Clamp01(snapshot.StaggerRemainingSeconds / StaggerRecoveryVisualSeconds);
                speedBias *= Mathf.Lerp(0.82f, 0.62f, recoveryPressure);
            }

            return speedBias;
        }

        private static float BuildMissRecoveryMotionPressure(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Stopped
                || snapshot.Paused
                || snapshot.ChoiceActive
                || snapshot.CountdownActive
                || (!snapshot.Staggered && snapshot.StaggerRemainingSeconds <= 0.01f))
            {
                return 0f;
            }

            return Mathf.Clamp01(snapshot.StaggerRemainingSeconds / StaggerRecoveryVisualSeconds);
        }

        private static Color32 BuildMissRecoveryMotionTint(Color32 baseColor, float recoveryPressure, float maxBlend)
        {
            return Color32.Lerp(
                baseColor,
                new Color32(207, 87, 65, 255),
                Mathf.Clamp01(recoveryPressure) * Mathf.Clamp01(maxBlend));
        }

        private static int BuildMissRecoveryMotionAlpha(int alpha, float recoveryPressure, float maxDim)
        {
            float dim = Mathf.Clamp01(recoveryPressure) * Mathf.Clamp01(maxDim);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0, 255) * (1f - dim));
        }

        private void UpdateLobbyRunPortal(float pulse)
        {
            float runHandoffProgress = BuildRunEntranceHandoffProgress(
                runModeActive && hasRunSnapshot,
                Time.unscaledTime,
                runEntranceHandoffStartedAt,
                runEntranceHandoffUntil);
            float runHandoffPortalVisibility = BuildRunEntrancePortalVisibility(runHandoffProgress);
            bool handoffPortalVisible = runModeActive
                && hasRunSnapshot
                && runHandoffPortalVisibility > 0f;
            bool portalVisible = lobbyRunPortalVisible || handoffPortalVisible;
            bool portalReady = lobbyRunPortalVisible
                ? lobbyRunPortalReady
                : runEntranceHandoffPortalReady;
            bool practiceFirst = lobbyRunPortalVisible
                ? lobbyRunPortalPracticeFirst
                : runEntranceHandoffPracticeFirst;
            float revealProgress = BuildLobbyEntranceRevealProgress(
                lobbyRunPortalVisible,
                Time.unscaledTime,
                lobbyEntranceRevealStartedAt,
                lobbyEntranceRevealUntil);
            float portalVisibility = lobbyRunPortalVisible
                ? revealProgress
                : runHandoffPortalVisibility;
            UpdateLobbyRunButtonEmphasis(pulse, revealProgress);
            if (lobbyRunPortalPieces == null || lobbyRunPortalPips == null)
            {
                return;
            }

            float portalStrength = BuildLobbyRunPortalPulse(
                portalVisible,
                portalReady,
                pulse);
            Color32 portalColor = portalReady
                ? Color32.Lerp(PrototypePyramidStoneColor, PrototypeGoldColor, 0.68f)
                : practiceFirst
                    ? Color32.Lerp(PrototypePyramidStoneColor, PrototypeTealColor, 0.42f)
                    : PrototypePyramidStoneColor;
            for (int i = 0; i < lobbyRunPortalPieces.Length; i += 1)
            {
                Image piece = lobbyRunPortalPieces[i];
                if (piece == null)
                {
                    continue;
                }

                int alpha = BuildLobbyRunPortalPieceAlpha(
                    i,
                    portalVisible,
                    portalReady,
                    practiceFirst,
                    pulse);
                alpha = BuildLobbyEntranceRevealAlpha(alpha, portalVisibility);
                piece.color = WithAlpha(portalColor, alpha);
                float scale = i == 3
                    ? 1f + portalStrength * (portalReady ? 0.08f : 0.025f)
                    : 1f;
                float handoffScale = handoffPortalVisible
                    ? Mathf.Lerp(1f, 1.08f, runHandoffProgress)
                    : Mathf.Lerp(0.94f, 1f, revealProgress);
                piece.rectTransform.localScale = new Vector3(
                    scale * handoffScale,
                    handoffPortalVisible
                        ? Mathf.Lerp(1f, 1.05f, runHandoffProgress)
                        : Mathf.Lerp(0.84f, 1f, revealProgress),
                    1f);
            }

            for (int i = 0; i < lobbyRunPortalPips.Length; i += 1)
            {
                Image pip = lobbyRunPortalPips[i];
                if (pip == null)
                {
                    continue;
                }

                int alpha = BuildLobbyRunPortalPipAlpha(
                    i,
                    portalVisible,
                    portalReady,
                    beatPhase);
                alpha = BuildLobbyEntranceRevealAlpha(alpha, portalVisibility);
                pip.color = WithAlpha(PrototypeGoldColor, alpha);
                float pipScale = alpha > 0 ? Mathf.Lerp(0.82f, 1.12f, alpha / 255f) : 1f;
                pip.rectTransform.localScale = new Vector3(pipScale, 1f, 1f);
            }
        }

        private void UpdateLobbyRunButtonEmphasis(float pulse, float revealProgress)
        {
            float normalEmphasis = BuildLobbyRunButtonEmphasis(
                lobbyRunPortalVisible,
                lobbyRunPortalReady,
                pulse) * Mathf.Clamp01(revealProgress);
            float practiceEmphasis = BuildLobbyPracticeButtonEmphasis(
                lobbyRunPortalVisible,
                lobbyRunPortalPracticeFirst,
                pulse) * Mathf.Clamp01(revealProgress);
            if (normalRunButton != null)
            {
                float normalScale = BuildLobbyRunButtonScale(normalEmphasis);
                normalRunButton.transform.localScale = new Vector3(normalScale, normalScale, 1f);
            }

            if (practiceRunButton != null)
            {
                float practiceScale = BuildLobbyRunButtonScale(practiceEmphasis);
                practiceRunButton.transform.localScale = new Vector3(practiceScale, practiceScale, 1f);
            }
        }

        private void UpdateTempleDepthBackdrop()
        {
            if (runTunnelLines == null || runTunnelHorizon == null)
            {
                return;
            }

            bool visible = runModeActive && hasRunSnapshot;
            float forwardPulse = BuildForwardPayoffBurstPulse(forwardPayoffBurstUntil - Time.unscaledTime, forwardPayoffBurstStrength);
            bool liveMotion = visible && ShouldAdvanceRunMotion(latestRunSnapshot);
            float motionStrength = liveMotion
                ? (latestRunSnapshot.ActivePattern ? 1f : 0.72f)
                : visible ? 0.34f : 0f;
            motionStrength = Mathf.Clamp01(motionStrength + forwardPulse * 0.20f);
            motionStrength *= BuildMotionComfortMotionScale(motionComfortEnabled);
            float pulse = 0.5f + Mathf.Sin(beatPhase * Mathf.PI * 2f) * 0.5f;
            float stageMotionScale = visible ? BuildStageMotionScale(latestRunSnapshot) : 1f;
            float stageDepthScale = (visible ? BuildStageDepthScale(latestRunSnapshot) : 1f) * (1f + forwardPulse * 0.09f);
            float tunnelContact = visible ? BuildTunnelDepthContactStrength(latestRunSnapshot, forwardPulse, pulse) : 0f;
            float tunnelBeatCueUrgency = visible
                ? BuildTunnelBeatCueUrgency(BuildActiveBeatCueUrgency(latestRunSnapshot), tunnelContact)
                : 0f;
            float tunnelDepthScale = BuildTunnelDepthContactScale(stageDepthScale, tunnelContact);
            float comboStrength = visible ? Mathf.Clamp01(latestRunSnapshot.Combo / 12f) : 0f;
            float motionSpeedBias = visible ? BuildForwardMotionSpeedBias(latestRunSnapshot, comboStrength, forwardPulse) : 1f;
            float recoveryPressure = visible ? BuildMissRecoveryMotionPressure(latestRunSnapshot) : 0f;
            float downbeatPulse = visible && ShouldShowDownbeatPulse(latestRunSnapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;
            float rotationDirection = visible ? BuildRotationPatternDirection(latestRunSnapshot.Pattern) : 0f;
            float rotationReadiness = visible
                && latestRunSnapshot.ActivePattern
                && latestRunSnapshot.Pattern.IsValid
                && GreedLastRunCore.IsRotationPattern(latestRunSnapshot.Pattern)
                    ? BuildStraightRunRotationReadiness(latestRunSnapshot)
                    : 0f;
            rotationReadiness *= BuildMotionComfortRotationScale(motionComfortEnabled);
            float rotationInputAlignment = BuildStraightRunRotationInputAlignment(
                rotationDirection,
                rotationReadiness,
                rotationTiltInputAxis);
            Color32 atmosphereAccent = visible
                ? BuildRunAtmosphereAccent(latestRunSnapshot)
                : new Color32(67, 105, 103, 255);
            for (int i = 0; i < runTunnelLines.Length; i += 1)
            {
                Image line = runTunnelLines[i];
                if (line == null)
                {
                    continue;
                }

                bool innerRail = i >= 2;
                float railBeatCueUrgency = BuildTunnelRailBeatCueUrgency(tunnelBeatCueUrgency, innerRail);
                Color32 color = innerRail
                    ? Color32.Lerp(atmosphereAccent, new Color32(255, 214, 105, 255), 0.24f)
                    : Color32.Lerp(new Color32(67, 105, 103, 255), atmosphereAccent, 0.58f);
                int alpha = Mathf.RoundToInt((innerRail ? 28f : 42f) * motionStrength + pulse * (innerRail ? 34f : 24f) * motionStrength);
                if (forwardPulse > 0f)
                {
                    color = Color32.Lerp(color, new Color32(255, 238, 181, 255), forwardPulse * (innerRail ? 0.32f : 0.18f));
                    alpha = Mathf.RoundToInt(alpha * Mathf.Lerp(1f, 1.28f, forwardPulse));
                }
                if (tunnelContact > 0f)
                {
                    color = Color32.Lerp(color, new Color32(255, 248, 210, 255), BuildTunnelDepthContactColorBlend(tunnelContact, innerRail));
                    alpha += BuildTunnelDepthContactAlphaLift(tunnelContact, innerRail);
                }
                if (downbeatPulse > 0f)
                {
                    color = Color32.Lerp(color, new Color32(255, 214, 105, 255), BuildDownbeatColorBlend(downbeatPulse, innerRail ? 0.22f : 0.14f));
                    alpha += BuildTunnelDownbeatAlphaLift(downbeatPulse, innerRail);
                }
                if (railBeatCueUrgency > 0f)
                {
                    color = Color32.Lerp(
                        color,
                        new Color32(255, 238, 181, 255),
                        BuildTunnelBeatCueUrgencyColorBlend(railBeatCueUrgency, innerRail));
                    alpha += BuildTunnelBeatCueUrgencyAlphaLift(railBeatCueUrgency, innerRail);
                }
                if (recoveryPressure > 0f)
                {
                    color = BuildMissRecoveryMotionTint(color, recoveryPressure, innerRail ? 0.34f : 0.24f);
                    alpha = BuildMissRecoveryMotionAlpha(alpha, recoveryPressure, innerRail ? 0.18f : 0.12f);
                }
                line.color = WithAlpha(color, alpha);
                line.rectTransform.localScale = new Vector3(
                    1f,
                    1f
                        + pulse * 0.35f * motionStrength
                        + (tunnelDepthScale - 1f) * 0.18f
                        + BuildTunnelDownbeatScaleLift(downbeatPulse, innerRail)
                        + BuildTunnelBeatCueUrgencyScaleLift(railBeatCueUrgency, innerRail),
                    1f);
            }

            int horizonAlpha = Mathf.RoundToInt(Mathf.Lerp(0f, 104f, motionStrength) * Mathf.Lerp(0.72f, 1f, pulse));
            Color32 horizonColor = atmosphereAccent;
            if (tunnelContact > 0f)
            {
                horizonColor = Color32.Lerp(horizonColor, new Color32(255, 248, 210, 255), BuildTunnelDepthContactColorBlend(tunnelContact, true));
                horizonAlpha += BuildTunnelDepthHorizonAlphaLift(tunnelContact);
            }
            if (downbeatPulse > 0f)
            {
                horizonColor = Color32.Lerp(horizonColor, new Color32(255, 214, 105, 255), BuildDownbeatColorBlend(downbeatPulse, 0.20f));
                horizonAlpha += BuildTunnelDownbeatAlphaLift(downbeatPulse, true);
            }
            if (tunnelBeatCueUrgency > 0f)
            {
                horizonColor = Color32.Lerp(
                    horizonColor,
                    new Color32(255, 238, 181, 255),
                    BuildTunnelBeatCueUrgencyColorBlend(tunnelBeatCueUrgency, true));
                horizonAlpha += BuildTunnelBeatCueUrgencyHorizonAlphaLift(tunnelBeatCueUrgency);
            }
            if (rotationReadiness > 0f)
            {
                horizonColor = Color32.Lerp(
                    horizonColor,
                    PrototypeGoldColor,
                    BuildTunnelHorizonRotationColorBlend(rotationReadiness));
                horizonAlpha += BuildTunnelHorizonRotationAlphaLift(rotationReadiness);
            }
            if (recoveryPressure > 0f)
            {
                horizonColor = BuildMissRecoveryMotionTint(horizonColor, recoveryPressure, 0.28f);
                horizonAlpha = BuildMissRecoveryMotionAlpha(horizonAlpha, recoveryPressure, 0.14f);
            }
            horizonColor.a = (byte)Mathf.Clamp(horizonAlpha, 0, 255);
            runTunnelHorizon.color = horizonColor;
            RectTransform horizonRect = runTunnelHorizon.rectTransform;
            horizonRect.anchorMin = new Vector2(
                BuildTunnelHorizonAnchorX(rotationDirection, rotationReadiness),
                BuildTunnelHorizonAnchorY(tunnelContact, rotationReadiness));
            horizonRect.anchorMax = horizonRect.anchorMin;
            horizonRect.anchoredPosition = Vector2.zero;
            horizonRect.localEulerAngles = new Vector3(
                0f,
                0f,
                BuildTunnelHorizonInputResponsiveTiltAngle(
                    BuildTunnelHorizonTiltAngle(rotationDirection, rotationReadiness),
                    rotationInputAlignment));
            horizonRect.localScale = new Vector3(
                BuildTunnelHorizonScaleX(
                    pulse,
                    tunnelDepthScale,
                    downbeatPulse,
                    tunnelBeatCueUrgency,
                    rotationReadiness),
                1f,
                1f);

            UpdateTempleEntranceArch(
                visible,
                motionStrength,
                tunnelContact,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                recoveryPressure,
                atmosphereAccent);

            bool sceneryRunning = visible && ShouldAdvanceRunMotion(latestRunSnapshot);
            UpdateStraightRunPathVisuals(
                visible,
                sceneryRunning,
                motionStrength,
                stageMotionScale,
                motionSpeedBias,
                stageDepthScale,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                atmosphereAccent);
            UpdateFloorBeatTiles(
                visible,
                sceneryRunning,
                motionStrength,
                stageMotionScale,
                motionSpeedBias,
                stageDepthScale,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                latestRunSnapshot.FocusStateActive,
                latestRunSnapshot,
                atmosphereAccent);

            if (runSceneryPillars == null)
            {
                return;
            }

            const int depthPairs = 4;
            for (int pair = 0; pair < depthPairs; pair += 1)
            {
                float phase = BuildSceneryPillarPhase(
                    sceneryRunning,
                    beatPhase,
                    stageMotionScale,
                    motionSpeedBias,
                    forwardPulse,
                    pair,
                    depthPairs);
                float pillarDownbeatLift = BuildSceneryPillarDownbeatLift(downbeatPulse, phase, pair, depthPairs);
                float pillarBeatCueUrgency = BuildTunnelPillarBeatCueUrgency(tunnelBeatCueUrgency, phase, pair);
                float pillarRotationCue = BuildSceneryPillarRotationCue(rotationReadiness, phase, pair);
                float y = Mathf.Lerp(0.84f, 0.20f, phase);
                float spread = Mathf.Min(
                    0.475f,
                    Mathf.Lerp(0.075f, 0.44f, phase)
                        * tunnelDepthScale
                        * BuildTunnelDepthPillarSpreadScale(tunnelContact, pair)
                        * BuildSceneryPillarDownbeatSpreadScale(pillarDownbeatLift)
                        * BuildTunnelPillarBeatCueUrgencySpreadScale(pillarBeatCueUrgency)
                        * BuildSceneryPillarRotationSpreadScale(pillarRotationCue));
                float width = Mathf.Lerp(12f, 44f, phase)
                    * tunnelDepthScale
                    * BuildTunnelDepthPillarWidthScale(tunnelContact, pair)
                    * BuildSceneryPillarDownbeatWidthScale(pillarDownbeatLift)
                    * BuildTunnelPillarBeatCueUrgencyWidthScale(pillarBeatCueUrgency);
                float height = Mathf.Lerp(42f, 208f, phase)
                    * tunnelDepthScale
                    * BuildTunnelDepthPillarHeightScale(tunnelContact, pair)
                    * BuildSceneryPillarDownbeatHeightScale(pillarDownbeatLift)
                    * BuildTunnelPillarBeatCueUrgencyHeightScale(pillarBeatCueUrgency);
                int alpha = visible
                    ? Mathf.RoundToInt(Mathf.Lerp(22f, sceneryRunning ? 108f : 52f, phase) * motionStrength)
                    : 0;
                Color32 pillarColor = Color32.Lerp(new Color32(45, 65, 67, 255), atmosphereAccent, 0.34f + phase * 0.22f);
                if (forwardPulse > 0f)
                {
                    pillarColor = Color32.Lerp(pillarColor, new Color32(255, 238, 181, 255), forwardPulse * 0.18f);
                    alpha = Mathf.RoundToInt(alpha * Mathf.Lerp(1f, 1.24f, forwardPulse));
                }
                if (tunnelContact > 0f)
                {
                    pillarColor = Color32.Lerp(
                        pillarColor,
                        new Color32(255, 248, 210, 255),
                        BuildTunnelDepthContactColorBlend(tunnelContact, false));
                    alpha += BuildTunnelDepthContactAlphaLift(tunnelContact, false);
                }
                if (pillarDownbeatLift > 0f)
                {
                    pillarColor = Color32.Lerp(
                        pillarColor,
                        new Color32(255, 214, 105, 255),
                        BuildSceneryPillarDownbeatColorBlend(pillarDownbeatLift));
                    alpha += BuildSceneryPillarDownbeatAlphaLift(pillarDownbeatLift);
                }
                if (pillarBeatCueUrgency > 0f)
                {
                    pillarColor = Color32.Lerp(
                        pillarColor,
                        new Color32(255, 238, 181, 255),
                        BuildTunnelPillarBeatCueUrgencyColorBlend(pillarBeatCueUrgency));
                    alpha += BuildTunnelPillarBeatCueUrgencyAlphaLift(pillarBeatCueUrgency);
                }
                if (pillarRotationCue > 0f)
                {
                    pillarColor = Color32.Lerp(
                        pillarColor,
                        PrototypeGoldColor,
                        BuildSceneryPillarRotationColorBlend(pillarRotationCue));
                    alpha += BuildSceneryPillarRotationAlphaLift(pillarRotationCue);
                }
                if (recoveryPressure > 0f)
                {
                    pillarColor = BuildMissRecoveryMotionTint(pillarColor, recoveryPressure, 0.34f);
                    alpha = BuildMissRecoveryMotionAlpha(alpha, recoveryPressure, 0.16f);
                }
                pillarColor.a = (byte)Mathf.Clamp(alpha, 0, 255);

                for (int side = 0; side < 2; side += 1)
                {
                    int index = pair * 2 + side;
                    Image pillar = runSceneryPillars[index];
                    if (pillar == null)
                    {
                        continue;
                    }

                    float sideDirection = side == 0 ? -1f : 1f;
                    float x = 0.5f
                        + sideDirection * spread
                        + BuildSceneryPillarRotationOffsetX(
                            rotationDirection,
                            pillarRotationCue,
                            sideDirection);
                    RectTransform pillarRect = pillar.rectTransform;
                    pillarRect.anchorMin = new Vector2(x, y);
                    pillarRect.anchorMax = new Vector2(x, y);
                    pillarRect.anchoredPosition = Vector2.zero;
                    pillarRect.sizeDelta = new Vector2(width, height);
                    pillarRect.localScale = Vector3.one;
                    pillarRect.localEulerAngles = new Vector3(
                        0f,
                        0f,
                        BuildSceneryPillarRotationAngle(rotationDirection, pillarRotationCue, sideDirection));
                    pillar.color = pillarColor;
                }
            }
        }

        private void UpdateTempleEntranceArch(
            bool visible,
            float motionStrength,
            float tunnelContact,
            float downbeatPulse,
            float tunnelBeatCueUrgency,
            float rotationDirection,
            float rotationReadiness,
            float recoveryPressure,
            Color32 atmosphereAccent)
        {
            if (templeEntranceArchPieces == null)
            {
                return;
            }

            float launchPassThrough = BuildTempleEntranceLaunchPassThroughStrength(
                visible,
                hasRunSnapshot && ShouldAdvanceRunMotion(latestRunSnapshot),
                straightRunLaunchReleaseWasResume,
                Time.unscaledTime,
                straightRunLaunchReleaseStartedAt,
                straightRunLaunchReleaseUntil);

            for (int i = 0; i < templeEntranceArchPieces.Length; i += 1)
            {
                Image piece = templeEntranceArchPieces[i];
                if (piece == null)
                {
                    continue;
                }

                bool lintel = i == 2;
                RectTransform rect = piece.rectTransform;
                rect.anchorMin = new Vector2(
                    BuildTempleEntranceArchPieceAnchorX(i, rotationDirection, rotationReadiness),
                    BuildTempleEntranceArchPieceAnchorY(i, tunnelContact, rotationReadiness)
                        + BuildTempleEntranceLaunchAnchorYOffset(i, launchPassThrough));
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = Vector2.zero;
                rect.sizeDelta = new Vector2(
                    BuildTempleEntranceArchPieceWidth(i, tunnelContact, downbeatPulse, rotationReadiness)
                        + BuildTempleEntranceLaunchWidthLift(i, launchPassThrough),
                    BuildTempleEntranceArchPieceHeight(i, tunnelContact, downbeatPulse, rotationReadiness)
                        + BuildTempleEntranceLaunchHeightLift(i, launchPassThrough));
                rect.localEulerAngles = new Vector3(
                    0f,
                    0f,
                    BuildTempleEntranceArchPieceAngle(i, rotationDirection, rotationReadiness));
                rect.localScale = new Vector3(
                    BuildTempleEntranceLaunchScaleX(i, launchPassThrough),
                    BuildTempleEntranceLaunchScaleY(i, launchPassThrough),
                    1f);

                int alpha = BuildTempleEntranceArchPieceAlpha(
                    visible,
                    motionStrength,
                    tunnelContact,
                    downbeatPulse,
                    tunnelBeatCueUrgency,
                    rotationReadiness,
                    lintel);
                alpha += BuildTempleEntranceLaunchAlphaLift(i, launchPassThrough);
                Color32 pieceColor = Color32.Lerp(
                    PrototypePyramidStoneColor,
                    atmosphereAccent,
                    BuildTempleEntranceArchPieceColorBlend(tunnelContact, downbeatPulse, tunnelBeatCueUrgency, rotationReadiness));
                if (downbeatPulse > 0f || rotationReadiness > 0f)
                {
                    pieceColor = Color32.Lerp(pieceColor, PrototypeGoldColor, Mathf.Clamp01(downbeatPulse * 0.12f + rotationReadiness * 0.14f));
                }
                if (launchPassThrough > 0f)
                {
                    pieceColor = Color32.Lerp(
                        pieceColor,
                        PrototypeGoldColor,
                        BuildTempleEntranceLaunchColorBlend(launchPassThrough));
                }
                if (recoveryPressure > 0f)
                {
                    pieceColor = BuildMissRecoveryMotionTint(pieceColor, recoveryPressure, 0.20f);
                    alpha = BuildMissRecoveryMotionAlpha(alpha, recoveryPressure, 0.12f);
                }

                piece.color = WithAlpha(pieceColor, Mathf.Clamp(alpha, 0, 154));
            }
        }

        private void UpdateStraightRunPathVisuals(
            bool visible,
            bool running,
            float motionStrength,
            float stageMotionScale,
            float motionSpeedBias,
            float stageDepthScale,
            float forwardPulse,
            float recoveryPressure,
            float downbeatPulse,
            float tunnelBeatCueUrgency,
            Color32 atmosphereAccent)
        {
            if (straightRunPathRails == null || straightRunPathSegments == null)
            {
                return;
            }

            float launchForwardBurst = BuildStraightRunLaunchForwardBurst(
                visible,
                running,
                Time.unscaledTime,
                straightRunLaunchReleaseStartedAt,
                straightRunLaunchReleaseUntil);
            forwardPulse = Mathf.Max(forwardPulse, launchForwardBurst);
            motionStrength = Mathf.Clamp01(motionStrength + launchForwardBurst * 0.18f);
            stageMotionScale += launchForwardBurst * 0.10f;
            motionSpeedBias += launchForwardBurst * 0.16f;
            stageDepthScale += launchForwardBurst * 0.06f;

            float exitSprintStrength = BuildStraightRunExitSprintStrength(
                visible,
                running,
                BuildStraightRunExitSlotEscapeStrength(latestRunSnapshot));
            float exitSprintPulse = BuildStraightRunExitSprintPulse(exitSprintStrength, downbeatPulse);
            forwardPulse = Mathf.Max(forwardPulse, exitSprintPulse);
            motionStrength = Mathf.Clamp01(motionStrength + exitSprintStrength * 0.08f);
            stageMotionScale += exitSprintStrength * 0.07f;
            motionSpeedBias += exitSprintStrength * 0.10f;
            stageDepthScale += exitSprintStrength * 0.04f;

            GreedLastPatternModel pattern = visible ? latestRunSnapshot.Pattern : GreedLastPatternModel.Empty;
            float activeRotationDirection = BuildRotationPatternDirection(pattern);
            float activeRotationReadiness = visible
                && latestRunSnapshot.ActivePattern
                && GreedLastRunCore.IsRotationPattern(pattern)
                    ? BuildStraightRunRotationReadiness(latestRunSnapshot)
                    : 0f;
            bool showRotationResponse = ShouldShowStraightRunRotationResponsePips(
                visible,
                latestRunSnapshot.Stopped,
                latestRunSnapshot.Paused,
                latestRunSnapshot.ChoiceActive,
                latestRunSnapshot.CountdownActive);
            float rotationResponsePulse = showRotationResponse
                ? BuildStraightRunRotationResponsePulse(
                    runnerResponseWasRotationPattern,
                    runnerResponseResult,
                    runnerResponseUntil - Time.unscaledTime,
                    runnerResponseUntil - runnerResponseStartedAt)
                : 0f;
            float rotationResponseDirection = BuildRotationResponseDirection(runnerResponseChannel);
            float rotationDirection = BuildStraightRunRotationCorridorSettleDirection(
                activeRotationDirection,
                activeRotationReadiness,
                rotationResponseDirection,
                rotationResponsePulse);
            float rotationReadiness = BuildStraightRunRotationCorridorSettleReadiness(
                activeRotationReadiness,
                rotationResponsePulse);
            float rotationInputAlignment = BuildStraightRunRotationInputAlignment(
                activeRotationDirection,
                activeRotationReadiness,
                rotationTiltInputAxis);
            Color32 rotationSettleColor = BuildStraightRunRotationCorridorSettleColor(
                rotationResponsePulse,
                runnerResponseResult);
            float rotationSettleColorBlend = BuildStraightRunRotationCorridorSettleColorBlend(rotationResponsePulse);
            float trapPressure = BuildStraightRunTrapPressureForValues(
                visible && latestRunSnapshot.ActivePattern,
                latestRunSnapshot.Paused,
                latestRunSnapshot.Stopped,
                latestRunSnapshot.ChoiceActive,
                latestRunSnapshot.CountdownActive,
                latestRunSnapshot.CoreDeltaSeconds,
                pattern.IsValid ? pattern.GoodWindowSeconds : 0f,
                pattern.TimingType,
                latestRunSnapshot.InfiniteMode,
                latestRunSnapshot.InfiniteThreatLevel,
                tunnelBeatCueUrgency,
                BuildTrapVariationPressure(pattern));
            float pathRoll = BuildStraightRunRotationInputResponsivePathRoll(
                BuildStraightRunPathRollAngle(rotationDirection, rotationReadiness, downbeatPulse, tunnelBeatCueUrgency),
                rotationInputAlignment);
            Color32 railColor = Color32.Lerp(PrototypeTealColor, atmosphereAccent, 0.50f);
            if (rotationReadiness > 0f)
            {
                railColor = Color32.Lerp(railColor, PrototypeGoldColor, rotationReadiness * 0.42f);
            }
            if (rotationSettleColorBlend > 0f)
            {
                railColor = Color32.Lerp(railColor, rotationSettleColor, rotationSettleColorBlend);
            }
            railColor = BuildStraightRunRotationInputResponsiveColor(railColor, rotationInputAlignment);
            if (trapPressure > 0f)
            {
                railColor = Color32.Lerp(
                    railColor,
                    BuildPrototypeTrapBaseColor(pattern),
                    BuildStraightRunTrapPressureColorBlend(trapPressure, 0.66f));
            }
            if (recoveryPressure > 0f)
            {
                railColor = BuildMissRecoveryMotionTint(railColor, recoveryPressure, 0.20f);
            }

            for (int i = 0; i < straightRunPathRails.Length; i += 1)
            {
                Image rail = straightRunPathRails[i];
                if (rail == null)
                {
                    continue;
                }

                bool innerRail = i == 1 || i == 2;
                RectTransform railRect = rail.rectTransform;
                float anchorX = BuildStraightRunPathRailAnchorX(i, rotationDirection, rotationReadiness);
                railRect.anchorMin = new Vector2(anchorX, 0.55f);
                railRect.anchorMax = new Vector2(anchorX, 0.55f);
                railRect.anchoredPosition = Vector2.zero;
                railRect.sizeDelta = new Vector2(
                    BuildStraightRunPathRailWidth(i, stageDepthScale, rotationReadiness)
                        * BuildStraightRunTrapPressureWidthScale(trapPressure, innerRail ? 0.68f : 0.52f),
                    innerRail ? 5f : 7f);
                railRect.localEulerAngles = new Vector3(0f, 0f, BuildStraightRunPathRailAngle(i, pathRoll));
                railRect.localScale = Vector3.one;
                int alpha = BuildStraightRunPathRailAlpha(visible, motionStrength, rotationReadiness, innerRail);
                alpha += BuildStraightRunTrapPressureAlphaLift(trapPressure, innerRail ? 0.68f : 0.52f, innerRail ? 18 : 13);
                rail.color = WithAlpha(railColor, BuildMissRecoveryMotionAlpha(alpha, recoveryPressure, 0.12f));
            }

            UpdateStraightRunCorridorGates(
                visible,
                running,
                motionStrength,
                stageMotionScale,
                motionSpeedBias,
                stageDepthScale,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                trapPressure,
                atmosphereAccent);

            UpdateStraightRunSideWallStripes(
                visible,
                running,
                motionStrength,
                stageMotionScale,
                motionSpeedBias,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                trapPressure,
                atmosphereAccent);

            UpdateStraightRunSpeedStreaks(
                visible,
                running,
                motionStrength,
                stageMotionScale,
                motionSpeedBias,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                trapPressure,
                atmosphereAccent);

            UpdateStraightRunCenterSeamDashes(
                visible,
                running,
                motionStrength,
                stageMotionScale,
                motionSpeedBias,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                trapPressure,
                atmosphereAccent);

            UpdateStraightRunForwardPaceMarkers(
                visible,
                running,
                motionStrength,
                stageMotionScale,
                motionSpeedBias,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                trapPressure,
                atmosphereAccent);

            UpdateStraightRunFocusRings(
                visible,
                running,
                motionStrength,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                atmosphereAccent);

            UpdateStraightRunTargetFrame(
                visible,
                running,
                motionStrength,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                atmosphereAccent);

            UpdateStraightRunExitSlot(
                visible,
                running,
                motionStrength,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                atmosphereAccent);

            UpdateStraightRunExitApproachRails(
                visible,
                running,
                motionStrength,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                atmosphereAccent);

            UpdateStraightRunFocusBeacon(
                visible,
                running,
                motionStrength,
                forwardPulse,
                recoveryPressure,
                downbeatPulse,
                tunnelBeatCueUrgency,
                rotationDirection,
                rotationReadiness,
                atmosphereAccent);

            UpdateStraightRunLaunchGate(visible, atmosphereAccent);

            UpdateStraightRunRotationComfortAnchor(
                visible,
                activeRotationDirection,
                activeRotationReadiness,
                rotationResponseDirection,
                rotationResponsePulse,
                runnerResponseResult,
                downbeatPulse,
                atmosphereAccent);

            for (int i = 0; i < straightRunPathSegments.Length; i += 1)
            {
                Image segment = straightRunPathSegments[i];
                if (segment == null)
                {
                    continue;
                }

                float phase = BuildStraightRunPathSegmentPhase(
                    running,
                    beatPhase,
                    stageMotionScale,
                    motionSpeedBias,
                    forwardPulse,
                    i);
                float y = BuildStraightRunPathSegmentY(phase);
                float offsetX = BuildStraightRunPathRotationOffset(rotationDirection, rotationReadiness, phase);
                RectTransform segmentRect = segment.rectTransform;
                segmentRect.anchorMin = new Vector2(0.5f + offsetX, y);
                segmentRect.anchorMax = new Vector2(0.5f + offsetX, y);
                segmentRect.anchoredPosition = Vector2.zero;
                segmentRect.sizeDelta = new Vector2(
                    BuildStraightRunPathSegmentHalfWidth(phase, stageDepthScale, rotationReadiness) * 2f
                        * BuildStraightRunTrapPressureWidthScale(trapPressure, phase),
                    BuildStraightRunPathSegmentHeight(phase, rotationReadiness)
                        * BuildStraightRunTrapPressureHeightScale(trapPressure, phase));
                segmentRect.localEulerAngles = new Vector3(0f, 0f, pathRoll * 0.40f);
                segmentRect.localScale = Vector3.one;

                float nearPulse = BuildStraightRunPathSegmentNearPulse(phase, downbeatPulse);
                int alpha = BuildStraightRunPathSegmentAlpha(
                    visible,
                    motionStrength,
                    phase,
                    forwardPulse,
                    nearPulse,
                    rotationReadiness);
                Color32 segmentColor = Color32.Lerp(PrototypeTealColor, PrototypeGoldColor, rotationReadiness * 0.46f + nearPulse * 0.18f);
                if (rotationSettleColorBlend > 0f)
                {
                    segmentColor = Color32.Lerp(
                        segmentColor,
                        rotationSettleColor,
                        rotationSettleColorBlend * Mathf.Lerp(0.45f, 1f, Mathf.Clamp01(phase)));
                }
                if (trapPressure > 0f)
                {
                    alpha += BuildStraightRunTrapPressureAlphaLift(trapPressure, phase, 18);
                    segmentColor = Color32.Lerp(
                        segmentColor,
                        BuildPrototypeTrapBaseColor(pattern),
                        BuildStraightRunTrapPressureColorBlend(trapPressure, phase));
                }
                if (recoveryPressure > 0f)
                {
                    segmentColor = BuildMissRecoveryMotionTint(segmentColor, recoveryPressure, 0.18f);
                    alpha = BuildMissRecoveryMotionAlpha(alpha, recoveryPressure, 0.10f);
                }
                segment.color = WithAlpha(segmentColor, alpha);
            }

            if (straightRunRotationGuideBand == null)
            {
                return;
            }

            RectTransform guideRect = straightRunRotationGuideBand.rectTransform;
            guideRect.anchorMin = new Vector2(0.5f + BuildStraightRunRotationGuideOffset(rotationDirection, rotationReadiness), 0.55f);
            guideRect.anchorMax = guideRect.anchorMin;
            guideRect.anchoredPosition = Vector2.zero;
            guideRect.sizeDelta = new Vector2(
                BuildStraightRunRotationGuideWidth(rotationReadiness),
                BuildStraightRunRotationGuideHeight(rotationReadiness, downbeatPulse));
            guideRect.localEulerAngles = new Vector3(0f, 0f, BuildStraightRunRotationGuideAngle(rotationDirection, rotationReadiness));
            guideRect.localScale = Vector3.one;
            int guideAlpha = BuildStraightRunRotationGuideAlpha(visible, rotationReadiness, downbeatPulse);
            straightRunRotationGuideBand.color = WithAlpha(
                Color32.Lerp(PrototypeGoldColor, rotationSettleColor, rotationSettleColorBlend),
                guideAlpha);
            UpdateStraightRunRotationGuideNeedles(visible, rotationDirection, rotationReadiness, downbeatPulse);
            UpdateStraightRunRotationTiltPips(
                visible,
                activeRotationDirection,
                activeRotationReadiness,
                downbeatPulse,
                rotationResponseDirection,
                rotationResponsePulse,
                runnerResponseResult);
        }

