                    atmosphereAccent,
                    PrototypeGoldColor,
                    BuildStraightRunExitSlotPieceColorBlend(pulse, escapeStrength, rotationReadiness, i));
                if (escapeStrength > 0.65f)
                {
                    slotColor = Color32.Lerp(slotColor, new Color32(255, 248, 210, 255), Mathf.Clamp01(escapeStrength - 0.65f) * 0.34f);
                }
                if (recoveryPressure > 0f)
                {
                    slotColor = BuildMissRecoveryMotionTint(slotColor, recoveryPressure, 0.12f);
                }

                piece.color = WithAlpha(slotColor, alpha);
            }
        }

