        private void UpdateStraightRunLaunchGate(bool visible, Color32 atmosphereAccent)
        {
            if (straightRunLaunchGatePieces == null)
            {
                return;
            }

            bool countdownVisible = BuildStraightRunLaunchGateVisible(
                visible,
                latestRunSnapshot.CountdownActive,
                latestRunSnapshot.Paused,
                latestRunSnapshot.Stopped,
                latestRunSnapshot.ChoiceActive,
                latestRunSnapshot.ResumeCountdownActive);
            float remainingSeconds = latestRunSnapshot.CountdownRemainingSeconds;
            float releaseProgress = BuildStraightRunLaunchGateReleaseProgress(
                Time.unscaledTime,
                straightRunLaunchReleaseStartedAt,
                straightRunLaunchReleaseUntil);
            float releasePulse = BuildStraightRunLaunchGateReleasePulse(
                Time.unscaledTime,
                straightRunLaunchReleaseStartedAt,
                straightRunLaunchReleaseUntil);
            bool show = countdownVisible || releasePulse > 0f;
            float openProgress = countdownVisible
                ? BuildStraightRunLaunchGateOpenProgress(true, remainingSeconds)
                : 1f;
            float beatPulse = countdownVisible
                ? BuildStraightRunLaunchGateBeatPulse(true, remainingSeconds)
                : 0f;
            float pulse = Mathf.Max(beatPulse, releasePulse);
            for (int i = 0; i < straightRunLaunchGatePieces.Length; i += 1)
            {
                Image piece = straightRunLaunchGatePieces[i];
                if (piece == null)
                {
                    continue;
                }

                RectTransform rect = piece.rectTransform;
                float side = BuildStraightRunLaunchGateSide(i);
                rect.anchorMin = new Vector2(
                    BuildStraightRunLaunchGateAnchorX(i, openProgress)
                        + side * BuildStraightRunLaunchGateReleaseOffset(releaseProgress, releasePulse),
                    BuildStraightRunLaunchGateAnchorY(openProgress, pulse));
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = Vector2.zero;
                rect.sizeDelta = new Vector2(
                    BuildStraightRunLaunchGateWidth(openProgress, pulse),
                    BuildStraightRunLaunchGateHeight(openProgress, pulse));
                rect.localEulerAngles = new Vector3(
                    0f,
                    0f,
                    BuildStraightRunLaunchGateAngle(i, openProgress)
                        + side * BuildStraightRunLaunchGateReleaseAngleLift(releaseProgress, releasePulse));
                rect.localScale = Vector3.one;

                int alpha = countdownVisible
                    ? BuildStraightRunLaunchGateAlpha(true, openProgress, pulse)
                    : BuildStraightRunLaunchGateReleaseAlpha(show, releasePulse);
                Color32 gateColor = Color32.Lerp(
                    atmosphereAccent,
                    PrototypeGoldColor,
                    BuildStraightRunLaunchGateColorBlend(openProgress, pulse)
                        + BuildStraightRunLaunchGateReleaseColorLift(releasePulse));
                piece.color = WithAlpha(gateColor, alpha);
            }

            if (straightRunLaunchThresholdSweep != null)
            {
                float thresholdStrength = BuildRunEntryThresholdSweepStrength(
                    visible,
                    hasRunSnapshot && ShouldAdvanceRunMotion(latestRunSnapshot),
                    straightRunLaunchReleaseWasResume,
                    Time.unscaledTime,
                    straightRunLaunchReleaseStartedAt,
                    straightRunLaunchReleaseUntil);
                RectTransform thresholdRect = straightRunLaunchThresholdSweep.rectTransform;
                thresholdRect.anchorMin = new Vector2(0.5f, BuildRunEntryThresholdSweepAnchorY(releaseProgress));
                thresholdRect.anchorMax = thresholdRect.anchorMin;
                thresholdRect.anchoredPosition = Vector2.zero;
                thresholdRect.sizeDelta = new Vector2(
                    BuildRunEntryThresholdSweepWidth(releaseProgress),
                    BuildRunEntryThresholdSweepHeight(thresholdStrength));
                thresholdRect.localScale = Vector3.one;
                thresholdRect.localEulerAngles = Vector3.zero;
                Color32 thresholdColor = Color32.Lerp(
                    atmosphereAccent,
                    PrototypeGoldColor,
                    BuildRunEntryThresholdSweepColorBlend(releaseProgress));
                straightRunLaunchThresholdSweep.color = WithAlpha(
                    thresholdColor,
                    BuildRunEntryThresholdSweepAlpha(thresholdStrength, releaseProgress));
            }
        }

        private void UpdateStraightRunRotationComfortAnchor(
            bool visible,
            float activeRotationDirection,
            float activeRotationReadiness,
            float rotationResponseDirection,
            float rotationResponsePulse,
            GreedLastJudgementResult rotationResponseResult,
            float downbeatPulse,
            Color32 atmosphereAccent)
        {
            if (straightRunRotationComfortAnchorPieces == null)
            {
                return;
            }

            bool liveComfortWindow = visible
                && !latestRunSnapshot.Paused
                && !latestRunSnapshot.Stopped
                && !latestRunSnapshot.ChoiceActive
                && !latestRunSnapshot.CountdownActive;
            bool show = ShouldShowStraightRunRotationComfortAnchor(
                liveComfortWindow,
                activeRotationDirection,
                activeRotationReadiness,
                rotationResponseDirection,
                rotationResponsePulse);
            float direction = BuildStraightRunRotationComfortAnchorDirection(
                activeRotationDirection,
                activeRotationReadiness,
                rotationResponseDirection,
                rotationResponsePulse);
            float strength = BuildStraightRunRotationComfortAnchorStrength(
                activeRotationReadiness,
                rotationResponsePulse);
            Color32 responseColor = BuildStraightRunRotationCorridorSettleColor(
                rotationResponsePulse,
                rotationResponseResult);
            float responseColorBlend = BuildStraightRunRotationCorridorSettleColorBlend(rotationResponsePulse);

            for (int i = 0; i < straightRunRotationComfortAnchorPieces.Length; i += 1)
            {
                Image piece = straightRunRotationComfortAnchorPieces[i];
                if (piece == null)
                {
                    continue;
                }

                bool centerPiece = i == 0;
                float side = BuildStraightRunRotationComfortAnchorSide(i);
                float targetStrength = BuildStraightRunRotationComfortAnchorTargetStrength(
                    side,
                    direction,
                    strength);
                RectTransform rect = piece.rectTransform;
                rect.anchorMin = new Vector2(
                    BuildStraightRunRotationComfortAnchorAnchorX(i),
                    0.675f);
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = Vector2.zero;
                rect.sizeDelta = new Vector2(
                    BuildStraightRunRotationComfortAnchorWidth(i, targetStrength, downbeatPulse),
                    BuildStraightRunRotationComfortAnchorHeight(i, strength, targetStrength, downbeatPulse));
                rect.localEulerAngles = Vector3.zero;
                rect.localScale = Vector3.one;

                Color32 baseColor = centerPiece
                    ? Color32.Lerp(PrototypeTealColor, atmosphereAccent, 0.42f)
                    : Color32.Lerp(atmosphereAccent, PrototypeGoldColor, targetStrength);
                Color32 pieceColor = Color32.Lerp(baseColor, responseColor, responseColorBlend);
                piece.color = WithAlpha(
                    pieceColor,
                    BuildStraightRunRotationComfortAnchorAlpha(
                        show,
                        centerPiece,
                        targetStrength,
                        strength,
                        downbeatPulse));
            }
        }

        private void UpdateStraightRunRotationGuideNeedles(
            bool visible,
            float rotationDirection,
            float rotationReadiness,
            float downbeatPulse)
        {
            if (straightRunRotationGuideNeedles == null)
            {
                return;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            for (int i = 0; i < straightRunRotationGuideNeedles.Length; i += 1)
            {
                Image needle = straightRunRotationGuideNeedles[i];
                if (needle == null)
                {
                    continue;
                }

                float sequence = (i + 1f) / (straightRunRotationGuideNeedles.Length + 1f);
                RectTransform rect = needle.rectTransform;
                rect.anchorMin = new Vector2(
                    0.5f + BuildStraightRunRotationGuideNeedleOffset(rotationDirection, readiness, sequence),
                    BuildStraightRunRotationGuideNeedleAnchorY(sequence, readiness));
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = Vector2.zero;
                rect.sizeDelta = new Vector2(
                    BuildStraightRunRotationGuideNeedleWidth(readiness, downbeatPulse, sequence),
                    BuildStraightRunRotationGuideNeedleHeight(readiness, downbeatPulse, sequence));
                rect.localEulerAngles = new Vector3(0f, 0f, BuildStraightRunRotationGuideNeedleAngle(rotationDirection, readiness));
                rect.localScale = Vector3.one;
                int alpha = BuildStraightRunRotationGuideNeedleAlpha(visible, rotationDirection, readiness, downbeatPulse, sequence);
                needle.color = WithAlpha(Color32.Lerp(PrototypeGoldColor, PrototypeTealColor, readiness * 0.18f), alpha);
            }
        }

        private void UpdateStraightRunRotationTiltPips(
            bool visible,
            float rotationDirection,
            float rotationReadiness,
