            GreedLastJudgementResult responseResult)
        {
            if (straightRunRotationTiltPips == null)
            {
                return;
            }

            float readiness = BuildStraightRunRotationTiltDisplayReadiness(rotationReadiness, responsePulse);
            float direction = BuildStraightRunRotationTiltDisplayDirection(
                rotationDirection,
                rotationReadiness,
                responseDirection,
                responsePulse);
            Color32 targetColor = BuildStraightRunRotationTiltPipTargetColor(responsePulse, responseResult);
            for (int i = 0; i < straightRunRotationTiltPips.Length; i += 1)
            {
                Image pip = straightRunRotationTiltPips[i];
                if (pip == null)
                {
                    continue;
                }

                RectTransform rect = pip.rectTransform;
                rect.anchorMin = new Vector2(
                    0.5f + BuildStraightRunRotationTiltPipOffsetX(direction, readiness, i),
                    BuildStraightRunRotationTiltPipAnchorY(readiness, i));
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = Vector2.zero;
                rect.sizeDelta = new Vector2(
                    BuildStraightRunRotationTiltPipWidth(direction, readiness, downbeatPulse, i),
                    BuildStraightRunRotationTiltPipHeight(direction, readiness, downbeatPulse, i));
                rect.localEulerAngles = new Vector3(0f, 0f, BuildStraightRunRotationTiltPipAngle(direction, readiness, i));
                rect.localScale = Vector3.one;
                pip.color = WithAlpha(
                    Color32.Lerp(PrototypeTealColor, targetColor, BuildStraightRunRotationTiltPipColorBlend(direction, readiness, i)),
                    BuildStraightRunRotationTiltPipAlpha(visible, direction, readiness, downbeatPulse, i));
            }

            UpdateStraightRunRotationNeutralGate(
                ShouldShowRotationTiltControl(visible, rotationTiltInputAvailable),
                direction,
                readiness,
                downbeatPulse,
                rotationTiltInputReady,
                rotationTiltInputHeldDirection,
                responsePulse,
                targetColor);
            UpdateStraightRunRotationInputCursor(
                ShouldShowRotationTiltControl(visible, rotationTiltInputAvailable),
                direction,
                readiness,
                rotationTiltInputAxis,
                rotationTiltInputCandidateDirection,
                rotationTiltInputCandidateProgress,
                targetColor);
            UpdateStraightRunRotationGripBars(
                ShouldShowRotationTiltControl(visible, rotationTiltInputAvailable),
                direction,
                readiness,
                downbeatPulse,
                targetColor);
        }

        private static bool ShouldShowRotationTiltControl(bool rotationVisualVisible, bool tiltInputAvailable)
