            rect.anchorMin = new Vector2(
                0.5f + BuildStraightRunRotationInputCursorOffsetX(axis),
                BuildStraightRunRotationInputCursorAnchorY(rotationReadiness, progress));
            rect.anchorMax = rect.anchorMin;
            rect.anchoredPosition = Vector2.zero;
            rect.sizeDelta = new Vector2(
                BuildStraightRunRotationInputCursorWidth(axis, progress),
                BuildStraightRunRotationInputCursorHeight(axis, progress));
            rect.localEulerAngles = new Vector3(
                0f,
                0f,
                BuildStraightRunRotationInputCursorAngle(axis, progress));
            rect.localScale = Vector3.one;

            bool correctDirection = IsStraightRunRotationInputCursorCorrectDirection(
                rotationDirection,
                axis,
                candidateDirection);
            Color32 cursorColor = correctDirection
                ? Color32.Lerp(PrototypeTealColor, targetColor, 0.72f + progress * 0.28f)
                : PrototypeVermilionColor;
