        internal static bool ShouldShowLobbyRunner(
            bool lobbyPortalVisible,
            bool runModeActive,
            bool lobbyPortalReady,
            bool practiceFirst)
        {
            return lobbyPortalVisible
                && !runModeActive
                && (lobbyPortalReady || practiceFirst);
        }

        internal static float BuildLobbyRunnerPulse(float phase)
        {
            return 0.5f + Mathf.Sin(phase * Mathf.PI * 2f) * 0.5f;
        }

        internal static float BuildLobbyRunnerScale(bool ready, float pulse)
        {
            float safePulse = Mathf.Clamp01(pulse);
            float baseScale = ready ? 0.64f : 0.59f;
            return baseScale + safePulse * (ready ? 0.025f : 0.015f);
        }

        internal static float BuildLobbyRunnerBob(bool visible, float pulse)
        {
            return visible ? Mathf.Lerp(0f, 5f, Mathf.Clamp01(pulse)) : 0f;
        }

        internal static float BuildLobbyRunnerAlpha(bool visible, bool ready, bool practiceFirst)
        {
            if (!visible)
            {
                return 0f;
            }

            if (ready)
            {
                return 0.88f;
            }

            return practiceFirst ? 0.68f : 0.58f;
        }

        private void UpdateLobbyRunnerAvatar()
        {
            if (runnerAvatarRoot == null || runnerShadow == null)
            {
                return;
            }

            float pulse = BuildLobbyRunnerPulse(beatPhase);
            float sway = Mathf.Sin(beatPhase * Mathf.PI * 2f);
            float revealProgress = BuildLobbyEntranceRevealProgress(
                lobbyRunPortalVisible,
                Time.unscaledTime,
                lobbyEntranceRevealStartedAt,
                lobbyEntranceRevealUntil);
            float scale = BuildLobbyRunnerScale(lobbyRunPortalReady, pulse)
                * Mathf.Lerp(0.90f, 1f, revealProgress);
            RectTransform avatarRect = runnerAvatarRoot.GetComponent<RectTransform>();
            avatarRect.anchoredPosition = new Vector2(
                0f,
                -24f + BuildLobbyRunnerBob(true, pulse) + BuildLobbyRunnerRevealYOffset(revealProgress));
            avatarRect.localScale = new Vector3(scale, scale, 1f);
            avatarRect.localEulerAngles = new Vector3(0f, 0f, sway * 0.8f);

            Color32 idleColor = lobbyRunPortalReady
                ? Color32.Lerp(PrototypeRunnerSkinColor, PrototypeGoldColor, 0.14f)
                : lobbyRunPortalPracticeFirst
                    ? Color32.Lerp(PrototypeRunnerSkinColor, PrototypeTealColor, 0.20f)
                    : Color32.Lerp(PrototypeRunnerSkinColor, PrototypePyramidStoneColor, 0.12f);
            SetRunnerBodyColor(idleColor);
            ApplyRunnerLimbPose(
                -7f + sway * 1.8f,
                7f - sway * 1.8f,
                -3f - sway * 1.2f,
                3f + sway * 1.2f);
            ApplyRunnerPrototypeSilhouettePose(RunnerResponseType.None, 0f, 1f, sway * 0.18f);

            if (runnerAvatarCanvasGroup != null)
            {
                runnerAvatarCanvasGroup.alpha = BuildLobbyRunnerAlpha(
                    true,
                    lobbyRunPortalReady,
                    lobbyRunPortalPracticeFirst) * revealProgress;
            }

            runnerShadow.rectTransform.anchoredPosition = new Vector2(0f, -18f);
            runnerShadow.rectTransform.localScale = new Vector3(
                scale * Mathf.Lerp(0.92f, 1.04f, pulse),
                scale * 0.58f,
                1f);
            runnerShadow.color = new Color32(
                0,
                0,
                0,
                (byte)BuildLobbyEntranceRevealAlpha(
                    lobbyRunPortalReady ? 82 : 58,
                    revealProgress));
        }

        private void UpdateRunnerAvatar()
        {
            if (runnerAvatarRoot == null || runnerShadow == null)
            {
                return;
            }

            bool runVisible = runModeActive && hasRunSnapshot && !latestRunSnapshot.ChoiceActive && !latestRunSnapshot.Stopped;
            bool lobbyVisible = ShouldShowLobbyRunner(
                lobbyRunPortalVisible,
                runModeActive,
                lobbyRunPortalReady,
                lobbyRunPortalPracticeFirst);
            bool visible = runVisible || lobbyVisible;
            runnerAvatarRoot.SetActive(visible);
            runnerShadow.gameObject.SetActive(visible);
            bool coreRecovered = runVisible
                && runnerCoreGlow != null
                && latestRunSnapshot.CoreRetrieved
                && !latestRunSnapshot.InfiniteMode;
            float focusReadyGlow = runVisible ? BuildFocusReadyCoreGlow(latestRunSnapshot) : 0f;
            bool coreVisible = coreRecovered || (runVisible && latestRunSnapshot.FocusStateActive) || focusReadyGlow > 0f;
            if (runnerCoreGlow != null)
            {
                runnerCoreGlow.gameObject.SetActive(coreVisible);
            }

            if (lobbyVisible)
            {
                UpdateLobbyRunnerAvatar();
                HideRunnerFootfallPips();
                HideRunnerPreparationCue();
                HideRunnerActionTrails();
                return;
            }

            if (!runVisible)
            {
                HideRunnerFootfallPips();
                HideRunnerPreparationCue();
                HideRunnerActionTrails();
                return;
            }

            if (runnerAvatarCanvasGroup != null)
            {
                runnerAvatarCanvasGroup.alpha = 1f;
            }

            bool running = ShouldAdvanceRunMotion(latestRunSnapshot);
            float comboMotion = Mathf.Clamp01(latestRunSnapshot.Combo / 12f);
            float forwardPulse = BuildForwardPayoffBurstPulse(forwardPayoffBurstUntil - Time.unscaledTime, forwardPayoffBurstStrength);
            float launchStepStrength = BuildRunnerLaunchStepStrength(
                runVisible,
                running,
                Time.unscaledTime,
                straightRunLaunchReleaseStartedAt,
                straightRunLaunchReleaseUntil);
            float countdownReadyStrength = BuildRunnerCountdownReadyStrength(
                runVisible,
                latestRunSnapshot.CountdownActive,
                latestRunSnapshot.Paused,
                latestRunSnapshot.ResumeCountdownActive,
                latestRunSnapshot.Stopped,
                latestRunSnapshot.ChoiceActive,
                latestRunSnapshot.CountdownRemainingSeconds);
            float runEntryThreatRevealStrength = BuildRunEntryTrapRevealStrength();
            float strideSpeedBias = BuildForwardMotionSpeedBias(latestRunSnapshot, comboMotion, forwardPulse);
            float stridePhase = BuildRunnerStridePhase(running, beatPhase, strideSpeedBias, forwardPulse);
            float recoveryPressure = BuildMissRecoveryMotionPressure(latestRunSnapshot);
            float stride = running ? Mathf.Sin(stridePhase * Mathf.PI * 4f) : 0f;
            float bob = running ? Mathf.Abs(stride) * Mathf.Lerp(7f, 11f, comboMotion) : 0f;
            bool runnerBlocked = latestRunSnapshot.Paused
                || latestRunSnapshot.CountdownActive
                || latestRunSnapshot.Stopped
                || latestRunSnapshot.ChoiceActive;
            RectTransform avatarRect = runnerAvatarRoot.GetComponent<RectTransform>();
            avatarRect.anchoredPosition = new Vector2(0f, bob);
            avatarRect.localScale = Vector3.one;
            avatarRect.localEulerAngles = new Vector3(0f, 0f, stride * 1.6f);

            Vector4 runningLimbs = BuildRunnerStrideLimbAngles(stride);
            ApplyRunnerLimbPose(runningLimbs.x, runningLimbs.y, runningLimbs.z, runningLimbs.w);
            Color32 runnerBaseColor = PrototypeRunnerSkinColor;
            if (IsVisibleChoiceProfile(latestRunSnapshot.ActiveChoiceProfile))
            {
                runnerBaseColor = Color32.Lerp(
                    runnerBaseColor,
                    GetChoiceProfilePulseColor(latestRunSnapshot.ActiveChoiceProfile),
                    0.22f);
            }

            if (latestRunSnapshot.FocusStateActive)
            {
                runnerBaseColor = Color32.Lerp(runnerBaseColor, new Color32(255, 196, 74, 255), 0.46f);
            }
            if (recoveryPressure > 0f)
            {
                runnerBaseColor = BuildMissRecoveryMotionTint(runnerBaseColor, recoveryPressure, 0.32f);
            }
            SetRunnerBodyColor(runnerBaseColor);

            float shadowOffsetX = 0f;
            float shadowScaleX = 1f + Mathf.Abs(stride) * 0.08f;
            float shadowAlpha = 112f;
            float remaining = runnerResponseUntil - Time.unscaledTime;
            float runnerDownbeatLift = remaining <= 0f
                ? BuildRunnerDownbeatLift(
                    running && latestRunSnapshot.ActivePattern,
                    runnerBlocked,
                    ShouldShowDownbeatPulse(latestRunSnapshot) ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime) : 0f,
                    latestRunSnapshot.CoreDeltaSeconds,
                    latestRunSnapshot.Pattern.IsValid ? latestRunSnapshot.Pattern.GoodWindowSeconds : 0f)
                : 0f;
            if (remaining > 0f)
            {
                float duration = Mathf.Max(0.01f, runnerResponseUntil - runnerResponseStartedAt);
                float progress = Mathf.Clamp01((Time.unscaledTime - runnerResponseStartedAt) / duration);
                float arc = Mathf.Sin(progress * Mathf.PI);
                float channelDirection = runnerResponseChannel == GreedLastRunChannel.Left
                    ? 1f
                    : runnerResponseChannel == GreedLastRunChannel.Right
                        ? -1f
                        : Mathf.Sign(Mathf.Sin(beatPhase * Mathf.PI * 2f));
                if (Mathf.Approximately(channelDirection, 0f))
                {
                    channelDirection = 1f;
                }

                SetRunnerBodyColor(Color32.Lerp(runnerBaseColor, runnerResponseColor, arc * 0.88f));
                if (runnerResponseResult == GreedLastJudgementResult.Miss)
                {
                    float decay = 1f - progress;
                    float shake = Mathf.Sin(progress * Mathf.PI * 10f)
                        * decay
                        * BuildMotionComfortShakeScale(motionComfortEnabled);
                    avatarRect.anchoredPosition = new Vector2(shake * 26f, bob - arc * 16f);
                    avatarRect.localEulerAngles = new Vector3(0f, 0f, shake * 11f + channelDirection * arc * 7f);
                    avatarRect.localScale = new Vector3(1f + arc * 0.08f, 1f - arc * 0.12f, 1f);
                    ApplyRunnerLimbPose(-42f * arc, 34f * arc, 18f * arc, -28f * arc);
                    shadowOffsetX = shake * 10f;
                    shadowScaleX = 1.15f + arc * 0.18f;
                    shadowAlpha = 142f;
                }
                else
                {
                    float responseStrength = runnerResponseResult == GreedLastJudgementResult.Good ? 0.68f : 1f;
                    ApplyRunnerResponsePose(
                        avatarRect,
                        arc * responseStrength,
                        channelDirection,
                        ref shadowOffsetX,
                        ref shadowScaleX,
                        ref shadowAlpha);
                }
            }
            else if (running && latestRunSnapshot.ActivePattern)
            {
                float anticipation = BuildRunnerAnticipationStrength(
                    latestRunSnapshot.ActivePattern,
                    runnerBlocked,
                    latestRunSnapshot.CoreDeltaSeconds,
                    latestRunSnapshot.Pattern.GoodWindowSeconds);
                if (anticipation > 0f)
                {
                    float channelDirection = latestRunSnapshot.Pattern.Channel == GreedLastRunChannel.Left
                        ? 1f
                        : latestRunSnapshot.Pattern.Channel == GreedLastRunChannel.Right
                            ? -1f
                            : Mathf.Sign(stride);
                    if (Mathf.Approximately(channelDirection, 0f))
                    {
                        channelDirection = 1f;
                    }

                    ApplyRunnerAnticipationPose(
                        avatarRect,
                        anticipation,
                        channelDirection,
                        bob,
                        stride,
                        runningLimbs,
                        ref shadowOffsetX,
                        ref shadowScaleX,
                        ref shadowAlpha);
                }
            }

            if (remaining <= 0f && countdownReadyStrength > 0f)
            {
                avatarRect.anchoredPosition += new Vector2(0f, BuildRunnerCountdownReadyOffsetY(countdownReadyStrength));
                avatarRect.localScale = new Vector3(
                    BuildRunnerCountdownReadyScaleX(countdownReadyStrength),
                    BuildRunnerCountdownReadyScaleY(countdownReadyStrength),
                    1f);
                avatarRect.localEulerAngles = new Vector3(
                    0f,
                    0f,
                    BuildRunnerCountdownReadyAngle(countdownReadyStrength, beatPhase));
                ApplyRunnerLimbPose(
                    -18f * countdownReadyStrength,
                    18f * countdownReadyStrength,
                    14f * countdownReadyStrength,
                    -14f * countdownReadyStrength);
                SetRunnerBodyColor(Color32.Lerp(
                    runnerBaseColor,
                    PrototypeGoldColor,
                    BuildRunnerCountdownReadyColorBlend(countdownReadyStrength)));
                shadowScaleX += BuildRunnerCountdownReadyShadowScaleXLift(countdownReadyStrength);
                shadowAlpha += BuildRunnerCountdownReadyShadowAlphaLift(countdownReadyStrength);
            }
            else if (remaining <= 0f && launchStepStrength > 0f)
            {
                avatarRect.anchoredPosition += new Vector2(0f, BuildRunnerLaunchStepLift(launchStepStrength));
                Vector3 launchScale = avatarRect.localScale;
                avatarRect.localScale = new Vector3(
                    launchScale.x * BuildRunnerLaunchStepScaleX(launchStepStrength),
                    launchScale.y * BuildRunnerLaunchStepScaleY(launchStepStrength),
                    launchScale.z);
                avatarRect.localEulerAngles += new Vector3(
                    0f,
                    0f,
                    BuildRunnerLaunchStepAngle(launchStepStrength));
                ApplyRunnerLimbPose(
                    -30f * launchStepStrength,
                    24f * launchStepStrength,
                    26f * launchStepStrength,
                    -22f * launchStepStrength);
                SetRunnerBodyColor(Color32.Lerp(
                    runnerBaseColor,
                    PrototypeGoldColor,
                    BuildRunnerLaunchStepColorBlend(launchStepStrength)));
                shadowScaleX += BuildRunnerLaunchStepShadowScaleXLift(launchStepStrength);
                shadowAlpha += BuildRunnerLaunchStepShadowAlphaLift(launchStepStrength);
            }

            if (remaining <= 0f && runEntryThreatRevealStrength > 0f)
            {
                float revealDirection = BuildRunnerEntryThreatDirection(latestRunSnapshot.Pattern.Channel);
                avatarRect.anchoredPosition += new Vector2(
                    BuildRunnerEntryThreatOffsetX(revealDirection, runEntryThreatRevealStrength),
                    BuildRunnerEntryThreatOffsetY(runEntryThreatRevealStrength));
                Vector3 revealScale = avatarRect.localScale;
                avatarRect.localScale = new Vector3(
                    revealScale.x * BuildRunnerEntryThreatScaleX(runEntryThreatRevealStrength),
                    revealScale.y * BuildRunnerEntryThreatScaleY(runEntryThreatRevealStrength),
                    revealScale.z);
                avatarRect.localEulerAngles += new Vector3(
                    0f,
                    0f,
                    BuildRunnerEntryThreatAngle(revealDirection, runEntryThreatRevealStrength));
                Color32 currentRunnerColor = runnerHead != null ? (Color32)runnerHead.color : runnerBaseColor;
                SetRunnerBodyColor(Color32.Lerp(
                    currentRunnerColor,
                    BuildPrototypeTrapAccentColor(latestRunSnapshot.Pattern),
                    BuildRunnerEntryThreatColorBlend(runEntryThreatRevealStrength)));
                shadowOffsetX += BuildRunnerEntryThreatShadowOffsetX(revealDirection, runEntryThreatRevealStrength);
                shadowScaleX += BuildRunnerEntryThreatShadowScaleXLift(runEntryThreatRevealStrength);
                shadowAlpha += BuildRunnerEntryThreatShadowAlphaLift(runEntryThreatRevealStrength);
            }

            float rotationBrace = remaining <= 0f
                ? BuildRunnerRotationCorridorBraceStrength(latestRunSnapshot, runnerBlocked)
                : 0f;
            if (rotationBrace > 0f)
            {
                float rotationDirection = BuildRotationPatternDirection(latestRunSnapshot.Pattern);
                avatarRect.anchoredPosition += new Vector2(
                    BuildRunnerRotationCorridorBraceOffsetX(rotationDirection, rotationBrace),
                    0f);
                Vector3 avatarScale = avatarRect.localScale;
                avatarRect.localScale = new Vector3(
                    avatarScale.x * BuildRunnerRotationCorridorBraceScaleX(rotationBrace),
                    avatarScale.y * BuildRunnerRotationCorridorBraceScaleY(rotationBrace),
                    avatarScale.z);
                avatarRect.localEulerAngles += new Vector3(
                    0f,
                    0f,
                    BuildRunnerRotationCorridorBraceAngle(rotationDirection, rotationBrace));
                Color32 currentRunnerColor = runnerHead != null ? (Color32)runnerHead.color : runnerBaseColor;
                SetRunnerBodyColor(Color32.Lerp(
                    currentRunnerColor,
                    PrototypeGoldColor,
                    BuildRunnerRotationCorridorBraceColorBlend(rotationBrace)));
                shadowOffsetX += BuildRunnerRotationCorridorBraceShadowOffsetX(rotationDirection, rotationBrace);
                shadowScaleX += BuildRunnerRotationCorridorBraceShadowScaleXLift(rotationBrace);
                shadowAlpha += BuildRunnerRotationCorridorBraceShadowAlphaLift(rotationBrace);
            }

            float groundContact = BuildRunnerGroundContactStrength(
                running,
                latestRunSnapshot.ActivePattern,
                runnerBlocked,
                stridePhase,
                latestRunSnapshot.CoreDeltaSeconds,
                latestRunSnapshot.Pattern.IsValid ? latestRunSnapshot.Pattern.GoodWindowSeconds : 0f,
                forwardPulse,
                recoveryPressure);
            float runnerBeatCueUrgency = BuildRunnerBeatCueUrgency(BuildActiveBeatCueUrgency(latestRunSnapshot), groundContact);
            if (groundContact > 0f)
            {
                Vector3 avatarScale = avatarRect.localScale;
                avatarRect.localScale = new Vector3(
                    avatarScale.x * BuildRunnerContactBodyScaleX(groundContact),
                    avatarScale.y * BuildRunnerContactBodyScaleY(groundContact),
                    avatarScale.z);
            }
            if (runnerDownbeatLift > 0f)
            {
                Vector3 avatarScale = avatarRect.localScale;
                avatarRect.localScale = new Vector3(
                    avatarScale.x * BuildRunnerDownbeatBodyScaleX(latestRunSnapshot.Pattern, runnerDownbeatLift),
                    avatarScale.y * BuildRunnerDownbeatBodyScaleY(latestRunSnapshot.Pattern, runnerDownbeatLift),
                    avatarScale.z);
                avatarRect.localEulerAngles += new Vector3(
                    0f,
                    0f,
                    BuildRunnerDownbeatBodyAngleLift(latestRunSnapshot.Pattern, runnerDownbeatLift));
                SetRunnerBodyColor(Color32.Lerp(
                    runnerBaseColor,
                    new Color32(255, 214, 105, 255),
                    BuildRunnerDownbeatBodyColorBlend(runnerDownbeatLift)));
                shadowScaleX += BuildRunnerDownbeatShadowScaleXLift(runnerDownbeatLift);
                shadowAlpha += BuildRunnerDownbeatShadowAlphaLift(runnerDownbeatLift);
            }
            if (runnerBeatCueUrgency > 0f)
            {
                Vector3 avatarScale = avatarRect.localScale;
                avatarRect.localScale = new Vector3(
                    avatarScale.x * BuildRunnerBeatCueUrgencyBodyScaleX(latestRunSnapshot.Pattern, runnerBeatCueUrgency),
                    avatarScale.y * BuildRunnerBeatCueUrgencyBodyScaleY(latestRunSnapshot.Pattern, runnerBeatCueUrgency),
                    avatarScale.z);
                avatarRect.localEulerAngles += new Vector3(
                    0f,
                    0f,
                    BuildRunnerBeatCueUrgencyBodyAngleLift(latestRunSnapshot.Pattern, runnerBeatCueUrgency));
                Color32 currentRunnerColor = runnerHead != null ? (Color32)runnerHead.color : runnerBaseColor;
                SetRunnerBodyColor(Color32.Lerp(
                    currentRunnerColor,
                    new Color32(255, 238, 181, 255),
                    BuildRunnerBeatCueUrgencyBodyColorBlend(runnerBeatCueUrgency)));
                shadowScaleX += BuildRunnerBeatCueUrgencyShadowScaleXLift(runnerBeatCueUrgency);
                shadowAlpha += BuildRunnerBeatCueUrgencyShadowAlphaLift(runnerBeatCueUrgency);
            }

            RunnerResponseType silhouetteResponse = RunnerResponseType.None;
            float silhouetteStrength = 0f;
            float silhouetteDirection = Mathf.Sign(Mathf.Sin(beatPhase * Mathf.PI * 2f));
            if (Mathf.Approximately(silhouetteDirection, 0f))
            {
                silhouetteDirection = 1f;
            }

            if (remaining > 0f
                && runnerResponseType != RunnerResponseType.None
                && runnerResponseResult != GreedLastJudgementResult.None)
            {
                float duration = Mathf.Max(0.01f, runnerResponseUntil - runnerResponseStartedAt);
                float progress = Mathf.Clamp01((Time.unscaledTime - runnerResponseStartedAt) / duration);
                float arc = Mathf.Sin(progress * Mathf.PI);
                silhouetteResponse = runnerResponseType;
                silhouetteStrength = Mathf.Clamp01(arc * (runnerResponseResult == GreedLastJudgementResult.Good ? 0.74f : 1f));
                float responseDirection = BuildRunnerActionTrailDirection(runnerResponseChannel);
                silhouetteDirection = Mathf.Approximately(responseDirection, 0f)
                    ? silhouetteDirection
                    : responseDirection;
            }
            else if (running
                && latestRunSnapshot.ActivePattern
                && latestRunSnapshot.Pattern.IsValid
                && !runnerBlocked)
            {
                silhouetteResponse = BuildRunnerResponseType(latestRunSnapshot.Pattern);
                silhouetteStrength = Mathf.Max(
                    BuildRunnerAnticipationStrength(
                        latestRunSnapshot.ActivePattern,
                        runnerBlocked,
                        latestRunSnapshot.CoreDeltaSeconds,
                        latestRunSnapshot.Pattern.GoodWindowSeconds) * 0.76f,
                    Mathf.Max(
                        Mathf.Max(runnerDownbeatLift, runnerBeatCueUrgency),
                        BuildRunnerEntryThreatSilhouetteStrength(runEntryThreatRevealStrength)));
                silhouetteDirection = BuildRunnerPreparationCueDirection(latestRunSnapshot.Pattern, silhouetteDirection);
            }

            if (rotationBrace > 0f)
            {
                silhouetteResponse = RunnerResponseType.Twist;
                silhouetteStrength = Mathf.Max(silhouetteStrength, rotationBrace);
                silhouetteDirection = BuildRotationPatternDirection(latestRunSnapshot.Pattern);
            }

            ApplyRunnerPrototypeSilhouettePose(
                silhouetteResponse,
                silhouetteStrength,
                silhouetteDirection,
                running ? stride : 0f);

            float runEntranceHandoffProgress = BuildRunEntranceHandoffProgress(
                runVisible,
                Time.unscaledTime,
                runEntranceHandoffStartedAt,
                runEntranceHandoffUntil);
            if (runEntranceHandoffProgress < 1f)
            {
                avatarRect.anchoredPosition += new Vector2(
                    0f,
                    BuildRunEntranceRunnerOffsetY(runEntranceHandoffProgress));
                float entranceScale = BuildRunEntranceRunnerScale(runEntranceHandoffProgress);
                avatarRect.localScale = new Vector3(
                    avatarRect.localScale.x * entranceScale,
                    avatarRect.localScale.y * entranceScale,
                    avatarRect.localScale.z);
                float entranceAlpha = BuildRunEntranceRunnerAlpha(
                    runEntranceHandoffProgress,
                    runEntranceHandoffPortalReady,
                    runEntranceHandoffPracticeFirst);
                if (runnerAvatarCanvasGroup != null)
                {
                    runnerAvatarCanvasGroup.alpha = entranceAlpha;
                }

                shadowScaleX *= entranceScale;
                shadowAlpha *= entranceAlpha;
            }

            avatarRect.localScale = new Vector3(avatarRect.localScale.x * PrototypeRunAvatarScale,
                avatarRect.localScale.y * PrototypeRunAvatarScale, avatarRect.localScale.z);
            shadowScaleX *= 1.25f;
            shadowScaleX = BuildRunnerShadowContactScaleX(shadowScaleX, groundContact, recoveryPressure);
            float shadowScaleY = BuildRunnerShadowContactScaleY(shadowScaleX, groundContact, recoveryPressure);
            shadowAlpha = BuildRunnerShadowContactAlpha(shadowAlpha, groundContact, recoveryPressure);
            runnerShadow.rectTransform.anchoredPosition = new Vector2(shadowOffsetX, 0f);
            runnerShadow.rectTransform.localScale = new Vector3(shadowScaleX, shadowScaleY, 1f);
            runnerShadow.color = new Color32(0, 0, 0, (byte)Mathf.Clamp(Mathf.RoundToInt(shadowAlpha), 0, 180));
            if (coreVisible)
            {
                float corePulse = GetGameplayBeatPulse();
                float readyPulse = focusReadyGlow * Mathf.Lerp(0.62f, 1f, corePulse);
                float readyDownbeatLift = BuildFocusReadyCoreDownbeatLift(
                    ShouldShowDownbeatPulse(latestRunSnapshot) ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime) : 0f,
                    focusReadyGlow,
                    latestRunSnapshot.ActivePattern);
                runnerCoreGlow.rectTransform.anchoredPosition = avatarRect.anchoredPosition * 0.42f;
                runnerCoreGlow.rectTransform.localScale = Vector3.one * (Mathf.Lerp(0.78f, 1.16f, corePulse)
                    + readyPulse * 0.10f
                    + BuildFocusReadyCoreDownbeatScaleLift(readyDownbeatLift)
                    + BuildRunnerBeatCueUrgencyCoreScaleLift(runnerBeatCueUrgency));
                int coreAlpha = Mathf.RoundToInt(Mathf.Lerp(
                    latestRunSnapshot.FocusStateActive ? 34f : focusReadyGlow > 0f ? 28f : 42f,
                    coreRecovered ? 116f : latestRunSnapshot.FocusStateActive ? 86f : 72f + focusReadyGlow * 38f,
                    corePulse));
                coreAlpha += BuildFocusReadyCoreDownbeatAlphaLift(readyDownbeatLift);
                coreAlpha += BuildRunnerBeatCueUrgencyCoreAlphaLift(runnerBeatCueUrgency);
                Color32 auraColor = coreRecovered
                    ? new Color32(255, 196, 74, 255)
                    : latestRunSnapshot.FocusStateActive
                        ? new Color32(255, 214, 105, 255)
                        : Color32.Lerp(new Color32(145, 231, 199, 255), new Color32(255, 238, 181, 255), readyPulse * 0.55f);
                auraColor = Color32.Lerp(
                    auraColor,
                    new Color32(255, 248, 210, 255),
                    BuildFocusReadyCoreDownbeatColorBlend(readyDownbeatLift));
                auraColor = Color32.Lerp(
                    auraColor,
                    new Color32(255, 248, 210, 255),
                    BuildRunnerBeatCueUrgencyCoreColorBlend(runnerBeatCueUrgency));
                auraColor.a = (byte)Mathf.Clamp(coreAlpha, 0, 255);
                runnerCoreGlow.color = auraColor;
            }

            UpdateRunnerFootfallPips(
                avatarRect.anchoredPosition,
                running,
                runnerBlocked,
                stridePhase,
                groundContact,
                runnerDownbeatLift,
                runnerBeatCueUrgency,
                recoveryPressure,
                launchStepStrength);
            UpdateRunnerPreparationCue(
                avatarRect.anchoredPosition,
                avatarRect.localEulerAngles.z,
                running,
                runnerBlocked,
                remaining,
                runnerDownbeatLift,
                runnerBeatCueUrgency);
            UpdateRunnerActionTrails(
                avatarRect.anchoredPosition,
                avatarRect.localScale,
                avatarRect.localEulerAngles.z);
        }

        private static float BuildFocusReadyCoreGlow(GreedLastRunSnapshot snapshot)
        {
            return BuildFocusReadyCoreGlowFromValues(
                snapshot.Focus,
                snapshot.MaxFocus,
                snapshot.PrecisionStreak,
                snapshot.ActivePattern,
                snapshot.FocusStateActive,
                snapshot.Stopped,
                snapshot.Paused,
                snapshot.ChoiceActive,
                snapshot.CountdownActive);
        }

        private static float BuildFocusReadyCoreGlowFromValues(
            int focus,
            int maxFocus,
            int precisionStreak,
            bool activePattern,
            bool focusStateActive,
            bool stopped,
            bool paused,
            bool choiceActive,
            bool countdownActive)
        {
            if (focusStateActive
                || stopped
                || paused
                || choiceActive
                || countdownActive
                || maxFocus <= 1
                || focus < maxFocus - 1)
            {
                return 0f;
            }

            float readiness = Mathf.Clamp01(focus / (float)Mathf.Max(1, maxFocus));
            float patternPressure = activePattern ? 0.12f : 0f;
            float precisionHint = Mathf.Clamp01(precisionStreak / (float)PrecisionFocusStepUi) * 0.10f;
            return Mathf.Clamp01(0.48f + readiness * 0.34f + patternPressure + precisionHint);
        }

        private static float BuildFocusReadyCoreDownbeatLift(float downbeatPulse, float focusReadyGlow, bool activePattern)
        {
            if (focusReadyGlow <= 0f)
            {
                return 0f;
            }

            float patternWeight = activePattern ? 1f : 0.56f;
            return Mathf.Clamp01(downbeatPulse) * Mathf.Clamp01(focusReadyGlow) * patternWeight;
        }

        private static float BuildFocusReadyCoreDownbeatScaleLift(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.10f;
        }

        private static int BuildFocusReadyCoreDownbeatAlphaLift(float downbeatLift)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(downbeatLift) * 28f);
        }

        private static float BuildFocusReadyCoreDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.34f;
        }

        private void UpdateRunnerActionTrails(
            Vector2 avatarPosition,
            Vector3 avatarScale,
            float avatarAngle)
        {
            if (runnerActionTrails == null)
            {
                return;
            }

            float remaining = runnerResponseUntil - Time.unscaledTime;
            float duration = Mathf.Max(0.01f, runnerResponseUntil - runnerResponseStartedAt);
            if (remaining <= 0f
                || runnerResponseResult == GreedLastJudgementResult.None
                || runnerResponseType == RunnerResponseType.None
                || !CanShowRunTransientFeedback())
            {
                HideRunnerActionTrails();
                return;
            }

            float progress = Mathf.Clamp01((Time.unscaledTime - runnerResponseStartedAt) / duration);
            float direction = BuildRunnerActionTrailDirection(runnerResponseChannel);
            for (int i = 0; i < runnerActionTrails.Length; i += 1)
            {
                Image trail = runnerActionTrails[i];
                if (trail == null)
                {
                    continue;
                }

                float sequence = (i + 1f) / (runnerActionTrails.Length + 1f);
                RectTransform rect = trail.rectTransform;
                rect.anchorMin = new Vector2(0.5f, 0.155f);
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = avatarPosition + new Vector2(
                    BuildRunnerActionTrailOffsetX(runnerResponseType, direction, runnerResponseResult, progress, sequence),
                    BuildRunnerActionTrailOffsetY(runnerResponseType, runnerResponseResult, progress, sequence));
                rect.sizeDelta = new Vector2(
                    BuildRunnerActionTrailWidth(runnerResponseType, sequence),
                    BuildRunnerActionTrailHeight(runnerResponseType, sequence));
                rect.localScale = new Vector3(
                    Mathf.Max(0.05f, avatarScale.x) * BuildRunnerActionTrailScaleX(runnerResponseType, runnerResponseResult, progress, sequence),
                    Mathf.Max(0.05f, avatarScale.y) * BuildRunnerActionTrailScaleY(runnerResponseType, runnerResponseResult, progress, sequence),
                    1f);
                rect.localEulerAngles = new Vector3(
                    0f,
                    0f,
                    avatarAngle + BuildRunnerActionTrailAngle(runnerResponseType, direction, runnerResponseResult, progress, sequence));
                trail.color = WithAlpha(
                    BuildRunnerActionTrailColor(runnerResponseColor, runnerResponseResult, progress, sequence),
                    BuildRunnerActionTrailAlpha(runnerResponseResult, progress, sequence));
            }
        }

        private void HideRunnerActionTrails()
        {
            if (runnerActionTrails == null)
            {
                return;
            }

            for (int i = 0; i < runnerActionTrails.Length; i += 1)
            {
                Image trail = runnerActionTrails[i];
                if (trail == null)
                {
                    continue;
                }

                trail.color = new Color32(255, 238, 181, 0);
                trail.rectTransform.localScale = Vector3.one;
                trail.rectTransform.localEulerAngles = Vector3.zero;
            }
        }

        private void UpdateRunnerPreparationCue(
            Vector2 avatarPosition,
            float avatarAngle,
            bool running,
            bool runnerBlocked,
            float responseRemaining,
            float downbeatLift,
            float beatCueUrgency)
        {
            if (runnerPreparationCue == null)
            {
                return;
            }

            bool activePreparation = running
                && latestRunSnapshot.ActivePattern
                && latestRunSnapshot.Pattern.IsValid
                && responseRemaining <= 0f
                && CanShowRunTransientFeedback();
            float readiness = BuildRunnerAnticipationStrength(
                activePreparation,
                runnerBlocked,
                latestRunSnapshot.CoreDeltaSeconds,
                latestRunSnapshot.Pattern.GoodWindowSeconds);
            int alpha = BuildRunnerPreparationCueAlpha(
                latestRunSnapshot.Pattern,
                activePreparation,
                runnerBlocked,
                readiness,
                beatCueUrgency,
                downbeatLift);
            if (alpha <= 0)
            {
                HideRunnerPreparationCue();
                return;
            }

            float fallbackDirection = Mathf.Sign(Mathf.Sin(beatPhase * Mathf.PI * 2f));
            float direction = BuildRunnerPreparationCueDirection(latestRunSnapshot.Pattern, fallbackDirection);
            Vector4 layout = BuildRunnerPreparationCueLayout(latestRunSnapshot.Pattern, readiness, direction);
            RectTransform rect = runnerPreparationCue.rectTransform;
            rect.anchorMin = new Vector2(0.5f, 0.155f);
            rect.anchorMax = rect.anchorMin;
            rect.anchoredPosition = avatarPosition + new Vector2(layout.x, layout.y);
            rect.sizeDelta = new Vector2(layout.z, layout.w);
            float scale = BuildRunnerPreparationCueScale(readiness, downbeatLift);
            rect.localScale = new Vector3(scale, scale, 1f);
            rect.localEulerAngles = new Vector3(
                0f,
                0f,
                avatarAngle * 0.32f + BuildRunnerPreparationCueAngle(latestRunSnapshot.Pattern, readiness, direction));
            Color32 cueColor = Color32.Lerp(
                GetRunnerResponseAtmosphereColor(BuildRunnerResponseType(latestRunSnapshot.Pattern)),
                new Color32(255, 248, 210, 255),
                BuildRunnerPreparationCueColorBlend(readiness, beatCueUrgency, downbeatLift));
            runnerPreparationCue.gameObject.SetActive(true);
            runnerPreparationCue.color = WithAlpha(cueColor, alpha);

            if (runnerPreparationSymbolText != null)
            {
                Vector4 symbolLayout = BuildRunnerPreparationSymbolLayout(latestRunSnapshot.Pattern, readiness, direction);
                int symbolAlpha = BuildRunnerPreparationSymbolAlpha(
                    latestRunSnapshot.Pattern,
                    activePreparation,
                    runnerBlocked,
                    readiness,
                    beatCueUrgency,
                    downbeatLift);
                if (symbolAlpha <= 0)
                {
                    runnerPreparationSymbolText.text = string.Empty;
                    runnerPreparationSymbolText.color = new Color32(255, 238, 181, 0);
                    runnerPreparationSymbolText.gameObject.SetActive(false);
                }
                else
                {
                    runnerPreparationSymbolText.text = BuildRunnerResponseSymbol(latestRunSnapshot.Pattern);
                    runnerPreparationSymbolText.fontSize = Mathf.RoundToInt(symbolLayout.z);
                    runnerPreparationSymbolText.rectTransform.anchorMin = new Vector2(0.5f, 0.155f);
                    runnerPreparationSymbolText.rectTransform.anchorMax = runnerPreparationSymbolText.rectTransform.anchorMin;
                    runnerPreparationSymbolText.rectTransform.anchoredPosition = avatarPosition + new Vector2(symbolLayout.x, symbolLayout.y);
                    runnerPreparationSymbolText.rectTransform.localScale = Vector3.one * symbolLayout.w;
                    runnerPreparationSymbolText.rectTransform.localEulerAngles = new Vector3(
                        0f,
                        0f,
                        BuildRunnerPreparationSymbolAngle(latestRunSnapshot.Pattern, readiness, direction));
                    runnerPreparationSymbolText.color = WithAlpha(cueColor, symbolAlpha);
                    runnerPreparationSymbolText.gameObject.SetActive(true);
                }
            }
        }

        private void KeepRunnerCuesAboveTimingGuide()
        {
            if (timingGuideText == null || !timingGuideText.isActiveAndEnabled
                || timingGuideText.color.a < 0.01f || string.IsNullOrWhiteSpace(timingGuideText.text)) return;

            Transform parent = timingGuideText.transform.parent;
            Rect guide = GetRunnerCueBounds(timingGuideText.rectTransform, parent);
            KeepRunnerCueAboveGuide(runnerPreparationCue, parent, guide);
            KeepRunnerCueAboveGuide(runnerPreparationSymbolText, parent, guide);
            if (runnerFootfallPips == null) return;
            foreach (Image pip in runnerFootfallPips) KeepRunnerCueAboveGuide(pip, parent, guide);
        }

        private void KeepRunnerCueAboveGuide(Graphic cue, Transform parent, Rect guide)
        {
            if (cue == null || !cue.isActiveAndEnabled || cue.color.a < 0.01f) return;
            Rect area = GetRunnerCueBounds(cue.rectTransform, parent);
            if (area.xMax <= guide.xMin || area.xMin >= guide.xMax) return;
            float lift = guide.yMax + 8f - area.yMin;
            if (lift <= 0f) return;
            // Measure after pose/rotation and text pulses so foot effects never strike through the HUD.
            cue.rectTransform.position += parent.TransformVector(new Vector3(0f, lift, 0f));
        }

        private Rect GetRunnerCueBounds(RectTransform rect, Transform parent)
        {
            rect.GetWorldCorners(runnerCueCorners);
            Vector2 min = new Vector2(float.PositiveInfinity, float.PositiveInfinity);
            Vector2 max = new Vector2(float.NegativeInfinity, float.NegativeInfinity);
            for (int i = 0; i < runnerCueCorners.Length; i++)
            {
                Vector2 point = parent.InverseTransformPoint(runnerCueCorners[i]);
                min = Vector2.Min(min, point);
                max = Vector2.Max(max, point);
            }
            return Rect.MinMaxRect(min.x, min.y, max.x, max.y);
        }

        private void UpdateRunnerFootfallPips(
            Vector2 avatarPosition,
            bool running,
            bool runnerBlocked,
            float stridePhase,
            float groundContact,
            float downbeatLift,
            float beatCueUrgency,
            float recoveryPressure,
            float launchStepStrength)
        {
            if (runnerFootfallPips == null)
            {
                return;
            }

            if (!ShouldShowRunnerFootfallPips(
                    running,
                    runnerBlocked,
                    CanShowRunTransientFeedback(),
                    launchStepStrength))
            {
                HideRunnerFootfallPips();
                return;
            }

            float visibleGroundContact = BuildRunnerLaunchFootfallGroundContact(
                groundContact,
                launchStepStrength);
            float visibleDownbeatLift = BuildRunnerLaunchFootfallDownbeatLift(
                downbeatLift,
                launchStepStrength);
            float visibleBeatCueUrgency = BuildRunnerLaunchFootfallBeatCueUrgency(
                beatCueUrgency,
                launchStepStrength);

            for (int i = 0; i < runnerFootfallPips.Length; i += 1)
            {
                Image pip = runnerFootfallPips[i];
                if (pip == null)
                {
                    continue;
                }

                float footPlant = Mathf.Max(
                    BuildRunnerFootfallPipPlant(stridePhase, i),
                    BuildRunnerLaunchFootPlant(i, launchStepStrength));
                RectTransform rect = pip.rectTransform;
                rect.anchorMin = new Vector2(0.5f, 0.155f);
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = avatarPosition + new Vector2(
                    BuildRunnerFootfallPipOffsetX(i, visibleGroundContact, recoveryPressure),
                    BuildRunnerFootfallPipOffsetY(visibleGroundContact, recoveryPressure));
                rect.sizeDelta = new Vector2(
                    BuildRunnerFootfallPipWidth(footPlant, visibleGroundContact, visibleDownbeatLift),
                    BuildRunnerFootfallPipHeight(footPlant, visibleGroundContact, recoveryPressure));
                rect.localScale = new Vector3(
                    BuildRunnerFootfallPipScaleX(footPlant, visibleGroundContact, visibleBeatCueUrgency),
                    BuildRunnerFootfallPipScaleY(footPlant, visibleGroundContact, visibleDownbeatLift),
                    1f);
                rect.localEulerAngles = new Vector3(0f, 0f, BuildRunnerFootfallPipAngle(i, footPlant, recoveryPressure));
                Color32 footColor = Color32.Lerp(
                    new Color32(145, 231, 199, 255),
                    new Color32(255, 238, 181, 255),
                    BuildRunnerFootfallPipColorBlend(footPlant, visibleDownbeatLift, visibleBeatCueUrgency));
                pip.color = WithAlpha(
                    footColor,
                    BuildRunnerFootfallPipAlpha(
                        running,
                        runnerBlocked,
                        footPlant,
                        visibleGroundContact,
                        visibleDownbeatLift,
                        visibleBeatCueUrgency,
                        recoveryPressure));
            }
        }

        private static bool ShouldShowRunnerFootfallPips(
            bool running,
            bool blocked,
            bool transientFeedbackVisible,
            float launchStepStrength)
        {
            return running
                && !blocked
                && (transientFeedbackVisible || launchStepStrength > 0f);
        }

        private static float BuildRunnerLaunchFootPlant(int footIndex, float launchStepStrength)
        {
            float strength = Mathf.Clamp01(launchStepStrength);
            return Mathf.Clamp(footIndex, 0, RunnerFootfallPipCount - 1) == 0
                ? strength
                : strength * 0.42f;
        }

        private static float BuildRunnerLaunchFootfallGroundContact(float groundContact, float launchStepStrength)
        {
            return Mathf.Max(Mathf.Clamp01(groundContact), Mathf.Clamp01(launchStepStrength) * 0.92f);
        }

        private static float BuildRunnerLaunchFootfallDownbeatLift(float downbeatLift, float launchStepStrength)
        {
            return Mathf.Max(Mathf.Clamp01(downbeatLift), Mathf.Clamp01(launchStepStrength) * 0.78f);
        }

        private static float BuildRunnerLaunchFootfallBeatCueUrgency(float beatCueUrgency, float launchStepStrength)
        {
            return Mathf.Max(Mathf.Clamp01(beatCueUrgency), Mathf.Clamp01(launchStepStrength) * 0.68f);
        }

        private void HideRunnerFootfallPips()
        {
            if (runnerFootfallPips == null)
            {
                return;
            }

            for (int i = 0; i < runnerFootfallPips.Length; i += 1)
            {
                Image pip = runnerFootfallPips[i];
                if (pip == null)
                {
                    continue;
                }

                pip.color = new Color32(255, 238, 181, 0);
                pip.rectTransform.localScale = Vector3.one;
                pip.rectTransform.localEulerAngles = Vector3.zero;
            }
        }

        private static float BuildRunnerFootfallPipPlant(float stridePhase, int index)
        {
            int safeIndex = Mathf.Clamp(index, 0, RunnerFootfallPipCount - 1);
            float phase = Mathf.Repeat(Mathf.Clamp01(stridePhase) + safeIndex * 0.5f, 1f);
            return Mathf.Pow(Mathf.Clamp01(Mathf.Cos(phase * Mathf.PI * 2f)), 1.7f);
        }

        private static int BuildRunnerFootfallPipAlpha(
            bool running,
            bool blocked,
            float footPlant,
            float groundContact,
            float downbeatLift,
            float beatCueUrgency,
            float recoveryPressure)
        {
            if (!running || blocked)
            {
                return 0;
            }

            float plant = Mathf.Clamp01(footPlant);
            float contact = Mathf.Clamp01(groundContact);
            if (plant <= 0f && contact <= 0.02f)
            {
                return 0;
            }

            float alpha = plant * Mathf.Lerp(34f, 94f, contact)
                + contact * 18f
                + Mathf.Clamp01(downbeatLift) * 16f
                + Mathf.Clamp01(beatCueUrgency) * 12f
                + Mathf.Clamp01(recoveryPressure) * 24f;
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 150f));
        }

        private static float BuildRunnerFootfallPipOffsetX(int index, float groundContact, float recoveryPressure)
        {
            float side = index == 0 ? -1f : 1f;
            return side * (Mathf.Lerp(16f, 23f, Mathf.Clamp01(groundContact)) + Mathf.Clamp01(recoveryPressure) * 5f);
        }

        private static float BuildRunnerFootfallPipOffsetY(float groundContact, float recoveryPressure)
        {
            return Mathf.Lerp(-47f, -53f, Mathf.Clamp01(groundContact)) - Mathf.Clamp01(recoveryPressure) * 3f;
        }

        private static float BuildRunnerFootfallPipWidth(float footPlant, float groundContact, float downbeatLift)
        {
            return Mathf.Lerp(18f, 38f, Mathf.Clamp01(footPlant))
                + Mathf.Clamp01(groundContact) * 5f
                + Mathf.Clamp01(downbeatLift) * 4f;
        }

        private static float BuildRunnerFootfallPipHeight(float footPlant, float groundContact, float recoveryPressure)
        {
            return Mathf.Lerp(4f, 9f, Mathf.Clamp01(footPlant))
                + Mathf.Clamp01(groundContact) * 1.5f
                + Mathf.Clamp01(recoveryPressure) * 2f;
        }

        private static float BuildRunnerFootfallPipScaleX(float footPlant, float groundContact, float beatCueUrgency)
        {
            return 1f
                + Mathf.Clamp01(footPlant) * 0.12f
                + Mathf.Clamp01(groundContact) * 0.08f
                + Mathf.Clamp01(beatCueUrgency) * 0.05f;
        }

        private static float BuildRunnerFootfallPipScaleY(float footPlant, float groundContact, float downbeatLift)
        {
            return 1f
                - Mathf.Clamp01(groundContact) * 0.05f
                + Mathf.Clamp01(footPlant) * 0.03f
                + Mathf.Clamp01(downbeatLift) * 0.04f;
        }

        private static float BuildRunnerFootfallPipAngle(int index, float footPlant, float recoveryPressure)
        {
            float side = index == 0 ? -1f : 1f;
            return side * Mathf.Lerp(5f, 9f, Mathf.Clamp01(footPlant))
                + side * Mathf.Clamp01(recoveryPressure) * 4f;
        }

        private static float BuildRunnerFootfallPipColorBlend(
            float footPlant,
            float downbeatLift,
            float beatCueUrgency)
        {
            return Mathf.Clamp01(
                Mathf.Clamp01(footPlant) * 0.36f
                + Mathf.Clamp01(downbeatLift) * 0.22f
                + Mathf.Clamp01(beatCueUrgency) * 0.14f);
        }

        private void HideRunnerPreparationCue()
        {
            if (runnerPreparationCue == null)
            {
                return;
            }

            runnerPreparationCue.color = new Color32(255, 238, 181, 0);
            runnerPreparationCue.rectTransform.localScale = Vector3.one;
            runnerPreparationCue.rectTransform.localEulerAngles = Vector3.zero;
            runnerPreparationCue.gameObject.SetActive(false);
            if (runnerPreparationSymbolText != null)
            {
                runnerPreparationSymbolText.text = string.Empty;
                runnerPreparationSymbolText.color = new Color32(255, 238, 181, 0);
                runnerPreparationSymbolText.rectTransform.localScale = Vector3.one;
                runnerPreparationSymbolText.rectTransform.localEulerAngles = Vector3.zero;
                runnerPreparationSymbolText.gameObject.SetActive(false);
            }
        }

        private static float BuildRunnerActionTrailDirection(GreedLastRunChannel channel)
        {
            switch (channel)
            {
                case GreedLastRunChannel.Left:
                    return 1f;
                case GreedLastRunChannel.Right:
                    return -1f;
                default:
                    return 0f;
            }
        }

        private static int BuildRunnerActionTrailAlpha(
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            if (result == GreedLastJudgementResult.None)
            {
                return 0;
            }

            float safeProgress = Mathf.Clamp01(progress);
            float safeSequence = Mathf.Clamp01(sequence);
            float fade = 1f - Mathf.Clamp01((safeProgress - safeSequence * 0.08f) / 0.92f);
            float sequenceFalloff = Mathf.Lerp(1f, 0.56f, safeSequence);
            float baseAlpha = result == GreedLastJudgementResult.Success
                ? 108f
                : result == GreedLastJudgementResult.Good ? 74f : 92f;
            return Mathf.RoundToInt(baseAlpha * fade * sequenceFalloff);
        }

        private static float BuildRunnerActionTrailOffsetXForPattern(
            GreedLastPatternModel pattern,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            return BuildRunnerActionTrailOffsetX(
                BuildRunnerResponseType(pattern),
                BuildRunnerActionTrailDirection(pattern.Channel),
                result,
                progress,
                sequence);
        }

        private static float BuildRunnerActionTrailOffsetYForPattern(
            GreedLastPatternModel pattern,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            return BuildRunnerActionTrailOffsetY(BuildRunnerResponseType(pattern), result, progress, sequence);
        }

        private static float BuildRunnerActionTrailScaleXForPattern(
            GreedLastPatternModel pattern,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            return BuildRunnerActionTrailScaleX(BuildRunnerResponseType(pattern), result, progress, sequence);
        }

        private static float BuildRunnerActionTrailScaleYForPattern(
            GreedLastPatternModel pattern,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            return BuildRunnerActionTrailScaleY(BuildRunnerResponseType(pattern), result, progress, sequence);
        }

        private static float BuildRunnerActionTrailAngleForPattern(
            GreedLastPatternModel pattern,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            return BuildRunnerActionTrailAngle(
                BuildRunnerResponseType(pattern),
                BuildRunnerActionTrailDirection(pattern.Channel),
                result,
                progress,
                sequence);
        }

        private static float BuildRunnerActionTrailWidthForPattern(GreedLastPatternModel pattern, float sequence)
        {
            return BuildRunnerActionTrailWidth(BuildRunnerResponseType(pattern), sequence);
        }

        private static float BuildRunnerActionTrailHeightForPattern(GreedLastPatternModel pattern, float sequence)
        {
            return BuildRunnerActionTrailHeight(BuildRunnerResponseType(pattern), sequence);
        }

        private static float BuildRunnerActionTrailOffsetX(
            RunnerResponseType response,
            float direction,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            float safeProgress = Mathf.Clamp01(progress);
            float safeSequence = Mathf.Clamp01(sequence);
            float lag = Mathf.Lerp(1f, 0.22f, safeProgress) * Mathf.Lerp(0.55f, 1f, safeSequence);
            float resultWeight = result == GreedLastJudgementResult.Good ? 0.70f : result == GreedLastJudgementResult.Miss ? 0.52f : 1f;
            switch (response)
            {
                case RunnerResponseType.Slide:
                    return Mathf.Sign(direction) * 18f * lag * resultWeight;
                case RunnerResponseType.Twist:
                    return Mathf.Sign(direction) * 42f * lag * resultWeight;
                case RunnerResponseType.Jump:
                    return Mathf.Sign(direction) * 8f * lag * resultWeight;
                default:
                    return 0f;
            }
        }

        private static float BuildRunnerActionTrailOffsetY(
            RunnerResponseType response,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            float safeProgress = Mathf.Clamp01(progress);
            float safeSequence = Mathf.Clamp01(sequence);
            float lag = Mathf.Lerp(1f, 0.25f, safeProgress) * Mathf.Lerp(0.52f, 1f, safeSequence);
            float resultWeight = result == GreedLastJudgementResult.Good ? 0.70f : result == GreedLastJudgementResult.Miss ? 0.48f : 1f;
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return -58f * lag * resultWeight;
                case RunnerResponseType.Slide:
                    return 24f * lag * resultWeight;
                case RunnerResponseType.Twist:
                    return -10f * lag * resultWeight;
                default:
                    return 0f;
            }
        }

        private static float BuildRunnerActionTrailScaleX(
            RunnerResponseType response,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            float arc = Mathf.Sin(Mathf.Clamp01(progress) * Mathf.PI);
            float sequenceLift = Mathf.Lerp(0.94f, 1.10f, Mathf.Clamp01(sequence));
            float resultLift = result == GreedLastJudgementResult.Success ? 1f : result == GreedLastJudgementResult.Good ? 0.55f : 0.34f;
            switch (response)
            {
                case RunnerResponseType.Slide:
                    return sequenceLift + arc * resultLift * 0.18f;
                case RunnerResponseType.Twist:
                    return sequenceLift - arc * resultLift * 0.10f;
                case RunnerResponseType.Jump:
                    return sequenceLift - arc * resultLift * 0.04f;
                default:
                    return 1f;
            }
        }

        private static float BuildRunnerActionTrailScaleY(
            RunnerResponseType response,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            float arc = Mathf.Sin(Mathf.Clamp01(progress) * Mathf.PI);
            float sequenceLift = Mathf.Lerp(0.88f, 1.04f, Mathf.Clamp01(sequence));
            float resultLift = result == GreedLastJudgementResult.Success ? 1f : result == GreedLastJudgementResult.Good ? 0.55f : 0.40f;
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return sequenceLift + arc * resultLift * 0.17f;
                case RunnerResponseType.Slide:
                    return sequenceLift - arc * resultLift * 0.13f;
                case RunnerResponseType.Twist:
                    return sequenceLift + arc * resultLift * 0.10f;
                default:
                    return 1f;
            }
        }

        private static float BuildRunnerActionTrailAngle(
            RunnerResponseType response,
            float direction,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            float safeProgress = Mathf.Clamp01(progress);
            float safeSequence = Mathf.Clamp01(sequence);
            float resultWeight = result == GreedLastJudgementResult.Success ? 1f : result == GreedLastJudgementResult.Good ? 0.68f : 0.42f;
            switch (response)
            {
                case RunnerResponseType.Slide:
                    return -Mathf.Sign(direction) * Mathf.Lerp(8f, 2f, safeProgress) * resultWeight * safeSequence;
                case RunnerResponseType.Twist:
                    return -Mathf.Sign(direction) * Mathf.Lerp(18f, 4f, safeProgress) * resultWeight * safeSequence;
                case RunnerResponseType.Jump:
                    return Mathf.Sign(direction) * Mathf.Lerp(4f, 1f, safeProgress) * resultWeight * safeSequence;
                default:
                    return 0f;
            }
        }

        private static float BuildRunnerActionTrailWidth(RunnerResponseType response, float sequence)
        {
            float safeSequence = Mathf.Clamp01(sequence);
            switch (response)
            {
                case RunnerResponseType.Slide:
                    return Mathf.Lerp(88f, 118f, safeSequence);
                case RunnerResponseType.Twist:
                    return Mathf.Lerp(58f, 78f, safeSequence);
                case RunnerResponseType.Jump:
                    return Mathf.Lerp(62f, 82f, safeSequence);
                default:
                    return 70f;
            }
        }

        private static float BuildRunnerActionTrailHeight(RunnerResponseType response, float sequence)
        {
            float safeSequence = Mathf.Clamp01(sequence);
            switch (response)
            {
                case RunnerResponseType.Slide:
                    return Mathf.Lerp(78f, 104f, safeSequence);
                case RunnerResponseType.Twist:
                    return Mathf.Lerp(126f, 156f, safeSequence);
                case RunnerResponseType.Jump:
                    return Mathf.Lerp(138f, 172f, safeSequence);
                default:
                    return 124f;
            }
        }

        private static Color32 BuildRunnerActionTrailColor(
            Color32 responseColor,
            GreedLastJudgementResult result,
            float progress,
            float sequence)
        {
            if (result == GreedLastJudgementResult.Miss)
            {
                return Color32.Lerp(
                    PrototypeVermilionColor,
                    new Color32(255, 190, 154, 255),
                    Mathf.Clamp01(progress) * 0.24f + Mathf.Clamp01(sequence) * 0.10f);
            }

            Color32 target = result == GreedLastJudgementResult.Success
                ? new Color32(255, 248, 210, 255)
                : new Color32(145, 231, 199, 255);
            return Color32.Lerp(responseColor, target, Mathf.Clamp01(progress) * 0.22f + Mathf.Clamp01(sequence) * 0.12f);
        }

        private static Vector4 BuildRunnerPreparationCueLayout(
            GreedLastPatternModel pattern,
            float readiness,
            float direction)
        {
            float safeReadiness = Mathf.Clamp01(readiness);
            float safeDirection = BuildRunnerPreparationCueDirection(pattern, direction);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return new Vector4(
                        safeDirection * Mathf.Lerp(2f, 6f, safeReadiness),
                        Mathf.Lerp(-38f, -48f, safeReadiness),
                        Mathf.Lerp(68f, 132f, safeReadiness),
                        Mathf.Lerp(8f, 16f, safeReadiness));
                case RunnerResponseType.Slide:
                    return new Vector4(
                        safeDirection * Mathf.Lerp(6f, 14f, safeReadiness),
                        Mathf.Lerp(-6f, -16f, safeReadiness),
                        Mathf.Lerp(102f, 176f, safeReadiness),
                        Mathf.Lerp(7f, 13f, safeReadiness));
                case RunnerResponseType.Twist:
                    return new Vector4(
                        safeDirection * Mathf.Lerp(44f, 74f, safeReadiness),
                        Mathf.Lerp(8f, 2f, safeReadiness),
                        Mathf.Lerp(7f, 14f, safeReadiness),
                        Mathf.Lerp(82f, 150f, safeReadiness));
                default:
                    return Vector4.zero;
            }
        }

        private static Vector4 BuildRunnerPreparationCueLayoutForPattern(
            GreedLastPatternModel pattern,
            float readiness,
            float direction)
        {
            return BuildRunnerPreparationCueLayout(pattern, readiness, direction);
        }

        private static float BuildRunnerPreparationCueAngle(
            GreedLastPatternModel pattern,
            float readiness,
            float direction)
        {
            float safeReadiness = Mathf.Clamp01(readiness);
            float safeDirection = BuildRunnerPreparationCueDirection(pattern, direction);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Slide:
                    return -safeDirection * Mathf.Lerp(2f, 5.5f, safeReadiness);
                case RunnerResponseType.Twist:
                    return -safeDirection * Mathf.Lerp(12f, 27f, safeReadiness);
                default:
                    return 0f;
            }
        }

        private static float BuildRunnerPreparationCueAngleForPattern(
            GreedLastPatternModel pattern,
            float readiness,
            float direction)
        {
            return BuildRunnerPreparationCueAngle(pattern, readiness, direction);
        }

        private static int BuildRunnerPreparationCueAlpha(
            GreedLastPatternModel pattern,
            bool activePattern,
            bool blocked,
            float readiness,
            float beatCueUrgency,
            float downbeatLift)
        {
            if (!activePattern || blocked || !pattern.IsValid || BuildRunnerResponseType(pattern) == RunnerResponseType.None)
            {
                return 0;
            }

            float safeReadiness = Mathf.Clamp01(readiness);
            if (safeReadiness <= 0f)
            {
                return 0;
            }

            float baseAlpha = Mathf.Lerp(30f, 112f, safeReadiness);
            baseAlpha += Mathf.Clamp01(beatCueUrgency) * 22f;
            baseAlpha += Mathf.Clamp01(downbeatLift) * 26f;
            return Mathf.RoundToInt(Mathf.Clamp(baseAlpha, 0f, 158f));
        }

        private static float BuildRunnerPreparationCueScale(float readiness, float downbeatLift)
        {
            return 1f + Mathf.Clamp01(readiness) * 0.10f + Mathf.Clamp01(downbeatLift) * 0.08f;
        }

        private static float BuildRunnerPreparationCueColorBlend(
            float readiness,
            float beatCueUrgency,
            float downbeatLift)
        {
            return Mathf.Clamp01(
                Mathf.Clamp01(readiness) * 0.28f
                + Mathf.Clamp01(beatCueUrgency) * 0.12f
                + Mathf.Clamp01(downbeatLift) * 0.22f);
        }

        private static float BuildRunnerPreparationCueDirection(
            GreedLastPatternModel pattern,
            float fallbackDirection)
        {
            float direction = pattern.Channel == GreedLastRunChannel.Left
                ? 1f
                : pattern.Channel == GreedLastRunChannel.Right ? -1f : Mathf.Sign(fallbackDirection);
            if (Mathf.Approximately(direction, 0f))
            {
                direction = 1f;
            }

            return direction;
        }

        private static Vector4 BuildRunnerPreparationSymbolLayout(
            GreedLastPatternModel pattern,
            float readiness,
            float direction)
        {
            float safeReadiness = Mathf.Clamp01(readiness);
            float safeDirection = BuildRunnerPreparationCueDirection(pattern, direction);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return new Vector4(
                        safeDirection * Mathf.Lerp(0f, 5f, safeReadiness),
                        Mathf.Lerp(52f, 82f, safeReadiness),
                        Mathf.Lerp(32f, 42f, safeReadiness),
                        1f + safeReadiness * 0.14f);
                case RunnerResponseType.Slide:
                    return new Vector4(
                        safeDirection * Mathf.Lerp(24f, 46f, safeReadiness),
                        Mathf.Lerp(-2f, -18f, safeReadiness),
                        Mathf.Lerp(30f, 38f, safeReadiness),
                        0.94f + safeReadiness * 0.10f);
                case RunnerResponseType.Twist:
                    return new Vector4(
                        safeDirection * Mathf.Lerp(58f, 88f, safeReadiness),
                        Mathf.Lerp(22f, 34f, safeReadiness),
                        Mathf.Lerp(32f, 40f, safeReadiness),
                        0.96f + safeReadiness * 0.12f);
                default:
                    return Vector4.zero;
            }
        }

        private static Vector4 BuildRunnerPreparationSymbolLayoutForPattern(
            GreedLastPatternModel pattern,
            float readiness,
            float direction)
        {
            return BuildRunnerPreparationSymbolLayout(pattern, readiness, direction);
        }

        private static float BuildRunnerPreparationSymbolAngle(
            GreedLastPatternModel pattern,
            float readiness,
            float direction)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            return -BuildRunnerPreparationCueDirection(pattern, direction) * Mathf.Lerp(5f, 12f, Mathf.Clamp01(readiness));
        }

        private static float BuildRunnerPreparationSymbolAngleForPattern(
            GreedLastPatternModel pattern,
            float readiness,
            float direction)
        {
            return BuildRunnerPreparationSymbolAngle(pattern, readiness, direction);
        }

        private static int BuildRunnerPreparationSymbolAlpha(
            GreedLastPatternModel pattern,
            bool activePattern,
            bool blocked,
            float readiness,
            float beatCueUrgency,
            float downbeatLift)
        {
            if (!activePattern || blocked || !pattern.IsValid || BuildRunnerResponseType(pattern) == RunnerResponseType.None)
            {
                return 0;
            }

            float safeReadiness = Mathf.Clamp01(readiness);
            if (safeReadiness <= 0f)
            {
                return 0;
            }

            float alpha = Mathf.Lerp(46f, 156f, safeReadiness)
                + Mathf.Clamp01(beatCueUrgency) * 24f
                + Mathf.Clamp01(downbeatLift) * 30f;
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 220f));
        }

        private void ApplyRunnerResponsePose(
            RectTransform avatarRect,
            float arc,
            float channelDirection,
            ref float shadowOffsetX,
            ref float shadowScaleX,
            ref float shadowAlpha)
        {
            Vector4 transform = BuildRunnerResponsePoseTransform(runnerResponseType, arc, channelDirection);
            Vector4 motion = BuildRunnerResponsePoseMotion(runnerResponseType, arc, channelDirection);
            Vector4 limbs = BuildRunnerResponseLimbAngles(runnerResponseType, arc, channelDirection);
            avatarRect.anchoredPosition = new Vector2(transform.x, transform.y);
            avatarRect.localScale = new Vector3(transform.z, transform.w, 1f);
            avatarRect.localEulerAngles = new Vector3(0f, 0f, motion.x);
            ApplyRunnerLimbPose(limbs.x, limbs.y, limbs.z, limbs.w);
            shadowOffsetX = motion.y;
            shadowScaleX = motion.z;
            shadowAlpha = motion.w;
        }

        private void ApplyRunnerAnticipationPose(
            RectTransform avatarRect,
            float readiness,
            float channelDirection,
            float bob,
            float stride,
            Vector4 runningLimbs,
            ref float shadowOffsetX,
            ref float shadowScaleX,
            ref float shadowAlpha)
        {
            Vector4 transform = BuildRunnerAnticipationPoseTransform(
                BuildRunnerResponseType(latestRunSnapshot.Pattern),
                readiness,
                channelDirection);
            Vector4 motion = BuildRunnerAnticipationPoseMotion(
                BuildRunnerResponseType(latestRunSnapshot.Pattern),
                readiness,
                channelDirection);
            Vector4 limbs = BuildRunnerAnticipationLimbAngles(
                BuildRunnerResponseType(latestRunSnapshot.Pattern),
                readiness,
                channelDirection);
            avatarRect.anchoredPosition = new Vector2(transform.x, bob + transform.y);
            avatarRect.localScale = new Vector3(transform.z, transform.w, 1f);
            avatarRect.localEulerAngles = new Vector3(0f, 0f, motion.x + stride * Mathf.Lerp(1.2f, 0.4f, Mathf.Clamp01(readiness)));
            float poseBlend = Mathf.Clamp01(readiness * 0.86f);
            ApplyRunnerLimbPose(
                Mathf.Lerp(runningLimbs.x, limbs.x, poseBlend),
                Mathf.Lerp(runningLimbs.y, limbs.y, poseBlend),
                Mathf.Lerp(runningLimbs.z, limbs.z, poseBlend),
                Mathf.Lerp(runningLimbs.w, limbs.w, poseBlend));
            shadowOffsetX = motion.y;
            shadowScaleX = motion.z;
            shadowAlpha = motion.w;
        }

        private static float BuildRunnerAnticipationStrength(
            bool activePattern,
            bool blocked,
            float coreDeltaSeconds,
            float goodWindowSeconds)
        {
            if (!activePattern || blocked)
            {
                return 0f;
            }

            const float anticipationLeadSeconds = 0.82f;
            float lateWindow = Mathf.Max(0.05f, goodWindowSeconds);
            if (coreDeltaSeconds < -anticipationLeadSeconds || coreDeltaSeconds > lateWindow)
            {
                return 0f;
            }

            float normalized = coreDeltaSeconds <= 0f
                ? 1f - Mathf.Clamp01(-coreDeltaSeconds / anticipationLeadSeconds)
                : 1f - Mathf.Clamp01(coreDeltaSeconds / lateWindow);
            return Mathf.SmoothStep(0f, 1f, normalized);
        }

        private static float BuildRunnerDownbeatLift(
            bool activePattern,
            bool blocked,
            float downbeatPulse,
            float coreDeltaSeconds,
            float goodWindowSeconds)
        {
            float anticipation = BuildRunnerAnticipationStrength(activePattern, blocked, coreDeltaSeconds, goodWindowSeconds);
            if (anticipation <= 0f)
            {
                return 0f;
            }

            return Mathf.Clamp01(downbeatPulse) * Mathf.Lerp(0.34f, 1f, anticipation);
        }

        private static float BuildRunnerDownbeatBodyScaleX(GreedLastPatternModel pattern, float downbeatLift)
        {
            float safeLift = Mathf.Clamp01(downbeatLift);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 1f - safeLift * 0.006f;
                case RunnerResponseType.Slide:
                    return 1f + safeLift * 0.030f;
                case RunnerResponseType.Twist:
                    return 1f - safeLift * 0.010f;
                default:
                    return 1f + safeLift * 0.010f;
            }
        }

        private static float BuildRunnerDownbeatBodyScaleY(GreedLastPatternModel pattern, float downbeatLift)
        {
            float safeLift = Mathf.Clamp01(downbeatLift);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 1f + safeLift * 0.032f;
                case RunnerResponseType.Slide:
                    return 1f - safeLift * 0.018f;
                case RunnerResponseType.Twist:
                    return 1f + safeLift * 0.018f;
                default:
                    return 1f + safeLift * 0.012f;
            }
        }

        private static float BuildRunnerDownbeatBodyAngleLift(GreedLastPatternModel pattern, float downbeatLift)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = pattern.Channel == GreedLastRunChannel.Left
                ? 1f
                : pattern.Channel == GreedLastRunChannel.Right ? -1f : 0.5f;
            return direction * Mathf.Clamp01(downbeatLift) * 1.8f;
        }

        private static float BuildRunnerDownbeatBodyColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.12f;
        }

        private static float BuildRunnerDownbeatShadowScaleXLift(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.035f;
        }

        private static float BuildRunnerDownbeatShadowAlphaLift(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 10f;
        }

        private static float BuildRunnerBeatCueUrgency(float beatCueUrgency, float groundContact)
        {
            return Mathf.Clamp01(beatCueUrgency) * Mathf.Lerp(0.68f, 1f, Mathf.Clamp01(groundContact));
        }

        private static float BuildRunnerBeatCueUrgencyBodyScaleX(GreedLastPatternModel pattern, float runnerBeatCueUrgency)
        {
            float urgency = Mathf.Clamp01(runnerBeatCueUrgency);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 1f - urgency * 0.004f;
                case RunnerResponseType.Slide:
                    return 1f + urgency * 0.016f;
                case RunnerResponseType.Twist:
                    return 1f - urgency * 0.006f;
                default:
                    return 1f + urgency * 0.006f;
            }
        }

        private static float BuildRunnerBeatCueUrgencyBodyScaleY(GreedLastPatternModel pattern, float runnerBeatCueUrgency)
        {
            float urgency = Mathf.Clamp01(runnerBeatCueUrgency);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 1f + urgency * 0.020f;
                case RunnerResponseType.Slide:
                    return 1f - urgency * 0.012f;
                case RunnerResponseType.Twist:
                    return 1f + urgency * 0.010f;
                default:
                    return 1f + urgency * 0.008f;
            }
        }

        private static float BuildRunnerBeatCueUrgencyBodyAngleLift(GreedLastPatternModel pattern, float runnerBeatCueUrgency)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = pattern.Channel == GreedLastRunChannel.Left
                ? 1f
                : pattern.Channel == GreedLastRunChannel.Right ? -1f : 0.5f;
            return direction * Mathf.Clamp01(runnerBeatCueUrgency) * 0.85f;
        }

        private static float BuildRunnerBeatCueUrgencyBodyColorBlend(float runnerBeatCueUrgency)
