        private static Vector4 BuildRunnerSilhouetteHairLayout(
            RunnerResponseType response,
            float strength,
            float direction,
            float stride)
        {
            float safeStrength = Mathf.Clamp01(strength);
            float safeDirection = NormalizeRunnerSilhouetteDirection(direction);
            float strideLift = Mathf.Abs(stride) * Mathf.Lerp(1.4f, 0.5f, safeStrength);
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return new Vector4(
                        0f,
                        strideLift + safeStrength * 7f,
                        1f - safeStrength * 0.035f,
                        1f + safeStrength * 0.16f);
                case RunnerResponseType.Slide:
                    return new Vector4(
                        safeDirection * safeStrength * 2f,
                        strideLift * 0.35f - safeStrength * 11f,
                        1f + safeStrength * 0.14f,
                        1f - safeStrength * 0.22f);
                case RunnerResponseType.Twist:
                    return new Vector4(
                        safeDirection * safeStrength * 7f,
                        strideLift * 0.65f + safeStrength * 2.5f,
                        1f - safeStrength * 0.06f,
                        1f + safeStrength * 0.06f);
                default:
                    return new Vector4(0f, strideLift, 1f, 1f);
            }
        }

        private static Vector4 BuildRunnerSilhouetteSashLayout(
            RunnerResponseType response,
            float strength,
            float direction)
        {
            float safeStrength = Mathf.Clamp01(strength);
            float safeDirection = NormalizeRunnerSilhouetteDirection(direction);
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return new Vector4(
                        0f,
                        -safeStrength * 2f,
                        58f + safeStrength * 7f,
                        -8f - safeStrength * 6f);
                case RunnerResponseType.Slide:
                    return new Vector4(
                        safeDirection * safeStrength * 3f,
                        -safeStrength * 7f,
                        58f + safeStrength * 20f,
                        -8f + safeStrength * 4f);
                case RunnerResponseType.Twist:
                    return new Vector4(
                        safeDirection * safeStrength * 9f,
                        safeStrength * 1.5f,
                        58f + safeStrength * 12f,
                        -8f + safeDirection * safeStrength * 18f);
                default:
                    return new Vector4(0f, 0f, 58f, -8f);
            }
        }

        private static Vector4 BuildRunnerSilhouetteHornLayout(
            RunnerResponseType response,
            float strength,
            float direction,
            float side)
        {
            float safeStrength = Mathf.Clamp01(strength);
            float safeDirection = NormalizeRunnerSilhouetteDirection(direction);
            float safeSide = NormalizeRunnerSilhouetteDirection(side);
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return new Vector4(
                        safeSide * safeStrength * 2.4f,
                        safeStrength * 3f,
                        1f + safeStrength * 0.06f,
                        safeSide * 22f + safeSide * safeStrength * 5f);
                case RunnerResponseType.Slide:
                    return new Vector4(
                        safeSide * safeStrength * 3.2f,
                        -safeStrength * 4f,
                        1f - safeStrength * 0.10f,
                        safeSide * 22f - safeSide * safeStrength * 5f);
                case RunnerResponseType.Twist:
                    return new Vector4(
                        safeDirection * safeStrength * 2.6f + safeSide * safeStrength * 1.1f,
                        safeStrength * 1.2f,
                        1f + safeStrength * 0.02f,
                        safeSide * 22f + safeDirection * safeStrength * 7f - safeSide * safeStrength * 2f);
                default:
                    return new Vector4(0f, 0f, 1f, safeSide * 22f);
            }
        }

        private static float NormalizeRunnerSilhouetteDirection(float direction)
        {
            if (Mathf.Approximately(direction, 0f))
            {
                return 1f;
            }

            return Mathf.Sign(direction);
        }

        private static Vector4 BuildRunnerResponsePoseTransform(
            RunnerResponseType response,
            float arc,
            float channelDirection)
        {
            float safeArc = Mathf.Clamp01(arc);
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return new Vector4(0f, safeArc * 92f, 0.96f + safeArc * 0.04f, 1f - safeArc * 0.08f);
                case RunnerResponseType.Slide:
                    return new Vector4(
                        channelDirection * safeArc * 12f,
                        -safeArc * 30f,
                        1f + safeArc * 0.24f,
                        1f - safeArc * 0.44f);
                case RunnerResponseType.Twist:
                    return new Vector4(
                        channelDirection * safeArc * 48f,
                        safeArc * 8f,
                        1f - safeArc * 0.16f,
                        1f + safeArc * 0.05f);
                default:
                    return new Vector4(0f, 0f, 1f, 1f);
            }
        }

        private static Vector4 BuildRunnerAnticipationPoseTransform(
            RunnerResponseType response,
            float readiness,
            float channelDirection)
        {
            float safeReadiness = Mathf.Clamp01(readiness);
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return new Vector4(0f, -safeReadiness * 8f, 1f + safeReadiness * 0.035f, 1f - safeReadiness * 0.065f);
                case RunnerResponseType.Slide:
                    return new Vector4(
                        channelDirection * safeReadiness * 5f,
                        -safeReadiness * 14f,
                        1f + safeReadiness * 0.16f,
                        1f - safeReadiness * 0.20f);
                case RunnerResponseType.Twist:
                    return new Vector4(
                        channelDirection * safeReadiness * 18f,
                        safeReadiness * 2f,
                        1f - safeReadiness * 0.08f,
                        1f + safeReadiness * 0.03f);
                default:
                    return new Vector4(0f, 0f, 1f, 1f);
            }
        }

        private static Vector4 BuildRunnerResponsePoseMotion(
            RunnerResponseType response,
            float arc,
            float channelDirection)
        {
            float safeArc = Mathf.Clamp01(arc);
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return new Vector4(0f, 0f, Mathf.Lerp(1f, 0.58f, safeArc), Mathf.Lerp(112f, 54f, safeArc));
                case RunnerResponseType.Slide:
                    return new Vector4(
                        -channelDirection * safeArc * 9f,
                        channelDirection * safeArc * 8f,
                        1f + safeArc * 0.38f,
                        132f);
                case RunnerResponseType.Twist:
                    return new Vector4(
                        -channelDirection * safeArc * 14f,
                        channelDirection * safeArc * 24f,
                        1f - safeArc * 0.18f,
                        104f);
                default:
                    return new Vector4(0f, 0f, 1f, 112f);
            }
        }

        private static Vector4 BuildRunnerAnticipationPoseMotion(
            RunnerResponseType response,
            float readiness,
            float channelDirection)
        {
            float safeReadiness = Mathf.Clamp01(readiness);
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return new Vector4(0f, 0f, 1f + safeReadiness * 0.12f, 112f + safeReadiness * 16f);
                case RunnerResponseType.Slide:
                    return new Vector4(
                        -channelDirection * safeReadiness * 5f,
                        channelDirection * safeReadiness * 4f,
                        1f + safeReadiness * 0.25f,
                        112f + safeReadiness * 14f);
                case RunnerResponseType.Twist:
                    return new Vector4(
                        -channelDirection * safeReadiness * 8f,
                        channelDirection * safeReadiness * 10f,
                        1f - safeReadiness * 0.10f,
                        112f + safeReadiness * 4f);
                default:
                    return new Vector4(0f, 0f, 1f, 112f);
            }
        }

        private static Vector4 BuildRunnerResponseLimbAngles(
            RunnerResponseType response,
            float arc,
            float channelDirection)
        {
            float safeArc = Mathf.Clamp01(arc);
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return new Vector4(-58f * safeArc, 58f * safeArc, 52f * safeArc, -52f * safeArc);
                case RunnerResponseType.Slide:
                    return new Vector4(50f * safeArc, 42f * safeArc, -18f * safeArc, 24f * safeArc);
                case RunnerResponseType.Twist:
                    return new Vector4(
                        -channelDirection * 48f * safeArc,
                        channelDirection * 48f * safeArc,
                        channelDirection * 20f * safeArc,
                        -channelDirection * 20f * safeArc);
                default:
                    return Vector4.zero;
            }
        }

        private static Vector4 BuildRunnerStrideLimbAngles(float stride)
        {
            return new Vector4(stride * 27f, -stride * 27f, -stride * 22f, stride * 22f);
        }

        private static float BuildRunnerStridePhase(
            bool running,
            float beatProgress,
            float motionSpeedBias,
            float forwardPulse)
        {
            if (!running)
            {
                return 0f;
            }

            float speed = Mathf.Max(0.1f, motionSpeedBias) * (1f + Mathf.Clamp01(forwardPulse) * 0.12f);
            return Mathf.Repeat(Mathf.Clamp01(beatProgress) * speed, 1f);
        }

        private static float BuildRunnerGroundContactStrength(
            bool running,
            bool activePattern,
            bool blocked,
            float stridePhase,
            float coreDeltaSeconds,
            float goodWindowSeconds,
            float forwardPulse,
            float recoveryPressure)
        {
            if (!running || blocked)
            {
                return 0f;
            }

            float stride = Mathf.Clamp01(stridePhase);
            float footPlant = Mathf.Pow(1f - Mathf.Abs(Mathf.Sin(stride * Mathf.PI * 2f)), 1.6f);
            float contact = 0.18f + footPlant * 0.46f;
            if (activePattern)
            {
                float coreWindow = Mathf.Max(0.04f, Mathf.Max(0.01f, goodWindowSeconds) * 1.75f);
                float coreProximity = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / coreWindow);
                contact += coreProximity * 0.34f;
            }

            contact += Mathf.Clamp01(forwardPulse) * 0.18f;
            contact += Mathf.Clamp01(recoveryPressure) * 0.16f;
            return Mathf.Clamp01(contact);
        }

        private static float BuildRunnerShadowContactScaleX(float baseScaleX, float contactStrength, float recoveryPressure)
        {
            return Mathf.Max(0.1f, baseScaleX)
                * (1f + Mathf.Clamp01(contactStrength) * 0.13f + Mathf.Clamp01(recoveryPressure) * 0.10f);
        }

        private static float BuildRunnerShadowContactScaleY(float scaleX, float contactStrength, float recoveryPressure)
        {
            float baseScaleY = Mathf.Lerp(0.72f, 1f, Mathf.Clamp01(scaleX - 0.55f));
            return Mathf.Clamp(
                baseScaleY * (1f - Mathf.Clamp01(contactStrength) * 0.18f + Mathf.Clamp01(recoveryPressure) * 0.06f),
                0.48f,
                1.08f);
        }

        private static float BuildRunnerShadowContactAlpha(float baseAlpha, float contactStrength, float recoveryPressure)
        {
            return Mathf.Clamp(
                baseAlpha + Mathf.Clamp01(contactStrength) * 28f + Mathf.Clamp01(recoveryPressure) * 16f,
                0f,
                180f);
        }

        private static float BuildRunnerRotationCorridorBraceStrength(GreedLastRunSnapshot snapshot, bool blocked)
        {
            return BuildRunnerRotationCorridorBraceStrengthForValues(
                snapshot.ActivePattern,
                blocked,
                snapshot.Pattern.IsValid && GreedLastRunCore.IsRotationPattern(snapshot.Pattern),
                snapshot.CoreDeltaSeconds,
                snapshot.Pattern.IsValid ? snapshot.Pattern.GoodWindowSeconds : 0f,
                BuildActiveBeatCueUrgency(snapshot));
        }

        private static float BuildRunnerRotationCorridorBraceStrengthForValues(
            bool activePattern,
            bool blocked,
            bool rotationPattern,
            float coreDeltaSeconds,
            float goodWindowSeconds,
            float beatCueUrgency)
        {
            if (!activePattern || blocked || !rotationPattern)
            {
                return 0f;
            }

            float readableWindow = Mathf.Max(0.35f, Mathf.Max(0.01f, goodWindowSeconds) * 2.25f);
            float readiness = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / readableWindow);
            return Mathf.Clamp01(readiness * Mathf.Lerp(0.72f, 1f, Mathf.Clamp01(beatCueUrgency)));
        }

        private static float BuildRunnerRotationCorridorBraceOffsetX(float rotationDirection, float braceStrength)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(braceStrength) * 12f;
        }

        private static float BuildRunnerRotationCorridorBraceAngle(float rotationDirection, float braceStrength)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(braceStrength) * 4.8f;
        }

        private static float BuildRunnerRotationCorridorBraceScaleX(float braceStrength)
        {
            return 1f - Mathf.Clamp01(braceStrength) * 0.035f;
        }

        private static float BuildRunnerRotationCorridorBraceScaleY(float braceStrength)
        {
            return 1f + Mathf.Clamp01(braceStrength) * 0.025f;
        }

        private static float BuildRunnerRotationCorridorBraceColorBlend(float braceStrength)
        {
            return Mathf.Clamp01(braceStrength) * 0.22f;
        }

        private static float BuildRunnerRotationCorridorBraceShadowOffsetX(float rotationDirection, float braceStrength)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(braceStrength) * 7f;
        }

        private static float BuildRunnerRotationCorridorBraceShadowScaleXLift(float braceStrength)
        {
            return Mathf.Clamp01(braceStrength) * 0.10f;
        }

        private static float BuildRunnerRotationCorridorBraceShadowAlphaLift(float braceStrength)
        {
            return Mathf.Clamp01(braceStrength) * 18f;
        }

        private static float BuildRunnerContactBodyScaleX(float contactStrength)
        {
            return 1f + Mathf.Clamp01(contactStrength) * 0.025f;
        }

        private static float BuildRunnerContactBodyScaleY(float contactStrength)
        {
            return 1f - Mathf.Clamp01(contactStrength) * 0.034f;
        }

        private static Vector4 BuildRunnerAnticipationLimbAngles(
            RunnerResponseType response,
            float readiness,
            float channelDirection)
        {
            float safeReadiness = Mathf.Clamp01(readiness);
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return new Vector4(-24f * safeReadiness, 24f * safeReadiness, 22f * safeReadiness, -22f * safeReadiness);
                case RunnerResponseType.Slide:
                    return new Vector4(24f * safeReadiness, 20f * safeReadiness, -10f * safeReadiness, 14f * safeReadiness);
                case RunnerResponseType.Twist:
                    return new Vector4(
                        -channelDirection * 24f * safeReadiness,
                        channelDirection * 24f * safeReadiness,
                        channelDirection * 10f * safeReadiness,
                        -channelDirection * 10f * safeReadiness);
                default:
                    return Vector4.zero;
            }
        }

        private void ApplyRunnerLimbPose(float leftArmAngle, float rightArmAngle, float leftLegAngle, float rightLegAngle)
        {
            SetRunnerPartAngle(runnerLeftArm, leftArmAngle);
            SetRunnerPartAngle(runnerRightArm, rightArmAngle);
            SetRunnerPartAngle(runnerLeftLeg, leftLegAngle);
            SetRunnerPartAngle(runnerRightLeg, rightLegAngle);
        }

        private static void SetRunnerPartAngle(Image part, float angle)
        {
            if (part != null)
            {
                part.rectTransform.localEulerAngles = new Vector3(0f, 0f, angle);
            }
        }

        private void ApplyRunnerPrototypeSilhouettePose(
            RunnerResponseType response,
            float strength,
            float direction,
            float stride)
        {
            Vector4 hair = BuildRunnerSilhouetteHairLayout(response, strength, direction, stride);
            SetRunnerPartLayout(
                runnerHairBack,
                0.5f,
                0.80f,
                58f * hair.z,
                48f * hair.w,
                0f,
                new Vector2(hair.x, hair.y));

            Vector4 sash = BuildRunnerSilhouetteSashLayout(response, strength, direction);
            SetRunnerPartLayout(
                runnerSash,
                0.55f,
                0.49f,
                sash.z,
                13f,
                sash.w,
                new Vector2(sash.x, sash.y));

            Vector4 leftHorn = BuildRunnerSilhouetteHornLayout(response, strength, direction, -1f);
            SetRunnerPartLayout(
                runnerLeftHorn,
                0.38f,
                0.96f,
                16f,
                34f * leftHorn.z,
                leftHorn.w,
                new Vector2(leftHorn.x, leftHorn.y));

            Vector4 rightHorn = BuildRunnerSilhouetteHornLayout(response, strength, direction, 1f);
            SetRunnerPartLayout(
                runnerRightHorn,
                0.62f,
                0.96f,
                16f,
                34f * rightHorn.z,
                rightHorn.w,
                new Vector2(rightHorn.x, rightHorn.y));
        }

        private static void SetRunnerPartLayout(
            Image part,
            float anchorX,
            float anchorY,
            float width,
            float height,
            float angle,
            Vector2 anchoredPosition)
        {
            if (part == null)
            {
                return;
            }

            RectTransform rect = part.rectTransform;
            rect.anchorMin = new Vector2(anchorX, anchorY);
            rect.anchorMax = rect.anchorMin;
            rect.anchoredPosition = anchoredPosition;
            rect.sizeDelta = new Vector2(width, height);
            rect.localScale = Vector3.one;
            rect.localEulerAngles = new Vector3(0f, 0f, angle);
        }

        private void SetRunnerBodyColor(Color32 color)
        {
            bool hasIllustration = runnerIllustration != null;
            int overlayAlpha = BuildRunnerProceduralOverlayAlpha(hasIllustration);
            if (hasIllustration)
            {
                runnerIllustration.color = BuildPrototypeRunnerIllustrationTint(color);
            }

            SetRunnerPartColor(runnerHairBack, WithAlpha(Color32.Lerp(PrototypeRunnerHairColor, color, 0.10f), overlayAlpha));
            SetRunnerPartColor(runnerLeftHorn, WithAlpha(Color32.Lerp(PrototypeRunnerHornColor, color, 0.18f), overlayAlpha));
            SetRunnerPartColor(runnerRightHorn, WithAlpha(Color32.Lerp(PrototypeRunnerHornColor, color, 0.18f), overlayAlpha));
            SetRunnerPartColor(runnerHead, WithAlpha(color, overlayAlpha));
            SetRunnerPartColor(runnerTorso, WithAlpha(color, overlayAlpha));
            SetRunnerPartColor(runnerSash, WithAlpha(Color32.Lerp(PrototypeRunnerSashColor, color, 0.22f), overlayAlpha));
            SetRunnerPartColor(runnerLeftArm, WithAlpha(color, overlayAlpha));
            SetRunnerPartColor(runnerRightArm, WithAlpha(color, overlayAlpha));
            SetRunnerPartColor(runnerLeftLeg, WithAlpha(color, overlayAlpha));
            SetRunnerPartColor(runnerRightLeg, WithAlpha(color, overlayAlpha));
        }

        private static int BuildRunnerProceduralOverlayAlpha(bool hasIllustration)
        {
            return hasIllustration ? 40 : 255;
        }

        private static Color32 BuildPrototypeRunnerIllustrationTint(Color32 bodyColor)
        {
            return WithAlpha(Color32.Lerp(new Color32(255, 255, 255, 255), bodyColor, 0.14f), 240);
        }

        private static void SetRunnerPartColor(Image part, Color32 color)
        {
            if (part != null)
            {
                part.color = color;
            }
        }

        private void HideRunTimingFeedback()
        {
            HideTrapDangerVisuals();
            HideTimingBands();
            HideActiveActionCue();
            HideInputTimingTrace();
            HideRhythmBreakLine();
            HideThreeActionExactBurst();
            if (timingGuideText != null)
            {
                timingGuideText.text = string.Empty;
                timingGuideText.rectTransform.localScale = Vector3.one;
            }
        }

        private void UpdateRunTimingVisuals()
        {
            if (trapMarker == null || judgementLine == null || !hasRunSnapshot)
            {
                HideRunTimingFeedback();
                return;
            }

            if (!runModeActive)
            {
                SetJudgementLineY(0.22f);
                judgementLine.color = new Color32(255, 238, 181, 120);
                ApplyJudgementLinePulse();
                HideRunTimingFeedback();

                lastActivePatternVisual = false;
                runEntryTrapRevealPending = false;
                runEntryTrapRevealStartedAt = 0f;
                runEntryTrapRevealUntil = 0f;
                targetCuePlayed = false;
                return;
            }

            if (!ShouldShowActivePatternVisuals(latestRunSnapshot))
            {
                runEntryTrapRevealStartedAt = 0f;
                runEntryTrapRevealUntil = 0f;
                if (latestRunSnapshot.Paused
                    || latestRunSnapshot.CountdownActive
                    || latestRunSnapshot.ChoiceActive
                    || latestRunSnapshot.Stopped)
                {
                    runEntryTrapRevealPending = false;
                }

                HideTrapDangerVisuals();
                SetJudgementLineY(0.22f);
                judgementLine.color = new Color32(255, 238, 181, 120);
                ApplyJudgementLinePulse();
                UpdateRhythmBreakLine();
                HideTimingBands();
                ApplyStaggerRecoveryVisuals();
                if (timingGuideText != null)
                {
                    timingGuideText.fontSize = !DevToolsEnabled || devCleanViewEnabled ? 36 : 28;
                    timingGuideText.text = ShouldShowRunWaitingTimingGuide(latestRunSnapshot)
                        ? "다음 함정 대기"
                        : string.Empty;
                    timingGuideText.color = new Color32(125, 139, 143, 180);
                    timingGuideText.rectTransform.localScale = Vector3.one;
                }

                lastActivePatternVisual = false;
                targetCuePlayed = false;
                HideActiveActionCue();
                UpdateInputTimingTrace();
                UpdateThreeActionExactBurst();
                return;
            }

            if (!lastActivePatternVisual)
            {
                bool firstRunEntryTrap = runEntryTrapRevealPending;
                PlayLaneCue(
                    latestRunSnapshot.Pattern.Channel,
                    BuildTrapEntryLaneCueVolume(
                        firstRunEntryTrap,
                        latestRunSnapshot.PracticeMode,
                        latestRunSnapshot.InfiniteMode,
                        latestRunSnapshot.InfiniteThreatLevel));
                PlayRunnerResponseCue(latestRunSnapshot.Pattern);
                trapEntryPulseUntil = Time.unscaledTime + TrapEntryPulseDuration;
                if (runEntryTrapRevealPending)
                {
                    runEntryTrapRevealStartedAt = Time.unscaledTime;
                    runEntryTrapRevealUntil = Time.unscaledTime + RunEntryTrapRevealDuration;
                    runEntryTrapRevealPending = false;
                }
                targetCuePlayed = false;
            }

            if (!latestRunSnapshot.Paused && !targetCuePlayed && latestRunSnapshot.CoreDeltaSeconds >= -TargetCueLeadSeconds)
            {
                PlayClip(GetTimingCueClip(latestRunSnapshot.Pattern.TimingType), BuildTimingCueVolume(latestRunSnapshot));
                PlayRunnerResponseCue(latestRunSnapshot.Pattern, BuildTargetActionCueVolume(latestRunSnapshot));
                PlayVariationTimingCue(latestRunSnapshot);
                targetCuePlayed = true;
            }

            lastActivePatternVisual = true;

            float channelX = 0.2f;
            if (latestRunSnapshot.Pattern.Channel == GreedLastRunChannel.Center)
            {
                channelX = 0.5f;
            }
            else if (latestRunSnapshot.Pattern.Channel == GreedLastRunChannel.Right)
            {
                channelX = 0.8f;
            }

            float progress = latestRunSnapshot.BeatProgress;
            float coreProgress = Mathf.Clamp01(latestRunSnapshot.Pattern.CoreSeconds / Mathf.Max(0.01f, latestRunSnapshot.Pattern.HitSeconds));
            float visualProgress = BuildTrapVisualProgress(
                latestRunSnapshot.Pattern.TimingType,
                progress,
                coreProgress);
            visualProgress = ApplyDevTrapVisualPreviewProgress(visualProgress, coreProgress);
            float markerX = Mathf.Clamp01(
                channelX
                    + BuildTrapVisualHorizontalOffset(latestRunSnapshot.Pattern.TimingType, progress, coreProgress)
                    + BuildTrapApproachSweepX(latestRunSnapshot.Pattern, visualProgress));
            float y = Mathf.Lerp(BuildTrapApproachStartY(latestRunSnapshot.Pattern), 0.18f, visualProgress);
            float coreY = Mathf.Lerp(0.88f, 0.18f, coreProgress);
            RectTransform rect = trapMarker.rectTransform;
            rect.anchorMin = new Vector2(markerX, y);
            rect.anchorMax = new Vector2(markerX, y);
            rect.anchoredPosition = Vector2.zero;

            float coreNear = Mathf.Clamp01(1f - Mathf.Abs(latestRunSnapshot.CoreDeltaSeconds) / 0.32f);
            float entryPulse = BuildTrapEntryPulse();
            float markerExactPulse = BuildExactTimingPulse();
            float markerBeatCueUrgency = BuildTrapMarkerBeatCueUrgency(
                BuildActiveBeatCueUrgency(latestRunSnapshot),
                coreNear);
            float markerDownbeatLift = BuildTrapMarkerDownbeatLift(
                ShouldShowDownbeatPulse(latestRunSnapshot) ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime) : 0f,
                coreNear,
                markerExactPulse);
            UpdateTrapMarkerShape(rect, latestRunSnapshot.Pattern, coreNear);
            rect.localEulerAngles += new Vector3(
                0f,
                0f,
                BuildTrapMarkerResponseAngleLift(latestRunSnapshot.Pattern, coreNear, markerExactPulse)
                    + BuildTrapMarkerDownbeatAngleLift(latestRunSnapshot.Pattern, markerDownbeatLift));
            UpdateTrapDangerVisuals(channelX, markerX, y, coreNear, markerDownbeatLift);
            UpdateTrapApproachGhosts(channelX, progress, coreProgress, coreNear);
            SetTimingBand(goodTimingBand, latestRunSnapshot.Pattern.GoodWindowSeconds, channelX, false);
            SetTimingBand(successTimingBand, latestRunSnapshot.Pattern.SuccessWindowSeconds, channelX, true);
            SetCenterTimingBand(channelX);
            UpdateTimingBeatPips(channelX);
            UpdateThreeActionExactBurst();

            SetJudgementLineY(coreY);

            Color32 trapBaseColor = BuildPrototypeTrapBaseColor(latestRunSnapshot.Pattern);
            Color32 trapAccentColor = BuildPrototypeTrapAccentColor(latestRunSnapshot.Pattern);
            Color32 markerColor = Color32.Lerp(
                Color32.Lerp(WithAlpha(trapBaseColor, 178), trapAccentColor, entryPulse * 0.72f),
                trapAccentColor,
                coreNear);
            if (TryGetPatternVariationAccent(latestRunSnapshot.Pattern, out Color32 markerVariationColor, out float markerVariationStrength))
            {
                markerColor = Color32.Lerp(markerColor, markerVariationColor, markerVariationStrength * 0.56f);
            }

            if (markerDownbeatLift > 0f)
            {
                markerColor = Color32.Lerp(
                    markerColor,
                    new Color32(255, 214, 105, 255),
                    BuildTrapMarkerDownbeatColorBlend(markerDownbeatLift));
            }
            if (markerBeatCueUrgency > 0f)
            {
                markerColor = Color32.Lerp(
                    markerColor,
                    new Color32(255, 238, 181, 255),
                    BuildTrapMarkerBeatCueUrgencyColorBlend(markerBeatCueUrgency));
            }

            trapMarker.color = WithAlpha(
                markerColor,
                BuildPrototypeTrapProceduralAlpha(trapIllustration != null, markerColor.a));
            UpdatePrototypeTrapIllustration(latestRunSnapshot.Pattern, markerColor);
            float markerBaseScale = Mathf.Lerp(0.88f, 1.22f, coreNear) + entryPulse * 0.18f;
            trapMarker.rectTransform.localScale = new Vector3(
                markerBaseScale * BuildTrapMarkerResponseScaleX(latestRunSnapshot.Pattern, coreNear, markerExactPulse, entryPulse)
                    * BuildTrapMarkerDownbeatScaleX(latestRunSnapshot.Pattern, markerDownbeatLift)
                    + BuildTrapMarkerBeatCueUrgencyScaleXLift(latestRunSnapshot.Pattern, markerBeatCueUrgency),
                markerBaseScale * BuildTrapMarkerResponseScaleY(latestRunSnapshot.Pattern, coreNear, markerExactPulse, entryPulse)
                    * BuildTrapMarkerDownbeatScaleY(latestRunSnapshot.Pattern, markerDownbeatLift)
                    + BuildTrapMarkerBeatCueUrgencyScaleYLift(latestRunSnapshot.Pattern, markerBeatCueUrgency),
                1f);
            UpdateRunEntryTrapReveal(
                markerX,
                y,
                rect.sizeDelta,
                BuildRunEntryTrapRevealStrength(),
                trapAccentColor);
            UpdateTrapActionSymbol(latestRunSnapshot.Pattern, coreNear, entryPulse, markerExactPulse, markerDownbeatLift, markerColor);
            judgementLine.color = Color32.Lerp(new Color32(255, 238, 181, 150), new Color32(255, 255, 255, 255), coreNear);
            ApplyJudgementLinePulse();
            UpdateRhythmBreakLine();
            ApplyStaggerRecoveryVisuals();
            if (timingGuideText != null)
            {
                float exactPulse = BuildExactTimingPulse();
                float guideExactLock = BuildTimingGuideExactLock(coreNear, exactPulse);
                float beatCueUrgency = BuildActiveBeatCueUrgency(latestRunSnapshot);
                float guideDownbeatLift = BuildTimingGuideDownbeatLift(
                    ShouldShowDownbeatPulse(latestRunSnapshot) ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime) : 0f,
                    coreNear,
                    guideExactLock);
                bool compactGuide = !DevToolsEnabled || devCleanViewEnabled;
                timingGuideText.fontSize = compactGuide ? 36 : 28;
                timingGuideText.text = compactGuide
                    ? GetCompactTimingGuideLabel(latestRunSnapshot) : BuildTimingGuideLabel(latestRunSnapshot);
                Color32 guideColor = GetTimingGuideColor(latestRunSnapshot);
                if (exactPulse > 0f)
                {
                    guideColor = Color32.Lerp(
                        guideColor,
                        new Color32(255, 248, 210, 255),
                        BuildTimingGuideExactColorBlend(exactPulse, guideExactLock));
                }
                if (guideDownbeatLift > 0f)
                {
                    guideColor = Color32.Lerp(
                        guideColor,
                        new Color32(255, 214, 105, 255),
                        BuildTimingGuideDownbeatColorBlend(guideDownbeatLift));
                }
                if (beatCueUrgency > 0f)
                {
                    guideColor = Color32.Lerp(
                        guideColor,
                        new Color32(255, 238, 181, 255),
                        BuildBeatCueUrgencyColorBlend(beatCueUrgency));
                }

                int guideAlpha = BuildTimingGuideAlphaWithDownbeat(
                    BuildTimingGuideExactAlpha(guideColor.a, guideExactLock),
                    guideDownbeatLift);
                guideAlpha = Mathf.Clamp(guideAlpha + BuildBeatCueUrgencyAlphaLift(beatCueUrgency), 0, 255);
                float guideScaleX = BuildTimingGuideScaleXWithDownbeat(
                    BuildTimingGuideScaleX(exactPulse, guideExactLock),
                    guideDownbeatLift)
                    + BuildBeatCueUrgencyScaleLift(beatCueUrgency) * 0.62f;
                float guideScaleY = BuildTimingGuideScaleYWithDownbeat(
                    BuildTimingGuideScaleY(exactPulse, guideExactLock),
                    guideDownbeatLift)
                    + BuildBeatCueUrgencyScaleLift(beatCueUrgency);
                timingGuideText.color = WithAlpha(guideColor, guideAlpha);
                timingGuideText.rectTransform.localScale = new Vector3(
                    guideScaleX,
                    guideScaleY,
                    1f);
            }

            UpdateActiveActionCue(latestRunSnapshot, coreNear);
            UpdateInputTimingTrace();
        }

        private void UpdateActiveActionCue(GreedLastRunSnapshot snapshot, float coreNear)
        {
            if (activeActionCueText == null)
            {
                return;
            }

            if (!ShouldShowActiveActionCue(snapshot) || judgementFeedbackUntil > Time.unscaledTime)
            {
                HideActiveActionCue();
                return;
            }

            bool compact = !DevToolsEnabled || devCleanViewEnabled;
            string cue = compact
                ? GetCompactActiveActionCueText(snapshot, DevToolsEnabled, IsRuntimeRotationTiltAvailable())
                : BuildActiveActionCueText(snapshot);
            if (string.IsNullOrEmpty(cue))
            {
                HideActiveActionCue();
                return;
            }

            float exactPulse = BuildExactTimingPulse();
            float beatPulse = GetGameplayBeatPulse();
            float readinessPulse = BuildActiveActionCueReadinessPulse(coreNear, exactPulse, beatPulse);
            float beatCueUrgency = BuildActiveBeatCueUrgency(snapshot);
            float downbeatPulse = ShouldShowDownbeatPulse(snapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;
            Color32 color = GetTimingGuideColor(snapshot);
            if (exactPulse > 0f)
            {
                color = Color32.Lerp(color, new Color32(255, 248, 210, 255), exactPulse * 0.64f);
            }
            if (downbeatPulse > 0f)
            {
                color = Color32.Lerp(color, new Color32(255, 214, 105, 255), BuildDownbeatColorBlend(downbeatPulse, 0.18f));
            }
            if (beatCueUrgency > 0f)
            {
                color = Color32.Lerp(
                    color,
                    new Color32(255, 238, 181, 255),
                    BuildBeatCueUrgencyColorBlend(beatCueUrgency));
            }

            activeActionCueText.text = cue;
            activeActionCueText.fontSize = compact ? 38 : BuildActiveActionCueFontSize(cue, coreNear, exactPulse);
            int cueAlpha = Mathf.Clamp(
                BuildActiveActionCueAlpha(coreNear, readinessPulse)
                    + BuildActiveActionCueDownbeatAlphaLift(downbeatPulse),
                0,
                255);
            cueAlpha = Mathf.Clamp(cueAlpha + BuildBeatCueUrgencyAlphaLift(beatCueUrgency), 0, 255);
            activeActionCueText.color = WithAlpha(color, cueAlpha);
            activeActionCueText.rectTransform.localScale = Vector3.one * (
                BuildActiveActionCueScale(coreNear, exactPulse, readinessPulse)
                + BuildActiveActionCueDownbeatScaleLift(downbeatPulse, coreNear)
                + BuildBeatCueUrgencyScaleLift(beatCueUrgency));
            activeActionCueText.rectTransform.anchoredPosition = new Vector2(
                BuildActiveActionCueOffsetX(snapshot.Pattern.Channel, coreNear, exactPulse),
                0f);
        }

        private static bool ShouldShowActiveActionCue(GreedLastRunSnapshot snapshot)
        {
            return snapshot.ActivePattern
                && IsLiveRunControlWindow(snapshot);
        }

        private static bool ShouldShowActivePatternVisuals(GreedLastRunSnapshot snapshot)
        {
            return snapshot.ActivePattern
                && IsLiveRunControlWindow(snapshot);
        }

        private static bool ShouldShowRunWaitingTimingGuide(GreedLastRunSnapshot snapshot)
        {
            return !snapshot.ActivePattern
                && IsLiveRunControlWindow(snapshot);
        }

        private bool CanShowRunTransientFeedback()
        {
            return runModeActive && hasRunSnapshot && ShouldShowRunTransientFeedback(latestRunSnapshot);
        }

        private static bool ShouldShowRunTransientFeedback(GreedLastRunSnapshot snapshot)
        {
            return (snapshot.ActivePattern || snapshot.LastResult != GreedLastJudgementResult.None)
                && IsLiveRunControlWindow(snapshot);
        }

        private void HideActiveActionCue()
        {
            if (activeActionCueText == null)
            {
                return;
            }

            activeActionCueText.text = string.Empty;
            activeActionCueText.color = new Color32(255, 238, 181, 0);
            activeActionCueText.rectTransform.localScale = Vector3.one;
            activeActionCueText.rectTransform.anchoredPosition = Vector2.zero;
        }

        private static float BuildTimingGuideExactLock(float coreNear, float exactPulse)
        {
            float near = Mathf.Clamp01((Mathf.Clamp01(coreNear) - 0.56f) / 0.44f);
            return Mathf.Clamp01(Mathf.Clamp01(exactPulse) * (0.76f + near * 0.24f));
        }

        private static float BuildTimingGuideExactColorBlend(float exactPulse, float guideExactLock)
        {
            return Mathf.Clamp01(Mathf.Clamp01(exactPulse) * 0.46f + Mathf.Clamp01(guideExactLock) * 0.22f);
        }

        private static int BuildTimingGuideExactAlpha(int baseAlpha, float guideExactLock)
        {
            return Mathf.RoundToInt(Mathf.Clamp(baseAlpha + Mathf.Clamp01(guideExactLock) * 18f, 0f, 255f));
        }

        private static float BuildTimingGuideScaleX(float exactPulse, float guideExactLock)
        {
            return 1f + Mathf.Clamp01(exactPulse) * 0.064f + Mathf.Clamp01(guideExactLock) * 0.014f;
        }

        private static float BuildTimingGuideScaleY(float exactPulse, float guideExactLock)
        {
            return 1f + Mathf.Clamp01(exactPulse) * 0.080f + Mathf.Clamp01(guideExactLock) * 0.046f;
        }

        private static float BuildTimingGuideDownbeatLift(float downbeatPulse, float coreNear, float guideExactLock)
        {
            float readiness = Mathf.Clamp01(0.16f + Mathf.Clamp01(coreNear) * 0.54f + Mathf.Clamp01(guideExactLock) * 0.30f);
            return Mathf.Clamp01(downbeatPulse) * readiness;
        }

        private static float BuildTimingGuideDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.16f;
        }

        private static int BuildTimingGuideAlphaWithDownbeat(int baseAlpha, float downbeatLift)
        {
            return Mathf.RoundToInt(Mathf.Clamp(baseAlpha + Mathf.Clamp01(downbeatLift) * 12f, 0f, 255f));
        }

        private static float BuildTimingGuideScaleXWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.012f;
        }

        private static float BuildTimingGuideScaleYWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.020f;
        }

        private static float BuildActiveActionCueOffsetX(
            GreedLastRunChannel channel,
            float coreNear,
            float exactPulse)
        {
            float direction = channel == GreedLastRunChannel.Left
                ? -1f
                : channel == GreedLastRunChannel.Right ? 1f : 0f;
            if (Mathf.Approximately(direction, 0f))
            {
                return 0f;
            }

            float readiness = Mathf.Clamp01(coreNear);
            return direction * (Mathf.Lerp(20f, 52f, readiness) + Mathf.Clamp01(exactPulse) * 12f);
        }

        private static float BuildActiveActionCueReadinessPulse(float coreNear, float exactPulse, float beatPulse)
        {
            float readiness = Mathf.Clamp01((Mathf.Clamp01(coreNear) - 0.22f) / 0.78f);
            float beatLift = Mathf.Clamp01(beatPulse) * 0.38f + 0.24f;
            return Mathf.Clamp01(readiness * beatLift + Mathf.Clamp01(exactPulse) * 0.62f);
        }

        private static int BuildActiveActionCueAlpha(float coreNear, float readinessPulse)
        {
            return Mathf.RoundToInt(Mathf.Min(255f, Mathf.Lerp(176f, 244f, Mathf.Clamp01(coreNear)) + Mathf.Clamp01(readinessPulse) * 14f));
        }

        private static float BuildActiveActionCueScale(float coreNear, float exactPulse, float readinessPulse)
        {
            return 1f
                + Mathf.Clamp01(coreNear) * 0.045f
                + Mathf.Clamp01(readinessPulse) * 0.035f
                + Mathf.Clamp01(exactPulse) * 0.13f;
        }

        private static int BuildActiveActionCueDownbeatAlphaLift(float downbeatPulse)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(downbeatPulse) * 10f);
        }

        private static float BuildActiveActionCueDownbeatScaleLift(float downbeatPulse, float coreNear)
        {
            return Mathf.Clamp01(downbeatPulse) * Mathf.Lerp(0.010f, 0.028f, Mathf.Clamp01(coreNear));
        }

        private static int BuildActiveActionCueFontSize(string cue, float coreNear, float exactPulse)
        {
            int length = string.IsNullOrEmpty(cue) ? 0 : cue.Length;
            int baseSize = 40;
            if (length > 66)
            {
                baseSize = 34;
            }
            else if (length > 58)
            {
                baseSize = 36;
            }
            else if (length > 48)
            {
                baseSize = 38;
            }

            int timingLift = Mathf.RoundToInt(Mathf.Clamp01(coreNear) * 2f + Mathf.Clamp01(exactPulse) * 2f);
            return Mathf.Clamp(baseSize + timingLift, 34, 43);
        }

        private void UpdateTrapActionSymbol(
            GreedLastPatternModel pattern,
            float coreNear,
            float entryPulse,
            float exactPulse,
            float downbeatLift,
            Color32 markerColor)
        {
            if (trapActionSymbolText == null)
            {
                return;
            }

            string symbol = BuildRunnerResponseSymbol(pattern);
            float exactLock = BuildTrapActionSymbolExactLock(coreNear, exactPulse);
            float symbolDownbeatLift = BuildTrapActionSymbolDownbeatLift(downbeatLift, exactLock);
            float alpha = BuildTrapActionSymbolAlpha(pattern.IsValid, coreNear, entryPulse)
                + BuildTrapActionSymbolExactLockAlphaLift(exactLock)
                + BuildTrapActionSymbolDownbeatAlphaLift(symbolDownbeatLift);
            if (string.IsNullOrEmpty(symbol) || alpha <= 0f)
            {
                HideTrapActionSymbol();
                return;
            }

            trapActionSymbolText.text = symbol;
            Color32 color = Color32.Lerp(
                markerColor,
                new Color32(255, 248, 210, 255),
                Mathf.Clamp01(coreNear) * 0.48f + BuildTrapActionSymbolExactLockColorBlend(exactLock));
            if (symbolDownbeatLift > 0f)
            {
                color = Color32.Lerp(
                    color,
                    new Color32(255, 214, 105, 255),
                    BuildTrapActionSymbolDownbeatColorBlend(symbolDownbeatLift));
            }

            trapActionSymbolText.color = WithAlpha(color, Mathf.RoundToInt(alpha * 255f));
            float symbolBaseScale = BuildTrapActionSymbolScale(coreNear, entryPulse);
            trapActionSymbolText.rectTransform.localScale = new Vector3(
                BuildTrapActionSymbolScaleXWithDownbeat(
                    BuildTrapActionSymbolScaleXWithExactLock(symbolBaseScale, exactLock),
                    symbolDownbeatLift),
                BuildTrapActionSymbolScaleYWithDownbeat(
                    BuildTrapActionSymbolScaleYWithExactLock(symbolBaseScale, exactLock),
                    symbolDownbeatLift),
                1f);
        }

        private void HideTrapActionSymbol()
        {
            if (trapActionSymbolText == null)
            {
                return;
            }

            trapActionSymbolText.text = string.Empty;
            trapActionSymbolText.color = new Color32(255, 238, 181, 0);
            trapActionSymbolText.rectTransform.localScale = Vector3.one;
        }

        private static float BuildTrapActionSymbolAlpha(bool activePattern, float coreNear, float entryPulse)
        {
            if (!activePattern)
            {
                return 0f;
            }

            return Mathf.Clamp01(0.36f + Mathf.Clamp01(coreNear) * 0.50f + Mathf.Clamp01(entryPulse) * 0.18f);
        }

        private static float BuildTrapActionSymbolScale(float coreNear, float entryPulse)
        {
            return 1f + Mathf.Clamp01(coreNear) * 0.10f + Mathf.Clamp01(entryPulse) * 0.12f;
        }

        private static float BuildTrapActionSymbolExactLock(float coreNear, float exactPulse)
        {
            return Mathf.Clamp01(Mathf.Clamp01(exactPulse) * (0.68f + Mathf.Clamp01(coreNear) * 0.32f));
        }

        private static float BuildTrapActionSymbolExactLockAlphaLift(float exactLock)
        {
            return Mathf.Clamp01(exactLock) * 0.12f;
        }

        private static float BuildTrapActionSymbolExactLockColorBlend(float exactLock)
        {
            return Mathf.Clamp01(exactLock) * 0.22f;
        }

        private static float BuildTrapActionSymbolScaleWithExactLock(float coreNear, float entryPulse, float exactLock)
        {
            return BuildTrapActionSymbolScale(coreNear, entryPulse) + Mathf.Clamp01(exactLock) * 0.055f;
        }

        private static float BuildTrapActionSymbolScaleXWithExactLock(float baseScale, float exactLock)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(exactLock) * 0.028f;
        }

        private static float BuildTrapActionSymbolScaleYWithExactLock(float baseScale, float exactLock)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(exactLock) * 0.074f;
        }

        private static float BuildTrapActionSymbolDownbeatLift(float markerDownbeatLift, float exactLock)
        {
            return Mathf.Clamp01(markerDownbeatLift) * Mathf.Lerp(0.72f, 1f, Mathf.Clamp01(exactLock));
        }

        private static float BuildTrapActionSymbolDownbeatAlphaLift(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.10f;
        }

        private static float BuildTrapActionSymbolDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.18f;
        }

        private static float BuildTrapActionSymbolScaleWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.044f;
        }

        private static float BuildTrapActionSymbolScaleXWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.024f;
        }

        private static float BuildTrapActionSymbolScaleYWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.052f;
        }

        private static float BuildTrapVisualProgress(
            GreedLastTimingType timingType,
            float linearProgress,
            float coreProgress)
        {
            float progress = Mathf.Clamp01(linearProgress);
            float safeCore = Mathf.Clamp(coreProgress, 0.05f, 0.95f);
            if (timingType == GreedLastTimingType.Clutch)
            {
                if (progress <= safeCore)
                {
                    float normalized = progress / safeCore;
                    return safeCore * Mathf.Pow(normalized, 1.42f);
                }

                float afterCore = (progress - safeCore) / Mathf.Max(0.01f, 1f - safeCore);
                return safeCore + (1f - safeCore) * Mathf.Pow(afterCore, 0.82f);
            }

            if (timingType == GreedLastTimingType.Offbeat)
            {
                float normalizedToCore = progress / safeCore;
                float distanceEnvelope = 1f - Mathf.Clamp01(Mathf.Abs(progress - safeCore) / 0.32f);
                float wobble = Mathf.Sin(normalizedToCore * Mathf.PI * 2f) * 0.024f * distanceEnvelope;
                return Mathf.Clamp01(progress + wobble);
            }

            return progress;
        }

        private float ApplyDevTrapVisualPreviewProgress(float visualProgress, float coreProgress)
        {
            return BuildTrapVisualPreviewProgress(
                visualProgress,
                coreProgress,
                devTrapVisualPreviewMode,
                DevToolsEnabled);
        }

        private static float BuildTrapVisualPreviewProgress(
            float visualProgress,
            float coreProgress,
            int previewMode,
            bool devToolsEnabled)
        {
            float progress = Mathf.Clamp01(visualProgress);
            if (!devToolsEnabled)
            {
                return progress;
            }

            int safeMode = NormalizeDevTrapVisualPreviewMode(previewMode);
            if (safeMode == 0)
            {
                return progress;
            }

            float safeCore = Mathf.Clamp(coreProgress, 0.05f, 0.95f);
            if (progress >= safeCore)
            {
                return progress;
            }

            float normalizedToCore = progress / safeCore;
            float exponent = safeMode == 1 ? 1.36f : 0.72f;
            return Mathf.Clamp01(safeCore * Mathf.Pow(Mathf.Clamp01(normalizedToCore), exponent));
        }

        private static float BuildTrapVisualHorizontalOffset(
            GreedLastTimingType timingType,
            float linearProgress,
            float coreProgress)
        {
            if (timingType != GreedLastTimingType.Offbeat)
            {
                return 0f;
            }

            float safeCore = Mathf.Max(0.05f, coreProgress);
            float progress = Mathf.Clamp01(linearProgress);
            float distanceEnvelope = 1f - Mathf.Clamp01(Mathf.Abs(progress - safeCore) / 0.34f);
            return Mathf.Sin(progress / safeCore * Mathf.PI * 4f) * 0.018f * distanceEnvelope;
        }

        private void ApplyStaggerRecoveryVisuals()
        {
            if (judgementLine == null || !hasRunSnapshot || !IsLiveRunControlWindow(latestRunSnapshot))
            {
                return;
            }

            float remaining = latestRunSnapshot.StaggerRemainingSeconds;
            if (!latestRunSnapshot.Staggered && remaining <= 0.01f)
            {
                return;
            }

            float normalized = Mathf.Clamp01(remaining / StaggerRecoveryVisualSeconds);
            float pulse = Mathf.Lerp(0.38f, 1f, normalized)
                * (0.70f + Mathf.Sin(Time.unscaledTime * 28f) * 0.30f);
            judgementLine.color = Color32.Lerp(judgementLine.color, new Color32(231, 91, 77, 235), pulse * 0.52f);
            float currentScaleY = judgementLine.rectTransform.localScale.y;
            judgementLine.rectTransform.localScale = new Vector3(1f, Mathf.Max(currentScaleY, 1f + pulse * 0.34f), 1f);

            if (goodTimingBand == null || latestRunSnapshot.ActivePattern)
            {
                return;
            }

            float lineY = judgementLine.rectTransform.anchorMin.y;
            RectTransform bandRect = goodTimingBand.rectTransform;
            bandRect.anchorMin = new Vector2(0.12f, Mathf.Clamp01(lineY - 0.018f - pulse * 0.012f));
            bandRect.anchorMax = new Vector2(0.88f, Mathf.Clamp01(lineY + 0.018f + pulse * 0.012f));
            bandRect.offsetMin = Vector2.zero;
            bandRect.offsetMax = Vector2.zero;
            goodTimingBand.color = new Color32(231, 91, 77, (byte)Mathf.RoundToInt(32f + pulse * 72f));
        }

        private void ApplyJudgementLinePulse()
        {
            if (judgementLine == null)
            {
                return;
            }

            if (!CanShowRunTransientFeedback())
            {
                judgementLine.rectTransform.localScale = Vector3.one;
                return;
            }

            float pulse = BuildJudgementLinePulse();
            float exactPulse = BuildExactTimingPulse();
            float beatPulse = GetGameplayBeatPulse();
            float contactPulse = BuildJudgementLineContactStrength(
                latestRunSnapshot.ActivePattern,
                latestRunSnapshot.Paused || latestRunSnapshot.CountdownActive || latestRunSnapshot.Stopped || latestRunSnapshot.ChoiceActive,
                latestRunSnapshot.CoreDeltaSeconds,
                latestRunSnapshot.Pattern.IsValid ? latestRunSnapshot.Pattern.SuccessWindowSeconds : 0f,
                latestRunSnapshot.Pattern.IsValid ? latestRunSnapshot.Pattern.GoodWindowSeconds : 0f,
                latestRunSnapshot.Pattern.IsValid ? latestRunSnapshot.Pattern.TimingType : GreedLastTimingType.Perfect,
                latestRunSnapshot.InfiniteMode,
                latestRunSnapshot.InfiniteThreatLevel,
                beatPulse);
            float exactLineLock = BuildJudgementLineExactLock(exactPulse, contactPulse);
            float downbeatLineLift = latestRunSnapshot.ActivePattern && ShouldShowDownbeatPulse(latestRunSnapshot)
                ? BuildJudgementLineDownbeatLift(
                    BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime),
                    contactPulse,
                    exactLineLock)
                : 0f;
            float beatCueUrgency = BuildActiveBeatCueUrgency(latestRunSnapshot);
            if (pulse <= 0f && exactPulse <= 0f && contactPulse <= 0f && downbeatLineLift <= 0f && beatCueUrgency <= 0f)
            {
                judgementLine.rectTransform.localScale = Vector3.one;
                return;
            }

            if (contactPulse > 0f)
            {
                judgementLine.color = Color32.Lerp(
                    judgementLine.color,
                    new Color32(255, 238, 181, 255),
                    BuildJudgementLineContactColorBlend(contactPulse));
            }

            if (exactPulse > 0f)
            {
                judgementLine.color = Color32.Lerp(
                    judgementLine.color,
                    new Color32(255, 248, 210, 255),
                    BuildJudgementLineExactColorBlend(exactPulse, exactLineLock));
            }

            if (pulse > 0f)
            {
                judgementLine.color = Color32.Lerp(judgementLine.color, judgementLinePulseColor, pulse);
            }

            if (downbeatLineLift > 0f)
            {
                judgementLine.color = Color32.Lerp(
                    judgementLine.color,
                    new Color32(255, 214, 105, 255),
                    BuildJudgementLineDownbeatColorBlend(downbeatLineLift));
            }

            if (beatCueUrgency > 0f)
            {
                judgementLine.color = Color32.Lerp(
                    judgementLine.color,
                    new Color32(255, 238, 181, 255),
                    BuildJudgementLineBeatCueUrgencyColorBlend(beatCueUrgency));
                judgementLine.color = WithAlpha(
                    judgementLine.color,
                    Mathf.RoundToInt(judgementLine.color.a * 255f) + BuildJudgementLineBeatCueUrgencyAlphaLift(beatCueUrgency));
            }

            judgementLine.rectTransform.localScale = new Vector3(
                BuildJudgementLineScaleXWithDownbeat(
                    BuildJudgementLineScaleX(contactPulse, pulse, exactLineLock),
                    downbeatLineLift)
                    + BuildJudgementLineBeatCueUrgencyScaleXLift(beatCueUrgency),
                BuildJudgementLineScaleY(exactPulse, pulse)
                    + BuildJudgementLineContactScaleYLift(contactPulse)
                    + BuildJudgementLineExactScaleYLift(exactLineLock)
                    + BuildJudgementLineDownbeatScaleYLift(downbeatLineLift)
                    + BuildJudgementLineBeatCueUrgencyScaleYLift(beatCueUrgency),
                1f);
        }

        private void UpdateRhythmBreakLine()
        {
            if (rhythmBreakLine == null)
            {
                return;
            }

            float remaining = rhythmBreakLineUntil - Time.unscaledTime;
            if (remaining <= 0f
                || !CanShowRunTransientFeedback())
            {
                HideRhythmBreakLine();
                return;
            }

            float normalized = Mathf.Clamp01(remaining / RhythmBreakLineDuration);
            RectTransform rect = rhythmBreakLine.rectTransform;
            rect.anchorMin = new Vector2(0.5f, rhythmBreakLineY);
            rect.anchorMax = new Vector2(0.5f, rhythmBreakLineY);
            rect.anchoredPosition = new Vector2(BuildRhythmBreakLineShakeWithStrength(normalized, rhythmBreakLineStrength), 0f);
            rect.sizeDelta = new Vector2(
                BuildRhythmBreakLineWidthWithStrength(normalized, rhythmBreakLineStrength),
                BuildRhythmBreakLineThicknessWithStrength(normalized, rhythmBreakLineStrength));
            rect.localEulerAngles = new Vector3(0f, 0f, BuildRhythmBreakLineAngleWithStrength(normalized, rhythmBreakLineStrength));
            rect.localScale = Vector3.one;
            rhythmBreakLine.color = new Color32(
                231,
                91,
                77,
                (byte)Mathf.RoundToInt(BuildRhythmBreakLineAlphaWithStrength(remaining, rhythmBreakLineStrength) * 255f));
            rhythmBreakLine.transform.SetAsLastSibling();
        }

        private void HideRhythmBreakLine()
        {
            if (rhythmBreakLine == null)
            {
                return;
            }

            rhythmBreakLine.color = new Color32(231, 91, 77, 0);
            rhythmBreakLine.rectTransform.localScale = Vector3.one;
            rhythmBreakLine.rectTransform.localEulerAngles = Vector3.zero;
        }

        private static float BuildRhythmBreakLineAlpha(float remainingSeconds)
        {
            if (remainingSeconds <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remainingSeconds / RhythmBreakLineDuration);
            return Mathf.Pow(normalized, 0.82f);
        }

        private static float BuildRhythmBreakLineAlphaWithStrength(float remainingSeconds, float strength)
        {
            return Mathf.Clamp01(BuildRhythmBreakLineAlpha(remainingSeconds) * Mathf.Lerp(1f, 1.28f, Mathf.Clamp01(strength)));
        }

        private static float BuildRhythmBreakLineWidth(float normalized)
        {
            return Mathf.Lerp(320f, 760f, Mathf.Clamp01(normalized));
        }

        private static float BuildRhythmBreakLineWidthWithStrength(float normalized, float strength)
        {
            return BuildRhythmBreakLineWidth(normalized) + Mathf.Clamp01(strength) * 140f;
        }

        private static float BuildRhythmBreakLineThickness(float normalized)
        {
            return Mathf.Lerp(3f, 12f, Mathf.Clamp01(normalized));
        }

        private static float BuildRhythmBreakLineThicknessWithStrength(float normalized, float strength)
        {
            return BuildRhythmBreakLineThickness(normalized) + Mathf.Clamp01(strength) * 5f;
        }

        private static float BuildRhythmBreakLineAngle(float normalized)
        {
            float age = 1f - Mathf.Clamp01(normalized);
            return Mathf.Lerp(-9f, 7f, age);
        }

        private static float BuildRhythmBreakLineAngleWithStrength(float normalized, float strength)
        {
            return BuildRhythmBreakLineAngle(normalized) + Mathf.Clamp01(strength) * Mathf.Lerp(-4f, 4f, 1f - Mathf.Clamp01(normalized));
        }

        private static float BuildRhythmBreakLineShake(float normalized)
        {
            float clamped = Mathf.Clamp01(normalized);
            return Mathf.Sin((1f - clamped) * Mathf.PI * 5f) * clamped * 12f;
        }

        private static float BuildRhythmBreakLineShakeWithStrength(float normalized, float strength)
        {
            return BuildRhythmBreakLineShake(normalized) * Mathf.Lerp(1f, 1.55f, Mathf.Clamp01(strength));
        }

        private static float BuildRhythmBreakLineComboStrength(int comboBeforeBreak)
        {
            if (comboBeforeBreak < 3)
            {
                return 0f;
            }

            return Mathf.Clamp01((comboBeforeBreak - 2) / 10f);
        }

        private void UpdateThreeActionExactBurst()
        {
            if (threeActionExactBurstPips == null)
            {
                return;
            }

            float remaining = threeActionExactBurstUntil - Time.unscaledTime;
            if (remaining <= 0f
                || !CanShowRunTransientFeedback())
            {
                HideThreeActionExactBurst();
                return;
            }

            float normalized = Mathf.Clamp01(remaining / ThreeActionExactBurstDuration);
            float age = 1f - normalized;
            float spread = BuildThreeActionExactBurstSpread(age);
            float rise = BuildThreeActionExactBurstRise(age);
            float scale = BuildThreeActionExactBurstScale(remaining);
            int alpha = Mathf.RoundToInt(BuildThreeActionExactBurstAlpha(remaining) * 255f);

            for (int i = 0; i < threeActionExactBurstPips.Length; i += 1)
            {
                Image pip = threeActionExactBurstPips[i];
                if (pip == null)
                {
                    continue;
                }

                float offsetIndex = i - (threeActionExactBurstPips.Length - 1) * 0.5f;
                RectTransform rect = pip.rectTransform;
                float x = Mathf.Clamp01(threeActionExactBurstX + offsetIndex * spread);
                float y = Mathf.Clamp01(threeActionExactBurstY + rise);
                rect.anchorMin = new Vector2(x, y);
                rect.anchorMax = new Vector2(x, y);
                rect.anchoredPosition = Vector2.zero;
                rect.localScale = Vector3.one * scale;
                rect.localEulerAngles = new Vector3(0f, 0f, Mathf.Lerp(-10f, 10f, i / (float)Mathf.Max(1, threeActionExactBurstPips.Length - 1)) * age);
                pip.color = WithAlpha(GetThreeActionExactBurstColor(i), alpha);
                pip.transform.SetAsLastSibling();
            }
        }

        private void HideThreeActionExactBurst()
        {
            if (threeActionExactBurstPips == null)
            {
                return;
            }

            for (int i = 0; i < threeActionExactBurstPips.Length; i += 1)
            {
                Image pip = threeActionExactBurstPips[i];
                if (pip == null)
                {
                    continue;
                }

                pip.color = WithAlpha(GetThreeActionExactBurstColor(i), 0);
                pip.rectTransform.localScale = Vector3.one;
                pip.rectTransform.localEulerAngles = Vector3.zero;
            }
        }

        private static float BuildThreeActionExactBurstAlpha(float remainingSeconds)
        {
            if (remainingSeconds <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remainingSeconds / ThreeActionExactBurstDuration);
            return Mathf.Pow(normalized, 0.72f);
        }

        private static float BuildThreeActionExactBurstScale(float remainingSeconds)
        {
            float normalized = Mathf.Clamp01(remainingSeconds / ThreeActionExactBurstDuration);
            return Mathf.Lerp(1.34f, 0.86f, normalized);
        }

        private static float BuildThreeActionExactBurstSpread(float normalizedAge)
        {
            return Mathf.Lerp(0.018f, 0.074f, Mathf.Clamp01(normalizedAge));
        }

        private static float BuildThreeActionExactBurstRise(float normalizedAge)
        {
            return Mathf.Sin(Mathf.Clamp01(normalizedAge) * Mathf.PI) * 0.038f;
        }

        private static Color32 GetThreeActionExactBurstColor(int index)
        {
            switch (Mathf.Clamp(index, 0, 2))
            {
                case 0:
                    return new Color32(255, 238, 181, 255);
                case 1:
                    return new Color32(145, 231, 199, 255);
                default:
                    return new Color32(168, 220, 226, 255);
            }
        }

        private static float BuildRunChannelAnchorX(GreedLastRunChannel channel)
        {
            switch (channel)
            {
                case GreedLastRunChannel.Left:
                    return 0.2f;
                case GreedLastRunChannel.Right:
                    return 0.8f;
                case GreedLastRunChannel.Center:
                default:
                    return 0.5f;
            }
        }

        private float BuildJudgementLinePulse()
        {
            float remaining = judgementLinePulseUntil - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            return Mathf.Clamp01(remaining / JudgementLinePulseDuration) * judgementLinePulseStrength;
        }

        private static float BuildJudgementLinePulseStrength(GreedLastJudgementResult result)
        {
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return 1.12f;
                case GreedLastJudgementResult.Good:
                    return 0.58f;
                case GreedLastJudgementResult.Miss:
                    return 0.78f;
                default:
                    return 0f;
            }
        }

        private static float BuildJudgementLineScaleY(float exactPulse, float judgementPulse)
        {
            return 1f + Mathf.Clamp01(exactPulse) * 0.32f + Mathf.Max(0f, judgementPulse) * 0.9f;
        }

        private static float BuildJudgementLineExactLock(float exactPulse, float contactPulse)
        {
            return Mathf.Clamp01(Mathf.Clamp01(exactPulse) * (0.80f + Mathf.Clamp01(contactPulse) * 0.20f));
        }

        private static float BuildJudgementLineExactColorBlend(float exactPulse, float exactLineLock)
        {
            return Mathf.Clamp01(Mathf.Clamp01(exactPulse) * 0.38f + Mathf.Clamp01(exactLineLock) * 0.18f);
        }

        private static float BuildJudgementLineScaleX(float contactPulse, float judgementPulse, float exactLineLock)
        {
            return BuildJudgementLineContactScaleX(contactPulse, judgementPulse)
                + Mathf.Clamp01(exactLineLock) * 0.006f;
        }

        private static float BuildJudgementLineExactScaleYLift(float exactLineLock)
        {
            return Mathf.Clamp01(exactLineLock) * 0.072f;
        }

        private static float BuildJudgementLineContactStrength(
            bool activePattern,
            bool blocked,
            float coreDeltaSeconds,
            float successWindowSeconds,
            float goodWindowSeconds,
            GreedLastTimingType timingType,
            bool infiniteMode,
            int infiniteThreatLevel,
            float beatPulse)
        {
            if (!activePattern || blocked)
            {
                return 0f;
            }

            float successWindow = Mathf.Max(0.01f, successWindowSeconds);
            float goodWindow = Mathf.Max(successWindow, Mathf.Max(0.01f, goodWindowSeconds));
            float successProximity = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / successWindow);
            float goodProximity = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / goodWindow);
            float timingLift;
            switch (timingType)
            {
                case GreedLastTimingType.Clutch:
                    timingLift = 1.10f;
                    break;
                case GreedLastTimingType.Offbeat:
                    timingLift = 1.05f;
                    break;
                default:
                    timingLift = 1f;
                    break;
            }

            float threatLift = infiniteMode
                ? Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.08f
                : 0f;
            float beatLift = 0.78f + Mathf.Clamp01(beatPulse) * 0.22f;
            return Mathf.Clamp01((goodProximity * 0.42f + successProximity * 0.48f + threatLift) * timingLift * beatLift);
        }

        private static float BuildJudgementLineContactScaleX(float contactPulse, float judgementPulse)
        {
            return 1f + Mathf.Clamp01(contactPulse) * 0.040f + Mathf.Clamp01(judgementPulse) * 0.018f;
        }

        private static float BuildJudgementLineContactScaleYLift(float contactPulse)
        {
            return Mathf.Clamp01(contactPulse) * 0.15f;
        }

        private static float BuildJudgementLineContactColorBlend(float contactPulse)
        {
            return Mathf.Clamp01(contactPulse) * 0.34f;
        }

        private static float BuildJudgementLineDownbeatLift(float downbeatPulse, float contactPulse, float exactLineLock)
        {
            float readiness = Mathf.Clamp01(0.18f + Mathf.Clamp01(contactPulse) * 0.58f + Mathf.Clamp01(exactLineLock) * 0.24f);
            return Mathf.Clamp01(downbeatPulse) * readiness;
        }

        private static float BuildJudgementLineDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.18f;
        }

        private static float BuildJudgementLineScaleXWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.014f;
        }

        private static float BuildJudgementLineDownbeatScaleYLift(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.038f;
        }

        private static int BuildJudgementLineBeatCueUrgencyAlphaLift(float beatCueUrgency)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(beatCueUrgency) * 14f);
        }

        private static float BuildJudgementLineBeatCueUrgencyColorBlend(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.13f;
        }

        private static float BuildJudgementLineBeatCueUrgencyScaleXLift(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.008f;
        }

        private static float BuildJudgementLineBeatCueUrgencyScaleYLift(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.030f;
        }

        private float BuildTrapEntryPulse()
        {
            float remaining = trapEntryPulseUntil - Time.unscaledTime;
            if (remaining <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remaining / TrapEntryPulseDuration);
            return Mathf.Sin(normalized * Mathf.PI);
        }

        private float BuildRunEntryTrapRevealStrength()
        {
            return BuildRunEntryTrapRevealStrengthForValues(
                latestRunSnapshot.ActivePattern,
                latestRunSnapshot.Paused,
                latestRunSnapshot.Stopped,
                latestRunSnapshot.CountdownActive,
                latestRunSnapshot.ChoiceActive,
                Time.unscaledTime,
                runEntryTrapRevealStartedAt,
                runEntryTrapRevealUntil);
        }

        internal static float BuildRunEntryTrapRevealStrengthForValues(
            bool activePattern,
            bool paused,
            bool stopped,
            bool countdownActive,
            bool choiceActive,
            float now,
            float startedAt,
            float until)
        {
            if (!activePattern
                || paused
                || stopped
                || countdownActive
                || choiceActive
                || until <= startedAt
                || now < startedAt
                || now >= until)
            {
                return 0f;
            }

            float progress = Mathf.Clamp01((now - startedAt) / Mathf.Max(0.01f, until - startedAt));
            return Mathf.Clamp01(Mathf.Sin(progress * Mathf.PI));
        }

        private void UpdateRunEntryTrapReveal(
            float markerX,
            float markerY,
            Vector2 markerSize,
            float strength,
            Color32 accentColor)
        {
            if (runEntryTrapRevealPieces == null)
            {
                return;
            }

            if (strength <= 0f)
            {
                HideRunEntryTrapReveal();
                return;
            }

            for (int i = 0; i < runEntryTrapRevealPieces.Length; i += 1)
            {
                Image piece = runEntryTrapRevealPieces[i];
                if (piece == null)
                {
                    continue;
                }

                Vector4 layout = BuildRunEntryTrapRevealPieceLayout(
                    i,
                    markerSize.x,
                    markerSize.y,
                    strength);
                RectTransform rect = piece.rectTransform;
                rect.anchorMin = new Vector2(markerX, markerY);
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = new Vector2(layout.x, layout.y);
                rect.sizeDelta = new Vector2(layout.z, layout.w);
                rect.localScale = Vector3.one;
                rect.localEulerAngles = Vector3.zero;
                Color32 revealColor = Color32.Lerp(PrototypeGoldColor, accentColor, 0.34f);
                piece.color = WithAlpha(
                    revealColor,
                    Mathf.RoundToInt(Mathf.Lerp(36f, 188f, strength)));
            }
        }

        internal static Vector4 BuildRunEntryTrapRevealPieceLayout(
            int pieceIndex,
            float markerWidth,
            float markerHeight,
            float strength)
        {
            int safeIndex = Mathf.Clamp(pieceIndex, 0, RunEntryTrapRevealPieceCount - 1);
            float safeStrength = Mathf.Clamp01(strength);
            float halfWidth = Mathf.Max(48f, markerWidth * 0.5f);
            float halfHeight = Mathf.Max(36f, markerHeight * 0.5f);
            float gap = Mathf.Lerp(54f, 18f, safeStrength);
            float horizontalLength = Mathf.Lerp(52f, 84f, safeStrength);
            float verticalLength = Mathf.Lerp(38f, 68f, safeStrength);

            switch (safeIndex)
            {
                case 0:
                    return new Vector4(0f, halfHeight + gap, horizontalLength, 7f);
                case 1:
                    return new Vector4(halfWidth + gap, 0f, 7f, verticalLength);
                case 2:
                    return new Vector4(0f, -halfHeight - gap, horizontalLength, 7f);
                default:
                    return new Vector4(-halfWidth - gap, 0f, 7f, verticalLength);
            }
        }

        private void HideRunEntryTrapReveal()
        {
            if (runEntryTrapRevealPieces == null)
            {
                return;
            }

            for (int i = 0; i < runEntryTrapRevealPieces.Length; i += 1)
            {
                Image piece = runEntryTrapRevealPieces[i];
                if (piece != null)
                {
                    piece.color = new Color32(255, 214, 105, 0);
                    piece.rectTransform.localScale = Vector3.one;
                }
            }
        }

        private float BuildExactTimingPulse()
        {
            if (!hasRunSnapshot
                || !runModeActive
                || !latestRunSnapshot.ActivePattern
                || latestRunSnapshot.Paused
                || latestRunSnapshot.CountdownActive
                || latestRunSnapshot.Stopped)
            {
                return 0f;
            }

            float successWindow = Mathf.Max(0.001f, latestRunSnapshot.Pattern.SuccessWindowSeconds);
            float absoluteDelta = Mathf.Abs(latestRunSnapshot.CoreDeltaSeconds);
            if (absoluteDelta > successWindow)
            {
                return 0f;
            }

            float centered = 1f - Mathf.Clamp01(absoluteDelta / successWindow);
            float centerWindow = BuildCenterHitWindow(latestRunSnapshot.Pattern);
            if (absoluteDelta <= centerWindow)
            {
                centered = Mathf.Lerp(centered, 1f, 0.42f);
            }

            float shimmer = 0.74f + Mathf.Sin(Time.unscaledTime * 54f) * 0.26f;
            return Mathf.Clamp01(centered * shimmer);
        }

        private static void UpdateTrapMarkerShape(RectTransform markerRect, GreedLastPatternModel pattern, float coreNear)
        {
            if (markerRect == null)
            {
                return;
            }

            Vector4 shape = BuildTrapMarkerShapeLayout(pattern, coreNear);
            markerRect.sizeDelta = new Vector2(shape.x, shape.y);
            markerRect.localEulerAngles = new Vector3(0f, 0f, shape.z);
        }

        private static Vector4 BuildTrapMarkerShapeLayout(GreedLastPatternModel pattern, float coreNear)
        {
            float safeCoreNear = Mathf.Clamp01(coreNear);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return new Vector4(
                        Mathf.Lerp(148f, 214f, safeCoreNear),
                        Mathf.Lerp(44f, 66f, safeCoreNear),
                        0f,
                        0f);
                case RunnerResponseType.Slide:
                    return new Vector4(
                        Mathf.Lerp(138f, 198f, safeCoreNear),
                        Mathf.Lerp(76f, 112f, safeCoreNear),
                        0f,
                        0f);
                case RunnerResponseType.Twist:
                    float direction = pattern.Channel == GreedLastRunChannel.Left ? -1f : pattern.Channel == GreedLastRunChannel.Right ? 1f : 0.5f;
                    return new Vector4(
                        Mathf.Lerp(34f, 52f, safeCoreNear),
                        Mathf.Lerp(126f, 184f, safeCoreNear),
                        direction * Mathf.Lerp(12f, 24f, safeCoreNear),
                        0f);
                default:
                    return new Vector4(128f, 128f, 0f, 0f);
            }
        }

        private static float BuildTrapMarkerResponseScaleX(
            GreedLastPatternModel pattern,
            float coreNear,
            float exactPulse,
            float entryPulse)
        {
            float pressure = BuildTrapMarkerResponsePressure(coreNear, exactPulse, entryPulse);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 1f + pressure * 0.095f;
                case RunnerResponseType.Slide:
                    return 1f - pressure * 0.026f;
                case RunnerResponseType.Twist:
                    return 1f - pressure * 0.018f;
                default:
                    return 1f;
            }
        }

        private static float BuildTrapMarkerResponseScaleY(
            GreedLastPatternModel pattern,
            float coreNear,
            float exactPulse,
            float entryPulse)
        {
            float pressure = BuildTrapMarkerResponsePressure(coreNear, exactPulse, entryPulse);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 1f - pressure * 0.038f;
                case RunnerResponseType.Slide:
                    return 1f + pressure * 0.095f;
                case RunnerResponseType.Twist:
                    return 1f + pressure * 0.082f;
                default:
                    return 1f;
            }
        }

        private static float BuildTrapMarkerResponseAngleLift(
            GreedLastPatternModel pattern,
            float coreNear,
            float exactPulse)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = pattern.Channel == GreedLastRunChannel.Left
                ? -1f
                : pattern.Channel == GreedLastRunChannel.Right ? 1f : 0.5f;
            float pressure = Mathf.Clamp01(Mathf.Clamp01(coreNear) * 0.62f + Mathf.Clamp01(exactPulse) * 0.38f);
            return direction * pressure * 3.2f;
        }

        private static float BuildTrapMarkerDownbeatLift(float downbeatPulse, float coreNear, float exactPulse)
        {
            float readiness = Mathf.Clamp01(Mathf.Clamp01(coreNear) * 0.72f + Mathf.Clamp01(exactPulse) * 0.28f);
            return Mathf.Clamp01(downbeatPulse) * readiness;
        }

        private static float BuildTrapMarkerDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.18f;
        }

        private static float BuildTrapMarkerDownbeatScaleX(GreedLastPatternModel pattern, float downbeatLift)
        {
            float safeLift = Mathf.Clamp01(downbeatLift);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 1f + safeLift * 0.050f;
                case RunnerResponseType.Slide:
                    return 1f + safeLift * 0.018f;
                case RunnerResponseType.Twist:
                    return 1f - safeLift * 0.010f;
                default:
                    return 1f + safeLift * 0.024f;
            }
        }

        private static float BuildTrapMarkerDownbeatScaleY(GreedLastPatternModel pattern, float downbeatLift)
        {
            float safeLift = Mathf.Clamp01(downbeatLift);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 1f + safeLift * 0.018f;
                case RunnerResponseType.Slide:
                    return 1f + safeLift * 0.052f;
                case RunnerResponseType.Twist:
                    return 1f + safeLift * 0.050f;
                default:
                    return 1f + safeLift * 0.024f;
            }
        }

        private static float BuildTrapMarkerDownbeatAngleLift(GreedLastPatternModel pattern, float downbeatLift)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = pattern.Channel == GreedLastRunChannel.Left
                ? -1f
                : pattern.Channel == GreedLastRunChannel.Right ? 1f : 0.5f;
            return direction * Mathf.Clamp01(downbeatLift) * 1.6f;
        }

        private static float BuildTrapMarkerBeatCueUrgency(float beatCueUrgency, float coreNear)
        {
            return Mathf.Clamp01(beatCueUrgency) * Mathf.Lerp(0.62f, 1f, Mathf.Clamp01(coreNear));
        }

        private static float BuildTrapMarkerBeatCueUrgencyColorBlend(float markerBeatCueUrgency)
        {
            return Mathf.Clamp01(markerBeatCueUrgency) * 0.12f;
        }

        private static float BuildTrapMarkerBeatCueUrgencyScaleXLift(GreedLastPatternModel pattern, float markerBeatCueUrgency)
        {
            float urgency = Mathf.Clamp01(markerBeatCueUrgency);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return urgency * 0.020f;
                case RunnerResponseType.Slide:
                    return urgency * 0.008f;
                case RunnerResponseType.Twist:
                    return urgency * 0.004f;
                default:
                    return urgency * 0.010f;
            }
        }

        private static float BuildTrapMarkerBeatCueUrgencyScaleYLift(GreedLastPatternModel pattern, float markerBeatCueUrgency)
        {
            float urgency = Mathf.Clamp01(markerBeatCueUrgency);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return urgency * 0.008f;
                case RunnerResponseType.Slide:
                    return urgency * 0.022f;
                case RunnerResponseType.Twist:
                    return urgency * 0.024f;
                default:
                    return urgency * 0.010f;
            }
        }

        private static float BuildTrapMarkerResponsePressure(float coreNear, float exactPulse, float entryPulse)
        {
            return Mathf.Clamp01(
                Mathf.Clamp01(coreNear) * 0.58f
                    + Mathf.Clamp01(exactPulse) * 0.32f
                    + Mathf.Clamp01(entryPulse) * 0.10f);
        }

        private void UpdateResolvedTrapAfterimage()
        {
            if (resolvedTrapAfterimage == null || resolvedTrapImpact == null)
            {
                return;
            }

            float remaining = resolvedTrapUntil - Time.unscaledTime;
            if (!runModeActive
                || !resolvedTrapPattern.IsValid
                || remaining <= 0f
                || !CanShowRunTransientFeedback())
            {
                HideResolvedTrapAfterimage();
                return;
            }

            float duration = Mathf.Max(0.01f, resolvedTrapUntil - resolvedTrapStartedAt);
            float progress = Mathf.Clamp01((Time.unscaledTime - resolvedTrapStartedAt) / duration);
            float eased = 1f - Mathf.Pow(1f - progress, 2f);
            float fade = BuildResolvedTrapAfterimageFade(progress);
            float channelX = resolvedTrapPattern.Channel == GreedLastRunChannel.Left
                ? 0.2f
                : resolvedTrapPattern.Channel == GreedLastRunChannel.Right
                    ? 0.8f
                    : 0.5f;
            float convergedX = Mathf.Lerp(channelX, 0.5f, Mathf.Clamp01(progress * 3.2f));
            RectTransform rect = resolvedTrapAfterimage.rectTransform;
            UpdateTrapMarkerShape(rect, resolvedTrapPattern, 1f);

            if (resolvedTrapResult == GreedLastJudgementResult.Miss)
            {
                float impactArc = Mathf.Sin(progress * Mathf.PI);
                float shake = Mathf.Sin(progress * Mathf.PI * 12f) * (1f - progress);
                rect.anchorMin = new Vector2(convergedX, Mathf.Lerp(0.18f, 0.155f, eased));
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = new Vector2(shake * 18f, 0f);
                rect.localScale = Vector3.one * (1f + impactArc * 0.28f);
                rect.localEulerAngles += new Vector3(0f, 0f, shake * 8f);
                resolvedTrapAfterimage.color = WithAlpha(new Color32(231, 91, 77, 255), Mathf.RoundToInt(235f * fade));

                RectTransform impactRect = resolvedTrapImpact.rectTransform;
                Vector4 impactLayout = BuildResolvedMissImpactLayout(resolvedTrapPattern);
                impactRect.anchorMin = new Vector2(impactLayout.x, impactLayout.y);
                impactRect.anchorMax = impactRect.anchorMin;
                impactRect.anchoredPosition = Vector2.zero;
                impactRect.sizeDelta = new Vector2(impactLayout.z, impactLayout.w);
                impactRect.localEulerAngles = new Vector3(0f, 0f, BuildResolvedMissImpactAngle(resolvedTrapPattern));
                switch (BuildRunnerResponseType(resolvedTrapPattern))
                {
                    case RunnerResponseType.Jump:
                        impactRect.localScale = new Vector3(
                            Mathf.Lerp(0.34f, 1.58f, eased),
                            0.82f + impactArc * 0.34f,
                            1f);
                        break;
                    case RunnerResponseType.Slide:
                        impactRect.localScale = new Vector3(
                            0.86f + impactArc * 0.20f,
                            Mathf.Lerp(0.38f, 1.36f, eased),
                            1f);
                        break;
                    default:
                        impactRect.localScale = Vector3.one * Mathf.Lerp(0.42f, 1.48f, eased);
                        break;
                }
                resolvedTrapImpact.color = new Color32(231, 91, 77, (byte)Mathf.RoundToInt(118f * impactArc * fade));
                UpdateResolvedJudgementImpactWake(resolvedTrapPattern, resolvedTrapResult, progress, fade);
                return;
            }

            RunnerResponseType response = BuildRunnerResponseType(resolvedTrapPattern);
            float avoidanceStrength = BuildResolvedTrapAvoidanceStrength(resolvedTrapResult);
            float avoidanceEase = eased * avoidanceStrength;
            float x = convergedX;
            float y;
            switch (response)
            {
                case RunnerResponseType.Jump:
                    y = Mathf.Lerp(0.18f, 0.055f, avoidanceEase);
                    rect.localScale = new Vector3(Mathf.Lerp(1.04f, 1.32f, avoidanceEase), Mathf.Lerp(1f, 0.72f, avoidanceEase), 1f);
                    break;
                case RunnerResponseType.Slide:
                    y = Mathf.Lerp(0.205f, 0.105f, avoidanceEase);
                    rect.localScale = new Vector3(Mathf.Lerp(1f, 1.38f, avoidanceEase), Mathf.Lerp(1f, 0.82f, avoidanceEase), 1f);
                    break;
                default:
                    float direction = resolvedTrapPattern.Channel == GreedLastRunChannel.Right ? -1f : 1f;
                    x += direction * avoidanceEase * 0.16f;
                    y = Mathf.Lerp(0.18f, 0.095f, avoidanceEase);
                    rect.localScale = new Vector3(Mathf.Lerp(1f, 0.72f, avoidanceEase), Mathf.Lerp(1f, 1.28f, avoidanceEase), 1f);
                    rect.localEulerAngles += new Vector3(0f, 0f, direction * avoidanceEase * 22f);
                    break;
            }

            rect.anchorMin = new Vector2(Mathf.Clamp01(x), y);
            rect.anchorMax = rect.anchorMin;
            rect.anchoredPosition = Vector2.zero;
            int alpha = BuildResolvedTrapAfterimageAlpha(resolvedTrapResult, fade);
            resolvedTrapAfterimage.color = WithAlpha(resolvedTrapColor, alpha);
            UpdateResolvedAvoidanceTrail(resolvedTrapPattern, resolvedTrapResult, x, y, progress, fade);
            UpdateResolvedJudgementImpactWake(resolvedTrapPattern, resolvedTrapResult, progress, fade);
        }

        private void UpdatePrototypeTrapIllustration(GreedLastPatternModel pattern, Color32 markerColor)
        {
            if (trapIllustration == null)
            {
                return;
            }

            Vector4 uv = BuildPrototypeTrapAtlasUv(pattern);
            trapIllustration.uvRect = new Rect(uv.x, uv.y, uv.z, uv.w);
            trapIllustration.color = BuildPrototypeTrapIllustrationTint(markerColor);
            trapIllustration.rectTransform.localScale = new Vector3(
                BuildPrototypeTrapIllustrationMirrorX(pattern),
                1f,
                1f);
        }

        private static Vector4 BuildPrototypeTrapAtlasUv(GreedLastPatternModel pattern)
        {
            const float cellWidth = 1f / 3f;
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return new Vector4(0f, 0f, cellWidth, 1f);
                case RunnerResponseType.Slide:
                    return new Vector4(cellWidth, 0f, cellWidth, 1f);
                case RunnerResponseType.Twist:
                    return new Vector4(cellWidth * 2f, 0f, cellWidth, 1f);
                default:
                    return new Vector4(cellWidth, 0f, cellWidth, 1f);
            }
        }

        private static float BuildPrototypeTrapIllustrationMirrorX(GreedLastPatternModel pattern)
        {
            return BuildRunnerResponseType(pattern) == RunnerResponseType.Twist
                && pattern.Channel == GreedLastRunChannel.Right
                    ? -1f
                    : 1f;
        }

        private static int BuildPrototypeTrapProceduralAlpha(bool hasIllustration, int baseAlpha)
        {
            int safeAlpha = Mathf.Clamp(baseAlpha, 0, 255);
            return hasIllustration ? Mathf.Min(46, safeAlpha) : safeAlpha;
        }

        private static Color32 BuildPrototypeTrapIllustrationTint(Color32 markerColor)
        {
            return WithAlpha(Color32.Lerp(new Color32(255, 255, 255, 255), markerColor, 0.10f), 244);
        }

        private void UpdateResolvedAvoidanceTrail(
            GreedLastPatternModel pattern,
            GreedLastJudgementResult result,
            float x,
            float y,
            float progress,
            float fade)
        {
            if (resolvedTrapImpact == null)
            {
                return;
            }

            int alpha = BuildResolvedAvoidanceTrailAlpha(result, progress, fade);
            if (alpha <= 0)
            {
                resolvedTrapImpact.color = new Color32(231, 91, 77, 0);
                resolvedTrapImpact.rectTransform.localScale = Vector3.one;
                resolvedTrapImpact.rectTransform.localEulerAngles = Vector3.zero;
                return;
            }

            RectTransform impactRect = resolvedTrapImpact.rectTransform;
            Vector4 layout = BuildResolvedAvoidanceTrailLayout(pattern, x, y);
            impactRect.anchorMin = new Vector2(layout.x, layout.y);
            impactRect.anchorMax = impactRect.anchorMin;
            impactRect.anchoredPosition = Vector2.zero;
            impactRect.sizeDelta = new Vector2(layout.z, layout.w);
            impactRect.localEulerAngles = new Vector3(0f, 0f, BuildResolvedAvoidanceTrailAngle(pattern));
            impactRect.localScale = Vector3.one * BuildResolvedAvoidanceTrailScale(result, progress);
            Color32 trailColor = Color32.Lerp(
                resolvedTrapColor,
                new Color32(255, 248, 210, 255),
                result == GreedLastJudgementResult.Success ? 0.42f : 0.18f);
            resolvedTrapImpact.color = WithAlpha(trailColor, alpha);
        }

        private static float BuildResolvedTrapAfterimageFade(float progress)
        {
            return 1f - Mathf.Clamp01((Mathf.Clamp01(progress) - 0.42f) / 0.58f);
        }

        private static float BuildResolvedTrapAvoidanceStrength(GreedLastJudgementResult result)
        {
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return 1f;
                case GreedLastJudgementResult.Good:
                    return 0.62f;
                default:
                    return 0f;
            }
        }

        private static int BuildResolvedTrapAfterimageAlpha(GreedLastJudgementResult result, float fade)
        {
            float clampedFade = Mathf.Clamp01(fade);
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return Mathf.RoundToInt(222f * clampedFade);
                case GreedLastJudgementResult.Good:
                    return Mathf.RoundToInt(172f * clampedFade);
                case GreedLastJudgementResult.Miss:
                    return Mathf.RoundToInt(235f * clampedFade);
                default:
                    return 0;
            }
        }

        private static Vector4 BuildResolvedAvoidanceTrailLayout(GreedLastPatternModel pattern, float x, float y)
        {
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return new Vector4(Mathf.Clamp01(x), Mathf.Clamp01(y + 0.025f), 260f, 30f);
                case RunnerResponseType.Slide:
                    return new Vector4(Mathf.Clamp01(x), Mathf.Clamp01(y + 0.020f), 286f, 22f);
                case RunnerResponseType.Twist:
                    return new Vector4(Mathf.Clamp01(x), Mathf.Clamp01(y + 0.060f), 38f, 226f);
                default:
                    return new Vector4(Mathf.Clamp01(x), Mathf.Clamp01(y), 170f, 24f);
            }
        }

        private static float BuildResolvedAvoidanceTrailAngle(GreedLastPatternModel pattern)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = pattern.Channel == GreedLastRunChannel.Right ? -1f : 1f;
            return direction * 28f;
        }

        private static int BuildResolvedAvoidanceTrailAlpha(
            GreedLastJudgementResult result,
            float progress,
            float fade)
        {
            if (result != GreedLastJudgementResult.Success && result != GreedLastJudgementResult.Good)
            {
                return 0;
            }

            float arc = Mathf.Sin(Mathf.Clamp01(progress) * Mathf.PI);
            float baseAlpha = result == GreedLastJudgementResult.Success ? 104f : 58f;
            return Mathf.RoundToInt(baseAlpha * Mathf.Clamp01(arc) * Mathf.Clamp01(fade));
        }

        private static float BuildResolvedAvoidanceTrailScale(GreedLastJudgementResult result, float progress)
        {
            if (result != GreedLastJudgementResult.Success && result != GreedLastJudgementResult.Good)
            {
                return 1f;
            }

            float arc = Mathf.Sin(Mathf.Clamp01(progress) * Mathf.PI);
            float baseScale = result == GreedLastJudgementResult.Success ? 0.96f : 0.88f;
            float lift = result == GreedLastJudgementResult.Success ? 0.24f : 0.16f;
            return baseScale + Mathf.Clamp01(arc) * lift;
        }

        private void UpdateResolvedJudgementImpactWake(
            GreedLastPatternModel pattern,
            GreedLastJudgementResult result,
            float progress,
            float fade)
        {
            if (resolvedJudgementWake == null)
            {
                return;
            }

            int alpha = BuildResolvedJudgementImpactWakeAlpha(result, progress, fade);
            if (alpha <= 0)
            {
                HideResolvedJudgementImpactWake();
                return;
            }

            RectTransform wakeRect = resolvedJudgementWake.rectTransform;
            Vector4 layout = BuildResolvedJudgementImpactWakeLayout(pattern, result, progress);
            wakeRect.anchorMin = new Vector2(layout.x, layout.y);
            wakeRect.anchorMax = wakeRect.anchorMin;
            wakeRect.anchoredPosition = Vector2.zero;
            wakeRect.sizeDelta = new Vector2(layout.z, layout.w);
            wakeRect.localEulerAngles = new Vector3(0f, 0f, BuildResolvedJudgementImpactWakeAngle(pattern, result, progress));
            wakeRect.localScale = Vector3.one * BuildResolvedJudgementImpactWakeScale(result, progress);

            Color32 baseColor = BuildResolvedJudgementImpactWakeColor(result);
            Color32 highlightColor = result == GreedLastJudgementResult.Miss
                ? new Color32(255, 154, 116, 255)
                : new Color32(255, 248, 210, 255);
            resolvedJudgementWake.color = WithAlpha(
                Color32.Lerp(baseColor, highlightColor, BuildResolvedJudgementImpactWakeColorBlend(result, progress)),
                alpha);
        }

        private static Vector4 BuildResolvedJudgementImpactWakeLayout(
            GreedLastPatternModel pattern,
            GreedLastJudgementResult result,
            float progress)
        {
            if (result == GreedLastJudgementResult.None)
            {
                return new Vector4(0.5f, 0.16f, 0f, 0f);
            }

            float p = Mathf.Clamp01(progress);
            float arc = Mathf.Sin(p * Mathf.PI);
            float resultStrength = BuildResolvedJudgementImpactWakeResultStrength(result);
            float spread = Mathf.Clamp01(p * resultStrength + Mathf.Clamp01(arc) * 0.35f);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return new Vector4(
                        0.5f,
                        Mathf.Lerp(0.132f, result == GreedLastJudgementResult.Miss ? 0.112f : 0.172f, p),
                        Mathf.Lerp(150f, result == GreedLastJudgementResult.Good ? 270f : result == GreedLastJudgementResult.Miss ? 330f : 360f, spread),
                        Mathf.Lerp(14f, result == GreedLastJudgementResult.Miss ? 52f : 38f, Mathf.Clamp01(arc)));
                case RunnerResponseType.Slide:
                    return new Vector4(
                        0.5f,
                        Mathf.Lerp(0.315f, result == GreedLastJudgementResult.Miss ? 0.260f : 0.235f, p),
                        Mathf.Lerp(125f, result == GreedLastJudgementResult.Good ? 242f : result == GreedLastJudgementResult.Miss ? 260f : 292f, spread),
                        Mathf.Lerp(28f, result == GreedLastJudgementResult.Miss ? 92f : 68f, Mathf.Clamp01(arc)));
                case RunnerResponseType.Twist:
                    float direction = pattern.Channel == GreedLastRunChannel.Left ? -1f : pattern.Channel == GreedLastRunChannel.Right ? 1f : 0f;
                    return new Vector4(
                        Mathf.Clamp01(0.5f + direction * Mathf.Lerp(0.055f, result == GreedLastJudgementResult.Miss ? 0.120f : 0.150f, spread)),
                        Mathf.Lerp(0.190f, result == GreedLastJudgementResult.Miss ? 0.165f : 0.220f, p),
                        Mathf.Lerp(24f, result == GreedLastJudgementResult.Good ? 42f : result == GreedLastJudgementResult.Miss ? 58f : 54f, Mathf.Clamp01(arc)),
                        Mathf.Lerp(138f, result == GreedLastJudgementResult.Good ? 230f : result == GreedLastJudgementResult.Miss ? 310f : 286f, spread));
                default:
                    return new Vector4(
                        0.5f,
                        Mathf.Lerp(0.155f, 0.185f, p),
                        Mathf.Lerp(130f, result == GreedLastJudgementResult.Good ? 220f : 282f, spread),
                        Mathf.Lerp(22f, result == GreedLastJudgementResult.Miss ? 72f : 42f, Mathf.Clamp01(arc)));
            }
        }

        private static float BuildResolvedJudgementImpactWakeAngle(
            GreedLastPatternModel pattern,
            GreedLastJudgementResult result,
            float progress)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = pattern.Channel == GreedLastRunChannel.Left ? -1f : 1f;
            float angle = result == GreedLastJudgementResult.Good ? 22f : result == GreedLastJudgementResult.Miss ? 38f : 30f;
            return direction * Mathf.Lerp(angle * 0.62f, angle, Mathf.Clamp01(progress));
        }

        private static int BuildResolvedJudgementImpactWakeAlpha(
            GreedLastJudgementResult result,
            float progress,
            float fade)
        {
            if (result == GreedLastJudgementResult.None)
            {
                return 0;
            }

            float p = Mathf.Clamp01(progress);
            float arc = Mathf.Sin(p * Mathf.PI);
            float baseAlpha = result == GreedLastJudgementResult.Success
                ? 128f
                : result == GreedLastJudgementResult.Good
                    ? 72f
                    : 118f;
            return Mathf.RoundToInt(baseAlpha * Mathf.Clamp01(arc) * Mathf.Clamp01(fade));
        }

        private static float BuildResolvedJudgementImpactWakeScale(
            GreedLastJudgementResult result,
            float progress)
        {
            if (result == GreedLastJudgementResult.None)
            {
                return 1f;
            }

            float arc = Mathf.Sin(Mathf.Clamp01(progress) * Mathf.PI);
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return 0.92f + Mathf.Clamp01(arc) * 0.34f;
                case GreedLastJudgementResult.Good:
                    return 0.88f + Mathf.Clamp01(arc) * 0.22f;
                case GreedLastJudgementResult.Miss:
                    return 0.98f + Mathf.Clamp01(arc) * 0.42f;
                default:
                    return 1f;
            }
        }

        private static float BuildResolvedJudgementImpactWakeColorBlend(
            GreedLastJudgementResult result,
            float progress)
        {
            float arc = Mathf.Sin(Mathf.Clamp01(progress) * Mathf.PI);
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return 0.36f + Mathf.Clamp01(arc) * 0.24f;
                case GreedLastJudgementResult.Good:
                    return 0.18f + Mathf.Clamp01(arc) * 0.16f;
                case GreedLastJudgementResult.Miss:
                    return 0.04f + Mathf.Clamp01(arc) * 0.10f;
                default:
                    return 0f;
            }
        }

        private static Color32 BuildResolvedJudgementImpactWakeColor(GreedLastJudgementResult result)
        {
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return new Color32(255, 214, 105, 255);
                case GreedLastJudgementResult.Good:
                    return new Color32(132, 190, 208, 255);
                case GreedLastJudgementResult.Miss:
                    return new Color32(231, 91, 77, 255);
                default:
                    return new Color32(255, 238, 181, 0);
            }
        }

        private static float BuildResolvedJudgementImpactWakeResultStrength(GreedLastJudgementResult result)
        {
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return 1f;
                case GreedLastJudgementResult.Good:
                    return 0.68f;
                case GreedLastJudgementResult.Miss:
                    return 0.92f;
                default:
                    return 0f;
            }
        }

        private void HideResolvedJudgementImpactWake()
        {
            if (resolvedJudgementWake == null)
            {
                return;
            }

            resolvedJudgementWake.color = new Color32(255, 238, 181, 0);
            resolvedJudgementWake.rectTransform.localScale = Vector3.one;
            resolvedJudgementWake.rectTransform.localEulerAngles = Vector3.zero;
        }

        private void HideResolvedTrapAfterimage()
        {
            if (resolvedTrapAfterimage != null)
            {
                resolvedTrapAfterimage.color = new Color32(255, 238, 181, 0);
                resolvedTrapAfterimage.rectTransform.localScale = Vector3.one;
            }

            if (resolvedTrapImpact != null)
            {
                resolvedTrapImpact.color = new Color32(231, 91, 77, 0);
                resolvedTrapImpact.rectTransform.localScale = Vector3.one;
                resolvedTrapImpact.rectTransform.localEulerAngles = Vector3.zero;
            }

            HideResolvedJudgementImpactWake();
        }

        private static Vector4 BuildResolvedMissImpactLayout(GreedLastPatternModel pattern)
        {
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return new Vector4(0.5f, 0.145f, 310f, 46f);
                case RunnerResponseType.Slide:
                    return new Vector4(0.5f, 0.30f, 218f, 78f);
                case RunnerResponseType.Twist:
                    float direction = pattern.Channel == GreedLastRunChannel.Left ? -1f : 1f;
                    return new Vector4(0.5f + direction * 0.075f, 0.19f, 48f, 268f);
                default:
                    return new Vector4(0.5f, 0.155f, 170f, 170f);
            }
        }

        private static float BuildResolvedMissImpactAngle(GreedLastPatternModel pattern)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = pattern.Channel == GreedLastRunChannel.Left ? -1f : 1f;
            return direction * 32f;
        }

        private static float BuildMissHapticDuration(GreedLastPatternModel pattern)
        {
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 0.060f;
                case RunnerResponseType.Slide:
                    return 0.085f;
                case RunnerResponseType.Twist:
                    return 0.070f;
                default:
                    return 0.075f;
            }
        }

        private static float BuildJudgementHapticDuration(
            GreedLastRunSnapshot snapshot,
            float baseSeconds,
            bool reviewTargetAchievementJustReached)
        {
            return BuildJudgementHapticDurationFromValues(
                baseSeconds,
                snapshot.LastResult,
                snapshot.LastCenterHit,
                snapshot.Combo,
                snapshot.FocusStateActive,
                snapshot.InfiniteMode,
                snapshot.InfiniteThreatLevel,
                snapshot.Phase == GreedLastRunPhase.EscapeRunning,
                BuildJudgementBeatCueUrgency(snapshot),
                reviewTargetAchievementJustReached);
        }

        private static float BuildJudgementHapticDurationFromValues(
            float baseSeconds,
            GreedLastJudgementResult result,
            bool centerHit,
            int combo,
            bool focusStateActive,
            bool infiniteMode,
            int infiniteThreatLevel,
            bool escapeRunning,
            float beatCueUrgency,
            bool reviewTargetAchievementJustReached)
        {
            if (baseSeconds <= 0f || result == GreedLastJudgementResult.None)
            {
                return 0f;
            }

            float urgency = Mathf.Clamp01(beatCueUrgency);
            float seconds = baseSeconds;
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    seconds += centerHit ? 0.004f : 0f;
                    seconds += Mathf.Clamp01(combo / 12f) * 0.006f;
                    seconds += focusStateActive ? 0.003f : 0f;
                    seconds += escapeRunning ? 0.003f : 0f;
                    seconds += urgency * 0.006f;
                    break;
                case GreedLastJudgementResult.Good:
                    seconds += centerHit ? 0.002f : 0f;
                    seconds += focusStateActive ? 0.003f : 0f;
                    seconds += urgency * 0.003f;
                    break;
                case GreedLastJudgementResult.Miss:
                    seconds += escapeRunning ? 0.006f : 0f;
                    seconds += urgency * 0.008f;
                    break;
            }

            if (infiniteMode)
            {
                float threat = Mathf.Clamp01((infiniteThreatLevel - 1) / 4f);
                seconds += result == GreedLastJudgementResult.Miss ? threat * 0.010f : threat * 0.004f;
            }

            if (reviewTargetAchievementJustReached)
            {
                seconds = Mathf.Max(seconds + 0.005f, result == GreedLastJudgementResult.Miss ? 0.070f : 0.050f);
            }

            return Mathf.Clamp(seconds, 0.008f, 0.115f);
        }

        private static float BuildJudgementBeatCueUrgency(GreedLastRunSnapshot snapshot)
        {
            return BuildJudgementBeatCueUrgencyFromValues(
                snapshot.Pattern.IsValid,
                snapshot.CoreDeltaSeconds,
                snapshot.Pattern.SuccessWindowSeconds,
                snapshot.Pattern.GoodWindowSeconds,
                BuildActiveBeatCueUrgency(snapshot));
        }

        private static float BuildJudgementBeatCueUrgencyFromValues(
            bool patternValid,
            float coreDeltaSeconds,
            float successWindowSeconds,
            float goodWindowSeconds,
            float liveBeatCueUrgency)
        {
            float liveUrgency = Mathf.Clamp01(liveBeatCueUrgency);
            if (!patternValid)
            {
                return liveUrgency;
            }

            float absoluteDelta = Mathf.Abs(coreDeltaSeconds);
            float successWindow = Mathf.Max(0.001f, successWindowSeconds);
            float goodWindow = Mathf.Max(successWindow + 0.001f, goodWindowSeconds);
            if (absoluteDelta <= successWindow)
            {
                return 1f;
            }

            if (absoluteDelta <= goodWindow)
            {
                float lateGoodRatio = Mathf.Clamp01((absoluteDelta - successWindow) / Mathf.Max(0.001f, goodWindow - successWindow));
                return Mathf.Max(liveUrgency, Mathf.Lerp(0.86f, 0.56f, lateGoodRatio));
            }

            return liveUrgency;
        }

        private static float BuildJudgementCueVolume(GreedLastRunSnapshot snapshot)
        {
            return BuildJudgementCueVolumeFromValues(
                snapshot.LastResult,
                snapshot.LastCenterHit,
                snapshot.Combo,
                snapshot.FocusStateActive,
                snapshot.InfiniteMode,
                snapshot.InfiniteThreatLevel,
                snapshot.Phase == GreedLastRunPhase.EscapeRunning);
        }

        private static float BuildJudgementCueVolumeFromValues(
            GreedLastJudgementResult result,
            bool centerHit,
            int combo,
            bool focusStateActive,
            bool infiniteMode,
            int infiniteThreatLevel,
            bool escapeRunning)
        {
            float volume;
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    volume = 0.50f
                        + (centerHit ? 0.06f : 0f)
                        + Mathf.Clamp01(combo / 12f) * 0.08f
                        + (focusStateActive ? 0.035f : 0f)
                        + (escapeRunning ? 0.025f : 0f);
                    break;
                case GreedLastJudgementResult.Good:
                    volume = 0.32f
                        + (centerHit ? 0.025f : 0f)
                        + (focusStateActive ? 0.025f : 0f);
                    break;
                case GreedLastJudgementResult.Miss:
                    volume = 0.44f
                        + (centerHit ? 0.025f : 0f)
                        + Mathf.Clamp01(combo / 10f) * 0.035f
                        + (escapeRunning ? 0.035f : 0f);
                    break;
                default:
                    return 0f;
            }

            if (infiniteMode)
            {
                float threat = Mathf.Clamp01((infiniteThreatLevel - 1) / 4f);
                volume += result == GreedLastJudgementResult.Miss ? threat * 0.060f : threat * 0.035f;
            }

            return Mathf.Clamp(volume, 0.20f, 0.68f);
        }

        private void UpdateTrapApproachGhosts(float channelX, float linearProgress, float coreProgress, float coreNear)
        {
            if (trapApproachGhosts == null)
            {
                return;
            }

            Color32 baseColor = BuildPrototypeTrapBaseColor(latestRunSnapshot.Pattern);
            Color32 accentColor = BuildPrototypeTrapAccentColor(latestRunSnapshot.Pattern);
            if (TryGetPatternVariationAccent(latestRunSnapshot.Pattern, out Color32 variationColor, out float variationStrength))
            {
                baseColor = Color32.Lerp(baseColor, variationColor, variationStrength * 0.56f);
                accentColor = Color32.Lerp(accentColor, variationColor, variationStrength * 0.42f);
            }

            float downbeatPulse = ShouldShowDownbeatPulse(latestRunSnapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;
            float variationPressure = BuildTrapVariationPressure(latestRunSnapshot.Pattern);
            for (int i = 0; i < trapApproachGhosts.Length; i += 1)
            {
                Image ghost = trapApproachGhosts[i];
                if (ghost == null)
                {
                    continue;
                }

                float alpha = BuildTrapApproachGhostAlpha(
                    latestRunSnapshot.Pattern,
                    linearProgress,
                    coreProgress,
                    coreNear,
                    i);
                if (alpha <= 0f)
                {
                    ghost.color = new Color32(207, 87, 65, 0);
                    continue;
                }

                float approachPressure = BuildTrapApproachGhostPressure(
                    coreNear,
                    latestRunSnapshot.InfiniteMode,
                    latestRunSnapshot.InfiniteThreatLevel,
                    variationPressure);
                float ghostDownbeatLift = BuildTrapApproachGhostDownbeatLift(downbeatPulse, coreNear, approachPressure, i);
                Vector4 layout = BuildTrapApproachGhostLayoutWithPreview(
                    latestRunSnapshot.Pattern,
                    channelX,
                    linearProgress,
                    coreProgress,
                    i,
                    devTrapVisualPreviewMode);
                RectTransform rect = ghost.rectTransform;
                rect.anchorMin = new Vector2(layout.x, layout.y);
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = Vector2.zero;
                float pressureScale = BuildTrapApproachGhostPressureScale(approachPressure, i);
                float downbeatScale = BuildTrapApproachGhostDownbeatScaleLift(ghostDownbeatLift, i);
                rect.sizeDelta = new Vector2(layout.z * (pressureScale + downbeatScale), layout.w * (pressureScale + downbeatScale));
                rect.localScale = Vector3.one;
                float baseAngle = BuildTrapStrikeAngle(latestRunSnapshot.Pattern);
                rect.localEulerAngles = new Vector3(
                    0f,
                    0f,
                    BuildTrapApproachGhostPressureAngle(baseAngle, approachPressure, i)
                        + BuildTrapApproachGhostDownbeatAngleLift(baseAngle, ghostDownbeatLift, i));
                Color32 ghostColor = Color32.Lerp(
                    baseColor,
                    accentColor,
                    BuildTrapApproachGhostPressureColorBlend(approachPressure, i));
                if (ghostDownbeatLift > 0f)
                {
                    ghostColor = Color32.Lerp(
                        ghostColor,
                        new Color32(255, 214, 105, 255),
                        BuildTrapApproachGhostDownbeatColorBlend(ghostDownbeatLift, i));
                }

                ghost.color = WithAlpha(
                    ghostColor,
                    Mathf.RoundToInt(BuildTrapApproachGhostDownbeatAlpha(
                        BuildTrapApproachGhostPressureAlpha(alpha, approachPressure, i),
                        ghostDownbeatLift,
                        i) * 255f));
            }
        }

        private static Vector4 BuildTrapApproachGhostLayout(
            GreedLastPatternModel pattern,
            float channelX,
            float linearProgress,
            float coreProgress,
            int ghostIndex)
        {
            return BuildTrapApproachGhostLayoutWithPreview(
                pattern,
                channelX,
                linearProgress,
                coreProgress,
                ghostIndex,
                0);
        }

        private static Vector4 BuildTrapApproachGhostLayoutWithPreview(
            GreedLastPatternModel pattern,
            float channelX,
            float linearProgress,
            float coreProgress,
            int ghostIndex,
            int previewMode)
        {
            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            float ghostProgress = Mathf.Clamp01(linearProgress - (safeIndex + 1) * 0.105f);
            float ghostVisualProgress = BuildTrapVisualProgress(pattern.TimingType, ghostProgress, coreProgress);
            ghostVisualProgress = BuildTrapVisualPreviewProgress(ghostVisualProgress, coreProgress, previewMode, true);
            float x = Mathf.Clamp01(
                channelX
                    + BuildTrapVisualHorizontalOffset(pattern.TimingType, ghostProgress, coreProgress)
                    + BuildTrapApproachSweepX(pattern, ghostVisualProgress));
            float y = Mathf.Lerp(BuildTrapApproachStartY(pattern), 0.18f, ghostVisualProgress);
            Vector4 shape = BuildTrapMarkerShapeLayout(pattern, Mathf.Clamp01(1f - safeIndex * 0.22f));
            float scale = Mathf.Clamp(0.76f - safeIndex * 0.12f, 0.46f, 0.80f);
            return new Vector4(x, y, shape.x * scale, shape.y * scale);
        }

        private static float BuildTrapApproachGhostAlpha(
            GreedLastPatternModel pattern,
            float linearProgress,
            float coreProgress,
            float coreNear,
            int ghostIndex)
        {
            if (!pattern.IsValid)
            {
                return 0f;
            }

            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            float ghostProgress = linearProgress - (safeIndex + 1) * 0.105f;
            if (ghostProgress <= 0f || linearProgress >= 0.985f)
            {
                return 0f;
            }

            float born = Mathf.Clamp01(ghostProgress / 0.18f);
            float coreFade = Mathf.Lerp(0.62f, 1f, Mathf.Clamp01(coreNear));
            float coreProgressBoost = Mathf.Clamp01(coreProgress * 1.35f);
            float baseAlpha = 0.36f - safeIndex * 0.075f;
            return Mathf.Clamp01(baseAlpha * born * coreFade * Mathf.Lerp(0.72f, 1f, coreProgressBoost));
        }

        private static float BuildTrapApproachGhostPressure(
            float coreNear,
            bool infiniteMode,
            int infiniteThreatLevel,
            float variationPressure)
        {
            float pressure = Mathf.Clamp01(coreNear) * 0.70f + Mathf.Max(0f, variationPressure) * 0.24f;
            if (infiniteMode)
            {
                pressure += Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.20f;
            }

            return Mathf.Clamp01(pressure);
        }

        private static float BuildTrapApproachGhostPressureScale(float approachPressure, int ghostIndex)
        {
            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            float indexFalloff = 1f - safeIndex * 0.16f;
            return 1f + Mathf.Clamp01(approachPressure) * Mathf.Clamp(indexFalloff, 0.54f, 1f) * 0.14f;
        }

        private static float BuildTrapApproachGhostPressureAlpha(float baseAlpha, float approachPressure, int ghostIndex)
        {
            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            float lift = Mathf.Clamp01(approachPressure) * (0.13f - safeIndex * 0.028f);
            return Mathf.Clamp01(baseAlpha + Mathf.Max(0f, lift));
        }

        private static float BuildTrapApproachGhostPressureColorBlend(float approachPressure, int ghostIndex)
        {
            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            return Mathf.Clamp01(0.32f + Mathf.Clamp01(approachPressure) * (0.18f - safeIndex * 0.035f));
        }

        private static float BuildTrapApproachGhostPressureAngle(float baseAngle, float approachPressure, int ghostIndex)
        {
            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            return baseAngle * (0.18f + Mathf.Clamp01(approachPressure) * 0.08f)
                + (safeIndex - 1) * Mathf.Clamp01(approachPressure) * 1.6f;
        }

        private static float BuildTrapApproachGhostDownbeatLift(
            float downbeatPulse,
            float coreNear,
            float approachPressure,
            int ghostIndex)
        {
            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            float indexFalloff = 1f - safeIndex * 0.20f;
            float readiness = Mathf.Clamp01(0.12f + Mathf.Clamp01(coreNear) * 0.52f + Mathf.Clamp01(approachPressure) * 0.36f);
            return Mathf.Clamp01(downbeatPulse) * readiness * Mathf.Clamp(indexFalloff, 0.48f, 1f);
        }

        private static float BuildTrapApproachGhostDownbeatScaleLift(float downbeatLift, int ghostIndex)
        {
            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            return Mathf.Clamp01(downbeatLift) * Mathf.Clamp(0.050f - safeIndex * 0.008f, 0.025f, 0.050f);
        }

        private static float BuildTrapApproachGhostDownbeatAlpha(float baseAlpha, float downbeatLift, int ghostIndex)
        {
            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            float lift = Mathf.Clamp01(downbeatLift) * Mathf.Clamp(0.075f - safeIndex * 0.012f, 0.034f, 0.075f);
            return Mathf.Clamp01(Mathf.Clamp01(baseAlpha) + lift);
        }

        private static float BuildTrapApproachGhostDownbeatColorBlend(float downbeatLift, int ghostIndex)
        {
            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            return Mathf.Clamp01(downbeatLift) * Mathf.Clamp(0.140f - safeIndex * 0.018f, 0.080f, 0.140f);
        }

        private static float BuildTrapApproachGhostDownbeatAngleLift(float baseAngle, float downbeatLift, int ghostIndex)
        {
            int safeIndex = Mathf.Clamp(ghostIndex, 0, 2);
            return baseAngle * Mathf.Clamp01(downbeatLift) * Mathf.Clamp(0.030f - safeIndex * 0.006f, 0.012f, 0.030f);
        }

        private void UpdateTrapDangerVisuals(float channelX, float markerX, float y, float coreNear, float downbeatLift)
        {
            float safeDownbeatLift = Mathf.Clamp01(downbeatLift);
            float threatStrength = latestRunSnapshot.InfiniteMode
                ? Mathf.Clamp01((latestRunSnapshot.InfiniteThreatLevel - 1) / 4f)
                : 0f;
            float entryPulse = BuildTrapEntryPulse();
            float warningPulse = 0.5f + Mathf.Sin((beatPhase * 1.6f + coreNear) * Mathf.PI * 2f) * 0.5f;
            Color32 baseColor = BuildPrototypeTrapBaseColor(latestRunSnapshot.Pattern);
            Color32 accentColor = BuildPrototypeTrapAccentColor(latestRunSnapshot.Pattern);
            if (TryGetPatternVariationAccent(latestRunSnapshot.Pattern, out Color32 variationColor, out float variationStrength))
            {
                baseColor = Color32.Lerp(baseColor, variationColor, variationStrength * 0.72f);
                accentColor = Color32.Lerp(accentColor, variationColor, variationStrength * 0.54f);
            }

            float variationPressure = BuildTrapVariationPressure(latestRunSnapshot.Pattern);
            float visualPressure = Mathf.Clamp01(Mathf.Max(coreNear, threatStrength * 0.7f) + Mathf.Max(0f, variationPressure) * 0.42f);
            int dangerAlpha = Mathf.RoundToInt((Mathf.Lerp(28f, 116f, visualPressure) + entryPulse * 52f + variationPressure * 34f) * Mathf.Lerp(0.78f, 1.18f, warningPulse))
                + BuildTrapDangerBandDownbeatAlphaLift(safeDownbeatLift);
            int glowAlpha = Mathf.RoundToInt(Mathf.Lerp(35f, 154f, Mathf.Max(coreNear, entryPulse * 0.65f)) + threatStrength * 32f + variationPressure * 28f)
                + BuildTrapDangerGlowDownbeatAlphaLift(safeDownbeatLift);
            int strikeAlpha = Mathf.RoundToInt(Mathf.Lerp(70f, 240f, Mathf.Max(coreNear, entryPulse * 0.54f)) + variationPressure * 22f)
                + BuildTrapStrikeDownbeatAlphaLift(safeDownbeatLift);

            if (laneDangerBand != null)
            {
                Vector4 dangerBounds = BuildTrapDangerBandLayout(
                    latestRunSnapshot.Pattern,
                    channelX,
                    coreNear,
                    threatStrength,
                    variationPressure);
                RectTransform dangerRect = laneDangerBand.rectTransform;
                dangerRect.anchorMin = new Vector2(dangerBounds.x, dangerBounds.y);
                dangerRect.anchorMax = new Vector2(dangerBounds.z, dangerBounds.w);
                dangerRect.offsetMin = Vector2.zero;
                dangerRect.offsetMax = Vector2.zero;
                laneDangerBand.color = WithAlpha(baseColor, dangerAlpha);
            }

            if (trapCorridorShadow != null)
            {
                Vector4 shadowLayout = BuildTrapCorridorShadowLayout(
                    latestRunSnapshot.Pattern,
                    channelX,
                    markerX,
                    y,
                    coreNear);
                RectTransform shadowRect = trapCorridorShadow.rectTransform;
                shadowRect.anchorMin = new Vector2(shadowLayout.x, shadowLayout.y);
                shadowRect.anchorMax = shadowRect.anchorMin;
                shadowRect.anchoredPosition = Vector2.zero;
                shadowRect.sizeDelta = new Vector2(shadowLayout.z, shadowLayout.w);
                float shadowScale = BuildTrapCorridorShadowScale(safeDownbeatLift, coreNear);
                shadowRect.localScale = new Vector3(shadowScale, shadowScale, 1f);
                shadowRect.localEulerAngles = new Vector3(
                    0f,
                    0f,
                    BuildTrapCorridorShadowAngle(latestRunSnapshot.Pattern, coreNear, safeDownbeatLift));
                int shadowAlpha = BuildTrapCorridorShadowAlpha(
                    latestRunSnapshot.Pattern,
                    coreNear,
                    safeDownbeatLift,
                    latestRunSnapshot.InfiniteMode,
                    latestRunSnapshot.InfiniteThreatLevel,
                    variationPressure);
                Color32 shadowColor = Color32.Lerp(
                    baseColor,
                    accentColor,
                    BuildTrapCorridorShadowColorBlend(coreNear, safeDownbeatLift, variationPressure));
                trapCorridorShadow.color = WithAlpha(shadowColor, shadowAlpha);
            }

            if (trapGlow != null)
            {
                RectTransform glowRect = trapGlow.rectTransform;
                glowRect.anchorMin = new Vector2(markerX, y);
                glowRect.anchorMax = new Vector2(markerX, y);
                glowRect.anchoredPosition = Vector2.zero;
                glowRect.localScale = Vector3.one * (Mathf.Lerp(0.72f, 1.44f + threatStrength * 0.22f + Mathf.Max(0f, variationPressure) * 0.22f, Mathf.Max(coreNear, warningPulse * 0.42f)) + entryPulse * 0.24f + BuildTrapDangerGlowDownbeatScaleLift(safeDownbeatLift));
                Color32 glowColor = safeDownbeatLift > 0f
                    ? Color32.Lerp(baseColor, new Color32(255, 214, 105, 255), BuildTrapDangerGlowDownbeatColorBlend(safeDownbeatLift))
                    : baseColor;
                trapGlow.color = WithAlpha(glowColor, glowAlpha);
            }

            if (trapStrike != null)
            {
                RectTransform strikeRect = trapStrike.rectTransform;
                strikeRect.anchorMin = new Vector2(markerX, y);
                strikeRect.anchorMax = new Vector2(markerX, y);
                strikeRect.anchoredPosition = Vector2.zero;
                float strikePressure = Mathf.Clamp01(coreNear + threatStrength * 0.25f + Mathf.Max(0f, variationPressure) * 0.16f);
                switch (BuildRunnerResponseType(latestRunSnapshot.Pattern))
                {
                    case RunnerResponseType.Jump:
                        strikeRect.sizeDelta = new Vector2(
                            Mathf.Lerp(150f, 236f + Mathf.Max(0f, variationPressure) * 18f, strikePressure),
                            Mathf.Lerp(18f, 32f, coreNear));
                        break;
                    case RunnerResponseType.Slide:
                        strikeRect.sizeDelta = new Vector2(
                            Mathf.Lerp(28f, 48f + Mathf.Max(0f, variationPressure) * 10f, coreNear),
                            Mathf.Lerp(170f, 248f, strikePressure));
                        break;
                    default:
                        strikeRect.sizeDelta = new Vector2(
                            Mathf.Lerp(22f, 38f + Mathf.Max(0f, variationPressure) * 9f, coreNear),
                            Mathf.Lerp(150f, 220f, strikePressure));
                        break;
                }
                float strikeBaseScale = Mathf.Lerp(0.82f, 1.18f, warningPulse) + entryPulse * 0.16f;
                strikeRect.localScale = new Vector3(
                    strikeBaseScale * BuildTrapStrikeDownbeatScaleX(latestRunSnapshot.Pattern, safeDownbeatLift),
                    strikeBaseScale * BuildTrapStrikeDownbeatScaleY(latestRunSnapshot.Pattern, safeDownbeatLift),
                    1f);
                strikeRect.localEulerAngles = new Vector3(
                    0f,
                    0f,
                    BuildTrapStrikeAngle(latestRunSnapshot.Pattern) + BuildTrapStrikeDownbeatAngleLift(latestRunSnapshot.Pattern, safeDownbeatLift));
                Color32 strikeColor = safeDownbeatLift > 0f
                    ? Color32.Lerp(accentColor, new Color32(255, 214, 105, 255), BuildTrapStrikeDownbeatColorBlend(safeDownbeatLift))
                    : accentColor;
                trapStrike.color = WithAlpha(strikeColor, strikeAlpha);
            }

            if (trapContactCue != null)
            {
                Vector4 contactLayout = BuildTrapContactCueLayout(
                    latestRunSnapshot.Pattern,
                    channelX,
                    markerX,
                    coreNear);
                RectTransform contactRect = trapContactCue.rectTransform;
                contactRect.anchorMin = new Vector2(contactLayout.x, contactLayout.y);
                contactRect.anchorMax = contactRect.anchorMin;
                contactRect.anchoredPosition = Vector2.zero;
                contactRect.sizeDelta = new Vector2(contactLayout.z, contactLayout.w);
                float contactPulseScale = BuildTrapContactCueScale(safeDownbeatLift, coreNear);
                contactRect.localScale = new Vector3(contactPulseScale, contactPulseScale, 1f);
                contactRect.localEulerAngles = new Vector3(
                    0f,
                    0f,
                    BuildTrapContactCueAngle(latestRunSnapshot.Pattern, coreNear, safeDownbeatLift));
                int contactAlpha = BuildTrapContactCueAlpha(
                    latestRunSnapshot.Pattern,
                    coreNear,
                    safeDownbeatLift,
                    latestRunSnapshot.InfiniteMode,
                    latestRunSnapshot.InfiniteThreatLevel,
                    variationPressure);
                Color32 contactColor = Color32.Lerp(
                    accentColor,
                    new Color32(255, 214, 105, 255),
                    BuildTrapContactCueColorBlend(coreNear, safeDownbeatLift, variationPressure));
                trapContactCue.color = WithAlpha(contactColor, contactAlpha);
            }

            UpdateTrapWarningRails(
                channelX,
                markerX,
                y,
                coreNear,
                safeDownbeatLift,
                latestRunSnapshot.InfiniteMode,
                latestRunSnapshot.InfiniteThreatLevel,
                variationPressure,
                accentColor);
        }

        private void UpdateTrapWarningRails(
            float channelX,
            float markerX,
            float markerY,
            float coreNear,
            float downbeatLift,
            bool infiniteMode,
            int infiniteThreatLevel,
            float variationPressure,
            Color32 accentColor)
        {
            if (trapWarningRails == null)
            {
                return;
            }

            for (int i = 0; i < trapWarningRails.Length; i += 1)
            {
                Image rail = trapWarningRails[i];
                if (rail == null)
                {
                    continue;
                }

                Vector4 layout = BuildTrapWarningRailLayout(
                    latestRunSnapshot.Pattern,
                    channelX,
                    markerX,
                    markerY,
                    coreNear,
                    i);
                RectTransform rect = rail.rectTransform;
                rect.anchorMin = new Vector2(layout.x, layout.y);
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = Vector2.zero;
                rect.sizeDelta = new Vector2(layout.z, layout.w);
                float railScale = BuildTrapWarningRailScale(downbeatLift, coreNear, i);
                rect.localScale = new Vector3(railScale, railScale, 1f);
                rect.localEulerAngles = new Vector3(
                    0f,
                    0f,
                    BuildTrapWarningRailAngle(latestRunSnapshot.Pattern, coreNear, downbeatLift, i));
                Color32 railColor = Color32.Lerp(
                    accentColor,
                    new Color32(255, 214, 105, 255),
                    BuildTrapWarningRailColorBlend(coreNear, downbeatLift, variationPressure));
                rail.color = WithAlpha(
                    railColor,
                    BuildTrapWarningRailAlpha(
                        latestRunSnapshot.Pattern,
                        coreNear,
                        downbeatLift,
                        infiniteMode,
                        infiniteThreatLevel,
                        variationPressure));
            }
        }

        private static int BuildTrapDangerBandDownbeatAlphaLift(float downbeatLift)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(downbeatLift) * 16f);
        }

        private static int BuildTrapDangerGlowDownbeatAlphaLift(float downbeatLift)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(downbeatLift) * 36f);
        }

        private static float BuildTrapDangerGlowDownbeatScaleLift(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.16f;
        }

        private static float BuildTrapDangerGlowDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.16f;
        }

        private static int BuildTrapStrikeDownbeatAlphaLift(float downbeatLift)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(downbeatLift) * 32f);
        }

        private static float BuildTrapStrikeDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.22f;
        }

        private static float BuildTrapStrikeDownbeatScaleX(GreedLastPatternModel pattern, float downbeatLift)
        {
            float safeLift = Mathf.Clamp01(downbeatLift);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 1f + safeLift * 0.085f;
                case RunnerResponseType.Slide:
                    return 1f + safeLift * 0.018f;
                case RunnerResponseType.Twist:
                    return 1f - safeLift * 0.008f;
                default:
                    return 1f + safeLift * 0.022f;
            }
        }

        private static float BuildTrapStrikeDownbeatScaleY(GreedLastPatternModel pattern, float downbeatLift)
        {
            float safeLift = Mathf.Clamp01(downbeatLift);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 1f + safeLift * 0.020f;
                case RunnerResponseType.Slide:
                    return 1f + safeLift * 0.092f;
                case RunnerResponseType.Twist:
                    return 1f + safeLift * 0.076f;
                default:
                    return 1f + safeLift * 0.022f;
            }
        }

        private static float BuildTrapStrikeDownbeatAngleLift(GreedLastPatternModel pattern, float downbeatLift)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = pattern.Channel == GreedLastRunChannel.Left
                ? -1f
                : pattern.Channel == GreedLastRunChannel.Right ? 1f : 0.5f;
            return direction * Mathf.Clamp01(downbeatLift) * 2.2f;
        }

        private static Vector4 BuildTrapContactCueLayout(
            GreedLastPatternModel pattern,
            float channelX,
            float markerX,
            float coreNear)
        {
            float near = Mathf.Clamp01(coreNear);
            float safeChannelX = Mathf.Clamp01(channelX);
            float safeMarkerX = Mathf.Clamp01(markerX);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return new Vector4(
                        Mathf.Lerp(safeChannelX, safeMarkerX, 0.28f),
                        0.155f,
                        Mathf.Lerp(96f, 218f, near),
                        Mathf.Lerp(5f, 14f, near));
                case RunnerResponseType.Slide:
                    return new Vector4(
                        Mathf.Lerp(safeChannelX, safeMarkerX, 0.22f),
                        Mathf.Lerp(0.845f, 0.665f, near),
                        Mathf.Lerp(86f, 174f, near),
                        Mathf.Lerp(5f, 13f, near));
                case RunnerResponseType.Twist:
                    float direction = pattern.Channel == GreedLastRunChannel.Left
                        ? -1f
                        : pattern.Channel == GreedLastRunChannel.Right ? 1f : 1f;
                    return new Vector4(
                        Mathf.Clamp01(Mathf.Lerp(safeChannelX, safeMarkerX, 0.35f) + direction * Mathf.Lerp(0.045f, 0.090f, near)),
                        Mathf.Lerp(0.54f, 0.47f, near),
                        Mathf.Lerp(6f, 15f, near),
                        Mathf.Lerp(150f, 292f, near));
                default:
                    return new Vector4(safeMarkerX, 0.18f, 96f, 8f);
            }
        }

        private static float BuildTrapContactCueAngle(
            GreedLastPatternModel pattern,
            float coreNear,
            float downbeatLift)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = pattern.Channel == GreedLastRunChannel.Left
                ? -1f
                : pattern.Channel == GreedLastRunChannel.Right ? 1f : 1f;
            return direction * (Mathf.Lerp(3.5f, 9.5f, Mathf.Clamp01(coreNear)) + Mathf.Clamp01(downbeatLift) * 1.8f);
        }

        private static int BuildTrapContactCueAlpha(
            GreedLastPatternModel pattern,
            float coreNear,
            float downbeatLift,
            bool infiniteMode,
            int infiniteThreatLevel,
            float variationPressure)
        {
            if (!pattern.IsValid)
            {
                return 0;
            }

            float readiness = Mathf.Clamp01((Mathf.Clamp01(coreNear) - 0.10f) / 0.74f);
            float threat = infiniteMode ? Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) : 0f;
            float positiveVariation = Mathf.Max(0f, variationPressure);
            float alpha = Mathf.Lerp(0f, 104f, readiness);
            alpha += Mathf.Clamp01(downbeatLift) * Mathf.Lerp(10f, 34f, readiness);
            alpha += threat * Mathf.Lerp(6f, 24f, readiness);
            alpha += positiveVariation * Mathf.Lerp(5f, 24f, readiness);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 168f));
        }

        private static float BuildTrapContactCueScale(float downbeatLift, float coreNear)
        {
            return 1f + Mathf.Clamp01(downbeatLift) * Mathf.Lerp(0.04f, 0.13f, Mathf.Clamp01(coreNear));
        }

        private static float BuildTrapContactCueColorBlend(
            float coreNear,
            float downbeatLift,
            float variationPressure)
        {
            return Mathf.Clamp01(
                Mathf.Lerp(0.22f, 0.58f, Mathf.Clamp01(coreNear))
                    + Mathf.Clamp01(downbeatLift) * 0.20f
                    + Mathf.Max(0f, variationPressure) * 0.16f);
        }

        private static Vector4 BuildTrapWarningRailLayout(
            GreedLastPatternModel pattern,
            float channelX,
            float markerX,
            float markerY,
            float coreNear,
            int railIndex)
        {
            float near = Mathf.Clamp01(coreNear);
            float safeChannelX = Mathf.Clamp01(channelX);
            float safeMarkerX = Mathf.Clamp01(markerX);
            int safeIndex = Mathf.Clamp(railIndex, 0, TrapWarningRailCount - 1);
            float pairSign = safeIndex == 0 ? -1f : 1f;
            float x = Mathf.Lerp(safeChannelX, safeMarkerX, 0.46f);

            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return new Vector4(
                        x,
                        Mathf.Lerp(0.222f, 0.176f, near) + pairSign * Mathf.Lerp(0.022f, 0.030f, near),
                        Mathf.Lerp(116f, 256f, near) * (safeIndex == 0 ? 0.92f : 1f),
                        Mathf.Lerp(5f, 10f, near));
                case RunnerResponseType.Slide:
                    return new Vector4(
                        x,
                        Mathf.Lerp(Mathf.Clamp(markerY - 0.040f, 0.70f, 0.86f), 0.668f, near)
                            + pairSign * Mathf.Lerp(0.026f, 0.038f, near),
                        Mathf.Lerp(106f, 212f, near) * (safeIndex == 0 ? 0.88f : 1f),
                        Mathf.Lerp(5f, 10f, near));
                case RunnerResponseType.Twist:
                    float direction = BuildTrapCorridorShadowDirection(pattern);
                    return new Vector4(
                        Mathf.Clamp01(x + direction * Mathf.Lerp(0.060f, 0.116f, near) + pairSign * 0.016f),
                        Mathf.Lerp(0.586f, 0.468f, near) + pairSign * Mathf.Lerp(0.026f, 0.034f, near),
                        Mathf.Lerp(5f, 11f, near),
                        Mathf.Lerp(96f, 264f, near) * (safeIndex == 0 ? 0.84f : 1f));
                default:
                    return new Vector4(safeMarkerX, 0.22f, 96f, 8f);
            }
        }

        private static float BuildTrapWarningRailAngle(
            GreedLastPatternModel pattern,
            float coreNear,
            float downbeatLift,
            int railIndex)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            int safeIndex = Mathf.Clamp(railIndex, 0, TrapWarningRailCount - 1);
            float direction = BuildTrapCorridorShadowDirection(pattern);
            float pairSpread = safeIndex == 0 ? -1.8f : 1.8f;
            return direction * (Mathf.Lerp(16f, 31f, Mathf.Clamp01(coreNear)) + Mathf.Clamp01(downbeatLift) * 3.2f)
                + pairSpread;
        }

        private static int BuildTrapWarningRailAlpha(
            GreedLastPatternModel pattern,
            float coreNear,
            float downbeatLift,
            bool infiniteMode,
            int infiniteThreatLevel,
            float variationPressure)
        {
            if (!pattern.IsValid)
            {
                return 0;
            }

            float readiness = Mathf.Clamp01((Mathf.Clamp01(coreNear) - 0.06f) / 0.78f);
            float threat = infiniteMode ? Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) : 0f;
            float positiveVariation = Mathf.Max(0f, variationPressure);
            float alpha = Mathf.Lerp(0f, 88f, readiness);
            alpha += Mathf.Clamp01(downbeatLift) * Mathf.Lerp(8f, 30f, readiness);
            alpha += threat * Mathf.Lerp(5f, 22f, readiness);
            alpha += positiveVariation * Mathf.Lerp(4f, 18f, readiness);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 148f));
        }

        private static float BuildTrapWarningRailScale(float downbeatLift, float coreNear, int railIndex)
        {
            int safeIndex = Mathf.Clamp(railIndex, 0, TrapWarningRailCount - 1);
            float pairFalloff = safeIndex == 0 ? 0.92f : 1f;
            return 1f + Mathf.Clamp01(downbeatLift) * Mathf.Lerp(0.035f, 0.115f, Mathf.Clamp01(coreNear)) * pairFalloff;
        }

        private static float BuildTrapWarningRailColorBlend(
            float coreNear,
            float downbeatLift,
            float variationPressure)
        {
            return Mathf.Clamp01(
                Mathf.Lerp(0.18f, 0.52f, Mathf.Clamp01(coreNear))
                    + Mathf.Clamp01(downbeatLift) * 0.16f
                    + Mathf.Max(0f, variationPressure) * 0.12f);
        }

        private static Vector4 BuildTrapCorridorShadowLayout(
            GreedLastPatternModel pattern,
            float channelX,
            float markerX,
            float markerY,
            float coreNear)
        {
            float near = Mathf.Clamp01(coreNear);
            float safeChannelX = Mathf.Clamp01(channelX);
            float safeMarkerX = Mathf.Clamp01(markerX);
            float x = Mathf.Lerp(safeChannelX, safeMarkerX, 0.62f);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return new Vector4(
                        x,
                        Mathf.Lerp(0.300f, 0.225f, near),
                        Mathf.Lerp(118f, 244f, near),
                        Mathf.Lerp(26f, 56f, near));
                case RunnerResponseType.Slide:
                    return new Vector4(
                        x,
                        Mathf.Lerp(Mathf.Clamp(markerY - 0.10f, 0.48f, 0.78f), 0.490f, near),
                        Mathf.Lerp(76f, 138f, near),
                        Mathf.Lerp(154f, 264f, near));
                case RunnerResponseType.Twist:
                    float direction = BuildTrapCorridorShadowDirection(pattern);
                    return new Vector4(
                        Mathf.Clamp01(x + direction * Mathf.Lerp(0.018f, 0.060f, near)),
                        Mathf.Lerp(0.540f, 0.430f, near),
                        Mathf.Lerp(24f, 52f, near),
                        Mathf.Lerp(156f, 316f, near));
                default:
                    return new Vector4(x, 0.45f, 96f, 96f);
            }
        }

        private static float BuildTrapCorridorShadowAngle(
            GreedLastPatternModel pattern,
            float coreNear,
            float downbeatLift)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = BuildTrapCorridorShadowDirection(pattern);
            return direction * (Mathf.Lerp(14f, 28f, Mathf.Clamp01(coreNear)) + Mathf.Clamp01(downbeatLift) * 3f);
        }

        private static int BuildTrapCorridorShadowAlpha(
            GreedLastPatternModel pattern,
            float coreNear,
            float downbeatLift,
            bool infiniteMode,
            int infiniteThreatLevel,
            float variationPressure)
        {
            if (!pattern.IsValid)
            {
                return 0;
            }

            float near = Mathf.Clamp01(coreNear);
            float threat = infiniteMode ? Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) : 0f;
            float positiveVariation = Mathf.Max(0f, variationPressure);
            float alpha = Mathf.Lerp(18f, 96f, near);
            alpha += Mathf.Clamp01(downbeatLift) * Mathf.Lerp(8f, 24f, near);
            alpha += threat * Mathf.Lerp(8f, 22f, near);
            alpha += positiveVariation * Mathf.Lerp(6f, 24f, near);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 158f));
        }

        private static float BuildTrapCorridorShadowScale(float downbeatLift, float coreNear)
        {
            return 1f + Mathf.Clamp01(coreNear) * 0.05f + Mathf.Clamp01(downbeatLift) * 0.07f;
        }

        private static float BuildTrapCorridorShadowColorBlend(
            float coreNear,
            float downbeatLift,
            float variationPressure)
        {
            return Mathf.Clamp01(
                Mathf.Clamp01(coreNear) * 0.30f
                    + Mathf.Clamp01(downbeatLift) * 0.18f
                    + Mathf.Max(0f, variationPressure) * 0.16f);
        }

        private static float BuildTrapCorridorShadowDirection(GreedLastPatternModel pattern)
        {
            if (pattern.Channel == GreedLastRunChannel.Left)
            {
                return -1f;
            }

            if (pattern.Channel == GreedLastRunChannel.Right)
            {
                return 1f;
            }

            float rotationDirection = BuildRotationPatternDirection(pattern);
            return Mathf.Approximately(rotationDirection, 0f) ? 1f : Mathf.Sign(rotationDirection);
        }

        private static Vector4 BuildTrapDangerBandLayout(
            GreedLastPatternModel pattern,
            float channelX,
            float coreNear,
            float threatStrength,
            float variationPressure)
        {
            float positiveVariation = Mathf.Max(0f, variationPressure);
            float pressure = Mathf.Clamp01(coreNear + threatStrength * 0.24f + positiveVariation * 0.32f);
            float halfWidth = Mathf.Clamp(
                Mathf.Lerp(0.095f, 0.13f, threatStrength) + positiveVariation * 0.018f,
                0.08f,
                0.155f);
            float minY = 0.18f;
            float maxY = 0.88f;

            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    halfWidth = Mathf.Clamp(halfWidth * 1.38f, 0.12f, 0.19f);
                    minY = 0.145f;
                    maxY = Mathf.Lerp(0.255f, 0.365f, pressure);
                    break;
                case RunnerResponseType.Slide:
                    minY = Mathf.Lerp(0.50f, 0.305f, pressure);
                    maxY = 0.91f;
                    break;
                case RunnerResponseType.Twist:
                    halfWidth = Mathf.Clamp(halfWidth * 0.62f, 0.052f, 0.082f);
                    break;
            }

            return new Vector4(
                Mathf.Clamp01(channelX - halfWidth),
                Mathf.Clamp01(minY),
                Mathf.Clamp01(channelX + halfWidth),
                Mathf.Clamp01(maxY));
        }

        private static float BuildTrapApproachStartY(GreedLastPatternModel pattern)
        {
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 0.62f;
                case RunnerResponseType.Twist:
                    return 0.72f;
                default:
                    return 0.88f;
            }
        }

        private static float BuildTrapApproachSweepX(GreedLastPatternModel pattern, float visualProgress)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            float direction = pattern.Channel == GreedLastRunChannel.Left
                ? -1f
                : pattern.Channel == GreedLastRunChannel.Right
                    ? 1f
                    : 1f;
            return direction * (1f - Mathf.Clamp01(visualProgress)) * 0.12f;
        }

        private static float BuildTrapStrikeAngle(GreedLastPatternModel pattern)
        {
            float timingAccent = GetTrapStrikeAngle(pattern.TimingType);
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return 90f + timingAccent * 0.18f;
                case RunnerResponseType.Slide:
                    return timingAccent * 0.42f;
                case RunnerResponseType.Twist:
                    float direction = pattern.Channel == GreedLastRunChannel.Left ? -1f : 1f;
                    return direction * 38f + timingAccent * 0.22f;
                default:
                    return timingAccent;
            }
        }

        private static float BuildTrapVariationPressure(GreedLastPatternModel pattern)
        {
            string prompt = pattern.Prompt ?? string.Empty;
            if (prompt.Contains("[복구]", StringComparison.Ordinal))
            {
                return -0.10f;
            }

            if (prompt.Contains("[유예]", StringComparison.Ordinal))
            {
                return -0.08f;
            }

            if (prompt.Contains("[안정]", StringComparison.Ordinal))
            {
                return -0.06f;
            }

            if (prompt.Contains("[탈출]", StringComparison.Ordinal))
            {
                return 0.16f;
            }

            if (prompt.Contains("[위기]", StringComparison.Ordinal))
            {
                return 0.30f;
            }

            if (prompt.Contains("[압박]", StringComparison.Ordinal))
            {
                return 0.14f;
            }

            if (prompt.Contains("[급박]", StringComparison.Ordinal))
            {
                return 0.20f;
            }

            if (prompt.Contains("[정밀]", StringComparison.Ordinal)
                || prompt.Contains("[연쇄]", StringComparison.Ordinal))
            {
                return 0.12f;
            }

            if (prompt.Contains("[변주]", StringComparison.Ordinal))
            {
                return 0.08f;
            }

            if (prompt.Contains("[심층]", StringComparison.Ordinal))
            {
                return 0.10f;
            }

            return 0f;
        }

        private void HideTrapDangerVisuals()
        {
            HideRunEntryTrapReveal();

            if (trapMarker != null)
            {
                trapMarker.color = new Color32(207, 87, 65, 0);
            }

            if (trapIllustration != null)
            {
                trapIllustration.color = new Color32(255, 255, 255, 0);
            }

            HideTrapActionSymbol();

            if (laneDangerBand != null)
            {
                laneDangerBand.color = new Color32(207, 87, 65, 0);
            }

            if (trapGlow != null)
            {
                trapGlow.color = new Color32(207, 87, 65, 0);
            }

            if (trapCorridorShadow != null)
            {
                trapCorridorShadow.color = new Color32(207, 87, 65, 0);
                trapCorridorShadow.rectTransform.localScale = Vector3.one;
                trapCorridorShadow.rectTransform.localEulerAngles = Vector3.zero;
            }

            if (trapStrike != null)
            {
                trapStrike.color = new Color32(255, 238, 181, 0);
            }

            if (trapContactCue != null)
            {
                trapContactCue.color = new Color32(255, 214, 105, 0);
                trapContactCue.rectTransform.localScale = Vector3.one;
                trapContactCue.rectTransform.localEulerAngles = Vector3.zero;
            }

            if (trapWarningRails != null)
            {
                for (int i = 0; i < trapWarningRails.Length; i += 1)
                {
                    if (trapWarningRails[i] != null)
                    {
                        trapWarningRails[i].color = new Color32(255, 214, 105, 0);
                        trapWarningRails[i].rectTransform.localScale = Vector3.one;
                        trapWarningRails[i].rectTransform.localEulerAngles = Vector3.zero;
                    }
                }
            }

            if (trapApproachGhosts != null)
            {
                for (int i = 0; i < trapApproachGhosts.Length; i += 1)
                {
                    if (trapApproachGhosts[i] != null)
                    {
                        trapApproachGhosts[i].color = new Color32(207, 87, 65, 0);
                        trapApproachGhosts[i].rectTransform.localScale = Vector3.one;
                    }
                }
            }
        }

        private void UpdateFloorBeatTiles(
            bool visible,
            bool running,
            float motionStrength,
            float stageMotionScale,
            float motionSpeedBias,
            float stageDepthScale,
            float forwardPulse,
            float recoveryPressure,
            float downbeatPulse,
            bool focusActive,
            GreedLastRunSnapshot snapshot,
            Color32 atmosphereAccent)
        {
            if (runFloorBeatTiles == null)
            {
                return;
            }

            float activeBeatCueUrgency = visible ? BuildActiveBeatCueUrgency(snapshot) : 0f;
            for (int i = 0; i < runFloorBeatTiles.Length; i += 1)
            {
                Image tile = runFloorBeatTiles[i];
                if (tile == null)
                {
                    continue;
                }

                if (!visible)
                {
                    tile.color = new Color32(205, 166, 70, 0);
                    continue;
                }

                float phase = BuildFloorBeatTilePhase(
                    running,
                    beatPhase,
                    stageMotionScale,
                    motionSpeedBias,
                    forwardPulse,
                    i);
                float tilePulse = 0.5f + Mathf.Sin((beatPhase + phase * 0.55f) * Mathf.PI * 2f) * 0.5f;
                float compression = BuildFloorBeatTileJudgementCompression(snapshot, phase, forwardPulse, tilePulse);
                float downbeatLift = BuildFloorBeatTileDownbeatPulse(downbeatPulse, phase);
                float tileBeatCueUrgency = BuildFloorBeatTileBeatCueUrgency(activeBeatCueUrgency, phase, i);
                float y = Mathf.Lerp(0.78f, 0.13f, phase);
                float halfWidth = BuildFloorBeatTileHalfWidth(phase, stageDepthScale, forwardPulse)
                    * BuildFloorBeatTileCompressionWidthScale(compression)
                    * BuildFloorBeatTileDownbeatWidthScale(downbeatLift)
                    * BuildFloorBeatTileBeatCueUrgencyWidthScale(tileBeatCueUrgency);
                RectTransform rect = tile.rectTransform;
                rect.anchorMin = new Vector2(Mathf.Clamp01(0.5f - halfWidth), y);
                rect.anchorMax = new Vector2(Mathf.Clamp01(0.5f + halfWidth), y);
                rect.sizeDelta = new Vector2(
                    0f,
                    BuildFloorBeatTileHeight(phase, stageDepthScale, forwardPulse)
                        * BuildFloorBeatTileCompressionHeightScale(compression)
                        * BuildFloorBeatTileDownbeatHeightScale(downbeatLift)
                        * BuildFloorBeatTileBeatCueUrgencyHeightScale(tileBeatCueUrgency));
                rect.anchoredPosition = Vector2.zero;
                rect.localScale = new Vector3(
                    BuildFloorBeatTileBeatCueUrgencyScaleX(tileBeatCueUrgency),
                    BuildFloorBeatTileBeatCueUrgencyScaleY(tileBeatCueUrgency),
                    1f);

                float alpha = BuildFloorBeatTileAlpha(visible, running, motionStrength, phase, forwardPulse, focusActive, tilePulse);
                Color32 tileColor = Color32.Lerp(new Color32(67, 105, 103, 255), atmosphereAccent, 0.22f + phase * 0.36f);
                if (compression > 0f)
                {
                    alpha += BuildFloorBeatTileCompressionAlphaLift(compression);
                    tileColor = Color32.Lerp(tileColor, new Color32(255, 248, 210, 255), compression * 0.34f);
                }
                if (downbeatLift > 0f)
                {
                    alpha += BuildFloorBeatTileDownbeatAlphaLift(downbeatLift);
                    tileColor = Color32.Lerp(tileColor, new Color32(255, 214, 105, 255), BuildDownbeatColorBlend(downbeatLift, 0.22f));
                }
                if (tileBeatCueUrgency > 0f)
                {
                    alpha += BuildFloorBeatTileBeatCueUrgencyAlphaLift(tileBeatCueUrgency);
                    tileColor = Color32.Lerp(
                        tileColor,
                        new Color32(255, 238, 181, 255),
                        BuildFloorBeatTileBeatCueUrgencyColorBlend(tileBeatCueUrgency));
                }
                if (focusActive)
                {
                    tileColor = Color32.Lerp(tileColor, new Color32(255, 214, 105, 255), 0.24f);
                }
                if (forwardPulse > 0f)
                {
                    tileColor = Color32.Lerp(tileColor, new Color32(255, 238, 181, 255), forwardPulse * 0.30f);
                }
                if (recoveryPressure > 0f)
                {
                    tileColor = BuildMissRecoveryMotionTint(tileColor, recoveryPressure, 0.38f);
                    alpha = BuildMissRecoveryMotionAlpha(Mathf.RoundToInt(alpha), recoveryPressure, 0.18f);
                }

                tile.color = WithAlpha(tileColor, Mathf.RoundToInt(alpha));
            }
        }

        private static float BuildFloorBeatTileJudgementCompression(
            GreedLastRunSnapshot snapshot,
            float tilePhase,
            float forwardPulse,
            float tilePulse)
        {
            return BuildFloorBeatTileJudgementCompressionForValues(
                snapshot.ActivePattern,
                snapshot.Paused,
                snapshot.Stopped,
                snapshot.ChoiceActive,
                snapshot.CountdownActive,
                snapshot.CoreDeltaSeconds,
                snapshot.Pattern.IsValid ? snapshot.Pattern.GoodWindowSeconds : 0f,
                snapshot.Pattern.IsValid ? snapshot.Pattern.TimingType : GreedLastTimingType.Perfect,
                snapshot.InfiniteMode,
                snapshot.InfiniteThreatLevel,
                tilePhase,
                forwardPulse,
                tilePulse);
        }

        private static float BuildFloorBeatTileJudgementCompressionForValues(
            bool activePattern,
            bool paused,
            bool stopped,
            bool choiceActive,
            bool countdownActive,
            float coreDeltaSeconds,
            float goodWindowSeconds,
            GreedLastTimingType timingType,
            bool infiniteMode,
            int infiniteThreatLevel,
            float tilePhase,
            float forwardPulse,
            float tilePulse)
        {
            if (!activePattern || paused || stopped || choiceActive || countdownActive)
            {
                return 0f;
            }

            float coreWindow = Mathf.Max(0.01f, Mathf.Max(0.01f, goodWindowSeconds) * 1.65f);
            float coreProximity = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / coreWindow);
            float tileProximity = Mathf.Clamp01(1f - Mathf.Abs(Mathf.Clamp01(tilePhase) - 0.925f) / 0.22f);
            float timingLift;
            switch (timingType)
            {
                case GreedLastTimingType.Clutch:
                    timingLift = 1.12f;
                    break;
                case GreedLastTimingType.Offbeat:
                    timingLift = 1.06f;
                    break;
                default:
                    timingLift = 1f;
                    break;
            }

            float pressureLift = infiniteMode
                ? Mathf.Lerp(1f, 1.18f, Mathf.Clamp01((infiniteThreatLevel - 1) / 4f))
                : 1f;
            float pulseLift = 0.72f + Mathf.Clamp01(tilePulse) * 0.22f + Mathf.Clamp01(forwardPulse) * 0.18f;
            return Mathf.Clamp01(coreProximity * tileProximity * timingLift * pressureLift * pulseLift);
        }

        private static float BuildFloorBeatTileCompressionWidthScale(float compression)
        {
            return 1f + Mathf.Clamp01(compression) * 0.085f;
        }

        private static float BuildFloorBeatTileCompressionHeightScale(float compression)
        {
            return 1f - Mathf.Clamp01(compression) * 0.30f;
        }

        private static float BuildFloorBeatTileCompressionAlphaLift(float compression)
        {
            return Mathf.Clamp01(compression) * 34f;
        }

        private static float BuildFloorBeatTileDownbeatPulse(float downbeatPulse, float tilePhase)
        {
            return Mathf.Clamp01(downbeatPulse) * Mathf.Lerp(0.42f, 1f, Mathf.Clamp01(tilePhase));
        }

        private static float BuildFloorBeatTileDownbeatWidthScale(float downbeatPulse)
        {
            return 1f + Mathf.Clamp01(downbeatPulse) * 0.040f;
        }

        private static float BuildFloorBeatTileDownbeatHeightScale(float downbeatPulse)
        {
            return 1f + Mathf.Clamp01(downbeatPulse) * 0.075f;
        }

        private static float BuildFloorBeatTileDownbeatAlphaLift(float downbeatPulse)
        {
            return Mathf.Clamp01(downbeatPulse) * 18f;
        }

        private static float BuildFloorBeatTileBeatCueUrgency(float beatCueUrgency, float tilePhase, int tileIndex)
        {
            int safeIndex = Mathf.Clamp(tileIndex, 0, FloorBeatTileCount - 1);
            float indexFalloff = Mathf.Lerp(1f, 0.62f, Mathf.Clamp01(safeIndex / (float)Mathf.Max(1, FloorBeatTileCount - 1)));
            float lineProximity = Mathf.Clamp01(1f - Mathf.Abs(Mathf.Clamp01(tilePhase) - 0.925f) / 0.28f);
            float depthWeight = Mathf.Lerp(0.42f, 1f, Mathf.Clamp01(tilePhase));
            return Mathf.Clamp01(beatCueUrgency) * lineProximity * depthWeight * indexFalloff;
        }

        private static float BuildFloorBeatTileBeatCueUrgencyWidthScale(float tileBeatCueUrgency)
        {
            return 1f + Mathf.Clamp01(tileBeatCueUrgency) * 0.035f;
        }

        private static float BuildFloorBeatTileBeatCueUrgencyHeightScale(float tileBeatCueUrgency)
        {
            return 1f + Mathf.Clamp01(tileBeatCueUrgency) * 0.055f;
        }

        private static float BuildFloorBeatTileBeatCueUrgencyScaleX(float tileBeatCueUrgency)
        {
            return 1f + Mathf.Clamp01(tileBeatCueUrgency) * 0.006f;
        }

        private static float BuildFloorBeatTileBeatCueUrgencyScaleY(float tileBeatCueUrgency)
        {
            return 1f + Mathf.Clamp01(tileBeatCueUrgency) * 0.018f;
        }

        private static float BuildFloorBeatTileBeatCueUrgencyAlphaLift(float tileBeatCueUrgency)
        {
            return Mathf.Clamp01(tileBeatCueUrgency) * 12f;
        }

        private static float BuildFloorBeatTileBeatCueUrgencyColorBlend(float tileBeatCueUrgency)
        {
            return Mathf.Clamp01(tileBeatCueUrgency) * 0.14f;
        }

        private static float BuildRotationPatternDirection(GreedLastPatternModel pattern)
        {
            if (!GreedLastRunCore.IsRotationPattern(pattern))
            {
                return 0f;
            }

            switch (pattern.Channel)
            {
                case GreedLastRunChannel.Left:
                    return -1f;
                case GreedLastRunChannel.Right:
                    return 1f;
                default:
                    return 0f;
            }
        }

        private static float BuildStraightRunRotationReadiness(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ActivePattern
                || !snapshot.Pattern.IsValid
                || !GreedLastRunCore.IsRotationPattern(snapshot.Pattern)
                || snapshot.Paused
                || snapshot.Stopped
                || snapshot.ChoiceActive
                || snapshot.CountdownActive)
            {
                return 0f;
            }

            float readableWindow = Mathf.Max(0.35f, snapshot.Pattern.GoodWindowSeconds * 2.25f);
            return Mathf.Clamp01(1f - Mathf.Abs(snapshot.CoreDeltaSeconds) / readableWindow);
        }

        private static float BuildStraightRunTrapPressureForValues(
            bool activePattern,
            bool paused,
            bool stopped,
            bool choiceActive,
            bool countdownActive,
            float coreDeltaSeconds,
            float goodWindowSeconds,
            GreedLastTimingType timingType,
            bool infiniteMode,
            int infiniteThreatLevel,
            float beatCueUrgency,
            float variationPressure)
        {
            if (!activePattern || paused || stopped || choiceActive || countdownActive)
            {
                return 0f;
            }

            float goodWindow = Mathf.Max(0.01f, goodWindowSeconds);
            float readableWindow = Mathf.Max(0.24f, goodWindow * 2.75f);
            float nearBeat = Mathf.Clamp01(1f - Mathf.Abs(coreDeltaSeconds) / readableWindow);
            float threat = infiniteMode ? Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) : 0f;
            float timingWeight = BuildStraightRunTrapPressureTimingWeight(timingType);
            float pressure = nearBeat * timingWeight;
            pressure += nearBeat * Mathf.Clamp01(beatCueUrgency) * 0.13f;
            pressure += nearBeat * threat * 0.18f;
            pressure += nearBeat * Mathf.Max(0f, variationPressure) * 0.16f;
            return Mathf.Clamp01(pressure);
        }

        private static float BuildStraightRunTrapPressureTimingWeight(GreedLastTimingType timingType)
        {
            switch (timingType)
            {
                case GreedLastTimingType.Clutch:
                    return 1.14f;
                case GreedLastTimingType.Offbeat:
                    return 1.07f;
                default:
                    return 1f;
            }
        }

        private static float BuildStraightRunTrapPressureWidthScale(float trapPressure, float phase)
        {
            return 1f + Mathf.Clamp01(trapPressure) * Mathf.Lerp(0.012f, 0.070f, Mathf.Clamp01(phase));
        }

        private static float BuildStraightRunTrapPressureHeightScale(float trapPressure, float phase)
        {
            return 1f + Mathf.Clamp01(trapPressure) * Mathf.Lerp(0.040f, 0.145f, Mathf.Clamp01(phase));
        }

        private static int BuildStraightRunTrapPressureAlphaLift(float trapPressure, float phase, int maxLift)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(trapPressure) * Mathf.Lerp(maxLift * 0.32f, maxLift, Mathf.Clamp01(phase)));
        }

        private static float BuildStraightRunTrapPressureColorBlend(float trapPressure, float phase)
        {
            return Mathf.Clamp01(Mathf.Clamp01(trapPressure) * Mathf.Lerp(0.08f, 0.24f, Mathf.Clamp01(phase)));
        }

        private static float BuildStraightRunPathRollAngle(
            float rotationDirection,
            float rotationReadiness,
            float downbeatPulse,
            float beatCueUrgency)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            float pulseLift = Mathf.Clamp01(downbeatPulse) * 1.7f + Mathf.Clamp01(beatCueUrgency) * 1.15f;
            float angle = Mathf.Clamp01(rotationReadiness) * (8.2f + pulseLift);
            return Mathf.Clamp(Mathf.Sign(rotationDirection) * angle, -12f, 12f);
        }

        private static float BuildStraightRunRotationInputAlignment(
            float rotationDirection,
            float rotationReadiness,
            float normalizedInputAxis)
        {
            if (Mathf.Approximately(rotationDirection, 0f) || rotationReadiness <= 0f)
            {
                return 0f;
            }

            return Mathf.Clamp(
                Mathf.Sign(rotationDirection)
                    * Mathf.Clamp(normalizedInputAxis, -1f, 1f)
                    * Mathf.Clamp01(rotationReadiness),
                -1f,
                1f);
        }

        private static float BuildStraightRunRotationInputResponsivePathRoll(
            float basePathRoll,
            float inputAlignment)
        {
            float correctAlignment = Mathf.Clamp01(inputAlignment);
            float wrongAlignment = Mathf.Clamp01(-inputAlignment);
            float responseScale = 1f - correctAlignment * 0.18f + wrongAlignment * 0.10f;
            return Mathf.Clamp(basePathRoll * responseScale, -12f, 12f);
        }

        private static float BuildTunnelHorizonInputResponsiveTiltAngle(
            float baseTiltAngle,
            float inputAlignment)
        {
            float correctAlignment = Mathf.Clamp01(inputAlignment);
            float wrongAlignment = Mathf.Clamp01(-inputAlignment);
            float responseScale = 1f - correctAlignment * 0.22f + wrongAlignment * 0.12f;
            return Mathf.Clamp(baseTiltAngle * responseScale, -3f, 3f);
        }

        private static Color32 BuildStraightRunRotationInputResponsiveColor(
            Color32 baseColor,
            float inputAlignment)
        {
            float correctAlignment = Mathf.Clamp01(inputAlignment);
            float wrongAlignment = Mathf.Clamp01(-inputAlignment);
            Color32 alignedColor = Color32.Lerp(baseColor, PrototypeGoldColor, correctAlignment * 0.14f);
            return Color32.Lerp(alignedColor, PrototypeVermilionColor, wrongAlignment * 0.20f);
        }

        private static float BuildStraightRunPathRailAnchorX(int railIndex, float rotationDirection, float rotationReadiness)
        {
            float baseAnchor;
            switch (Mathf.Clamp(railIndex, 0, StraightRunPathRailCount - 1))
            {
                case 0:
                    baseAnchor = 0.30f;
                    break;
                case 1:
                    baseAnchor = 0.43f;
                    break;
                case 2:
                    baseAnchor = 0.57f;
                    break;
                default:
                    baseAnchor = 0.70f;
                    break;
            }

            float direction = Mathf.Approximately(rotationDirection, 0f) ? 0f : Mathf.Sign(rotationDirection);
            return baseAnchor + direction * Mathf.Clamp01(rotationReadiness) * 0.024f;
        }

        private static float BuildStraightRunPathRailAngle(int railIndex, float pathRoll)
        {
            switch (Mathf.Clamp(railIndex, 0, StraightRunPathRailCount - 1))
            {
                case 0:
                    return 54f + pathRoll;
                case 1:
                    return 70f + pathRoll * 0.85f;
                case 2:
                    return -70f + pathRoll * 0.85f;
                default:
                    return -54f + pathRoll;
            }
        }

        private static float BuildStraightRunPathRailWidth(int railIndex, float stageDepthScale, float rotationReadiness)
        {
            bool innerRail = railIndex == 1 || railIndex == 2;
            float baseWidth = innerRail ? 490f : 650f;
            return baseWidth * Mathf.Lerp(0.96f, 1.04f, Mathf.Clamp01(rotationReadiness)) * Mathf.Max(0.82f, stageDepthScale);
        }

        private static int BuildStraightRunPathRailAlpha(
            bool visible,
            float motionStrength,
            float rotationReadiness,
            bool innerRail)
        {
            if (!visible)
            {
                return 0;
            }

            float baseAlpha = innerRail ? 22f : 28f;
            float motionAlpha = Mathf.Clamp01(motionStrength) * (innerRail ? 44f : 34f);
            float rotationAlpha = Mathf.Clamp01(rotationReadiness) * (innerRail ? 42f : 34f);
            return Mathf.RoundToInt(baseAlpha + motionAlpha + rotationAlpha);
        }

        private static float BuildStraightRunCorridorGatePhase(
            bool running,
            float beatProgress,
            float stageMotionScale,
            float motionSpeedBias,
            float forwardPulse,
            int gateIndex)
        {
            float indexOffset = Mathf.Clamp(gateIndex, 0, StraightRunCorridorGateCount - 1) / (float)StraightRunCorridorGateCount;
            if (!running)
            {
                return indexOffset;
            }

            float speed = (0.30f + Mathf.Clamp01(forwardPulse) * 0.12f)
                * Mathf.Max(0.1f, stageMotionScale)
                * Mathf.Max(0.1f, motionSpeedBias);
            return Mathf.Repeat(Mathf.Clamp01(beatProgress) * speed + indexOffset, 1f);
        }

        private static float BuildStraightRunCorridorGateAnchorY(float phase)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(0.80f, 0.24f, Mathf.Pow(depth, 1.55f));
        }

        private static float BuildStraightRunCorridorGateWidth(
            float phase,
            float stageDepthScale,
            float rotationReadiness)
        {
            float depth = Mathf.Clamp01(phase);
            float baseWidth = Mathf.Lerp(170f, 820f, depth * depth);
            return baseWidth
                * Mathf.Max(0.84f, stageDepthScale)
                * Mathf.Lerp(1f, 1.07f, Mathf.Clamp01(rotationReadiness));
        }

        private static float BuildStraightRunCorridorGateHeight(
            float phase,
            float gatePulse,
            float rotationReadiness)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(3f, 12f, depth)
                + Mathf.Clamp01(gatePulse) * Mathf.Lerp(1.2f, 3.8f, depth)
                + Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.6f, 2.4f, depth);
        }

        private static float BuildStraightRunCorridorGateOffsetX(
            float rotationDirection,
            float rotationReadiness,
            float phase)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.006f, 0.052f, Mathf.Clamp01(phase));
        }

        private static float BuildStraightRunCorridorGateAngle(
            float rotationDirection,
            float rotationReadiness,
            float phase)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            float depth = Mathf.Clamp01(phase);
            return Mathf.Clamp(Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(2f, 10.5f, depth), -10.5f, 10.5f);
        }

        private static float BuildStraightRunCorridorGatePulse(float phase, float downbeatPulse)
        {
            return Mathf.Clamp01(downbeatPulse) * Mathf.Lerp(0.36f, 1f, Mathf.Clamp01(phase));
        }

        private static int BuildStraightRunCorridorGateAlpha(
            bool visible,
            float motionStrength,
            float phase,
            float forwardPulse,
            float gatePulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            if (!visible)
            {
                return 0;
            }

            float depth = Mathf.Clamp01(phase);
            float alpha = Mathf.Lerp(8f, 54f, depth) * Mathf.Lerp(0.48f, 1f, Mathf.Clamp01(motionStrength));
            alpha += Mathf.Clamp01(forwardPulse) * Mathf.Lerp(4f, 16f, depth);
            alpha += Mathf.Clamp01(gatePulse) * Mathf.Lerp(5f, 18f, depth);
            alpha += Mathf.Clamp01(tunnelBeatCueUrgency) * Mathf.Lerp(4f, 12f, depth);
            alpha += Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(4f, 16f, depth);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 105f));
        }

        private static float BuildStraightRunCorridorGateColorBlend(
            float phase,
            float gatePulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            return Mathf.Clamp01(
                Mathf.Lerp(0.12f, 0.38f, Mathf.Clamp01(phase))
                    + Mathf.Clamp01(gatePulse) * 0.20f
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * 0.12f
                    + Mathf.Clamp01(rotationReadiness) * 0.22f);
        }

        private static float BuildStraightRunSideWallStripePhase(
            bool running,
            float beatProgress,
            float stageMotionScale,
            float motionSpeedBias,
            float forwardPulse,
            int depthIndex)
        {
            float indexOffset = Mathf.Clamp(depthIndex, 0, StraightRunSideWallStripeCount - 1) / (float)StraightRunSideWallStripeCount;
            if (!running)
            {
                return indexOffset;
            }

            float speed = (0.38f + Mathf.Clamp01(forwardPulse) * 0.14f)
                * Mathf.Max(0.1f, stageMotionScale)
                * Mathf.Max(0.1f, motionSpeedBias);
            return Mathf.Repeat(Mathf.Clamp01(beatProgress) * speed + indexOffset, 1f);
        }

        private static float BuildStraightRunSideWallStripeAnchorX(
            float sideDirection,
            float phase,
            float rotationDirection,
            float rotationReadiness)
        {
            float side = Mathf.Approximately(sideDirection, 0f) ? 1f : Mathf.Sign(sideDirection);
            float depth = Mathf.Clamp01(phase);
            float wallSpread = Mathf.Lerp(0.205f, 0.482f, Mathf.Pow(depth, 0.86f));
            float rotationDrift = Mathf.Approximately(rotationDirection, 0f)
                ? 0f
                : Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.004f, 0.032f, depth);
            return Mathf.Clamp01(0.5f + side * wallSpread + rotationDrift);
        }

        private static float BuildStraightRunSideWallStripeAnchorY(float phase)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(0.765f, 0.205f, Mathf.Pow(depth, 1.24f));
        }

        private static float BuildStraightRunSideWallStripeWidth(
            float phase,
            float forwardPulse,
            float rotationReadiness)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(34f, 132f, depth)
                * (1f + Mathf.Clamp01(forwardPulse) * Mathf.Lerp(0.03f, 0.11f, depth))
                * (1f + Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.02f, 0.08f, depth));
        }

        private static float BuildStraightRunSideWallStripeHeight(
            float phase,
            float stripePulse,
            float rotationReadiness)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(4f, 10f, depth)
                + Mathf.Clamp01(stripePulse) * Mathf.Lerp(0.8f, 2.7f, depth)
                + Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.4f, 1.8f, depth);
        }

        private static float BuildStraightRunSideWallStripeAngle(
            float sideDirection,
            float rotationDirection,
            float rotationReadiness,
            float phase)
        {
            float side = Mathf.Approximately(sideDirection, 0f) ? 1f : Mathf.Sign(sideDirection);
            float depth = Mathf.Clamp01(phase);
            float baseAngle = -side * Mathf.Lerp(22f, 48f, depth);
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return baseAngle;
            }

            float rotationLean = Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(1.2f, 6.2f, depth);
            return Mathf.Clamp(baseAngle + rotationLean, -55f, 55f);
        }

        private static float BuildStraightRunSideWallStripePulse(float phase, float downbeatPulse)
        {
            return Mathf.Clamp01(downbeatPulse) * Mathf.Lerp(0.30f, 1f, Mathf.Clamp01(phase));
        }

        private static int BuildStraightRunSideWallStripeAlpha(
            bool visible,
            float motionStrength,
            float phase,
            float forwardPulse,
            float stripePulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            if (!visible)
            {
                return 0;
            }

            float depth = Mathf.Clamp01(phase);
            float alpha = Mathf.Lerp(7f, 50f, depth) * Mathf.Lerp(0.46f, 1f, Mathf.Clamp01(motionStrength));
            alpha += Mathf.Clamp01(forwardPulse) * Mathf.Lerp(3f, 14f, depth);
            alpha += Mathf.Clamp01(stripePulse) * Mathf.Lerp(4f, 16f, depth);
            alpha += Mathf.Clamp01(tunnelBeatCueUrgency) * Mathf.Lerp(3f, 11f, depth);
            alpha += Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(3f, 13f, depth);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 94f));
        }

        private static float BuildStraightRunSideWallStripeAtmosphereBlend(
            float phase,
            float stripePulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            return Mathf.Clamp01(
                Mathf.Lerp(0.26f, 0.58f, Mathf.Clamp01(phase))
                    + Mathf.Clamp01(stripePulse) * 0.14f
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * 0.10f
                    + Mathf.Clamp01(rotationReadiness) * 0.12f);
        }

        private static float BuildStraightRunSpeedStreakPhase(
            bool running,
            float beatProgress,
            float stageMotionScale,
            float motionSpeedBias,
            float forwardPulse,
            int streakIndex)
        {
            float indexOffset = Mathf.Clamp(streakIndex, 0, StraightRunSpeedStreakPairCount - 1) / (float)StraightRunSpeedStreakPairCount;
            if (!running)
            {
                return indexOffset;
            }

            float speed = (0.58f + Mathf.Clamp01(forwardPulse) * 0.22f)
                * Mathf.Max(0.1f, stageMotionScale)
                * Mathf.Max(0.1f, motionSpeedBias);
            return Mathf.Repeat(Mathf.Clamp01(beatProgress) * speed + indexOffset, 1f);
        }

        private static float BuildStraightRunSpeedStreakAnchorX(
            float sideDirection,
            float phase,
            float rotationDirection,
            float rotationReadiness)
        {
            float side = Mathf.Approximately(sideDirection, 0f) ? 1f : Mathf.Sign(sideDirection);
            float depth = Mathf.Clamp01(phase);
            float x = 0.5f + side * Mathf.Lerp(0.145f, 0.385f, Mathf.Pow(depth, 0.82f));
            if (!Mathf.Approximately(rotationDirection, 0f))
            {
                x += Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.006f, 0.032f, depth);
            }

            return Mathf.Clamp01(x);
        }

        private static float BuildStraightRunSpeedStreakAnchorY(float phase)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(0.755f, 0.285f, Mathf.Pow(depth, 1.10f));
        }

        private static float BuildStraightRunSpeedStreakWidth(
            float phase,
            float forwardPulse,
            float streakPulse,
            float rotationReadiness)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(28f, 164f, depth)
                + Mathf.Clamp01(forwardPulse) * Mathf.Lerp(4f, 26f, depth)
                + Mathf.Clamp01(streakPulse) * Mathf.Lerp(3f, 22f, depth)
                + Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(1f, 12f, depth);
        }

        private static float BuildStraightRunSpeedStreakHeight(float phase, float streakPulse)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(2f, 6f, depth) + Mathf.Clamp01(streakPulse) * Mathf.Lerp(0.6f, 2.4f, depth);
        }

        private static float BuildStraightRunSpeedStreakAngle(
            float sideDirection,
            float rotationDirection,
            float rotationReadiness,
            float phase)
        {
            float side = Mathf.Approximately(sideDirection, 0f) ? 1f : Mathf.Sign(sideDirection);
            float depth = Mathf.Clamp01(phase);
            float baseAngle = -side * Mathf.Lerp(11f, 26f, depth);
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return baseAngle;
            }

            float rotationLean = Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.9f, 5.0f, depth);
            return Mathf.Clamp(baseAngle + rotationLean, -32f, 32f);
        }

        private static float BuildStraightRunSpeedStreakPulse(float phase, float downbeatPulse, float tunnelBeatCueUrgency)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Clamp01(
                Mathf.Clamp01(downbeatPulse) * Mathf.Lerp(0.20f, 0.92f, depth)
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * Mathf.Lerp(0.10f, 0.28f, depth));
        }

        private static int BuildStraightRunSpeedStreakAlpha(
            bool visible,
            float motionStrength,
            float phase,
            float forwardPulse,
            float streakPulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            if (!visible)
            {
                return 0;
            }

            float depth = Mathf.Clamp01(phase);
            float alpha = Mathf.Lerp(5f, 44f, depth) * Mathf.Lerp(0.38f, 1f, Mathf.Clamp01(motionStrength));
            alpha += Mathf.Clamp01(forwardPulse) * Mathf.Lerp(4f, 18f, depth);
            alpha += Mathf.Clamp01(streakPulse) * Mathf.Lerp(4f, 18f, depth);
            alpha += Mathf.Clamp01(tunnelBeatCueUrgency) * Mathf.Lerp(2f, 10f, depth);
            alpha += Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(1f, 8f, depth);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 82f));
        }

        private static float BuildStraightRunSpeedStreakColorBlend(
            float phase,
            float streakPulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            return Mathf.Clamp01(
                Mathf.Lerp(0.20f, 0.52f, Mathf.Clamp01(phase))
                    + Mathf.Clamp01(streakPulse) * 0.16f
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * 0.10f
                    + Mathf.Clamp01(rotationReadiness) * 0.08f);
        }

        private static float BuildStraightRunCenterSeamDashPhase(
            bool running,
            float beatProgress,
            float stageMotionScale,
            float motionSpeedBias,
            float forwardPulse,
            int dashIndex)
        {
            float indexOffset = Mathf.Clamp(dashIndex, 0, StraightRunCenterSeamDashCount - 1) / (float)StraightRunCenterSeamDashCount;
            if (!running)
            {
                return indexOffset;
            }

            float speed = (0.42f + Mathf.Clamp01(forwardPulse) * 0.15f)
                * Mathf.Max(0.1f, stageMotionScale)
                * Mathf.Max(0.1f, motionSpeedBias);
            return Mathf.Repeat(Mathf.Clamp01(beatProgress) * speed + indexOffset, 1f);
        }

        private static float BuildStraightRunCenterSeamDashAnchorY(float phase)
        {
            float depth = Mathf.Clamp01(phase);
