                + Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.5f, 2.2f, depth);
        }

        private static float BuildStraightRunCenterSeamDashHeight(
            float phase,
            float forwardPulse,
            float dashPulse)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(12f, 42f, depth)
                * (1f + Mathf.Clamp01(forwardPulse) * Mathf.Lerp(0.02f, 0.12f, depth))
                + Mathf.Clamp01(dashPulse) * Mathf.Lerp(1f, 5f, depth);
        }

        private static float BuildStraightRunCenterSeamDashAngle(
            float rotationDirection,
            float rotationReadiness,
