        }

        private static float BuildStraightRunCenterSeamDashPulse(float phase, float downbeatPulse)
        {
            return Mathf.Clamp01(downbeatPulse) * Mathf.Lerp(0.34f, 1f, Mathf.Clamp01(phase));
        }

        private static int BuildStraightRunCenterSeamDashAlpha(
