            alpha += Mathf.Clamp01(forwardPulse) * Mathf.Lerp(3f, 13f, depth);
            alpha += Mathf.Clamp01(dashPulse) * Mathf.Lerp(4f, 15f, depth);
            alpha += Mathf.Clamp01(tunnelBeatCueUrgency) * Mathf.Lerp(2f, 9f, depth);
            alpha += Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(2f, 8f, depth);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 88f));
