            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.004f, 0.030f, Mathf.Clamp01(phase));
        }

        private static float BuildStraightRunForwardPaceMarkerWidth(
            float phase,
            float forwardPulse,
            float markerPulse,
            float rotationReadiness)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(34f, 132f, depth)
                + Mathf.Clamp01(forwardPulse) * Mathf.Lerp(3f, 18f, depth)
                + Mathf.Clamp01(markerPulse) * Mathf.Lerp(2f, 16f, depth)
                + Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(1f, 8f, depth);
        }

        private static float BuildStraightRunForwardPaceMarkerHeight(float phase, float markerPulse)
        {
            float depth = Mathf.Clamp01(phase);
            return Mathf.Lerp(3f, 8f, depth) + Mathf.Clamp01(markerPulse) * Mathf.Lerp(1f, 4f, depth);
        }

        private static float BuildStraightRunForwardPaceMarkerAngle(
            float rotationDirection,
            float rotationReadiness,
            float phase)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.8f, 4.2f, Mathf.Clamp01(phase));
        }

        private static float BuildStraightRunForwardPaceMarkerPulse(
            float phase,
            float downbeatPulse,
            float tunnelBeatCueUrgency)
        {
            float depth = Mathf.Clamp01(phase);
            float nearBeat = Mathf.Lerp(0.22f, 1f, depth);
            return Mathf.Clamp01(
                Mathf.Clamp01(downbeatPulse) * nearBeat
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * Mathf.Lerp(0.05f, 0.24f, depth));
        }

        private static int BuildStraightRunForwardPaceMarkerAlpha(
            bool visible,
            float motionStrength,
            float phase,
            float forwardPulse,
            float markerPulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            if (!visible)
            {
                return 0;
            }

            float depth = Mathf.Clamp01(phase);
            float alpha = Mathf.Lerp(6f, 38f, depth) * Mathf.Lerp(0.36f, 1f, Mathf.Clamp01(motionStrength));
            alpha += Mathf.Clamp01(forwardPulse) * Mathf.Lerp(2f, 11f, depth);
            alpha += Mathf.Clamp01(markerPulse) * Mathf.Lerp(3f, 14f, depth);
            alpha += Mathf.Clamp01(tunnelBeatCueUrgency) * Mathf.Lerp(1f, 7f, depth);
            alpha += Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(1f, 6f, depth);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 76f));
