        {
            return Mathf.Clamp01(
                Mathf.Lerp(0.28f, 0.64f, Mathf.Clamp01(phase))
                    + Mathf.Clamp01(markerPulse) * 0.18f
                    + Mathf.Clamp01(rotationReadiness) * 0.10f);
        }

        private static float BuildStraightRunFocusBeaconOffsetX(
            float rotationDirection,
            float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 0.035f;
        }

        private static float BuildStraightRunFocusRingOffsetX(
            float rotationDirection,
            float rotationReadiness,
            int ringIndex)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            int safeIndex = Mathf.Clamp(ringIndex, 0, StraightRunFocusRingCount - 1);
            float sequence = safeIndex / (float)Mathf.Max(1, StraightRunFocusRingCount - 1);
            float depthWeight = Mathf.Lerp(1f, 0.58f, sequence);
            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 0.030f * depthWeight;
        }

        private static float BuildStraightRunFocusRingAnchorY(float rotationReadiness, int ringIndex)
        {
            int safeIndex = Mathf.Clamp(ringIndex, 0, StraightRunFocusRingCount - 1);
            float sequence = safeIndex / (float)Mathf.Max(1, StraightRunFocusRingCount - 1);
            float baseY = Mathf.Lerp(0.734f, 0.804f, sequence);
            return baseY - Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.010f, 0.020f, sequence);
        }

        private static float BuildStraightRunFocusRingPulse(
            bool running,
            float motionStrength,
            float forwardPulse,
            float downbeatPulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness,
            int ringIndex)
        {
            if (!running)
            {
                return 0f;
            }

            int safeIndex = Mathf.Clamp(ringIndex, 0, StraightRunFocusRingCount - 1);
            float sequence = safeIndex / (float)Mathf.Max(1, StraightRunFocusRingCount - 1);
            float depthWeight = Mathf.Lerp(1f, 0.72f, sequence);
            return Mathf.Clamp01(
                (Mathf.Clamp01(motionStrength) * 0.20f
                    + Mathf.Clamp01(forwardPulse) * 0.30f
                    + Mathf.Clamp01(downbeatPulse) * 0.20f
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * 0.13f
                    + Mathf.Clamp01(rotationReadiness) * 0.17f)
                * depthWeight);
        }

        private static float BuildStraightRunFocusRingSize(
            float pulse,
            float rotationReadiness,
            int ringIndex)
        {
            int safeIndex = Mathf.Clamp(ringIndex, 0, StraightRunFocusRingCount - 1);
            float sequence = safeIndex / (float)Mathf.Max(1, StraightRunFocusRingCount - 1);
            return Mathf.Lerp(78f, 30f, sequence)
                + Mathf.Clamp01(pulse) * Mathf.Lerp(12f, 6f, sequence)
                + Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(5f, 2f, sequence);
        }

        private static int BuildStraightRunFocusRingAlpha(
            bool visible,
            float motionStrength,
            float pulse,
            float recoveryPressure,
            int ringIndex)
        {
            if (!visible)
            {
                return 0;
            }

            int safeIndex = Mathf.Clamp(ringIndex, 0, StraightRunFocusRingCount - 1);
            float sequence = safeIndex / (float)Mathf.Max(1, StraightRunFocusRingCount - 1);
            float alpha = Mathf.Lerp(18f, 12f, sequence)
                + Mathf.Clamp01(motionStrength) * Mathf.Lerp(18f, 10f, sequence)
                + Mathf.Clamp01(pulse) * Mathf.Lerp(38f, 26f, sequence);
            alpha = Mathf.Min(alpha, 82f);
            return BuildMissRecoveryMotionAlpha(
                Mathf.RoundToInt(alpha),
                recoveryPressure,
                0.16f);
        }

        private static float BuildStraightRunFocusRingAngle(
            float rotationDirection,
            float rotationReadiness,
            int ringIndex)
        {
            int safeIndex = Mathf.Clamp(ringIndex, 0, StraightRunFocusRingCount - 1);
            float sequence = safeIndex / (float)Mathf.Max(1, StraightRunFocusRingCount - 1);
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 45f;
            }

            return Mathf.Clamp(
                45f + Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(5.5f, 2.5f, sequence),
                39f,
                51f);
        }

        private static float BuildStraightRunFocusRingColorBlend(
            float pulse,
            float rotationReadiness,
            int ringIndex)
        {
            int safeIndex = Mathf.Clamp(ringIndex, 0, StraightRunFocusRingCount - 1);
            float sequence = safeIndex / (float)Mathf.Max(1, StraightRunFocusRingCount - 1);
            return Mathf.Clamp01(
                0.32f
                + Mathf.Clamp01(pulse) * Mathf.Lerp(0.32f, 0.20f, sequence)
                + Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.22f, 0.14f, sequence));
        }

        private static bool IsStraightRunTargetFrameHorizontalPiece(int pieceIndex)
        {
            int safeIndex = Mathf.Clamp(pieceIndex, 0, StraightRunTargetFramePieceCount - 1);
            return safeIndex == 0 || safeIndex == 1;
        }

        private static float BuildStraightRunTargetFrameHalfSpread(float rotationReadiness)
        {
            return Mathf.Lerp(0.040f, 0.052f, Mathf.Clamp01(rotationReadiness));
        }

        private static float BuildStraightRunTargetFrameOffsetX(
            float rotationDirection,
            float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 0.026f;
        }

        private static float BuildStraightRunTargetFramePieceAnchorX(
            int pieceIndex,
            float rotationDirection,
            float rotationReadiness)
        {
            int safeIndex = Mathf.Clamp(pieceIndex, 0, StraightRunTargetFramePieceCount - 1);
            float offset = BuildStraightRunTargetFrameOffsetX(rotationDirection, rotationReadiness);
            if (safeIndex == 2)
            {
                return 0.5f - BuildStraightRunTargetFrameHalfSpread(rotationReadiness) + offset;
            }

            if (safeIndex == 3)
            {
                return 0.5f + BuildStraightRunTargetFrameHalfSpread(rotationReadiness) + offset;
            }

            return 0.5f + offset;
        }

        private static float BuildStraightRunTargetFramePieceAnchorY(
            int pieceIndex,
            float rotationReadiness)
        {
            int safeIndex = Mathf.Clamp(pieceIndex, 0, StraightRunTargetFramePieceCount - 1);
            float readiness = Mathf.Clamp01(rotationReadiness);
            switch (safeIndex)
            {
                case 0:
                    return 0.816f - readiness * 0.012f;
                case 1:
                    return 0.768f - readiness * 0.010f;
                default:
                    return 0.792f - readiness * 0.011f;
            }
        }

        private static float BuildStraightRunTargetFramePulse(
            bool running,
            float motionStrength,
            float forwardPulse,
            float downbeatPulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            if (!running)
            {
                return 0f;
            }

            return Mathf.Clamp01(
                Mathf.Clamp01(motionStrength) * 0.18f
                    + Mathf.Clamp01(forwardPulse) * 0.30f
                    + Mathf.Clamp01(downbeatPulse) * 0.19f
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * 0.13f
                    + Mathf.Clamp01(rotationReadiness) * 0.20f);
        }

        private static float BuildStraightRunTargetFramePieceWidth(
            int pieceIndex,
            float pulse,
            float rotationReadiness)
        {
            bool horizontal = IsStraightRunTargetFrameHorizontalPiece(pieceIndex);
            float readiness = Mathf.Clamp01(rotationReadiness);
            return horizontal
                ? 68f + Mathf.Clamp01(pulse) * 18f + readiness * 8f
                : 5f + Mathf.Clamp01(pulse) * 1.6f + readiness * 1.2f;
        }

        private static float BuildStraightRunTargetFramePieceHeight(
            int pieceIndex,
            float pulse,
            float rotationReadiness)
        {
            bool horizontal = IsStraightRunTargetFrameHorizontalPiece(pieceIndex);
            float readiness = Mathf.Clamp01(rotationReadiness);
            return horizontal
                ? 5f + Mathf.Clamp01(pulse) * 1.8f + readiness * 1.0f
                : 38f + Mathf.Clamp01(pulse) * 10f + readiness * 5f;
        }

        private static int BuildStraightRunTargetFramePieceAlpha(
            bool visible,
            float motionStrength,
            float pulse,
            float recoveryPressure,
            int pieceIndex)
        {
            if (!visible)
            {
                return 0;
            }

            bool horizontal = IsStraightRunTargetFrameHorizontalPiece(pieceIndex);
            float alpha = horizontal ? 13f : 11f;
            alpha += Mathf.Clamp01(motionStrength) * (horizontal ? 20f : 17f);
            alpha += Mathf.Clamp01(pulse) * (horizontal ? 48f : 39f);
            alpha = Mathf.Min(alpha, horizontal ? 92f : 78f);
            return BuildMissRecoveryMotionAlpha(
                Mathf.RoundToInt(alpha),
                recoveryPressure,
                0.14f);
        }

        private static float BuildStraightRunTargetFramePieceAngle(
            int pieceIndex,
            float rotationDirection,
            float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            int safeIndex = Mathf.Clamp(pieceIndex, 0, StraightRunTargetFramePieceCount - 1);
            float pieceWeight = IsStraightRunTargetFrameHorizontalPiece(safeIndex) ? 1f : 0.72f;
            return Mathf.Clamp(
                Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 4.8f * pieceWeight,
                -4.8f,
                4.8f);
        }

        private static float BuildStraightRunTargetFramePieceColorBlend(
            float pulse,
            float rotationReadiness,
            int pieceIndex)
        {
            bool horizontal = IsStraightRunTargetFrameHorizontalPiece(pieceIndex);
            return Mathf.Clamp01(
                (horizontal ? 0.34f : 0.28f)
                    + Mathf.Clamp01(pulse) * (horizontal ? 0.30f : 0.24f)
                    + Mathf.Clamp01(rotationReadiness) * 0.20f);
        }

        private static bool IsStraightRunExitSlotCenterPiece(int pieceIndex)
        {
            return Mathf.Clamp(pieceIndex, 0, StraightRunExitSlotPieceCount - 1) == 0;
        }

        private static float BuildStraightRunExitSlotEscapeStrength(GreedLastRunSnapshot snapshot)
        {
            return BuildStraightRunExitSlotEscapeStrengthForValues(
                snapshot.CoreRetrieved,
                snapshot.Phase,
                snapshot.ChapterIndex,
                snapshot.EscapeSucceeded,
                snapshot.Stopped);
        }

        private static float BuildStraightRunExitSlotEscapeStrengthForValues(
            bool coreRetrieved,
            GreedLastRunPhase phase,
            int chapterIndex,
            bool escapeSucceeded,
            bool stopped)
        {
            if (escapeSucceeded)
            {
                return stopped ? 0.82f : 1f;
            }

            if (phase == GreedLastRunPhase.EscapeRunning || phase == GreedLastRunPhase.ClearResolving)
            {
                return 1f;
            }

            if (coreRetrieved)
            {
                return 0.78f;
            }

            return chapterIndex >= 4 ? 0.36f : 0f;
        }

        private static float BuildStraightRunExitSlotPulse(
            bool running,
            float motionStrength,
            float forwardPulse,
            float downbeatPulse,
            float tunnelBeatCueUrgency,
            float escapeStrength,
            float rotationReadiness)
        {
            if (!running && escapeStrength <= 0f)
            {
                return 0f;
            }

            float liveWeight = running ? 1f : 0.62f;
            return Mathf.Clamp01(
                (Mathf.Clamp01(motionStrength) * 0.16f
                    + Mathf.Clamp01(forwardPulse) * 0.24f
                    + Mathf.Clamp01(downbeatPulse) * 0.16f
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * 0.10f
                    + Mathf.Clamp01(escapeStrength) * 0.38f
                    + Mathf.Clamp01(rotationReadiness) * 0.10f)
                * liveWeight);
        }

        private static float BuildStraightRunExitSlotPieceAnchorX(
            int pieceIndex,
            float rotationDirection,
            float rotationReadiness)
        {
            float offset = Mathf.Approximately(rotationDirection, 0f)
                ? 0f
                : Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 0.018f;
            if (IsStraightRunExitSlotCenterPiece(pieceIndex))
            {
                return 0.5f + offset;
            }

            float side = Mathf.Clamp(pieceIndex, 0, StraightRunExitSlotPieceCount - 1) == 1 ? -1f : 1f;
            return 0.5f + offset + side * (0.030f + Mathf.Clamp01(rotationReadiness) * 0.006f);
        }

        private static float BuildStraightRunExitSlotPieceAnchorY(
            int pieceIndex,
            float escapeStrength,
            float rotationReadiness)
        {
            float centerLift = IsStraightRunExitSlotCenterPiece(pieceIndex) ? 0.004f : 0f;
            return 0.836f
                - Mathf.Clamp01(escapeStrength) * 0.016f
                - Mathf.Clamp01(rotationReadiness) * 0.006f
                + centerLift;
        }

        private static float BuildStraightRunExitSlotPieceWidth(
            int pieceIndex,
            float pulse,
            float escapeStrength,
            float rotationReadiness)
        {
            bool center = IsStraightRunExitSlotCenterPiece(pieceIndex);
            return (center ? 16f : 5f)
                + Mathf.Clamp01(pulse) * (center ? 8f : 2f)
                + Mathf.Clamp01(escapeStrength) * (center ? 10f : 1.6f)
                + Mathf.Clamp01(rotationReadiness) * (center ? 2f : 0.8f);
        }

        private static float BuildStraightRunExitSlotPieceHeight(
            int pieceIndex,
            float pulse,
            float escapeStrength,
            float rotationReadiness)
        {
            bool center = IsStraightRunExitSlotCenterPiece(pieceIndex);
            return (center ? 52f : 38f)
                + Mathf.Clamp01(pulse) * (center ? 18f : 11f)
                + Mathf.Clamp01(escapeStrength) * (center ? 24f : 16f)
                + Mathf.Clamp01(rotationReadiness) * (center ? 5f : 3f);
        }

        private static float BuildStraightRunExitSlotPieceAngle(
            int pieceIndex,
            float rotationDirection,
            float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            float sideWeight = IsStraightRunExitSlotCenterPiece(pieceIndex) ? 0.55f : 1f;
            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 3.4f * sideWeight;
        }

        private static int BuildStraightRunExitSlotPieceAlpha(
            bool visible,
            float motionStrength,
            float pulse,
            float escapeStrength,
            float recoveryPressure,
            int pieceIndex)
        {
            if (!visible)
            {
                return 0;
            }

            bool center = IsStraightRunExitSlotCenterPiece(pieceIndex);
            float alpha = (center ? 8f : 6f)
                + Mathf.Clamp01(motionStrength) * (center ? 18f : 13f)
                + Mathf.Clamp01(pulse) * (center ? 54f : 38f)
                + Mathf.Clamp01(escapeStrength) * (center ? 74f : 56f);
            alpha = Mathf.Min(alpha, center ? 142f : 112f);
            return BuildMissRecoveryMotionAlpha(
                Mathf.RoundToInt(alpha),
                recoveryPressure,
                0.10f);
        }

        private static float BuildStraightRunExitSlotPieceColorBlend(
            float pulse,
            float escapeStrength,
            float rotationReadiness,
            int pieceIndex)
        {
            bool center = IsStraightRunExitSlotCenterPiece(pieceIndex);
            return Mathf.Clamp01(
                (center ? 0.40f : 0.30f)
                + Mathf.Clamp01(pulse) * (center ? 0.26f : 0.20f)
                + Mathf.Clamp01(escapeStrength) * (center ? 0.34f : 0.28f)
                + Mathf.Clamp01(rotationReadiness) * 0.12f);
        }

        private static float BuildStraightRunExitApproachRailSide(int railIndex)
        {
            return Mathf.Clamp(railIndex, 0, StraightRunExitApproachRailCount - 1) == 0 ? -1f : 1f;
        }

        private static float BuildStraightRunExitApproachRailPulse(
            bool running,
            float motionStrength,
            float forwardPulse,
            float downbeatPulse,
            float tunnelBeatCueUrgency,
            float escapeStrength,
            float rotationReadiness)
        {
            if (escapeStrength <= 0f)
            {
                return 0f;
            }

            float liveWeight = running ? 1f : 0.58f;
            return Mathf.Clamp01(
                (Mathf.Clamp01(motionStrength) * 0.12f
                    + Mathf.Clamp01(forwardPulse) * 0.22f
                    + Mathf.Clamp01(downbeatPulse) * 0.24f
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * 0.12f
                    + Mathf.Clamp01(escapeStrength) * 0.38f
                    + Mathf.Clamp01(rotationReadiness) * 0.08f)
                * liveWeight);
        }

        private static float BuildStraightRunExitApproachRailAnchorX(
            int railIndex,
            float escapeStrength,
            float rotationDirection,
            float rotationReadiness)
        {
            float side = BuildStraightRunExitApproachRailSide(railIndex);
            float spread = Mathf.Lerp(0.068f, 0.048f, Mathf.Clamp01(escapeStrength));
            float rotationOffset = Mathf.Approximately(rotationDirection, 0f)
                ? 0f
                : Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 0.018f;
            return 0.5f + side * spread + rotationOffset;
        }

        private static float BuildStraightRunExitApproachRailAnchorY(float escapeStrength, float pulse)
        {
            return 0.785f
                - Mathf.Clamp01(escapeStrength) * 0.018f
                - Mathf.Clamp01(pulse) * 0.006f;
        }

        private static float BuildStraightRunExitApproachRailWidth(float pulse, float escapeStrength)
        {
            return 4f
                + Mathf.Clamp01(pulse) * 2.4f
                + Mathf.Clamp01(escapeStrength) * 2f;
        }

        private static float BuildStraightRunExitApproachRailHeight(float pulse, float escapeStrength)
        {
            return 92f
                + Mathf.Clamp01(pulse) * 30f
                + Mathf.Clamp01(escapeStrength) * 62f;
        }

        private static float BuildStraightRunExitApproachRailAngle(
            int railIndex,
            float escapeStrength,
            float rotationDirection,
            float rotationReadiness)
        {
            float side = BuildStraightRunExitApproachRailSide(railIndex);
            float inwardAngle = Mathf.Lerp(8f, 4.8f, Mathf.Clamp01(escapeStrength));
            float rotationAngle = Mathf.Approximately(rotationDirection, 0f)
                ? 0f
                : Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 2.2f;
            return side * inwardAngle + rotationAngle;
        }

        private static int BuildStraightRunExitApproachRailAlpha(
            bool visible,
            float motionStrength,
            float pulse,
            float escapeStrength,
            float recoveryPressure)
        {
            if (!visible || escapeStrength <= 0f)
            {
                return 0;
            }

            float alpha = Mathf.Clamp01(escapeStrength) * 72f
                + Mathf.Clamp01(motionStrength) * 12f
                + Mathf.Clamp01(pulse) * 34f;
            alpha = Mathf.Min(alpha, 116f);
            return BuildMissRecoveryMotionAlpha(
                Mathf.RoundToInt(alpha),
                recoveryPressure,
                0.10f);
        }

        private static float BuildStraightRunExitApproachRailColorBlend(
            float pulse,
            float escapeStrength,
            float rotationReadiness)
        {
            return Mathf.Clamp01(
                0.34f
                + Mathf.Clamp01(pulse) * 0.25f
                + Mathf.Clamp01(escapeStrength) * 0.31f
                + Mathf.Clamp01(rotationReadiness) * 0.10f);
        }

        private static float BuildStraightRunLaunchGateSide(int pieceIndex)
        {
            return Mathf.Clamp(pieceIndex, 0, StraightRunLaunchGatePieceCount - 1) == 0 ? -1f : 1f;
        }

        private static bool BuildStraightRunLaunchGateVisible(
            bool visible,
            bool countdownActive,
            bool paused,
            bool stopped,
            bool choiceActive,
            bool resumeCountdownActive)
        {
            return visible
                && countdownActive
                && (!paused || resumeCountdownActive)
                && !stopped
                && !choiceActive;
        }

        private static bool ShouldStartStraightRunLaunchRelease(
            bool previousCountdownActive,
            bool countdownActive,
            bool runModeActive,
            bool liveControlWindow)
        {
            return previousCountdownActive
                && !countdownActive
                && runModeActive
                && liveControlWindow;
        }

        private static bool ShouldQueueRunEntryTrapReveal(
            bool launchReleaseStarted,
            bool resumeCountdown,
            int successCount,
            int goodCount,
            int missCount)
        {
            return launchReleaseStarted
                && !resumeCountdown
                && Mathf.Max(0, successCount) == 0
                && Mathf.Max(0, goodCount) == 0
                && Mathf.Max(0, missCount) == 0;
        }

        private static float BuildStraightRunLaunchGateReleaseProgress(
            float now,
            float startedAt,
            float until)
        {
            float duration = until - startedAt;
            if (duration <= 0f || now >= until)
            {
                return 1f;
            }

            if (now <= startedAt)
            {
                return 0f;
            }

            return Mathf.Clamp01((now - startedAt) / duration);
        }

        private static float BuildStraightRunLaunchGateReleasePulse(
            float now,
            float startedAt,
            float until)
        {
            if (until <= startedAt || now < startedAt || now >= until)
            {
                return 0f;
            }

            float remaining = 1f - BuildStraightRunLaunchGateReleaseProgress(now, startedAt, until);
            return remaining * remaining;
        }

        private static float BuildStraightRunLaunchGateOpenProgress(bool visible, float remainingSeconds)
        {
            if (!visible)
            {
                return 1f;
            }

            return Mathf.Clamp01(1f - Mathf.Max(0f, remainingSeconds) / 1.2f);
        }

        private static float BuildStraightRunLaunchGateBeatPulse(bool visible, float remainingSeconds)
        {
            if (!visible)
            {
                return 0f;
            }

            float phase = Mathf.Repeat(Mathf.Max(0f, remainingSeconds), 0.6f) / 0.6f;
            return 1f - Mathf.Abs(phase * 2f - 1f);
        }

        private static float BuildStraightRunLaunchGateAnchorX(int pieceIndex, float openProgress)
        {
            float side = BuildStraightRunLaunchGateSide(pieceIndex);
            return 0.5f + side * Mathf.Lerp(0.078f, 0.205f, Mathf.Clamp01(openProgress));
        }

        private static float BuildStraightRunLaunchGateAnchorY(float openProgress, float pulse)
        {
            return 0.69f
                + Mathf.Clamp01(openProgress) * 0.012f
                + Mathf.Clamp01(pulse) * 0.004f;
        }

        private static float BuildStraightRunLaunchGateWidth(float openProgress, float pulse)
        {
            return 150f
                - Mathf.Clamp01(openProgress) * 54f
                + Mathf.Clamp01(pulse) * 10f;
        }

        private static float BuildStraightRunLaunchGateHeight(float openProgress, float pulse)
        {
            return 8f
                + Mathf.Clamp01(openProgress) * 3f
                + Mathf.Clamp01(pulse) * 3f;
        }

        private static float BuildStraightRunLaunchGateAngle(int pieceIndex, float openProgress)
        {
            float side = BuildStraightRunLaunchGateSide(pieceIndex);
            return side * Mathf.Lerp(2.5f, 7.5f, Mathf.Clamp01(openProgress));
        }

        private static int BuildStraightRunLaunchGateAlpha(bool visible, float openProgress, float pulse)
        {
            if (!visible)
            {
                return 0;
            }

            float alpha = 76f
                + Mathf.Clamp01(pulse) * 52f
                - Mathf.Clamp01(openProgress) * 16f;
            return Mathf.Clamp(Mathf.RoundToInt(alpha), 0, 132);
        }

        private static float BuildStraightRunLaunchGateColorBlend(float openProgress, float pulse)
        {
            return Mathf.Clamp01(
                0.42f
                + Mathf.Clamp01(openProgress) * 0.18f
                + Mathf.Clamp01(pulse) * 0.30f);
        }

        private static float BuildStraightRunLaunchGateReleaseOffset(float releaseProgress, float releasePulse)
        {
            if (releasePulse <= 0f)
            {
                return 0f;
            }

            return Mathf.Lerp(0.015f, 0.075f, Mathf.Clamp01(releaseProgress))
                * Mathf.Clamp01(releasePulse);
        }

        private static float BuildStraightRunLaunchGateReleaseAngleLift(float releaseProgress, float releasePulse)
        {
            return Mathf.Lerp(1f, 5f, Mathf.Clamp01(releaseProgress))
                * Mathf.Clamp01(releasePulse);
        }

        private static int BuildStraightRunLaunchGateReleaseAlpha(bool visible, float releasePulse)
        {
            return visible
                ? Mathf.Clamp(Mathf.RoundToInt(118f * Mathf.Clamp01(releasePulse)), 0, 118)
                : 0;
        }

        private static float BuildStraightRunLaunchGateReleaseColorLift(float releasePulse)
        {
            return Mathf.Clamp01(releasePulse) * 0.24f;
        }

        private static float BuildStraightRunLaunchForwardBurst(
            bool visible,
            bool running,
            float now,
            float releaseStartedAt,
            float releaseUntil)
        {
            if (!visible || !running)
            {
                return 0f;
            }

            return Mathf.Clamp01(
                BuildStraightRunLaunchGateReleasePulse(
                    now,
                    releaseStartedAt,
                    releaseUntil) * 1.08f);
        }

        private static float BuildRunEntryThresholdSweepStrength(
            bool visible,
            bool running,
            bool resumeLaunch,
            float now,
            float releaseStartedAt,
            float releaseUntil)
        {
            return BuildTempleEntranceLaunchPassThroughStrength(
                visible,
                running,
                resumeLaunch,
                now,
                releaseStartedAt,
                releaseUntil);
        }

        private static float BuildRunEntryThresholdSweepAnchorY(float releaseProgress)
        {
            float progress = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(releaseProgress));
            return Mathf.Lerp(0.72f, 0.30f, progress);
        }

        private static float BuildRunEntryThresholdSweepWidth(float releaseProgress)
        {
            return Mathf.Lerp(210f, 610f, Mathf.Clamp01(releaseProgress));
        }

        private static float BuildRunEntryThresholdSweepHeight(float strength)
        {
            return 6f + Mathf.Clamp01(strength) * 6f;
        }

        private static int BuildRunEntryThresholdSweepAlpha(float strength, float releaseProgress)
        {
            float alpha = Mathf.Clamp01(strength) * Mathf.Lerp(172f, 88f, Mathf.Clamp01(releaseProgress));
            return Mathf.Clamp(Mathf.RoundToInt(alpha), 0, 172);
        }

        private static float BuildRunEntryThresholdSweepColorBlend(float releaseProgress)
        {
            return Mathf.Lerp(0.56f, 0.82f, Mathf.Clamp01(releaseProgress));
        }

        private static float BuildRunnerCountdownReadyStrength(
            bool visible,
            bool countdownActive,
            bool paused,
            bool resumeCountdownActive,
            bool stopped,
            bool choiceActive,
            float remainingSeconds)
        {
            if (!BuildStraightRunLaunchGateVisible(
                    visible,
                    countdownActive,
                    paused,
                    stopped,
                    choiceActive,
                    resumeCountdownActive))
            {
                return 0f;
            }

            float openProgress = BuildStraightRunLaunchGateOpenProgress(true, remainingSeconds);
            float beatPulse = BuildStraightRunLaunchGateBeatPulse(true, remainingSeconds);
            return Mathf.Clamp01(0.36f + openProgress * 0.44f + beatPulse * 0.20f);
        }

        private static float BuildRunnerCountdownReadyOffsetY(float strength)
        {
            return -Mathf.Clamp01(strength) * 8f;
        }

        private static float BuildRunnerCountdownReadyScaleX(float strength)
        {
            return 1f + Mathf.Clamp01(strength) * 0.06f;
        }

        private static float BuildRunnerCountdownReadyScaleY(float strength)
        {
            return 1f - Mathf.Clamp01(strength) * 0.10f;
        }

        private static float BuildRunnerCountdownReadyAngle(float strength, float phase)
        {
            return Mathf.Sin(Mathf.Repeat(phase, 1f) * Mathf.PI * 2f)
                * Mathf.Clamp01(strength)
                * 1.2f;
        }

        private static float BuildRunnerCountdownReadyColorBlend(float strength)
        {
            return Mathf.Clamp01(strength) * 0.20f;
        }

        private static float BuildRunnerCountdownReadyShadowScaleXLift(float strength)
        {
            return Mathf.Clamp01(strength) * 0.16f;
        }

        private static float BuildRunnerCountdownReadyShadowAlphaLift(float strength)
        {
            return Mathf.Clamp01(strength) * 22f;
        }

        private static float BuildRunnerLaunchStepStrength(
            bool visible,
            bool running,
            float now,
            float releaseStartedAt,
            float releaseUntil)
        {
            return BuildStraightRunLaunchForwardBurst(
                visible,
                running,
                now,
                releaseStartedAt,
                releaseUntil);
        }

        private static float BuildRunnerLaunchStepLift(float strength)
        {
            return Mathf.Clamp01(strength) * 12f;
        }

        private static float BuildRunnerLaunchStepScaleX(float strength)
        {
            return 1f - Mathf.Clamp01(strength) * 0.045f;
        }

        private static float BuildRunnerLaunchStepScaleY(float strength)
        {
            return 1f + Mathf.Clamp01(strength) * 0.09f;
        }

        private static float BuildRunnerLaunchStepAngle(float strength)
        {
            return -Mathf.Clamp01(strength) * 2.4f;
        }

        private static float BuildRunnerLaunchStepColorBlend(float strength)
        {
            return Mathf.Clamp01(strength) * 0.24f;
        }

        private static float BuildRunnerLaunchStepShadowScaleXLift(float strength)
        {
            return Mathf.Clamp01(strength) * 0.12f;
        }

        private static float BuildRunnerLaunchStepShadowAlphaLift(float strength)
        {
            return Mathf.Clamp01(strength) * 18f;
        }

        private static float BuildRunnerEntryThreatDirection(GreedLastRunChannel channel)
        {
            if (channel == GreedLastRunChannel.Left)
            {
                return -1f;
            }

            return channel == GreedLastRunChannel.Right ? 1f : 0f;
        }

        private static float BuildRunnerEntryThreatOffsetX(float direction, float strength)
        {
            return Mathf.Clamp(direction, -1f, 1f) * Mathf.Clamp01(strength) * 6f;
        }

        private static float BuildRunnerEntryThreatOffsetY(float strength)
        {
            return -Mathf.Clamp01(strength) * 2.5f;
        }

        private static float BuildRunnerEntryThreatScaleX(float strength)
        {
            return 1f + Mathf.Clamp01(strength) * 0.025f;
        }

        private static float BuildRunnerEntryThreatScaleY(float strength)
        {
            return 1f - Mathf.Clamp01(strength) * 0.018f;
        }

        private static float BuildRunnerEntryThreatAngle(float direction, float strength)
        {
            return -Mathf.Clamp(direction, -1f, 1f) * Mathf.Clamp01(strength) * 2.8f;
        }

        private static float BuildRunnerEntryThreatColorBlend(float strength)
        {
            return Mathf.Clamp01(strength) * 0.16f;
        }

        private static float BuildRunnerEntryThreatShadowOffsetX(float direction, float strength)
        {
            return Mathf.Clamp(direction, -1f, 1f) * Mathf.Clamp01(strength) * 2.8f;
        }

        private static float BuildRunnerEntryThreatShadowScaleXLift(float strength)
        {
            return Mathf.Clamp01(strength) * 0.07f;
        }

        private static float BuildRunnerEntryThreatShadowAlphaLift(float strength)
        {
            return Mathf.Clamp01(strength) * 12f;
        }

        private static float BuildRunnerEntryThreatSilhouetteStrength(float strength)
        {
            return Mathf.Clamp01(strength) * 0.58f;
        }

        private static float BuildStraightRunExitSprintStrength(
            bool visible,
            bool running,
            float escapeStrength)
        {
            if (!visible || !running)
            {
                return 0f;
            }

            return Mathf.Clamp01(Mathf.InverseLerp(0.50f, 1f, escapeStrength)) * 0.62f;
        }

        private static float BuildStraightRunExitSprintPulse(float exitSprintStrength, float downbeatPulse)
        {
            float sprint = Mathf.Clamp01(exitSprintStrength);
            return sprint * Mathf.Lerp(0.62f, 1f, Mathf.Clamp01(downbeatPulse));
        }

        private static float BuildStraightRunRotationComfortAnchorSide(int pieceIndex)
        {
            if (pieceIndex == 1)
            {
                return -1f;
            }

            return pieceIndex == 2 ? 1f : 0f;
        }

        private static bool ShouldShowStraightRunRotationComfortAnchor(
            bool visible,
            float activeRotationDirection,
            float activeRotationReadiness,
            float rotationResponseDirection,
            float rotationResponsePulse)
        {
            if (!visible)
            {
                return false;
            }

            bool activeRotation = Mathf.Abs(activeRotationDirection) > 0.01f
                && activeRotationReadiness > 0.01f;
            bool settlingRotation = Mathf.Abs(rotationResponseDirection) > 0.01f
                && rotationResponsePulse > 0.01f;
            return activeRotation || settlingRotation;
        }

        private static float BuildStraightRunRotationComfortAnchorDirection(
            float activeRotationDirection,
            float activeRotationReadiness,
            float rotationResponseDirection,
            float rotationResponsePulse)
        {
            if (Mathf.Abs(activeRotationDirection) > 0.01f && activeRotationReadiness > 0.01f)
            {
                return Mathf.Sign(activeRotationDirection);
            }

            return Mathf.Abs(rotationResponseDirection) > 0.01f && rotationResponsePulse > 0.01f
                ? Mathf.Sign(rotationResponseDirection)
                : 0f;
        }

        private static float BuildStraightRunRotationComfortAnchorStrength(
            float activeRotationReadiness,
            float rotationResponsePulse)
        {
            return Mathf.Clamp01(Mathf.Max(activeRotationReadiness, rotationResponsePulse));
        }

        private static float BuildStraightRunRotationComfortAnchorTargetStrength(
            float pieceSide,
            float rotationDirection,
            float strength)
        {
            float clampedStrength = Mathf.Clamp01(strength);
            if (Mathf.Abs(pieceSide) < 0.01f)
            {
                return clampedStrength * 0.62f;
            }

            bool targetSide = Mathf.Abs(rotationDirection) > 0.01f
                && Mathf.Sign(pieceSide) == Mathf.Sign(rotationDirection);
            return clampedStrength * (targetSide ? 1f : 0.18f);
        }

        private static float BuildStraightRunRotationComfortAnchorAnchorX(int pieceIndex)
        {
            return 0.5f + BuildStraightRunRotationComfortAnchorSide(pieceIndex) * 0.026f;
        }

        private static float BuildStraightRunRotationComfortAnchorWidth(
            int pieceIndex,
            float targetStrength,
            float downbeatPulse)
        {
            if (pieceIndex == 0)
            {
                return 3f + Mathf.Clamp01(downbeatPulse) * 1.5f;
            }

            return 18f
                + Mathf.Clamp01(targetStrength) * 18f
                + Mathf.Clamp01(downbeatPulse) * Mathf.Clamp01(targetStrength) * 5f;
        }

        private static float BuildStraightRunRotationComfortAnchorHeight(
            int pieceIndex,
            float strength,
            float targetStrength,
            float downbeatPulse)
        {
            if (pieceIndex == 0)
            {
                return 24f
                    + Mathf.Clamp01(strength) * 11f
                    + Mathf.Clamp01(downbeatPulse) * 4f;
            }

            return 3f
                + Mathf.Clamp01(targetStrength) * 2f
                + Mathf.Clamp01(downbeatPulse) * Mathf.Clamp01(targetStrength);
        }

        private static int BuildStraightRunRotationComfortAnchorAlpha(
            bool visible,
            bool centerPiece,
            float targetStrength,
            float strength,
            float downbeatPulse)
        {
            if (!visible)
            {
                return 0;
            }

            float alpha = centerPiece
                ? 28f + Mathf.Clamp01(strength) * 36f + Mathf.Clamp01(downbeatPulse) * 10f
                : 18f + Mathf.Clamp01(targetStrength) * 72f
                    + Mathf.Clamp01(downbeatPulse) * Mathf.Clamp01(targetStrength) * 14f;
            return Mathf.Clamp(Mathf.RoundToInt(alpha), 0, 108);
        }

        private static float BuildStraightRunFocusBeaconAnchorY(float rotationReadiness)
        {
            return Mathf.Lerp(0.792f, 0.772f, Mathf.Clamp01(rotationReadiness));
        }

        private static float BuildStraightRunFocusBeaconPulse(
            bool running,
            float motionStrength,
            float forwardPulse,
            float downbeatPulse,
            float tunnelBeatCueUrgency,
            float rotationReadiness)
        {
            if (!running)
            {
                return 0f;
            }

            return Mathf.Clamp01(
                Mathf.Clamp01(motionStrength) * 0.26f
                    + Mathf.Clamp01(forwardPulse) * 0.30f
                    + Mathf.Clamp01(downbeatPulse) * 0.24f
                    + Mathf.Clamp01(tunnelBeatCueUrgency) * 0.12f
                    + Mathf.Clamp01(rotationReadiness) * 0.20f);
        }

        private static float BuildStraightRunFocusBeaconSize(float pulse, float rotationReadiness)
        {
            return Mathf.Lerp(10f, 22f, Mathf.Clamp01(pulse))
                + Mathf.Clamp01(rotationReadiness) * 4f;
        }

        private static int BuildStraightRunFocusBeaconAlpha(
            bool visible,
            float motionStrength,
            float pulse,
            float recoveryPressure)
        {
            if (!visible)
            {
                return 0;
            }

            float alpha = 20f
                + Mathf.Clamp01(motionStrength) * 34f
                + Mathf.Clamp01(pulse) * 58f;
            alpha = Mathf.Min(alpha, 118f);
            return BuildMissRecoveryMotionAlpha(
                Mathf.RoundToInt(alpha),
                recoveryPressure,
                0.18f);
        }

        private static float BuildStraightRunFocusBeaconAngle(
            float rotationDirection,
            float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 45f;
            }

            return Mathf.Clamp(
                45f + Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 7f,
                38f,
                52f);
        }

        private static float BuildStraightRunFocusBeaconColorBlend(float pulse, float rotationReadiness)
        {
            return Mathf.Clamp01(0.44f + Mathf.Clamp01(pulse) * 0.32f + Mathf.Clamp01(rotationReadiness) * 0.24f);
        }

        private static float BuildStraightRunPathSegmentPhase(
            bool running,
            float beatProgress,
            float stageMotionScale,
            float motionSpeedBias,
            float forwardPulse,
            int segmentIndex)
        {
            float indexOffset = Mathf.Clamp(segmentIndex, 0, StraightRunPathSegmentCount - 1) / (float)StraightRunPathSegmentCount;
            if (!running)
            {
                return indexOffset;
            }

            float speed = (0.46f + Mathf.Clamp01(forwardPulse) * 0.16f)
                * Mathf.Max(0.1f, stageMotionScale)
                * Mathf.Max(0.1f, motionSpeedBias);
            return Mathf.Repeat(Mathf.Clamp01(beatProgress) * speed + indexOffset, 1f);
        }

        private static float BuildStraightRunPathSegmentY(float phase)
        {
            float eased = Mathf.Clamp01(phase);
            return Mathf.Lerp(0.82f, 0.18f, eased * eased);
        }

        private static float BuildStraightRunPathSegmentHalfWidth(float phase, float stageDepthScale, float rotationReadiness)
        {
            float eased = Mathf.Clamp01(phase);
            float width = Mathf.Lerp(45f, 345f, eased * eased);
            return width * Mathf.Max(0.86f, stageDepthScale) * Mathf.Lerp(1f, 1.08f, Mathf.Clamp01(rotationReadiness));
        }

        private static float BuildStraightRunPathSegmentHeight(float phase, float rotationReadiness)
        {
            return Mathf.Lerp(3f, 13f, Mathf.Clamp01(phase)) * Mathf.Lerp(1f, 1.25f, Mathf.Clamp01(rotationReadiness));
        }

        private static float BuildStraightRunPathRotationOffset(float rotationDirection, float rotationReadiness, float phase)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(0.006f, 0.040f, Mathf.Clamp01(phase));
        }

        private static float BuildStraightRunPathSegmentNearPulse(float phase, float downbeatPulse)
        {
            float nearWeight = Mathf.Clamp01((Mathf.Clamp01(phase) - 0.55f) / 0.45f);
            return Mathf.Clamp01(downbeatPulse) * nearWeight;
        }

        private static int BuildStraightRunPathSegmentAlpha(
            bool visible,
            float motionStrength,
            float phase,
            float forwardPulse,
            float nearPulse,
            float rotationReadiness)
        {
            if (!visible)
            {
                return 0;
            }

            float depthAlpha = Mathf.Lerp(10f, 74f, Mathf.Clamp01(phase));
            float alpha = depthAlpha * Mathf.Lerp(0.52f, 1f, Mathf.Clamp01(motionStrength));
            alpha += Mathf.Clamp01(forwardPulse) * 18f;
            alpha += Mathf.Clamp01(nearPulse) * 20f;
            alpha += Mathf.Clamp01(rotationReadiness) * 24f;
            return Mathf.RoundToInt(alpha);
        }

        private static float BuildStraightRunRotationGuideOffset(float rotationDirection, float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Clamp01(rotationReadiness) * 0.045f;
        }

        private static float BuildStraightRunRotationGuideWidth(float rotationReadiness)
        {
            return Mathf.Lerp(360f, 610f, Mathf.Clamp01(rotationReadiness));
        }

        private static float BuildStraightRunRotationGuideHeight(float rotationReadiness, float downbeatPulse)
        {
            return Mathf.Lerp(10f, 23f, Mathf.Clamp01(rotationReadiness)) + Mathf.Clamp01(downbeatPulse) * 4f;
        }

        private static float BuildStraightRunRotationGuideAngle(float rotationDirection, float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Lerp(4f, 18f, Mathf.Clamp01(rotationReadiness));
        }

        private static int BuildStraightRunRotationGuideAlpha(bool visible, float rotationReadiness, float downbeatPulse)
        {
            if (!visible)
            {
                return 0;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            return Mathf.RoundToInt(readiness * 116f + Mathf.Clamp01(downbeatPulse) * readiness * 28f);
        }

        private static float BuildStraightRunRotationGuideNeedleOffset(
            float rotationDirection,
            float rotationReadiness,
            float sequence)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            float fan = (Mathf.Clamp01(sequence) - 0.5f) * 0.030f;
            float distance = Mathf.Lerp(0.070f, 0.132f, Mathf.Clamp01(rotationReadiness));
            return Mathf.Sign(rotationDirection) * (distance + fan);
        }

        private static float BuildStraightRunRotationGuideNeedleAnchorY(float sequence, float rotationReadiness)
        {
            float centered = Mathf.Clamp01(sequence) - 0.5f;
            return 0.55f + centered * 0.052f + Mathf.Clamp01(rotationReadiness) * 0.010f;
        }

        private static float BuildStraightRunRotationGuideNeedleAngle(float rotationDirection, float rotationReadiness)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection) * Mathf.Lerp(24f, 43f, Mathf.Clamp01(rotationReadiness));
        }

        private static float BuildStraightRunRotationGuideNeedleWidth(
            float rotationReadiness,
            float downbeatPulse,
            float sequence)
        {
            float sequenceLift = Mathf.Clamp01(sequence) * 5f;
            return Mathf.Lerp(18f, 34f + sequenceLift, Mathf.Clamp01(rotationReadiness))
                + Mathf.Clamp01(downbeatPulse) * 4f;
        }

        private static float BuildStraightRunRotationGuideNeedleHeight(
            float rotationReadiness,
            float downbeatPulse,
            float sequence)
        {
            return Mathf.Lerp(4f, 8f + Mathf.Clamp01(sequence) * 2f, Mathf.Clamp01(rotationReadiness))
                + Mathf.Clamp01(downbeatPulse) * 1.6f;
        }

        private static int BuildStraightRunRotationGuideNeedleAlpha(
            bool visible,
            float rotationDirection,
            float rotationReadiness,
            float downbeatPulse,
            float sequence)
        {
            if (!visible || Mathf.Approximately(rotationDirection, 0f))
            {
                return 0;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            float wave = Mathf.Lerp(0.78f, 1.08f, Mathf.Clamp01(sequence));
            float pulseLift = Mathf.Clamp01(downbeatPulse) * 42f;
            return Mathf.RoundToInt(readiness * (58f * wave + pulseLift));
        }

        private static bool ShouldShowStraightRunRotationResponsePips(
            bool visible,
            bool stopped,
            bool paused,
            bool choiceActive,
            bool countdownActive)
        {
            return visible && !stopped && !paused && !choiceActive && !countdownActive;
        }

        private static float BuildStraightRunRotationResponsePulse(
            bool rotationResponse,
            GreedLastJudgementResult result,
            float remainingSeconds,
            float durationSeconds)
        {
            if (!rotationResponse
                || result == GreedLastJudgementResult.None
                || remainingSeconds <= 0f
                || durationSeconds <= 0f)
            {
                return 0f;
            }

            float remaining = Mathf.Clamp01(remainingSeconds / durationSeconds);
            float resultWeight = result == GreedLastJudgementResult.Success
                ? 1f
                : result == GreedLastJudgementResult.Good ? 0.72f : 0.56f;
            return Mathf.Clamp01(remaining * remaining * resultWeight);
        }

        private static float BuildStraightRunRotationTiltDisplayReadiness(
            float activeReadiness,
            float responsePulse)
        {
            return Mathf.Clamp01(Mathf.Max(activeReadiness, responsePulse));
        }

        private static float BuildStraightRunRotationCorridorSettleReadiness(
            float activeReadiness,
            float responsePulse)
        {
            return Mathf.Clamp01(Mathf.Max(activeReadiness, Mathf.Clamp01(responsePulse) * 0.72f));
        }

        private static float BuildStraightRunRotationTiltDisplayDirection(
            float activeDirection,
            float activeReadiness,
            float responseDirection,
            float responsePulse)
        {
            float active = Mathf.Clamp01(activeReadiness);
            float response = Mathf.Clamp01(responsePulse);
            if (response > active + 0.04f && !Mathf.Approximately(responseDirection, 0f))
            {
                return Mathf.Sign(responseDirection);
            }

            if (!Mathf.Approximately(activeDirection, 0f))
            {
                return Mathf.Sign(activeDirection);
            }

            return Mathf.Approximately(responseDirection, 0f) ? 0f : Mathf.Sign(responseDirection);
        }

        private static float BuildStraightRunRotationCorridorSettleDirection(
            float activeDirection,
            float activeReadiness,
            float responseDirection,
            float responsePulse)
        {
            float active = Mathf.Clamp01(activeReadiness);
            float response = Mathf.Clamp01(responsePulse) * 0.72f;
            if (response > active + 0.04f && !Mathf.Approximately(responseDirection, 0f))
            {
                return Mathf.Sign(responseDirection);
            }

            if (!Mathf.Approximately(activeDirection, 0f))
            {
                return Mathf.Sign(activeDirection);
            }

            return Mathf.Approximately(responseDirection, 0f) ? 0f : Mathf.Sign(responseDirection);
        }

        private static float BuildRotationResponseDirection(GreedLastRunChannel channel)
        {
            switch (channel)
            {
                case GreedLastRunChannel.Left:
                    return -1f;
                case GreedLastRunChannel.Right:
                    return 1f;
                default:
                    return 0f;
            }
        }

        private static Color32 BuildStraightRunRotationCorridorSettleColor(
            float responsePulse,
            GreedLastJudgementResult responseResult)
        {
            if (responsePulse <= 0f)
            {
                return PrototypeGoldColor;
            }

            if (responseResult == GreedLastJudgementResult.Miss)
            {
                return Color32.Lerp(PrototypeVermilionColor, PrototypeGoldColor, 0.12f);
            }

            if (responseResult == GreedLastJudgementResult.Good)
            {
                return Color32.Lerp(PrototypeTealColor, PrototypeGoldColor, 0.54f);
            }

            return new Color32(255, 238, 181, 255);
        }

        private static float BuildStraightRunRotationCorridorSettleColorBlend(float responsePulse)
        {
            return Mathf.Clamp01(Mathf.Clamp01(responsePulse) * 0.34f);
        }

        private static Color32 BuildStraightRunRotationTiltPipTargetColor(
            float responsePulse,
            GreedLastJudgementResult responseResult)
        {
            if (responsePulse <= 0f)
            {
                return PrototypeGoldColor;
            }

            if (responseResult == GreedLastJudgementResult.Miss)
            {
                return Color32.Lerp(PrototypeVermilionColor, PrototypeGoldColor, 0.18f);
            }

            return responseResult == GreedLastJudgementResult.Good
                ? Color32.Lerp(PrototypeTealColor, PrototypeGoldColor, 0.68f)
                : new Color32(255, 238, 181, 255);
        }

        private static float BuildStraightRunRotationTiltPipSide(int pipIndex)
        {
            int center = StraightRunRotationTiltPipCount / 2;
            int clamped = Mathf.Clamp(pipIndex, 0, StraightRunRotationTiltPipCount - 1);
            if (clamped < center)
            {
                return -1f;
            }

            return clamped > center ? 1f : 0f;
        }

        private static float BuildStraightRunRotationTiltPipDistance(int pipIndex)
        {
            int center = StraightRunRotationTiltPipCount / 2;
            return Mathf.Abs(Mathf.Clamp(pipIndex, 0, StraightRunRotationTiltPipCount - 1) - center);
        }

        private static bool IsStraightRunRotationTiltPipTargetSide(float rotationDirection, int pipIndex)
        {
            float side = BuildStraightRunRotationTiltPipSide(pipIndex);
            return !Mathf.Approximately(rotationDirection, 0f)
                && !Mathf.Approximately(side, 0f)
                && Mathf.Sign(rotationDirection) == Mathf.Sign(side);
        }

        private static float BuildStraightRunRotationTiltPipOffsetX(
            float rotationDirection,
            float rotationReadiness,
            int pipIndex)
        {
            float side = BuildStraightRunRotationTiltPipSide(pipIndex);
            float distance = BuildStraightRunRotationTiltPipDistance(pipIndex);
            if (Mathf.Approximately(side, 0f))
            {
                return 0f;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            float fan = Mathf.Lerp(0.040f, 0.056f, readiness) * distance;
            float pull = IsStraightRunRotationTiltPipTargetSide(rotationDirection, pipIndex)
                ? readiness * 0.010f * distance
                : -readiness * 0.004f * distance;
            return side * (fan + pull);
        }

        private static float BuildStraightRunRotationTiltPipAnchorY(float rotationReadiness, int pipIndex)
        {
            float readiness = Mathf.Clamp01(rotationReadiness);
            float distance = BuildStraightRunRotationTiltPipDistance(pipIndex);
            return 0.105f + readiness * (0.006f + distance * 0.004f);
        }

        private static float BuildStraightRunRotationTiltPipWidth(
            float rotationDirection,
            float rotationReadiness,
            float downbeatPulse,
            int pipIndex)
        {
            float readiness = Mathf.Clamp01(rotationReadiness);
            float distance = BuildStraightRunRotationTiltPipDistance(pipIndex);
            float targetLift = IsStraightRunRotationTiltPipTargetSide(rotationDirection, pipIndex) ? 1f : 0f;
            float centerLift = Mathf.Approximately(BuildStraightRunRotationTiltPipSide(pipIndex), 0f) ? 0.45f : 0f;
            return 28f
                + distance * 5f
                + readiness * (12f + targetLift * 22f + centerLift * 8f)
                + Mathf.Clamp01(downbeatPulse) * readiness * (targetLift * 9f + centerLift * 4f);
        }

        private static float BuildStraightRunRotationTiltPipHeight(
            float rotationDirection,
            float rotationReadiness,
            float downbeatPulse,
            int pipIndex)
        {
            float readiness = Mathf.Clamp01(rotationReadiness);
            float targetLift = IsStraightRunRotationTiltPipTargetSide(rotationDirection, pipIndex) ? 1f : 0f;
            float centerLift = Mathf.Approximately(BuildStraightRunRotationTiltPipSide(pipIndex), 0f) ? 0.5f : 0f;
            return 5f
                + readiness * (2f + targetLift * 3.2f + centerLift * 1.2f)
                + Mathf.Clamp01(downbeatPulse) * readiness * (targetLift * 1.6f + centerLift * 0.6f);
        }

        private static float BuildStraightRunRotationTiltPipAngle(
            float rotationDirection,
            float rotationReadiness,
            int pipIndex)
        {
            float side = BuildStraightRunRotationTiltPipSide(pipIndex);
            if (Mathf.Approximately(rotationDirection, 0f) || Mathf.Approximately(side, 0f))
            {
                return 0f;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            float targetLift = IsStraightRunRotationTiltPipTargetSide(rotationDirection, pipIndex) ? 1f : 0.34f;
            return Mathf.Sign(rotationDirection) * Mathf.Lerp(3f, 14f, readiness) * targetLift;
        }

        private static int BuildStraightRunRotationTiltPipAlpha(
            bool visible,
            float rotationDirection,
            float rotationReadiness,
            float downbeatPulse,
            int pipIndex)
        {
            if (!visible || Mathf.Approximately(rotationDirection, 0f))
            {
                return 0;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            float side = BuildStraightRunRotationTiltPipSide(pipIndex);
            float targetLift = IsStraightRunRotationTiltPipTargetSide(rotationDirection, pipIndex) ? 1f : 0f;
            float centerLift = Mathf.Approximately(side, 0f) ? 0.52f : 0f;
            float passive = Mathf.Approximately(side, 0f) ? 0f : 0.20f;
            float pulseLift = Mathf.Clamp01(downbeatPulse) * readiness * (targetLift * 38f + centerLift * 12f);
            return Mathf.RoundToInt(readiness * (24f + passive * 36f + centerLift * 44f + targetLift * 98f) + pulseLift);
        }

        private static float BuildStraightRunRotationTiltPipColorBlend(
            float rotationDirection,
            float rotationReadiness,
            int pipIndex)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            float side = BuildStraightRunRotationTiltPipSide(pipIndex);
            if (Mathf.Approximately(side, 0f))
            {
                return Mathf.Clamp01(0.36f + readiness * 0.24f);
            }

            return IsStraightRunRotationTiltPipTargetSide(rotationDirection, pipIndex)
                ? Mathf.Clamp01(0.54f + readiness * 0.46f)
                : Mathf.Clamp01(0.18f + readiness * 0.18f);
        }

        private static float BuildStraightRunRotationNeutralGateReleasePressure(
            bool tiltReady,
            int heldDirection,
            float rotationReadiness,
            float responsePulse)
        {
            if (tiltReady || heldDirection == 0)
            {
                return 0f;
            }

            return Mathf.Clamp01(rotationReadiness) * Mathf.Lerp(1f, 0.48f, Mathf.Clamp01(responsePulse));
        }

        private static float BuildStraightRunRotationNeutralGateOffsetX(
            float rotationDirection,
            float rotationReadiness,
            float releasePressure)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            return Mathf.Sign(rotationDirection) * readiness * Mathf.Lerp(0.010f, 0.002f, Mathf.Clamp01(releasePressure));
        }

        private static float BuildStraightRunRotationNeutralGateAnchorY(float rotationReadiness, float releasePressure)
        {
            return 0.091f
                + Mathf.Clamp01(rotationReadiness) * 0.010f
                + Mathf.Clamp01(releasePressure) * 0.008f;
        }

        private static float BuildStraightRunRotationNeutralGateWidth(
            float rotationReadiness,
            float releasePressure,
            float downbeatPulse)
        {
            float readiness = Mathf.Clamp01(rotationReadiness);
            float release = Mathf.Clamp01(releasePressure);
            return 42f
                + readiness * 28f
                + release * 36f
                + Mathf.Clamp01(downbeatPulse) * readiness * (8f + release * 8f);
        }

        private static float BuildStraightRunRotationNeutralGateHeight(
            float rotationReadiness,
            float releasePressure,
            float downbeatPulse)
        {
            float readiness = Mathf.Clamp01(rotationReadiness);
            float release = Mathf.Clamp01(releasePressure);
            return 5f
                + readiness * 2.2f
                + release * 4.6f
                + Mathf.Clamp01(downbeatPulse) * readiness * (0.8f + release * 1.2f);
        }

        private static float BuildStraightRunRotationNeutralGateAngle(
            float rotationDirection,
            float rotationReadiness,
            float releasePressure)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            return Mathf.Sign(rotationDirection)
                * Mathf.Clamp01(rotationReadiness)
                * Mathf.Lerp(5.2f, 0.8f, Mathf.Clamp01(releasePressure));
        }

        private static int BuildStraightRunRotationNeutralGateAlpha(
            bool visible,
            float rotationDirection,
            float rotationReadiness,
            float releasePressure,
            float downbeatPulse)
        {
            if (!visible || Mathf.Approximately(rotationDirection, 0f))
            {
                return 0;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            float release = Mathf.Clamp01(releasePressure);
            float alpha = readiness * 54f
                + release * 84f
                + Mathf.Clamp01(downbeatPulse) * readiness * (24f + release * 18f);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 156f));
        }

        private static float BuildStraightRunRotationNeutralGateColorBlend(float rotationReadiness, float releasePressure)
        {
            return Mathf.Clamp01(0.24f + Mathf.Clamp01(rotationReadiness) * 0.42f + Mathf.Clamp01(releasePressure) * 0.18f);
        }

        private static float BuildStraightRunRotationInputCursorOffsetX(float inputAxis)
        {
            return Mathf.Clamp(inputAxis, -1.25f, 1.25f) * 0.105f;
        }

        private static float BuildStraightRunRotationInputCursorAnchorY(float rotationReadiness, float candidateProgress)
        {
            return 0.077f
                + Mathf.Clamp01(rotationReadiness) * 0.004f
                + Mathf.Clamp01(candidateProgress) * 0.004f;
        }

        private static float BuildStraightRunRotationInputCursorWidth(float inputAxis, float candidateProgress)
        {
            return 6f
                + Mathf.Abs(Mathf.Clamp(inputAxis, -1.25f, 1.25f)) * 4f
                + Mathf.Clamp01(candidateProgress) * 5f;
        }

        private static float BuildStraightRunRotationInputCursorHeight(float inputAxis, float candidateProgress)
        {
            return 12f
                + Mathf.Abs(Mathf.Clamp(inputAxis, -1.25f, 1.25f)) * 8f
                + Mathf.Clamp01(candidateProgress) * 6f;
        }

        private static float BuildStraightRunRotationInputCursorAngle(float inputAxis, float candidateProgress)
        {
            return -Mathf.Clamp(inputAxis, -1.25f, 1.25f)
                * Mathf.Lerp(5f, 9f, Mathf.Clamp01(candidateProgress));
        }

        private static bool IsStraightRunRotationInputCursorCorrectDirection(
            float rotationDirection,
            float inputAxis,
            int candidateDirection)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return false;
            }

            float inputDirection = candidateDirection != 0
                ? Mathf.Sign(candidateDirection)
                : Mathf.Sign(inputAxis);
            return !Mathf.Approximately(inputDirection, 0f)
                && Mathf.Sign(rotationDirection) == inputDirection;
        }

        private static int BuildStraightRunRotationInputCursorAlpha(
            bool visible,
            float rotationDirection,
            float rotationReadiness,
            float inputAxis,
            float candidateProgress)
        {
            float axisStrength = Mathf.Clamp01(Mathf.Abs(inputAxis));
            if (!visible
                || Mathf.Approximately(rotationDirection, 0f)
                || axisStrength < 0.06f)
            {
                return 0;
            }

            float alpha = Mathf.Clamp01(rotationReadiness) * 84f
                + axisStrength * 34f
                + Mathf.Clamp01(candidateProgress) * 54f;
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 172f));
        }

        private static float BuildStraightRunRotationGripBarSide(int gripIndex)
        {
            return Mathf.Clamp(gripIndex, 0, StraightRunRotationGripBarCount - 1) == 0 ? -1f : 1f;
        }

        private static bool IsStraightRunRotationGripBarTargetSide(float rotationDirection, int gripIndex)
        {
            return !Mathf.Approximately(rotationDirection, 0f)
                && Mathf.Sign(rotationDirection) == Mathf.Sign(BuildStraightRunRotationGripBarSide(gripIndex));
        }

        private static float BuildStraightRunRotationGripBarOffsetX(
            float rotationDirection,
            float rotationReadiness,
            int gripIndex)
        {
            float side = BuildStraightRunRotationGripBarSide(gripIndex);
            float readiness = Mathf.Clamp01(rotationReadiness);
            float targetPull = IsStraightRunRotationGripBarTargetSide(rotationDirection, gripIndex)
                ? readiness * 0.018f
                : -readiness * 0.006f;
            return side * (0.176f + targetPull);
        }

        private static float BuildStraightRunRotationGripBarAnchorY(
            float rotationDirection,
            float rotationReadiness,
            int gripIndex)
        {
            float readiness = Mathf.Clamp01(rotationReadiness);
            return 0.118f
                + readiness * (IsStraightRunRotationGripBarTargetSide(rotationDirection, gripIndex) ? 0.008f : 0.004f);
        }

        private static float BuildStraightRunRotationGripBarWidth(
            float rotationDirection,
            float rotationReadiness,
            float downbeatPulse,
            int gripIndex)
        {
            float readiness = Mathf.Clamp01(rotationReadiness);
            float targetLift = IsStraightRunRotationGripBarTargetSide(rotationDirection, gripIndex) ? 1f : 0f;
            return 7f
                + readiness * (2f + targetLift * 5f)
                + Mathf.Clamp01(downbeatPulse) * readiness * (targetLift * 2.2f + 0.4f);
        }

        private static float BuildStraightRunRotationGripBarHeight(
            float rotationDirection,
            float rotationReadiness,
            float downbeatPulse,
            int gripIndex)
        {
            float readiness = Mathf.Clamp01(rotationReadiness);
            float targetLift = IsStraightRunRotationGripBarTargetSide(rotationDirection, gripIndex) ? 1f : 0f;
            return 38f
                + readiness * (14f + targetLift * 30f)
                + Mathf.Clamp01(downbeatPulse) * readiness * (targetLift * 10f + 2f);
        }

        private static float BuildStraightRunRotationGripBarAngle(
            float rotationDirection,
            float rotationReadiness,
            int gripIndex)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            float side = BuildStraightRunRotationGripBarSide(gripIndex);
            float targetLift = IsStraightRunRotationGripBarTargetSide(rotationDirection, gripIndex) ? 1f : 0.28f;
            return Mathf.Sign(rotationDirection) * Mathf.Lerp(3f, 10f, Mathf.Clamp01(rotationReadiness)) * targetLift
                + side * 1.2f;
        }

        private static int BuildStraightRunRotationGripBarAlpha(
            bool visible,
            float rotationDirection,
            float rotationReadiness,
            float downbeatPulse,
            int gripIndex)
        {
            if (!visible || Mathf.Approximately(rotationDirection, 0f))
            {
                return 0;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            float targetLift = IsStraightRunRotationGripBarTargetSide(rotationDirection, gripIndex) ? 1f : 0f;
            float alpha = readiness * (26f + targetLift * 88f);
            alpha += Mathf.Clamp01(downbeatPulse) * readiness * (targetLift * 28f + 5f);
            return Mathf.RoundToInt(Mathf.Clamp(alpha, 0f, 146f));
        }

        private static float BuildStraightRunRotationGripBarColorBlend(
            float rotationDirection,
            float rotationReadiness,
            int gripIndex)
        {
            if (Mathf.Approximately(rotationDirection, 0f))
            {
                return 0f;
            }

            float readiness = Mathf.Clamp01(rotationReadiness);
            return IsStraightRunRotationGripBarTargetSide(rotationDirection, gripIndex)
                ? Mathf.Clamp01(0.48f + readiness * 0.48f)
                : Mathf.Clamp01(0.14f + readiness * 0.18f);
        }

        private static float BuildFloorBeatTilePhase(
            bool running,
            float beatProgress,
            float stageMotionScale,
            float motionSpeedBias,
            float forwardPulse,
            int tileIndex)
        {
            float indexOffset = Mathf.Clamp(tileIndex, 0, FloorBeatTileCount - 1) / (float)FloorBeatTileCount;
            if (!running)
            {
                return indexOffset;
            }

            float speed = (0.34f + Mathf.Clamp01(forwardPulse) * 0.10f)
                * Mathf.Max(0.1f, stageMotionScale)
                * Mathf.Max(0.1f, motionSpeedBias);
            return Mathf.Repeat(Mathf.Clamp01(beatProgress) * speed + indexOffset, 1f);
        }

        private static float BuildSceneryPillarPhase(
            bool running,
            float beatProgress,
            float stageMotionScale,
            float motionSpeedBias,
            float forwardPulse,
            int depthIndex,
            int depthCount)
        {
            int safeDepthCount = Mathf.Max(1, depthCount);
            float indexOffset = Mathf.Clamp(depthIndex, 0, safeDepthCount - 1) / (float)safeDepthCount;
            if (!running)
            {
                return indexOffset;
            }

            float speed = (0.24f + Mathf.Clamp01(forwardPulse) * 0.07f)
                * Mathf.Max(0.1f, stageMotionScale)
                * Mathf.Max(0.1f, motionSpeedBias);
            return Mathf.Repeat(Mathf.Clamp01(beatProgress) * speed + indexOffset, 1f);
        }

        private static float BuildSceneryPillarDownbeatLift(float downbeatPulse, float phase, int depthIndex, int depthCount)
        {
            int safeDepthCount = Mathf.Max(1, depthCount);
            float indexRatio = safeDepthCount <= 1
                ? 0f
                : Mathf.Clamp(depthIndex, 0, safeDepthCount - 1) / (float)(safeDepthCount - 1);
            float depthWeight = Mathf.Lerp(0.48f, 1f, Mathf.Clamp01(phase));
            float indexWeight = Mathf.Lerp(1f, 0.78f, indexRatio);
            return Mathf.Clamp01(downbeatPulse) * depthWeight * indexWeight;
        }

        private static float BuildSceneryPillarDownbeatSpreadScale(float downbeatLift)
        {
            return 1f + Mathf.Clamp01(downbeatLift) * 0.026f;
        }

        private static float BuildSceneryPillarDownbeatWidthScale(float downbeatLift)
        {
            return 1f + Mathf.Clamp01(downbeatLift) * 0.040f;
        }

        private static float BuildSceneryPillarDownbeatHeightScale(float downbeatLift)
        {
            return 1f + Mathf.Clamp01(downbeatLift) * 0.030f;
        }

        private static int BuildSceneryPillarDownbeatAlphaLift(float downbeatLift)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(downbeatLift) * 18f);
        }

        private static float BuildSceneryPillarDownbeatColorBlend(float downbeatLift)
        {
            return Mathf.Clamp01(downbeatLift) * 0.20f;
        }

        private static float BuildTunnelPillarBeatCueUrgency(float tunnelBeatCueUrgency, float phase, int depthIndex)
        {
            int safeIndex = Mathf.Clamp(depthIndex, 0, 3);
            float indexFalloff = Mathf.Clamp(1f - safeIndex * 0.045f, 0.74f, 1f);
            float depthWeight = Mathf.Lerp(0.54f, 1f, Mathf.Clamp01(phase));
            return Mathf.Clamp01(tunnelBeatCueUrgency) * depthWeight * indexFalloff;
        }

        private static float BuildTunnelPillarBeatCueUrgencySpreadScale(float pillarBeatCueUrgency)
        {
            return 1f + Mathf.Clamp01(pillarBeatCueUrgency) * 0.016f;
        }

        private static float BuildTunnelPillarBeatCueUrgencyWidthScale(float pillarBeatCueUrgency)
        {
            return 1f + Mathf.Clamp01(pillarBeatCueUrgency) * 0.026f;
        }

        private static float BuildTunnelPillarBeatCueUrgencyHeightScale(float pillarBeatCueUrgency)
        {
            return 1f + Mathf.Clamp01(pillarBeatCueUrgency) * 0.018f;
        }

        private static int BuildTunnelPillarBeatCueUrgencyAlphaLift(float pillarBeatCueUrgency)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(pillarBeatCueUrgency) * 8f);
        }

        private static float BuildTunnelPillarBeatCueUrgencyColorBlend(float pillarBeatCueUrgency)
        {
            return Mathf.Clamp01(pillarBeatCueUrgency) * 0.10f;
        }

        private static float BuildFloorBeatTileHalfWidth(float phase, float stageDepthScale, float forwardPulse)
        {
            float width = Mathf.Lerp(0.07f, 0.45f, Mathf.Clamp01(phase));
            return Mathf.Min(0.48f, width * Mathf.Max(0.1f, stageDepthScale) * (1f + Mathf.Clamp01(forwardPulse) * 0.06f));
        }

        private static float BuildFloorBeatTileHeight(float phase, float stageDepthScale, float forwardPulse)
        {
            return Mathf.Lerp(3f, 16f, Mathf.Clamp01(phase))
                * Mathf.Max(0.1f, stageDepthScale)
                * (1f + Mathf.Clamp01(forwardPulse) * 0.22f);
        }

        private static float BuildFloorBeatTileAlpha(
            bool visible,
            bool running,
            float motionStrength,
            float phase,
            float forwardPulse,
            bool focusActive,
            float tilePulse)
        {
            if (!visible)
            {
                return 0f;
            }

            float depth = Mathf.Clamp01(phase);
            float strength = Mathf.Clamp01(motionStrength);
            float baseAlpha = Mathf.Lerp(running ? 18f : 8f, running ? 76f : 28f, depth) * strength;
            float pulseLift = Mathf.Lerp(0.76f, 1.12f, Mathf.Clamp01(tilePulse));
            float payoffLift = 1f + Mathf.Clamp01(forwardPulse) * 0.36f + (focusActive ? 0.18f : 0f);
            return Mathf.Clamp(baseAlpha * pulseLift * payoffLift, 0f, 155f);
        }

        private void HideTimingBands()
        {
            if (goodTimingBand != null)
            {
                goodTimingBand.color = new Color32(105, 168, 190, 0);
                goodTimingBand.rectTransform.localScale = Vector3.one;
            }

            if (successTimingBand != null)
            {
                successTimingBand.color = new Color32(255, 238, 181, 0);
                successTimingBand.rectTransform.localScale = Vector3.one;
            }

            if (centerTimingBand != null)
            {
                centerTimingBand.color = new Color32(255, 248, 210, 0);
                centerTimingBand.rectTransform.localScale = Vector3.one;
            }

            HideTimingBeatPips();
        }

        private void UpdateTimingBeatPips(float channelX)
        {
            if (timingBeatPips == null)
            {
                return;
            }

            float beatInterval = BuildTimingBeatPipInterval(latestRunSnapshot.Pattern, BuildBeatInterval(latestRunSnapshot));
            float exactPulse = BuildExactTimingPulse();
            float downbeatPulse = ShouldShowDownbeatPulse(latestRunSnapshot)
                ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime)
                : 0f;
            float beatCueUrgency = BuildActiveBeatCueUrgency(latestRunSnapshot);
            Color32 baseColor = Color32.Lerp(
                new Color32(218, 226, 218, 255),
                GetTrapAccentColor(latestRunSnapshot.Pattern.TimingType),
                0.42f);
            if (TryGetPatternVariationAccent(latestRunSnapshot.Pattern, out Color32 variationColor, out float variationStrength))
            {
                baseColor = Color32.Lerp(baseColor, variationColor, variationStrength * 0.34f);
            }

            for (int i = 0; i < timingBeatPips.Length; i += 1)
            {
                Image pip = timingBeatPips[i];
                if (pip == null)
                {
                    continue;
                }

                float alpha = BuildTimingBeatPipAlpha(
                    latestRunSnapshot.Pattern,
                    latestRunSnapshot.CoreDeltaSeconds,
                    beatInterval,
                    i);
                if (alpha <= 0f)
                {
                    pip.color = new Color32(255, 238, 181, 0);
                    pip.rectTransform.localScale = Vector3.one;
                    pip.rectTransform.localEulerAngles = Vector3.zero;
                    continue;
                }

                float readiness = BuildTimingBeatPipReadiness(
                    latestRunSnapshot.Pattern,
                    latestRunSnapshot.CoreDeltaSeconds,
                    beatInterval,
                    i);
                float pipBeatPulse = GetGameplayBeatPulse();
                float pipPulse = BuildTimingBeatPipPulse(readiness, exactPulse, pipBeatPulse, i);
                float pipDownbeatLift = BuildTimingBeatPipDownbeatLift(downbeatPulse, readiness, i);
                float pipExactLock = BuildTimingBeatPipExactLock(exactPulse, i);
                float pipBeatCueUrgency = BuildTimingBeatPipBeatCueUrgency(beatCueUrgency, readiness, i);
                Vector4 layout = BuildTimingBeatPipLayoutWithPreview(
                    latestRunSnapshot.Pattern,
                    channelX,
                    beatInterval,
                    i,
                    devTrapVisualPreviewMode);
                RectTransform rect = pip.rectTransform;
                rect.anchorMin = new Vector2(layout.x, layout.y);
                rect.anchorMax = rect.anchorMin;
                rect.anchoredPosition = Vector2.zero;
                rect.sizeDelta = new Vector2(
                    layout.z
                        + BuildTimingBeatPipWidthLift(pipPulse, i)
                        + BuildTimingBeatPipDownbeatWidthLift(pipDownbeatLift, i)
                        + BuildTimingBeatPipBeatCueUrgencyWidthLift(pipBeatCueUrgency, i),
                    layout.w
                        + BuildTimingBeatPipHeightLift(pipPulse, i)
                        + BuildTimingBeatPipDownbeatHeightLift(pipDownbeatLift, i)
                        + BuildTimingBeatPipBeatCueUrgencyHeightLift(pipBeatCueUrgency, i));
                rect.localEulerAngles = new Vector3(0f, 0f, BuildTimingBeatPipAngle(latestRunSnapshot.Pattern));
                float baseScale = BuildTimingBeatPipScale(
                    latestRunSnapshot.Pattern,
                    latestRunSnapshot.CoreDeltaSeconds,
                    beatInterval,
                    i,
                    exactPulse);
                float pipScale = BuildTimingBeatPipScaleWithPulse(baseScale, pipPulse);
                pipScale = BuildTimingBeatPipScaleWithDownbeat(pipScale, pipDownbeatLift);
                rect.localScale = new Vector3(
                    BuildTimingBeatPipScaleXWithExactLock(pipScale, pipExactLock)
                        + BuildTimingBeatPipBeatCueUrgencyScaleXLift(pipBeatCueUrgency),
                    BuildTimingBeatPipScaleYWithExactLock(pipScale, pipExactLock)
                        + BuildTimingBeatPipBeatCueUrgencyScaleYLift(pipBeatCueUrgency),
                    1f);
                Color32 pipColor = baseColor;
                if (pipDownbeatLift > 0f)
                {
                    pipColor = Color32.Lerp(pipColor, new Color32(255, 214, 105, 255), BuildDownbeatColorBlend(pipDownbeatLift, 0.26f));
                }
                if (pipBeatCueUrgency > 0f)
                {
                    pipColor = Color32.Lerp(
                        pipColor,
                        new Color32(255, 238, 181, 255),
                        BuildTimingBeatPipBeatCueUrgencyColorBlend(pipBeatCueUrgency));
                }

                pip.color = WithAlpha(
                    pipColor,
                    Mathf.RoundToInt(
                        BuildTimingBeatPipAlphaWithBeatCueUrgency(
                            BuildTimingBeatPipAlphaWithExactLock(
                                BuildTimingBeatPipAlphaWithDownbeat(
                                    BuildTimingBeatPipAlphaWithPulse(alpha, pipPulse),
                                    pipDownbeatLift),
                                pipExactLock),
                            pipBeatCueUrgency)
                        * 255f));
            }
        }

        private void HideTimingBeatPips()
        {
            if (timingBeatPips == null)
            {
                return;
            }

            for (int i = 0; i < timingBeatPips.Length; i += 1)
            {
                if (timingBeatPips[i] == null)
                {
                    continue;
                }

                timingBeatPips[i].color = new Color32(255, 238, 181, 0);
                timingBeatPips[i].rectTransform.localScale = Vector3.one;
                timingBeatPips[i].rectTransform.localEulerAngles = Vector3.zero;
            }
        }

        private static float BuildTimingBeatPipInterval(GreedLastPatternModel pattern, float beatIntervalSeconds)
        {
            if (!pattern.IsValid)
            {
                return Mathf.Max(0.12f, beatIntervalSeconds);
            }

            float authoredInterval = Mathf.Max(0.12f, beatIntervalSeconds);
            float fitInterval = Mathf.Max(0.12f, pattern.CoreSeconds / (TimingBeatPipCount + 0.35f));
            return Mathf.Min(authoredInterval, fitInterval);
        }

        private static Vector4 BuildTimingBeatPipLayout(
            GreedLastPatternModel pattern,
            float channelX,
            float beatIntervalSeconds,
            int pipIndex)
        {
            return BuildTimingBeatPipLayoutWithPreview(pattern, channelX, beatIntervalSeconds, pipIndex, 0);
        }

        private static Vector4 BuildTimingBeatPipLayoutWithPreview(
            GreedLastPatternModel pattern,
            float channelX,
            float beatIntervalSeconds,
            int pipIndex,
            int previewMode)
        {
            int safeIndex = Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1);
            float interval = BuildTimingBeatPipInterval(pattern, beatIntervalSeconds);
            float hitSeconds = Mathf.Max(0.01f, pattern.HitSeconds);
            float sampleSeconds = Mathf.Max(0f, pattern.CoreSeconds - interval * (safeIndex + 1));
            float linearProgress = Mathf.Clamp01(sampleSeconds / hitSeconds);
            float coreProgress = Mathf.Clamp01(pattern.CoreSeconds / hitSeconds);
            float visualProgress = BuildTrapVisualProgress(pattern.TimingType, linearProgress, coreProgress);
            visualProgress = BuildTrapVisualPreviewProgress(visualProgress, coreProgress, previewMode, true);
            float x = Mathf.Clamp01(
                channelX
                    + BuildTrapVisualHorizontalOffset(pattern.TimingType, linearProgress, coreProgress)
                    + BuildTrapApproachSweepX(pattern, visualProgress));
            float y = Mathf.Lerp(BuildTrapApproachStartY(pattern), 0.18f, visualProgress);
            float emphasis = Mathf.Clamp01(1f - safeIndex * 0.24f);
            float width = Mathf.Lerp(72f, 126f, emphasis);
            float height = Mathf.Lerp(5f, 9f, emphasis);

            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    width *= 1.18f;
                    height *= 0.82f;
                    break;
                case RunnerResponseType.Slide:
                    width *= 1.04f;
                    height *= 1.16f;
                    break;
                case RunnerResponseType.Twist:
                    width *= 0.54f;
                    height *= 2.05f;
                    break;
            }

            return new Vector4(x, y, width, height);
        }

        private static float BuildTimingBeatPipAlpha(
            GreedLastPatternModel pattern,
            float coreDeltaSeconds,
            float beatIntervalSeconds,
            int pipIndex)
        {
            if (!pattern.IsValid)
            {
                return 0f;
            }

            int safeIndex = Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1);
            float interval = BuildTimingBeatPipInterval(pattern, beatIntervalSeconds);
            float leadSeconds = interval * (safeIndex + 1);
            if (pattern.CoreSeconds - leadSeconds <= 0.02f || coreDeltaSeconds > pattern.GoodWindowSeconds)
            {
                return 0f;
            }

            float secondsUntilCore = Mathf.Max(0f, -coreDeltaSeconds);
            float passedFade = secondsUntilCore < leadSeconds
                ? Mathf.Clamp01(secondsUntilCore / Mathf.Max(0.01f, leadSeconds))
                : 1f;
            float nearThisPip = BuildTimingBeatPipReadiness(pattern, coreDeltaSeconds, interval, safeIndex);
            float baseAlpha = 0.54f - safeIndex * 0.085f;
            return Mathf.Clamp01(baseAlpha * Mathf.Lerp(0.58f, 1.16f, nearThisPip) * Mathf.Lerp(0.28f, 1f, passedFade));
        }

        private static float BuildTimingBeatPipScale(
            GreedLastPatternModel pattern,
            float coreDeltaSeconds,
            float beatIntervalSeconds,
            int pipIndex,
            float exactPulse)
        {
            if (!pattern.IsValid)
            {
                return 1f;
            }

            int safeIndex = Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1);
            float readiness = BuildTimingBeatPipReadiness(pattern, coreDeltaSeconds, beatIntervalSeconds, safeIndex);
            float indexDamping = Mathf.Lerp(0.055f, 0.02f, Mathf.Clamp01(safeIndex / 2f));
            float nearScale = Mathf.Lerp(0.16f, 0.07f, Mathf.Clamp01(safeIndex / 2f));
            return 1f
                + Mathf.Clamp01(exactPulse) * indexDamping
                + readiness * nearScale;
        }

        private static float BuildTimingBeatPipPulse(float readiness, float exactPulse, float beatPulse, int pipIndex)
        {
            float indexDamping = Mathf.Lerp(1f, 0.62f, Mathf.Clamp01(Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1) / 2f));
            float pulse = Mathf.Clamp01(readiness) * Mathf.Lerp(0.34f, 1f, Mathf.Clamp01(beatPulse));
            return Mathf.Clamp01((pulse + Mathf.Clamp01(exactPulse) * 0.55f) * indexDamping);
        }

        private static float BuildTimingBeatPipAlphaWithPulse(float baseAlpha, float pipPulse)
        {
            return Mathf.Clamp01(Mathf.Clamp01(baseAlpha) + Mathf.Clamp01(pipPulse) * 0.14f);
        }

        private static float BuildTimingBeatPipScaleWithPulse(float baseScale, float pipPulse)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(pipPulse) * 0.035f;
        }

        private static float BuildTimingBeatPipDownbeatLift(float downbeatPulse, float readiness, int pipIndex)
        {
            float indexDamping = Mathf.Lerp(1f, 0.54f, Mathf.Clamp01(Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1) / 2f));
            float readinessLift = Mathf.Lerp(0.46f, 1f, Mathf.Clamp01(readiness));
            return Mathf.Clamp01(downbeatPulse) * readinessLift * indexDamping;
        }

        private static float BuildTimingBeatPipAlphaWithDownbeat(float baseAlpha, float downbeatLift)
        {
            return Mathf.Clamp01(Mathf.Clamp01(baseAlpha) + Mathf.Clamp01(downbeatLift) * 0.065f);
        }

        private static float BuildTimingBeatPipScaleWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.018f;
        }

        private static float BuildTimingBeatPipExactLock(float exactPulse, int pipIndex)
        {
            float indexDamping = Mathf.Lerp(1f, 0.48f, Mathf.Clamp01(Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1) / 2f));
            return Mathf.Clamp01(exactPulse) * indexDamping;
        }

        private static float BuildTimingBeatPipAlphaWithExactLock(float baseAlpha, float pipExactLock)
        {
            return Mathf.Clamp01(Mathf.Clamp01(baseAlpha) + Mathf.Clamp01(pipExactLock) * 0.060f);
        }

        private static float BuildTimingBeatPipScaleXWithExactLock(float baseScale, float pipExactLock)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(pipExactLock) * 0.006f;
        }

        private static float BuildTimingBeatPipScaleYWithExactLock(float baseScale, float pipExactLock)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(pipExactLock) * 0.028f;
        }

        private static float BuildTimingBeatPipWidthLift(float pipPulse, int pipIndex)
        {
            float indexDamping = Mathf.Lerp(1f, 0.58f, Mathf.Clamp01(Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1) / 2f));
            return Mathf.Clamp01(pipPulse) * Mathf.Lerp(18f, 8f, 1f - indexDamping);
        }

        private static float BuildTimingBeatPipHeightLift(float pipPulse, int pipIndex)
        {
            float indexDamping = Mathf.Lerp(1f, 0.58f, Mathf.Clamp01(Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1) / 2f));
            return Mathf.Clamp01(pipPulse) * Mathf.Lerp(3.6f, 1.4f, 1f - indexDamping);
        }

        private static float BuildTimingBeatPipDownbeatWidthLift(float downbeatLift, int pipIndex)
        {
            float indexDamping = Mathf.Lerp(1f, 0.56f, Mathf.Clamp01(Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1) / 2f));
            return Mathf.Clamp01(downbeatLift) * Mathf.Lerp(9f, 3.4f, 1f - indexDamping);
        }

        private static float BuildTimingBeatPipDownbeatHeightLift(float downbeatLift, int pipIndex)
        {
            float indexDamping = Mathf.Lerp(1f, 0.56f, Mathf.Clamp01(Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1) / 2f));
            return Mathf.Clamp01(downbeatLift) * Mathf.Lerp(2.6f, 1.0f, 1f - indexDamping);
        }

        private static float BuildTimingBeatPipBeatCueUrgency(float beatCueUrgency, float readiness, int pipIndex)
        {
            float indexDamping = Mathf.Lerp(1f, 0.42f, Mathf.Clamp01(Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1) / 2f));
            float readinessLift = Mathf.Lerp(0.54f, 1f, Mathf.Clamp01(readiness));
            return Mathf.Clamp01(beatCueUrgency) * readinessLift * indexDamping;
        }

        private static float BuildTimingBeatPipAlphaWithBeatCueUrgency(float baseAlpha, float pipBeatCueUrgency)
        {
            return Mathf.Clamp01(Mathf.Clamp01(baseAlpha) + Mathf.Clamp01(pipBeatCueUrgency) * 0.045f);
        }

        private static float BuildTimingBeatPipBeatCueUrgencyColorBlend(float pipBeatCueUrgency)
        {
            return Mathf.Clamp01(pipBeatCueUrgency) * 0.11f;
        }

        private static float BuildTimingBeatPipBeatCueUrgencyScaleXLift(float pipBeatCueUrgency)
        {
            return Mathf.Clamp01(pipBeatCueUrgency) * 0.004f;
        }

        private static float BuildTimingBeatPipBeatCueUrgencyScaleYLift(float pipBeatCueUrgency)
        {
            return Mathf.Clamp01(pipBeatCueUrgency) * 0.018f;
        }

        private static float BuildTimingBeatPipBeatCueUrgencyWidthLift(float pipBeatCueUrgency, int pipIndex)
        {
            float indexDamping = Mathf.Lerp(1f, 0.50f, Mathf.Clamp01(Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1) / 2f));
            return Mathf.Clamp01(pipBeatCueUrgency) * Mathf.Lerp(6.0f, 2.0f, 1f - indexDamping);
        }

        private static float BuildTimingBeatPipBeatCueUrgencyHeightLift(float pipBeatCueUrgency, int pipIndex)
        {
            float indexDamping = Mathf.Lerp(1f, 0.50f, Mathf.Clamp01(Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1) / 2f));
            return Mathf.Clamp01(pipBeatCueUrgency) * Mathf.Lerp(2.0f, 0.7f, 1f - indexDamping);
        }

        private static float BuildTimingBeatPipReadiness(
            GreedLastPatternModel pattern,
            float coreDeltaSeconds,
            float beatIntervalSeconds,
            int pipIndex)
        {
            if (!pattern.IsValid)
            {
                return 0f;
            }

            int safeIndex = Mathf.Clamp(pipIndex, 0, TimingBeatPipCount - 1);
            float interval = BuildTimingBeatPipInterval(pattern, beatIntervalSeconds);
            float leadSeconds = interval * (safeIndex + 1);
            if (pattern.CoreSeconds - leadSeconds <= 0.02f || coreDeltaSeconds > pattern.GoodWindowSeconds)
            {
                return 0f;
            }

            float secondsUntilCore = Mathf.Max(0f, -coreDeltaSeconds);
            return Mathf.Clamp01(1f - Mathf.Abs(secondsUntilCore - leadSeconds) / Mathf.Max(0.01f, interval * 0.78f));
        }

        private static float BuildTimingBeatPipAngle(GreedLastPatternModel pattern)
        {
            if (BuildRunnerResponseType(pattern) != RunnerResponseType.Twist)
            {
                return 0f;
            }

            return pattern.Channel == GreedLastRunChannel.Left ? -22f : 22f;
        }

        private void UpdateInputTimingTrace()
        {
            if (inputTimingTraceMarker == null)
            {
                return;
            }

            float remaining = inputTimingTraceUntil - Time.unscaledTime;
            if (remaining <= 0f || !CanShowRunTransientFeedback())
            {
                HideInputTimingTrace();
                return;
            }

            float normalized = Mathf.Clamp01(remaining / InputTimingTraceDuration);
            RectTransform traceRect = inputTimingTraceMarker.rectTransform;
            Vector4 traceLayout = BuildInputTimingTraceMarkerLayout(
                inputTimingTraceResult,
                inputTimingTraceSignedDeltaSeconds,
                normalized);
            float resultIntensity = BuildInputTimingTraceResultIntensity(
                inputTimingTraceResult,
                inputTimingTraceSignedDeltaSeconds);
            traceRect.anchorMin = new Vector2(inputTimingTraceX, inputTimingTraceY);
            traceRect.anchorMax = new Vector2(inputTimingTraceX, inputTimingTraceY);
            traceRect.sizeDelta = new Vector2(
                traceLayout.x * BuildInputTimingTraceMarkerWidthScale(inputTimingTraceResult, resultIntensity),
                traceLayout.y * BuildInputTimingTraceMarkerHeightScale(inputTimingTraceResult, resultIntensity));
            traceRect.anchoredPosition = new Vector2(0f, traceLayout.z);
            traceRect.localEulerAngles = new Vector3(0f, 0f, traceLayout.w);
            traceRect.localScale = Vector3.one;
            Color32 color = BuildInputTimingTraceResultColor(
                inputTimingTraceColor,
                inputTimingTraceResult,
                resultIntensity);
            color.a = (byte)Mathf.RoundToInt(
                BuildInputTimingTraceAlphaWithResult(
                    Mathf.Lerp(0f, inputTimingTraceColor.a / 255f, normalized),
                    resultIntensity)
                    * 255f);
            inputTimingTraceMarker.color = color;
            if (inputTimingTraceText != null)
            {
                Color32 labelColor = color;
                labelColor.a = (byte)Mathf.RoundToInt(
                    BuildInputTimingTraceLabelAlphaWithResult(
                        BuildInputTimingTraceLabelAlpha(remaining),
                        resultIntensity)
                        * 255f);
                inputTimingTraceText.color = labelColor;
                inputTimingTraceText.rectTransform.localScale = Vector3.one
                    * BuildInputTimingTraceLabelScaleWithResult(normalized, resultIntensity);
            }
        }

        private void HideInputTimingTrace()
        {
            if (inputTimingTraceMarker != null)
            {
                inputTimingTraceMarker.color = new Color32(255, 238, 181, 0);
                inputTimingTraceMarker.rectTransform.sizeDelta = new Vector2(88f, 18f);
                inputTimingTraceMarker.rectTransform.anchoredPosition = Vector2.zero;
                inputTimingTraceMarker.rectTransform.localEulerAngles = Vector3.zero;
                inputTimingTraceMarker.rectTransform.localScale = Vector3.one;
            }

            inputTimingTraceSignedDeltaSeconds = 0f;
            inputTimingTraceResult = GreedLastJudgementResult.None;

            if (inputTimingTraceText != null)
            {
                inputTimingTraceText.text = string.Empty;
                inputTimingTraceText.color = new Color32(255, 238, 181, 0);
                inputTimingTraceText.rectTransform.localScale = Vector3.one;
            }
        }

        private void SetJudgementLineY(float y)
        {
            RectTransform lineRect = judgementLine.rectTransform;
            lineRect.anchorMin = new Vector2(0.08f, y);
            lineRect.anchorMax = new Vector2(0.92f, y);
            lineRect.anchoredPosition = Vector2.zero;
        }

        private static float GetChannelAnchorX(GreedLastRunChannel channel)
        {
            switch (channel)
            {
                case GreedLastRunChannel.Left:
                    return 0.2f;
                case GreedLastRunChannel.Center:
                    return 0.5f;
                case GreedLastRunChannel.Right:
                    return 0.8f;
                default:
                    return 0.5f;
            }
        }

        private void SetTimingBand(Image band, float windowSeconds, float channelX, bool focusedLaneOnly)
        {
            if (band == null)
            {
                return;
            }

            GreedLastPatternModel pattern = latestRunSnapshot.Pattern;
            float hitSeconds = Mathf.Max(0.01f, pattern.HitSeconds);
            float startProgress = Mathf.Clamp01((pattern.CoreSeconds - windowSeconds) / hitSeconds);
            float endProgress = Mathf.Clamp01((pattern.CoreSeconds + windowSeconds) / hitSeconds);
            float yA = Mathf.Lerp(0.88f, 0.18f, startProgress);
            float yB = Mathf.Lerp(0.88f, 0.18f, endProgress);
            RectTransform rect = band.rectTransform;
            float exactPulse = band == successTimingBand ? BuildExactTimingPulse() : 0f;
            float readiness = BuildTrapReadinessAtmosphereStrength(latestRunSnapshot);
            float successLock = band == successTimingBand ? BuildSuccessTimingBandExactLock(exactPulse, readiness) : 0f;
            bool exactBand = band == successTimingBand;
            float downbeatLift = BuildTimingBandDownbeatLift(
                ShouldShowDownbeatPulse(latestRunSnapshot) ? BuildDownbeatPulse(downbeatPulseUntil - Time.unscaledTime) : 0f,
                readiness,
                exactBand);
            float laneHalfWidth = focusedLaneOnly
                ? BuildSuccessTimingBandLaneHalfWidth(exactPulse, readiness)
                : 0f;
            float minX = focusedLaneOnly ? Mathf.Clamp01(channelX - laneHalfWidth) : 0.08f;
            float maxX = focusedLaneOnly ? Mathf.Clamp01(channelX + laneHalfWidth) : 0.92f;
            rect.anchorMin = new Vector2(minX, Mathf.Min(yA, yB));
            rect.anchorMax = new Vector2(maxX, Mathf.Max(yA, yB));
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;
            if (exactBand)
            {
                Color32 successColor = Color32.Lerp(
                    new Color32(255, 238, 181, 255),
                    new Color32(255, 248, 210, 255),
                    BuildSuccessTimingBandExactLockColorBlend(successLock));
                if (downbeatLift > 0f)
                {
                    successColor = Color32.Lerp(successColor, new Color32(255, 214, 105, 255), BuildTimingBandDownbeatColorBlend(downbeatLift, exactBand));
                }

                successColor.a = (byte)Mathf.Clamp(
                    BuildSuccessTimingBandAlpha(exactPulse, readiness)
                        + BuildSuccessTimingBandExactLockAlphaLift(successLock)
                        + BuildTimingBandDownbeatAlphaLift(downbeatLift, exactBand),
                    0,
                    255);
                band.color = successColor;
            }
            else
            {
                Color32 goodColor = new Color32(105, 168, 190, 255);
                if (downbeatLift > 0f)
                {
                    goodColor = Color32.Lerp(goodColor, new Color32(255, 214, 105, 255), BuildTimingBandDownbeatColorBlend(downbeatLift, exactBand));
                }

                goodColor.a = (byte)Mathf.Clamp(
                    BuildGoodTimingBandAlpha(readiness)
                        + BuildTimingBandDownbeatAlphaLift(downbeatLift, exactBand),
                    0,
                    255);
                band.color = goodColor;
            }

            float bandScale = BuildTimingBandScale(exactPulse, readiness, focusedLaneOnly);
            bandScale = BuildTimingBandScaleWithDownbeat(bandScale, downbeatLift);
            band.rectTransform.localScale = new Vector3(
                BuildTimingBandScaleXWithExactLock(bandScale, successLock),
                BuildTimingBandScaleYWithExactLock(bandScale, successLock)
                    + BuildTimingBandDownbeatScaleYLift(downbeatLift, exactBand),
                1f);
        }

        private void SetCenterTimingBand(float channelX)
        {
            if (centerTimingBand == null)
            {
                return;
            }

            GreedLastPatternModel pattern = latestRunSnapshot.Pattern;
            float hitSeconds = Mathf.Max(0.01f, pattern.HitSeconds);
            float windowSeconds = BuildCenterHitWindow(pattern);
            float startProgress = Mathf.Clamp01((pattern.CoreSeconds - windowSeconds) / hitSeconds);
            float endProgress = Mathf.Clamp01((pattern.CoreSeconds + windowSeconds) / hitSeconds);
            float yA = Mathf.Lerp(0.88f, 0.18f, startProgress);
            float yB = Mathf.Lerp(0.88f, 0.18f, endProgress);
            RectTransform rect = centerTimingBand.rectTransform;
            rect.anchorMin = new Vector2(Mathf.Clamp01(channelX - 0.062f), Mathf.Min(yA, yB));
            rect.anchorMax = new Vector2(Mathf.Clamp01(channelX + 0.062f), Mathf.Max(yA, yB));
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;

            float exactPulse = BuildExactTimingPulse();
            float centerLock = BuildCenterTimingBandExactLock(exactPulse);
            centerTimingBand.color = new Color32(
                255,
                248,
                210,
                (byte)Mathf.Clamp(
                    Mathf.RoundToInt(Mathf.Lerp(98f, 220f, exactPulse))
                        + BuildCenterTimingBandExactLockAlphaLift(centerLock),
                    0,
                    255));
            float centerScale = BuildCenterTimingBandScale(exactPulse);
            centerTimingBand.rectTransform.localScale = new Vector3(
                BuildCenterTimingBandScaleXWithExactLock(centerScale, centerLock),
                BuildCenterTimingBandScaleYWithExactLock(centerScale, centerLock),
                1f);
        }

        private static float BuildSuccessTimingBandLaneHalfWidth(float exactPulse, float readiness)
        {
            return Mathf.Lerp(0.095f, 0.122f, Mathf.Clamp01(readiness)) + Mathf.Clamp01(exactPulse) * 0.012f;
        }

        private static int BuildGoodTimingBandAlpha(float readiness)
        {
            return Mathf.RoundToInt(Mathf.Lerp(28f, 48f, Mathf.Clamp01(readiness)));
        }

        private static int BuildSuccessTimingBandAlpha(float exactPulse, float readiness)
        {
            return Mathf.RoundToInt(116f + Mathf.Clamp01(readiness) * 28f + Mathf.Clamp01(exactPulse) * 76f);
        }

        private static float BuildSuccessTimingBandExactLock(float exactPulse, float readiness)
        {
            float exactStrength = Mathf.Clamp01(exactPulse);
            if (exactStrength <= 0f)
            {
                return 0f;
            }

            return Mathf.Clamp01(exactStrength * (0.74f + Mathf.Clamp01(readiness) * 0.26f));
        }

        private static int BuildSuccessTimingBandExactLockAlphaLift(float exactLock)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(exactLock) * 22f);
        }

        private static float BuildSuccessTimingBandExactLockColorBlend(float exactLock)
        {
            return Mathf.Clamp01(exactLock) * 0.26f;
        }

        private static float BuildTimingBandScale(float exactPulse, float readiness, bool focusedLaneOnly)
        {
            float focusLift = focusedLaneOnly ? Mathf.Clamp01(readiness) * 0.018f : Mathf.Clamp01(readiness) * 0.010f;
            return 1f + focusLift + Mathf.Clamp01(exactPulse) * 0.045f;
        }

        private static float BuildTimingBandDownbeatLift(float downbeatPulse, float readiness, bool exactBand)
        {
            float bandWeight = exactBand ? 1f : 0.62f;
            float readinessWeight = Mathf.Lerp(0.45f, 1f, Mathf.Clamp01(readiness));
            return Mathf.Clamp01(downbeatPulse) * readinessWeight * bandWeight;
        }

        private static int BuildTimingBandDownbeatAlphaLift(float downbeatLift, bool exactBand)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(downbeatLift) * (exactBand ? 18f : 10f));
        }

        private static float BuildTimingBandDownbeatColorBlend(float downbeatLift, bool exactBand)
        {
            return Mathf.Clamp01(downbeatLift) * (exactBand ? 0.18f : 0.10f);
        }

        private static float BuildTimingBandScaleWithDownbeat(float baseScale, float downbeatLift)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(downbeatLift) * 0.010f;
        }

        private static float BuildTimingBandDownbeatScaleYLift(float downbeatLift, bool exactBand)
        {
            return Mathf.Clamp01(downbeatLift) * (exactBand ? 0.026f : 0.014f);
        }

        private static float BuildTimingBandScaleXWithExactLock(float baseScale, float exactLock)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(exactLock) * 0.012f;
        }

        private static float BuildTimingBandScaleYWithExactLock(float baseScale, float exactLock)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(exactLock) * 0.074f;
        }

        private static float BuildCenterTimingBandScale(float exactPulse)
        {
            return 1f + Mathf.Clamp01(exactPulse) * 0.08f;
        }

        private static float BuildCenterTimingBandExactLock(float exactPulse)
        {
            return Mathf.Clamp01((Mathf.Clamp01(exactPulse) - 0.18f) / 0.82f);
        }

        private static int BuildCenterTimingBandExactLockAlphaLift(float centerLock)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(centerLock) * 18f);
        }

        private static float BuildCenterTimingBandScaleXWithExactLock(float baseScale, float centerLock)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(centerLock) * 0.010f;
        }

        private static float BuildCenterTimingBandScaleYWithExactLock(float baseScale, float centerLock)
        {
            return Mathf.Max(0.1f, baseScale) + Mathf.Clamp01(centerLock) * 0.064f;
        }

        private void PlayLaneCue(GreedLastRunChannel channel)
        {
            PlayLaneCue(channel, LaneCueVolume);
        }

        private void PlayLaneCue(GreedLastRunChannel channel, float volume)
        {
            if (laneCueClips == null)
            {
                return;
            }

            int index = (int)channel - 1;
            if (index >= 0 && index < laneCueClips.Length)
            {
                PlayClip(laneCueClips[index], Mathf.Clamp(volume, 0f, MaxSfxVolume));
            }
        }

        private static float BuildTrapEntryLaneCueVolume(
            bool firstRunEntryTrap,
            bool practiceMode,
            bool infiniteMode,
            int infiniteThreatLevel)
        {
            if (!firstRunEntryTrap)
            {
                return LaneCueVolume;
            }

            float volume = LaneCueVolume + (practiceMode ? 0.025f : 0.035f);
            if (infiniteMode)
            {
                volume += Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.015f;
            }

            return Mathf.Min(volume, 0.29f);
        }

        private void PlayRunnerResponseCue(GreedLastPatternModel pattern)
        {
            float volume = latestRunSnapshot.Phase == GreedLastRunPhase.EscapeRunning ? 0.18f : 0.14f;
            PlayRunnerResponseCue(pattern, volume);
        }

        private void PlayRunnerResponseCue(GreedLastPatternModel pattern, float volume)
        {
            AudioClip clip;
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    clip = jumpActionCueClip;
                    break;
                case RunnerResponseType.Slide:
                    clip = slideActionCueClip;
                    break;
                case RunnerResponseType.Twist:
                    clip = twistActionCueClip;
                    break;
                default:
                    clip = null;
                    break;
            }

            if (clip != null)
            {
                PlayClip(clip, Mathf.Clamp(volume, 0f, MaxSfxVolume));
            }
        }

        private static float BuildTargetActionCueVolume(GreedLastRunSnapshot snapshot)
        {
            float baseVolume = snapshot.Phase == GreedLastRunPhase.EscapeRunning
                ? TargetActionCueVolume + 0.035f
                : TargetActionCueVolume;
            baseVolume += BuildTargetActionPayoffCueVolumeBonus(snapshot);
            if (snapshot.InfiniteMode)
            {
                baseVolume += Mathf.Clamp01((snapshot.InfiniteThreatLevel - 1) / 4f) * 0.035f;
            }

            return Mathf.Min(baseVolume, 0.18f);
        }

        private static float BuildTargetActionPayoffCueVolumeBonus(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ActivePattern || !snapshot.Pattern.IsValid)
            {
                return 0f;
            }

            float bonus;
            if (IsRecoveryPattern(snapshot.Pattern))
            {
                bonus = 0.016f;
            }
            else
            {
                switch (snapshot.Pattern.TimingType)
                {
                    case GreedLastTimingType.Clutch:
                    case GreedLastTimingType.Offbeat:
                        bonus = 0.014f;
                        break;
                    case GreedLastTimingType.Perfect:
                        bonus = 0.008f;
                        break;
                    default:
                        bonus = 0f;
                        break;
                }
            }

            if (PatternHasRoute(snapshot.Pattern, "변주") || PatternHasRoute(snapshot.Pattern, "압박"))
            {
                bonus += 0.006f;
            }

            return bonus;
        }

        private AudioClip GetTimingCueClip(GreedLastTimingType timingType)
        {
            switch (timingType)
            {
                case GreedLastTimingType.Clutch:
                    return clutchCueClip;
                case GreedLastTimingType.Offbeat:
                    return offbeatCueClip;
                case GreedLastTimingType.Perfect:
                    return perfectCueClip;
                default:
                    return perfectCueClip;
            }
        }

        private static float BuildTimingCueVolume(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.InfiniteMode)
            {
                return TargetCueVolume;
            }

            return Mathf.Lerp(TargetCueVolume, 0.36f, Mathf.Clamp01((snapshot.InfiniteThreatLevel - 1) / 4f));
        }

        private void PlayVariationTimingCue(GreedLastRunSnapshot snapshot)
        {
            AudioClip clip = GetVariationCueClip(snapshot.Pattern);
            if (clip == null)
            {
                return;
            }

            PlayClip(clip, BuildVariationCueVolume(snapshot));
        }

        private AudioClip GetVariationCueClip(GreedLastPatternModel pattern)
        {
            string prompt = pattern.Prompt ?? string.Empty;
            if (prompt.Contains("[안정]", StringComparison.Ordinal)
                || prompt.Contains("[복구]", StringComparison.Ordinal)
                || prompt.Contains("[유예]", StringComparison.Ordinal))
            {
                return variationBreatherClip;
            }

            if (prompt.Contains("[탈출]", StringComparison.Ordinal)
                || prompt.Contains("[위기]", StringComparison.Ordinal)
                || prompt.Contains("[압박]", StringComparison.Ordinal)
                || prompt.Contains("[심층]", StringComparison.Ordinal)
                || prompt.Contains("[급박]", StringComparison.Ordinal))
            {
                return variationTensionClip;
            }

            if (prompt.Contains("[변주]", StringComparison.Ordinal)
                || prompt.Contains("[정밀]", StringComparison.Ordinal)
                || prompt.Contains("[연쇄]", StringComparison.Ordinal))
            {
                return variationPrecisionClip;
            }

            return null;
        }

        private static float BuildVariationCueVolume(GreedLastRunSnapshot snapshot)
        {
            float pressure = Mathf.Max(0f, BuildTrapVariationPressure(snapshot.Pattern));
            float baseVolume = snapshot.InfiniteMode
                ? Mathf.Lerp(0.14f, 0.24f, Mathf.Clamp01((snapshot.InfiniteThreatLevel - 1) / 4f))
                : 0.16f;
            return Mathf.Clamp(baseVolume + pressure * 0.16f, 0.12f, 0.32f);
        }

        private void PlayJudgementFeedback(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.TimingRecommendationSampleCount <= 0)
            {
                lastTimingRecommendationReady = false;
            }

            int judgementCount = snapshot.SuccessCount + snapshot.GoodCount + snapshot.MissCount;
            bool newResult = snapshot.LastResult != GreedLastJudgementResult.None
                && judgementCount > lastFeedbackJudgementCount;
            lastFeedbackJudgementCount = judgementCount;

            if (!newResult)
            {
                return;
            }

            bool timingRecommendationJustReady = snapshot.HasTimingRecommendation && !lastTimingRecommendationReady;
            if (snapshot.HasTimingRecommendation)
            {
                lastTimingRecommendationReady = true;
            }

            bool reviewTargetAchievementJustReached = !reviewTargetAchievementAnnounced
                && IsReviewTargetAchievementSnapshot(snapshot);
            if (reviewTargetAchievementJustReached)
            {
                reviewTargetAchievementAnnounced = true;
            }

            TriggerRunnerResponse(snapshot);
            TriggerResolvedTrapAfterimage(snapshot);
            TriggerForwardPayoffBurst(snapshot);
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            bool feedbackPatternValid = feedbackPattern.IsValid;
            bool bundleCompleted = snapshot.JudgementText.Contains("패턴 묶음 완벽", StringComparison.Ordinal);
            bool profileBonusFeedback = HasChoiceProfileScoreBonus(snapshot);
            switch (snapshot.LastResult)
            {
                case GreedLastJudgementResult.Success:
                    PlayClip(successClip, BuildJudgementCueVolume(snapshot));
                    beatMarkerSuccessPulseUntil = Time.unscaledTime + BeatMarkerSuccessPulseDuration;
                    comboBadgePulseUntil = Time.unscaledTime + 0.22f;
                    bool tierFeedback = false;
                    bool centerHitFeedback = snapshot.LastCenterHit && snapshot.PrecisionStreak >= 2;
                    bool recoveryFeedback = snapshot.LastCenterHit && feedbackPatternValid && IsRecoveryPattern(feedbackPattern);
                    bool perfectFocusFeedback = snapshot.LastCenterHit
                        && feedbackPatternValid
                        && feedbackPattern.TimingType == GreedLastTimingType.Perfect;
                    bool clutchCounterFeedback = snapshot.LastCenterHit
                        && feedbackPatternValid
                        && feedbackPattern.TimingType == GreedLastTimingType.Clutch;
                    bool offbeatFlowFeedback = snapshot.LastCenterHit
                        && feedbackPatternValid
                        && feedbackPattern.TimingType == GreedLastTimingType.Offbeat;
                    bool variationRouteFeedback = offbeatFlowFeedback
                        && JudgementTextContains(snapshot, "변주 루트 - 엇박 공명");
                    bool pressureRouteFeedback = clutchCounterFeedback
                        && JudgementTextContains(snapshot, "압박 루트 - 클러치 증폭");
                    if (recoveryFeedback)
                    {
                        PlayClip(recoveryClip, 0.46f);
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, 0.045f, false));
                    }
                    else if (pressureRouteFeedback)
                    {
                        PlayClip(threatUpClip, 0.42f);
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, BuildRoutePayoffHapticDuration("압박 루트", reviewTargetAchievementJustReached), false));
                    }
                    else if (variationRouteFeedback)
                    {
                        PlayClip(focusBeatClip, 0.36f);
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, BuildRoutePayoffHapticDuration("변주 루트", reviewTargetAchievementJustReached), false));
                    }
                    else if (perfectFocusFeedback)
                    {
                        PlayClip(focusBeatClip, 0.30f);
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, 0.030f, false));
                    }
                    else if (clutchCounterFeedback)
                    {
                        PlayClip(variationPrecisionClip, 0.36f);
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, 0.035f, false));
                    }
                    else if (offbeatFlowFeedback)
                    {
                        PlayClip(chainClip, 0.32f);
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, 0.032f, false));
                    }

                    if (profileBonusFeedback)
                    {
                        beatMarkerProfilePulseUntil = Time.unscaledTime + BeatMarkerProfilePulseDuration;
                    }

                    if (snapshot.Combo >= 3)
                    {
                        if (comboTierFeedbackPending)
                        {
                            PlayClip(comboTierClip, 0.38f);
                            PlayHaptic(BuildJudgementHapticDuration(snapshot, reviewTargetAchievementJustReached ? 0.055f : 0.045f, false));
                            comboTierFeedbackPending = false;
                            tierFeedback = true;
                        }
                        else
                        {
                            PlayClip(chainClip, Mathf.Lerp(0.24f, 0.40f, Mathf.Clamp01(snapshot.Combo / 15f)));
                            PlayHaptic(BuildJudgementHapticDuration(snapshot, reviewTargetAchievementJustReached ? 0.05f : 0.035f, false));
                        }
                    }
                    else
                    {
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, 0.018f, reviewTargetAchievementJustReached));
                    }

                    if (centerHitFeedback
                        && !tierFeedback
                        && !recoveryFeedback
                        && !perfectFocusFeedback
                        && !clutchCounterFeedback
                        && !offbeatFlowFeedback)
                    {
                        PlayClip(chainClip, Mathf.Lerp(0.18f, 0.30f, Mathf.Clamp01(snapshot.PrecisionStreak / 9f)));
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, 0.03f, false));
                    }

                    Color32 successFlashColor;
                    float successFlashDuration;
                    if (recoveryFeedback)
                    {
                        successFlashColor = new Color32(145, 231, 199, 112);
                        successFlashDuration = 0.18f;
                    }
                    else if (pressureRouteFeedback)
                    {
                        successFlashColor = new Color32(238, 151, 76, 126);
                        successFlashDuration = 0.20f;
                    }
                    else if (variationRouteFeedback)
                    {
                        successFlashColor = new Color32(181, 146, 226, 122);
                        successFlashDuration = 0.19f;
                    }
                    else if (perfectFocusFeedback)
                    {
                        successFlashColor = new Color32(255, 238, 181, 108);
                        successFlashDuration = 0.16f;
                    }
                    else if (clutchCounterFeedback)
                    {
                        successFlashColor = new Color32(226, 137, 70, 110);
                        successFlashDuration = 0.17f;
                    }
                    else if (offbeatFlowFeedback)
                    {
                        successFlashColor = new Color32(181, 146, 226, 108);
                        successFlashDuration = 0.165f;
                    }
                    else if (tierFeedback)
                    {
                        successFlashColor = new Color32(255, 214, 105, 112);
                        successFlashDuration = 0.16f;
                    }
                    else if (centerHitFeedback)
                    {
                        successFlashColor = new Color32(255, 248, 210, 104);
                        successFlashDuration = 0.145f;
                    }
                    else
                    {
                        successFlashColor = new Color32(255, 238, 181, 90);
                        successFlashDuration = 0.12f;
                    }

                    if (profileBonusFeedback)
                    {
                        successFlashColor = Color32.Lerp(successFlashColor, GetChoiceProfilePulseColor(snapshot.ActiveChoiceProfile), 0.36f);
                    }

                    float successRewardPulse = BuildComboBadgeRewardPulse(
                        BuildComboBadgeRewardReadiness(
                            snapshot.PrecisionStreak,
                            snapshot.Combo,
                            snapshot.Stopped,
                            snapshot.Paused,
                            snapshot.CountdownActive,
                            snapshot.ChoiceActive),
                        centerHitFeedback,
                        tierFeedback,
                        false);
                    successFlashColor = BuildColorWithAlphaLift(
                        successFlashColor,
                        BuildComboBadgeRewardFlashAlphaLift(successRewardPulse),
                        150);
                    successFlashDuration += BuildComboBadgeRewardFlashDurationLift(successRewardPulse);
                    StartFeedbackFlash(
                        successFlashColor,
                        Mathf.Max(
                            successFlashDuration,
                            profileBonusFeedback ? 0.14f : 0f));
                    break;
                case GreedLastJudgementResult.Good:
                    comboTierFeedbackPending = false;
                    bool focusFlowFeedback = snapshot.FocusStateActive;
                    bool stableRouteFeedback = JudgementTextContains(snapshot, "안정 루트 - 보정 회복");
                    if (stableRouteFeedback)
                    {
                        PlayClip(recoveryClip, 0.38f);
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, BuildRoutePayoffHapticDuration("안정 루트", reviewTargetAchievementJustReached), false));
                        beatMarkerGoodPulseUntil = Time.unscaledTime + BeatMarkerGoodPulseDuration;
                        StartFeedbackFlash(new Color32(145, 231, 199, 104), 0.16f);
                    }
                    else if (focusFlowFeedback)
                    {
                        PlayClip(focusBeatClip, 0.26f);
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, 0.024f, reviewTargetAchievementJustReached));
                        beatMarkerGoodPulseUntil = Time.unscaledTime + BeatMarkerGoodPulseDuration;
                        StartFeedbackFlash(new Color32(255, 196, 74, 76), 0.12f);
                    }
                    else
                    {
                        PlayClip(goodClip, BuildJudgementCueVolume(snapshot));
                        PlayHaptic(BuildJudgementHapticDuration(snapshot, 0.012f, reviewTargetAchievementJustReached));
                        beatMarkerGoodPulseUntil = Time.unscaledTime + BeatMarkerGoodPulseDuration;
                        StartFeedbackFlash(new Color32(105, 168, 190, 75), 0.10f);
                    }

                    if (profileBonusFeedback)
                    {
                        beatMarkerProfilePulseUntil = Time.unscaledTime + BeatMarkerProfilePulseDuration;
                        ExtendFeedbackFlash(
                            Color32.Lerp(feedbackFlashBaseColor, GetChoiceProfilePulseColor(snapshot.ActiveChoiceProfile), focusFlowFeedback ? 0.24f : 0.36f),
                            0.13f);
                    }

                    break;
                case GreedLastJudgementResult.Miss:
                    comboTierFeedbackPending = false;
                    PlayClip(missClip, BuildJudgementCueVolume(snapshot));
                    PlayHaptic(BuildJudgementHapticDuration(snapshot, BuildMissHapticDuration(feedbackPattern), false));
                    StartFeedbackFlash(new Color32(180, 42, 36, 95), 0.16f);
                    break;
            }

            if (reviewTargetAchievementJustReached)
            {
                beatMarkerProfilePulseUntil = Time.unscaledTime + BeatMarkerProfilePulseDuration;
                ExtendFeedbackFlash(new Color32(145, 231, 199, 118), 0.20f);
            }

            TriggerLaneJudgementPulse(snapshot);
            TriggerJudgementLinePulse(snapshot);
            TriggerRhythmBreakLine(snapshot);
            TriggerInputTimingTrace(snapshot);
            RecordJudgementHistory(snapshot);
            if (bundleCompleted)
            {
                TriggerPatternBundleFeedback(snapshot);
            }

            if (timingRecommendationJustReady)
            {
                PlayClip(comboTierClip, 0.28f);
                PlayHaptic(0.025f);
            }

            ShowJudgementFeedback(snapshot, timingRecommendationJustReady, reviewTargetAchievementJustReached);
        }

        private void TriggerForwardPayoffBurst(GreedLastRunSnapshot snapshot)
        {
            float strength = BuildForwardPayoffBurstStrength(snapshot);
            if (strength <= 0f)
            {
                return;
            }

            forwardPayoffBurstStrength = Mathf.Max(forwardPayoffBurstStrength * 0.35f, strength);
            forwardPayoffBurstUntil = Time.unscaledTime + ForwardPayoffBurstDuration;
        }

        private static float BuildForwardPayoffBurstStrength(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.LastResult == GreedLastJudgementResult.None
                || snapshot.LastResult == GreedLastJudgementResult.Miss
                || snapshot.Stopped)
            {
                return 0f;
            }

            float strength = snapshot.LastResult == GreedLastJudgementResult.Success ? 0.62f : 0.34f;
            if (snapshot.LastCenterHit)
            {
                strength += 0.14f;
            }

            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (feedbackPattern.IsValid)
            {
                strength += Mathf.Max(0f, BuildTrapVariationPressure(feedbackPattern)) * 0.18f;
            }

            strength += Mathf.Clamp01(snapshot.Combo / 12f) * 0.18f;
            if (snapshot.FocusStateActive)
            {
                strength += 0.08f;
            }

            if (snapshot.InfiniteMode)
            {
                strength += Mathf.Clamp01((snapshot.InfiniteThreatLevel - 1) / 4f) * 0.06f;
            }

            if (snapshot.Phase == GreedLastRunPhase.EscapeRunning)
            {
                strength += 0.08f;
            }

            return Mathf.Clamp01(strength);
        }

        private static float BuildForwardPayoffBurstPulse(float remainingSeconds, float strength)
        {
            if (remainingSeconds <= 0f || strength <= 0f)
            {
                return 0f;
            }

            float normalized = Mathf.Clamp01(remainingSeconds / ForwardPayoffBurstDuration);
            float snapFade = normalized * normalized;
            float beatLift = 0.72f + Mathf.Sin(normalized * Mathf.PI) * 0.28f;
            return Mathf.Clamp01(strength * snapFade * beatLift);
        }

        private void TriggerResolvedTrapAfterimage(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (!feedbackPattern.IsValid)
            {
                return;
            }

            resolvedTrapPattern = feedbackPattern;
            resolvedTrapResult = snapshot.LastResult;
            resolvedTrapStartedAt = Time.unscaledTime;
            float duration = snapshot.LastResult == GreedLastJudgementResult.Miss
                ? ResolvedTrapMissDuration
                : snapshot.LastResult == GreedLastJudgementResult.Good
                    ? ResolvedTrapGoodDuration
                    : ResolvedTrapSuccessDuration;
            resolvedTrapUntil = resolvedTrapStartedAt + duration;
            Color32 baseColor = GetTrapAccentColor(feedbackPattern.TimingType);
            resolvedTrapColor = snapshot.LastResult == GreedLastJudgementResult.Good
                ? Color32.Lerp(baseColor, new Color32(105, 168, 190, 255), 0.56f)
                : Color32.Lerp(baseColor, GetJudgementPulseColor(snapshot), 0.48f);
        }

        private void TriggerPatternBundleFeedback(GreedLastRunSnapshot snapshot)
        {
            bool stableBundle = JudgementTextContains(snapshot, "안정 완주");
            bool variationBundle = JudgementTextContains(snapshot, "변주 완주");
            bool pressureBundle = JudgementTextContains(snapshot, "압박 완주");
            bool threeActionExact = JudgementTextContains(snapshot, "3동작 정확");
            Color32 bundleColor;
            if (stableBundle)
            {
                PlayClip(recoveryClip, 0.46f);
                bundleColor = new Color32(145, 231, 199, 132);
            }
            else if (variationBundle)
            {
                PlayClip(focusBeatClip, 0.40f);
                bundleColor = new Color32(181, 146, 226, 132);
            }
            else if (pressureBundle)
            {
                PlayClip(threatUpClip, 0.46f);
                bundleColor = new Color32(238, 151, 76, 138);
            }
            else
            {
                bundleColor = new Color32(255, 214, 105, 126);
            }

            string bundleLabel = BuildPatternBundleBannerLabel(snapshot);
            bool routeBundle = stableBundle || variationBundle || pressureBundle;
            PlayClip(bundleCompleteClip, BuildPatternBundleCompletionVolume(routeBundle, threeActionExact));
            PlayHaptic(BuildPatternBundleCompletionHapticDuration(stableBundle, variationBundle, pressureBundle, threeActionExact));
            judgementHistoryPulseUntil = Time.unscaledTime + BuildPatternBundleHistoryPulseDuration(threeActionExact);
            beatMarkerComboTierPulseUntil = Time.unscaledTime + BeatMarkerComboTierPulseDuration;
            ExtendFeedbackFlash(bundleColor, BuildPatternBundleFeedbackFlashDuration(threeActionExact));
            if (threeActionExact)
            {
                TriggerThreeActionExactBurst(snapshot);
            }

            if (stageTransitionText != null)
            {
                stageTransitionCuePending = false;
                stageTransitionText.text = bundleLabel;
                stageTransitionColor = WithAlpha(bundleColor, 255);
                stageTransitionStartedAt = Time.unscaledTime;
                stageTransitionUntil = stageTransitionStartedAt + 1.05f;
            }
        }

        private void TriggerThreeActionExactBurst(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (!feedbackPattern.IsValid || feedbackPattern.Channel == GreedLastRunChannel.None)
            {
                return;
            }

            threeActionExactBurstUntil = Time.unscaledTime + ThreeActionExactBurstDuration;
            threeActionExactBurstX = BuildRunChannelAnchorX(feedbackPattern.Channel);
            threeActionExactBurstY = judgementLine != null
                ? Mathf.Clamp01(judgementLine.rectTransform.anchorMin.y + 0.012f)
                : 0.22f;
        }

        private static string BuildPatternBundleBannerLabel(GreedLastRunSnapshot snapshot)
        {
            string label = JudgementTextContains(snapshot, "안정 완주")
                ? "안정 완주"
                : JudgementTextContains(snapshot, "변주 완주")
                    ? "변주 완주"
                    : JudgementTextContains(snapshot, "압박 완주")
                        ? "압박 완주"
                        : "3 패턴 완벽";
            return JudgementTextContains(snapshot, "3동작 정확")
                ? label + " · 3동작 정확"
                : label;
        }

        private static float BuildPatternBundleCompletionVolume(bool routeBundle, bool threeActionExact)
        {
            float baseVolume = routeBundle ? 0.36f : 0.52f;
            return threeActionExact ? baseVolume + 0.08f : baseVolume;
        }

        private static float BuildPatternBundleCompletionHapticDuration(
            bool stableBundle,
            bool variationBundle,
            bool pressureBundle,
            bool threeActionExact)
        {
            float baseDuration = pressureBundle ? 0.080f : variationBundle ? 0.070f : 0.065f;
            return threeActionExact ? baseDuration + 0.012f : baseDuration;
        }

        private static float BuildPatternBundleHistoryPulseDuration(bool threeActionExact)
        {
            return threeActionExact ? 0.62f : 0.48f;
        }

        private static float BuildPatternBundleFeedbackFlashDuration(bool threeActionExact)
        {
            return threeActionExact ? 0.30f : 0.24f;
        }

        private void TriggerRunnerResponse(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (!feedbackPattern.IsValid)
            {
                return;
            }

            runnerResponseType = BuildRunnerResponseType(feedbackPattern);
            runnerResponseChannel = feedbackPattern.Channel;
            runnerResponseWasRotationPattern = GreedLastRunCore.IsRotationPattern(feedbackPattern);
            if (snapshot.MissReason == "wrong_channel"
                && snapshot.LastJudgedInputChannel != GreedLastRunChannel.None)
            {
                runnerResponseChannel = snapshot.LastJudgedInputChannel;
            }

            runnerResponseResult = snapshot.LastResult;
            runnerResponseStartedAt = Time.unscaledTime;
            float duration = snapshot.LastResult == GreedLastJudgementResult.Miss
                ? RunnerMissResponseDuration
                : snapshot.LastResult == GreedLastJudgementResult.Good
                    ? RunnerGoodResponseDuration
                    : RunnerSuccessResponseDuration;
            runnerResponseUntil = runnerResponseStartedAt + duration;
            runnerResponseColor = snapshot.FocusStateActive && snapshot.LastResult != GreedLastJudgementResult.Miss
                ? Color32.Lerp(GetJudgementPulseColor(snapshot), new Color32(255, 214, 105, 255), 0.58f)
                : GetJudgementPulseColor(snapshot);
        }

        private void TriggerLaneJudgementPulse(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (laneJudgementPulseUntil == null
                || laneJudgementPulseColors == null
                || feedbackPattern.Channel == GreedLastRunChannel.None)
            {
                return;
            }

            if (snapshot.MissReason == "wrong_channel"
                && snapshot.LastJudgedInputChannel != GreedLastRunChannel.None)
            {
                ArmLaneJudgementPulse(
                    snapshot.LastJudgedInputChannel,
                    GreedLastJudgementResult.Miss,
                    new Color32(231, 91, 77, 245),
                    true,
                    BuildLaneJudgementTagLabel(GreedLastJudgementResult.Miss, false));
                ArmLaneJudgementPulse(
                    feedbackPattern.Channel,
                    GreedLastJudgementResult.None,
                    new Color32(255, 238, 181, 225),
                    false,
                    BuildLaneJudgementTagLabel(GreedLastJudgementResult.Miss, true));
                beatMarkerMissImpactUntil = Time.unscaledTime + BeatMarkerMissImpactDuration;
                return;
            }

            Color32 pulseColor = HasChoiceProfileScoreBonus(snapshot) && snapshot.LastResult != GreedLastJudgementResult.Miss
                ? Color32.Lerp(GetJudgementPulseColor(snapshot), GetChoiceProfilePulseColor(snapshot.ActiveChoiceProfile), 0.42f)
                : GetJudgementPulseColor(snapshot);
            ArmLaneJudgementPulse(
                feedbackPattern.Channel,
                snapshot.LastResult,
                pulseColor,
                snapshot.LastResult == GreedLastJudgementResult.Miss,
                BuildLaneJudgementTagLabel(snapshot.LastResult, false));
        }

        private void ArmLaneJudgementPulse(
            GreedLastRunChannel channel,
            GreedLastJudgementResult result,
            Color32 pulseColor,
            bool shake,
            string tagLabel)
        {
            int index = (int)channel - 1;
            if (index < 0 || index >= laneJudgementPulseUntil.Length)
            {
                return;
            }

            laneJudgementPulseUntil[index] = Time.unscaledTime + 0.24f;
            laneJudgementPulseColors[index] = pulseColor;
            if (!string.IsNullOrEmpty(tagLabel)
                && laneJudgementTagTexts != null
                && laneJudgementTagUntil != null
                && laneJudgementTagColors != null
                && laneJudgementTagResults != null
                && index < laneJudgementTagTexts.Length
                && index < laneJudgementTagUntil.Length
                && index < laneJudgementTagColors.Length
                && index < laneJudgementTagResults.Length
                && laneJudgementTagTexts[index] != null)
            {
                laneJudgementTagTexts[index].text = tagLabel;
                laneJudgementTagUntil[index] = Time.unscaledTime + LaneJudgementTagDuration;
                laneJudgementTagColors[index] = pulseColor;
                laneJudgementTagResults[index] = result;
            }

            if (shake && laneMissShakeUntil != null && index < laneMissShakeUntil.Length)
            {
                laneMissShakeUntil[index] = Time.unscaledTime + LaneMissShakeDuration;
                beatMarkerMissImpactUntil = Time.unscaledTime + BeatMarkerMissImpactDuration;
            }
        }

        private static string BuildLaneJudgementTagLabel(GreedLastJudgementResult result, bool targetLane)
        {
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return "정확";
                case GreedLastJudgementResult.Good:
                    return "Good";
                case GreedLastJudgementResult.Miss:
                    return targetLane ? "정답" : "Miss";
                default:
                    return string.Empty;
            }
        }

        private void TriggerJudgementLinePulse(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.LastResult == GreedLastJudgementResult.None)
            {
                return;
            }

            judgementLinePulseUntil = Time.unscaledTime + JudgementLinePulseDuration;
            judgementLinePulseStrength = BuildJudgementLinePulseStrength(snapshot.LastResult);
            judgementLinePulseColor = HasChoiceProfileScoreBonus(snapshot) && snapshot.LastResult != GreedLastJudgementResult.Miss
                ? Color32.Lerp(GetJudgementPulseColor(snapshot), GetChoiceProfilePulseColor(snapshot.ActiveChoiceProfile), 0.54f)
                : GetJudgementPulseColor(snapshot);
        }

        private void TriggerRhythmBreakLine(GreedLastRunSnapshot snapshot)
        {
            if (rhythmBreakLine == null || snapshot.LastResult != GreedLastJudgementResult.Miss)
            {
                return;
            }

            float lineY = 0.22f;
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (feedbackPattern.IsValid)
            {
                float hitSeconds = Mathf.Max(0.01f, feedbackPattern.HitSeconds);
                float coreProgress = Mathf.Clamp01(feedbackPattern.CoreSeconds / hitSeconds);
                lineY = Mathf.Lerp(0.88f, 0.18f, coreProgress);
            }

            rhythmBreakLineY = Mathf.Clamp01(lineY);
            rhythmBreakLineStrength = BuildRhythmBreakLineComboStrength(Mathf.Max(comboBreakBadgeCombo, snapshot.MaxCombo));
            rhythmBreakLineUntil = Time.unscaledTime + RhythmBreakLineDuration;
            UpdateRhythmBreakLine();
        }

        private void TriggerInputTimingTrace(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (inputTimingTraceMarker == null
                || feedbackPattern.Channel == GreedLastRunChannel.None
                || !snapshot.HasJudgedInputTiming)
            {
                return;
            }

            float signedDeltaSeconds = snapshot.LastInputTimingDeltaSeconds;
            float hitSeconds = Mathf.Max(0.01f, feedbackPattern.HitSeconds);
            float coreProgress = Mathf.Clamp01(feedbackPattern.CoreSeconds / hitSeconds);
            float coreY = Mathf.Lerp(0.88f, 0.18f, coreProgress);
            GreedLastRunChannel traceChannel = snapshot.LastJudgedInputChannel != GreedLastRunChannel.None
                ? snapshot.LastJudgedInputChannel : feedbackPattern.Channel;
            inputTimingTraceX = GetChannelAnchorX(traceChannel);
            inputTimingTraceY = Mathf.Clamp(coreY - signedDeltaSeconds / hitSeconds * 0.70f, 0.18f, 0.88f);
            inputTimingTraceSignedDeltaSeconds = signedDeltaSeconds;
            inputTimingTraceResult = snapshot.LastResult;
            inputTimingTraceColor = WithAlpha(GetJudgementFeedbackColor(snapshot), 225);
            inputTimingTraceUntil = Time.unscaledTime + InputTimingTraceDuration;
            if (inputTimingTraceText != null)
            {
                inputTimingTraceText.text = BuildInputTimingTraceLabel(snapshot, signedDeltaSeconds);
                inputTimingTraceText.transform.SetAsLastSibling();
            }

            inputTimingTraceMarker.transform.SetAsLastSibling();
        }

        private static string BuildInputTimingTraceLabel(GreedLastRunSnapshot snapshot, float signedDeltaSeconds)
        {
            if (snapshot.MissReason == "wrong_channel")
            {
                return "오입력";
            }

            int milliseconds = Mathf.RoundToInt(Mathf.Abs(signedDeltaSeconds) * 1000f);
            if (milliseconds <= 0)
            {
                return snapshot.LastResult == GreedLastJudgementResult.Success ? "정확" : string.Empty;
            }

            return signedDeltaSeconds < 0f ? "빠름 " + milliseconds + "ms" : "늦음 " + milliseconds + "ms";
        }

        private static float BuildInputTimingTraceLabelAlpha(float remainingSeconds)
        {
            if (remainingSeconds <= 0f)
            {
                return 0f;
            }

            return Mathf.Clamp01(remainingSeconds / InputTimingTraceDuration);
        }

        private static float BuildInputTimingTraceLabelScale(float normalized)
        {
            return Mathf.Lerp(0.92f, 1.10f, Mathf.Clamp01(normalized));
        }

        private static float BuildInputTimingTraceResultIntensity(
            GreedLastJudgementResult result,
            float signedDeltaSeconds)
        {
            float deltaStrength = Mathf.Clamp01(Mathf.Abs(signedDeltaSeconds) / 0.16f);
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return Mathf.Lerp(1f, 0.90f, deltaStrength);
                case GreedLastJudgementResult.Good:
                    return 0.64f + deltaStrength * 0.12f;
                case GreedLastJudgementResult.Miss:
                    return 0.86f + deltaStrength * 0.14f;
                default:
                    return 0f;
            }
        }

        private static float BuildInputTimingTraceAlphaWithResult(float baseAlpha, float resultIntensity)
        {
            return Mathf.Clamp01(Mathf.Clamp01(baseAlpha) + Mathf.Clamp01(resultIntensity) * 0.055f);
        }

        private static float BuildInputTimingTraceLabelAlphaWithResult(float baseAlpha, float resultIntensity)
        {
            return Mathf.Clamp01(Mathf.Clamp01(baseAlpha) + Mathf.Clamp01(resultIntensity) * 0.045f);
        }

        private static float BuildInputTimingTraceLabelScaleWithResult(float normalized, float resultIntensity)
        {
            return BuildInputTimingTraceLabelScale(normalized) + Mathf.Clamp01(resultIntensity) * 0.040f;
        }

        private static float BuildInputTimingTraceMarkerWidthScale(
            GreedLastJudgementResult result,
            float resultIntensity)
        {
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return 1f + Mathf.Clamp01(resultIntensity) * 0.040f;
                case GreedLastJudgementResult.Good:
                    return 1f + Mathf.Clamp01(resultIntensity) * 0.016f;
                case GreedLastJudgementResult.Miss:
                    return 1f - Mathf.Clamp01(resultIntensity) * 0.030f;
                default:
                    return 1f;
            }
        }

        private static float BuildInputTimingTraceMarkerHeightScale(
            GreedLastJudgementResult result,
            float resultIntensity)
        {
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return 1f + Mathf.Clamp01(resultIntensity) * 0.030f;
                case GreedLastJudgementResult.Good:
                    return 1f + Mathf.Clamp01(resultIntensity) * 0.024f;
                case GreedLastJudgementResult.Miss:
                    return 1f + Mathf.Clamp01(resultIntensity) * 0.090f;
                default:
                    return 1f;
            }
        }

        private static Color32 BuildInputTimingTraceResultColor(
            Color32 baseColor,
            GreedLastJudgementResult result,
            float resultIntensity)
        {
            float strength = Mathf.Clamp01(resultIntensity);
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return Color32.Lerp(baseColor, new Color32(255, 248, 210, baseColor.a), strength * 0.28f);
                case GreedLastJudgementResult.Good:
                    return Color32.Lerp(baseColor, new Color32(105, 168, 190, baseColor.a), strength * 0.20f);
                case GreedLastJudgementResult.Miss:
                    return Color32.Lerp(baseColor, new Color32(231, 91, 77, baseColor.a), strength * 0.32f);
                default:
                    return baseColor;
            }
        }

        private static Vector4 BuildInputTimingTraceMarkerLayout(
            GreedLastJudgementResult result,
            float signedDeltaSeconds,
            float normalized)
        {
            float safeNormalized = Mathf.Clamp01(normalized);
            float ageScale = Mathf.Lerp(0.74f, 1.08f, safeNormalized);
            float absoluteDelta = Mathf.Abs(signedDeltaSeconds);
            float direction = signedDeltaSeconds > 0.001f ? 1f : signedDeltaSeconds < -0.001f ? -1f : 0f;
            float directionStrength = Mathf.Clamp01(absoluteDelta / 0.16f);
            bool exact = result == GreedLastJudgementResult.Success && absoluteDelta <= 0.025f;
            bool miss = result == GreedLastJudgementResult.Miss;

            float width = exact ? 116f : miss ? 92f : Mathf.Lerp(82f, 112f, directionStrength);
            float height = exact ? 14f : miss ? 25f : Mathf.Lerp(13f, 20f, directionStrength);
            float offsetY = -direction * Mathf.Lerp(0f, 11f, directionStrength);
            float angle = direction * Mathf.Lerp(0f, 10f, directionStrength);
            if (miss)
            {
                angle = direction == 0f ? -15f : direction * 14f;
            }

            return new Vector4(width * ageScale, height * ageScale, offsetY, angle);
        }

        private void ShowJudgementFeedback(
            GreedLastRunSnapshot snapshot,
            bool timingRecommendationJustReady,
            bool reviewTargetAchievementJustReached)
        {
            if (judgementFeedbackText == null)
            {
                return;
            }

            lastPresentedJudgementSnapshot = snapshot;
            lastPresentedJudgementRecommendationReady = timingRecommendationJustReady;
            SetJudgementFeedbackText(snapshot);
            judgementFeedbackOffsetX = BuildJudgementFeedbackLaneOffsetX(
                snapshot.Pattern.Channel,
                snapshot.LastResult,
                reviewTargetAchievementJustReached);
            ApplyJudgementFeedbackOffset(1f);
            judgementFeedbackText.color = GetJudgementFeedbackColor(snapshot);
            judgementFeedbackUntil = Time.unscaledTime + 0.82f;
            judgementFeedbackPopScale = BuildJudgementFeedbackPopScale(
                snapshot.LastResult,
                reviewTargetAchievementJustReached);
            judgementFeedbackPopDuration = BuildJudgementFeedbackPopDuration(
                snapshot.LastResult,
                reviewTargetAchievementJustReached);
            judgementFeedbackPopUntil = Time.unscaledTime + judgementFeedbackPopDuration;
        }

        private void SetJudgementFeedbackText(GreedLastRunSnapshot snapshot)
        {
            bool compact = UsePlayerRunControls;
            string text = compact
                ? BuildCompactJudgementFeedbackText(snapshot, DevToolsEnabled, IsRuntimeRotationTiltAvailable())
                : BuildJudgementFeedbackText(snapshot);
            if (!compact && lastPresentedJudgementRecommendationReady)
                text += (CountTextLines(text) >= 3 ? " · " : "\n")
                    + "보정 추천 준비 " + FormatTimingRecommendation(snapshot);
            SetAnchored(judgementFeedbackText.rectTransform, 0.5f, 0.42f, 1100f, 124f);
            if (compact)
            {
                judgementFeedbackText.fontSize = snapshot.LastResult == GreedLastJudgementResult.Miss ? 36 : 40;
            }
            else judgementFeedbackText.fontSize = CountTextLines(text) >= 3 ? 26 : 32;
            judgementFeedbackText.text = text;
            // Fit diagnostic copy without letting its pop animation enter the gauges below.
            if (!compact)
                while (judgementFeedbackText.fontSize > 18 && !FeedbackTextFitsBounds(judgementFeedbackText))
                    judgementFeedbackText.fontSize -= 2;
        }

        private static bool FeedbackTextFitsBounds(Text label)
        {
            Rect rect = label.rectTransform.rect;
            if (label.preferredHeight > rect.height - 2f) return false;
            TextGenerator generator = label.cachedTextGenerator;
            generator.Populate(label.text, label.GetGenerationSettings(rect.size));
            IList<UIVertex> vertices = generator.verts;
            float pixelsPerUnit = label.pixelsPerUnit;
            for (int i = 0; i < vertices.Count; i++)
            {
                Vector3 point = vertices[i].position / pixelsPerUnit;
                if (point.x < rect.xMin + 2f || point.x > rect.xMax - 2f
                    || point.y < rect.yMin + 2f || point.y > rect.yMax - 2f) return false;
            }
            return true;
        }

        private void ShowDevTrapVisualPreviewFeedback()
        {
            if (judgementFeedbackText == null || !CanShowRunTransientFeedback())
            {
                return;
            }

            string feedbackText = BuildDevTrapVisualPreviewFeedbackText(devTrapVisualPreviewMode);
            lastPresentedJudgementSnapshot = default;
            lastPresentedJudgementRecommendationReady = false;
            ApplyJudgementFeedbackLayout(feedbackText);
            judgementFeedbackOffsetX = 0f;
            ApplyJudgementFeedbackOffset(1f);
            judgementFeedbackText.text = feedbackText;
            judgementFeedbackText.color = new Color32(255, 238, 181, 225);
            judgementFeedbackUntil = Time.unscaledTime + 0.82f;
            judgementFeedbackPopScale = 0.10f;
            judgementFeedbackPopDuration = 0.20f;
            judgementFeedbackPopUntil = Time.unscaledTime + judgementFeedbackPopDuration;
        }

        private void ShowResumeCountdownFeedback(GreedLastRunSnapshot snapshot)
        {
            if (judgementFeedbackText == null)
            {
                return;
            }

            judgementFeedbackText.fontSize = 104;
            lastPresentedJudgementSnapshot = default;
            lastPresentedJudgementRecommendationReady = false;
            // Leave room for the largest GO pulse above the health/focus gauges.
            SetAnchored(judgementFeedbackText.rectTransform, 0.5f, 0.44f, 850f, 160f);
            judgementFeedbackOffsetX = 0f;
            judgementFeedbackPopUntil = 0f;
            judgementFeedbackText.text = BuildResumeCountdownFeedbackText(snapshot);
            judgementFeedbackText.color = BuildResumeCountdownFeedbackColor(snapshot);
            judgementFeedbackText.rectTransform.localScale = Vector3.one * BuildResumeCountdownFeedbackScale(snapshot);
            judgementFeedbackUntil = Time.unscaledTime + 0.12f;
        }

        private void ApplyJudgementFeedbackLayout(string feedbackText)
        {
            int lineCount = CountTextLines(feedbackText);
            if (lineCount >= 3)
            {
                judgementFeedbackText.fontSize = 34;
                SetAnchored(judgementFeedbackText.rectTransform, 0.5f, 0.39f, 900f, 164f);
                return;
            }

            if (lineCount >= 2)
            {
                judgementFeedbackText.fontSize = 40;
                SetAnchored(judgementFeedbackText.rectTransform, 0.5f, 0.385f, 850f, 138f);
                return;
            }

            judgementFeedbackText.fontSize = 48;
            SetAnchored(judgementFeedbackText.rectTransform, 0.5f, 0.385f, 850f, 126f);
        }

        private void ApplyJudgementFeedbackOffset(float popRatio)
        {
            if (judgementFeedbackText == null)
            {
                return;
            }

            RectTransform rect = judgementFeedbackText.rectTransform;
            Vector2 position = rect.anchoredPosition;
            position.x = BuildJudgementFeedbackAnimatedOffsetX(judgementFeedbackOffsetX, popRatio);
            rect.anchoredPosition = position;
        }

        private static float BuildJudgementFeedbackLaneOffsetX(
            GreedLastRunChannel channel,
            GreedLastJudgementResult result,
            bool emphasized)
        {
            if (result == GreedLastJudgementResult.None)
            {
                return 0f;
            }

            float direction = BuildRunChannelDirection(channel);
            if (Mathf.Approximately(direction, 0f))
            {
                return 0f;
            }

            float distance;
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    distance = 38f;
                    break;
                case GreedLastJudgementResult.Good:
                    distance = 32f;
                    break;
                case GreedLastJudgementResult.Miss:
                    distance = 46f;
                    break;
                default:
                    distance = 0f;
                    break;
            }

            if (emphasized)
            {
                distance += 8f;
            }

            return direction * distance;
        }

        private static float BuildJudgementFeedbackAnimatedOffsetX(float baseOffsetX, float popRatio)
        {
            float pulse = Mathf.Clamp01(popRatio);
            return baseOffsetX * (1f + pulse * pulse * 0.22f);
        }

        private static float BuildJudgementFeedbackPopScale(
            GreedLastJudgementResult result,
            bool emphasized)
        {
            float scale;
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    scale = 0.22f;
                    break;
                case GreedLastJudgementResult.Good:
                    scale = 0.13f;
                    break;
                case GreedLastJudgementResult.Miss:
                    scale = 0.17f;
                    break;
                default:
                    scale = 0.10f;
                    break;
            }

            return scale + (emphasized ? 0.10f : 0f);
        }

        private static float BuildJudgementFeedbackPopDuration(
            GreedLastJudgementResult result,
            bool emphasized)
        {
            if (emphasized)
            {
                return 0.34f;
            }

            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return 0.24f;
                case GreedLastJudgementResult.Good:
                    return 0.18f;
                case GreedLastJudgementResult.Miss:
                    return 0.28f;
                default:
                    return JudgementFeedbackPopDuration;
            }
        }

        private static float BuildRunChannelDirection(GreedLastRunChannel channel)
        {
            if (channel == GreedLastRunChannel.Left)
            {
                return -1f;
            }

            return channel == GreedLastRunChannel.Right ? 1f : 0f;
        }

        private static string BuildCompactJudgementFeedbackText(
            GreedLastRunSnapshot snapshot, bool devToolsEnabled, bool rotationTiltAvailable)
        {
            GreedLastPatternModel pattern = BuildJudgementFeedbackPattern(snapshot);
            string action = BuildRunnerResponseSymbol(pattern) + " " + BuildActiveActionResponseLabel(pattern);
            switch (snapshot.LastResult)
            {
                case GreedLastJudgementResult.Success:
                    string bonus = snapshot.LastCenterHit ? BuildTimingActionPayoffTag(pattern) : "회피 성공";
                    if (snapshot.LastJudgementScoreLimited)
                    {
                        bonus = "점수 상한";
                    }
                    else if (snapshot.LastCenterHit && pattern.TimingType == GreedLastTimingType.Perfect && !IsRecoveryPattern(pattern))
                    {
                        if (snapshot.LastJudgementStartedInFocusState) bonus = "집중 유지";
                        else if (snapshot.FocusStateActive) bonus = "집중 발동";
                    }
                    string exactPayoff = snapshot.LastJudgementHealthChange > 0
                        ? "체력 +" + snapshot.LastJudgementHealthChange : "콤보 " + snapshot.Combo;
                    return "정확 · " + action + " · +" + snapshot.LastJudgementScoreGain + "점"
                        + "\n" + bonus + " · " + exactPayoff;
                case GreedLastJudgementResult.Good:
                    string timing = BuildJudgedInputTimingLine(snapshot);
                    if (string.IsNullOrEmpty(timing)) timing = "타이밍 보정";
                    string goodPayoff = snapshot.LastJudgementHealthChange > 0
                        ? "체력 +" + snapshot.LastJudgementHealthChange : "콤보 " + snapshot.Combo;
                    return "Good · " + action + " · +" + snapshot.LastJudgementScoreGain + "점"
                        + "\n" + timing + " · " + goodPayoff;
                case GreedLastJudgementResult.Miss:
                    string reason = snapshot.MissReason == "wrong_channel"
                        ? "정답 " + BuildActiveActionCueInputHintForCapabilities(pattern, devToolsEnabled, rotationTiltAvailable)
                        : snapshot.MissReason == "no_input" ? "입력 없음"
                        : snapshot.MissReason == "too_early" ? "너무 빠름"
                        : snapshot.MissReason == "too_late" ? "너무 늦음" : "회피 실패";
                    return "Miss · " + action + "\n" + reason + " · 체력 " + snapshot.Health;
                default:
                    return string.Empty;
            }
        }

        private static string BuildJudgementFeedbackText(GreedLastRunSnapshot snapshot)
        {
            return BuildJudgementFeedbackTextForCapabilities(
                snapshot,
                DevToolsEnabled,
                IsRuntimeRotationTiltAvailable());
        }

        private static string BuildJudgementFeedbackTextForMode(GreedLastRunSnapshot snapshot, bool devToolsEnabled)
        {
            return BuildJudgementFeedbackTextForCapabilities(snapshot, devToolsEnabled, rotationTiltAvailable: true);
        }

        private static string BuildJudgementFeedbackTextForCapabilities(
            GreedLastRunSnapshot snapshot,
            bool devToolsEnabled,
            bool rotationTiltAvailable)
        {
            string[] lines = (snapshot.JudgementText ?? string.Empty).Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries);
            string timingLine = BuildJudgedInputTimingLine(snapshot);
            string transitionPayoff = string.Empty;
            for (int i = 0; i < lines.Length; i += 1)
            {
                if (lines[i].StartsWith("복구 정박 -", StringComparison.Ordinal)
                    || lines[i].StartsWith("압박 정박 -", StringComparison.Ordinal)
                    || lines[i].StartsWith("엇박 정박 -", StringComparison.Ordinal))
                {
                    transitionPayoff = CompactUiText(lines[i], 54);
                    break;
                }
            }

            for (int i = 0; i < lines.Length; i += 1)
            {
                const string bundlePrefix = "패턴 묶음 완벽 - ";
                if (lines[i].StartsWith(bundlePrefix, StringComparison.Ordinal))
                {
                    GreedLastPatternModel bundleFeedbackPattern = BuildJudgementFeedbackPattern(snapshot);
                    string payoffGoal = BuildPrototypeFeelPayoffGoal(snapshot, bundleFeedbackPattern);
                    if (string.IsNullOrEmpty(payoffGoal))
                    {
                        payoffGoal = BuildPrototypePayoffGoalFromTransitionText(transitionPayoff);
                    }

                    string payoffPrefix = string.IsNullOrEmpty(payoffGoal) ? string.Empty : "정확→" + payoffGoal + " / ";
                    string bundleFeedback = BuildJudgementBundleHeader(snapshot)
                        + (string.IsNullOrEmpty(transitionPayoff) ? string.Empty : " · " + transitionPayoff)
                        + "\n"
                        + payoffPrefix
                        + lines[i].Substring(bundlePrefix.Length);
                    string bundleEffect = BuildJudgementEffectLine(snapshot);
                    if (!string.IsNullOrEmpty(payoffGoal))
                    {
                        string duplicateEffectPrefix = "정확→" + payoffGoal;
                        if (bundleEffect == duplicateEffectPrefix)
                        {
                            bundleEffect = string.Empty;
                        }
                        else if (bundleEffect.StartsWith(duplicateEffectPrefix + " / ", StringComparison.Ordinal))
                        {
                            bundleEffect = bundleEffect.Substring(duplicateEffectPrefix.Length + 3);
                        }
                    }

                    if (!string.IsNullOrEmpty(bundleEffect))
                    {
                        bundleFeedback += "\n" + bundleEffect;
                    }

                    return bundleFeedback;
                }
            }

            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            switch (snapshot.LastResult)
            {
                case GreedLastJudgementResult.Success:
                    if (snapshot.PracticeMode)
                    {
                        return AppendPracticeReviewTargetFeedback(
                            "정확 성공 · " + BuildRunnerOutcomeLabel(feedbackPattern, snapshot.LastResult)
                                + "\n" + BuildPracticeSuccessPayoffLine(snapshot),
                            snapshot);
                    }

                    string chainText = snapshot.Combo >= 3 ? "  연쇄 " + BuildRhythmChainLabel(snapshot) : string.Empty;
                    string successActionText = feedbackPattern.IsValid ? " · " + BuildRunnerOutcomeLabel(feedbackPattern, snapshot.LastResult) : string.Empty;
                    return AppendJudgementFeedbackEffect(
                        string.IsNullOrEmpty(timingLine)
                            ? "정확" + successActionText + chainText
                            : "정확" + successActionText + chainText + "  " + timingLine,
                        BuildJudgementEffectLine(snapshot));
                case GreedLastJudgementResult.Good:
                    if (snapshot.PracticeMode)
                    {
                        string practiceGoodTimingHint = BuildTimingGoodFeedbackHint(snapshot);
                        string practiceGoodTimingText = string.IsNullOrEmpty(practiceGoodTimingHint)
                            ? timingLine
                            : string.IsNullOrEmpty(timingLine) ? practiceGoodTimingHint : timingLine + "  " + practiceGoodTimingHint;
                        return AppendPracticeReviewTargetFeedback(
                            "Good · " + BuildRunnerOutcomeLabel(feedbackPattern, snapshot.LastResult)
                                + "\n" + BuildPracticeGoodPayoffMissLine(snapshot)
                                + (string.IsNullOrEmpty(practiceGoodTimingText) ? string.Empty : "\n" + practiceGoodTimingText),
                            snapshot);
                    }

                    string goodActionText = feedbackPattern.IsValid ? " · " + BuildRunnerOutcomeLabel(feedbackPattern, snapshot.LastResult) : string.Empty;
                    string missedExactPayoffText = BuildGoodMissedExactPayoffLine(snapshot);
                    string goodBaseText = string.IsNullOrEmpty(missedExactPayoffText)
                        ? "보정" + goodActionText
                        : "보정" + goodActionText + "  " + missedExactPayoffText;
                    string goodTimingHint = BuildTimingGoodFeedbackHint(snapshot);
                    string goodTimingText = string.IsNullOrEmpty(goodTimingHint)
                        ? timingLine
                        : string.IsNullOrEmpty(timingLine) ? goodTimingHint : timingLine + "  " + goodTimingHint;
                    return AppendJudgementFeedbackEffect(
                        string.IsNullOrEmpty(goodTimingText) ? goodBaseText : goodBaseText + "\n" + goodTimingText,
                        BuildJudgementEffectLine(snapshot));
                case GreedLastJudgementResult.Miss:
                    if (snapshot.PracticeMode)
                    {
                        string practiceMissDetail = snapshot.MissReason == "wrong_channel"
                            ? BuildWrongChannelFeedbackLine(snapshot, feedbackPattern)
                            : snapshot.MissReason == "no_input" ? "입력 없음"
                            : string.IsNullOrEmpty(timingLine) ? "보정권 밖 입력은 피해 처리"
                            : timingLine;
                        string practiceMissHint = BuildTimingMissFeedbackHint(snapshot.MissReason);
                        if (!string.IsNullOrEmpty(practiceMissHint)) practiceMissDetail += " / " + practiceMissHint;
                        string practiceMissText = "Miss · " + BuildRunnerOutcomeLabel(feedbackPattern, snapshot.LastResult)
                            + "\n" + practiceMissDetail;
                        return AppendPracticeReviewTargetFeedback(practiceMissText, snapshot);
                    }

                    string missActionText = feedbackPattern.IsValid
                        ? " · " + BuildRunnerOutcomeLabel(feedbackPattern, snapshot.LastResult)
                        : string.Empty;

                    if (snapshot.MissReason == "wrong_channel")
                    {
                        string deltaLine = timingLine;
                        string wrongChannelText = BuildWrongChannelFeedbackLine(snapshot, feedbackPattern);
                        string keyHint = BuildTargetChannelKeyFeedbackForCapabilities(
                            snapshot,
                            devToolsEnabled,
                            rotationTiltAvailable);
                        if (!string.IsNullOrEmpty(keyHint))
                        {
                            wrongChannelText += "  " + keyHint;
                        }

                        if (!string.IsNullOrEmpty(deltaLine))
                        {
                            wrongChannelText += "  " + deltaLine;
                        }

                        return AppendJudgementFeedbackEffect(
                            "실수" + missActionText + "\n" + wrongChannelText,
                            BuildJudgementEffectLine(snapshot));
                    }

                    if (snapshot.MissReason == "no_input")
                    {
                        string keyHint = BuildTargetChannelKeyFeedbackForCapabilities(
                            snapshot,
                            devToolsEnabled,
                            rotationTiltAvailable);
                        return AppendJudgementFeedbackEffect(
                            "실수" + missActionText + "\n입력 없음" + (string.IsNullOrEmpty(keyHint) ? string.Empty : "  " + keyHint),
                            BuildJudgementEffectLine(snapshot));
                    }

                    string missText = string.IsNullOrEmpty(timingLine)
                        ? "실수" + missActionText
                        : "실수" + missActionText + "\n" + timingLine;
                    string timingHint = BuildTimingMissFeedbackHint(snapshot.MissReason);
                    string baseMissText = string.IsNullOrEmpty(timingHint) ? missText : missText + "  " + timingHint;
                    return AppendJudgementFeedbackEffect(baseMissText, BuildJudgementEffectLine(snapshot));
                default:
                    return string.Empty;
            }
        }

        private static string BuildWrongChannelFeedbackLine(GreedLastRunSnapshot snapshot, GreedLastPatternModel pattern)
        {
            return snapshot.LastJudgedInputChannel == GreedLastRunChannel.None
                ? "채널 오류" : FormatChannel(snapshot.LastJudgedInputChannel)
                    + " 입력 / 정답 " + FormatChannel(pattern.Channel);
        }

        private static string BuildJudgementBundleHeader(GreedLastRunSnapshot snapshot)
        {
            string header = "묶음 완벽";
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (feedbackPattern.IsValid && GreedLastRunCore.IsRotationPattern(feedbackPattern))
            {
                header += " · " + BuildRunnerOutcomeLabel(feedbackPattern, snapshot.LastResult);
            }

            return header;
        }

        private static GreedLastPatternModel BuildJudgementFeedbackPattern(GreedLastRunSnapshot snapshot)
        {
            return snapshot.Pattern.IsValid ? snapshot.Pattern : snapshot.LastJudgedPattern;
        }

        private static string BuildJudgementFeedbackPatternCueLabel(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            return feedbackPattern.IsValid ? BuildTrapResponseCueLabel(feedbackPattern) : string.Empty;
        }

        private static string BuildTargetChannelKeyFeedback(GreedLastRunSnapshot snapshot)
        {
            return BuildTargetChannelKeyFeedbackForCapabilities(
                snapshot,
                DevToolsEnabled,
                IsRuntimeRotationTiltAvailable());
        }

        private static string BuildTargetChannelKeyFeedbackForMode(GreedLastRunSnapshot snapshot, bool devToolsEnabled)
        {
            return BuildTargetChannelKeyFeedbackForCapabilities(
                snapshot,
                devToolsEnabled,
                rotationTiltAvailable: true);
        }

        private static string BuildTargetChannelKeyFeedbackForCapabilities(
            GreedLastRunSnapshot snapshot,
            bool devToolsEnabled,
            bool rotationTiltAvailable)
        {
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (!feedbackPattern.IsValid)
            {
                return string.Empty;
            }

            if (GreedLastRunCore.IsRotationPattern(feedbackPattern))
            {
                string rotationHint = BuildRotationInputHintForCapabilities(
                    feedbackPattern,
                    devToolsEnabled,
                    rotationTiltAvailable);
                return string.IsNullOrEmpty(rotationHint)
                    ? string.Empty
                    : devToolsEnabled ? "정답키 " + rotationHint : "정답 " + rotationHint;
            }

            return BuildTargetChannelInputFeedback(feedbackPattern.Channel, devToolsEnabled);
        }

        private static string BuildTargetChannelInputFeedback(GreedLastRunChannel channel, bool devToolsEnabled)
        {
            string inputHint = BuildRunChannelInputHintForMode(channel, devToolsEnabled);
            if (string.IsNullOrEmpty(inputHint))
            {
                return string.Empty;
            }

            return devToolsEnabled ? "정답키 " + inputHint : "정답 " + inputHint;
        }

        private static string BuildPracticeSuccessPayoffLine(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (!feedbackPattern.IsValid)
            {
                return "대응 확인";
            }

            if (!snapshot.LastCenterHit)
            {
                return FormatTimingType(feedbackPattern.TimingType) + " 대응 확인";
            }

            if (snapshot.JudgementText.Contains("복구 정박", StringComparison.Ordinal)
                || IsRecoveryPattern(feedbackPattern))
            {
                return "정확→회복 · 복구 정박 · 점수 +" + GreedLastRunCore.RecoveryPrecisionScoreBonus
                    + " · 연쇄 +" + GreedLastRunCore.RecoveryPrecisionComboBonus;
            }

            if (snapshot.JudgementText.Contains("정박 중앙 - 집중 충전", StringComparison.Ordinal)
                || feedbackPattern.TimingType == GreedLastTimingType.Perfect)
            {
                return snapshot.LastJudgementStartedInFocusState
                    ? "정확→집중 · 정박 집중 유지 · " + BuildResolvedFocusStateHint(snapshot)
                    : "정확→집중 · 정박 충전 · 집중 +" + GreedLastRunCore.PerfectFocusChargeBonus;
            }

            if (snapshot.JudgementText.Contains("압박 정박 - 반격", StringComparison.Ordinal)
                || feedbackPattern.TimingType == GreedLastTimingType.Clutch)
            {
                return "정확→반격 · 압박 반격 · 점수 +" + GreedLastRunCore.ClutchCounterScoreBonus;
            }

            if (snapshot.JudgementText.Contains("엇박 정박 - 연쇄 가속", StringComparison.Ordinal)
                || feedbackPattern.TimingType == GreedLastTimingType.Offbeat)
            {
                return "정확→연쇄 · 엇박 포착 · 연쇄 +" + GreedLastRunCore.OffbeatFlowComboBonus;
            }

            return FormatTimingType(feedbackPattern.TimingType) + " 대응 확인";
        }

        private static string BuildPracticeGoodPayoffMissLine(GreedLastRunSnapshot snapshot)
        {
            return BuildPracticeGoodPayoffMissLineForPattern(BuildJudgementFeedbackPattern(snapshot));
        }

        private static string BuildGoodMissedExactPayoffLine(GreedLastRunSnapshot snapshot)
        {
            string payoffGoal = BuildPrototypeFeelPayoffGoal(snapshot);
            if (string.IsNullOrEmpty(payoffGoal))
            {
                GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
                if (feedbackPattern.IsValid)
                {
                    payoffGoal = BuildPrototypePatternPayoffGoal(feedbackPattern);
                }
            }

            if (string.IsNullOrEmpty(payoffGoal))
            {
                return string.Empty;
            }

            return payoffGoal == "생존" ? "Good 생존 · 정확 보상 미발동" : "정확→" + payoffGoal + " 미발동";
        }

        private static string BuildPracticeGoodPayoffMissLineForPattern(GreedLastPatternModel pattern)
        {
            string payoffGoal = BuildPrototypePatternPayoffGoal(pattern);
            return string.IsNullOrEmpty(payoffGoal)
                ? "정확 성공은 아니며 목표 보상은 발동하지 않음"
                : "정확 성공은 아니며 정확→" + payoffGoal + " 보상은 발동하지 않음";
        }

        private static string AppendPracticeReviewTargetFeedback(string baseText, GreedLastRunSnapshot snapshot)
        {
            string reviewTargetFeedback = BuildReviewTargetFeedbackLine(snapshot);
            return string.IsNullOrEmpty(reviewTargetFeedback)
                ? baseText
                : baseText + "\n" + reviewTargetFeedback;
        }

        private static string AppendJudgementFeedbackEffect(string baseText, string effectText)
        {
            if (string.IsNullOrEmpty(effectText))
            {
                return baseText;
            }

            int effectBreak = effectText.IndexOf('\n');
            if (baseText.Contains('\n') && effectBreak >= 0)
            {
                // Preserve the timing row while sharing one row for payoff and next-route cues.
                effectText = effectText.Substring(0, effectBreak) + " / " + effectText.Substring(effectBreak + 1);
            }

            return baseText + "\n" + effectText;
        }

        private static string BuildJudgementEffectLine(GreedLastRunSnapshot snapshot)
        {
            string effect;
            switch (snapshot.LastResult)
            {
                case GreedLastJudgementResult.Success:
                    effect = BuildSuccessEffectLine(snapshot);
                    break;
                case GreedLastJudgementResult.Good:
                    effect = BuildGoodEffectLine(snapshot);
                    break;
                case GreedLastJudgementResult.Miss:
                    effect = BuildMissEffectLine(snapshot);
                    break;
                default:
                    return string.Empty;
            }

            string routeStepFeedback = BuildRouteStepFeedback(snapshot);
            if (!string.IsNullOrEmpty(routeStepFeedback))
            {
                effect = string.IsNullOrEmpty(effect)
                    ? routeStepFeedback
                    : effect + "\n" + routeStepFeedback;
            }

            string reviewTargetFeedback = BuildReviewTargetFeedbackLine(snapshot);
            if (string.IsNullOrEmpty(reviewTargetFeedback))
            {
                return effect;
            }

            return string.IsNullOrEmpty(effect) ? reviewTargetFeedback : effect + "\n" + reviewTargetFeedback;
        }

        private static string BuildRouteStepFeedback(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.LastResult == GreedLastJudgementResult.None
                || !TryGetNextRouteCadenceStep(snapshot, out string routeLabel, out string nextTiming, out string nextAction))
            {
                return string.Empty;
            }

            if (!snapshot.PerfectBundleIntact)
            {
                return "경로 " + routeLabel + " 중단 · 다음 " + nextTiming + " 연습 · " + nextAction;
            }

            int remaining = Mathf.Max(0, snapshot.ChapterTarget - snapshot.ChapterProgress);
            if (remaining == 1)
            {
                return "경로 " + routeLabel + " " + snapshot.ChapterProgress + "/" + snapshot.ChapterTarget
                    + " · 마지막 " + nextTiming + " · " + nextAction
                    + " · " + BuildRouteBundleRewardPreview(snapshot);
            }

            return "경로 " + routeLabel + " " + snapshot.ChapterProgress + "/" + snapshot.ChapterTarget
                + " · 다음 " + nextTiming + " · " + nextAction;
        }

        private static bool TryGetNextRouteCadenceStep(
            GreedLastRunSnapshot snapshot,
            out string routeLabel,
            out string nextTiming,
            out string nextAction)
        {
            routeLabel = string.Empty;
            nextTiming = string.Empty;
            nextAction = string.Empty;
            if (snapshot.InfiniteMode
                || snapshot.ChoiceActive
                || snapshot.Stopped
                || snapshot.ChapterProgress <= 0
                || snapshot.ChapterProgress >= snapshot.ChapterTarget
                || !TryBuildRouteCadence(snapshot, out routeLabel, out GreedLastTimingType[] timings))
            {
                return false;
            }

            int nextStep = Mathf.Clamp(snapshot.ChapterProgress, 0, timings.Length - 1);
            nextTiming = BuildCadenceToken(timings[nextStep]);
            bool finalValidation = snapshot.Phase == GreedLastRunPhase.EscapeRunning || snapshot.ChapterIndex >= 4;
            GreedLastAvoidanceType avoidance = GreedLastRunCore.GetAuthoredAvoidanceType(
                snapshot.ChapterIndex,
                nextStep,
                snapshot.PracticeMode,
                snapshot.InfiniteMode,
                finalValidation,
                snapshot.ActiveRouteProfile);
            nextAction = BuildAvoidanceActionLabel(avoidance);
            return !string.IsNullOrEmpty(routeLabel) && nextTiming != "-" && avoidance != GreedLastAvoidanceType.None;
        }

        private static string BuildRouteBundleRewardPreview(GreedLastRunSnapshot snapshot)
        {
            switch (snapshot.ActiveRouteProfile)
            {
                case "안정 루트":
                    return snapshot.GoodHealthGainPreview > 0 ? "회복 대기" : "집중 보상 대기";
                case "변주 루트":
                    return "집중 보상 대기";
                case "압박 루트":
                    return "+" + GreedLastRunCore.PressureRouteBundleScoreBonus + "점 대기";
                default:
                    return "완주 보상 대기";
            }
        }

        private static string BuildSuccessEffectLine(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.LastJudgementScoreLimited)
            {
                string limited = "점수 상한";
                if (snapshot.LastCenterHit) AppendCompactStatus(ref limited, "정박");
                if (snapshot.Combo > 0) AppendCompactStatus(ref limited, "콤보 " + snapshot.Combo);
                if (snapshot.FocusStateActive) AppendCompactStatus(ref limited, snapshot.LastJudgementStartedInFocusState
                    ? BuildResolvedFocusStateHint(snapshot) : "집중 발동");
                return limited;
            }
            string effect = string.Empty;
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            bool feedbackPatternValid = feedbackPattern.IsValid;
            string payoffGoal = BuildPrototypeFeelPayoffGoal(snapshot, feedbackPattern);
            if (!string.IsNullOrEmpty(payoffGoal))
            {
                AppendCompactStatus(ref effect, "정확→" + payoffGoal);
            }

            if (feedbackPatternValid && IsRecoveryPattern(feedbackPattern))
            {
                AppendCompactStatus(
                    ref effect,
                    snapshot.LastCenterHit
                        ? "흐름 회복 +" + GreedLastRunCore.RecoveryPrecisionScoreBonus
                        : "흐름 복귀");
            }

            if (snapshot.LastCenterHit && feedbackPatternValid && feedbackPattern.TimingType == GreedLastTimingType.Perfect)
            {
                AppendCompactStatus(ref effect, snapshot.LastJudgementStartedInFocusState
                    ? "정박 집중 유지" : "정박 충전 +" + GreedLastRunCore.PerfectFocusChargeBonus);
            }

            if (snapshot.LastCenterHit && feedbackPatternValid && feedbackPattern.TimingType == GreedLastTimingType.Clutch)
            {
                AppendCompactStatus(ref effect, "압박 반격 +" + GreedLastRunCore.ClutchCounterScoreBonus);
                if (PatternHasRoute(feedbackPattern, "압박"))
                {
                    AppendCompactStatus(ref effect, "루트 증폭 +" + GreedLastRunCore.PressureRouteClutchScoreBonus);
                }
            }
            else if (snapshot.LastCenterHit && feedbackPatternValid && feedbackPattern.TimingType == GreedLastTimingType.Offbeat)
            {
                AppendCompactStatus(ref effect, "엇박 연쇄 +" + GreedLastRunCore.OffbeatFlowComboBonus);
                if (PatternHasRoute(feedbackPattern, "변주"))
                {
                    AppendCompactStatus(ref effect, snapshot.LastJudgementStartedInFocusState
                        ? "루트 공명 유지" : "루트 집중 +" + GreedLastRunCore.VariationRouteOffbeatFocusBonus);
                }
            }

            int threatBonus = BuildThreatPrecisionBonusPreview(snapshot, feedbackPattern);
            if (threatBonus > 0)
            {
                AppendCompactStatus(ref effect, "위협 +" + threatBonus);
            }

            int variationBonus = BuildPatternVariationPrecisionBonusPreview(feedbackPattern);
            if (variationBonus > 0)
            {
                AppendCompactStatus(ref effect, "변주 +" + variationBonus);
            }

            if (snapshot.LastCenterHit)
            {
                AppendCompactStatus(ref effect, snapshot.PrecisionStreak >= 2 ? "정박 " + snapshot.PrecisionStreak : "정박");
                AppendCompactStatus(ref effect, BuildPrecisionRewardStatus(snapshot));
            }

            if (snapshot.Combo >= 3)
            {
                AppendCompactStatus(ref effect, "연쇄 " + BuildRhythmChainLabel(snapshot));
            }

            AppendCompactStatus(ref effect, BuildChoiceProfileScoreBonusPreview(snapshot));

            if (snapshot.FocusStateActive)
            {
                if (snapshot.LastJudgementStartedInFocusState) AppendCompactStatus(ref effect, BuildResolvedFocusStateHint(snapshot));
                AppendCompactStatus(ref effect, "집중 " + snapshot.FocusStateRemainingSeconds.ToString("0.0") + "s");
            }
            else if (snapshot.Focus == snapshot.MaxFocus - 1 && snapshot.MaxFocus > 1)
            {
                AppendCompactStatus(ref effect, "집중 1칸");
            }

            return effect;
        }

        private static string BuildGoodEffectLine(GreedLastRunSnapshot snapshot)
        {
            string effect = "보정 생존";
            if (snapshot.LastJudgementScoreLimited) AppendCompactStatus(ref effect, "점수 상한");
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (IsRecoveryPattern(feedbackPattern))
            {
                AppendCompactStatus(ref effect, "복구 성공");
            }

            if (JudgementTextContains(snapshot, "안정 루트 - 보정 회복"))
            {
                AppendCompactStatus(ref effect, "안정 회복 +" + GreedLastRunCore.StableRouteGoodHealthBonus);
            }

            AppendCompactStatus(ref effect, "판정선 안쪽");
            AppendCompactStatus(ref effect, BuildChoiceProfileScoreBonusPreview(snapshot));
            if (JudgementTextContains(snapshot, "연쇄 끊김"))
            {
                AppendCompactStatus(ref effect, "연쇄 리셋");
            }

            if (JudgementTextContains(snapshot, "완주 중단"))
            {
                AppendCompactStatus(ref effect, "완주 중단");
            }

            if (snapshot.FocusStateActive)
            {
                if (!snapshot.LastJudgementStartedInFocusState) AppendCompactStatus(ref effect, "집중 발동");
                else if (snapshot.Combo > 0) AppendCompactStatus(ref effect, "집중 연쇄 완충");
            }
            else if (snapshot.Focus == snapshot.MaxFocus - 1 && snapshot.MaxFocus > 1)
            {
                AppendCompactStatus(ref effect, "집중 1칸");
            }

            return effect;
        }

        private static bool PatternHasRoute(GreedLastPatternModel pattern, string route)
        {
            if (string.IsNullOrEmpty(route) || string.IsNullOrEmpty(pattern.Prompt))
                return false;
            string token;
            switch (route)
            {
                case "안정": token = "[안정]"; break;
                case "변주": token = "[변주]"; break;
                case "압박": token = "[압박]"; break;
                default: token = "[" + route + "]"; break;
            }
            return pattern.Prompt.Contains(token, StringComparison.Ordinal);
        }

        private static string BuildChoiceProfileScoreBonusPreview(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.LastResult != GreedLastJudgementResult.Success
                && snapshot.LastResult != GreedLastJudgementResult.Good)
            {
                return string.Empty;
            }

            if (snapshot.LastJudgementProfileScoreBonus >= 0)
            {
                return snapshot.LastJudgementProfileScoreBonus == 0 ? string.Empty
                    : snapshot.LastJudgementScoreLimited ? "조합 보상 · 점수 상한" : "조합 +" + snapshot.LastJudgementProfileScoreBonus;
            }

            int bonus = 0;
            switch (snapshot.ActiveChoiceProfile)
            {
                case "안정형":
                    bonus = snapshot.LastResult == GreedLastJudgementResult.Success
                        ? snapshot.Health >= Mathf.Max(2, snapshot.MaxHealth - 1) ? 12 : 8
                        : 12;
                    break;
                case "집중형":
                    bonus = snapshot.LastResult == GreedLastJudgementResult.Success
                        ? snapshot.LastCenterHit ? 18 : 8
                        : 8;
                    break;
                case "연쇄형":
                    bonus = snapshot.LastResult == GreedLastJudgementResult.Success
                        ? snapshot.Combo >= 3 ? 20 : 10
                        : 6;
                    break;
                case "고점형":
                    bonus = snapshot.LastResult == GreedLastJudgementResult.Success
                        ? snapshot.LastCenterHit ? 28 : 18
                        : 8;
                    break;
                case "균형형":
                    bonus = snapshot.LastResult == GreedLastJudgementResult.Success ? 10 : 8;
                    break;
            }

            return bonus > 0 ? "조합 +" + bonus : string.Empty;
        }

        private static bool HasChoiceProfileScoreBonus(GreedLastRunSnapshot snapshot)
        {
            return !string.IsNullOrEmpty(BuildChoiceProfileScoreBonusPreview(snapshot));
        }

        private static string BuildMissEffectLine(GreedLastRunSnapshot snapshot)
        {
            GreedLastPatternModel feedbackPattern = BuildJudgementFeedbackPattern(snapshot);
            if (snapshot.DevInvincible)
            {
                string devEffect = "무적 테스트 / 체력 유지";
                if (JudgementTextContains(snapshot, "완주 중단"))
                {
                    AppendCompactStatus(ref devEffect, "완주 중단");
                }

                return devEffect;
            }

            if (snapshot.Stopped)
            {
                string stoppedEffect = snapshot.InfiniteMode ? "무한 기록 종료" : "런 실패";
                if (JudgementTextContains(snapshot, "완주 중단"))
                {
                    AppendCompactStatus(ref stoppedEffect, "완주 중단");
                }

                return stoppedEffect;
            }

            string effect;
            switch (snapshot.MissReason)
            {
                case "wrong_channel":
                    effect = "정답 채널 확인";
                    break;
                case "no_input":
                    effect = "다음 함정 입력";
                    break;
                case "too_early":
                    effect = "조금 늦게";
                    break;
                case "too_late":
                    effect = "조금 빠르게";
                    break;
                default:
                    effect = "회복 필요";
                    break;
            }

            AppendCompactStatus(ref effect, BuildPatternVariationMissHint(feedbackPattern));
            AppendCompactStatus(ref effect, "체력 " + snapshot.Health);
            if (!snapshot.FocusStateActive
                && snapshot.Focus == snapshot.MaxFocus - 1
                && snapshot.MaxFocus > 1)
            {
                AppendCompactStatus(ref effect, "집중 1칸");
            }

            if (JudgementTextContains(snapshot, "완주 중단"))
            {
                AppendCompactStatus(ref effect, "완주 중단");
            }

            return effect;
        }

        private static string BuildPatternVariationMissHint(GreedLastPatternModel pattern)
        {
            string prompt = pattern.Prompt ?? string.Empty;
            if (prompt.Contains("[안정]", StringComparison.Ordinal)
                || prompt.Contains("[복구]", StringComparison.Ordinal)
                || prompt.Contains("[유예]", StringComparison.Ordinal))
            {
                return "판정 여유";
            }

            if (prompt.Contains("[탈출]", StringComparison.Ordinal))
            {
                return "탈출 집중";
            }

            if (prompt.Contains("[압박]", StringComparison.Ordinal)
                || prompt.Contains("[심층]", StringComparison.Ordinal))
            {
                return "압박 준비";
            }

            if (prompt.Contains("[변주]", StringComparison.Ordinal))
            {
                return "엇박 대기";
            }

            return string.Empty;
        }

        private static int BuildThreatPrecisionBonusPreview(GreedLastRunSnapshot snapshot)
        {
            return BuildThreatPrecisionBonusPreview(snapshot, snapshot.Pattern);
        }

        private static int BuildThreatPrecisionBonusPreview(GreedLastRunSnapshot snapshot, GreedLastPatternModel pattern)
        {
            if (snapshot.LastResult == GreedLastJudgementResult.Success && !snapshot.ActivePattern
                && snapshot.LastJudgementThreatScoreBonus >= 0)
                return snapshot.LastJudgementScoreLimited ? 0 : snapshot.LastJudgementThreatScoreBonus;
            if (!snapshot.InfiniteMode
                || (!snapshot.ActivePattern && snapshot.LastResult != GreedLastJudgementResult.Success)
                || !pattern.IsValid)
            {
                return 0;
            }

            int threatLevel = Mathf.Max(1, snapshot.InfiniteThreatLevel);
            int bonus = Mathf.Max(0, threatLevel - 1) * 12;
            if (pattern.TimingType == GreedLastTimingType.Clutch)
            {
                bonus += threatLevel >= 3 ? 10 : 0;
            }
            else if (pattern.TimingType == GreedLastTimingType.Offbeat)
            {
                bonus += threatLevel >= 3 ? 8 : 0;
            }

            return bonus;
        }

        private static int BuildPatternVariationPrecisionBonusPreview(GreedLastPatternModel pattern)
        {
            string prompt = pattern.Prompt ?? string.Empty;
            if (prompt.Contains("[복구]", StringComparison.Ordinal)
                || prompt.Contains("[유예]", StringComparison.Ordinal))
            {
                return 0;
            }

            if (prompt.Contains("[위기]", StringComparison.Ordinal))
            {
                return 40;
            }

            if (prompt.Contains("[탈출]", StringComparison.Ordinal))
            {
                return 30;
            }

            if (prompt.Contains("[정밀]", StringComparison.Ordinal))
            {
                return 25;
            }

            if (prompt.Contains("[압박]", StringComparison.Ordinal))
            {
                return 22;
            }

            if (prompt.Contains("[급박]", StringComparison.Ordinal))
            {
                return 20;
            }

            if (prompt.Contains("[연쇄]", StringComparison.Ordinal))
            {
                return 15;
            }

            return 0;
        }

        private static bool JudgementTextContains(GreedLastRunSnapshot snapshot, string token)
        {
            return !string.IsNullOrEmpty(snapshot.JudgementText)
                && snapshot.JudgementText.IndexOf(token, StringComparison.Ordinal) >= 0;
        }

        private static string BuildTimingMissFeedbackHint(string missReason)
        {
            switch (missReason)
            {
                case "too_early":
                    return "다음은 조금 늦게";
                case "too_late":
                    return "다음은 조금 빠르게";
                default:
                    return string.Empty;
            }
        }

        private static string BuildResumeCountdownFeedbackText(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.Paused && snapshot.StartCountdownActive && !snapshot.ResumeCountdownActive)
            {
                return "대기 " + Mathf.CeilToInt(snapshot.StartCountdownRemainingSeconds);
            }

            if (snapshot.CountdownRemainingSeconds > 0.9f)
            {
                return "2";
            }

            if (snapshot.CountdownRemainingSeconds > 0.25f)
            {
                return "1";
            }

            return "GO";
        }

        private static float BuildResumeCountdownFeedbackScale(GreedLastRunSnapshot snapshot)
        {
            return BuildResumeCountdownFeedbackScaleFromValues(
                snapshot.Paused && snapshot.StartCountdownActive && !snapshot.ResumeCountdownActive,
                snapshot.CountdownRemainingSeconds);
        }

        private static float BuildResumeCountdownFeedbackScaleFromValues(bool waitingForStartCountdown, float remainingSeconds)
        {
            if (waitingForStartCountdown)
            {
                return 0.92f;
            }

            float remaining = Mathf.Max(0f, remainingSeconds);
            if (remaining > 0.9f)
            {
                return 1.06f + Mathf.Clamp01((1.4f - remaining) / 0.5f) * 0.04f;
            }

            if (remaining > 0.25f)
            {
                return 1.10f + Mathf.Clamp01((0.9f - remaining) / 0.65f) * 0.04f;
            }

            return 1.24f;
        }

        private static Color32 BuildResumeCountdownFeedbackColor(GreedLastRunSnapshot snapshot)
        {
            return BuildResumeCountdownFeedbackColorFromValues(
                snapshot.Paused && snapshot.StartCountdownActive && !snapshot.ResumeCountdownActive,
                snapshot.CountdownRemainingSeconds);
        }

        private static Color32 BuildResumeCountdownFeedbackColorFromValues(bool waitingForStartCountdown, float remainingSeconds)
        {
            if (waitingForStartCountdown)
            {
                return new Color32(206, 205, 190, 210);
            }

            if (remainingSeconds <= 0.25f)
            {
                return new Color32(255, 248, 210, 255);
            }

            if (remainingSeconds <= 0.9f)
            {
                return new Color32(255, 238, 181, 245);
            }

            return new Color32(230, 218, 185, 230);
        }

        private static string BuildTimingGoodFeedbackHint(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.HasJudgedInputTiming
                || Mathf.RoundToInt(Mathf.Abs(snapshot.LastInputTimingDeltaSeconds) * 1000f) <= 20)
            {
                return string.Empty;
            }

            return snapshot.LastInputTimingDeltaSeconds < 0f ? "다음은 살짝 늦게" : "다음은 살짝 빠르게";
        }

        private static Color32 GetJudgementFeedbackColor(GreedLastJudgementResult result)
        {
            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return new Color32(255, 238, 181, 255);
                case GreedLastJudgementResult.Good:
                    return new Color32(132, 190, 208, 245);
                case GreedLastJudgementResult.Miss:
                    return new Color32(231, 91, 77, 245);
                default:
                    return new Color32(255, 255, 255, 0);
            }
        }

        private static Color32 GetJudgementFeedbackColor(GreedLastRunSnapshot snapshot)
        {
            Color32 baseColor = GetJudgementFeedbackColor(snapshot.LastResult);
            if (IsReviewTargetFailureSnapshot(snapshot))
            {
                return snapshot.LastResult == GreedLastJudgementResult.Good
                    ? new Color32(240, 126, 91, 250)
                    : new Color32(231, 91, 77, 245);
            }

            if (IsReviewTargetAchievementSnapshot(snapshot))
            {
                return new Color32(145, 231, 199, 255);
            }

            if (TryGetRoutePayoffFeedbackColor(snapshot, out Color32 routeColor))
            {
                return routeColor;
            }

            if (snapshot.FocusStateActive && snapshot.LastResult != GreedLastJudgementResult.Miss)
            {
                return Color32.Lerp(baseColor, new Color32(255, 214, 105, 255), 0.48f);
            }

            return baseColor;
        }

        private static bool TryGetRoutePayoffFeedbackColor(
            GreedLastRunSnapshot snapshot,
            out Color32 color)
        {
            if (snapshot.LastResult == GreedLastJudgementResult.Good
                && JudgementTextContains(snapshot, "안정 루트 - 보정 회복"))
            {
                color = new Color32(145, 231, 199, 255);
                return true;
            }

            if (snapshot.LastResult == GreedLastJudgementResult.Success
                && snapshot.LastCenterHit
                && JudgementTextContains(snapshot, "변주 루트 - 엇박 공명"))
            {
                color = new Color32(181, 146, 226, 255);
                return true;
            }

            if (snapshot.LastResult == GreedLastJudgementResult.Success
                && snapshot.LastCenterHit
                && JudgementTextContains(snapshot, "압박 루트 - 클러치 증폭"))
            {
                color = new Color32(238, 151, 76, 255);
                return true;
            }

            color = default;
            return false;
        }

        private static float BuildRoutePayoffHapticDuration(string routeProfile, bool reviewTargetAchievementJustReached)
        {
            float baseSeconds;
            switch (routeProfile)
            {
                case "안정 루트":
                    baseSeconds = 0.030f;
                    break;
                case "변주 루트":
                    baseSeconds = 0.040f;
                    break;
                case "압박 루트":
                    baseSeconds = 0.050f;
                    break;
                default:
                    baseSeconds = 0.018f;
                    break;
            }

            return reviewTargetAchievementJustReached
                ? Mathf.Max(0.055f, baseSeconds + 0.010f)
                : baseSeconds;
        }

        private static bool IsReviewTargetFailureSnapshot(GreedLastRunSnapshot snapshot)
        {
            if (string.IsNullOrWhiteSpace(snapshot.ReviewTargetText)
                || snapshot.LastResult == GreedLastJudgementResult.None)
            {
                return false;
            }

            string target = snapshot.ReviewTargetText;
            if (target.Contains("무실수", StringComparison.Ordinal))
            {
                return snapshot.LastResult == GreedLastJudgementResult.Miss || snapshot.MissCount > 0;
            }

            if (target.Contains("보정 0회", StringComparison.Ordinal))
            {
                return snapshot.LastResult == GreedLastJudgementResult.Good
                    || snapshot.GoodCount > 0
                    || snapshot.LastResult == GreedLastJudgementResult.Miss
                    || snapshot.MissCount > 0;
            }

            if (target.Contains("입력 없음", StringComparison.Ordinal))
            {
                int targetNoInput = ExtractTargetNumberAfterKeywordForUi(target, "입력 없음");
                return snapshot.NoInputMissCount > targetNoInput;
            }

            if (target.Contains("실수", StringComparison.Ordinal)
                && target.Contains("이하", StringComparison.Ordinal))
            {
                int targetMisses = ExtractTargetNumberAfterKeywordForUi(target, "실수");
                return snapshot.MissCount > targetMisses;
            }

            return false;
        }

        private static bool IsReviewTargetAchievementSnapshot(GreedLastRunSnapshot snapshot)
        {
            if (string.IsNullOrWhiteSpace(snapshot.ReviewTargetText)
                || snapshot.LastResult == GreedLastJudgementResult.None
                || snapshot.LastResult == GreedLastJudgementResult.Miss)
            {
                return false;
            }

            string target = snapshot.ReviewTargetText;
            if (snapshot.Stopped && target.Contains("무실수", StringComparison.Ordinal))
            {
                return snapshot.MissCount <= 0;
            }

            if (snapshot.Stopped && target.Contains("보정 0회", StringComparison.Ordinal))
            {
                return snapshot.GoodCount <= 0 && snapshot.MissCount <= 0;
            }

            if (snapshot.Stopped && target.Contains("입력 없음", StringComparison.Ordinal))
            {
                int targetNoInput = ExtractTargetNumberAfterKeywordForUi(target, "입력 없음");
                return snapshot.NoInputMissCount <= targetNoInput;
            }

            if (snapshot.Stopped
                && target.Contains("실수", StringComparison.Ordinal)
                && target.Contains("이하", StringComparison.Ordinal))
            {
                int targetMisses = ExtractTargetNumberAfterKeywordForUi(target, "실수");
                return snapshot.MissCount <= targetMisses;
            }

            if (target.Contains("콤보", StringComparison.Ordinal))
            {
                int targetCombo = ExtractTargetNumberAfterKeywordForUi(target, "콤보");
                return targetCombo > 0 && snapshot.Combo >= targetCombo;
            }

            if (target.Contains("점", StringComparison.Ordinal))
            {
                int targetScore = ExtractTargetNumberBeforeMarkerForUi(target, "점");
                return targetScore > 0 && snapshot.Score >= targetScore;
            }

            if (target.Contains("구간 생존", StringComparison.Ordinal))
            {
                int targetSections = ExtractTargetNumberBeforeMarkerForUi(target, "구간");
                return targetSections > 0 && snapshot.InfiniteSectionsCleared >= targetSections;
            }

            if (target.Contains("위협", StringComparison.Ordinal))
            {
                int targetThreat = ExtractTargetNumberAfterKeywordForUi(target, "위협");
                return targetThreat > 0 && snapshot.MaxInfiniteThreatLevel >= targetThreat;
            }

            if (target.Contains("추천 보정 적용", StringComparison.Ordinal))
            {
                return snapshot.TimingRecommendationApplied;
            }

            if (target.Contains("체력", StringComparison.Ordinal) || target.Contains("생존", StringComparison.Ordinal))
            {
                int targetHealth = target.Contains("체력", StringComparison.Ordinal)
                    ? ExtractTargetNumberAfterKeywordForUi(target, "체력")
                    : ExtractTargetNumberAfterKeywordForUi(target, "생존");
                return targetHealth > 0 && snapshot.Health >= targetHealth;
            }

            if (target.Contains("집중", StringComparison.Ordinal))
            {
                int targetFocus = ExtractTargetNumberAfterKeywordForUi(target, "집중");
                return targetFocus > 0 && BuildReviewTargetFocusProgress(snapshot, target) >= targetFocus;
            }

            if (target.Contains("정박", StringComparison.Ordinal) || target.Contains("정확권", StringComparison.Ordinal))
            {
                int targetPrecision = ExtractTargetPrecisionNumberForUi(target);
                return targetPrecision > 0 && snapshot.PrecisionStreak >= targetPrecision;
            }

            return false;
        }

