        private void UpdateFeedbackFlash()
        {
            if (feedbackFlash == null || feedbackFlash.color.a <= 0f)
            {
                UpdateJudgementFeedbackText();
                return;
            }

            if (!CanShowRunTransientFeedback() || Time.unscaledTime >= feedbackFlashUntil)
            {
                ClearFeedbackFlash();
            }
            else
            {
                feedbackFlash.color = BuildFeedbackFlashFadedColor(
                    feedbackFlashBaseColor,
                    feedbackFlashStartedAt,
                    feedbackFlashUntil,
                    Time.unscaledTime);
            }

            UpdateJudgementFeedbackText();
        }

        private void StartFeedbackFlash(Color32 color, float duration)
        {
            if (feedbackFlash == null)
            {
                return;
            }

            float safeDuration = Mathf.Max(0.01f, duration);
            feedbackFlashBaseColor = color;
            feedbackFlashStartedAt = Time.unscaledTime;
            feedbackFlashUntil = feedbackFlashStartedAt + safeDuration;
            feedbackFlash.color = color;
        }

        private void ExtendFeedbackFlash(Color32 color, float duration)
        {
            if (feedbackFlash == null)
            {
                return;
            }

            float safeDuration = Mathf.Max(0.01f, duration);
            float requestedUntil = Time.unscaledTime + safeDuration;
            if (feedbackFlash.color.a <= 0f || requestedUntil >= feedbackFlashUntil)
            {
                StartFeedbackFlash(color, safeDuration);
                return;
            }

            feedbackFlashBaseColor = color;
            feedbackFlash.color = BuildFeedbackFlashFadedColor(
                feedbackFlashBaseColor,
                feedbackFlashStartedAt,
                feedbackFlashUntil,
                Time.unscaledTime);
        }

        private void ClearFeedbackFlash()
        {
            feedbackFlashBaseColor = new Color32(255, 255, 255, 0);
            feedbackFlashStartedAt = 0f;
            feedbackFlashUntil = 0f;
            if (feedbackFlash != null)
            {
                feedbackFlash.color = feedbackFlashBaseColor;
            }
        }

        private static Color32 BuildFeedbackFlashFadedColor(Color32 baseColor, float startedAt, float until, float now)
        {
            float alphaScale = BuildFeedbackFlashAlphaScale(startedAt, until, now);
            return WithAlpha(baseColor, Mathf.RoundToInt(baseColor.a * alphaScale));
        }

        private static float BuildFeedbackFlashAlphaScale(float startedAt, float until, float now)
        {
            float duration = Mathf.Max(0.01f, until - startedAt);
            float age = Mathf.Clamp01((now - startedAt) / duration);
            const float holdFraction = 0.16f;
            if (age <= holdFraction)
            {
                return 1f;
            }

            float remaining = 1f - Mathf.Clamp01((age - holdFraction) / (1f - holdFraction));
            return remaining * remaining * (3f - 2f * remaining);
        }

        private void UpdateJudgementFeedbackText()
        {
            if (judgementFeedbackText == null)
            {
                return;
            }

            if (runModeActive
                && hasRunSnapshot
                && (latestRunSnapshot.ResumeCountdownActive || latestRunSnapshot.StartCountdownActive))
            {
                ShowResumeCountdownFeedback(latestRunSnapshot);
                return;
            }

            if (runModeActive
                && hasRunSnapshot
                && !ShouldShowRunTransientFeedback(latestRunSnapshot))
            {
                judgementFeedbackText.fontSize = 48;
                judgementFeedbackText.color = new Color32(255, 238, 181, 0);
                judgementFeedbackText.rectTransform.localScale = Vector3.one;
                judgementFeedbackText.rectTransform.anchoredPosition = Vector2.zero;
                judgementFeedbackOffsetX = 0f;
                return;
            }

            if (!runModeActive || Time.unscaledTime >= judgementFeedbackUntil)
            {
                judgementFeedbackText.fontSize = 48;
                judgementFeedbackText.color = new Color32(255, 238, 181, 0);
                judgementFeedbackText.rectTransform.localScale = Vector3.one;
                judgementFeedbackText.rectTransform.anchoredPosition = Vector2.zero;
                judgementFeedbackOffsetX = 0f;
                return;
            }

            ApplyJudgementFeedbackPop();
        }

        private void ApplyJudgementFeedbackPop()
        {
            if (judgementFeedbackText == null)
            {
                return;
            }

            float remaining = judgementFeedbackPopUntil - Time.unscaledTime;
            if (remaining <= 0f)
            {
                judgementFeedbackText.rectTransform.localScale = Vector3.one;
                ApplyJudgementFeedbackOffset(0f);
                return;
            }

            float pulse = Mathf.Clamp01(remaining / Mathf.Max(0.01f, judgementFeedbackPopDuration));
            float eased = pulse * pulse;
            judgementFeedbackText.rectTransform.localScale = Vector3.one * (1f + eased * judgementFeedbackPopScale);
            ApplyJudgementFeedbackOffset(pulse);
        }

        private void PlayClip(AudioClip clip, float volume)
        {
            if (CanPlaySensoryFeedback && sfxVolume > 0f && rhythmAudio != null
                && rhythmAudio.isActiveAndEnabled && clip != null)
            {
                // The source owns the master gain so changes also affect sounds already playing.
                rhythmAudio.PlayOneShot(clip, BuildEffectiveSfxVolume(volume, BuildAudioSourceBaseVolume()));
            }
        }

        private bool CanPlaySensoryFeedback => appInputAvailable && sensoryComponentEnabled && isActiveAndEnabled && !audioConfigurationPending
            && sensoryHasFocus && !sensoryAppPaused && HasVisiblePresentation;

        private void RefreshAudioPlaybackState()
        {
            if (rhythmAudio == null) return;
            rhythmAudio.volume = BuildEffectiveSfxVolume(BuildAudioSourceBaseVolume(), sfxVolume);
            rhythmAudio.mute = !CanPlaySensoryFeedback || sfxVolume <= 0f;
            if (rhythmAudio.mute) StopRhythmAudio();
        }

        private void StopRhythmAudio()
        {
            if (rhythmAudio != null) rhythmAudio.Stop();
        }

        private static float BuildEffectiveSfxVolume(float clipVolume, float masterVolume)
        {
            return Mathf.Clamp01(clipVolume) * Mathf.Clamp(masterVolume, MinSfxVolume, MaxSfxVolume);
        }

        private static float BuildAudioSourceBaseVolume()
        {
            return 1f;
        }

        private void PlayHaptic(float seconds)
        {
            if (!hapticsEnabled || !CanPlaySensoryFeedback)
            {
                return;
            }

            if (lastHapticAt >= 0f && Time.unscaledTime - lastHapticAt < MinHapticInterval)
            {
                return;
            }

            lastHapticAt = Time.unscaledTime;

#if UNITY_ANDROID && !UNITY_EDITOR
            try
            {
                using (var unityPlayer = new AndroidJavaClass("com.unity3d.player.UnityPlayer"))
                using (AndroidJavaObject activity = unityPlayer.GetStatic<AndroidJavaObject>("currentActivity"))
                using (AndroidJavaObject vibrator = activity.Call<AndroidJavaObject>("getSystemService", "vibrator"))
                {
                    long milliseconds = BuildAndroidHapticMilliseconds(seconds);
                    vibrator.Call("vibrate", milliseconds);
                }
            }
            catch
            {
                Handheld.Vibrate();
            }
#elif UNITY_IOS && !UNITY_EDITOR
            Handheld.Vibrate();
#endif
        }

        private static int BuildAndroidHapticMilliseconds(float seconds)
        {
            return Mathf.Clamp(Mathf.RoundToInt(seconds * 1000f), 1, 120);
        }

