        private static float NormalizeSfxVolume(float volume)
        {
            return float.IsNaN(volume) || float.IsInfinity(volume)
                ? DefaultSfxVolume : Mathf.Clamp(volume, MinSfxVolume, MaxSfxVolume);
        }

