        private AudioClip CreateTone(string name, float frequency, float duration, float gain)
        {
            const int sampleRate = 44100;
            int samples = Mathf.CeilToInt(sampleRate * duration);
            float[] data = new float[samples];
            for (int i = 0; i < samples; i += 1)
            {
                float t = i / (float)sampleRate;
                float envelope = 1f - (i / (float)samples);
                data[i] = Mathf.Sin(2f * Mathf.PI * frequency * t) * gain * envelope;
            }

            AudioClip clip = AudioClip.Create(name, samples, 1, sampleRate, false);
            ownedAudioClips.Add(clip);
            clip.SetData(data, 0);
            return clip;
        }

        private AudioClip CreateSweepTone(string name, float startFrequency, float endFrequency, float duration, float gain)
        {
            const int sampleRate = 44100;
            int samples = Mathf.CeilToInt(sampleRate * duration);
            float[] data = new float[samples];
            float phase = 0f;
            for (int i = 0; i < samples; i += 1)
            {
                float t = i / (float)Mathf.Max(1, samples - 1);
                float frequency = Mathf.Lerp(startFrequency, endFrequency, t);
                phase += 2f * Mathf.PI * frequency / sampleRate;
                float envelope = 1f - t;
                data[i] = Mathf.Sin(phase) * gain * envelope;
            }

            AudioClip clip = AudioClip.Create(name, samples, 1, sampleRate, false);
            ownedAudioClips.Add(clip);
            clip.SetData(data, 0);
            return clip;
        }

        private AudioClip CreateDoubleTone(string name, float firstFrequency, float secondFrequency, float duration, float gain)
        {
            const int sampleRate = 44100;
            int samples = Mathf.CeilToInt(sampleRate * duration);
            float[] data = new float[samples];
            for (int i = 0; i < samples; i += 1)
            {
                float t = i / (float)sampleRate;
                float normalized = i / (float)Mathf.Max(1, samples - 1);
                float envelope = 1f - normalized;
                float split = normalized < 0.48f ? 1f : 0f;
                float first = Mathf.Sin(2f * Mathf.PI * firstFrequency * t) * split;
                float second = Mathf.Sin(2f * Mathf.PI * secondFrequency * t) * (1f - split);
                data[i] = (first + second) * gain * envelope;
            }

            AudioClip clip = AudioClip.Create(name, samples, 1, sampleRate, false);
            ownedAudioClips.Add(clip);
            clip.SetData(data, 0);
            return clip;
        }

        private static string FormatChannel(GreedLastRunChannel channel)
        {
            switch (channel)
            {
                case GreedLastRunChannel.Left:
                    return "좌";
                case GreedLastRunChannel.Center:
                    return "중";
                case GreedLastRunChannel.Right:
                    return "우";
                default:
                    return "-";
            }
        }

        private static string FormatTimingType(GreedLastTimingType timingType)
        {
            switch (timingType)
            {
                case GreedLastTimingType.Perfect:
                    return "정박";
                case GreedLastTimingType.Clutch:
                    return "압박";
                case GreedLastTimingType.Offbeat:
                    return "엇박";
                default:
                    return "-";
            }
        }

        private static string FormatMissReason(string missReason)
        {
            switch (missReason)
            {
                case "wrong_channel":
                    return "채널 오류";
                case "no_input":
                    return "입력 없음";
                case "too_early":
                    return "너무 빠름";
                case "too_late":
                    return "너무 늦음";
                case "focus_guard":
                    return "집중 보호";
                case "test_stop":
                    return "정산 종료";
                default:
                    return string.IsNullOrEmpty(missReason) ? "-" : missReason;
            }
        }

        private static string FormatBool(bool value)
        {
            return value ? "Y" : "N";
        }

        private static string FormatHealthValue(GreedLastRunSnapshot snapshot)
        {
            int maxHealth = Mathf.Max(1, snapshot.MaxHealth);
            return snapshot.Health + "/" + maxHealth;
        }

        private static string FormatFocusStatus(GreedLastRunSnapshot snapshot)
        {
            return snapshot.FocusStateActive
                ? "집중 상태 " + snapshot.FocusStateRemainingSeconds.ToString("0.0") + "s"
                : "집중 " + snapshot.Focus + "/" + snapshot.MaxFocus;
        }

        private static string BuildSnapshotFocusPerformance(GreedLastRunSnapshot snapshot)
        {
            return snapshot.FocusStateActivationCount <= 0
                ? "집중 상태 미발동"
                : "집중 발동 " + snapshot.FocusStateActivationCount
                    + "  집중 중 정확 " + snapshot.FocusStateSuccessCount
                    + "  유지 " + snapshot.FocusStateActiveSeconds.ToString("0.0") + "s";
        }

        private static string FormatTimingOffset(float seconds)
        {
            int milliseconds = Mathf.RoundToInt(seconds * 1000f);
            if (milliseconds == 0)
            {
                return "0ms";
            }

            return milliseconds > 0
                ? "+" + milliseconds + "ms"
                : milliseconds + "ms";
        }

        private static string BuildRhythmChainLabel(GreedLastRunSnapshot snapshot)
        {
            int level = Mathf.Clamp(snapshot.Combo / 3, 0, 5);
            return level <= 0 ? "-" : "x" + level;
        }

        private static string BuildInfiniteSnapshotGrade(GreedLastRunSnapshot snapshot)
        {
            long gradeScore = (long)snapshot.Score
                + (long)snapshot.InfiniteSectionsCleared * 120
                + (long)snapshot.MaxCombo * 30
                - (long)snapshot.MissCount * 90;
            if (gradeScore >= 2000)
            {
                return "S";
            }

            if (gradeScore >= 1300)
            {
                return "A";
            }

            if (gradeScore >= 700)
            {
                return "B";
            }

            return "C";
        }

        private static string FormatActiveInfiniteLoadoutName(string loadoutName)
        {
            return string.IsNullOrEmpty(loadoutName) ? "저장 조합 없음" : CompactUiText(loadoutName, 22);
        }

        private static string FormatActiveInfiniteLoadoutProfileSuffix(GreedLastRunSnapshot snapshot)
        {
            string profile = snapshot.InfiniteMode && IsVisibleChoiceProfile(snapshot.ActiveInfiniteLoadoutProfile)
                ? snapshot.ActiveInfiniteLoadoutProfile
                : snapshot.ActiveChoiceProfile;
            return IsVisibleChoiceProfile(profile)
                ? " / " + CompactUiText(CompactActiveInfiniteLoadoutProfileText(profile), 16)
                : string.Empty;
        }

        private static string CompactActiveInfiniteLoadoutProfileText(string profile)
        {
            return string.IsNullOrEmpty(profile)
                ? string.Empty
                : profile.Replace(" 루트", string.Empty).Replace(" / ", "/");
        }

        private static string CompactUiText(string value, int maxLength)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return "없음";
            }

            string compact = value.Replace('\r', ' ').Replace('\n', ' ').Trim();
            while (compact.Contains("  "))
            {
                compact = compact.Replace("  ", " ");
            }

            if (maxLength <= 3 || compact.Length <= maxLength)
            {
                return compact;
            }

            return compact.Substring(0, maxLength - 3) + "...";
        }

        private static string BuildInfiniteStoppedHighlight(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.InfiniteSectionsCleared >= 3 && snapshot.MissCount <= 2)
            {
                return "안정 생존";
            }

            if (snapshot.MaxCombo >= 9)
            {
                return "연쇄 유지";
            }

            if (snapshot.InfiniteThreatLevel >= 4)
            {
                return "고위험 도달";
            }

            if (snapshot.MissCount >= Math.Max(3L, (long)snapshot.SuccessCount + snapshot.GoodCount))
            {
                return "보정 필요";
            }

            return "기록 확인";
        }

        private static float BuildBeatVisualSpeed(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.ResumeCountdownActive || (snapshot.StartCountdownActive && !snapshot.Paused))
            {
                return 1.6f;
            }

            if (snapshot.Paused || snapshot.Stopped || snapshot.ChoiceActive)
            {
                return 0f;
            }

            float speed = snapshot.InfiniteMode
                ? Mathf.Lerp(1.6f, 2.18f, Mathf.Clamp01((snapshot.InfiniteThreatLevel - 1) / 4f))
                : 1.6f;
            return snapshot.FocusStateActive ? speed * 1.12f : speed;
        }

        private static bool BuildCountdownBeatActive(GreedLastRunSnapshot snapshot)
        {
            return snapshot.ResumeCountdownActive || (snapshot.StartCountdownActive && !snapshot.Paused);
        }

        private static bool ShouldResetCountdownBeatSchedule(bool previousCountdownBeatActive, bool currentCountdownBeatActive)
        {
            return currentCountdownBeatActive && !previousCountdownBeatActive;
        }

        private static float BuildBeatInterval(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.InfiniteMode)
            {
                return 0.5f;
            }

            return Mathf.Lerp(0.5f, 0.36f, Mathf.Clamp01((snapshot.InfiniteThreatLevel - 1) / 4f));
        }

        private static float BuildBeatClickVolume(GreedLastRunSnapshot snapshot)
        {
            float volume = snapshot.ActivePattern ? ActiveBeatVolume : IdleBeatVolume;
            if (snapshot.ActivePattern)
            {
                volume += Mathf.Max(0f, BuildTrapVariationPressure(snapshot.Pattern)) * 0.08f;
                volume += BuildBeatCueUrgencyVolumeLift(BuildActiveBeatCueUrgency(snapshot));
                if (snapshot.InfiniteMode)
                {
                    volume += Mathf.Clamp01((snapshot.InfiniteThreatLevel - 1) / 4f) * 0.035f;
                }
            }

            return Mathf.Clamp(volume, 0.04f, 0.22f);
        }

        private static float BuildBeatCueUrgencyVolumeLift(float beatCueUrgency)
        {
            return Mathf.Clamp01(beatCueUrgency) * 0.018f;
        }

        private static float BuildCountdownBeatVolume(GreedLastRunSnapshot snapshot)
        {
            return BuildCountdownBeatVolumeFromValues(
                snapshot.ResumeCountdownActive,
                snapshot.ActivePattern,
                snapshot.CountdownRemainingSeconds,
                snapshot.InfiniteMode,
                snapshot.InfiniteThreatLevel);
        }

        private static float BuildCountdownBeatVolumeFromValues(
            bool resumeCountdownActive,
            bool activePattern,
            float remainingSeconds,
            bool infiniteMode,
            int infiniteThreatLevel)
        {
            float volume = IdleBeatVolume * (resumeCountdownActive ? 1.40f : 1.28f);
            if (activePattern)
            {
                volume += 0.018f;
            }

            if (remainingSeconds <= 0.25f)
            {
                volume += 0.030f;
            }
            else if (remainingSeconds <= 0.9f)
            {
                volume += 0.012f;
            }

            if (infiniteMode)
            {
                volume += Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.018f;
            }

            return Mathf.Clamp(volume, 0.08f, 0.24f);
        }

        private static float BuildCountdownBeatHapticDuration(GreedLastRunSnapshot snapshot)
        {
            return BuildCountdownBeatHapticDurationFromValues(
                snapshot.ResumeCountdownActive,
                snapshot.ActivePattern,
                snapshot.CountdownRemainingSeconds,
                snapshot.InfiniteMode,
                snapshot.InfiniteThreatLevel);
        }

        private static float BuildCountdownBeatHapticDurationFromValues(
            bool resumeCountdownActive,
            bool activePattern,
            float remainingSeconds,
            bool infiniteMode,
            int infiniteThreatLevel)
        {
            float seconds = resumeCountdownActive ? 0.014f : 0.010f;
            if (activePattern)
            {
                seconds += 0.003f;
            }

            if (remainingSeconds <= 0.25f)
            {
                seconds += 0.014f;
            }
            else if (remainingSeconds <= 0.9f)
            {
                seconds += 0.005f;
            }

            if (infiniteMode)
            {
                seconds += Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.004f;
            }

            return Mathf.Clamp(seconds, 0.008f, 0.045f);
        }

        private static float BuildStraightRunLaunchCueVolume(
            bool releaseStarted,
            bool resumeCountdown,
            bool activePattern,
            bool infiniteMode,
            int infiniteThreatLevel)
        {
            if (!releaseStarted)
            {
                return 0f;
            }

            float volume = IdleBeatVolume * (resumeCountdown ? 1.52f : 1.44f);
            if (activePattern)
            {
                volume += 0.014f;
            }

            if (infiniteMode)
            {
                volume += Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.014f;
            }

            return Mathf.Clamp(volume, 0.12f, 0.25f);
        }

        private static float BuildStraightRunLaunchHapticDuration(
            bool releaseStarted,
            bool resumeCountdown,
            bool activePattern,
            bool infiniteMode,
            int infiniteThreatLevel)
        {
            if (!releaseStarted)
            {
                return 0f;
            }

            float seconds = resumeCountdown ? 0.022f : 0.018f;
            if (activePattern)
            {
                seconds += 0.003f;
            }

            if (infiniteMode)
            {
                seconds += Mathf.Clamp01((infiniteThreatLevel - 1) / 4f) * 0.003f;
            }

            return Mathf.Clamp(seconds, 0.012f, 0.032f);
        }

        private static string BuildCompactTimingGuideLabel(GreedLastRunSnapshot snapshot)
        {
            return BuildCompactTimingGuideLabelFromBeat(BuildCompactTimingGuideBeat(snapshot),
                Mathf.RoundToInt(snapshot.Pattern.SuccessWindowSeconds * 1000f));
        }

        private string GetCompactTimingGuideLabel(GreedLastRunSnapshot snapshot)
        {
            string beat = BuildCompactTimingGuideBeat(snapshot);
            int windowMs = Mathf.RoundToInt(snapshot.Pattern.SuccessWindowSeconds * 1000f);
            if (cachedCompactTimingGuideLabel == null || cachedCompactTimingGuideBeat != beat
                || cachedCompactTimingGuideWindowMs != windowMs)
            {
                cachedCompactTimingGuideBeat = beat;
                cachedCompactTimingGuideWindowMs = windowMs;
                cachedCompactTimingGuideLabel = BuildCompactTimingGuideLabelFromBeat(beat, windowMs);
            }
            return cachedCompactTimingGuideLabel;
        }

        private static string BuildCompactTimingGuideBeat(GreedLastRunSnapshot snapshot)
        {
            if (!ShouldShowActivePatternVisuals(snapshot) || !snapshot.Pattern.IsValid) return string.Empty;
            if (ShouldWaitForCalibratedInput(snapshot)) return "보정 입력 대기";
            if (snapshot.CoreDeltaSeconds > snapshot.Pattern.GoodWindowSeconds) return "놓침";
            if (snapshot.CoreDeltaSeconds > snapshot.Pattern.SuccessWindowSeconds) return "늦음 · Good 가능";
            return Mathf.Abs(snapshot.CoreDeltaSeconds) <= BuildCenterHitWindow(snapshot.Pattern)
                ? "정박" : BuildActivePatternBeatCue(snapshot);
        }

        private static string BuildCompactTimingGuideLabelFromBeat(string beat, int windowMs)
        {
            if (beat == string.Empty || beat == "놓침" || beat == "늦음 · Good 가능" || beat == "보정 입력 대기") return beat;
            return beat + " · 정확 ±" + windowMs + "ms";
        }

        private static bool ShouldWaitForCalibratedInput(GreedLastRunSnapshot snapshot)
        {
            return ShouldShowActivePatternVisuals(snapshot) && snapshot.Pattern.IsValid
                && snapshot.CoreDeltaSeconds > snapshot.Pattern.GoodWindowSeconds
                && Mathf.Abs(snapshot.CoreDeltaSeconds + snapshot.InputTimingOffsetSeconds)
                    <= snapshot.Pattern.GoodWindowSeconds;
        }

        private static string BuildTimingGuideLabel(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.ResumeCountdownActive)
            {
                return "재개 " + snapshot.ResumeCountdownRemainingSeconds.ToString("0.0") + "s";
            }

            if (snapshot.StartCountdownActive && snapshot.Paused)
            {
                return "시작 대기 " + snapshot.StartCountdownRemainingSeconds.ToString("0.0") + "s";
            }

            if (snapshot.Paused)
            {
                return "일시정지";
            }

            if (snapshot.StartCountdownActive)
            {
                return "시작 " + snapshot.StartCountdownRemainingSeconds.ToString("0.0") + "s";
            }

            if (!snapshot.ActivePattern)
            {
                return "대기";
            }

            bool waitingForInput = ShouldWaitForCalibratedInput(snapshot);
            float absoluteDelta = Mathf.Abs(snapshot.CoreDeltaSeconds
                + (waitingForInput ? snapshot.InputTimingOffsetSeconds : 0f));
            string timingWord = waitingForInput ? "보정 입력 대기" : BuildTimingGuideWordFromValues(
                snapshot.CoreDeltaSeconds,
                BuildCenterHitWindow(snapshot.Pattern),
                snapshot.Pattern.SuccessWindowSeconds,
                snapshot.Pattern.GoodWindowSeconds);

            string beatCue = waitingForInput ? string.Empty : BuildActivePatternBeatCue(snapshot);
            if (!string.IsNullOrEmpty(beatCue))
            {
                timingWord = beatCue + " · " + timingWord;
            }

            string windowText = absoluteDelta <= snapshot.Pattern.SuccessWindowSeconds
                ? $"정확권 ±{snapshot.Pattern.SuccessWindowSeconds:0.00}s"
                : absoluteDelta <= snapshot.Pattern.GoodWindowSeconds
                    ? $"보정권 ±{snapshot.Pattern.GoodWindowSeconds:0.00}s"
                    : $"정확 ±{snapshot.Pattern.SuccessWindowSeconds:0.00}s";
            string practicePrefix = snapshot.PracticeMode
                ? "연습 " + Mathf.Clamp(snapshot.ChapterProgress + 1, 1, snapshot.ChapterTarget) + "/" + snapshot.ChapterTarget + " · "
                : string.Empty;
            return practicePrefix + FormatChannel(snapshot.Pattern.Channel)
                + " / " + BuildTrapResponseCueLabel(snapshot.Pattern)
                + " / " + timingWord
                + " / " + windowText;
        }

        private static string BuildTimingGuideWordFromValues(
            float coreDeltaSeconds,
            float centerHitWindowSeconds,
            float successWindowSeconds,
            float goodWindowSeconds)
        {
            float secondsToCore = -coreDeltaSeconds;
            float absoluteDelta = Mathf.Abs(coreDeltaSeconds);
            if (absoluteDelta <= centerHitWindowSeconds)
            {
                return "정박";
            }

            if (absoluteDelta <= successWindowSeconds)
            {
                return "지금 누르기";
            }

            if (coreDeltaSeconds < 0f && absoluteDelta <= goodWindowSeconds)
            {
                return "곧 정확권 " + secondsToCore.ToString("0.00") + "s";
            }

            if (coreDeltaSeconds > 0f && absoluteDelta <= goodWindowSeconds)
            {
                return "보정권 / 늦음 " + coreDeltaSeconds.ToString("0.00") + "s";
            }

            if (coreDeltaSeconds > goodWindowSeconds)
            {
                return "놓침 " + coreDeltaSeconds.ToString("0.00") + "s";
            }

            return "준비 " + secondsToCore.ToString("0.00") + "s";
        }

        private string GetCompactActiveActionCueText(
            GreedLastRunSnapshot snapshot,
            bool devToolsEnabled,
            bool rotationTiltAvailable)
        {
            if (!ShouldShowActiveActionCue(snapshot) || !snapshot.Pattern.IsValid)
                return string.Empty;

            GreedLastPatternModel pattern = snapshot.Pattern;
            int exactScore = BuildActiveExactScorePreview(snapshot);
            if (cachedCompactActionCue == null
                || cachedCompactActionPattern.PatternId != pattern.PatternId
                || cachedCompactActionPattern.Prompt != pattern.Prompt
                || cachedCompactActionPattern.Channel != pattern.Channel
                || cachedCompactActionPattern.TimingType != pattern.TimingType
                || cachedCompactActionPattern.AvoidanceType != pattern.AvoidanceType
                || cachedCompactActionExactScore != exactScore
                || cachedCompactActionDevTools != devToolsEnabled
                || cachedCompactActionRotationTilt != rotationTiltAvailable)
            {
                cachedCompactActionPattern = pattern;
                cachedCompactActionExactScore = exactScore;
                cachedCompactActionDevTools = devToolsEnabled;
                cachedCompactActionRotationTilt = rotationTiltAvailable;
                cachedCompactActionCue = BuildCompactActiveActionCueTextWithScore(
                    snapshot, devToolsEnabled, rotationTiltAvailable, exactScore);
            }
            return cachedCompactActionCue;
        }

        private static string BuildCompactActiveActionCueText(
            GreedLastRunSnapshot snapshot,
            bool devToolsEnabled,
            bool rotationTiltAvailable)
        {
            if (!ShouldShowActiveActionCue(snapshot) || !snapshot.Pattern.IsValid)
                return string.Empty;
            return BuildCompactActiveActionCueTextWithScore(
                snapshot, devToolsEnabled, rotationTiltAvailable, BuildActiveExactScorePreview(snapshot));
        }

        private static string BuildCompactActiveActionCueTextWithScore(
            GreedLastRunSnapshot snapshot,
            bool devToolsEnabled,
            bool rotationTiltAvailable,
            int exactScore)
        {
            if (!ShouldShowActiveActionCue(snapshot) || !snapshot.Pattern.IsValid)
                return string.Empty;

            string action = BuildTrapApproachLabel(snapshot.Pattern) + " → "
                + BuildRunnerResponseSymbol(snapshot.Pattern) + " " + BuildActiveActionResponseLabel(snapshot.Pattern);
            if (GreedLastRunCore.IsRotationPattern(snapshot.Pattern))
                action += " · " + BuildActiveActionCueInputHintForCapabilities(snapshot.Pattern, devToolsEnabled, rotationTiltAvailable);

            return action + "\n정박 +" + exactScore
                + " · " + BuildActiveTimingActionCuePayoffTag(snapshot);
        }

        private static string BuildActiveActionCueText(GreedLastRunSnapshot snapshot)
        {
            return BuildActiveActionCueTextForCapabilities(
                snapshot,
                DevToolsEnabled,
                IsRuntimeRotationTiltAvailable());
        }

        private static string BuildActiveActionCueTextForMode(GreedLastRunSnapshot snapshot, bool devToolsEnabled)
        {
            return BuildActiveActionCueTextForCapabilities(
                snapshot,
                devToolsEnabled,
                rotationTiltAvailable: true);
        }

        private static string BuildActiveActionCueTextForCapabilities(
            GreedLastRunSnapshot snapshot,
            bool devToolsEnabled,
            bool rotationTiltAvailable)
        {
            if (!ShouldShowActiveActionCue(snapshot) || !snapshot.Pattern.IsValid)
            {
                return string.Empty;
            }

            string symbol = BuildRunnerResponseSymbol(snapshot.Pattern);
            string label = BuildActiveActionResponseLabel(snapshot.Pattern);
            string action = string.IsNullOrEmpty(symbol) ? label : symbol + " " + label;
            string keyHint = BuildActiveActionCueInputHintForCapabilities(
                snapshot.Pattern,
                devToolsEnabled,
                rotationTiltAvailable);
            string beatCue = BuildActivePatternBeatCue(snapshot);
            if (beatCue == "지금 박")
            {
                beatCue = "지금";
            }

            string hazard = BuildTrapApproachLabel(snapshot.Pattern);
            string verb = BuildPatternActionVerb(snapshot.Pattern);
            string cue = string.IsNullOrEmpty(hazard)
                ? action + " " + verb
                : hazard + " 위험 → " + action + " " + verb;
            if (!string.IsNullOrEmpty(keyHint))
            {
                cue += " · " + keyHint;
            }

            if (!string.IsNullOrEmpty(beatCue))
            {
                cue += " · " + beatCue;
            }

            string payoff = BuildActiveActionCuePayoffText(snapshot);
            if (!string.IsNullOrEmpty(payoff))
            {
                cue += " · " + payoff;
            }

            return CompactUiText(cue, 72);
        }

        private static string BuildActiveActionCuePayoffText(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ActivePattern || !snapshot.Pattern.IsValid)
            {
                return string.Empty;
            }

            int exactScore = BuildActiveExactScorePreview(snapshot);
            int goodScore = BuildActiveGoodScorePreview(snapshot);
            if (exactScore <= 0 || goodScore <= 0)
            {
                return string.Empty;
            }

            string text = "정박+" + exactScore;
            string goalPayoff = BuildActivePrototypeActionCueGoalTag(snapshot);
            if (!string.IsNullOrEmpty(goalPayoff))
            {
                text += goalPayoff.StartsWith("→", StringComparison.Ordinal)
                    ? goalPayoff
                    : " " + goalPayoff;
            }

            string timingPayoff = BuildActiveTimingActionCuePayoffTag(snapshot);
            if (!string.IsNullOrEmpty(timingPayoff))
            {
                text += " " + timingPayoff;
            }

            string routePayoff = BuildActiveRouteActionCuePayoffTag(snapshot);
            if (!string.IsNullOrEmpty(routePayoff))
            {
                text += " " + routePayoff;
            }

            return text + " 보정+" + goodScore;
        }

        private static string BuildActivePrototypeActionCueGoalTag(GreedLastRunSnapshot snapshot)
        {
            string payoffGoal = BuildPrototypeFeelPayoffGoal(snapshot);
            if (string.IsNullOrEmpty(payoffGoal))
            {
                return string.Empty;
            }

            return "→" + payoffGoal;
        }

        private static string BuildActiveTimingActionCuePayoffTag(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.FocusStateActive && snapshot.Pattern.TimingType == GreedLastTimingType.Perfect && !IsRecoveryPattern(snapshot.Pattern))
                return BuildActiveFocusPayoffHint(snapshot);
            return BuildTimingActionPayoffTag(snapshot.Pattern);
        }

        private static string BuildActiveFocusPayoffHint(GreedLastRunSnapshot snapshot)
        {
            return GreedLastRunCore.BuildChoiceFocusRewardPreview(snapshot.Focus, snapshot.FocusStateRemainingSeconds, 1)
                .Replace("집중 상태 ", "집중 ");
        }

        private static string BuildResolvedFocusStateHint(GreedLastRunSnapshot snapshot)
        {
            return snapshot.LastJudgementFocusStateExtensionSeconds > 0.001f
                ? "집중 연장 +" + snapshot.LastJudgementFocusStateExtensionSeconds.ToString("0.00") + "s" : "집중 상한 유지";
        }

        private static string BuildTimingActionPayoffTag(GreedLastPatternModel pattern)
        {
            if (IsRecoveryPattern(pattern))
            {
                return "복구+" + GreedLastRunCore.RecoveryPrecisionScoreBonus;
            }

            switch (pattern.TimingType)
            {
                case GreedLastTimingType.Perfect:
                    return "집중+" + GreedLastRunCore.PerfectFocusChargeBonus;
                case GreedLastTimingType.Clutch:
                    return "반격+" + GreedLastRunCore.ClutchCounterScoreBonus;
                case GreedLastTimingType.Offbeat:
                    return "연쇄+" + GreedLastRunCore.OffbeatFlowComboBonus;
                default:
                    return string.Empty;
            }
        }

        private static string BuildActiveRouteActionCuePayoffTag(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.ActiveRouteProfile == "안정 루트")
            {
                return snapshot.GoodHealthGainPreview > 0
                    ? "보정회복+" + snapshot.GoodHealthGainPreview : string.Empty;
            }

            if (snapshot.ActiveRouteProfile == "변주 루트"
                && snapshot.Pattern.TimingType == GreedLastTimingType.Offbeat)
            {
                return snapshot.FocusStateActive ? "변주 " + BuildActiveFocusPayoffHint(snapshot)
                    : "변주집중+" + GreedLastRunCore.VariationRouteOffbeatFocusBonus;
            }

            if (snapshot.ActiveRouteProfile == "압박 루트"
                && snapshot.Pattern.TimingType == GreedLastTimingType.Clutch)
            {
                return "압박+" + GreedLastRunCore.PressureRouteClutchScoreBonus;
            }

            return string.Empty;
        }

        private static string BuildRunChannelKeyHint(GreedLastRunChannel channel)
        {
            return DevToolsEnabled ? BuildRunChannelInputHintForMode(channel, true) : string.Empty;
        }

        private static string BuildRunChannelInputHint(GreedLastRunChannel channel)
        {
            return BuildRunChannelInputHintForMode(channel, DevToolsEnabled);
        }

        private static string BuildRunChannelInputHintForMode(GreedLastRunChannel channel, bool devToolsEnabled)
        {
            switch (channel)
            {
                case GreedLastRunChannel.Left:
                    return devToolsEnabled ? "A/←" : "좌 탭";
                case GreedLastRunChannel.Center:
                    return devToolsEnabled ? "S/Space" : "중 탭";
                case GreedLastRunChannel.Right:
                    return devToolsEnabled ? "D/→" : "우 탭";
                default:
                    return string.Empty;
            }
        }

        private static string BuildActiveActionCueInputHintForMode(GreedLastPatternModel pattern, bool devToolsEnabled)
        {
            return BuildActiveActionCueInputHintForCapabilities(
                pattern,
                devToolsEnabled,
                rotationTiltAvailable: true);
        }

        private static string BuildActiveActionCueInputHintForCapabilities(
            GreedLastPatternModel pattern,
            bool devToolsEnabled,
            bool rotationTiltAvailable)
        {
            if (!GreedLastRunCore.IsRotationPattern(pattern))
            {
                return BuildRunChannelInputHintForMode(pattern.Channel, devToolsEnabled);
            }

            if (devToolsEnabled)
            {
                return BuildRotationInputHintForCapabilities(pattern, true, rotationTiltAvailable);
            }

            string rotationHint = BuildRotationInputHintForCapabilities(
                pattern,
                false,
                rotationTiltAvailable);
            if (string.IsNullOrEmpty(rotationHint))
            {
                return string.Empty;
            }

            return rotationTiltAvailable ? "중립→" + rotationHint : rotationHint;
        }

        private static string BuildRotationInputHintForMode(GreedLastPatternModel pattern, bool devToolsEnabled)
        {
            return BuildRotationInputHintForCapabilities(
                pattern,
                devToolsEnabled,
                rotationTiltAvailable: true);
        }

        private static string BuildRotationInputHintForCapabilities(
            GreedLastPatternModel pattern,
            bool devToolsEnabled,
            bool rotationTiltAvailable)
        {
            if (!GreedLastRunCore.IsRotationPattern(pattern))
            {
                return BuildRunChannelInputHintForMode(pattern.Channel, devToolsEnabled);
            }

            if (!devToolsEnabled && !rotationTiltAvailable)
            {
                return BuildRunChannelInputHintForMode(pattern.Channel, false);
            }

            if (pattern.Channel == GreedLastRunChannel.Left)
            {
                return devToolsEnabled ? "Q/A/←" : "좌 기울임";
            }

            if (pattern.Channel == GreedLastRunChannel.Right)
            {
                return devToolsEnabled ? "E/D/→" : "우 기울임";
            }

            return devToolsEnabled ? "Q/E" : "기울임";
        }

        private static bool IsRuntimeRotationTiltAvailable()
        {
            return Application.isMobilePlatform
                && SystemInfo.supportsAccelerometer
                && IsRotationTiltEnabledFromPrefs();
        }

        private static string BuildActivePatternBeatCue(GreedLastRunSnapshot snapshot)
        {
            if (!snapshot.ActivePattern || !snapshot.Pattern.IsValid)
            {
                return string.Empty;
            }

            return BuildActivePatternBeatCueFromValues(
                snapshot.CoreDeltaSeconds,
                snapshot.Pattern.SuccessWindowSeconds,
                snapshot.Pattern.GoodWindowSeconds,
                BuildBeatInterval(snapshot));
        }

        private static string BuildActivePatternBeatCueFromValues(
            float coreDeltaSeconds,
            float successWindowSeconds,
            float goodWindowSeconds,
            float beatIntervalSeconds)
        {
            float absoluteDelta = Mathf.Abs(coreDeltaSeconds);
            if (absoluteDelta <= successWindowSeconds)
            {
                return "지금 박";
            }

            if (coreDeltaSeconds > goodWindowSeconds)
            {
                return "지난 박";
            }

            if (coreDeltaSeconds > successWindowSeconds)
            {
                return "늦은 박";
            }

            if (coreDeltaSeconds > 0f)
            {
                return "조금 늦음";
            }

            float secondsToCore = Mathf.Max(0f, -coreDeltaSeconds);
            float beatInterval = Mathf.Max(0.01f, beatIntervalSeconds);
            if (secondsToCore <= beatInterval * 0.35f)
            {
                return "다음 박";
            }

            int beatsToCore = Mathf.Clamp(Mathf.CeilToInt(secondsToCore / beatInterval), 1, 4);
            switch (beatsToCore)
            {
                case 1: return "1박 전";
                case 2: return "2박 전";
                case 3: return "3박 전";
                default: return "4박 전";
            }
        }

        private static float BuildActiveBeatCueUrgency(GreedLastRunSnapshot snapshot)
        {
            if (!IsLiveRunControlWindow(snapshot)
                || !snapshot.ActivePattern
                || !snapshot.Pattern.IsValid)
            {
                return 0f;
            }

            return BuildActiveBeatCueUrgencyFromValues(
                snapshot.CoreDeltaSeconds,
                snapshot.Pattern.SuccessWindowSeconds,
                snapshot.Pattern.GoodWindowSeconds,
                BuildBeatInterval(snapshot));
        }

        private static float BuildActiveBeatCueUrgencyFromValues(
            float coreDeltaSeconds,
            float successWindowSeconds,
            float goodWindowSeconds,
            float beatIntervalSeconds)
        {
            float absoluteDelta = Mathf.Abs(coreDeltaSeconds);
            if (absoluteDelta <= successWindowSeconds)
            {
                return 1f;
            }

            if (absoluteDelta <= goodWindowSeconds)
            {
                float goodRange = Mathf.Max(0.01f, goodWindowSeconds);
                return Mathf.Lerp(0.72f, 0.92f, 1f - absoluteDelta / goodRange);
            }

            if (coreDeltaSeconds > 0f)
            {
                return 0f;
            }

            float secondsToCore = Mathf.Max(0f, -coreDeltaSeconds);
            float beatInterval = Mathf.Max(0.01f, beatIntervalSeconds);
            if (secondsToCore <= beatInterval)
            {
                return Mathf.Lerp(0.42f, 0.74f, 1f - secondsToCore / beatInterval);
            }

            if (secondsToCore <= beatInterval * 2f)
            {
                return Mathf.Lerp(0.18f, 0.36f, 1f - (secondsToCore - beatInterval) / beatInterval);
            }

            return 0.10f;
        }

        private static int BuildBeatCueUrgencyAlphaLift(float urgency)
        {
            return Mathf.RoundToInt(Mathf.Clamp01(urgency) * 14f);
        }

        private static float BuildBeatCueUrgencyScaleLift(float urgency)
        {
            return Mathf.Clamp01(urgency) * 0.018f;
        }

        private static float BuildBeatCueUrgencyColorBlend(float urgency)
        {
            return Mathf.Clamp01(urgency) * 0.14f;
        }

        private static string BuildRunnerResponseLabel(GreedLastPatternModel pattern)
        {
            if (GreedLastRunCore.IsRotationPattern(pattern))
            {
                return "회전";
            }

            return FormatRunnerResponseLabel(BuildRunnerResponseType(pattern));
        }

        private static string BuildActiveActionResponseLabel(GreedLastPatternModel pattern)
        {
            if (!GreedLastRunCore.IsRotationPattern(pattern))
            {
                return BuildRunnerResponseLabel(pattern);
            }

            return BuildRotationPatternDirection(pattern) < 0f ? "좌회전" : "우회전";
        }

        private static string FormatRunnerResponseLabel(RunnerResponseType response)
        {
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return "점프";
                case RunnerResponseType.Slide:
                    return "숙이기";
                case RunnerResponseType.Twist:
                    return "비틀기";
                default:
                    return "대응";
            }
        }

        private static string BuildRunnerResponseSymbol(GreedLastPatternModel pattern)
        {
            if (GreedLastRunCore.IsRotationPattern(pattern))
            {
                return BuildRotationPatternDirection(pattern) < 0f ? "⭯" : "⭮";
            }

            return FormatRunnerResponseSymbol(BuildRunnerResponseType(pattern));
        }

        private static string FormatRunnerResponseSymbol(RunnerResponseType response)
        {
            switch (response)
            {
                case RunnerResponseType.Jump:
                    return "↑";
                case RunnerResponseType.Slide:
                    return "↓";
                case RunnerResponseType.Twist:
                    return "↔";
                default:
                    return string.Empty;
            }
        }

        private static string BuildTrapResponseCueLabel(GreedLastPatternModel pattern)
        {
            string symbol = BuildRunnerResponseSymbol(pattern);
            string response = string.IsNullOrEmpty(symbol)
                ? BuildRunnerResponseLabel(pattern)
                : symbol + BuildRunnerResponseLabel(pattern);
            return BuildTrapApproachLabel(pattern) + "→" + response;
        }

        private static string BuildTrapApproachLabel(GreedLastPatternModel pattern)
        {
            if (GreedLastRunCore.IsRotationPattern(pattern))
            {
                return "통로";
            }

            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return "바닥";
                case RunnerResponseType.Slide:
                    return "상단";
                case RunnerResponseType.Twist:
                    return "측면";
                default:
                    return "위험";
            }
        }

        private static string BuildRunnerOutcomeLabel(GreedLastPatternModel pattern, GreedLastJudgementResult result)
        {
            string response = BuildTrapResponseCueLabel(pattern);
            if (GreedLastRunCore.IsRotationPattern(pattern))
            {
                switch (result)
                {
                    case GreedLastJudgementResult.Success:
                        return response + " 정렬";
                    case GreedLastJudgementResult.Good:
                        return response + " 보정 정렬";
                    case GreedLastJudgementResult.Miss:
                        return response + " 정렬 실패";
                    default:
                        return response;
                }
            }

            switch (result)
            {
                case GreedLastJudgementResult.Success:
                    return response + " 회피";
                case GreedLastJudgementResult.Good:
                    return response + " 보정";
                case GreedLastJudgementResult.Miss:
                    return response + " 실패";
                default:
                    return response;
            }
        }

        private static RunnerResponseType BuildRunnerResponseType(GreedLastPatternModel pattern)
        {
            switch (pattern.AvoidanceType)
            {
                case GreedLastAvoidanceType.Jump:
                    return RunnerResponseType.Jump;
                case GreedLastAvoidanceType.Slide:
                    return RunnerResponseType.Slide;
                case GreedLastAvoidanceType.Twist:
                    return RunnerResponseType.Twist;
            }

            string patternId = pattern.PatternId ?? string.Empty;
            if (ContainsPatternToken(patternId, "floor")
                || ContainsPatternToken(patternId, "sand")
                || ContainsPatternToken(patternId, "falsebeat")
                || ContainsPatternToken(patternId, "crack")
                || ContainsPatternToken(patternId, "threshold")
                || ContainsPatternToken(patternId, "weight")
                || ContainsPatternToken(patternId, "mirror")
                || ContainsPatternToken(patternId, "echo")
                || ContainsPatternToken(patternId, "scarab")
                || ContainsPatternToken(patternId, "vortex"))
            {
                return RunnerResponseType.Jump;
            }

            if (ContainsPatternToken(patternId, "drop")
                || ContainsPatternToken(patternId, "pillar")
                || ContainsPatternToken(patternId, "beam")
                || ContainsPatternToken(patternId, "gate")
                || ContainsPatternToken(patternId, "obelisk")
                || ContainsPatternToken(patternId, "guard")
                || ContainsPatternToken(patternId, "drum")
                || ContainsPatternToken(patternId, "pulse")
                || ContainsPatternToken(patternId, "chain"))
            {
                return RunnerResponseType.Slide;
            }

            return pattern.IsValid ? RunnerResponseType.Twist : RunnerResponseType.None;
        }

        private static bool ContainsPatternToken(string patternId, string token)
        {
            return patternId.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static float BuildCenterHitWindow(GreedLastPatternModel pattern)
        {
            return Mathf.Max(0.018f, pattern.SuccessWindowSeconds * CenterHitWindowScale);
        }

        private static Color32 GetTimingGuideColor(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.ResumeCountdownActive || (snapshot.StartCountdownActive && !snapshot.Paused))
            {
                return new Color32(255, 238, 181, 245);
            }

            if (snapshot.Paused)
            {
                return new Color32(125, 139, 143, 220);
            }

            if (!snapshot.ActivePattern)
            {
                return new Color32(125, 139, 143, 180);
            }

            if (ShouldWaitForCalibratedInput(snapshot))
            {
                return new Color32(105, 168, 190, 245);
            }

            float absoluteDelta = Mathf.Abs(snapshot.CoreDeltaSeconds);
            if (absoluteDelta <= BuildCenterHitWindow(snapshot.Pattern))
            {
                return new Color32(255, 248, 210, 255);
            }

            if (absoluteDelta <= snapshot.Pattern.SuccessWindowSeconds)
            {
                return new Color32(255, 238, 181, 255);
            }

            if (absoluteDelta <= snapshot.Pattern.GoodWindowSeconds)
            {
                return new Color32(105, 168, 190, 245);
            }

            if (snapshot.CoreDeltaSeconds > snapshot.Pattern.GoodWindowSeconds)
            {
                return new Color32(207, 87, 65, 235);
            }

            return new Color32(218, 226, 218, 220);
        }

        private static string BuildPrototypeRunnerArtStyleKey()
        {
            return "도깨비 소녀 실루엣";
        }

        private static string BuildPrototypeTrapArtStyleKey(GreedLastPatternModel pattern)
        {
            if (GreedLastRunCore.IsRotationPattern(pattern))
            {
                return "통로:금색-청록";
            }

            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    return "바닥:흙빛-금색";
                case RunnerResponseType.Slide:
                    return "상단:청록";
                case RunnerResponseType.Twist:
                    return "측면:주홍";
                default:
                    return "기본:금색";
            }
        }

        private static string BuildPatternActionVerb(GreedLastPatternModel pattern)
        {
            return GreedLastRunCore.IsRotationPattern(pattern) ? "정렬" : "회피";
        }

        private static Color32 BuildPrototypeTrapBaseColor(GreedLastPatternModel pattern)
        {
            if (GreedLastRunCore.IsRotationPattern(pattern))
            {
                return Color32.Lerp(PrototypeGoldColor, PrototypeTealColor, 0.38f);
            }

            Color32 responseColor;
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    responseColor = new Color32(156, 83, 55, 255);
                    break;
                case RunnerResponseType.Slide:
                    responseColor = PrototypeTealColor;
                    break;
                case RunnerResponseType.Twist:
                    responseColor = PrototypeVermilionColor;
                    break;
                default:
                    responseColor = PrototypeGoldColor;
                    break;
            }

            return Color32.Lerp(responseColor, GetTrapBaseColor(pattern.TimingType), 0.28f);
        }

        private static Color32 BuildPrototypeTrapAccentColor(GreedLastPatternModel pattern)
        {
            if (GreedLastRunCore.IsRotationPattern(pattern))
            {
                return Color32.Lerp(new Color32(255, 238, 181, 255), PrototypeTealColor, 0.26f);
            }

            Color32 responseAccent;
            switch (BuildRunnerResponseType(pattern))
            {
                case RunnerResponseType.Jump:
                    responseAccent = PrototypeGoldColor;
                    break;
                case RunnerResponseType.Slide:
                    responseAccent = new Color32(168, 226, 215, 255);
                    break;
                case RunnerResponseType.Twist:
                    responseAccent = new Color32(255, 150, 119, 255);
                    break;
                default:
                    responseAccent = PrototypeGoldColor;
                    break;
            }

            return Color32.Lerp(responseAccent, GetTrapAccentColor(pattern.TimingType), 0.34f);
        }

        private static Color32 GetTrapBaseColor(GreedLastTimingType timingType)
        {
            switch (timingType)
            {
                case GreedLastTimingType.Perfect:
                    return new Color32(211, 174, 76, 255);
                case GreedLastTimingType.Clutch:
                    return new Color32(207, 87, 65, 255);
                case GreedLastTimingType.Offbeat:
                    return new Color32(95, 153, 171, 255);
                default:
                    return new Color32(207, 87, 65, 255);
            }
        }

        private static Color32 GetTrapAccentColor(GreedLastTimingType timingType)
        {
            switch (timingType)
            {
                case GreedLastTimingType.Perfect:
                    return new Color32(255, 238, 181, 255);
                case GreedLastTimingType.Clutch:
                    return new Color32(255, 169, 118, 255);
                case GreedLastTimingType.Offbeat:
                    return new Color32(168, 220, 226, 255);
                default:
                    return new Color32(255, 238, 181, 255);
            }
        }

        private static float GetTrapStrikeAngle(GreedLastTimingType timingType)
        {
            switch (timingType)
            {
                case GreedLastTimingType.Clutch:
                    return -18f;
                case GreedLastTimingType.Offbeat:
                    return 22f;
                default:
                    return 0f;
            }
        }

        private static Color32 WithAlpha(Color32 color, int alpha)
        {
            color.a = (byte)Mathf.Clamp(alpha, 0, 255);
            return color;
        }

        private void UpdateLaneLabels(GreedLastRunSnapshot snapshot)
        {
            if (laneLabelTexts == null || laneLabelTexts.Length < 3)
            {
                return;
            }

            bool cleanHeader = (!DevToolsEnabled || devCleanViewEnabled) && !snapshot.ChoiceActive;
            for (int i = 0; i < laneImages.Length; i++)
            {
                laneImages[i].rectTransform.sizeDelta = snapshot.ChoiceActive
                    ? new Vector2(440f, 410f) : new Vector2(195f, 520f);
                laneHitButtons[i].GetComponent<RectTransform>().sizeDelta = snapshot.ChoiceActive
                    ? new Vector2(460f, 430f) : new Vector2(230f, 580f);
                SetLaneLabelRect(laneLabelTexts[i], cleanHeader);
            }

            if (snapshot.ChoiceActive)
            {
                SetLaneLabelMode(38, true);
                laneLabelTexts[0].text = BuildChoiceLaneLabel(snapshot, snapshot.ChoiceLeft);
                laneLabelTexts[1].text = BuildChoiceLaneLabel(snapshot, snapshot.ChoiceCenter);
                laneLabelTexts[2].text = BuildChoiceLaneLabel(snapshot, snapshot.ChoiceRight);
                return;
            }

            if (cleanHeader)
            {
                int target = snapshot.ActivePattern && !snapshot.Paused && !snapshot.CountdownActive && !snapshot.Stopped
                    ? Mathf.Clamp((int)snapshot.Pattern.Channel - 1, 0, 2) : -1;
                SetLaneLabelMode(36, false);
                for (int i = 0; i < laneLabelTexts.Length; i++)
                {
                    laneLabelTexts[i].text = BuildCleanRunLaneLabel(i, i == target ? snapshot.Pattern : default,
                        DevToolsEnabled, IsRuntimeRotationTiltAvailable());
                }
                SetRunLaneLabelColors(target, snapshot);
                return;
            }

            if (!snapshot.ActivePattern || snapshot.Paused || snapshot.CountdownActive || snapshot.Stopped)
            {
                SetLaneLabelMode(DevToolsEnabled ? 38 : 56, DevToolsEnabled);
                laneLabelTexts[0].text = BuildRunLaneBaseLabel(0, compact: false);
                laneLabelTexts[1].text = BuildRunLaneBaseLabel(1, compact: false);
                laneLabelTexts[2].text = BuildRunLaneBaseLabel(2, compact: false);
                SetRunLaneLabelColors(-1, snapshot);
                return;
            }

            int targetIndex = Mathf.Clamp((int)snapshot.Pattern.Channel - 1, 0, 2);
            string timingHint = BuildLaneTimingHint(snapshot);
            string responseHint = BuildLaneResponseHint(snapshot);
            laneLabelTexts[0].text = targetIndex == 0
                ? BuildRunLaneBaseLabel(0, compact: true) + "\n" + responseHint + "\n" + timingHint
                : BuildRunLaneBaseLabel(0, compact: false);
            laneLabelTexts[1].text = targetIndex == 1
                ? BuildRunLaneBaseLabel(1, compact: true) + "\n" + responseHint + "\n" + timingHint
                : BuildRunLaneBaseLabel(1, compact: false);
            laneLabelTexts[2].text = targetIndex == 2
                ? BuildRunLaneBaseLabel(2, compact: true) + "\n" + responseHint + "\n" + timingHint
                : BuildRunLaneBaseLabel(2, compact: false);
            SetLaneLabelMode(34, true);
            Text targetLabel = laneLabelTexts[targetIndex];
            targetLabel.resizeTextForBestFit = false;
            while (targetLabel.fontSize > 20 && !FeedbackTextFitsBounds(targetLabel))
                targetLabel.fontSize -= 1;
            SetRunLaneLabelColors(targetIndex, snapshot);
        }

        private static string BuildRunLaneBaseLabel(int laneIndex, bool compact)
        {
            return BuildRunLaneBaseLabelForMode(laneIndex, compact, DevToolsEnabled);
        }

        private static string BuildCleanRunLaneLabel(int laneIndex, GreedLastPatternModel pattern,
            bool devToolsEnabled, bool rotationTiltAvailable)
        {
            if (laneIndex >= 0 && laneIndex < 3 && pattern.IsValid
                && (int)pattern.Channel == laneIndex + 1 && GreedLastRunCore.IsRotationPattern(pattern)
                && (devToolsEnabled || rotationTiltAvailable))
            {
                string direction = laneIndex == 0 ? "좌" : laneIndex == 1 ? "중" : "우";
                return direction + "\n" + BuildActiveActionCueInputHintForCapabilities(pattern,
                    devToolsEnabled, rotationTiltAvailable);
            }

            return BuildRunLaneBaseLabelForMode(laneIndex, false, devToolsEnabled);
        }

        private static void SetLaneLabelRect(Text label, bool header)
        {
            RectTransform rect = label.rectTransform;
            rect.pivot = new Vector2(0.5f, 0.5f);
            if (header)
            {
                rect.anchorMin = rect.anchorMax = new Vector2(0.5f, 1.15f);
                rect.sizeDelta = new Vector2(360f, 112f);
                rect.anchoredPosition = Vector2.zero;
            }
            else
            {
                rect.anchorMin = Vector2.zero;
                rect.anchorMax = Vector2.one;
                rect.offsetMin = new Vector2(12f, 12f);
                rect.offsetMax = new Vector2(-12f, -12f);
            }
        }

        private static string BuildRunLaneBaseLabelForMode(int laneIndex, bool compact, bool devToolsEnabled)
        {
            string label;
            string keyHint;
            switch (laneIndex)
            {
                case 0:
                    label = "좌";
                    keyHint = "A/←";
                    break;
                case 1:
                    label = "중";
                    keyHint = "S/Space";
                    break;
                case 2:
                    label = "우";
                    keyHint = "D/→";
                    break;
                default:
                    label = "-";
                    keyHint = string.Empty;
                    break;
            }

            if (string.IsNullOrEmpty(keyHint))
            {
                return label;
            }

            if (!devToolsEnabled)
            {
                return compact ? label + " 탭" : label + "\n탭";
            }

            return compact ? label + " " + keyHint : label + "\n" + keyHint;
        }

        private static string BuildLaneResponseHint(GreedLastRunSnapshot snapshot)
        {
            string responseHint = BuildTrapResponseCueLabel(snapshot.Pattern);
            string payoffHint = string.Empty;
            if (IsRecoveryPattern(snapshot.Pattern))
            {
                payoffHint = "복구+" + GreedLastRunCore.RecoveryPrecisionScoreBonus;
            }
            else if (snapshot.Pattern.TimingType == GreedLastTimingType.Perfect)
            {
                payoffHint = snapshot.FocusStateActive ? BuildActiveFocusPayoffHint(snapshot)
                    : "충전+" + GreedLastRunCore.PerfectFocusChargeBonus;
            }
            else if (snapshot.Pattern.TimingType == GreedLastTimingType.Clutch)
            {
                payoffHint = "반격+" + GreedLastRunCore.ClutchCounterScoreBonus;
            }
            else if (snapshot.Pattern.TimingType == GreedLastTimingType.Offbeat)
            {
                payoffHint = "연쇄+" + GreedLastRunCore.OffbeatFlowComboBonus;
            }

            return string.IsNullOrEmpty(payoffHint)
                ? responseHint
                : responseHint + " · 정확→" + payoffHint;
        }

        private void SetRunLaneLabelColors(int targetIndex, GreedLastRunSnapshot snapshot)
        {
            for (int i = 0; i < laneLabelTexts.Length; i += 1)
            {
                Text label = laneLabelTexts[i];
                if (label == null)
                {
                    continue;
                }

                label.color = BuildRunLaneLabelColor(i, targetIndex, snapshot);
            }
        }

        private static Color32 BuildRunLaneLabelColor(int laneIndex, int targetIndex, GreedLastRunSnapshot snapshot)
        {
            if (targetIndex < 0)
            {
                return new Color32(218, 226, 218, 230);
            }

            Color32 baseColor = laneIndex == targetIndex
                ? GetTimingGuideColor(snapshot)
                : new Color32(125, 139, 143, 170);
            if (laneIndex == targetIndex
                && TryGetPatternVariationAccent(snapshot.Pattern, out Color32 variationColor, out float variationStrength))
            {
                return Color32.Lerp(baseColor, variationColor, variationStrength * 0.58f);
            }

            return baseColor;
        }

        private static string BuildLaneTimingHint(GreedLastRunSnapshot snapshot)
        {
            if (ShouldWaitForCalibratedInput(snapshot)) return "보정 대기";
            float absoluteDelta = Mathf.Abs(snapshot.CoreDeltaSeconds);
            string beatCue = BuildActivePatternBeatCue(snapshot);
            if (absoluteDelta <= BuildCenterHitWindow(snapshot.Pattern))
            {
                return "정박";
            }

            if (absoluteDelta <= snapshot.Pattern.SuccessWindowSeconds)
            {
                return "누르기";
            }

            if (absoluteDelta <= snapshot.Pattern.GoodWindowSeconds)
            {
                string goodHint = snapshot.CoreDeltaSeconds < 0f
                    ? "곧 " + FormatLaneTimingSeconds(-snapshot.CoreDeltaSeconds)
                    : "늦음 " + FormatLaneTimingSeconds(snapshot.CoreDeltaSeconds);
                return AppendLaneBeatCue(goodHint, beatCue);
            }

            if (snapshot.CoreDeltaSeconds > snapshot.Pattern.GoodWindowSeconds)
            {
                return "놓침";
            }

            return string.IsNullOrEmpty(beatCue) || beatCue == "지금 박" || beatCue == "지난 박" || beatCue == "늦은 박"
                ? "대기 " + FormatLaneTimingSeconds(-snapshot.CoreDeltaSeconds)
                : beatCue;
        }

        private static string AppendLaneBeatCue(string timingHint, string beatCue)
        {
            if (string.IsNullOrEmpty(beatCue) || beatCue == "지금 박")
            {
                return timingHint;
            }

            return timingHint.Contains(beatCue, StringComparison.Ordinal)
                ? timingHint
                : timingHint + " · " + beatCue;
        }

        private static string FormatLaneTimingSeconds(float seconds)
        {
            return Mathf.Max(0f, seconds).ToString("0.00");
        }

        private static string BuildChoiceLaneLabel(GreedLastRunSnapshot snapshot, string choiceName)
        {
            string hint = BuildChoiceLaneHint(snapshot, choiceName);
            string text = string.IsNullOrEmpty(hint)
                ? choiceName
                : choiceName + "\n" + hint;
            return IsRecommendedChoice(snapshot, choiceName)
                ? text + "\n" + BuildChoiceLaneRecommendationText(snapshot, choiceName)
                : text;
        }

        private static string BuildChoiceLaneHint(GreedLastRunSnapshot snapshot, string choiceName)
        {
            if (snapshot.ChoiceKind == GreedLastChoiceKind.Node && IsRouteChoiceName(choiceName))
            {
                string reward = choiceName == "안정 루트" ? BuildCurrentChoiceHealthHint(snapshot) + " / Good 회복"
                    : choiceName == "변주 루트" ? BuildCurrentChoiceFocusHint(snapshot, 1) + " / 엇박 공명"
                    : BuildRouteChoiceRewardText(choiceName);
                return reward + "\n" + BuildRouteCadenceText(choiceName)
                    + " / " + BuildAvoidanceCadenceText(choiceName, false, -1);
            }
            return BuildCurrentChoiceEffectHint(snapshot, choiceName);
        }

        private static string BuildCurrentChoiceHealthHint(GreedLastRunSnapshot snapshot)
        {
            return snapshot.ChoiceHealthGainPreview > 0
                ? "체력 +" + snapshot.ChoiceHealthGainPreview : "체력 상한 유지";
        }

        private static string BuildCurrentChoiceFocusHint(GreedLastRunSnapshot snapshot, int amount)
        {
            return GreedLastRunCore.BuildChoiceFocusRewardPreview(snapshot.Focus, snapshot.FocusStateRemainingSeconds, amount);
        }

        private static string BuildCurrentChoiceEffectHint(GreedLastRunSnapshot snapshot, string choiceName)
        {
            switch (choiceName)
            {
                case "박자 감각": return BuildCurrentChoiceFocusHint(snapshot, 1);
                case "안정 호흡": return BuildCurrentChoiceHealthHint(snapshot);
                case "안정 루트": return BuildRouteChoiceEffectHint(BuildCurrentChoiceHealthHint(snapshot) + "/Good 회복", choiceName);
                case "변주 루트": return BuildRouteChoiceEffectHint(BuildCurrentChoiceFocusHint(snapshot, 1) + "/엇박 공명", choiceName);
                case "집중 축": return BuildCurrentChoiceFocusHint(snapshot, 2) + "/정확 누적";
                case "생존 축": return BuildCurrentChoiceHealthHint(snapshot) + "/보정 회복";
                case "사막의 잔상": return BuildCurrentChoiceHealthHint(snapshot) + "/" + BuildCurrentChoiceFocusHint(snapshot, 1);
                case "파라오의 각인": return "콤보+3/" + BuildCurrentChoiceFocusHint(snapshot, 3) + "/연쇄 증폭";
                default: return BuildChoiceEffectHint(snapshot.ChoiceKind, choiceName);
            }
        }

        private static string BuildChoiceLaneRecommendationText(GreedLastRunSnapshot snapshot, string choiceName)
        {
            string reason = BuildChoiceRecommendationReasonText(snapshot, choiceName);
            return string.IsNullOrEmpty(reason)
                ? "추천"
                : "추천\n" + reason;
        }

        private static string GetChoiceNameForLane(GreedLastRunSnapshot snapshot, int laneIndex)
        {
            switch (laneIndex)
            {
                case 0:
                    return snapshot.ChoiceLeft;
                case 1:
                    return snapshot.ChoiceCenter;
                case 2:
                    return snapshot.ChoiceRight;
                default:
                    return string.Empty;
            }
        }

        private static string BuildChoiceEffectHint(GreedLastChoiceKind kind, string choiceName)
        {
            switch (choiceName)
            {
                case "박자 감각":
                    return "집중 +1";
                case "안정 호흡":
                    return "체력 +1";
                case "고점 본능":
                    return "점수 +80";
                case "안정 루트":
                    return BuildRouteChoiceEffectHint(BuildRouteChoiceRewardText(choiceName), choiceName);
                case "변주 루트":
                    return BuildRouteChoiceEffectHint(BuildRouteChoiceRewardText(choiceName), choiceName);
                case "압박 루트":
                    return BuildRouteChoiceEffectHint(BuildRouteChoiceRewardText(choiceName), choiceName);
                case "집중 축":
                    return "집중+2/정확 누적";
                case "생존 축":
                    return "체력+1/보정 회복";
                case "연쇄 축":
                    return "콤보+2/정확 연쇄";
                case "황금 박동":
                    return "점수 +200";
                case "사막의 잔상":
                    return "체력+1/집중+1";
                case "파라오의 각인":
                    return "콤보+3/연쇄 증폭";
                default:
                    return kind == GreedLastChoiceKind.None ? string.Empty : "기본 유지";
            }
        }

        private static string BuildRouteChoiceRewardText(string choiceName)
        {
            switch (choiceName)
            {
                case "안정 루트":
                    return "Good 체력+" + GreedLastRunCore.StableRouteGoodHealthBonus;
                case "변주 루트":
                    return "엇박 집중+" + GreedLastRunCore.VariationRouteOffbeatFocusBonus;
                case "압박 루트":
                    return "Clutch +" + GreedLastRunCore.PressureRouteClutchScoreBonus;
                default:
                    return "기본 유지";
            }
        }

        private static string BuildRouteChoiceEffectHint(string rewardText, string choiceName)
        {
            return rewardText + "/" + BuildRouteCadenceText(choiceName) + "/" + BuildAvoidanceCadenceText(choiceName, false, -1);
        }

        private static Color32 BuildChoiceLaneTextColor(GreedLastRunSnapshot snapshot, int laneIndex)
        {
            string choiceName = GetChoiceNameForLane(snapshot, laneIndex);
            if (IsRecommendedChoice(snapshot, choiceName))
            {
                return new Color32(255, 238, 181, 255);
            }

            switch (BuildChoiceEffectGroup(choiceName))
            {
                case "health":
                    return new Color32(172, 230, 204, 255);
                case "focus":
                    return new Color32(178, 232, 238, 255);
                case "score":
                    return new Color32(255, 238, 181, 255);
                case "combo":
                    return new Color32(255, 197, 156, 255);
                case "hybrid":
                    return new Color32(204, 226, 196, 255);
                default:
                    return new Color32(218, 226, 218, 230);
            }
        }

        private static Color32 BuildChoiceLaneColumnColor(GreedLastRunSnapshot snapshot, int laneIndex, float lanePulse)
        {
            string choiceName = GetChoiceNameForLane(snapshot, laneIndex);
            bool recommended = IsRecommendedChoice(snapshot, choiceName);
            Color32 baseColor;
            switch (BuildChoiceEffectGroup(choiceName))
            {
                case "health":
                    baseColor = new Color32(28, 70, 58, 232);
                    break;
                case "focus":
                    baseColor = new Color32(29, 67, 84, 232);
                    break;
                case "score":
                    baseColor = new Color32(95, 72, 28, 232);
                    break;
                case "combo":
                    baseColor = new Color32(92, 52, 39, 232);
                    break;
                case "hybrid":
                    baseColor = new Color32(47, 76, 56, 232);
                    break;
                default:
                    baseColor = new Color32(32, 42, 49, 255);
                    break;
            }

            Color32 pulseColor = recommended
                ? new Color32(154, 112, 48, 255)
                : new Color32(82, 93, 91, 242);
            return Color32.Lerp(baseColor, pulseColor, recommended ? 0.34f + lanePulse * 0.18f : lanePulse * 0.22f);
        }

        private static bool IsRecommendedChoice(GreedLastRunSnapshot snapshot, string choiceName)
        {
            return !string.IsNullOrEmpty(choiceName)
                && choiceName == BuildRecommendedChoiceName(snapshot);
        }

        private static string BuildRecommendedChoiceName(GreedLastRunSnapshot snapshot)
        {
            string retryChoice = FindChoiceByRetryOpeningContext(snapshot);
            if (!string.IsNullOrEmpty(retryChoice))
            {
                return retryChoice;
            }

            if (snapshot.Health <= Mathf.Max(1, Mathf.CeilToInt(snapshot.MaxHealth * 0.45f)))
            {
                string survivalChoice = FindChoiceByEffectGroup(snapshot, "health", "hybrid");
                if (!string.IsNullOrEmpty(survivalChoice))
                {
                    return survivalChoice;
                }
            }

            string segmentChoice = FindNodeChoiceBySegmentPerformance(snapshot);
            if (!string.IsNullOrEmpty(segmentChoice))
            {
                return segmentChoice;
            }

            if (!snapshot.FocusStateActive && snapshot.Focus <= 1)
            {
                string focusChoice = FindChoiceByEffectGroup(snapshot, "focus", "hybrid");
                if (!string.IsNullOrEmpty(focusChoice))
                {
                    return focusChoice;
                }
            }

            if (snapshot.PrecisionStreak >= 3)
            {
                string precisionChoice = FindChoiceByEffectGroup(snapshot, "score", "combo");
                if (!string.IsNullOrEmpty(precisionChoice))
                {
                    return precisionChoice;
                }
            }

            if (snapshot.Combo >= 4)
            {
                string comboChoice = FindChoiceByEffectGroup(snapshot, "combo");
                if (!string.IsNullOrEmpty(comboChoice))
                {
                    return comboChoice;
                }
            }

            if (snapshot.Score < 300)
            {
                string scoreChoice = FindChoiceByEffectGroup(snapshot, "score");
                if (!string.IsNullOrEmpty(scoreChoice))
                {
                    return scoreChoice;
                }
            }

            string profileChoice = FindChoiceByActiveProfile(snapshot);
            if (!string.IsNullOrEmpty(profileChoice))
            {
                return profileChoice;
            }

            return string.Empty;
        }

        private static string BuildRecommendedChoiceReasonSuffix(GreedLastRunSnapshot snapshot, string choiceName)
        {
            if (string.IsNullOrEmpty(choiceName))
            {
                return string.Empty;
            }

            if (choiceName == FindChoiceByRetryOpeningContext(snapshot))
            {
                return BuildRetryChoiceReasonSuffix(snapshot);
            }

            string effectGroup = BuildChoiceEffectGroup(choiceName);
            if ((effectGroup == "health" || effectGroup == "hybrid")
                && snapshot.Health <= Mathf.Max(1, Mathf.CeilToInt(snapshot.MaxHealth * 0.45f)))
            {
                return " / 체력 보완";
            }

            if (snapshot.ChoiceKind == GreedLastChoiceKind.Node
                && choiceName == FindNodeChoiceBySegmentPerformance(snapshot))
            {
                if (snapshot.LastCompletedSegmentMissCount > 0)
                {
                    return " / 직전 실수 안정화 · " + BuildRouteCadenceText(choiceName);
                }

                if (choiceName == "변주 루트"
                    && snapshot.ActiveRouteProfile == "안정 루트")
                {
                    return snapshot.LastCompletedSegmentGoodCount > 0
                        ? " / 안정 흐름 확장 · " + BuildRouteCadenceText(choiceName)
                        : " / 안정 졸업 변주 · " + BuildRouteCadenceText(choiceName);
                }

                if (snapshot.LastCompletedSegmentGoodCount > 0)
                {
                    return " / 보정 정확 전환 · " + BuildRouteCadenceText(choiceName);
                }

                if (snapshot.LastCompletedSegmentExactCount >= 3)
                {
                    return " / 완전 정확 고점 · " + BuildRouteCadenceText(choiceName);
                }
            }

            if ((effectGroup == "focus" || effectGroup == "hybrid") && !snapshot.FocusStateActive && snapshot.Focus <= 1)
            {
                return " / 집중 회복";
            }

            if ((effectGroup == "score" || effectGroup == "combo") && snapshot.PrecisionStreak >= 3)
            {
                return " / 정박 고점";
            }

            if (effectGroup == "combo" && snapshot.Combo >= 4)
            {
                return " / 연쇄 유지";
            }

            if (effectGroup == "score" && snapshot.Score < 300)
            {
                return " / 초반 점수";
            }

            if (choiceName == FindChoiceByActiveProfile(snapshot))
            {
                return " / 조합 연계";
            }

            return string.Empty;
        }

        private static string BuildRouteCadenceText(string choiceName)
        {
            switch (choiceName)
            {
                case "안정 루트":
                    return "정-압-정";
                case "변주 루트":
                    return "엇-정-엇";
                case "압박 루트":
                    return "압-엇-압";
                default:
                    return "3박";
            }
        }

        private static string BuildRetryChoiceReasonSuffix(GreedLastRunSnapshot snapshot)
        {
            string text = snapshot.JudgementText ?? string.Empty;
            if (text.Contains("복기 목표:", StringComparison.Ordinal))
            {
                if (text.Contains("실패", StringComparison.Ordinal))
                {
                    return " / 복기 실패 보완";
                }

                if (text.Contains("달성", StringComparison.Ordinal))
                {
                    return text.Contains("재도전 목표:", StringComparison.Ordinal)
                        || text.Contains("목표:", StringComparison.Ordinal)
                        ? " / 목표 상향"
                        : " / 복기 달성 연장";
                }

                if (text.Contains("진행", StringComparison.Ordinal))
                {
                    return " / 복기 진행";
                }
            }

            return " / 복기 목표";
        }

        private static string FindNodeChoiceBySegmentPerformance(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.ChoiceKind != GreedLastChoiceKind.Node
                || string.IsNullOrEmpty(snapshot.LastCompletedSegment))
            {
                return string.Empty;
            }

            if (snapshot.LastCompletedSegmentMissCount > 0)
            {
                return FindChoiceByEffectGroup(snapshot, "health", "hybrid");
            }

            if (snapshot.LastCompletedSegmentGoodCount > 0)
            {
                return snapshot.ActiveRouteProfile == "안정 루트"
                    ? FindChoiceByEffectGroup(snapshot, "focus", "hybrid")
                    : FindChoiceByEffectGroup(snapshot, "health", "hybrid");
            }

            if (snapshot.LastCompletedSegmentExactCount >= 3
                && snapshot.ActiveRouteProfile == "안정 루트")
            {
                return FindChoiceByEffectGroup(snapshot, "focus", "hybrid");
            }

            return snapshot.LastCompletedSegmentExactCount >= 3
                ? FindChoiceByEffectGroup(snapshot, "combo", "score")
                : string.Empty;
        }

        private static string FindChoiceByRetryOpeningContext(GreedLastRunSnapshot snapshot)
        {
            if (snapshot.ChoiceKind != GreedLastChoiceKind.StartGift
                || string.IsNullOrWhiteSpace(snapshot.JudgementText)
                || (!snapshot.JudgementText.Contains("복기 재도전", StringComparison.Ordinal)
                    && !snapshot.JudgementText.Contains("재도전 목표:", StringComparison.Ordinal)))
            {
                return string.Empty;
            }

            string text = snapshot.JudgementText.Replace("\r", string.Empty);
            if (text.Contains("복기 목표:", StringComparison.Ordinal))
            {
                if (text.Contains("실패 실수", StringComparison.Ordinal))
                {
                    return FindChoiceByEffectGroup(snapshot, "health", "hybrid");
                }

                if (text.Contains("실패 보정", StringComparison.Ordinal))
                {
                    return FindChoiceByEffectGroup(snapshot, "focus", "hybrid");
                }

                if (text.Contains("진행", StringComparison.Ordinal)
                    && (text.Contains("점", StringComparison.Ordinal)
                        || text.Contains("콤보", StringComparison.Ordinal)
                        || text.Contains("고점", StringComparison.Ordinal)))
                {
                    return FindChoiceByEffectGroup(snapshot, "score", "combo");
                }
            }

            if (text.Contains("보정 0회", StringComparison.Ordinal)
                || text.Contains("정확권", StringComparison.Ordinal)
                || text.Contains("빠른 입력", StringComparison.Ordinal)
                || text.Contains("늦은 입력", StringComparison.Ordinal)
                || text.Contains("타이밍", StringComparison.Ordinal)
                || text.Contains("정박", StringComparison.Ordinal))
            {
                return FindChoiceByEffectGroup(snapshot, "focus", "hybrid");
            }

            if (text.Contains("콤보", StringComparison.Ordinal)
                || text.Contains("점수", StringComparison.Ordinal)
                || text.Contains("고점", StringComparison.Ordinal)
                || text.Contains("점 탈출", StringComparison.Ordinal)
                || text.Contains("점 /", StringComparison.Ordinal))
            {
                return FindChoiceByEffectGroup(snapshot, "score", "combo");
            }

            if (text.Contains("무실수", StringComparison.Ordinal)
                || text.Contains("체력", StringComparison.Ordinal)
                || text.Contains("생존", StringComparison.Ordinal)
                || text.Contains("채널 확인", StringComparison.Ordinal)
                || text.Contains("입력 없음", StringComparison.Ordinal)
                || text.Contains("보충", StringComparison.Ordinal))
            {
                return FindChoiceByEffectGroup(snapshot, "health", "hybrid");
            }

            return string.Empty;
        }

        private static string BuildChoiceRecommendationReasonText(GreedLastRunSnapshot snapshot, string choiceName)
        {
            string suffix = BuildRecommendedChoiceReasonSuffix(snapshot, choiceName);
            return suffix.StartsWith(" / ", StringComparison.Ordinal)
                ? suffix.Substring(3)
                : suffix;
        }

        private static string FindChoiceByEffectGroup(GreedLastRunSnapshot snapshot, string primaryGroup, string fallbackGroup = null)
        {
            string left = MatchChoiceEffectGroup(snapshot.ChoiceLeft, primaryGroup, fallbackGroup);
            if (!string.IsNullOrEmpty(left))
            {
                return left;
            }

            string center = MatchChoiceEffectGroup(snapshot.ChoiceCenter, primaryGroup, fallbackGroup);
            if (!string.IsNullOrEmpty(center))
            {
                return center;
            }

            return MatchChoiceEffectGroup(snapshot.ChoiceRight, primaryGroup, fallbackGroup);
        }

        private static string FindChoiceByActiveProfile(GreedLastRunSnapshot snapshot)
        {
            switch (snapshot.ActiveChoiceProfile)
            {
                case "안정형":
                    return FindChoiceByEffectGroup(snapshot, "health", "hybrid");
                case "집중형":
                    return FindChoiceByEffectGroup(snapshot, "focus", "hybrid");
                case "연쇄형":
                    return FindChoiceByEffectGroup(snapshot, "combo");
                case "고점형":
                    return FindChoiceByEffectGroup(snapshot, "score", "combo");
                default:
                    return string.Empty;
            }
        }

        private static string MatchChoiceEffectGroup(string choiceName, string primaryGroup, string fallbackGroup)
        {
            string effectGroup = BuildChoiceEffectGroup(choiceName);
            return effectGroup == primaryGroup || (!string.IsNullOrEmpty(fallbackGroup) && effectGroup == fallbackGroup)
                ? choiceName
                : string.Empty;
        }

        private static string BuildChoiceEffectGroup(string choiceName)
        {
            switch (choiceName)
            {
                case "안정 호흡":
                case "안정 루트":
                case "생존 축":
                    return "health";
                case "박자 감각":
                case "변주 루트":
                case "집중 축":
                    return "focus";
                case "고점 본능":
                case "황금 박동":
                    return "score";
                case "압박 루트":
                case "연쇄 축":
                case "파라오의 각인":
                    return "combo";
                case "사막의 잔상":
                    return "hybrid";
                default:
                    return string.Empty;
            }
        }

        private void UpdateSaveSlotLabels(
            int selectedSlotIndex,
            string[] slotLabels,
            bool[] slotUsable,
            bool[] slotOccupied,
            bool showUsability,
            bool canSaveCandidate)
        {
            if (laneLabelTexts == null || laneLabelTexts.Length < 3)
            {
                return;
            }

            SetLaneLabelMode(showUsability ? 30 : 32, true);
            bool slotChoiceRequired = selectedSlotIndex < 0;
            bool noRefillSourceAvailable = !canSaveCandidate
                && !AnyTrue(slotUsable)
                && !AnyTrue(slotOccupied);
            for (int i = 0; i < laneLabelTexts.Length; i += 1)
            {
                bool selected = i == selectedSlotIndex;
                bool usable = slotUsable != null && i < slotUsable.Length && slotUsable[i];
                bool occupied = slotOccupied != null && i < slotOccupied.Length && slotOccupied[i];
                string slotState = slotLabels != null
                    && i < slotLabels.Length
                    && !string.IsNullOrEmpty(slotLabels[i])
                    ? slotLabels[i]
                    : "슬롯 " + (i + 1);
                string displaySlotState = BuildCompactSaveSlotLaneState(slotState, noRefillSourceAvailable);
                bool lastUse = IsSaveSlotFinalUseLabel(slotState);
                bool recommended = slotState.Contains("추천", StringComparison.Ordinal);
                string actionHint = BuildSaveSlotLaneActionHint(
                    slotChoiceRequired,
                    showUsability,
                    canSaveCandidate,
                    usable,
                    occupied,
                    lastUse,
                    recommended,
                    noRefillSourceAvailable);

                string actionSuffix = displaySlotState.EndsWith("\n" + actionHint, StringComparison.Ordinal)
                    ? string.Empty : "\n" + actionHint;
                laneLabelTexts[i].text = selected
                    ? "선택\nS" + (i + 1) + "\n" + displaySlotState + actionSuffix
                    : "S" + (i + 1) + "\n" + displaySlotState + actionSuffix;
                laneLabelTexts[i].color = BuildSaveSlotLaneLabelColor(
                    slotChoiceRequired,
                    selected,
                    showUsability,
                    canSaveCandidate,
                    usable,
                    occupied,
                    lastUse,
                    recommended);
                UpdateSaveSlotUsePips(
                    i,
                    slotState,
                    saveSlotModeActive,
                    selected,
                    showUsability,
                    canSaveCandidate,
                    usable,
                    occupied,
                    lastUse,
                    recommended);

                if (laneImages != null && i < laneImages.Length && laneImages[i] != null)
                {
                    if (showUsability)
                    {
                        laneImages[i].color = selected
                            ? usable ? new Color32(154, 112, 48, 255) : new Color32(108, 54, 48, 255)
                            : slotChoiceRequired && usable ? new Color32(46, 76, 72, 235) : usable ? new Color32(32, 52, 55, 225) : new Color32(24, 29, 31, 205);
                    }
                    else
                    {
                        laneImages[i].color = selected
                            ? occupied ? new Color32(154, 112, 48, 255) : new Color32(74, 123, 118, 255)
                            : slotChoiceRequired && canSaveCandidate ? new Color32(52, 75, 68, 235) : occupied ? new Color32(32, 42, 49, 225) : new Color32(24, 50, 49, 215);
                    }
                }
            }
        }

        private void HideSaveSlotUsePips()
        {
            if (saveSlotUsePips == null)
            {
                return;
            }

            for (int laneIndex = 0; laneIndex < saveSlotUsePips.GetLength(0); laneIndex += 1)
            {
                for (int pipIndex = 0; pipIndex < saveSlotUsePips.GetLength(1); pipIndex += 1)
                {
                    Image pipFill = saveSlotUsePips[laneIndex, pipIndex];
                    if (pipFill == null)
                    {
                        continue;
                    }

                    SetGaugeFill(pipFill, 0f);
                    SetImageAlpha(pipFill, 0);
                    if (pipFill.transform.parent != null
                        && pipFill.transform.parent.TryGetComponent(out Image pipBack))
                    {
                        SetImageAlpha(pipBack, 0);
                        pipBack.rectTransform.localScale = Vector3.one;
                    }
                }
            }
        }

        private void UpdateSaveSlotUsePips(
            int laneIndex,
            string slotState,
            bool saveSlotModeActive,
            bool selected,
            bool showUsability,
            bool canSaveCandidate,
            bool usable,
            bool occupied,
            bool lastUse,
            bool recommended)
        {
            if (saveSlotUsePips == null
                || laneIndex < 0
                || laneIndex >= saveSlotUsePips.GetLength(0))
            {
                return;
            }

            int usesRemaining = ExtractSaveSlotUsesRemainingForVisual(slotState);
            bool visible = ShouldShowSaveSlotUsePips(saveSlotModeActive, showUsability, canSaveCandidate, usable, occupied, usesRemaining);
            bool finalUse = lastUse || usesRemaining == 1;
            float beatPulse = 0.5f + Mathf.Sin(beatPhase * Mathf.PI * 2f) * 0.5f;

            for (int pipIndex = 0; pipIndex < SaveSlotUsePipCount; pipIndex += 1)
            {
                Image pipFill = saveSlotUsePips[laneIndex, pipIndex];
                if (pipFill == null)
                {
                    continue;
                }

                Image pipBack = pipFill.transform.parent != null
                    ? pipFill.transform.parent.GetComponent<Image>()
                    : null;
                float fill = BuildSaveSlotUsePipFillAmount(usesRemaining, pipIndex);
                float alpha = BuildSaveSlotUsePipAlpha(visible, fill, selected, recommended, finalUse, beatPulse);
                float scale = BuildSaveSlotUsePipScale(visible, fill, selected, recommended, finalUse, beatPulse);
                Color32 emptyColor = finalUse
                    ? new Color32(92, 57, 36, 255)
                    : new Color32(51, 67, 64, 255);
                Color32 filledColor = finalUse
                    ? new Color32(255, 188, 116, 255)
                    : recommended
                        ? new Color32(255, 238, 181, 255)
                        : new Color32(132, 201, 181, 255);
                Color32 pipColor = Color32.Lerp(emptyColor, filledColor, Mathf.Clamp01(fill));

                SetGaugeFill(pipFill, visible ? fill : 0f);
                pipFill.color = WithAlpha(pipColor, Mathf.RoundToInt(alpha * 255f));

                if (pipBack != null)
                {
                    pipBack.color = WithAlpha(
                        finalUse ? new Color32(76, 43, 30, 255) : new Color32(32, 46, 44, 255),
                        visible ? Mathf.RoundToInt(54f + Mathf.Clamp01(fill) * 34f + (selected ? 20f : 0f)) : 0);
                    pipBack.rectTransform.localScale = Vector3.one * scale;
                }
            }
        }

        private static bool ShouldShowSaveSlotUsePips(
            bool saveSlotModeActive,
            bool showUsability,
            bool canSaveCandidate,
            bool usable,
            bool occupied,
            int usesRemaining)
        {
            return saveSlotModeActive
                && !canSaveCandidate
                && occupied
                && (showUsability ? usable : usesRemaining > 0)
                && usesRemaining > 0;
        }

        private static int ExtractSaveSlotUsesRemainingForVisual(string label)
        {
            if (string.IsNullOrWhiteSpace(label)
                || label == "빈 슬롯"
                || label == "사용 완료")
            {
                return 0;
            }

            if (IsSaveSlotFinalUseLabel(label))
            {
                return 1;
            }

            int useTextEnd = label.IndexOf("회 남음", StringComparison.Ordinal);
            if (useTextEnd > 0)
            {
                int scan = useTextEnd - 1;
                while (scan >= 0 && char.IsWhiteSpace(label[scan]))
                {
                    scan -= 1;
                }

                int digitEnd = scan;
                while (scan >= 0 && char.IsDigit(label[scan]))
                {
                    scan -= 1;
                }

                int digitStart = scan + 1;
                if (digitEnd >= digitStart
                    && int.TryParse(label.Substring(digitStart, digitEnd - digitStart + 1), out int parsedUses))
                {
                    return Mathf.Clamp(parsedUses, 0, SaveSlotUsePipCount);
                }
            }

            if (label.Contains("2/2", StringComparison.Ordinal))
            {
                return 2;
            }

            if (label.Contains("1/2", StringComparison.Ordinal))
            {
                return 1;
            }

            return 0;
        }

        private static float BuildSaveSlotUsePipFillAmount(int usesRemaining, int pipIndex)
        {
            if (pipIndex < 0 || pipIndex >= SaveSlotUsePipCount || usesRemaining <= 0)
            {
                return 0f;
            }

            return pipIndex < Mathf.Clamp(usesRemaining, 0, SaveSlotUsePipCount) ? 1f : 0f;
        }

        private static float BuildSaveSlotUsePipAlpha(
            bool visible,
            float fillAmount,
            bool selected,
            bool recommended,
            bool finalUse,
            float beatPulse)
        {
            if (!visible)
            {
                return 0f;
            }

            float baseAlpha = Mathf.Lerp(0.18f, 0.86f, Mathf.Clamp01(fillAmount));
            float selectedLift = selected ? 0.10f : 0f;
            float recommendedLift = recommended ? 0.06f : 0f;
            float finalUsePulse = finalUse && fillAmount > 0f ? Mathf.Clamp01(beatPulse) * 0.13f : 0f;
            return Mathf.Clamp01(baseAlpha + selectedLift + recommendedLift + finalUsePulse);
        }

        private static float BuildSaveSlotUsePipScale(
            bool visible,
            float fillAmount,
            bool selected,
            bool recommended,
            bool finalUse,
            float beatPulse)
        {
            if (!visible)
            {
                return 1f;
            }

            float selectedLift = selected ? 0.055f : 0f;
            float recommendedLift = recommended ? 0.035f : 0f;
            float finalUsePulse = finalUse && fillAmount > 0f ? Mathf.Clamp01(beatPulse) * 0.065f : 0f;
            return 1f + selectedLift + recommendedLift + finalUsePulse;
        }

        private static string BuildCompactSaveSlotLaneState(string label, bool noRefillSourceAvailable = false)
        {
            if (string.IsNullOrWhiteSpace(label))
            {
                return noRefillSourceAvailable ? "보충\n필요" : "빈 슬롯";
            }

            if (label == "빈 슬롯")
            {
                return noRefillSourceAvailable ? "보충\n필요" : label;
            }

            if (label == "사용 완료")
            {
                return "소진";
            }

            bool recommended = label.Contains("추천", StringComparison.Ordinal);
            string status = HasSaveSlotUseStatusLabel(label)
                ? BuildCompactSaveUseStatusFromSlotLabel(label, 8)
                : CompactUiText(ExtractFirstSlashPart(label), 7);

            string profile = ExtractSaveSlotProfile(label);
            string grade = ExtractSaveSlotGrade(label);
            string detail = string.Empty;
            if (!string.IsNullOrEmpty(profile))
            {
                detail = profile;
            }

            if (!string.IsNullOrEmpty(grade))
            {
                detail = string.IsNullOrEmpty(detail) ? grade : detail + " " + grade;
            }

            string text = string.IsNullOrEmpty(detail) ? status : status + "\n" + detail;
            return recommended ? text + "\n추천" : text;
        }

        private static string ExtractSaveSlotProfile(string label)
        {
            if (string.IsNullOrEmpty(label))
            {
                return string.Empty;
            }

            string[] parts = RemoveSaveUseStatusPrefix(label).Split('/');
            for (int i = 0; i < parts.Length; i += 1)
            {
                string part = parts[i].Trim();
                if (part.EndsWith("형", StringComparison.Ordinal))
                {
                    return CompactUiText(part, 5);
                }
            }

            return string.Empty;
        }

        private static string BuildSaveSlotLaneActionHint(
            bool slotChoiceRequired,
            bool showUsability,
            bool canSaveCandidate,
            bool usable,
            bool occupied,
            bool lastUse,
            bool recommended,
            bool noRefillSourceAvailable = false)
        {
            if (slotChoiceRequired)
            {
                if (showUsability)
                {
                    return usable ? lastUse ? "자동 비움" : "고르기" : occupied ? "소진" : noRefillSourceAvailable ? "보충 런" : "사용 불가";
                }

                return canSaveCandidate ? recommended ? "추천" : "고르기" : occupied ? "관리 가능" : noRefillSourceAvailable ? "보충 런" : "빈 슬롯";
            }

            if (showUsability)
            {
                return usable ? lastUse ? "시작 후 비움" : "시작 가능" : occupied ? "소진" : noRefillSourceAvailable ? "보충 런" : "사용 불가";
            }

            if (canSaveCandidate)
            {
                return occupied ? recommended ? "추천 교체" : "교체 대상" : recommended ? "추천 저장" : "바로 저장";
            }

            return occupied ? "관리 가능" : noRefillSourceAvailable ? "보충 런" : "빈 슬롯";
        }

        private static bool AnyTrue(bool[] values)
        {
            if (values == null)
            {
                return false;
            }

            for (int i = 0; i < values.Length; i += 1)
            {
                if (values[i])
                {
                    return true;
                }
            }

            return false;
        }

        private static Color32 BuildSaveSlotLaneLabelColor(
            bool slotChoiceRequired,
            bool selected,
            bool showUsability,
            bool canSaveCandidate,
            bool usable,
            bool occupied,
            bool lastUse,
            bool recommended)
        {
            if (selected)
            {
                return new Color32(255, 238, 181, 255);
            }

            if (slotChoiceRequired)
            {
                if (showUsability)
                {
                    if (usable && lastUse)
                    {
                        return new Color32(230, 205, 150, 245);
                    }

                    return usable
                        ? new Color32(205, 235, 221, 245)
                        : new Color32(145, 154, 152, 190);
                }

                if (canSaveCandidate && recommended)
                {
                    return new Color32(255, 238, 181, 245);
                }

                return canSaveCandidate
                    ? new Color32(215, 232, 212, 245)
                    : occupied ? new Color32(190, 204, 204, 220) : new Color32(145, 154, 152, 190);
            }

            if (showUsability)
            {
                if (usable && lastUse)
                {
                    return new Color32(230, 205, 150, 235);
                }

                return usable
                    ? new Color32(218, 226, 218, 235)
                    : new Color32(145, 154, 152, 190);
            }

            if (canSaveCandidate && recommended)
            {
                return new Color32(255, 238, 181, 240);
            }

            return occupied
                ? new Color32(218, 226, 218, 230)
                : new Color32(184, 214, 207, 220);
        }

