        private void UpdateInfinitePreparationLaneLabels(string detail)
        {
            if (laneLabelTexts == null || laneLabelTexts.Length < 3)
            {
                return;
            }

            string safeDetail = detail ?? string.Empty;
            bool giftStep = safeDetail.Contains("시작 정비 1/2", StringComparison.Ordinal);
            bool relicStep = safeDetail.Contains("시작 정비 2/2", StringComparison.Ordinal);
            bool completeStep = safeDetail.Contains("시작 정비 완료", StringComparison.Ordinal);
            if (!giftStep && !relicStep && !completeStep)
            {
                UpdateDefaultLaneLabels();
                return;
            }

            SetLaneLabelMode(27, true);
            if (giftStep)
            {
                laneLabelTexts[0].text = "좌\n생존 축\n보정 회복";
                laneLabelTexts[1].text = "중\n집중 축\n집중 가속";
                laneLabelTexts[2].text = "우\n연쇄 축\n콤보 가속";
            }
            else if (relicStep)
            {
                laneLabelTexts[0].text = "좌\n사막의 잔상\n보정 회복";
                laneLabelTexts[1].text = "중\n황금 박동\n정확 고점";
                laneLabelTexts[2].text = "우\n파라오 각인\n연쇄 증폭";
            }
            else
            {
                laneLabelTexts[0].text = "좌\n기프트\n다시 선택";
                laneLabelTexts[1].text = "중\n유물\n다시 선택";
                laneLabelTexts[2].text = "우\n현재 선택\n유지";
            }

            Color32[] colors =
            {
                new Color32(172, 230, 204, 255),
                new Color32(178, 232, 238, 255),
                new Color32(255, 197, 156, 255),
            };
            for (int i = 0; i < laneLabelTexts.Length; i += 1)
            {
                laneLabelTexts[i].color = colors[i];
                SetLaneInputInteractable(i, ShouldEnableInfinitePreparationLane(completeStep, i));
            }
        }

        private static bool ShouldEnableInfinitePreparationLane(bool completeStep, int laneIndex)
        {
            if (laneIndex < 0 || laneIndex >= 3)
            {
                return false;
            }

            return !completeStep || laneIndex <= 2;
        }

        private void SetLaneInputInteractable(int laneIndex, bool interactable)
        {
            if (!interactable) ClearLanePointerHold(laneIndex);

            if (!interactable && laneKeyboardHoldActive != null && laneIndex >= 0 && laneIndex < laneKeyboardHoldActive.Length)
            {
                laneKeyboardHoldActive[laneIndex] = false;
            }

            if (laneButtons != null && laneIndex >= 0 && laneIndex < laneButtons.Length && laneButtons[laneIndex] != null)
            {
                laneButtons[laneIndex].interactable = interactable;
            }

            if (laneHitButtons != null && laneIndex >= 0 && laneIndex < laneHitButtons.Length && laneHitButtons[laneIndex] != null)
            {
                laneHitButtons[laneIndex].interactable = interactable;
            }
        }

        private void SetLaneLabelMode(int fontSize, bool bestFit)
        {
            for (int i = 0; i < laneLabelTexts.Length; i += 1)
            {
                Text label = laneLabelTexts[i];
                if (label == null)
                {
                    continue;
                }

                label.fontSize = fontSize;
                label.resizeTextForBestFit = bestFit;
                label.resizeTextMinSize = 20;
                label.resizeTextMaxSize = fontSize;
                label.color = new Color32(218, 226, 218, 230);
                label.rectTransform.localScale = Vector3.one;
            }
        }

        private static void SetButtonFontSize(Button button, int fontSize)
        {
            Text text = button.GetComponentInChildren<Text>();
            if (text != null)
            {
                text.fontSize = fontSize;
                text.resizeTextForBestFit = true;
                text.resizeTextMinSize = 18;
                text.resizeTextMaxSize = fontSize;
            }
        }

        private static void SetButtonLabel(Button button, string label)
        {
            Text text = button.GetComponentInChildren<Text>();
            if (text != null)
            {
                string normalizedLabel = NormalizeButtonLabel(label);
                text.text = normalizedLabel;
                int baseMaxSize = Mathf.Max(text.fontSize, text.resizeTextMaxSize);
                int maxSize = BuildButtonLabelMaxFontSize(normalizedLabel, baseMaxSize);
                text.resizeTextForBestFit = true;
                text.resizeTextMinSize = BuildButtonLabelMinFontSize(maxSize);
                text.resizeTextMaxSize = maxSize;
            }
        }

        private static string NormalizeButtonLabel(string label)
        {
            if (string.IsNullOrWhiteSpace(label))
            {
                return string.Empty;
            }

            return label.Replace("\r\n", "\n").Replace('\r', '\n').Trim();
        }

        private static int BuildButtonLabelMaxFontSize(string label, int baseMaxSize)
        {
            int maxSize = Mathf.Clamp(baseMaxSize, 18, 36);
            int length = string.IsNullOrEmpty(label) ? 0 : label.Replace("\n", string.Empty).Length;
            int lineCount = string.IsNullOrEmpty(label) ? 1 : label.Split('\n').Length;
            if (length >= 20)
            {
                maxSize -= 7;
            }
            else if (lineCount >= 3 || length >= 14)
            {
                maxSize -= 5;
            }
            else if (lineCount >= 2 || length >= 10)
            {
                maxSize -= 3;
            }

            return Mathf.Clamp(maxSize, 18, baseMaxSize);
        }

        private static int BuildButtonLabelMinFontSize(int maxFontSize)
        {
            return Mathf.Clamp(maxFontSize - 8, 16, 22);
        }
    }
}
